INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('1329c7c0-6ff9-454c-b95c-82a01b3f8b19', '0015c9ea-2aa2-4fcb-9d7e-e3530f233e06', 'en', 'Double Kettlebell Clean', 'Bring two kettlebells from the floor to the rack position at the chest in one explosive hip-driven movement.'),
('dcb7693a-e0ce-4f89-8e06-cc56b64c1807', '0015c9ea-2aa2-4fcb-9d7e-e3530f233e06', 'es', 'Clean con Kettlebell doble', 'Lleva dos Kettlebells desde el suelo hasta la posición de rack en el pecho en un movimiento explosivo de cadera.'),
('bf49ce0d-6990-42f4-83e6-d733aef3bf6e', '0036af74-b2f1-4aa4-8b85-cc3a2143686d', 'en', 'Wall Facing Handstand', 'Walk feet up the wall while bringing hands closer to the wall until in a vertical inverted position.'),
('d0069659-7dfb-4d31-9e8d-d3d19ed2b929', '0036af74-b2f1-4aa4-8b85-cc3a2143686d', 'es', 'Parada de manos cara a la pared', 'Camina con los pies por la pared hacia arriba mientras acercas las manos a la pared hasta quedar en posición vertical invertida.'),
('db837be9-1d02-4eff-9cd0-57104eb0e8cf', '0058dd3e-f93e-49b1-9155-17c0baf06ae3', 'en', 'Single Arm Kettlebell Bottoms Up Dead Clean to Overhead Press', 'Clean the upside-down kettlebell from the floor to shoulder and press it overhead, challenging the grip in each phase of the movement.'),
('989340d7-2a45-45cc-aadc-0a63624a8ff9', '0058dd3e-f93e-49b1-9155-17c0baf06ae3', 'es', 'Dead Clean a Press Overhead con Kettlebell a una mano Bottoms Up', 'Lleva la pesa invertida desde el suelo hasta el hombro y presionala sobre la cabeza, desafiando el agarre en cada fase del movimiento.'),
('644bf492-1d3e-4d34-af35-8047951568c6', '007dfc37-a855-491b-a295-166525cb73c4', 'es', 'Press militar sentado en máquina Smith', 'Sentado, empuja la barra guiada de la Smith sobre la cabeza. Objetivo: deltoides con trayectoria controlada. Cue: espalda plana contra el banco. Error común: arquear la lumbar al final del recorrido.'),
('43d6a035-843e-429c-9d02-a0cd6ff900e0', '008f9175-b9dc-4ce5-a59c-fc773720ef77', 'es', 'Peso muerto sumo mancuernas', 'Adopta una postura amplia con los pies apuntando hacia afuera. Sujeta una mancuerna con ambas manos entre las piernas. Desciende manteniendo el pecho erguido y las rodillas alineadas con los pies. Esta variación enfatiza más glúteos y aductores.'),
('a592cb08-8b35-407d-9c01-60dadb9ea6f8', '00b278c0-12c7-436d-bfd9-fe6d8888b27c', 'en', 'Barbell Bulgarian Split Squat', 'Bulgarian split squat with a barbell on the back. Significantly increases intensity. Requires great balance and stabilization. Start with light weight. Excellent for correcting muscle imbalances.'),
('b9bb11d4-05f7-4b9d-bc78-9d30543686c5', '00b278c0-12c7-436d-bfd9-fe6d8888b27c', 'es', 'Sentadilla búlgara con barra', 'Sentadilla búlgara (split squat) con barra en la espalda. Aumenta significativamente la intensidad. Requiere gran equilibrio y estabilización. Comienza con peso ligero. Excelente para corregir desequilibrios musculares.'),
('a51d207b-ba0a-48a8-9b50-8bbc83ca638a', '00bb8e11-aa0c-418c-80cc-9de008dc5814', 'en', 'Superband Single Leg Standing Bent Knee Hip External Rotation', 'Standing on one leg with a bent knee and an anchored band, rotate the hip outward against the bands resistance.'),
('1ac292c3-5348-41d9-b392-503376362222', '00bb8e11-aa0c-418c-80cc-9de008dc5814', 'es', 'Rotación externa de cadera a una pierna con banda', 'De pie sobre una pierna con la rodilla flexionada y una banda anclada, rota la cadera hacia afuera resistiendo la banda.'),
('90e81d37-9ab9-4f66-a63f-62329c25d171', '00e93873-2ea5-463b-96da-4a7c5fd8c315', 'en', 'Burpee slam', 'Combines a full burpee with a slam ball. Perform the slam, place hands on the ball, jump to plank, optional push-up, return to feet and repeat. Extremely demanding metabolic exercise.'),
('9ffa2bb8-9e90-4c7f-83e8-140c6a42e948', '00e93873-2ea5-463b-96da-4a7c5fd8c315', 'es', 'Burpee slam', 'Combina un burpee completo con un slam ball. Realiza el slam, coloca las manos en el balón, salta a plancha, flexión opcional, vuelve a los pies y repite. Ejercicio metabólico extremadamente demandante.'),
('735db109-4680-4dc4-a208-6d16398c216b', '00fd4b17-81e5-409c-a9c5-83b628d91ed1', 'en', 'Single Arm Kettlebell Swing', 'Swing the kettlebell between your legs and drive it explosively with your hips to shoulder height using one arm.'),
('717d9e2a-4294-4a6f-af52-f99b9d310689', '00fd4b17-81e5-409c-a9c5-83b628d91ed1', 'es', 'Swing con Kettlebell a una mano', 'Balancéa la Kettlebell entre las piernas y empújala explosivamente con la cadera hasta la altura de los hombros usando un solo brazo.'),
('1af7b8f5-32d0-4a39-89f5-a8e809927b09', '014ae459-ef96-4e08-8c69-948f62b177ec', 'en', 'Battle Ropes Side Shuffle', 'Fast lateral shuffle while creating intense waves. Works agility, coordination, and endurance. Maintain a low athletic position. Change direction every 5-10 steps. Waves should not stop.'),
('b9f9dda4-3641-4a10-8c6f-13e1d34f3e6d', '014ae459-ef96-4e08-8c69-948f62b177ec', 'es', 'Desplazamiento lateral battle ropes', 'Desplazamiento lateral rápido mientras creas ondas intensas. Trabaja agilidad, coordinación y resistencia. Mantén posición atlética baja. Cambia dirección cada 5-10 pasos. Las ondas no deben interrumpirse.'),
('f5b5a73d-21f1-4e2e-8777-d28506f1a63d', '015066cb-b761-4cc4-bdbf-5c5ff7efb7e4', 'en', 'Single Arm Kettlebell Turkish Get Up', 'Rise from the floor to a standing position while keeping a kettlebell locked out overhead at all times.'),
('1e503c8f-b0a1-4a8b-a77b-75ac35bbcb9d', '015066cb-b761-4cc4-bdbf-5c5ff7efb7e4', 'es', 'Levantamiento turco con Kettlebell a una mano', 'Levántate desde el suelo hasta quedar de pie manteniendo una Kettlebell bloqueada sobre la cabeza en todo momento.'),
('0b153205-d225-4824-a7e0-b39b3f004a06', '0171e99a-1485-482b-9459-da45a163fff0', 'en', 'Bottom-Up Kettlebell Press', 'Press with the kettlebell upside down (bottom-up). Requires tremendous control and grip strength. Improves shoulder stabilization. Start with light weight. The kettlebell should not wobble during the movement.'),
('59f3164d-26f6-4280-934f-94e4410940b2', '0171e99a-1485-482b-9459-da45a163fff0', 'es', 'Press kettlebell invertida', 'Press con la kettlebell boca abajo (bottom-up). Requiere tremendo control y fuerza de agarre. Mejora estabilización del hombro. Comienza con peso ligero. La kettlebell no debe tambalearse durante el movimiento.'),
('ebf166b8-c104-4bde-a1d5-43b106e8d6fc', '01740541-4d83-4fb5-b952-f09f4a619c61', 'en', 'Wall Mountain Climber', 'Place yourself in a plank position with your feet supported on a wall at hip height. Bring knees alternately toward the chest maintaining core stability and pressure against the wall.'),
('499765bf-e4d5-4906-add2-f8880dd63e08', '01740541-4d83-4fb5-b952-f09f4a619c61', 'es', 'Mountain Climber con pies en pared', 'Colócate en posición de plancha con los pies apoyados en una pared a la altura de las caderas. Lleva las rodillas alternativamente hacia el pecho manteniendo la estabilidad del core y la presión contra la pared.'),
('185d575c-cd22-4faf-a2ed-2b565925efd1', '01779fa7-f4ad-4f7d-bc30-aea391427a00', 'en', 'Barbell Drag Curl', 'Perform a bicep curl brushing the bar against the torso while bringing elbows back. Objective: bicep long head. Cue: keep the bar in contact with the body always. Error: shrugging shoulders toward ears.'),
('8e5dcfba-a9c4-48ed-9166-928f0ecd1710', '01779fa7-f4ad-4f7d-bc30-aea391427a00', 'es', 'Drag Curl con barra', 'Realiza un curl de bíceps rozando la barra contra el torso mientras llevas los codos hacia atrás. Objetivo: cabeza larga del bíceps. Cue: mantén la barra siempre en contacto con el cuerpo. Error: encoger los hombros hacia las orejas.'),
('d9a15e82-b631-4f26-89d9-ea91998301cf', '017e7077-9540-4061-a3e5-17145b20f008', 'en', 'Single Arm Landmine Shrug', 'Standing next to the end of the landmine bar, hold the bar with one hand and shrug your shoulder toward your ear to work the trapezius unilaterally.'),
('0edadebd-787a-4d8a-8c33-67aeeb4a4b28', '017e7077-9540-4061-a3e5-17145b20f008', 'es', 'Encogimiento de hombros a una mano en Landmine', 'De pie junto al extremo de la barra Landmine, sujeta la barra con una mano y eleva el hombro hacia la oreja para trabajar el trapecio de forma unilateral.'),
('6fdcc0ca-43f6-416d-85a1-3a9359e9d84f', '019869be-7042-46d1-912a-736da36b6847', 'en', 'Single Arm Parallette Plank', 'Maintain the plank position on the parallettes but supported on only one hand, which requires extreme shoulder and core stabilization.'),
('53e8d7e3-7ec5-4d35-b978-a69ba6adc628', '019869be-7042-46d1-912a-736da36b6847', 'es', 'Plank a una mano en paralelas', 'Mantén la posición de plancha sobre las paralelas pero apoyado solo en una mano, lo que exige una estabilización extrema del hombro y core.'),
('3d928d64-d2e6-4d23-ac62-aff4e3daf762', '01b1aabe-7fc3-4a77-a9e5-ced29c147903', 'es', 'Puente de glúteo con pies en TRX', 'Acuéstate boca arriba con los talones en los estribos del TRX. Eleva las caderas del suelo presionando hacia abajo y manteniendo la estabilidad.'),
('998a9c32-0af0-4592-b9ce-a6c1728d8418', '01bb9dae-2be8-487d-b767-86de372704d9', 'en', 'Jumping Lunges', 'From a lunge position, explosively jump exchanging leg positions in the air. Land softly in a lunge position with the opposite leg forward. Continue alternating with explosive jumps. Develops power, coordination, and muscular endurance in the legs.'),
('4991038c-fada-4eba-9b93-0179c5f8c653', '01bb9dae-2be8-487d-b767-86de372704d9', 'es', 'Zancadas saltando', 'Desde la posición de zancada, salta explosivamente intercambiando la posición de las piernas en el aire. Aterriza suavemente en posición de zancada con la pierna opuesta adelante. Continúa alternando con saltos explosivos. Desarrolla potencia, coordinación y resistencia muscular en las piernas.'),
('66398ba5-f6a0-4361-8116-776a9c206161', '01f09b4f-1a6f-4470-891f-06e9b0d35f74', 'en', 'TRX Bicep Curl', 'Body leaned back, arms extended. Flex elbows bringing hands to temples. Keep body straight. Do not swing hips.'),
('4dd455b4-1edb-4eb7-923f-11e07a8ca812', '01f09b4f-1a6f-4470-891f-06e9b0d35f74', 'es', 'TRX Curl de bíceps', 'Cuerpo inclinado atrás, brazos extendidos. Flexiona codos llevando manos a las sienes. Mantén cuerpo recto. No balancees la cadera.'),
('1bf13226-9185-4e7b-98e8-f5fb893e8026', '026b9beb-932f-46d5-b2fd-ff58064d5c4f', 'en', 'Bodyweight Lateral Lunge', 'Take a wide side step lowering the hip and returning to the center. Objective: adductors and glute. Cue: chest high always. Common error: letting the heel of the moving foot lift.'),
('bffba037-29e6-4a9d-b174-9de9b9bc9362', '026b9beb-932f-46d5-b2fd-ff58064d5c4f', 'es', 'Zancada lateral (peso corporal)', 'Paso lateral amplio bajando la cadera y volviendo al centro. Objetivo: aductores y glúteo. Cue: pecho alto siempre. Error común: dejar que el talón del pie móvil se levante.'),
('ea312c60-2f1e-4fc6-8c7e-7bdf59e84f76', '02700dc1-8c21-4f60-8a8b-ba8ba3bf191b', 'en', 'Lateral bear crawl low knees', 'Crawl sideways. Cue: knees almost touch the floor. Error: raising hips.'),
('02084627-37fe-4c35-aed8-5192367f9b94', '02700dc1-8c21-4f60-8a8b-ba8ba3bf191b', 'es', 'Caminata oso lateral rodillas bajas', 'Desplázate a gatas de lado. Cue: rodillas casi tocan suelo. Error: subir cadera.'),
('afb03cb7-e2eb-4de2-8b04-d8d5a7c6c67c', '02dab88f-f109-451f-975a-481b5b64dad0', 'en', 'Slow Knee to Elbow Mountain Climbers', 'Bring knee to elbow holding 2s. Cue: do not move hips. Error: lifting glute.'),
('3a439c0d-8133-4a26-bac5-25fc91028279', '02dab88f-f109-451f-975a-481b5b64dad0', 'es', 'Escaladores lentos rodilla a codo', 'Lleva rodilla a codo manteniendo 2s. Cue: no muevas cadera. Error: elevar glúteo.'),
('ebc6c58c-dfaa-43c8-b065-4dae0ad3412b', '02fdac7d-339c-4006-8acd-d2e834f2d2e0', 'es', 'Plank sobre Fitball', 'Realiza una plancha apoyando los antebrazos sobre el Fitball, manteniendo el cuerpo recto y resistiendo la inestabilidad del balon.'),
('f585026f-7a32-4872-865e-fd1a778e600d', '0308962c-606d-4b3c-b287-930c97924520', 'en', 'Rolling Squat Burpee', 'Perform a burpee, but when going down, roll onto your back, use momentum to return to a squat, and jump.'),
('25beeddf-3cf5-49c7-bf73-6cf4cf4560b3', '0308962c-606d-4b3c-b287-930c97924520', 'es', 'Rolling Squat Burpee', 'Haz un burpee, pero al bajar, rueda sobre tu espalda hacia atrás, toma impulso para volver a la sentadilla y salta.'),
('f3dba23d-b45c-47c5-827f-782709baf279', '030be619-3fbd-4fc3-8936-3b285596555f', 'es', 'TRX Remo alto hombro', 'Tira codos fuera altura hombro TRX. Objetivo: espalda alta. Cue: retrae escápulas. Error: subir hombros.'),
('f429bc49-03ec-43fc-8d1f-2df2274f1aba', '030e0ce1-5dc8-456a-9df0-605b7c21eac1', 'en', 'Kettlebell Upright Row', 'Raise the kettlebell toward the chin keeping the elbows above the wrists. Objective: deltoids and upper back. Cues: straight back and looking forward. Common error: performing sudden jerks with the lower back.'),
('3cc2045c-689f-4bfd-81e5-0ca8deb00659', '030e0ce1-5dc8-456a-9df0-605b7c21eac1', 'es', 'Remo al cuello con kettlebell', 'Eleva la pesa rusa hacia el mentón manteniendo los codos por encima de las muñecas. Objetivo: deltoides y espalda alta. Cues: espalda recta y mirada al frente. Error común: realizar tirones bruscos con la espalda lumbar.'),
('9d1ed29b-03b9-41ce-9214-ad13d0dd88e7', '031ef73b-a0fd-4b61-b20b-43aef688be78', 'en', 'Standing Hip Abduction with Miniband', 'Standing with the band on the ankles. Lift one leg to the side keeping the body straight, working the gluteus medius.'),
('11c2ffb2-690f-4ea7-b048-2c3e26f6ee08', '031ef73b-a0fd-4b61-b20b-43aef688be78', 'es', 'Abducción de cadera de pie con Miniband', 'De pie con la banda en los tobillos. Levanta una pierna hacia el lado manteniendo el cuerpo recto, trabajando el glúteo medio.'),
('fb88eaf1-5db8-4977-a204-e43c4cdd21b6', '03289c31-1fe2-4431-8f1c-26c19c1ccc49', 'en', 'Single Arm Kettlebell Overhead Contralateral Knee Over Toe Split Squat', 'With one foot elevated, hold a kettlebell overhead on the side opposite to the front leg and perform the split squat.'),
('9dd74d61-66b6-47a7-81ef-add4050deb51', '03289c31-1fe2-4431-8f1c-26c19c1ccc49', 'es', 'Sentadilla Búlgara Overhead contralateral con Kettlebell', 'Con un pie elevado, sostén una Kettlebell sobre la cabeza en el lado opuesto a la pierna delantera y realiza la sentadilla split.'),
('f431ea51-3079-430d-9dec-f0e3efb3f9c9', '032e98d5-de9a-4758-be81-b9e288770fe2', 'en', 'Double Kettlebell Bottoms Up Front Rack Alternating Cossack Squat', 'Perform deep lateral squats while holding two upside-down kettlebells in a rack position, the ultimate motor stability challenge.'),
('e3528e54-3c75-4d7d-8bd5-a476c670e88c', '032e98d5-de9a-4758-be81-b9e288770fe2', 'es', 'Sentadilla Cosaca alterna Front Rack con Kettlebell doble Bottoms Up', 'Realiza sentadillas laterales profundas sosteniendo dos Kettlebells invertidas en posición rack, el reto definitivo de estabilidad motor.'),
('0ef4dd31-0305-462a-a36d-8bcd4916fe9d', '033fe3c6-aec6-4702-b70a-6269e8a58ab6', 'en', 'Medicine Ball Turkish Get-Up', 'Turkish get up holding a medicine ball. The spherical shape adds instability compared to a weight. Requires greater control and stabilizer activation. Progress from the unweighted version.'),
('91a6c17b-f48f-43a5-9895-33d34a34cbb5', '033fe3c6-aec6-4702-b70a-6269e8a58ab6', 'es', 'Levantamiento turco balón medicinal', 'Turkish get up sosteniendo balón medicinal. La forma esférica añade inestabilidad comparado con pesa. Requiere mayor control y activación de estabilizadores. Progresa desde versión sin peso.'),
('eee31efe-4876-40c1-9490-3363463c15e0', '03499f4c-ba25-49ca-b9ef-7638a2ae6b8b', 'en', 'Butt kicks', 'Run in place bringing heels toward glutes alternately, attempting to touch them with each kick. Keep the torso upright and thighs relatively still. Movement should come primarily from knee flexion. Excellent for warming up hamstrings and improving flexibility.'),
('1a30e99e-a5e3-401f-9dba-17f181340c76', '03499f4c-ba25-49ca-b9ef-7638a2ae6b8b', 'es', 'Butt kicks', 'Corre en el sitio llevando los talones hacia los glúteos alternadamente, intentando tocarlos con cada patada. Mantén el torso erguido y los muslos relativamente quietos. El movimiento debe venir principalmente de la flexión de rodillas. Excelente para calentar isquiotibiales y mejorar la flexibilidad.'),
('64597e0e-79fe-43ce-86c2-84ed18ceeb5b', '0373ee7d-4160-48f0-9969-3ec237264911', 'es', 'Plancha lateral estática', 'Apoyado en un antebrazo de lado, mantén cadera elevada. Cue: cuerpo alineado como una flecha. Error: dejar caer la cadera hacia el suelo.'),
('d2545c4f-6dca-42cb-adb1-99cc19e8a378', '037ea5b5-9cf2-4290-a4e8-b6666b014c61', 'es', 'Preacher curl barra', 'Usando un banco predicador, apoya los brazos en el soporte inclinado. Realiza el curl desde la extensión casi completa hasta la flexión máxima. Esta posición elimina el impulso y aísla efectivamente el bíceps. Ten cuidado de no hiperextender los codos.'),
('86165c79-6674-43f2-9c47-a93ed91318a9', '0389ba82-138e-4a2c-a107-1b2474c9cece', 'en', 'TRX Side Plank', 'Side plank with feet in the TRX straps. Intensely works obliques and lateral stabilizers. You can raise the free arm to increase difficulty. Keep hips elevated and aligned.'),
('58333044-f7e7-4bac-8a2d-35d5cb290a9d', '0389ba82-138e-4a2c-a107-1b2474c9cece', 'es', 'Side plank TRX', 'Plancha lateral con pies en las correas del TRX. Trabaja intensamente los oblicuos y estabilizadores laterales. Puedes elevar el brazo libre para aumentar la dificultad. Mantén las caderas elevadas y alineadas.'),
('7df23f16-6ca9-41b2-ad66-45606c704eee', '03bf9e78-dcbf-48ca-b8ae-3be0b0f27907', 'en', 'Alternating Swing', 'Switch hands on each swing at the highest point. Requires precise timing and coordination. The switch should be smooth without breaking the rhythm. Excellent for sports requiring hand-eye coordination.'),
('ce5989bf-da7b-4263-9b2c-4c8085316c46', '03bf9e78-dcbf-48ca-b8ae-3be0b0f27907', 'es', 'Swing alternado', 'Cambia de mano en cada swing en el punto más alto. Requiere timing y coordinación precisos. El cambio debe ser suave sin interrumpir el ritmo. Excelente para deportes que requieren coordinación mano-ojo.'),
('10e5cc5e-e6ce-473d-a5a7-4ab5dbcf846f', '03c4be64-5713-4680-bceb-c3c9328ab080', 'en', 'Kettlebell Feet Elevated Russian Twist', 'Seated with feet in the air, rotate your torso from side to side moving the kettlebell across the bodys midline.'),
('e13e866a-5b6e-4add-8f70-1692f38e009f', '03c4be64-5713-4680-bceb-c3c9328ab080', 'es', 'Russian Twist con Kettlebell y pies elevados', 'Sentado con los pies en el aire, rota el torso de lado a lado desplazando la pesa rusa a traves de la linea media del cuerpo.'),
('0fff941e-fb66-4123-a5d6-2cfa29c06376', '03e59c2f-9af8-4213-9ca9-53ec3ccd3ef3', 'en', 'French Press Triceps Extension', 'Triceps extension (French press) to emphasize the long head, keeping elbows stable and controlled descent.'),
('d840a690-f7d9-4707-a636-9385f3c3bf70', '03e59c2f-9af8-4213-9ca9-53ec3ccd3ef3', 'es', 'Tríceps press francés', 'Codos apuntan al techo y no se abren. Baja detrás de la cabeza con control y extiende sin bloquear agresivo.'),
('3aa92a3b-ce7c-4f50-91b2-41c94df7ae5b', '03f52fed-5dc6-45c4-a38b-7c571f345495', 'en', 'Double Dumbbell Renegade Row to Push Up', 'Perform a push-up on two dumbbells and immediately after row one weight to your hip, alternating arms each rep.'),
('422f7421-3994-451d-8e1c-72a4668c3587', '03f52fed-5dc6-45c4-a38b-7c571f345495', 'es', 'Remo renegado doble con mancuernas para hacer flexiones', 'Realiza una flexion sobre dos mancuernas e inmediatamente después rema una pesa hacia tu cadera, alternando el brazo en cada repeticion.'),
('35f21707-1d6b-45af-a66e-378259d8f0cc', '041d965f-9785-4345-933f-dcf9bed13fa0', 'en', 'Cyclist Squat with Kettlebell (Horn Grip)', 'With heels elevated, hold the kettlebell by the horns in front of the chest and lower into a deep squat.'),
('87d10ac0-6bfd-4aab-b018-461ee3761c90', '041d965f-9785-4345-933f-dcf9bed13fa0', 'es', 'Sentadilla Ciclista con Kettlebell (Horn)', 'Con los talones en alto, sujeta la pesa rusa por los cuernos frente al pecho y baja en sentadilla profunda.'),
('cbf91d9a-218e-4bdd-8a06-9027bfac53bd', '0425357d-bb8e-4262-91d3-7364b762c09c', 'en', 'Bent Over Barbell Reverse Fly', 'Leaning forward with a very wide grip on the bar, lift the bar performing a rear abduction. This unusual movement intensely works the rear deltoid and upper back muscles. Maintain a slight bend in the elbows.'),
('23d4a5dd-aec2-48d7-a977-98553a351308', '0425357d-bb8e-4262-91d3-7364b762c09c', 'es', 'Bent over reverse fly barra', 'Inclinado hacia adelante con agarre muy amplio en la barra, eleva la barra realizando una abducción posterior. Este movimiento poco común trabaja intensamente el deltoides posterior y los músculos de la espalda alta. Mantén una ligera flexión en los codos.'),
('be9a9992-e1fa-4a33-abea-0971d9c1bcce', '042cb66e-e1ff-47b1-9813-c0caa9b49934', 'en', 'Supinated Pull-ups', 'Grab the bar with palms facing you, shoulder-width apart. This position allows for greater bicep involvement. Lift the body until the chin clears the bar and descend in a controlled manner. Generally easier than prone pull-ups due to higher bicep engagement.'),
('3503a1a1-a7c1-40c0-ae39-5d0b8a695f8a', '042cb66e-e1ff-47b1-9813-c0caa9b49934', 'es', 'Dominadas supinas', 'Agarra la barra con las palmas mirando hacia ti, separadas al ancho de los hombros. Esta posición permite mayor participación del bíceps en el movimiento. Eleva el cuerpo hasta que la barbilla supere la barra y desciende de forma controlada. Es generalmente más fácil que las dominadas pronadas debido a la mayor implicación del bíceps.'),
('5bfc9b0a-8338-45d7-9523-c7541c3f04a4', '043e581a-3577-43cd-87d0-79fd667bc61e', 'en', 'Macebell Reverse Grip Offset Bent Over Row', 'Similar to the offset row but with palms facing up, increasing the work of the biceps and forearms.'),
('8d9d1c5c-baf2-4c69-8062-0ba852aedbce', '043e581a-3577-43cd-87d0-79fd667bc61e', 'es', 'Remo inclinado agarre inverso con maza (Offset)', 'Similar al remo offset pero con las palmas hacia arriba, incrementando el trabajo de los biceps y antebrazos.'),
('16ffc016-0d25-45ee-bcd5-39b08990061f', '04435260-58ab-44c3-996f-b1f1982f7a4a', 'en', 'Kneeling Ball Toss', 'Kneeling, throw the ball forward with an explosive chest push. Isolates the torso. Cue: do not sit on your heels. Common error: using excessive torso swinging.'),
('4733c83d-9984-46a6-bd3a-7a893ed67c16', '04435260-58ab-44c3-996f-b1f1982f7a4a', 'es', 'Lanzamiento de balón de rodillas', 'Arrodillado, lanza el balón hacia adelante con un empuje de pecho explosivo. Aísla el torso. Cue: no te sientes sobre los talones. Error común: usar el balanceo del tronco excesivamente.'),
('1436cec9-c063-4a39-8871-3f310d36e5f8', '0455b33f-7881-4b10-9e27-03d74b9f0d93', 'en', 'Reactive Skipping', 'Perform reactive skipping with quick and elastic ground contacts. Keep the torso upright, cadence high, and good arm-leg coordination.'),
('0412f247-4b97-4b7f-8777-46302f9acbf8', '0455b33f-7881-4b10-9e27-03d74b9f0d93', 'es', 'Skipping reactivo', 'Realiza skipping reactivo buscando contactos rápidos y elásticos con el suelo. Mantén el tronco erguido, la cadencia alta y una buena coordinación de brazos y piernas.'),
('12f0924e-b8e3-4f0a-b337-6fd94101771b', '047bb16c-c267-4e21-9d37-88a8bc53ceb2', 'en', 'Double Kettlebell Suitcase Cyclist Squat', 'With heels elevated, perform a deep squat while holding a kettlebell in each hand at the sides of the body.'),
('9fc9b869-5650-4ea6-b8f0-0148cb39ab7a', '047bb16c-c267-4e21-9d37-88a8bc53ceb2', 'es', 'Sentadilla Ciclista con Kettlebell doble (Maleta)', 'Con talones elevados, realiza una sentadilla profunda sosteniendo una pesa rusa en cada mano a los costados del cuerpo.'),
('cb7451d0-8f2e-4c52-9599-7690d2b02fb3', '0481a7a9-12ef-4fc4-bc05-a7b135cbaff7', 'en', 'Dragon Flag', 'Lying down holding onto something behind the head, lift the entire body straight except for the shoulders. Popularized by Bruce Lee. Descend in a controlled manner without the body touching the floor. One of the best core exercises.'),
('d32bd24c-2eda-43f0-93a1-7d0a2bd6ee3d', '0481a7a9-12ef-4fc4-bc05-a7b135cbaff7', 'es', 'Bandera dragón', 'Tumbado sujetando algo detrás de la cabeza, eleva todo el cuerpo recto excepto hombros. Popularizado por Bruce Lee. Desciende controladamente sin que el cuerpo toque el suelo. Uno de los mejores ejercicios para core.'),
('f9381846-f725-467f-97a2-2e4fcea986b2', '04a46c6d-cb64-44ed-a3b1-bed221f1bc2d', 'en', 'Single Arm Kettlebell Bottoms Up Half Kneeling Windmill', 'In a half-kneeling position with an upside-down kettlebell locked overhead, hinge your torso to touch the floor, demanding maximum scapular stability.'),
('9e204b4b-2b7b-403f-862a-bc3d5bf7604c', '04a46c6d-cb64-44ed-a3b1-bed221f1bc2d', 'es', 'Windmill medio arrodillado con Kettlebell Bottoms Up', 'En posicion de caballero con una Kettlebell invertida bloqueada arriba, inclina el torso hasta tocar el suelo, exigiendo maxima estabilidad escapular.'),
('164925c7-5588-4089-a7fd-4aebeb41a89c', '04eda32b-8e01-4e36-9a90-1329cdb56ba3', 'en', 'Behind-the-Neck Barbell Bulgarian Split Squat Knee-over-Toe', 'Hold a bar on the trapezius and perform a split squat with the back foot elevated, allowing the front knee to advance over the toes.'),
('24b8ceec-41e6-4501-80a7-4608e71aa535', '04eda32b-8e01-4e36-9a90-1329cdb56ba3', 'es', 'Sentadilla Búlgara con barra tras nuca rodilla sobre punta del pie', 'Sujeta una barra sobre los trapecios y realiza una sentadilla split con el pie trasero elevado, permitiendo que la rodilla delantera avance sobre los dedos del pie.'),
('47451b08-8eb9-4441-9dc5-5644bcc38620', '04fcec50-1969-4c08-919e-e93a17d3f5ad', 'en', 'Unilateral Fast Lateral Line Jumps', 'Jump side to side over a line with a single foot as fast as possible. Lateral stability. Knee aligned. Do not land on the heel.'),
('a5d37e41-4ff5-47a9-a072-43dfa0337b03', '04fcec50-1969-4c08-919e-e93a17d3f5ad', 'es', 'Saltos laterales sobre línea unilateral', 'Salta de lado a lado sobre una línea con un solo pie lo más rápido posible. Estabilidad lateral. Rodilla alineada. No apoyes el talón.'),
('cca2ac6c-0385-4295-bc9b-409144e268c7', '0500ef24-e637-4893-82d4-f82a31076f3d', 'es', 'Pulsos bandera humana', 'Desde la posición de bandera humana, realiza pequeños movimientos de subida y bajada controlados. Aumenta enormemente la dificultad de la bandera estática. Solo posible tras dominar la bandera humana completa por varios segundos.'),
('7b99b452-65d5-46a5-a9ec-fe7d8ea817bb', '050502d4-89b5-4ed9-97c6-b89f09c723b9', 'en', 'High Pulley Straight Bar Row', 'Pull the bar toward your thighs keeping arms straight at all times. Objective: lats and serratus. Cue: firm core and neutral back. Error: flexing elbows to help the pull.'),
('b4b62ac4-9e5b-44bc-b31f-d25573aae216', '050502d4-89b5-4ed9-97c6-b89f09c723b9', 'es', 'Remo en polea alta con barra recta', 'Tira de la barra hacia tus muslos manteniendo los brazos rectos en todo momento. Objetivo: dorsal y serrato. Cue: core firme y espalda neutra. Error: flexionar los codos para ayudar al tirón.'),
('f5ba2813-d687-48e9-bff7-824dc496e2b2', '055a966f-b2d1-4997-b678-6adca7ec173a', 'en', 'Ring Iron Cross', 'Hold your arms extended horizontally to the sides while supporting your body on the rings, forming a perfect cross.'),
('c985eb12-ab3b-4c75-a43e-b76358387ead', '055a966f-b2d1-4997-b678-6adca7ec173a', 'es', 'Iron Cross en anillas', 'Manten los brazos extendidos lateralmente de forma horizontal sosteniendo el cuerpo en las anillas, formando una cruz perfecta.'),
('690954d5-11ae-448d-8346-18023c122582', '058851ee-e570-46c8-8577-a1d3170a230f', 'en', 'Single Arm Kettlebell Front Rack Contralateral Bulgarian Split Squat', 'Split squat with elevated foot holding the kettlebell on the shoulder opposite to the working leg, keeping the core tight to prevent rotation.'),
('32227cdd-9bd9-41c0-8ed4-02878f1e43f2', '058851ee-e570-46c8-8577-a1d3170a230f', 'es', 'Sentadilla Búlgara contralateral con rack frontal y pesa rusa de un solo brazo', 'Sentadilla split con pie elevado sosteniendo la Kettlebell en el hombro opuesto a la pierna que trabaja, manteniendo el core firme para evitar la rotacion.'),
('95adacfc-4c55-4585-9434-a6ce62317d92', '05a14a23-ddd9-4939-a1ad-483b38d58cb7', 'en', 'Dumbbell Crush Grip Romanian Deadlift', 'Join the dumbbells together and perform a Romanian deadlift while maintaining tension by squeezing them during the movement.'),
('a4533840-d5e0-41f5-b21e-1e5927e68be1', '05a14a23-ddd9-4939-a1ad-483b38d58cb7', 'es', 'Peso muerto rumano con agarre aplastado y mancuernas', 'Pisa las mancuernas uniendolas y realiza un peso muerto rumano manteniendo la tension al apretarlas durante el movimiento.'),
('6159bf30-2124-4754-bf64-7185f636e76f', '05a792eb-9771-4473-a937-cfac19ae079b', 'en', 'Pendlay Row', 'Barbell row from the floor on each rep to develop back with power and strict hinge technique.'),
('4671f8d2-31ac-4d12-9b51-d762bccac4b7', '05a792eb-9771-4473-a937-cfac19ae079b', 'es', 'Remo Pendlay', 'Torso casi paralelo al suelo, espalda neutra. Tira hacia el abdomen y apoya controlado entre repeticiones.'),
('92aa3f75-4cab-46ef-83ff-2f321fa94f40', '05af56d8-a07c-4f69-bb88-bb45bf987d05', 'en', 'Behind the Neck Barbell Lateral Lunge', 'Side step with the bar on shoulders. Cue: hips back when lowering. Error: knee passes the foot.'),
('c401a787-cc46-493b-800a-7abbf80746c0', '05af56d8-a07c-4f69-bb88-bb45bf987d05', 'es', 'Zancada lateral barra tras nuca', 'Paso lateral con barra en hombros. Cue: cadera atrás al bajar. Error: rodilla sobrepasa pie.'),
('e16e29b5-9a67-4eb1-aad6-31bb38fa47ab', '05af5ac8-208e-4420-b8ac-de5c93b6582e', 'en', 'Single Arm Kettlebell Z Press', 'Sitting on the floor with straight legs, press the kettlebell overhead without back support to isolate the shoulder and core.'),
('bd8f2da0-9153-482b-abf7-515c0376b069', '05af5ac8-208e-4420-b8ac-de5c93b6582e', 'es', 'Press Z con pesa rusa de un solo brazo', 'Sentado en el suelo con piernas estiradas, presiona la Kettlebell sobre la cabeza sin apoyo dorsal para aislar el hombro y core.'),
('ca7fd497-63d5-4ca1-be98-0e1aa794032b', '05eda6ce-65ea-47b0-b6c9-1aeb35bbc2b7', 'en', 'Machine Hip Abduction', 'Seated, push the pads outward with your thighs. Cue: controlled movement. Error: using torso momentum to lift the weight.'),
('4ffe1734-d1f2-4ba4-b6a3-271d2334bcbe', '05eda6ce-65ea-47b0-b6c9-1aeb35bbc2b7', 'es', 'Abducción de cadera en máquina', 'Sentado, empuja las almohadillas hacia afuera con los muslos. Cue: movimiento controlado. Error: usar el impulso del tronco para despegar el peso.'),
('311c5bd0-eabf-476c-b1fe-61acd74b69a0', '060aa295-0ce4-43d2-947b-624c2e0ad896', 'en', 'Double Kettlebell Front Rack Skater Squat', 'Perform a skater squat while holding two kettlebells in the rack position, requiring extreme balance from the supporting leg.'),
('81d4c606-f3e3-49f1-8a3a-9714d276e00a', '060aa295-0ce4-43d2-947b-624c2e0ad896', 'es', 'Sentadilla patinadora Front Rack con Kettlebell doble', 'Realiza una sentadilla patinadora sosteniendo dos Kettlebells en posicion rack, exigiendo un equilibrio extremo de la pierna de apoyo.'),
('d1df5c18-0982-46db-80f9-9374a95ce0e9', '061295db-986a-40ae-bc77-4b4500e52773', 'en', 'Double Indian Club Overhead Arm Circles', 'Perform controlled circles above the head with both Indian Clubs to improve scapular stability and thoracic mobility.'),
('554580f0-c37d-446a-97c8-8b1d3d54d843', '061295db-986a-40ae-bc77-4b4500e52773', 'es', 'Círculos de brazos Overhead con Indian Club doble', 'Realiza círculos controlados por encima de la cabeza con ambos Indian Clubs para mejorar la estabilidad escapular y la movilidad torácica.'),
('06e19393-6f65-4139-a8f6-2bd2d874a274', '061645d0-5e65-4d09-b959-6f2317916106', 'en', 'Double Kettlebell Cyclist Thruster', 'Perform a cyclist squat with heels elevated holding two kettlebells. Rise with power and press both weights overhead in one fluid movement.'),
('a95a5e9e-62a3-442d-9062-8aab97d35c70', '061645d0-5e65-4d09-b959-6f2317916106', 'es', 'Thruster Ciclista con Kettlebell doble', 'Realiza una sentadilla ciclista con talones elevados sosteniendo dos Kettlebells. Sube con potencia y presiona ambas pesas sobre la cabeza en un movimiento fluido.'),
('7e8f36c0-6380-4103-ba66-adedfa565057', '0675465f-36aa-4355-8296-86d4cacbc2c1', 'en', 'Cable Glute Kickback', 'With ankle strap connected to low pulley, perform hip extensions backward keeping the leg relatively straight. Lean slightly forward for stability. Focus on contracting the glute without excessively arching the back.'),
('b627ecbf-1c51-4efe-8cca-34e05cf0d28a', '0675465f-36aa-4355-8296-86d4cacbc2c1', 'es', 'Patada glúteo cable', 'Con tobillera conectada a polea baja, realiza extensiones de cadera hacia atrás manteniendo la pierna relativamente recta. Inclínate ligeramente hacia adelante para estabilidad. Enfócate en contraer el glúteo sin arquear excesivamente la espalda.'),
('4fc7a7a3-a9a6-493c-9167-ab8eaaf4307c', '068fa480-9dff-4f2f-80ef-f834d8298a32', 'en', 'Rotational Throw', 'Sideways to a wall, rotate the torso and throw the ball laterally with force. Catch the bounce and repeat. Excellent for developing rotational power useful in sports. Keep hips stable and rotate from the core.'),
('4fc40e2f-85c1-41a1-a316-5c8e0be58fee', '068fa480-9dff-4f2f-80ef-f834d8298a32', 'es', 'Rotational throw', 'De lado a la pared, rota el torso y lanza el balón lateralmente con fuerza. Recibe el rebote y repite. Excelente para desarrollar potencia rotacional útil en deportes. Mantén las caderas estables y rota desde el core.'),
('8fd06123-3704-4e92-934d-39852bbf9585', '069ef703-85ee-412a-aa44-23d0ac48bfe8', 'en', 'Supinated Bent Over Barbell Row', 'Torso at 45 degrees, grab the bar with palms up and pull toward the navel. Objective: lower lat and biceps. Cue: elbows tucked to the sides when pulling. Common error: straightening the torso during the set to make it easier.'),
('5a161b9d-6757-48fe-91c9-cab90341be1e', '069ef703-85ee-412a-aa44-23d0ac48bfe8', 'es', 'Remo inclinado con barra supinado', 'Torso a 45 grados, agarra la barra con palmas hacia arriba y tira hacia el ombligo. Objetivo: dorsal inferior y bíceps. Cue: codos pegados a los costados al tirar. Error común: erguir el torso durante la serie para facilitar el movimiento.'),
('5b8c09da-2d10-450e-812e-6b685fff587c', '06be8aef-e358-41dd-8598-10da00b8af12', 'en', 'Unilateral Machine Lat Pulldown', 'Pull the lever with one arm. Cue: squeeze the lat. Error: leaning too much.'),
('bbe93921-436b-44db-a019-90fc94da9696', '06be8aef-e358-41dd-8598-10da00b8af12', 'es', 'Jalón lateral unilateral máquina dorsal', 'Tira palanca a un brazo. Cue: aprieta dorsal. Error: inclinarse mucho.'),
('64afc618-f0fd-483a-a736-19918faa1d88', '06de1c67-c22b-4f3d-bcb5-531724ad31d0', 'en', 'Chest-Supported Dumbbell Lateral Lunge', 'Hold a dumbbell Goblet-style and take lateral steps lowering the hip. Objective: adductors and glute. Cues: heel always supported. Common error: letting the torso fall forward.'),
('fd56a06a-5e52-4701-9cda-bd4b12e88bb0', '06de1c67-c22b-4f3d-bcb5-531724ad31d0', 'es', 'Zancada lateral con mancuerna al pecho', 'Sujeta una mancuerna estilo Goblet y realiza pasos laterales bajando la cadera. Objetivo: aductores y glúteo. Cues: talón siempre apoyado. Error común: dejar que el torso caiga hacia adelante.'),
('c0b7e839-b17b-403a-9f11-b81df1c90887', '06f90fda-e1d3-4c7a-a8d5-dc6e4ee817b5', 'en', 'Shrimp Squat', 'Standing on one leg, bring the free leg back holding the ankle with the hand of the same side. Lower into a squat until the knee of the back leg touches the floor. Push to return up. Requires strength, balance, and quadriceps flexibility.'),
('30b94386-b60f-43e3-ab9d-ec294465b37a', '06f90fda-e1d3-4c7a-a8d5-dc6e4ee817b5', 'es', 'Shrimp squats', 'De pie sobre una pierna, lleva la pierna libre hacia atrás sujetando el tobillo con la mano del mismo lado. Desciende en sentadilla hasta que la rodilla de la pierna trasera toque el suelo. Empuja para volver arriba. Requiere fuerza, equilibrio y flexibilidad en cuádriceps.'),
('ed5c3cef-e560-4ba0-bf4b-e36321d61924', '070868e8-6bef-4619-bfb2-a1709c4f5828', 'en', 'Chest Dips', 'Perform parallel bar dips with a chest emphasis. Lean the torso slightly forward, lower under control, and press up until the arms are extended.'),
('ffa385c2-34d7-42ad-8bbe-51bb836a86b8', '070868e8-6bef-4619-bfb2-a1709c4f5828', 'es', 'Fondos para pecho en paralelas', 'Realiza fondos en paralelas con énfasis en pecho. Inclina ligeramente el torso hacia delante, baja de forma controlada y empuja hasta extender los brazos.'),
('63320eb3-e5a4-4d70-9825-244ac62bbf43', '071734ec-cdef-44f7-9ada-a9bf797e5717', 'en', 'Dumbbell Bulgarian Split Squat', 'With the back foot elevated on a bench and a dumbbell in each hand, perform a unilateral squat descending until the front knee forms 90 degrees. Keep the torso upright and weight mainly on the front heel. Excellent for unilateral strength.'),
('5670198c-67db-422b-8b90-7b666053e75b', '071734ec-cdef-44f7-9ada-a9bf797e5717', 'es', 'Sentadilla búlgara mancuernas', 'Con el pie trasero elevado en un banco y una mancuerna en cada mano, realiza una sentadilla unilateral descendiendo hasta que la rodilla delantera forme 90 grados. Mantén el torso erguido y el peso principalmente en el talón delantero. Excelente para fuerza unilateral.'),
('66f6731e-7f0d-4177-aa58-bbf3f9410b9a', '0739688a-865f-42fe-84ad-91af88587d9e', 'en', 'Suitcase Deadlift', 'Deadlift with bar at the side of the body like a suitcase. Tremendous lateral stabilization challenge. Intensely works anti-lateral flexion core. Use less weight than regular deadlift. Alternate sides.'),
('74ea9994-c4c6-404f-b949-a4b488a44af5', '0739688a-865f-42fe-84ad-91af88587d9e', 'es', 'Peso muerto maleta', 'Peso muerto con barra al lado del cuerpo como una maleta. Tremendo desafío de estabilización lateral. Trabaja intensamente el core anti-flexión lateral. Usa menos peso que peso muerto regular. Alterna lados.'),
('adc6fe53-61f7-41f0-bcc9-ed28430f68fb', '07696a43-8968-48ba-b678-36cc2fa9329f', 'en', 'Cable Rope Behind the Neck Extension', 'Extend arms overhead with a rope. Objective: long head of the triceps. Cue: full stretch. Error: arching the lower back.'),
('e86b9c8d-52d1-4fc8-96a1-4b8712a78aa0', '07696a43-8968-48ba-b678-36cc2fa9329f', 'es', 'Extensión tras nuca cuerda polea', 'Extiende brazos sobre cabeza con cuerda. Objetivo: cabeza larga tríceps. Cue: estira total. Error: arquear lumbar.'),
('e0432a68-c59a-426e-b087-188d4bb6ad34', '077dd018-c38c-472a-8795-61bab428598e', 'en', 'TRX Clock Press', 'Press at different angles simulating clock positions. Works shoulders from multiple angles while challenging core stability. Requires exceptional control and shoulder strength.'),
('31b527bd-f123-4673-8d27-2aff739e93ce', '077dd018-c38c-472a-8795-61bab428598e', 'es', 'Clock press TRX', 'Press en diferentes ángulos simulando las posiciones de un reloj. Trabaja los hombros desde múltiples ángulos mientras desafía la estabilidad del core. Requiere control excepcional y fuerza en hombros.'),
('f9de530c-a9e6-4d1e-9149-add44130e07b', '07c2bf48-5235-495f-a61b-7997c1f924b9', 'en', 'Handstand Push Ups', 'Upside down against a wall, flex and extend arms. Cue: very firm core. Error: arching back like a bow.'),
('abdaf78a-2ec6-4134-82e6-5e4d9e3aa091', '07c2bf48-5235-495f-a61b-7997c1f924b9', 'es', 'Flexiones de pino', 'Boca abajo contra la pared, flexiona y extiende brazos. Cue: core muy firme. Error: arquear la espalda como un arco.'),
('e6381155-131f-447c-8d57-aec18de671cc', '07c60932-4073-4982-bd04-b46e0e80382c', 'en', 'Seated Machine Triceps Pushdown', 'Push the handles down while seated. Cue: fixed elbows. Error: using body weight.'),
('192aa307-84a0-4aaa-921e-3be439f1cb56', '07c60932-4073-4982-bd04-b46e0e80382c', 'es', 'Extensión tríceps máquina empuje', 'Empuja agarres abajo sentado. Cue: codos fijos. Error: usar peso cuerpo.'),
('73e1c3b9-555d-4964-a764-8c74ab93116a', '08038803-49dd-4088-849e-169253263a44', 'en', '180-Degree Jump Squat', 'Jump squat incorporating a full 180-degree turn in the air. Requires power, coordination, and spatial control. Land softly and continue the movement. Excellent for sports requiring agility.'),
('7f9f2402-05f3-4669-a6e7-1dc6cefada22', '08038803-49dd-4088-849e-169253263a44', 'es', 'Sentadilla salto 180 grados', 'Sentadilla con salto incorporando un giro completo de 180 grados en el aire. Requiere potencia, coordinación y control espacial. Aterriza suavemente y continúa el movimiento. Excelente para deportes que requieren agilidad.'),
('c7e9d972-a5c2-43e4-a0f1-e4414da1b56d', '080be644-8a87-4dcf-92d4-d2b5379bbc25', 'en', 'Alternating Front Barbell Cossack Squat', 'Perform a deep lateral squat with the bar in a front rack position, requiring maximum hip mobility and torso stability.'),
('af3bb39c-f7bd-499f-82ef-207fefab50f0', '080be644-8a87-4dcf-92d4-d2b5379bbc25', 'es', 'Sentadilla Cosaca alterna con barra frontal', 'Realiza una sentadilla lateral profunda con la barra en posición de rack frontal, exigiendo máxima movilidad de cadera y estabilidad del torso.'),
('b20cb0c3-4abd-47c7-9dff-8725172df89d', '080eba09-63ab-44d4-9059-8eb3c3a0d86b', 'en', 'Cross Arm Barbell Front Squat', 'Front squat with arms crossed over the bar. Cue: high elbows. Error: bar rolls to the neck.'),
('5208aca3-1c35-43d8-8139-7f7704f53d3f', '080eba09-63ab-44d4-9059-8eb3c3a0d86b', 'es', 'Sentadilla frontal agarre cruzado barra', 'Sentadilla frontal con brazos en X sobre la barra. Cue: codos altos. Error: barra rueda al cuello.'),
('288544b0-cb48-4142-8ec3-7d529ebe6a0d', '0811187b-348a-4383-8126-031b2e604512', 'en', 'Jefferson Squat', 'Straddle the bar, one foot forward and one behind, hold the bar and lower into a squat. Objective: leg and core power. Cue: maintain a vertical torso. Error: letting the bar touch the ground abruptly.'),
('25175bd7-141e-4a16-8910-ba19892b7495', '0811187b-348a-4383-8126-031b2e604512', 'es', 'Sentadilla Jefferson', 'Ponte a horcajadas sobre la barra, un pie delante y otro detrás, sujeta la barra y baja en sentadilla. Objetivo: potencia de piernas y core. Cue: mantén el torso vertical. Error: dejar que la barra toque el suelo de forma brusca.'),
('e111dcb1-2227-462f-be30-e2030c446b96', '081fcd2e-ca61-487a-ba7e-e90e55bacf72', 'en', 'Dumbbell Push Press', 'Hold dumbbells at the shoulders, perform a slight knee flexion and use the momentum to push the weights overhead.'),
('57810fc2-ebce-467b-b237-5c98bd7095d4', '081fcd2e-ca61-487a-ba7e-e90e55bacf72', 'es', 'Push Press con mancuernas', 'Sostén mancuernas en los hombros, haz una pequeña flexion de rodillas y utiliza el impulso para empujar las pesas sobre la cabeza.'),
('7f32ea6d-2600-4ed8-bb32-f1b66f2454e2', '0845d596-cb54-4576-ba1a-4a1a3a902fc3', 'es', 'Zancada en polea baja cable estricta', 'Zancada con cable tirando pierna atrás. Cue: torso erguido. Error: perder estabilidad.'),
('1c465eed-13c3-41c1-b12e-c1654d441854', '085cc2da-bfed-4bf4-aa76-2f1696868fb2', 'es', 'Turkish Sit Up con mancuernas', 'Realiza un sit up manteniendo dos mancuernas extendidas verticalmente sobre el pecho, exigiendo un control abdominal superior.'),
('5073190d-8187-4e43-88a5-a841c6d329cf', '08725c52-a28f-41fa-8402-57b01193c2a3', 'en', 'Double Kettlebell Bottoms Up Overhead Walking Lunge', 'Perform walking lunges while maintaining two upside-down kettlebells overhead with locked arms, demanding total balance and strength.'),
('3bf611c6-aee7-492a-a743-3df5adf915a2', '08725c52-a28f-41fa-8402-57b01193c2a3', 'es', 'Zancada caminando Overhead con Kettlebell doble Bottoms Up', 'Realiza zancadas manteniendo dos pesas rusas invertidas sobre la cabeza con brazos bloqueados, exigiendo un equilibrio y fuerza total.'),
('0735dc9b-9908-4eec-ba3f-8693635ad551', '0873ec86-5908-44fc-b938-1720af58d951', 'en', 'Unilateral High Pulley Ear Curl', 'Sideways to high pulley, flex to ear. Cue: high elbow. Error: dropping elbow.'),
('30097801-d5a9-4a25-8c6b-2a2cd75ce631', '0873ec86-5908-44fc-b938-1720af58d951', 'es', 'Curl bíceps polea alta unilateral oreja', 'De lado a polea alta, flexiona a oreja. Cue: codo alto. Error: bajar codo.'),
('285566bf-9de6-45f3-8988-68afc629ce5d', '089bd617-f41f-40da-8ae8-fa4e66c6d22f', 'en', 'Superband Single Leg Tibialis Raise', 'Seated with the band anchored to the foot, flex the ankle bringing toes toward the shin against resistance to strengthen the tibialis.'),
('480d44d5-60dc-40bb-a535-988e52abdb24', '089bd617-f41f-40da-8ae8-fa4e66c6d22f', 'es', 'Elevación de tibial a una pierna con banda', 'Sentado con la banda anclada al pie, flexiona el tobillo llevando los dedos hacia la espinilla contra la resistencia para fortalecer el tibial.'),
('9d7fc692-2023-4e5d-869f-4b889d6f0f1a', '08ad06fb-f21a-4d4e-9059-c5df4859383b', 'en', 'Seated Neutral Machine Row', 'Pull the handles in a rowing machine. Cue: join scapulae back. Error: shrugging shoulders.'),
('25c5b5ca-4e13-4d90-87e5-494b250dfd2d', '08ad06fb-f21a-4d4e-9059-c5df4859383b', 'es', 'Remo en máquina sentado neutro', 'Tira de los agarres en máquina de remo. Cue: junta escápulas atrás. Error: encoger hombros.'),
('cf2f092a-b1a3-4a67-a242-421a6c4395cd', '08c36a43-4a9c-4f3c-8179-e18535d35b6a', 'en', 'Cable Guillotine Curl', 'Lie on a flat bench under a high pulley. Perform a curl bringing the bar toward your neck (carefully), keeping elbows high and fixed.'),
('5d59e3c8-b19b-4025-80d1-8d50a9d95762', '08c36a43-4a9c-4f3c-8179-e18535d35b6a', 'es', 'Curl guillotina con cable', 'Acuéstate en un banco plano debajo de una polea alta. Realiza un curl llevando la barra hacia tu cuello (con cuidado), manteniendo los codos altos y fijos.'),
('b0675410-59fd-49ab-9c0e-187b7320c98a', '091f3beb-4843-490f-8511-c7d00f55e6d1', 'en', 'Spider Row (Dumbbell)', 'Lying face down on an incline bench, let the dumbbells hang and row toward the chest. Objective: mid-back and retractors. Cue: squeeze shoulder blades at the end. Error: separating chest from bench.'),
('e5a4df82-5b9a-445d-9d2e-bee74ef10ed1', '091f3beb-4843-490f-8511-c7d00f55e6d1', 'es', 'Remo con mancuerna al pecho (Spider Row)', 'Tumbado boca abajo en un banco inclinado, deja colgar las mancuernas y rema hacia el pecho. Objetivo: espalda media y retractores. Cue: aprieta las escápulas al final. Error: separar el pecho del banco.'),
('4733db6e-b949-49af-bd9f-81cc9be8bd79', '09275a9c-be70-4ac4-882c-700aa799251c', 'en', 'Behind the Neck Pull-ups', 'Pull-ups bringing the back of the neck toward the bar instead of the chin. Works lats from a different angle. Requires good shoulder mobility. Some experts advise against it due to injury risk. Use with caution.'),
('a387de4a-0d2f-4ec5-a301-efd816305c66', '09275a9c-be70-4ac4-882c-700aa799251c', 'es', 'Dominadas tras nuca', 'Dominadas llevando la nuca hacia la barra en lugar de la barbilla. Trabaja los dorsales desde un ángulo diferente. Requiere buena movilidad de hombros. Algunos expertos desaconsejan por riesgo de lesión. Usa con precaución.'),
('558bf609-93ee-4196-bbfb-dacc31006f1e', '0941737b-d37d-417b-a49c-b9d4a279743f', 'en', 'Lateral Lunge with Jump', 'Perform a lateral lunge and push explosively to jump to the other side. Power in the lateral plane. Cue: push with the entire sole of the foot. Common error: not going low enough before the jump.'),
('f1c839be-7305-460d-a3e8-6cc10cfcca81', '0941737b-d37d-417b-a49c-b9d4a279743f', 'es', 'Zancada lateral con salto', 'Realiza una zancada lateral y empuja explosivamente para saltar hacia el otro lado. Potencia en el plano lateral. Cue: empuja con toda la planta del pie. Error común: no bajar lo suficiente antes del salto.'),
('cd88dd28-834a-43c0-9a17-c473144d9e5b', '0955e938-65b1-4f57-ba45-e294557d1fce', 'en', 'Dumbbell Chest Press', 'Perform a dumbbell chest press. Lower the dumbbells under control to chest level and press upward while maintaining shoulder and scapular stability.'),
('598d22e3-cd34-41ce-804c-0cf411c7ee9b', '0955e938-65b1-4f57-ba45-e294557d1fce', 'es', 'Press pecho', 'Realiza un press de pecho con mancuernas. Baja las mancuernas de forma controlada hasta la altura del pecho y empuja hacia arriba manteniendo estabilidad en hombros y escápulas.'),
('f5551b32-c303-46d0-8366-e1f97359059c', '0967baba-b3fe-44a6-977a-22bbdcc34483', 'en', 'Double Kettlebell Overhead Walking Lunge', 'Walk performing lunges while holding two kettlebells locked out overhead, requiring total balance and mobility control.'),
('13357a8b-3c45-4ce4-be27-e285f1800855', '0967baba-b3fe-44a6-977a-22bbdcc34483', 'es', 'Zancada caminando Overhead con Kettlebell doble', 'Camina realizando zancadas mientras sostienes dos Kettlebells bloqueadas sobre la cabeza, exigiendo un control total del equilibrio y la movilidad.'),
('09ad3772-507c-4519-93e9-8987ba6e4556', '097ab32c-544d-42b3-b425-e8a39751a834', 'en', 'Cable Triceps Extension', 'With a high pulley and straight bar or rope, perform elbow extensions keeping the upper arms glued to the body. Fully extend the elbows at the bottom of the movement. It is one of the best exercises for isolating the triceps.'),
('999c40cb-b8ad-49ed-9333-8b8a1c25c9d7', '097ab32c-544d-42b3-b425-e8a39751a834', 'es', 'Extensión tríceps cable', 'Con polea alta y barra recta o cuerda, realiza extensiones de codo manteniendo los brazos superiores pegados al cuerpo. Extiende completamente los codos en la parte inferior del movimiento. Es uno de los mejores ejercicios para aislar el tríceps.'),
('7e70c727-e16a-487f-93ab-691479aa97dc', '098c8ab9-d39a-48b8-a436-c143c7610cd6', 'en', 'Band Chest Flyes', 'Band behind the back, bring hands together in front. Cue: keep elbows slightly bent. Error: shrugging shoulders.'),
('78398cfe-cbb5-4a36-9b9e-079a22be56d6', '098c8ab9-d39a-48b8-a436-c143c7610cd6', 'es', 'Aperturas de pecho con banda', 'Banda tras la espalda, junta manos al frente. Cue: mantén codos semiflexionados. Error: encoger hombros.'),
('1525d5a2-e5b1-408c-aac1-ff742bf85de8', '09a5b3df-37e8-458b-8125-d9588a31a962', 'en', 'Bosu Flat Plank', 'Maintain a plank with hands on the flat platform of the Bosu. Shoulder stability. Straight body. Don''t let the Bosu shake too much.'),
('14620a91-22d2-4f0e-a2af-01a7fe329fc1', '09a5b3df-37e8-458b-8125-d9588a31a962', 'es', 'Bosu plancha plana', 'Mantén plancha con manos en la plataforma plana del bosu. Estabilidad de hombros. Cuerpo recto. No dejes que el bosu tiemble demasiado.'),
('a3a6f7b2-a605-48ac-abfd-252b38446078', '09afcadd-7707-4c51-a76a-49306c6c4bc3', 'es', 'Press Pallof arrodillado con cable alto', 'Arrodillado sobre ambas piernas de lado a una polea alta, sujeta el mando y extiendelo frente a ti, resistiendo la traccion diagonal hacia arriba.'),
('c0475975-93f3-4d31-960f-149ef3381011', '09c14bdd-16ab-48f9-8513-69214c34e659', 'en', 'Ring Freestanding Handstand Push Up', 'The ultimate vertical push exercise: perform handstand push-ups directly on unstable rings.'),
('9c7e5bad-652e-4da3-8fe7-d76965b8c2c2', '09c14bdd-16ab-48f9-8513-69214c34e659', 'es', 'Handstand Push Up en anillas', 'El ejercicio máximo de empuje vertical: realiza flexiones en parada de manos directamente sobre las anillas inestables.'),
('999886f7-bcab-41d6-b0d6-b072e4fbf99b', '0a1562e7-1daa-4d5c-af93-5c989a267e2f', 'es', 'Zancada con rotación de tronco', 'Realiza una zancada y, en la posición baja, gira el torso hacia el lado de la pierna adelantada. Objetivo: estabilidad y movilidad. Cue: mantén la rodilla alineada al rotar. Error: perder el equilibrio lateral.'),
('e595b940-4fc0-488a-b0bb-be7b0041ff16', '0a2237ed-5455-43b7-a424-15add66c3394', 'en', 'Rotational Ball Toss', 'Explosive lateral toss against a wall. Generates maximum rotational power from the hips. Useful for throwing sports. Receive the bounce with control and repeat fluidly. Alternate directions.'),
('f5dcbe09-c88b-4153-ad5f-e2bed776cea0', '0a2237ed-5455-43b7-a424-15add66c3394', 'es', 'Lanzamiento rotacional balón', 'Lanzamiento lateral explosivo contra pared. Genera máxima potencia rotacional desde las caderas. Útil para deportes de lanzamiento. Recibe el rebote con control y repite fluidamente. Alterna direcciones.'),
('4d8aae47-5064-4997-b50a-a8a4156c764b', '0a945cee-f82c-4f0c-910c-25abce4432d2', 'en', 'TRX Chest Press (Chest Focus)', 'Back to the anchor, perform pushups holding the handles. Objective: chest with instability. Cue: body straight like a board. Common error: letting the straps rub against your arms.'),
('e74d54e2-3d8e-4f78-ba8c-5a2940ec9e5b', '0a945cee-f82c-4f0c-910c-25abce4432d2', 'es', 'TRX Press de pecho', 'De espaldas al anclaje, realiza flexiones sujetando los agarres. Objetivo: pectoral con inestabilidad. Cue: cuerpo recto como tabla. Error común: dejar que las correas rocen los brazos.'),
('fafbba9c-1ba3-4c04-a670-bfc232fd9ad5', '0b15b377-94ec-4038-af70-0e0801cc8c7b', 'en', 'Machine Shoulder Press', 'Seated in the machine, push the handles upward until arms are fully extended. Objective: deltoids. Cue: control the weight''s descent. Error: locking elbows abruptly at the top.'),
('37335573-d379-4912-a3bf-04c5c33f7ede', '0b15b377-94ec-4038-af70-0e0801cc8c7b', 'es', 'Press de hombros en máquina', 'Sentado en la máquina, empuja los agarres hacia arriba hasta extender los brazos por completo. Objetivo: deltoides. Cue: controla el descenso del peso. Error: bloquear los codos bruscamente arriba.'),
('3380afad-8e3f-48d9-8b0e-a9868f9042fa', '0b2645f5-2e12-4e20-b509-7557354e7b3b', 'en', 'Ring Straight Arm Pike Press Handstand', 'From a pike position on rings, press with locked straight arms until reaching a vertical handstand.'),
('30706a47-6598-45ab-9596-de431af5865e', '0b2645f5-2e12-4e20-b509-7557354e7b3b', 'es', 'Parada de manos con Press de pica con brazo recto en Anillas', 'Desde posicion de pica en anillas, presiona con los brazos bloqueados y rectos hasta alcanzar la vertical de la parada de manos.'),
('b6337cbf-3fb9-496e-945d-a85fb27ddd5e', '0b3a1aed-862f-45b7-8a17-1459bcd257af', 'en', 'Walking Lunges', 'Move forward by taking long steps and lowering the back knee toward the floor. Cue: upright torso. Error: step too short which lifts the front heel.'),
('339df9a6-409a-4c97-809b-c6ee4521052b', '0b3a1aed-862f-45b7-8a17-1459bcd257af', 'es', 'Zancadas caminadas', 'Avanza dando pasos largos y bajando la rodilla trasera hacia el suelo. Cue: torso erguido. Error: paso demasiado corto que levanta el talón delantero.'),
('add171a4-012c-4a2f-991c-3bf889d55611', '0b60f99f-758c-4aff-88ef-dedd3dc7a855', 'en', 'Dragon squats', 'Extreme variation of the single-leg squat where the free leg is kept extended behind the body throughout the movement. Descend to the lowest possible position while maintaining total control. Requires exceptional strength and mobility.'),
('ac17a082-039e-47f3-a4a6-6e06b3ea5a45', '0b60f99f-758c-4aff-88ef-dedd3dc7a855', 'es', 'Dragon squats', 'Variación extrema de sentadilla a una pierna donde la pierna libre se mantiene extendida detrás del cuerpo durante todo el movimiento. Desciende hasta la posición más baja posible manteniendo el control total. Requiere fuerza y movilidad excepcionales.'),
('fc088a84-43d2-483c-9b46-72e8ca53871c', '0b6d2484-6b2a-4ed3-9fbb-f5932552ff51', 'en', 'Medicine Ball Russian Twist', 'Seated, rotate the ball from side to side touching the floor. Objective: dynamic obliques. Cue: keep heels elevated. Common error: moving only the ball without rotating the shoulders.'),
('e3ff5608-0ff5-4b86-8119-157b82b9db32', '0b6d2484-6b2a-4ed3-9fbb-f5932552ff51', 'es', 'Giro ruso con balón medicinal', 'Sentado, gira el balón de lado a lado tocando el suelo. Objetivo: oblicuos dinámicos. Cue: mantén los talones elevados. Error común: mover solo el balón sin rotar los hombros.'),
('53e61923-09f3-40fc-8105-01d7d4289c1b', '0ba9e9da-5944-4405-b6f0-35fb53974f0d', 'en', 'Single Arm Dumbbell Windmill', 'With a dumbbell overhead and feet wide, lean the torso toward the opposite foot keeping the back leg straight and eyes on the weight.'),
('aa6db74c-cdc8-492b-a8a7-9b5045793a94', '0ba9e9da-5944-4405-b6f0-35fb53974f0d', 'es', 'Windmill con mancuerna a una mano', 'Con una mancuerna sobre la cabeza y pies anchos, inclina el torso hacia el pie opuesto manteniendo la pierna trasera recta y la mirada en la pesa.'),
('1b07ea06-f141-479b-a6ee-4af61fad83e9', '0bda9d32-ce04-4b6a-b7f7-1f153e0208fc', 'en', 'Push-ups', 'In a plank position, lower chest to the floor and push up. Cue: elbows at 45 degrees from the body. Error: letting hips sag or rise too high.'),
('b9be8df6-cb2a-4567-bcd8-2579c18b0a74', '0bda9d32-ce04-4b6a-b7f7-1f153e0208fc', 'es', 'Flexiones de brazos (Push-ups)', 'En posición de plancha, baja el pecho al suelo y empuja. Cue: codos a 45 grados del cuerpo. Error: dejar que la cadera se hunda o suba demasiado.'),
('7f04a5d5-5c4a-4883-914a-3662199d4965', '0be406e4-78c3-40db-a3b8-52c2afc65d68', 'en', 'Face Pull', 'Pull the rope toward the face, separating the ends. Objective: shoulder health and retractors. Cue: thumbs back at the end. Common error: forward neck when pulling.'),
('3f5646b2-9949-4eee-a896-d2f78656b935', '0be406e4-78c3-40db-a3b8-52c2afc65d68', 'es', 'Face Pull', 'Tira de la cuerda hacia la cara abriendo los extremos. Objetivo: salud del hombro y retractores. Cue: pulgares hacia atrás al final. Error común: adelantar el cuello al tirar.'),
('ce7bf5c7-b640-4d11-af13-3f14284d0ce8', '0c3b5550-518a-4b31-9581-c778d132104e', 'en', 'Ring Feet Elevated Archer Row', 'With feet elevated, pull the body up while extending one arm laterally, alternating the pulling arm each rep.'),
('dfff29fb-6e28-4762-ae66-79b270ab623e', '0c3b5550-518a-4b31-9581-c778d132104e', 'es', 'Remo con arquero elevado con pies anulares', 'Con los pies elevados, tira del cuerpo hacia arriba mientras extiendes un brazo lateralmente, alternando el brazo que tracciona en cada repeticion.'),
('0f897fa5-9c62-49ff-8a4f-a4235279e939', '0c3fb19a-b641-4d1a-88c9-90ecb63125c4', 'en', 'Max Unilateral Vertical Jump', 'Jump upward with a single leg seeking to touch a high point. Pure unilateral power. Cue: drive with the opposite arm. Common error: knee valgus during take-off.'),
('08569bef-7ec8-4100-aef8-055a08857cd6', '0c3fb19a-b641-4d1a-88c9-90ecb63125c4', 'es', 'Salto vertical unilateral max', 'Salta hacia arriba con una sola pierna buscando tocar un punto alto. Potencia pura unilateral. Cue: impulsa con el brazo contrario. Error común: valgo de rodilla al despegar.'),
('440deaaa-8965-4375-b631-179ec59f3291', '0c41ba23-35d8-423c-aeed-d66bc8221d1e', 'en', 'Unilateral Machine Shoulder Press', 'Push a single lever of the shoulder machine to correct asymmetries. Objective: isolated deltoid. Cues: back firm against the backrest. Common error: arching the lumbar when pushing.'),
('f6a9628d-f17a-4292-86d9-597da985c8d3', '0c41ba23-35d8-423c-aeed-d66bc8221d1e', 'es', 'Press hombros en máquina unilateral', 'Empuja una sola palanca de la máquina de hombro para corregir asimetrías. Objetivo: deltoides aislado. Cues: espalda firme contra el respaldo. Error común: arquear la lumbar al empujar.'),
('e965c2e3-c301-4456-84c6-2e27be40e421', '0c4f196d-537e-4b43-bf8b-4e03fcf96f09', 'en', 'Deficit Bulgarian Split Squat with Dumbbells', 'With the front foot on a small platform and the back foot elevated on a bench, lower the hip to achieve a deeper range of motion.'),
('5b76aa05-b521-4cf1-8e37-0d607db434dc', '0c4f196d-537e-4b43-bf8b-4e03fcf96f09', 'es', 'Sentadilla Split Búlgara con déficit y mancuernas', 'Con el pie delantero sobre una plataforma pequeña y el trasero elevado en un banco, baja la cadera para lograr un rango de movimiento mas profundo.'),
('95b2efc1-23e0-48d6-9e5d-a63437444a05', '0c6be42f-a9ec-48fd-aa86-a624a4c6ce22', 'en', 'Double Kettlebell Bottoms Up Decline Bench Press', 'On a decline bench, press two upside-down kettlebells toward the ceiling, requiring extreme control over shoulder stability and grip.'),
('1a454330-5582-4d1a-9abf-e0dd4dd68a0f', '0c6be42f-a9ec-48fd-aa86-a624a4c6ce22', 'es', 'Press de banca declinado con Kettlebell doble Bottoms Up', 'En un banco declinado, presiona dos Kettlebells invertidas hacia el techo, exigiendo un control extremo de la estabilidad del hombro y agarre.'),
('23a86ba8-ba86-4ac8-90cd-9dde31ab262c', '0c6e2fb1-4da8-447c-912a-9a324a6c1752', 'en', 'Fitball Hand-to-Foot Pass', 'Lying down, pass the ball from your hands to your feet and vice versa without touching the floor. Abdominal coordination. Lower back supported. Do not arch the back.'),
('5d22a2c7-d414-480d-8f93-1a05bd404df1', '0c6e2fb1-4da8-447c-912a-9a324a6c1752', 'es', 'Fitball pase manos pies', 'Tumbado, pasa la bola de tus manos a tus pies y viceversa sin tocar suelo. Coordinación abdominal. Lumbar apoyada. No arquees la espalda.'),
('6283dcd5-da1b-403f-a435-3750fd594247', '0c872bcd-ed07-41cf-8026-7de9804a932d', 'en', 'Behind the Neck Machine Pulldown', 'Pull the bar behind the head to the base of the neck. Cue: chest out. Error: leaning the head too far forward.'),
('8b2be6d0-d736-4c36-8974-6f55726a0622', '0c872bcd-ed07-41cf-8026-7de9804a932d', 'es', 'Jalón tras nuca en máquina', 'Tira de la barra por detrás de la cabeza hasta la base del cuello. Cue: pecho fuera. Error: inclinar la cabeza demasiado adelante.'),
('3d72de23-066b-425d-9699-b6072e44970e', '0c89492b-2f40-490f-87c4-602d96107841', 'en', 'EZ Bar Preacher Bench Bicep Curl', 'Support arms on the preacher bench and flex the EZ bar. Objective: total bicep isolation. Cue: fully straighten the arm on the way down. Common error: lifting the elbow off the pad when rising.'),
('33367858-2729-4a3c-81c3-8dd4dcb6acce', '0c89492b-2f40-490f-87c4-602d96107841', 'es', 'Curl de bíceps en banco predicador con barra Z', 'Apoya los brazos en el banco predicador y flexiona la barra Z. Objetivo: aislamiento total del bíceps. Cue: estira el brazo por completo en la bajada. Error común: levantar el codo de la almohadilla al subir.'),
('9c66077c-edd8-47bb-abaa-f9570066b66a', '0ca17aa3-8f6d-4fb7-bc1a-a8257f73f367', 'en', 'Decline Push Ups', 'Place feet on an elevated surface like a bench or step, while keeping hands on the floor. This position increases the load on the upper pectoral and shoulders. Descend in a controlled manner keeping the body straight and push forcefully to return to the starting position. Feet height determines difficulty.'),
('a30380cb-bed9-4909-9bf6-1008f05923d7', '0ca17aa3-8f6d-4fb7-bc1a-a8257f73f367', 'es', 'Flexiones declinadas', 'Coloca los pies sobre una superficie elevada como un banco o step, manteniendo las manos en el suelo. Esta posición aumenta la carga sobre el pectoral superior y los hombros. Desciende controladamente manteniendo el cuerpo recto y empuja con fuerza para volver a la posición inicial. La altura de los pies determinará la dificultad del ejercicio.'),
('b2bc7c5f-09ec-4db3-97d3-e47adecb7d36', '0caf8ec4-b785-479c-8b72-a5be57dc46b4', 'en', 'Split Squat Box Jump', 'Start in a deep lunge position and explosively jump onto a box. Strength from an unfavorable position. Cue: maximum vertical drive. Common error: losing stability before the jump.'),
('e58faccb-5da2-48dd-b664-e5dc104d42e6', '0caf8ec4-b785-479c-8b72-a5be57dc46b4', 'es', 'Salto al cajón desde split squat', 'Inicia en posición de zancada profunda y salta explosivamente sobre un cajón. Fuerza desde posición desfavorable. Cue: empuje vertical máximo. Error común: perder estabilidad antes del salto.'),
('5cb49d12-1339-4783-8de0-1ac6832b43c1', '0cc8214b-49f5-497b-82b7-71a699363ac1', 'en', 'Bulgarian Split Squat Knee-over-Toe', 'With one foot elevated behind you, perform a split squat allowing the front knee to pass the toes to emphasize quadriceps work and ankle mobility.'),
('3e9b59ba-51ab-4974-8e9a-ebb61be9df9a', '0cc8214b-49f5-497b-82b7-71a699363ac1', 'es', 'Sentadilla Búlgara rodilla sobre punta del pie', 'Con un pie elevado detras de ti, realiza una sentadilla split permitiendo que la rodilla delantera sobrepase los dedos del pie para enfatizar el trabajo del cuadriceps y la movilidad del tobillo.'),
('dec91503-6297-467d-bd5c-4b67ee444867', '0cf05856-b865-4f99-bc27-2bfdbecae5cf', 'en', 'Dragon Squat', 'Perform a deep single-leg squat by crossing the free leg behind the supporting leg without it touching the ground.'),
('a11f91a0-826d-49a7-b195-e3712dac55f0', '0cf05856-b865-4f99-bc27-2bfdbecae5cf', 'es', 'Sentadilla Dragón', 'Realiza una sentadilla profunda a una pierna cruzando la pierna libre por detrás de la pierna de apoyo, sin que esta toque el suelo.'),
('7728a845-8e6a-47ed-9ce5-780fca7aebdd', '0cf9ebf7-0167-4e76-9550-a3459196e399', 'en', 'Single Arm Kettlebell Incline Bench Prone Row', 'Support your chest on an incline bench and row a kettlebell toward your side with one arm, isolating the back muscles.'),
('e307ed43-395c-4e67-b9b2-4b98ec8a32a1', '0cf9ebf7-0167-4e76-9550-a3459196e399', 'es', 'Remo prono en banco inclinado a una mano con Kettlebell', 'Apoya el pecho en un banco inclinado y rema una Kettlebell hacia tu costado con un solo brazo, aislando la musculatura de la espalda.'),
('475092b3-5b9e-4483-87e2-f80661ce0643', '0cfb9c77-f630-4d06-916e-783b3ebe908a', 'en', 'Low Bench Chest Dips (45 degrees)', 'Hands on bench, lower chest. Cue: elbows at 45. Error: sinking shoulders.'),
('9a5e5b01-5555-44c0-8162-46d7431cbc91', '0cfb9c77-f630-4d06-916e-783b3ebe908a', 'es', 'Fondos pecho banco bajo 45 grados', 'Manos en banco, baja pecho. Cue: codos a 45. Error: hundir hombros.'),
('b09edc13-fa17-4e10-b2db-99ea8383f996', '0cfeb7b9-0e49-4a92-8d69-dc152bd8b454', 'en', 'Bodyweight Bent Knee Copenhagen Plank Side Raise', 'In a side plank with the top knee supported on a bench, lift your hips working the adductors and perform a raise with the free leg.'),
('e17e5687-5c96-49bf-baac-91d73fdcfc65', '0cfeb7b9-0e49-4a92-8d69-dc152bd8b454', 'es', 'Copenhagen Plank con rodilla doblada y elevación lateral', 'En plancha lateral con la rodilla superior apoyada en banco, eleva la cadera trabajando los aductores y realiza una elevacion con la pierna libre.'),
('92c60615-ea80-4d4b-9ec7-c6c6260f0793', '0d1c5e39-95df-4b03-9c38-ec74388572b4', 'en', 'Battle Ropes Side Shuffle', 'Move laterally while maintaining waves. Works lateral agility and coordination. Maintain a low athletic position and change direction periodically. The core must remain stable.'),
('a451d5f7-db9b-452c-b94c-43a8b74edee5', '0d1c5e39-95df-4b03-9c38-ec74388572b4', 'es', 'Battle ropes side shuffle', 'Desplázate lateralmente mientras mantienes las ondas. Trabaja la agilidad lateral y la coordinación. Mantén una posición atlética baja y cambia de dirección periódicamente. El core debe permanecer estable.'),
('8036ef15-451a-4d36-82a0-786f92a10c08', '0d2f06b7-43c1-4cb5-8c28-c04cca981208', 'en', 'EZ Bar Skullcrusher', 'Lie on a bench. Lower the EZ bar toward your forehead by flexing your elbows, keeping upper arms perpendicular to the floor. Extend back up.'),
('5e036adc-04df-4aa9-9af0-262cf299ec1b', '0d2f06b7-43c1-4cb5-8c28-c04cca981208', 'es', 'Rompecráneos con barra Z (Skullcrusher)', 'Acuéstate en un banco. Baja la barra Z hacia tu frente flexionando los codos, manteniendo los brazos perpendiculares al suelo. Extiende de nuevo.'),
('3509430f-d0d0-4e34-9149-64bbf76b4f8e', '0d3657f5-1468-4705-abe5-da4e38025cf5', 'en', 'Double Kettlebell Clean to Sots Press', 'Perform a clean and, while staying in the bottom of the squat, execute a full military press overhead.'),
('e1ea177d-a4f9-49f6-bfc8-7904400bf970', '0d3657f5-1468-4705-abe5-da4e38025cf5', 'es', 'Doble Kettlebell Clean para Sots Press', 'Realiza una cargada y, manteniéndote en la parte baja de la sentadilla, ejecuta un press militar completo sobre la cabeza.'),
('595be8cd-19ff-4fff-9282-53c55a2a2224', '0d3e0e77-b601-42ec-bb28-c799d1bc652c', 'en', 'Double Kettlebell Snatch to Overhead Squat', 'Execute a snatch with two kettlebells and immediately drop into a deep squat while keeping the weights locked out overhead.'),
('9fa1a86b-7de9-48bb-814a-c249cdc56551', '0d3e0e77-b601-42ec-bb28-c799d1bc652c', 'es', 'Arranque doble con pesa rusa hasta sentadilla por encima de la cabeza', 'Ejecuta un snatch con dos Kettlebells y baja inmediatamente a una sentadilla profunda manteniendo el peso bloqueado sobre la cabeza.'),
('5fbef519-798b-4f1a-acb8-eb2eca2bd886', '0d58180f-76e6-4624-9110-0a5689d60289', 'en', 'Cable Rope Face Pull', 'Pull the rope toward the face separating the ends. Shoulder health. Scapular retraction. Do not push your head forward.'),
('a4738f67-8b87-464a-b99a-4616fa12e737', '0d58180f-76e6-4624-9110-0a5689d60289', 'es', 'Face Pull con cuerda', 'Tira de la cuerda hacia la cara separando los extremos. Salud de hombro. Retracción escapular. No adelantes la cabeza.'),
('54a8d8cb-dca9-4819-8f48-f577b3382150', '0d80fe43-a6cc-47d7-8ee2-9a17bb570417', 'en', 'Reverse Barbell Bicep Curl', 'Flex elbows with prone grip (palms down). Objective: brachioradialis and forearms. Cue: keep wrists straight. Common error: using excessive weight that compromises grip.'),
('852315ad-dc1c-44a4-bb8a-609522723020', '0d80fe43-a6cc-47d7-8ee2-9a17bb570417', 'es', 'Curl de bíceps invertido con barra', 'Flexiona los codos con agarre prono (palmas hacia abajo). Objetivo: braquiorradial y antebrazos. Cue: mantén las muñecas rectas. Error común: usar excesivo peso que comprometa el agarre.'),
('3c320f7f-ac50-4bfb-87e9-d5405dc458ee', '0d9aa86b-8747-4f49-93b4-99382528369c', 'en', 'Band Clamshells', 'Lie on your side with knees bent and a band around the knees. Keep feet together and open the upper knee like a clamshell, resisting band tension. Avoid rotating hips backward. Excellent for gluteus medius activation.'),
('c2c23328-9bc1-4974-a78b-2aa7ddd57c4d', '0d9aa86b-8747-4f49-93b4-99382528369c', 'es', 'Clamshells con banda', 'Túmbate de lado con las rodillas flexionadas y una banda alrededor de las rodillas. Mantén los pies juntos y abre la rodilla superior como una almeja, resistiendo la tensión de la banda. Evita rotar la cadera hacia atrás. Excelente para activar el glúteo medio.'),
('ef4be105-8e3e-421f-bf29-afb75457b5d7', '0d9d8764-c4af-43b6-9ea0-a24940632419', 'en', 'Floor-to-Overhead Press', 'Press starting with the bar on the floor, eliminating the eccentric phase. Develops pure concentric strength. Requires flexibility for positioning. Use blocks if necessary. Popular in powerlifting to work on weak points.'),
('0cc741f5-600f-4c3a-962d-c70d9a70459e', '0d9d8764-c4af-43b6-9ea0-a24940632419', 'es', 'Press desde suelo', 'Press iniciando con la barra en el suelo, eliminando la fase excéntrica. Desarrolla fuerza concéntrica pura. Requiere flexibilidad para posicionarse. Usa bloques si es necesario. Popular en powerlifting para trabajar puntos débiles.'),
('d2bebf20-c05a-42ac-8df5-7acf37896fcb', '0db8dae9-f267-4eed-b7ad-74edbde33ef7', 'en', 'Plate Turkish Sit Up', 'Sit up while keeping a plate extended with both arms toward the ceiling, focusing effort on the core and stable shoulders.'),
('642a414b-ab52-4ac1-9680-9cc6b636d9b4', '0db8dae9-f267-4eed-b7ad-74edbde33ef7', 'es', 'Plato Turco Sentarse', 'Sit up manteniendo un disco extendido con ambos brazos hacia el techo, enfocando el esfuerzo en el core y hombros estables.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('63937368-35ec-41df-b5eb-0c1fe1cd7c69', '0dc804ef-2c06-402d-80a2-a1101931ae48', 'en', 'Kneeling Overhead EZ Bar Triceps Extension', 'Kneeling on both legs, lower the EZ bar behind your head by flexing elbows and extend back to the ceiling.'),
('d40ddb89-eb19-49c3-ba0c-f05ad7daa1f5', '0dc804ef-2c06-402d-80a2-a1101931ae48', 'es', 'Extensión de tríceps Overhead arrodillado con barra Z', 'De rodillas sobre ambas piernas, baja la barra Z por detras de tu cabeza flexionando los codos y extiende de nuevo al techo.'),
('7184edfd-146b-4777-baab-f5806b242b1f', '0ddbbd3b-a706-49d0-bc5b-18b8eea4927b', 'es', 'V-roll out', 'Rueda formando un patrón en V, alternando diagonales. Trabaja el core desde múltiples ángulos. Requiere control excepcional y fuerza en los oblicuos. Mantén movimientos simétricos en ambos lados.'),
('6cfc2a45-d92a-48b2-8184-0a3ee302ad06', '0df52446-40fe-495d-ba33-c90acaeaa926', 'en', 'Dumbbell Bulgarian Split Squat on Fitball', 'Perform a Bulgarian split squat by resting the back foot on an unstable Fitball while holding dumbbells at your sides.'),
('4402256d-8084-4d00-8f1b-28241acae0f6', '0df52446-40fe-495d-ba33-c90acaeaa926', 'es', 'Sentadilla Búlgara con mancuernas en Fitball', 'Realiza una sentadilla búlgara apoyando el pie trasero sobre un Fitball inestable mientras sostienes mancuernas a los costados.'),
('053ebf32-fa7c-4534-898b-f3656c3f84b2', '0df750b4-2729-462f-a642-fa4cae98759b', 'en', 'Dumbbell Renegade Row', 'In a plank position with hands on dumbbells, perform an alternating row while maintaining core stability. Avoid hip rotation. Requires significant core and back strength, as well as excellent stabilization.'),
('bdcd217c-5159-430a-9556-0fcefa65c686', '0df750b4-2729-462f-a642-fa4cae98759b', 'es', 'Renegade row mancuernas', 'En posición de plancha con las manos sobre mancuernas, realiza un remo alternando brazos mientras mantienes la estabilidad del core. Evita la rotación de caderas. Requiere fuerza significativa en core y espalda, además de excelente estabilización.'),
('53f7e6c3-e279-4102-a618-ad5f1c2bbd2a', '0df9b2b6-b48d-452c-b15a-13d6e200c65c', 'en', 'Push-Up', 'Perform a push-up while keeping the body aligned from head to heels. Lower the chest under control and push the floor away until the arms are extended.'),
('533faadc-24e6-46cd-ac5f-56c8aef40bd0', '0df9b2b6-b48d-452c-b15a-13d6e200c65c', 'es', 'Flexiones', 'Realiza una flexión manteniendo el cuerpo alineado desde la cabeza hasta los pies. Baja el pecho de forma controlada y empuja el suelo hasta extender los brazos.'),
('30ac805b-c091-48c3-bba5-b0375adf93a4', '0dfe54ed-0712-4095-8c5c-5102f1373d6b', 'es', 'Puente glúteo fitball', 'Eleva cadera con pies en fitball. Objetivo: glúteo/isquios. Cue: aprieta core. Error: bola ruede.'),
('857f2950-4348-4653-ac2a-1617489b5d9b', '0e007610-750f-40cb-b6a8-e5cc8b063242', 'en', 'Barbell Back Rack Step Up', 'Step up onto a bench with the bar on your traps, driving through the front leg to full hip extension.'),
('19d0eb33-9a00-4947-829e-d70b71b1fe34', '0e007610-750f-40cb-b6a8-e5cc8b063242', 'es', 'Step Up con barra tras nuca', 'Sube a un banco con la barra sobre los trapecios, empujando con la pierna delantera hasta la extension completa de cadera.'),
('c6267770-62ba-4fc6-9b46-c46cdcafcc8a', '0e2aff42-e79b-4c7f-b571-ac9f4b754742', 'en', 'Stability Ball Knee Tuck', 'In a plank position with shins on the Fitball, roll the ball forward bringing knees to the chest. Extend legs to return to the plank.'),
('4663b210-1e86-4f69-a10b-308511b71fe3', '0e2aff42-e79b-4c7f-b571-ac9f4b754742', 'es', 'Knee Tuck con Fitball', 'En posición de plancha con las espinillas sobre el Fitball, rueda el balón hacia adelante llevando las rodillas al pecho. Extiende las piernas para volver a la plancha.'),
('addc3c11-ddb4-40e6-9909-6a50c48e2a2e', '0e519696-19c0-4d71-a4c0-7be4425d928c', 'en', 'Ring Archer Row', 'Pull your body up while extending one arm laterally like an archer, shifting the tension onto a single arm.'),
('033ecf09-d670-42f2-9eb6-b86b75d7aac6', '0e519696-19c0-4d71-a4c0-7be4425d928c', 'es', 'Remo arquero en anillas', 'Tira del cuerpo hacia arriba mientras extiendes un brazo lateralmente emulando a un arquero, rotando la tensión hacia un solo brazo.'),
('9a285881-042a-472f-b839-a04e8c7baada', '0e62bf7c-80c9-4520-87f4-a3b76ff780ad', 'en', 'One-Arm Cable Bicep Curl', 'Standing in front of the low pulley. Perform a curl with a single arm keeping the elbow fixed at the side.'),
('7692defe-918a-4e0c-92aa-067b0b657a36', '0e62bf7c-80c9-4520-87f4-a3b76ff780ad', 'es', 'Curl de bíceps a una mano con cable', 'De pie frente a la polea baja. Realiza un curl con un solo brazo manteniendo el codo fijo al costado.'),
('5a9aa673-9b45-4f30-a149-d60842a135ab', '0e7e9f25-efef-4dfb-943e-803972994de3', 'en', 'Wall Sit', 'Rest your back against the wall and lower until your thighs are parallel to the floor and knees are at 90 degrees. Maintain the position.'),
('273b4f42-9fee-4f6e-a31f-50330cb14d25', '0e7e9f25-efef-4dfb-943e-803972994de3', 'es', 'Sentadilla isométrica en pared (Wall Sit)', 'Apoya la espalda en la pared y baja hasta que tus muslos estén paralelos al suelo y las rodillas a 90 grados. Mantén la posición.'),
('752b1240-1382-4119-b3eb-63370e46a954', '0e9c6dd2-1b2e-4f04-8a7a-dafcee6db107', 'en', 'Behind the Neck Barbell Sumo Squat', 'Wide feet with bar on shoulders. Objective: adductor/glute. Cue: knees out. Error: heels in the air.'),
('cc16cd38-f54e-4f87-9994-d7a73a2d029c', '0e9c6dd2-1b2e-4f04-8a7a-dafcee6db107', 'es', 'Sentadilla sumo barra nuca', 'Pies anchos barra hombros. Objetivo: aductor/glúteo. Cue: rodillas fuera. Error: talones aire.'),
('45accb91-ec66-47fb-8c47-97a61abfd8a1', '0ec90d63-beb8-443b-85cf-4be09e898b35', 'en', 'Bosu Push Ups', 'Push-ups with hands on the flat or round side of the Bosu. The unstable surface increases activation of shoulder and core stabilizers. Start with the flat side up for less difficulty. Maintain total control.'),
('d1232b2e-d4be-4426-93ad-8b6ba225d908', '0ec90d63-beb8-443b-85cf-4be09e898b35', 'es', 'Flexiones bosu', 'Flexiones con manos sobre el lado plano o redondo del bosu. La superficie inestable aumenta la activación de estabilizadores del hombro y core. Comienza con el lado plano hacia arriba para menor dificultad. Mantén control total.'),
('6e7f6882-c8ae-4e68-8fec-44dce331a41e', '0ecb99ec-5165-4fcf-b67a-8bde8132becb', 'en', 'Single Arm Kettlebell Sumo Deadlift', 'With a wide stance, lift the kettlebell from the floor with a single hand while keeping a neutral back and an engaged core.'),
('ad7654c0-7da0-4c07-ad8c-dc9992030627', '0ecb99ec-5165-4fcf-b67a-8bde8132becb', 'es', 'Peso muerto Sumo a una mano con Kettlebell', 'Con postura ancha, levanta la Kettlebell del suelo con una sola mano manteniendo la espalda neutra y el core activado.'),
('a6930570-532f-4677-ab9e-c521a4bc261b', '0fa7fe39-4da1-4c26-ad8d-76a6c11b41e4', 'en', 'Bodyweight Archer Push Up', 'Lower your body to one side while straightening the opposite arm laterally, mimicking an archers draw for increased unilateral load.'),
('5958d58a-56e6-441a-bb46-0af907dac351', '0fa7fe39-4da1-4c26-ad8d-76a6c11b41e4', 'es', 'Flexión de arquero', 'Baja el cuerpo hacia un lado mientras estiras el brazo opuesto lateralmente, imitando la apertura de un arco para mayor carga unilateral.'),
('a68e8b72-e120-48a5-be69-a3b2913f5b90', '0ff89d39-d509-461d-82f3-7c50adb30cdd', 'en', 'Negative One-Arm Pull-up', 'Controlled eccentric phase of a pull-up using only one arm. Excellent progression toward a full one-arm pull-up. Start from the top and descend as slowly as possible. Use assistance to get back up. Alternate arms.'),
('2aa94438-1be9-4c17-8870-63de1a66433e', '0ff89d39-d509-461d-82f3-7c50adb30cdd', 'es', 'Dominada a un brazo negativa', 'Fase excéntrica controlada de dominada usando un solo brazo. Excelente progresión hacia dominada completa a un brazo. Comienza desde arriba y desciende lo más lento posible. Usa asistencia para volver arriba. Alterna brazos.'),
('a387a4d6-0d24-4b4e-899e-1445a9430988', '0ffdf7d4-7798-49bc-82a6-64f03e7aa2f3', 'en', 'Ring Hanging Knee Raise', 'Hang from the rings with arms straight. Contract your abdomen and lift your knees toward your chest in a controlled manner. Lower legs slowly to avoid swinging.'),
('3bc5e0bd-db22-4759-860a-4087c24e7a11', '0ffdf7d4-7798-49bc-82a6-64f03e7aa2f3', 'es', 'Elevación de rodillas colgado en anillas', 'Cuélgate de las anillas con los brazos estirados. Contrae el abdomen y levanta las rodillas hacia el pecho de forma controlada. Baja las piernas lentamente evitando balancearte.'),
('13b1a12b-d16b-4acc-8371-62dc48a32dde', '1007a5b7-f088-496b-bf2c-b99ec783e4a8', 'en', 'Double Bottoms Up Kettlebell Cyclist Thruster', 'Hold two kettlebells inverted in rack position, descend into a cyclist squat and push both toward the ceiling, maintaining weight balance.'),
('c0ef784e-276f-4d35-8c96-352cef796868', '1007a5b7-f088-496b-bf2c-b99ec783e4a8', 'es', 'Thruster Ciclista con Kettlebell doble Bottoms Up', 'Sujeta dos Kettlebells invertidas en posicion rack, baja en sentadilla ciclista y empuja ambas hacia el techo, manteniendo el equilibrio del peso.'),
('27e286ed-04e2-464c-9d15-a0dc884f4cb8', '1009949c-12c6-4081-a5dd-229c510e428a', 'en', 'Cable crossover', 'Classic cable crossover exercise from high pulleys. Lean slightly forward and bring hands together in front of the chest or abdomen with a hugging motion. Constant cable tension maximizes pectoral work.'),
('cce72f5d-65c7-4d74-8d78-25a6195b2078', '1009949c-12c6-4081-a5dd-229c510e428a', 'es', 'Cable crossover', 'Ejercicio clásico de cruces de cables desde poleas altas. Inclínate ligeramente hacia adelante y junta las manos frente al pecho o abdomen con un movimiento de abrazo. La tensión constante del cable maximiza el trabajo del pectoral.'),
('471b345e-f2c4-4767-bd9b-473deb391bc4', '102ae941-ade5-420e-8630-615e5ed431dc', 'en', 'Dumbbell Sumo Squat (Hands Down)', 'Wide feet, hold two weights down. Cue: high chest. Error: rounding lumbar back.'),
('f66ae611-1c0e-494b-b6d8-2eddd94044cf', '102ae941-ade5-420e-8630-615e5ed431dc', 'es', 'Sentadilla sumo mancuernas manos abajo', 'Pies anchos, sujeta dos pesas abajo. Cue: pecho alto. Error: redondear lumbar.'),
('e8e63a13-f65f-46f3-9459-1a263ceceb6d', '1038df6a-f4f3-47cb-8e70-01860d9d49e9', 'en', 'Machine Bicep Curl', 'Seated with arms supported, perform elbow flexions. The machine stabilizes the movement allowing maximum bicep isolation. Some versions allow unilateral work. Especially control the negative phase.'),
('65292db6-91d4-4e4e-b513-0c9abf2b000f', '1038df6a-f4f3-47cb-8e70-01860d9d49e9', 'es', 'Curl bíceps máquina', 'Sentado con los brazos apoyados, realiza flexiones de codo. La máquina estabiliza el movimiento permitiendo máximo aislamiento del bíceps. Algunas versiones permiten trabajo unilateral. Controla especialmente la fase negativa.'),
('eb6fc387-2f73-497c-b0a9-7cf85a1e1da9', '103ef22a-2063-45ae-b93e-5258908e36ef', 'en', 'Dumbbell Power Jump', 'Jump vertically while holding dumbbells at your sides. Increases load in the stretch-shortening cycle. Cue: land with flexed knees. Common error: swinging the weights excessively.'),
('d8b67e3c-ce6f-4518-88bf-466973622543', '103ef22a-2063-45ae-b93e-5258908e36ef', 'es', 'Salto de potencia con mancuernas', 'Salta verticalmente sosteniendo mancuernas a los lados. Aumenta la carga en el ciclo de estiramiento. Cue: aterriza con rodillas flexionadas. Error común: balancear las pesas en exceso.'),
('ff492c92-4e6b-472a-96aa-6a3e789386fc', '10620311-a9c3-46c1-8940-52a4b2da45b8', 'en', 'Continuous Frog Jump', 'Chain frog jumps without pause, minimizing ground contact time. Plyometric endurance. Cue: maintain a fluid rhythm. Common error: stopping completely between jumps.'),
('3a195f0e-be9d-4977-a54f-effab9cc5468', '10620311-a9c3-46c1-8940-52a4b2da45b8', 'es', 'Salto de rana continuo', 'Encadena saltos de rana sin pausa, minimizando el tiempo en el suelo. Resistencia pliométrica. Cue: mantén el ritmo fluido. Error común: detenerse por completo entre saltos.'),
('ce86ddee-8415-4c48-8d02-cce9d6a2da94', '10686e87-54b2-43dc-98b2-3ef17a23ad41', 'en', 'Incline Dumbbell Flyes', 'Bench at 30-45 degrees, open arms laterally and close seeking upper stimulation. Cue: elbows slightly bent. Error: lowering too much, stretching the shoulder.'),
('2ecee18e-c76b-496c-b127-180f26ed5e76', '10686e87-54b2-43dc-98b2-3ef17a23ad41', 'es', 'Aperturas inclinadas con mancuernas', 'Banco a 30-45 grados, abre brazos lateralmente y cierra buscando el estímulo superior. Cue: codos semiflexionados. Error: bajar demasiado estirando el hombro.'),
('58dcf3d7-d369-4955-9e69-7ca75876e22f', '10703ccc-1202-4fee-9027-4cd34cd8ec18', 'es', 'Wall Squat fitball', 'Sentadilla con bola en pared. Objetivo: técnica cuádriceps. Cue: rodilla-pie alineados. Error: despegar talón.'),
('73774fff-4c24-4533-8773-0b8ac599c431', '10b2caf5-50b1-4b4f-8480-a87c2b068a30', 'en', 'Incline Hammer Curl', 'Seated on an incline bench, perform hammer curls. Objective: brachialis and long head. Cue: elbows toward the floor always. Common error: swinging the shoulder to assist.'),
('327cf7f2-2fda-4c8c-92c1-b07167926639', '10b2caf5-50b1-4b4f-8480-a87c2b068a30', 'es', 'Curl martillo inclinado', 'Sentado en banco inclinado, realiza curl martillo. Objetivo: braquial y cabeza larga. Cue: codos hacia el suelo siempre. Error común: balancear el hombro para ayudar.'),
('b9d5b388-c739-4651-9b53-0857df99f4cc', '10b9cf7e-f3ae-44c0-ab6d-54c14058bbbf', 'en', 'One-Arm Kneeling Low Row', 'In a half-kneeling position facing a low pulley, pull the cable toward the hip keeping the back straight and the core active.'),
('63d396d2-5794-4244-b747-9185378bfca6', '10b9cf7e-f3ae-44c0-ab6d-54c14058bbbf', 'es', 'Remo bajo a una mano de rodillas', 'En posición de caballero frente a una polea baja, tira del cable hacia la cadera manteniendo la espalda recta y el core activo.'),
('6b921f51-8ced-4431-ba07-9ec8497cd40d', '10ba1ef7-10bd-4c22-8ca7-b8c6f2478cd2', 'es', 'TRX Remo a una mano', 'Realiza remo inclinado usando solo un agarre. Evita la rotación del tronco. Core muy firme. Espalda neutra. No des tirones con el hombro.'),
('9b0b498d-509f-45e5-b253-b18d6933820a', '10c1996f-056a-4e2b-ba1b-154f93f5737f', 'en', 'Overhead Slam', 'Similar to the slam ball but emphasizing full overhead extension before the hit. Involves the lats more and provides greater range of motion. Use the whole body to generate maximum power.'),
('e997d90b-18c4-4803-8ffd-f189d0dbf6d7', '10c1996f-056a-4e2b-ba1b-154f93f5737f', 'es', 'Overhead slam', 'Similar al slam ball pero enfatizando la extensión completa sobre la cabeza antes del golpe. Involucra más los dorsales y proporciona mayor rango de movimiento. Usa todo el cuerpo para generar máxima potencia.'),
('bcd7593a-8bf4-4b5c-9874-8f823d27aba9', '10d7f6a5-37c5-400b-b2ef-09edc9885138', 'en', 'Bosu Unstable Squat', 'Perform squats on the hemispherical part of the Bosu. Ankle stability. Knees aligned. Do not look at the ground.'),
('005eaf67-130e-46c3-b1ab-757309f39044', '10d7f6a5-37c5-400b-b2ef-09edc9885138', 'es', 'Bosu sentadilla inestable', 'Realiza sentadillas sobre la parte semiesférica del bosu. Estabilidad de tobillo. Rodillas alineadas. No mires al suelo.'),
('03babbb7-23e6-4c62-bc52-98e56e0295e2', '10f0d2aa-5f5a-40ad-a810-1f5b01303406', 'en', 'Quadruped Hip Extension', 'On all fours, kick one leg toward the ceiling keeping the knee bent at 90 degrees. Squeeze the glute at the top.'),
('bc5aa02a-751a-46a1-a1e3-ba9ccc359db5', '10f0d2aa-5f5a-40ad-a810-1f5b01303406', 'es', 'Extensión de cadera en cuadrupedia', 'En posición de cuatro puntos, patea una pierna hacia el techo manteniendo la rodilla doblada a 90 grados. Aprieta el glúteo en el tope.'),
('224a40da-9919-4eec-9a82-3a1f9da71ea0', '1116c039-12f4-4943-802a-03200c4b1c1f', 'es', 'Upright row barra', 'Con la barra frente a los muslos y agarre cerrado o medio, tira verticalmente llevando los codos hacia arriba y afuera hasta que la barra llegue al nivel del pecho. Mantén la barra cerca del cuerpo. Ten cuidado con este ejercicio si tienes problemas de hombro.'),
('4cb368db-44b7-4ba4-8ebc-f0bcbd53b8db', '11257b14-1e6f-444b-b96d-e05f28022ef3', 'en', 'Straight Bar Bicep Curl', 'Flex elbows holding the bar with palms up. Objective: general bicep mass. Cues: elbows fixed to torso. Common error: moving shoulders forward when lifting.'),
('29e1f8f3-0889-4474-acbf-6842b054af54', '11257b14-1e6f-444b-b96d-e05f28022ef3', 'es', 'Curl de bíceps con barra recta', 'Flexiona los codos sujetando la barra con palmas arriba. Objetivo: masa general del bíceps. Cues: codos fijos al torso. Error común: mover los hombros hacia adelante al subir.'),
('7c0ca73e-d895-48ae-856f-d6f8e8a521b9', '114b9e2e-9a4a-48df-9143-f932d44f7032', 'en', 'Lateral Plyometric Push Up', 'Jump laterally with your hands on each push-up to move sideways. Cue: hands-core coordination. Common error: hips sagging during displacement.'),
('ed449c59-0b34-4341-a2a7-3e00984e24a1', '114b9e2e-9a4a-48df-9143-f932d44f7032', 'es', 'Flexión pliométrica lateral', 'Salta lateralmente con las manos en cada flexión para avanzar de lado. Cue: coordinación manos-core. Error común: que la cadera se hunda durante el desplazamiento.'),
('913cf5cf-bdeb-43e2-9e9e-ad86262117d6', '114bb31c-9bd3-499a-91fb-677828361bc7', 'en', 'Alternating Double Dumbbell Incline Bench Prone Row', 'Lying face down on an incline bench, row the dumbbells alternatively toward your hip to isolate lat work.'),
('585886b1-f5ff-4cab-8e3b-14ae95a60e30', '114bb31c-9bd3-499a-91fb-677828361bc7', 'es', 'Remo prono alterno en banco inclinado con mancuernas', 'Tumbado boca abajo en banco inclinado, rema las mancuernas alternativamente hacia tu cadera para aislar el trabajo dorsal.'),
('683fdc89-173a-4a8a-b05d-d9b5ca9e7091', '1164c727-b755-4879-b114-1912e7e8ffd7', 'en', 'Double Dumbbell Triceps Kickback', 'Extend both arms back while leaning. Cue: high elbows. Error: swinging weights.'),
('f32ecdcb-29ca-47ed-afa6-3288868aa695', '1164c727-b755-4879-b114-1912e7e8ffd7', 'es', 'Patada tríceps mancuernas ambas', 'Extiende ambos brazos atrás inclinado. Cue: codos altos. Error: balancear pesas.'),
('5e139591-4234-4dbf-9e32-0a5aea00a20d', '117adcd1-08b2-47e8-aafa-8b7b1146725f', 'en', 'Double Kettlebell Snatch to Overhead Alternating Reverse Lunge', 'Drive two kettlebells overhead and perform alternating lunges while keeping the arms locked out at all times.'),
('ab7bc602-e434-4fdb-ac9e-6f1ca48c5e43', '117adcd1-08b2-47e8-aafa-8b7b1146725f', 'es', 'Snatch doble a Zancada inversa alterna Overhead con Kettlebell', 'Lanza dos Kettlebells sobre la cabeza y realiza zancadas alternas manteniendo los brazos bloqueados en todo momento.'),
('fad95f02-12fb-4f32-8fb3-7c69ad1322f0', '117d9e0e-0b9d-4f5f-8170-470654fe3d55', 'en', 'V-Bar Triceps Extension', 'Push the bar down locking elbows. Stability. Straight back. Do not separate elbows from the body.'),
('28309d25-c4fb-4ed7-80a8-8c7372d62be5', '117d9e0e-0b9d-4f5f-8170-470654fe3d55', 'es', 'Extensión de tríceps con barra V', 'Empuja la barra hacia abajo bloqueando codos. Estabilidad. Espalda recta. No separes los codos del cuerpo.'),
('9758d47c-c3fc-4eef-a7e4-a7492c2cf9c0', '11868777-afbb-4b25-ac2d-f5163c4f4d66', 'en', 'LaLanne Push Ups', 'Push-ups with arms extended far in front of the body. Named after Jack LaLanne. The extreme lever arm makes them incredibly difficult. Progress by gradually increasing hand distance.'),
('16bb8d93-60f8-42b6-b7e1-2d570121b8cb', '11868777-afbb-4b25-ac2d-f5163c4f4d66', 'es', 'Flexiones lalanne', 'Flexiones con brazos extendidos muy por delante del cuerpo. Nombradas por Jack LaLanne. El brazo de palanca extremo las hace increíblemente difíciles. Progresa aumentando gradualmente la distancia de las manos.'),
('52cdaf1a-8582-49d7-ac88-b0259781696f', '12026ad3-4717-4d6f-bf3d-96dc0c315e9c', 'en', 'Handstand walk', 'Walk on your hands while maintaining inverted balance. Requires shoulder strength, core control, and exceptional coordination. Start with small steps near a wall. Progress by increasing distance and speed.'),
('24bf8ce6-84c6-4e65-9eb6-89c483344d82', '12026ad3-4717-4d6f-bf3d-96dc0c315e9c', 'es', 'Caminata en parada de manos', 'Camina sobre las manos manteniendo el equilibrio invertido. Requiere fuerza en hombros, control del core y coordinación excepcional. Comienza con pasos pequeños cerca de una pared. Progresa aumentando distancia y velocidad.'),
('173decec-756c-4d93-843f-df74ad9d1b0b', '124249bd-29bb-48aa-8416-0556d576e454', 'en', 'Box Pistol Squat', 'Perform a single-leg squat lowering in a controlled manner until lightly sitting on a box or bench, and rise again with the same leg.'),
('dadb0611-715f-4d86-98c1-e4213e23c458', '124249bd-29bb-48aa-8416-0556d576e454', 'es', 'Sentadilla Pistola a cajón', 'Realiza una sentadilla a una pierna bajando de forma controlada hasta sentarte ligeramente en un cajón o banco, y vuelve a subir con la misma pierna.'),
('b75d5139-d15a-406a-b97e-24a28638db4b', '1245502f-1417-40f1-8d37-117abc7d197d', 'en', 'Bounds', 'Jump forward seeking maximum flight time with each stride. Explosive hip drive. Coordinated arms. Do not land with a stiff leg.'),
('45f9197b-4350-4ce0-84e9-eebb2e47d001', '1245502f-1417-40f1-8d37-117abc7d197d', 'es', 'Saltos de potencia (Bounds)', 'Salta hacia adelante buscando el máximo tiempo de vuelo en cada zancada. Impulso explosivo de cadera. Brazos coordinados. No aterrices con la pierna rígida.'),
('e93ab1b3-a023-4c53-ac92-b253681bcd3d', '128ad98b-9ef6-4eb9-9c33-442b42e6c7a5', 'en', 'Seated Barbell Good Mornings', 'Seated on a bench with the barbell on your shoulders, lean the torso forward keeping the back straight until parallel to the floor.'),
('5f0b15fa-2e10-41a0-9596-e48c8daa2573', '128ad98b-9ef6-4eb9-9c33-442b42e6c7a5', 'es', 'Buenos días sentado con barra', 'Sentado en un banco con la barra en los hombros, inclina el torso hacia adelante manteniendo la espalda recta hasta quedar paralelo al suelo.'),
('22cc6227-8673-461d-9a45-13dae548ba83', '12908de9-6fa9-4abf-8c73-82755dd20d3e', 'es', 'Zancada caminando con mancuernas (Maleta)', 'Camina dando pasos largos mientras sostienes una mancuerna en cada mano a los costados del cuerpo, manteniendo el torso erguido y las rodillas a 90 grados.'),
('f12076f4-2dbb-4ee5-8ead-8c8cf0663b5f', '1298c0e1-8732-4af0-9877-f786680b6fe7', 'en', 'Double Kettlebell Front Rack Walking Lunge', 'Hold two kettlebells in the front rack position and perform walking lunges, keeping your elbows up and your core very stable.'),
('b57dd252-c8bf-4689-8d72-420dddbb5c79', '1298c0e1-8732-4af0-9877-f786680b6fe7', 'es', 'Zancada caminando Front Rack con Kettlebell doble', 'Sostén dos Kettlebells en posición de rack sobre el pecho y camina realizando zancadas, manteniendo los codos arriba y el core muy estable.'),
('bfe53ed8-3504-430f-bcea-5cc64b45b351', '129ffc3a-9198-4cc9-9049-286e5939e8a9', 'en', 'Pseudo Planche Push Ups', 'Push-ups with hands positioned further back, near the hips, leaning the body forward. Simulates the planche position. Excellent progression toward the full planche. Gradually increase the forward lean.'),
('1a113f42-3f6f-465f-98b3-c6063a024175', '129ffc3a-9198-4cc9-9049-286e5939e8a9', 'es', 'Flexiones pseudo planche', 'Flexiones con manos posicionadas más atrás, cerca de las caderas, inclinando el cuerpo hacia adelante. Simula la posición del planche. Excelente progresión hacia el planche completo. Aumenta gradualmente la inclinación hacia adelante.'),
('56d5f3d8-7c23-49df-9f08-ddc5c54277b0', '12a24c7d-f7b3-4970-89cc-d4274ce53fa1', 'en', 'Single Leg Hip Thrust', 'Unilateral barbell hip thrust. Extremely challenging for the glute and stabilization. Start with body weight and progress. Keep the pelvis level throughout the movement. Alternate legs.'),
('e0371f46-b1b8-46bf-a962-4c803fe09da2', '12a24c7d-f7b3-4970-89cc-d4274ce53fa1', 'es', 'Empuje cadera una pierna', 'Hip thrust unilateral con barra. Extremadamente desafiante para el glúteo y la estabilización. Comienza con peso corporal y progresa. Mantén la pelvis nivelada durante todo el movimiento. Alterna piernas.'),
('f18f832c-74b5-433d-b54a-eaa308691549', '130ab53a-f0e6-43e4-b097-0812346f932d', 'en', 'Barbell Hip Thrust', 'Back on bench, bar on hip, raise pelvis until parallel to the floor. Cue: chin to chest, squeeze glute. Error: arching lumbar at top.'),
('b6ea5d07-bf93-452e-b745-e582baab34a7', '130ab53a-f0e6-43e4-b097-0812346f932d', 'es', 'Hip Thrust con barra', 'Espalda en banco, barra en cadera, eleva pelvis hasta quedar paralelo al suelo. Cue: barbilla al pecho, aprieta glúteo. Error: arquear lumbar arriba.'),
('e99aedc1-88c4-45e7-8c67-8f3be8a6e5f0', '130dfd53-8627-4d94-8dcf-d7ac87b1be95', 'en', 'Kneeling Diamond Push Ups', 'Push-up with hands forming a diamond under the chest and knees supported. Objective: intro to triceps strength. Cue: elbows close to the body. Common error: arching lower back.'),
('1c246fd6-57e8-4adc-9c2a-4175970651bc', '130dfd53-8627-4d94-8dcf-d7ac87b1be95', 'es', 'Flexiones diamante con rodillas', 'Flexión con manos formando un diamante bajo el pecho y rodillas apoyadas. Objetivo: iniciación fuerza tríceps. Cue: codos pegados al cuerpo. Error común: arquear la espalda lumbar.'),
('95e706d5-0d4f-4959-aa63-944cb9659853', '132b44dc-a452-474f-99e0-40bbbbbb5740', 'en', 'Bird dog', 'In a quadruped position, simultaneously extend the right arm forward and the left leg backward, forming a straight line. Hold the position without rotating the hips and return in a controlled manner. Alternate with the other side. Excellent for core stability and coordination.'),
('66897639-9f41-4680-a0a5-16eda343c2e4', '132b44dc-a452-474f-99e0-40bbbbbb5740', 'es', 'Bird dog', 'En posición de cuadrupedia, extiende simultáneamente el brazo derecho al frente y la pierna izquierda hacia atrás, formando una línea recta. Mantén la posición sin rotar las caderas y vuelve controladamente. Alterna con el otro lado. Excelente para la estabilidad del core y coordinación.'),
('9f21a0d5-1a53-435e-b395-80a95d4c5b3a', '1347f6e3-5bff-4cfc-9cd7-59f62e9b13e7', 'en', 'Barbell Back Box Squat', 'Lower into a squat with the bar behind the neck until glutes lightly touch the box, perform a minimal pause, and rise again.'),
('e937e869-62a6-4361-a197-ef631f52fa53', '1347f6e3-5bff-4cfc-9cd7-59f62e9b13e7', 'es', 'Sentadilla trasera a cajón con barra', 'Baja en sentadilla con la barra tras la nuca hasta que los glúteos toquen el cajón, haz una pausa mínima y vuelve a subir.'),
('f25d1945-b515-44bc-8a1f-033f10da04cf', '13639b4a-b636-40d8-9a32-77eb1dd2b043', 'en', 'Barbell Low Bar Cyclist Squat', 'Execute a squat with heels elevated resting the bar on the rear delts to emphasize the vertical drive of the quadriceps.'),
('d3ac4476-b1b3-425e-9123-3809bec4c877', '13639b4a-b636-40d8-9a32-77eb1dd2b043', 'es', 'Sentadilla Ciclista con barra baja', 'Ejecuta una sentadilla con talones elevados apoyando la barra sobre los deltoides posteriores para enfatizar el empuje vertical de los cuádriceps.'),
('09e113df-49b4-46d7-b2c4-3524a0602ff3', '136e573d-dc95-4b81-98bb-9bff98fdcdc6', 'en', 'Superband Tall Kneeling Pallof Press', 'Kneeling on both knees, hold the band in front of your chest and extend it forward while resisting the lateral pull of the band.'),
('d8f44a31-75e4-44c9-84d2-89ced3b180c6', '136e573d-dc95-4b81-98bb-9bff98fdcdc6', 'es', 'Press Pallof arrodillado con banda elástica', 'Arrodillado sobre ambas rodillas, sujeta la banda frente al pecho y extiendela hacia adelante resistiendo la traccion lateral de la banda.'),
('3b948295-c8d3-4ce5-ba82-a28e504a24ea', '13d05b40-641e-4a1e-bfb3-e41bc8853082', 'en', 'Barbell Seated Reverse Grip Wrist Curl', 'Rest your forearms on your thighs with palms up and flex your wrists to lift the loaded bar toward you.'),
('62319c1d-cc64-4a44-bc42-549213315d48', '13d05b40-641e-4a1e-bfb3-e41bc8853082', 'es', 'Curl de muñeca con agarre inverso Sentado con barra', 'Apoya los antebrazos en los muslos con las palmas hacia arriba y flexiona las muñecas para elevar la barra cargada hacia ti.'),
('722d0b0c-96b7-4e70-b720-e1c02ffeb240', '140bda7e-0f85-4064-b86e-edcd61382b92', 'en', 'Smith Machine Hamstring RDL', 'Guided Romanian deadlift. Cue: hips back. Error: arching the back.'),
('9c820020-f2ec-4228-83f6-105325b02353', '140bda7e-0f85-4064-b86e-edcd61382b92', 'es', 'RDL máquina Smith isquios', 'Peso muerto rumano guiado. Cue: cadera atrás. Error: curvar espalda.'),
('0819255b-c62e-4c55-8089-8fe926050754', '144676aa-94da-4bca-b28a-c8d7b519186a', 'en', 'Parallel Bar Dips (Chest)', 'Lower by leaning the torso forward. Objective: lower pectoral. Cues: stable shoulders. Common error: shrugging shoulders.'),
('6c2d111d-8dda-40af-b7e3-7eaaab1d1db9', '144676aa-94da-4bca-b28a-c8d7b519186a', 'es', 'Fondos en paralelas (Pecho)', 'Baja inclinando el torso adelante. Objetivo: pectoral inferior. Cues: hombros estables. Error común: encoger hombros.'),
('d76ec220-bb1b-436f-8bde-3e115d711b2e', '144844dd-7852-4680-a4b5-0f19a79ce00a', 'en', 'Hanging Inverted Oblique Crunch', 'Hanging upside down, perform an abdominal flexion bringing one shoulder toward the opposite hip to emphasize oblique work.'),
('9a97b6d4-1c68-4095-93d8-965c0d38909b', '144844dd-7852-4680-a4b5-0f19a79ce00a', 'es', 'Crunch oblicuo invertido colgado', 'Colgado boca abajo, realiza una flexión abdominal llevando un hombro hacia la cadera opuesta para enfatizar el trabajo de los oblicuos.'),
('00465ee4-44b5-4c25-ba24-3c738d01274b', '14a70633-eb2b-4e18-91dc-511da0abf65b', 'es', 'Press anti-rotación cable', 'De lado al cable, extiende los brazos al frente resistiendo la rotación. Variación avanzada del Pallof press. Puedes añadir movimientos: caminar, sentadillas, etc., manteniendo la resistencia anti-rotación.'),
('e1b9f14e-5d44-4334-acbc-21ae7a95d83a', '14d06d40-d2af-45bd-9ec6-6614087b725a', 'en', 'Fitball Dumbbell W-Raise', 'Face down on the Fitball, lift arms bent forming a W, squeezing the shoulder blades and external rotators.'),
('ec4e9cf9-3026-4376-9da0-8d0d809ac1af', '14d06d40-d2af-45bd-9ec6-6614087b725a', 'es', 'Elevación W con mancuernas en Fitball', 'Boca abajo sobre el Fitball, levanta los brazos doblados formando una W, apretando los omóplatos y rotadores externos.'),
('5f3abaff-4714-46db-aa9c-45a9898faf00', '14f9a69f-13ab-476f-ada3-fee060f9b8fa', 'en', 'Alternating Single Arm Kettlebell Plank Pull Through', 'In a high plank position, pull a kettlebell under your torso from one side to the other, alternating the pulling arm.'),
('6f4abfba-af23-4f79-a73b-9b3000062cf3', '14f9a69f-13ab-476f-ada3-fee060f9b8fa', 'es', 'Plank con arrastre de Kettlebell alterno', 'En posición de plancha alta, arrastra una Kettlebell por debajo del torso de un lado al otro alternando el brazo que tracciona.'),
('53823fb8-75d4-428b-b9eb-f5c27148b039', '15189672-c417-44c1-a700-cdec3a95067d', 'en', 'Miniband Fire Hydrant', 'On all fours with a band above the knees, lift one leg laterally while keeping the knee bent, like a dog. Lower while controlling the resistance.'),
('03d4712b-77ee-4553-b5dd-53d4ba692269', '15189672-c417-44c1-a700-cdec3a95067d', 'es', 'Fire Hydrant con banda elástica', 'En cuadrupedia con una banda sobre las rodillas, levanta una pierna lateralmente manteniendo la rodilla doblada, como un perro. Baja controlando la resistencia.'),
('0046cc31-16c6-4159-9fa7-328ec4eef998', '151e08e3-7971-4ae1-b069-86cb3e92d270', 'en', 'Single Arm Kettlebell Turkish Sit Up', 'Lie on your back with one arm extended holding a kettlebell and perform a sit up keeping the load vertical at all times.'),
('6340dae1-efbe-4580-9c4e-7229e008ee7f', '151e08e3-7971-4ae1-b069-86cb3e92d270', 'es', 'Turkish Sit Up con Kettlebell a una mano', 'Acuéstate boca arriba con un brazo extendido sosteniendo una Kettlebell y realiza un sit up manteniendo la carga vertical en todo momento.'),
('6a62d771-2b1d-46bd-85e9-961692549018', '15362bd7-d794-44b2-82ae-e683aa53ecb7', 'es', 'Zancada inversa Goblet con Kettlebell y Slider', 'Sostén la pesa rusa en copa (frente al pecho) y desliza una pierna hacia atrás en un slider hasta que la rodilla casi toque el suelo.'),
('50b536cd-c68e-4381-9d51-9d3d42eea47a', '154f3687-0373-48a4-9e8b-f60537e3e8b0', 'en', 'Barbell Overhead Toe Balance Squat', 'Perform a deep squat while balancing on the balls of the feet with the barbell loaded overhead.'),
('909d4868-c08e-46f4-9a7e-787411b9b015', '154f3687-0373-48a4-9e8b-f60537e3e8b0', 'es', 'Sentadilla Overhead en equilibrio sobre dedos con barra', 'Realiza una sentadilla profunda manteniendo el equilibrio sobre las puntas de los pies y la barra cargada sobre la cabeza.'),
('ad604324-fa60-4634-afca-37cc01c1b3a2', '156693e3-0854-4ccb-9cef-33f4aa2d50c2', 'en', 'One-Leg Barbell Hip Thrust', 'Perform a barbell Hip Thrust but using only one supporting leg, keeping the bar balanced and the hip level.'),
('ea69d39c-7464-4b10-a21d-f663a6ac47b0', '156693e3-0854-4ccb-9cef-33f4aa2d50c2', 'es', 'Hip Thrust a una pierna con barra', 'Realiza un Hip Thrust con barra pero usando solo una pierna de apoyo, manteniendo la barra equilibrada y la cadera nivelada.'),
('7fc68b29-902c-4a12-bb9f-0c2d68eaf2ea', '156ffa33-d47f-4e05-85ee-548db1749ed0', 'en', 'Double Kettlebell Front Rack Bulgarian Split Squat', 'Perform a split squat with your rear foot elevated on a bench and two kettlebells in the front rack position on your chest.'),
('8c76f8c5-0a65-4ef3-b147-72ad66f6e171', '156ffa33-d47f-4e05-85ee-548db1749ed0', 'es', 'Sentadilla Búlgara Front Rack con Kettlebell doble', 'Realiza una sentadilla split con el pie trasero elevado en un banco y dos Kettlebells en posición de rack sobre el pecho.'),
('c2454fad-b43c-4d5c-8a81-193def49cf1b', '157dd472-27bc-45c2-9a08-867fe97ae65b', 'en', 'Fast Scissor Jumps', 'Change foot positions front to back with small, fast jumps. Improves stride frequency. Straight back. Do not lean forward.'),
('ad98849d-5aef-4552-bd6c-88b5f41a7398', '157dd472-27bc-45c2-9a08-867fe97ae65b', 'es', 'Saltos de tijera rápidos', 'Cambia la posición de los pies adelante y atrás con saltos pequeños y veloces. Mejora la frecuencia de zancada. Espalda recta. No te inclines hacia adelante.'),
('10351dc8-1c17-4bbd-b689-3c8e15a36e1b', '15caca70-b07d-47a3-962e-bc9d02bb228c', 'en', 'Front Squat (Clean Grip)', 'Bar over front deltoids, elbows high and parallel to the floor, lower into a squat. Objective: quadriceps with vertical torso. Cues: push elbows upward. Common error: letting elbows drop, causing the bar to roll.'),
('94c31381-8ff6-4e30-b5ff-1095c8a7e3ae', '15caca70-b07d-47a3-962e-bc9d02bb228c', 'es', 'Sentadilla frontal agarre Clean', 'Barra sobre deltoides frontales, codos altos y paralelos al suelo, baja en sentadilla. Objetivo: cuádriceps con torso vertical. Cues: empuja codos hacia arriba. Error común: dejar caer los codos, haciendo que la barra ruede.'),
('9188556a-d9c9-4c7c-97c7-d576e71e5021', '15ce37f0-4b41-4c24-9108-babe751033b6', 'en', 'One-Arm Kneeling Band Cuban Press', 'Kneeling, use an elastic band to perform the sequence: upright row, external rotation, and overhead press.'),
('8dcc0f4a-3855-431d-8a89-3d2b71d5651d', '15ce37f0-4b41-4c24-9108-babe751033b6', 'es', 'Press Cubano de rodillas con banda a una mano', 'De rodillas, usa una banda elástica para realizar la secuencia: remo vertical, rotación externa y press sobre la cabeza.'),
('b9391e80-b6d9-42eb-88e8-c17428549863', '15e5a8b0-583a-4ff5-9eed-b5f763b5a308', 'es', 'Puente de glúteo isométrica', 'Eleva la cadera y mantén la posición máxima arriba apretando los glúteos. Objetivo: resistencia posterior. Cue: empuja fuerte con los talones. Error: hiperextender la zona lumbar en lugar de usar glúteo.'),
('bedf9720-e57f-4265-bd18-868d5b11695c', '15ec8464-fff7-4865-941c-e1d6c5c13811', 'en', 'Single Arm Dumbbell Tall Kneeling Overhead Press', 'Kneeling on both legs, perform a single-arm shoulder press, resisting the tendency of the torso to tilt.'),
('37033eb0-efcd-42f4-9ccc-9189b2113a5a', '15ec8464-fff7-4865-941c-e1d6c5c13811', 'es', 'Press Overhead arrodillado a una mano con mancuerna', 'De rodillas sobre ambas piernas, realiza un press de hombro con un solo brazo, resistiendo la tendencia del torso a inclinarse.'),
('82b883af-72c6-4df8-95ad-687932602378', '1613d81b-58ba-4820-87cb-9b0a016f627f', 'en', 'Neutral-to-Prone Grip Dumbbell Bench Press', 'Rotate weights from neutral to prone as you rise. Cue: total control. Error: instability at the top.'),
('26294e09-2058-4e83-99da-a144fed41ce3', '1613d81b-58ba-4820-87cb-9b0a016f627f', 'es', 'Press banca mancuernas giro neutro-prono', 'Gira pesas al subir de neutro a prono. Cue: control total. Error: inestabilidad arriba.'),
('91f2a0ad-a358-44a9-ba61-811016c83219', '1633ee9d-5025-47fe-a98a-7dd375b0e198', 'en', 'Kneeling Fitball Rollout', 'Kneeling, place forearms on the Fitball. Roll the ball forward extending the body without letting the hips sag, and use the abdomen to return.'),
('45c80617-9d49-4d88-b708-5071404a3170', '1633ee9d-5025-47fe-a98a-7dd375b0e198', 'es', 'Rollout de rodillas con Fitball', 'De rodillas, coloca los antebrazos sobre el Fitball. Rueda el balón hacia adelante extendiendo el cuerpo sin dejar caer la cadera, y usa el abdomen para regresar.'),
('d5198ec7-7c87-4131-b90b-e8d6f167dd12', '1635b7f2-f4a1-45d4-b09b-4e0c50502f3c', 'en', 'Side Lying Hip Abduction with Miniband (Ankles)', 'Lie on your side with a band on your ankles and straight legs. Lift the upper leg laterally against the resistance of the band.'),
('fb4b4304-0325-40ea-a7d9-227b38ba57c2', '1635b7f2-f4a1-45d4-b09b-4e0c50502f3c', 'es', 'Abducción de cadera lateral con Miniband (Tobillos)', 'Acuéstate de lado con una banda en los tobillos y piernas rectas. Levanta la pierna superior lateralmente contra la resistencia de la banda.'),
('52096503-90ad-47e3-af98-3bd0b45922b7', '164d6ab5-e866-4b50-aa41-555839d598cc', 'en', 'Bar Full Front Lever Pull Up', 'Perform pull-ups while keeping the body fully extended and parallel to the floor facing up while hanging from the fixed bar.'),
('789fbb3d-2748-424d-ac31-468b5b59be0b', '164d6ab5-e866-4b50-aa41-555839d598cc', 'es', 'Full Front Lever Pull Up en barra', 'Realiza dominadas manteniendo el cuerpo completamente estirado y paralelo al suelo boca arriba colgado de la barra fija.'),
('880f412c-3d1d-4b19-8db1-73e9665d3c6f', '16630d19-b61b-4526-9dbd-7be685a68675', 'en', 'Cossack Squat', 'Lower toward one side stretching the opposite leg with the heel supported. Cue: chest high, lower as far as you can. Error: lifting the heel of the supporting foot.'),
('ecba4fd7-11b8-4735-a8c7-62a5ee7cc1e5', '16630d19-b61b-4526-9dbd-7be685a68675', 'es', 'Sentadilla lateral (Cossack)', 'Baja hacia un lado estirando la pierna opuesta con el talón apoyado. Cue: pecho alto, baja hasta donde puedas. Error: levantar el talón del pie de apoyo.'),
('4a20d8fd-40eb-4c28-b83f-29022403a352', '168c9a6d-9b5c-4556-8f10-3dce4a8ea6ca', 'en', 'Front Ball Toss', 'Throw the ball to the floor in front of you. Objective: core power. Cue: use the whole body. Error: arching back.'),
('030f42f2-9cab-4df7-82cc-d9953c7e88d7', '168c9a6d-9b5c-4556-8f10-3dce4a8ea6ca', 'es', 'Lanzamiento frontal balón', 'Lanza balón al suelo frente a ti. Objetivo: potencia core. Cue: usa todo cuerpo. Error: arquear espalda.'),
('832bb0ca-78f9-4cbd-a0fa-c9b2ce2dcbd1', '16b3eab5-5935-4010-95ff-8f288e1af007', 'en', 'Bulgarian Split Squat', 'Perform a Bulgarian split squat with the rear foot elevated on a bench. Lower under control while keeping the torso stable and push through the front leg to return to the starting position.'),
('a14835b5-5851-47df-aa5c-d4491a19c714', '16b3eab5-5935-4010-95ff-8f288e1af007', 'es', 'Búlgara', 'Realiza una sentadilla búlgara colocando el pie trasero elevado en un banco. Baja de forma controlada manteniendo el tronco estable y empuja con la pierna delantera para volver a la posición inicial.'),
('e71e4e9e-29d8-4b36-a8bd-c6e5d56bfa93', '16e6c4d9-6031-4050-990b-a6c648daf12f', 'en', 'Fitball Hamstring Curl', 'Lying on your back with heels on the Fitball, lift your hips and flex your knees to bring the ball toward your glutes.'),
('56b995b3-0c99-4baa-b974-ebc3bd33b7fd', '16e6c4d9-6031-4050-990b-a6c648daf12f', 'es', 'Curl de isquiotibiales en Fitball', 'Tumbado boca arriba con los talones sobre el Fitball, eleva la cadera y flexiona las rodillas para acercar el balón hacia tus glúteos.'),
('c892be35-8ee9-4a50-a010-5c544c36012a', '16fda8b8-0dd9-4ccb-8af4-8f9b1acc5fed', 'en', 'Reverse Grip Machine Pulldown', 'Pull the bar with palms facing you. Objective: lat/biceps. Cue: elbows down. Error: swinging.'),
('966ae150-e9e1-4778-afcc-f37ab8b6c553', '16fda8b8-0dd9-4ccb-8af4-8f9b1acc5fed', 'es', 'Jalón invertido máquina', 'Tira barra palmas hacia ti. Objetivo: dorsal/bíceps. Cue: codos abajo. Error: balanceo.'),
('0770cff3-0254-488d-ad9c-61070faaa1d7', '1705fc00-2ee9-4940-bd51-8a83fb04a26e', 'en', 'Barbell Triceps Extension', 'Standing or seated, hold the bar overhead with a close grip. Lower the bar behind the head by flexing only the elbows, keeping the upper arms vertical and motionless. Extend back to the starting position by contracting the triceps.'),
('785cb747-144c-48ca-ba84-7d87a83e81fc', '1705fc00-2ee9-4940-bd51-8a83fb04a26e', 'es', 'Extensión tríceps barra', 'De pie o sentado, sostén la barra sobre la cabeza con agarre cerrado. Desciende la barra por detrás de la cabeza flexionando solo los codos, manteniendo los brazos superiores verticales e inmóviles. Extiende hasta la posición inicial contrayendo los tríceps.'),
('d95f797f-edef-457a-aac6-2269a2b0f24e', '171bd587-8d9e-4aba-a205-f68516ee8d1f', 'en', 'Seated Cable Face Pull', 'Sit in front of a pulley. Pull the rope toward your forehead, bringing elbows back and externally rotating shoulders to work the rear deltoid.'),
('872d86e0-f039-4843-b7bb-44bbdd504082', '171bd587-8d9e-4aba-a205-f68516ee8d1f', 'es', 'Face Pull sentado con cable', 'Siéntate frente a una polea. Tira de la cuerda hacia tu frente, llevando los codos hacia atrás y rotando externamente los hombros para trabajar el deltoides posterior.'),
('704565e6-c974-4778-b4dd-f76a6f78c29e', '17207ac2-f9c8-4b21-a1fc-6b6181672e11', 'en', 'Snatch Grip Deadlift', 'Deadlift with hands very wide. Higher demand on the upper back. Neutral back. Do not round the lumbar area.'),
('1ac5f087-984b-4886-bfe6-33b5a4f2dc92', '17207ac2-f9c8-4b21-a1fc-6b6181672e11', 'es', 'Peso muerto con agarre Snatch', 'Peso muerto con manos muy separadas. Mayor demanda de espalda alta. Espalda neutra. No redondees la zona lumbar.'),
('94ee1d7e-91e8-4e73-af8d-ba8b5d766253', '1730b4b2-8e90-4468-92e1-868012e3a5f3', 'en', 'Half-Kneeling Cable Woodchopper', 'Woodchopper from a half-kneeling position. Eliminates leg contribution focusing work on the core. Greater range of motion than the kneeling version. Alternate lead knee.'),
('89b430d1-818e-45d1-954a-307355acd93a', '1730b4b2-8e90-4468-92e1-868012e3a5f3', 'es', 'Leñador media rodilla cable', 'Woodchopper desde posición de media rodilla. Elimina contribución de piernas enfocando el trabajo en core. Mayor rango de movimiento que versión arrodillada. Alterna rodilla adelantada.'),
('e93695ea-a32b-4648-b72b-741bb45db9a0', '17391cff-0178-48f7-a854-2b6379e9fba4', 'en', 'Pulley Pallof Press', 'Sideways to the pulley, push the handle forward and resist rotation. Cue: feet nailed to the ground. Error: rotating the torso toward the pulley.'),
('43a13cd6-0185-4fd3-ba62-3aa203361660', '17391cff-0178-48f7-a854-2b6379e9fba4', 'es', 'Pallof Press en polea', 'De lado a la polea, empuja el agarre al frente y resiste la rotación. Cue: pies clavados al suelo. Error: girar el torso hacia la polea.'),
('669728cb-3c08-4310-bb9d-5f2112f87e19', '173ad880-67af-4457-9201-89d6cd36968c', 'en', 'Box Squat', 'Squat with a pause by sitting completely on a box or bench. Eliminates the stretch reflex. Teaches how to generate force from a dead position. Popular in powerlifting. Box height should allow parallel thighs.'),
('39aed52f-a3bf-41c2-8293-47739b915012', '173ad880-67af-4457-9201-89d6cd36968c', 'es', 'Sentadilla en cajón', 'Sentadilla con pausa sentándose completamente en un cajón o banco. Elimina el reflejo de estiramiento. Enseña a generar fuerza desde posición muerta. Popular en powerlifting. La altura del cajón debe permitir muslos paralelos.'),
('f6b4aeff-e577-4dad-8bbd-179970d7c3b1', '1768a049-4c76-4ff6-bda0-33d75e3965c6', 'en', 'Hands-Behind-Head Long Jump', 'Perform a long jump without using arm momentum. Pure leg power. Firm core. Do not pull on your neck when jumping.'),
('3a895049-6fef-48e4-b736-d18c0b0cecda', '1768a049-4c76-4ff6-bda0-33d75e3965c6', 'es', 'Salto de longitud con manos tras nuca', 'Realiza un salto largo sin usar el impulso de los brazos. Potencia pura de piernas. Core firme. No tires del cuello al saltar.'),
('3e209b34-055b-415c-91b0-ed0b57518d1b', '176a49f0-fa39-46a8-a991-8be4cb8795a0', 'en', 'L-Sit', 'Supported on parallel bars or the floor, keep legs straight in front forming an L. Cue: shoulders down and away from ears. Error: hunching the chest.'),
('800f5fcb-e470-48c0-bdb3-bee528af506d', '176a49f0-fa39-46a8-a991-8be4cb8795a0', 'es', 'L-Sit', 'Apoyado en paralelas o suelo, mantén piernas estiradas al frente formando una L. Cue: hombros abajo y lejos de orejas. Error: encoger el pecho.'),
('64f13353-d393-40fd-8447-47cb208d62ef', '178165f2-5271-4f57-b298-6f17774932fc', 'es', 'Press Z con mancuernas', 'Siéntate en el suelo con las piernas extendidas en V. Realiza un press de hombros con mancuernas manteniendo el torso totalmente vertical sin apoyo trasero.'),
('0920391d-1129-46ba-8a54-a34e37f8355c', '1791c440-572a-486e-bea6-73dc3ae831a9', 'en', 'Barbell Rack Pull', 'Initiate the deadlift with the bar resting on the rack supports above the knees to focus the work on the upper back.'),
('165652bf-2792-492b-91e5-501759b22516', '1791c440-572a-486e-bea6-73dc3ae831a9', 'es', 'Rack Pull con barra', 'Inicia el peso muerto con la barra apoyada en los soportes del rack por encima de las rodillas para enfocar el trabajo en la espalda superior.'),
('f983eacb-ea54-4420-ae13-6555b9c9a7bb', '179f7ecf-923e-42c4-842b-84426e664a13', 'en', 'Reverse Box Jump', 'With your back to the box, jump rotating 180 degrees to land on it. Maximum aerial coordination. Cue: start the rotation early. Common error: landing off the edge of the box.'),
('73adb281-e2b1-4411-9c72-97cd9a82c6a8', '179f7ecf-923e-42c4-842b-84426e664a13', 'es', 'Salto al cajón invertido', 'De espaldas al cajón, salta girando 180 grados para aterrizar sobre él. Coordinación aérea máxima. Cue: inicia el giro temprano. Error común: caer fuera del borde del cajón.'),
('ce68f771-c2ff-4270-88e1-b315d376f276', '17dcf651-c852-4a79-b067-e39d4030f527', 'en', 'Elastic Band Hamstring Curl', 'Face down with the band anchored, flex knees bringing heels toward the glute. Objective: hamstring isolation. Cues: keep hips glued to the floor. Common error: lifting the pelvis to facilitate the movement.'),
('da33c239-9b87-4c1f-b2e1-7aa261982982', '17dcf651-c852-4a79-b067-e39d4030f527', 'es', 'Curl femoral con banda elástica', 'Boca abajo con la banda anclada, flexiona las rodillas llevando los talones hacia el glúteo. Objetivo: aislamiento de isquiotibiales. Cues: mantén la cadera pegada al suelo. Error común: levantar la pelvis para facilitar el movimiento.'),
('e96043d1-8517-4037-9dba-bf64a076a758', '17f0d72a-48bd-4e72-b38e-37e38eb4d70f', 'es', 'Zancada inversa ipsilateral con Slider y Kettlebell (Maleta)', 'Sostén una pesa rusa en un lado (posición maleta) y desliza hacia atrás la pierna del mismo lado usando un slider, manteniendo el equilibrio del torso.'),
('a91178e6-9275-41b2-98fe-6159f7779fd6', '17f675f9-9cdb-47a0-8fd6-114e4e88cb20', 'en', 'Kettlebell Thrusters', 'Perform a deep squat and leverage the momentum to push the weight overhead upon rising. Objective: total power and cardio. Cues: fluid and explosive movement. Common error: separating the squat from the press.'),
('01512be0-9cb8-4dd0-b3e3-24e7abe456f1', '17f675f9-9cdb-47a0-8fd6-114e4e88cb20', 'es', 'Thrusters con kettlebell', 'Realiza una sentadilla profunda y aprovecha el impulso para empujar la pesa sobre la cabeza al subir. Objetivo: potencia total y cardio. Cues: movimiento fluido y explosivo. Error común: separar la sentadilla del press.'),
('92ad548d-ff2a-4774-8e2e-4cea72373663', '17fc2020-7601-436a-a879-a09f1222436f', 'en', 'High Pulley Abdominal Crunch', 'Flex the torso while kneeling with a rope. Objective: loaded abs. Cue: exhale on the way down. Error: pulling with the arms.'),
('01b104f4-e173-4e50-a981-70d15ffd2d5c', '17fc2020-7601-436a-a879-a09f1222436f', 'es', 'Abdominales polea alta', 'Flexiona torso de rodillas con cuerda. Objetivo: abdomen carga. Cue: exhala al bajar. Error: tirar con brazos.'),
('cccb8ae0-8d11-408b-b5ad-3fcf3baf1102', '17fe0bc1-b524-4251-ac01-01f3d1377a87', 'en', 'Band Shoulder Press', 'Step on the center of the band and hold the ends at shoulder height. Press upward fully extending arms overhead. Progressive band resistance makes the exercise more challenging at the end of the movement.'),
('c5e21b14-2ddc-4fd7-913b-3efc3011d82b', '17fe0bc1-b524-4251-ac01-01f3d1377a87', 'es', 'Press hombros con banda', 'Pisa el centro de la banda y sujeta los extremos a la altura de los hombros. Presiona hacia arriba extendiendo completamente los brazos sobre la cabeza. La resistencia progresiva de la banda hace el ejercicio más desafiante en la parte final del movimiento.'),
('3387ec2b-ef73-4a1d-856b-42729856296f', '18623e44-ca76-4996-a5f7-994c344ef626', 'en', 'Kettlebell Half Kneeling Low to High Chop', 'In a half-kneeling position, hold the kettlebell and drive it from the hip of the kneeling leg toward the opposite shoulder diagonally.'),
('2cdc9cd5-3017-4c49-938c-c0aae60f3dec', '18623e44-ca76-4996-a5f7-994c344ef626', 'es', 'Woodchop bajo a alto medio arrodillado con Kettlebell', 'En posición de caballero, sujeta la Kettlebell y llévala desde la cadera de la rodilla apoyada hacia el hombro opuesto en diagonal.'),
('50e73d99-9882-4c50-ad5e-d1b100c82ae1', '1864c04f-6f4b-4aeb-a975-a38ccb29123a', 'en', 'Prone Pull-ups', 'Hang from a bar with palms facing forward and hands slightly wider than shoulder-width. Lift the body pulling with the lats until the chin clears the bar. Descend controlled to full arm extension. Keep the core engaged to avoid swinging.'),
('833d6228-d3f6-464b-a952-224ade8bfd5c', '1864c04f-6f4b-4aeb-a975-a38ccb29123a', 'es', 'Dominadas pronadas', 'Cuelga de una barra con las palmas mirando hacia adelante y las manos separadas ligeramente más que el ancho de los hombros. Eleva el cuerpo tirando con los dorsales hasta que la barbilla supere la barra. Desciende controladamente hasta la extensión completa de los brazos. Mantén el core activado para evitar el balanceo.'),
('57445915-1961-48f4-8d5d-33fdf23d9412', '188cf4ae-31c0-4846-ac16-040ddf2ad7e5', 'en', 'Single Arm Kettlebell Front Rack Contralateral Split Squat', 'With one foot forward, hold the kettlebell in the shoulder opposite to the front leg. Lower the back knee toward the floor while maintaining core stability against the asymmetrical load.'),
('635aeeab-4b9e-4b4a-bf15-7ed98f3b14ea', '188cf4ae-31c0-4846-ac16-040ddf2ad7e5', 'es', 'Sentadilla Split contralateral Front Rack con Kettlebell', 'Con un pie adelantado, sostén la pesa rusa en el hombro opuesto a la pierna delantera. Baja la rodilla trasera hacia el suelo manteniendo la estabilidad del core ante la carga asimétrica.'),
('5abf3cfa-7254-4ee9-8ca4-d0eb3f622243', '188eacb0-8a57-45b4-ba3f-02615ddecda4', 'es', 'Pullover con maza doble', 'Sujeta la maza con ambas manos y llévala desde detrás de la cabeza hacia el pecho en un arco controlado para trabajar el dorsal y la movilidad de hombros.'),
('aa66faa9-ee0e-44c2-8f65-7179b449d59e', '18c5ee15-78c9-4107-8ae2-064e14f79101', 'en', 'Wide-Grip Seated Cable Row', 'Perform a wide-grip seated cable row. Pull the handle toward the torso while keeping the back stable and squeezing the shoulder blades together.'),
('5910bf53-1e46-4f1a-b719-d83b78ea023e', '18c5ee15-78c9-4107-8ae2-064e14f79101', 'es', 'Remo cable polea baja agarre amplio', 'Realiza un remo en polea baja con agarre amplio. Tira del agarre hacia el torso manteniendo la espalda estable y juntando las escápulas.'),
('2d40595c-7c21-4d0e-9079-a5408b4a5a18', '18e3cd94-e37c-4ba8-b5c1-0a63de4b9c70', 'en', 'Kettlebell Figure 8', 'Pass the weight between the legs drawing an eight while maintaining a partial squat. Coordination. Chest out. Do not hunch the back.'),
('a45fad20-3c33-4a2a-92bb-ee380391090c', '18e3cd94-e37c-4ba8-b5c1-0a63de4b9c70', 'es', 'Kettlebell Figure 8', 'Pasa la pesa entre las piernas dibujando un ocho mientras mantienes sentadilla parcial. Coordinación. Pecho alto. No encorves la espalda.'),
('9773a390-bb8b-4f41-983f-9dd7b8985c0b', '18fd3305-05fb-41b5-a099-49319b554150', 'en', 'Cable Chest Crossovers', 'Standing, bring hands together in front of you with elbows slightly bent. Cue: imagine you are hugging a barrel. Error: turning the exercise into a press.'),
('a165f22a-f096-446b-9ca1-37eac6b0738a', '18fd3305-05fb-41b5-a099-49319b554150', 'es', 'Cruces de poleas para pecho', 'De pie, junta las manos frente a ti con codos semiflexionados. Cue: imagina que abrazas un barril. Error: transformar el ejercicio en un press.'),
('8f5f997e-3faa-41ea-9b2a-fea249c10071', '1904ee25-9ab9-46d9-a279-ea09dc8d466e', 'en', 'Lateral band walk', 'Place the band around ankles or above knees. Adopt a half-squat position and take lateral steps maintaining constant tension in the band. Keep feet parallel and do not allow knees to cave in. Activate gluteus medius and minimus.'),
('c854a607-ef80-4e85-8135-6f4389343193', '1904ee25-9ab9-46d9-a279-ea09dc8d466e', 'es', 'Caminata lateral con banda', 'Coloca la banda alrededor de los tobillos o por encima de las rodillas. Adopta una posición de media sentadilla y da pasos laterales manteniendo la tensión constante en la banda. Mantén los pies paralelos y no permitas que las rodillas se junten. Activa glúteo medio y menor.'),
('cde1e631-f821-4dd3-b12d-3b7e1f0c5973', '1921d221-714e-458c-94f8-83de53be4f8a', 'en', 'Bosu Squat', 'Perform a squat on the unstable part of the Bosu. Improves proprioception. Cue: parallel feet. Error: looking at the ground.'),
('80a6a8eb-679f-4055-a544-9a8ec44aa6ff', '1921d221-714e-458c-94f8-83de53be4f8a', 'es', 'Sentadilla sobre Bosu', 'Realiza una sentadilla sobre la parte inestable del bosu. Mejora la propiocepción. Cue: pies paralelos. Error: mirar al suelo.'),
('a5de92fd-f279-4a41-8848-abb977ba6d70', '1922828f-14b2-4482-a342-b5c055d1bded', 'es', 'Plancha con caminata lateral', 'En posición de plancha, desplázate lateralmente moviendo manos y pies a la vez. Objetivo: estabilidad total y hombros. Cues: cadera quieta y core firme. Error común: elevar demasiado el glúteo.'),
('89b1fca5-60e4-4e7b-9cea-5498bfe96bdd', '192f277f-1afa-4ba3-a8b2-42be649aec67', 'en', 'Unilateral Kettlebell Deadlift', 'Hold the weight and lower the torso while extending one leg back. Balance and strength. Neutral back. Do not rotate the hip outward.'),
('e103e523-cea8-424d-8542-8e3e43dc0057', '192f277f-1afa-4ba3-a8b2-42be649aec67', 'es', 'Kettlebell Deadlift unilateral', 'Sujeta la pesa y baja el torso mientras extiendes una pierna atrás. Equilibrio y fuerza. Espalda neutra. No gires la cadera hacia afuera.'),
('18e81033-d148-40f5-b88a-64549b7f60dd', '19305a46-83d2-4243-8cb8-a4ce8556c6e0', 'en', 'Dumbbell Farmers Walk', 'Hold heavy dumbbells in each hand and walk maintaining perfect upright posture. Shoulders should be back and down, core engaged. This functional exercise strengthens grip, traps, core, and improves overall stability.'),
('3f376c7c-382d-49cd-9eb2-ef18626299ac', '19305a46-83d2-4243-8cb8-a4ce8556c6e0', 'es', 'Caminata del granjero mancuernas', 'Sujeta mancuernas pesadas en cada mano y camina manteniendo una postura erguida perfecta. Los hombros deben estar hacia atrás y abajo, el core activado. Este ejercicio funcional fortalece el agarre, trapecios, core y mejora la estabilidad general.'),
('64385009-2654-484e-92fe-b685fc0a4027', '19523379-c1fb-478a-a1d2-84b2bcd8cc41', 'en', 'Back Openings (Band Pull-Apart)', 'Hold the band in front of you with straight arms and pull them apart to the sides until the band touches your chest. Objective: rear deltoid and posture. Cue: keep arms straight. Error: bending elbows to make the range easier.'),
('8644d96e-ffcd-4882-a947-5f2e97b9e97d', '19523379-c1fb-478a-a1d2-84b2bcd8cc41', 'es', 'Aperturas de espalda (Band Pull-Apart)', 'Sujeta la banda frente a ti con brazos estirados y sepáralos hacia los lados hasta que la banda toque tu pecho. Objetivo: deltoides posterior y postura. Cue: mantén los brazos rectos. Error: doblar los codos para facilitar el rango.'),
('cbedb919-e236-4177-95a1-406f5d03c0d0', '19be9978-7e51-41f5-a1cd-fd76b8fee27c', 'es', 'Zancada cruzada (Curtsy) Zercher en Landmine', 'Sujeta la barra Landmine en el pliegue de tus codos y realiza una zancada cruzando una pierna por detrás de la otra (reverencia).'),
('cdd26498-8c0f-403d-ae35-d32e16eb7911', '1a7cdfa7-8512-4ea6-8be1-1d57d3d18023', 'en', 'Abductor Machine with Back Support', 'Open legs while seated. Cue: back glued. Error: leaning.'),
('68f740b5-4e22-43da-a1c3-5c7db4f99411', '1a7cdfa7-8512-4ea6-8be1-1d57d3d18023', 'es', 'Máquina abductores espalda apoyada', 'Abre piernas sentado. Cue: espalda pegada. Error: inclinarse.'),
('0429430b-203d-4882-8f4b-a53e0d108603', '1a88841c-708c-4701-a2f7-c79e0a9935c0', 'en', 'Reverse Grip Dumbbell Bench Press', 'Lie on the bench and hold the dumbbells with palms facing your face (supine). Press upward focusing on the upper pectoral.'),
('ac86068d-1c83-4cca-9664-a3e0e2ef097f', '1a88841c-708c-4701-a2f7-c79e0a9935c0', 'es', 'Press de banca agarre inverso con mancuernas', 'Acuéstate en el banco y sostén las mancuernas con las palmas mirando hacia tu cara (supino). Presiona hacia arriba enfocando el pectoral superior.'),
('b6b82214-4ac4-45ad-8cbb-877acc85b9cb', '1a93c5b6-d801-49e2-93cc-1b42cd5593b3', 'es', 'Press Pallof con rotación', 'Extiende el cable al frente y realiza una rotación lenta controlada lejos del anclaje, volviendo despacio. Objetivo: fuerza rotacional del core. Cues: pies clavados al suelo y brazos estirados. Error común: mover las caderas junto con el torso.'),
('b90bad06-8845-4632-8e7d-0b3dd76fd5db', '1ae4d9fe-25ac-40a9-956f-267c709ecf69', 'en', 'One Arm Overhead Dumbbell Walk', 'Walk holding a dumbbell locked overhead with a straight arm, keeping the core tight and avoiding arching the back.'),
('24f7f54b-2b30-47b5-bac9-2409b1151d01', '1ae4d9fe-25ac-40a9-956f-267c709ecf69', 'es', 'Caminata Overhead con mancuerna a una mano', 'Camina sosteniendo una mancuerna bloqueada sobre la cabeza con el brazo recto, manteniendo el core tenso y evitando arquear la espalda.'),
('b97d4840-67c7-4a53-9615-e7dd348b407f', '1aeb6a4c-21d9-40ef-bb7c-839b3ae8a852', 'es', 'Peso muerto rumano con mancuernas', 'Baja las pesas pegadas a las piernas con rodillas semi-rígidas. Estiramiento de isquios. Espalda plana. No bajes más allá de tu flexibilidad.'),
('e2d81b5c-d46f-4ae8-9b54-1f0cd35fcd1d', '1b77e09c-b9e8-4c86-9257-3a272780761e', 'en', 'Stability Ball V Up Pass', 'Lie face up holding the Fitball with your hands. Lift legs and arms simultaneously to pass the ball from hands to feet. Lower the body and repeat passing the ball from feet back to hands.'),
('15334e66-2750-413d-b934-054f48ec114c', '1b77e09c-b9e8-4c86-9257-3a272780761e', 'es', 'V-Up con pase de Fitball', 'Acuéstate boca arriba sosteniendo el Fitball con las manos. Levanta piernas y brazos simultáneamente para pasar el balón de las manos a los pies. Baja el cuerpo y repite pasando el balón de los pies a las manos.'),
('40b1e05a-01e4-4f12-a94a-4103b41d113e', '1b9996ee-191c-42ed-8bf2-3674543d9f6b', 'en', 'Cable French Press', 'Lying on a bench with head toward the low pulley, perform triceps extensions bringing the bar from behind the head to arms extended vertically. The cable maintains constant tension throughout the range unlike the free bar.'),
('57067ccd-9840-46d5-9dbe-ec676d8eddbd', '1b9996ee-191c-42ed-8bf2-3674543d9f6b', 'es', 'Press francés cable', 'Tumbado en banco con la cabeza hacia la polea baja, realiza extensiones de tríceps llevando la barra desde detrás de la cabeza hasta brazos extendidos verticalmente. El cable mantiene tensión constante en todo el recorrido a diferencia de la barra libre.'),
('d304334a-70c4-4e3f-8af4-64ab46f35a92', '1bbdbce9-2e64-4618-81b5-9768938da26e', 'en', 'Explosive Kettlebell Snatch', 'A single movement from the floor to lockout overhead. Objective: total power. Cue: smooth transition of the handle in the hand. Common error: hitting the forearm with the weight.'),
('e5a52109-ac39-4a2f-8019-0e2c004684b5', '1bbdbce9-2e64-4618-81b5-9768938da26e', 'es', 'Kettlebell Snatch explosivo', 'Un solo movimiento desde el suelo hasta bloquear sobre la cabeza. Objetivo: potencia total. Cue: transición suave del asa en la mano. Error común: golpear el antebrazo con la pesa.'),
('57ab2a13-a4ac-4304-82e5-372517e98d1c', '1bc63a89-d890-4330-8494-2a188f2df0e8', 'en', 'Hollow Hold', 'Hold a hollow body position lying on your back, keeping the lower back pressed into the floor, legs extended, and arms overhead. Maintain abdominal tension for the prescribed time.'),
('4626ff5b-d987-4097-b213-db37b8d0d101', '1bc63a89-d890-4330-8494-2a188f2df0e8', 'es', 'Hollow hold', 'Mantén una posición hollow tumbado boca arriba, con la zona lumbar pegada al suelo, piernas extendidas y brazos por encima de la cabeza. Sostén la tensión abdominal durante todo el tiempo indicado.'),
('86836f10-c51f-4fa1-84d0-384f05a83f78', '1bd5bf73-c98a-4e59-a7cb-1856af42f5bb', 'en', 'Toe Take-off Vertical Jump', 'Jump seeking maximum ankle and toe extension at the end of take-off. Reactive force. Soft landing. Do not lock knees when landing.'),
('37b96c7d-da96-4b2f-9085-0c506f7290c1', '1bd5bf73-c98a-4e59-a7cb-1856af42f5bb', 'es', 'Salto vertical con despegue de dedos', 'Salta buscando máxima extensión de tobillo y dedos al final del despegue. Fuerza reactiva. Aterrizaje suave. No bloquees las rodillas al caer.'),
('08c9baec-8d74-4762-8a0d-05bc1e63fac5', '1c09d6cb-9279-4644-bf2b-8934fc2a1e9e', 'en', 'Cable Triceps Kickback', 'Leaning forward with low pulley, perform backward extensions keeping the upper arm parallel to the floor. The cable provides constant resistance unlike dumbbells. Excellent for maximum triceps contraction.'),
('81afbfc3-b255-40ee-bdf5-9faa841603ab', '1c09d6cb-9279-4644-bf2b-8934fc2a1e9e', 'es', 'Patada tríceps cable', 'Inclinado hacia adelante con polea baja, realiza extensiones hacia atrás manteniendo el brazo superior paralelo al suelo. El cable proporciona resistencia constante a diferencia de las mancuernas. Excelente para la contracción máxima del tríceps.'),
('660447b3-58fd-46f9-8ab0-1dec985494b7', '1c104156-705b-438b-9fc3-c160ab15610f', 'en', 'Narrow Neutral Lat Pulldown', 'Pull the V-handle to the chest. Objective: lat width. Cue: chest out. Error: hunching.'),
('c0ca97e3-cff5-4a1e-9113-7ea9b824fa9f', '1c104156-705b-438b-9fc3-c160ab15610f', 'es', 'Jalón neutro estrecho', 'Tira agarre V al pecho. Objetivo: amplitud dorsal. Cue: pecho fuera. Error: encorvarse.'),
('917ff0ce-e40b-42e1-ab07-37f36346edff', '1c13fa4f-1e78-46f9-80d1-0bffa400836b', 'es', 'Power Clean con barra', 'Lleva la barra desde el suelo hasta los hombros en un movimiento explosivo, recibiéndola en una posición de media sentadilla.'),
('23b16f8c-b312-4c72-b261-523fca079175', '1c4ae5a3-b88f-4d08-a413-10611c064a63', 'es', 'Planche', 'Mantén el cuerpo horizontal paralelo al suelo sostenido únicamente por las manos. Una de las habilidades más difíciles de calistenia. Requiere años de preparación específica. Progresa con lean planche, tuck, advanced tuck y straddle.'),
('347c2add-35f8-4d9b-ae51-651896a59c6e', '1c83611f-9414-48fc-990a-ee7f73705f78', 'es', 'Plancha frontal isométrica', 'Mantén el cuerpo recto apoyado en antebrazos. Cue: ombligo adentro. Error: hundir la cadera.'),
('66c4b3f4-a394-4eea-b4c7-10709661c347', '1ca8d902-cbca-43e3-ad19-f3d375faf9dc', 'en', 'Triple Long Jump', 'Three consecutive long jumps without stopping. Objective: horizontal reactivity. Cue: leverage the bounce of each landing. Common error: stopping between jumps.'),
('bacfa0bf-2089-47ee-b78f-45aba33c236e', '1ca8d902-cbca-43e3-ad19-f3d375faf9dc', 'es', 'Salto longitud triple', 'Tres saltos de longitud seguidos sin detenerse. Objetivo: reactividad horizontal. Cue: aprovecha el rebote de cada aterrizaje. Error común: paradas entre saltos.'),
('095d8bf8-7478-4659-bdc5-9e5bcf603bd8', '1cbdf502-9629-498d-b3a8-de1682c23cf3', 'en', 'Cable External Rotation', 'Perform a cable shoulder external rotation. Keep the elbow close to the body and rotate the forearm outward under control without compensating with the torso.'),
('92e97418-cef9-4bb9-8f05-eaea1a5310fe', '1cbdf502-9629-498d-b3a8-de1682c23cf3', 'es', 'Rotación externa con cables', 'Realiza una rotación externa de hombro con cable. Mantén el codo cerca del cuerpo y rota el antebrazo hacia fuera de forma controlada sin compensar con el tronco.'),
('4399a3c6-9495-44ef-a87e-08fa41a0f5d9', '1ccbb504-3c84-4352-b82a-722685f10e6b', 'es', 'Potencia rotacional TRX', 'Movimiento explosivo rotacional usando TRX. Simula patrones deportivos de lanzamiento. Genera potencia desde las caderas a través del core. Mantén brazos relativamente extendidos durante la rotación.'),
('c6d21909-eaea-4965-9b89-9d0fdddfbe5e', '1ccce816-8961-462a-a0fa-9fdd714f41ae', 'en', 'Double Kettlebell Suitcase Feet Elevated Calf Raise', 'Standing on a step with kettlebells at your sides, raise your heels as high as possible and lower slowly to work the calves.'),
('f84079e8-1854-4be0-966b-5aaf9dff0866', '1ccce816-8961-462a-a0fa-9fdd714f41ae', 'es', 'Elevación de gemelos con pies elevados y Kettlebell doble (Maleta)', 'De pie sobre un escalón con Kettlebells a los lados, eleva los talones al máximo y baja lentamente para trabajar los gemelos.'),
('f6b8fb05-2e1d-41a1-9027-6a0bca8655f9', '1cd057ab-1001-4265-afd0-41c31ec7f632', 'en', 'High Knees', 'Run in place raising knees as high as possible, ideally to hip height. Keep the torso upright and swing arms naturally. Land on the balls of the feet for agility. It is an excellent cardiovascular exercise that also strengthens the core.'),
('2568c130-ec19-4b1e-939d-08e58e2f0306', '1cd057ab-1001-4265-afd0-41c31ec7f632', 'es', 'High knees', 'Corre en el sitio elevando las rodillas lo más alto posible, idealmente hasta la altura de las caderas. Mantén el torso erguido y balancea los brazos de forma natural. Aterriza en las puntas de los pies para mayor agilidad. Es un excelente ejercicio cardiovascular que también fortalece el core.'),
('e9f58abc-b8ca-4245-a908-0fecf9ba2a4a', '1d1eb6d3-82db-4f55-8b5a-8ae5976209c1', 'es', 'Upright row mancuernas', 'Con las mancuernas frente a los muslos, tira hacia arriba llevando los codos por encima de las manos hasta que las mancuernas lleguen a la altura del pecho. Mantén las mancuernas cerca del cuerpo durante todo el movimiento. Cuidado con la posición de las muñecas.'),
('3f60c797-558a-4777-8289-fb522924ac18', '1d2e2369-8bc0-4968-966a-ea8ae6f71a7b', 'en', 'Alternating Double Kettlebell Spider Curl', 'Supported face down on an incline bench, perform the curl with kettlebells alternating arms for a unique grip stimulus.'),
('95fe71a5-c327-49bd-83bc-f440fb34d941', '1d2e2369-8bc0-4968-966a-ea8ae6f71a7b', 'es', 'Spider Curl alterno con Kettlebell doble', 'Apoyado boca abajo en banco inclinado, realiza el curl con pesas rusas alternando brazos para un estimulo de agarre unico.'),
('199abc3c-aaee-44a1-a314-d5c12cb73638', '1dae8e68-453b-4da4-91db-2c4bafc8eb31', 'en', 'Alternating Goblet Dumbbell Cossack Squat', 'Hold a dumbbell in front of the chest and perform deep lateral shifts, alternating between legs to work adductors and glutes.'),
('3f40e508-58b2-4c0a-8757-2f7230e9b4c5', '1dae8e68-453b-4da4-91db-2c4bafc8eb31', 'es', 'Sentadilla Cosaca alterna Goblet con mancuerna', 'Sostén una mancuerna frente al pecho y realiza desplazamientos laterales profundos, alternando entre piernas para trabajar aductores y glúteos.'),
('9bc5d0e6-afc7-4fae-bf63-8c72f5c40440', '1e2aef89-eb11-439a-bace-0c88dd786753', 'en', 'Slider Double Kettlebell Bottoms Up Front Rack Lateral Lunge', 'Hold inverted Kettlebells in rack position. Slide one leg laterally on a slider, lower into a lunge and return with power.'),
('4f176558-53c2-4c5c-be57-7ed18df82987', '1e2aef89-eb11-439a-bace-0c88dd786753', 'es', 'Zancada lateral Front Rack Bottoms Up con Slider', 'Sostén Kettlebells invertidas en posición de rack. Desliza una pierna lateralmente en un slider, baja en zancada y regresa con potencia.'),
('58fb64ad-a6ff-4050-8a82-7ab548d0c256', '1e5bd445-6532-4cc2-be39-d4668e14dbcf', 'en', 'Alternating Double Kettlebell Shoulder Press', 'Press the kettlebells overhead alternately, keeping one weight in the rack position while the other goes up.'),
('e92b458b-c76b-44c4-97ba-d21345180fad', '1e5bd445-6532-4cc2-be39-d4668e14dbcf', 'es', 'Press de hombros alterno con Kettlebell doble', 'Presiona las pesas rusas sobre la cabeza de forma alterna, manteniendo una pesa en posicion rack mientras la otra sube.'),
('62cd7978-45e6-49a4-9846-d9516dbcb46c', '1e5c39d6-cac0-432f-9ef2-75e953ea5159', 'en', 'Single Arm Kettlebell Bent Press', 'A traditional strength movement where you hinge away from the load while keeping the arm locked out until standing upright.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('d2ff01e4-4126-4458-acd1-8bab7d0592e7', '1e5c39d6-cac0-432f-9ef2-75e953ea5159', 'es', 'Bent Press con Kettlebell a una mano', 'Un movimiento de fuerza tradicional donde te inclinas alejandote de la carga mientras mantienes el brazo bloqueado hasta quedar erguido.'),
('69172252-b654-440f-b360-b12d386029aa', '1e6d8537-5df2-4a59-bf34-af6548967abb', 'en', 'Snatch Grip High Pull', 'Explosive pull with a wide snatch grip. Develops power for Olympic lifts. The bar should rise at least to the chest. Focus on speed and triple extension. This is not a slow upright row.'),
('f654533d-b38a-4418-aeb7-6576a490de07', '1e6d8537-5df2-4a59-bf34-af6548967abb', 'es', 'Tirón alto agarre arranque', 'Tirón explosivo con agarre amplio de arranque. Desarrolla potencia para levantamientos olímpicos. La barra debe subir al menos hasta el pecho. Enfócate en la velocidad y extensión triple. No es un remo alto lento.'),
('c03f7761-ec0e-4163-8021-3c12a7d249df', '1ea40f1e-7249-41da-bdfa-f68668ed8476', 'en', 'Single-Leg Jump Squat', 'Pistol squat with an explosive jump upon rising. Combines maximum unilateral strength with power. Extremely demanding. Land on the same leg and maintain control. Only after mastering the regular pistol squat.'),
('faf4cfdf-b4cd-4be7-9ebc-aae598b707d4', '1ea40f1e-7249-41da-bdfa-f68668ed8476', 'es', 'Sentadilla salto una pierna', 'Sentadilla pistol con salto explosivo al subir. Combina fuerza unilateral máxima con potencia. Extremadamente demandante. Aterriza en la misma pierna y mantén el control. Solo tras dominar sentadilla pistol regular.'),
('fabdee5b-403d-4f32-b3ce-18e586c60d14', '1f17f7ef-fa69-4b2a-b2ee-8391c56aa322', 'en', 'Dumbbell Thruster', 'Hold dumbbells at shoulder height. Perform a squat and use the rising momentum to push the weights overhead.'),
('dd69fedd-480b-4511-8c7a-f10d8a4b95dc', '1f17f7ef-fa69-4b2a-b2ee-8391c56aa322', 'es', 'Thruster con mancuernas', 'Sostén mancuernas a la altura de los hombros. Haz una sentadilla y usa el impulso de subida para empujar las pesas sobre la cabeza.'),
('7e83da53-69f7-4c7a-8291-3346cf96cfd5', '1f2a012e-f780-4510-8574-d026fa2feadb', 'en', 'Reverse Glute Hack Squat', 'Push with shoulders facing the machine. Cue: hip back. Error: knees inward.'),
('220f0c72-396d-4701-9c9c-eb4c4066a9f6', '1f2a012e-f780-4510-8574-d026fa2feadb', 'es', 'Sentadilla Hack inversa glúteo', 'Empuja con hombros de frente a máquina. Cue: cadera atrás. Error: rodillas dentro.'),
('a4b35f51-8dd1-441a-a4ab-9788e4141cec', '1f2f983c-3dab-4e26-b3fa-bc77fd00ca36', 'en', 'Single Arm Kettlebell Bottoms Up Overhead Contralateral Bulgarian Split Squat', 'Hold the upside-down kettlebell overhead with the arm opposite to the front leg while performing a deep Bulgarian split squat.'),
('27725cdc-27f6-4723-8317-e416d8a0da56', '1f2f983c-3dab-4e26-b3fa-bc77fd00ca36', 'es', 'Sentadilla Búlgara búlgara contralateral por encima de la cabeza con pesa rusa de un solo brazo de abajo hacia arriba', 'Sujeta la pesa invertida arriba con el brazo opuesto a la pierna delantera mientras realizas una sentadilla búlgara profunda.'),
('55a1bcbd-319d-4ff1-b556-3fbcb0317d9a', '1f3786c5-628c-4dcd-8961-19191dc031e7', 'en', 'Reverse Dumbbell Bicep Curl', 'Flex dumbbells with palms down. Objective: forearm. Cue: firm grip. Error: moving elbows.'),
('3e4ec806-2e11-4aaa-84a9-bb9e39a2cc36', '1f3786c5-628c-4dcd-8961-19191dc031e7', 'es', 'Curl bíceps invertido mancuerna', 'Flexiona mancuernas palmas abajo. Objetivo: antebrazo. Cue: agarre firme. Error: mover codos.'),
('32ce304f-37cf-4961-88fe-1892033239fb', '1fa91d6a-892e-4a55-ae88-15fe3c3a7382', 'es', 'Zancada atrás con mancuernas', 'Da un paso atrás con mancuernas a los lados y baja. Objetivo: cuádriceps y glúteo. Cues: rodilla a 90 grados. Error común: perder el equilibrio lateral.'),
('3c8329eb-747c-444c-9dfc-1e1bce3a39da', '1ffe14ed-4905-45ea-acda-17df07039f3c', 'en', 'Bicep Curl 21', 'Perform 7 repetitions from bottom to halfway, 7 from halfway to top, and 7 full repetitions without rest. Objective: maximum muscle fatigue and pump. Cues: elbows fixed at sides and no swinging. Common error: shortening the range of motion in the last 7 reps.'),
('97d15f2a-5833-4b12-b25e-b30c57b95587', '1ffe14ed-4905-45ea-acda-17df07039f3c', 'es', 'Curl de bíceps 21', 'Realiza 7 repeticiones desde abajo hasta la mitad, 7 desde la mitad hasta arriba, y 7 repeticiones completas sin descanso. Objetivo: máxima fatiga muscular y bombeo. Cues: codos fijos a los costados y sin balanceos. Error común: acortar el rango de movimiento en las últimas 7 repeticiones.'),
('e0619674-9312-4cd0-8f5f-cc5db52c4b07', '200948e0-4dcd-468d-bf46-7fde893a9f86', 'en', 'Flat Barbell Bench Press', 'Lower the bar to the chest and push upward on a flat bench. Cue: retract scapulae. Error: bouncing off the chest.'),
('cd22bd1a-2c70-42de-a013-aa4356964d04', '200948e0-4dcd-468d-bf46-7fde893a9f86', 'es', 'Press de banca plano con barra', 'Baja la barra al pecho y empuja hacia arriba en banco plano. Cue: retrae escápulas. Error: rebotar en el pecho.'),
('83fe416c-3eab-4702-8bdb-64510615d0be', '200a64da-0d96-45e8-bb9e-3a975a1acd0f', 'en', 'Double Kettlebell Seesaw Sots Press', 'In a deep squat position, perform a continuous alternating press with kettlebells in a rhythmic see-saw motion.'),
('65a31283-8839-4f54-87cf-33b0a0ad168e', '200a64da-0d96-45e8-bb9e-3a975a1acd0f', 'es', 'Press de Sots con balancín y pesas rusas dobles', 'En posicion de sentadilla profunda, realiza un press alterno continuo con Kettlebells en un movimiento rítmico de balancín.'),
('d2b2a7f3-eea5-47d3-a80e-e5728aca9684', '206dfae1-c623-420a-8344-d36c135a4f30', 'en', 'Double Kettlebell Renegade Row to Push Up', 'Execute a push-up supported on kettlebells followed immediately by a unilateral row, alternating arms in each cycle.'),
('2d91bf38-e56e-4eee-a0a6-c71e21dc0559', '206dfae1-c623-420a-8344-d36c135a4f30', 'es', 'Remo renegado doble con pesa rusa para flexiones', 'Ejecuta una flexion apoyado en las Kettlebells seguido inmediatamente por un remo unilateral, alternando los brazos en cada ciclo.'),
('09706713-a672-41d9-95c9-49a4cb3daadd', '2079e221-d565-4e2b-b5df-1b9702e0744b', 'en', 'Landmine Goblet Squat', 'Hold the end of the bar in front of the chest and perform a squat, taking advantage of the bar''s trajectory to keep the torso upright.'),
('4c2686a9-129a-4980-8106-277f04192755', '2079e221-d565-4e2b-b5df-1b9702e0744b', 'es', 'Sentadilla Goblet en Landmine', 'Sujeta el extremo de la barra frente al pecho y realiza una sentadilla, aprovechando la trayectoria de la barra para mantener el torso erguido.'),
('00c6e41d-569a-458a-832f-f3c1474dac4a', '20e1d0b5-ee6e-4aed-a45d-73b50205eb1b', 'en', 'Dumbbell Crush Grip Hollow Body Flutter Kicks', 'Perform flutter kicks in Hollow Body while pressing two dumbbells against each other over your chest to activate the core.'),
('31af5045-275a-4a28-88a8-c589949f9fe1', '20e1d0b5-ee6e-4aed-a45d-73b50205eb1b', 'es', 'Patadas de aleteo con cuerpo Hollow y agarre aplastado con mancuernas', 'Realiza patadas de aleteo en Hollow Body mientras presionas dos mancuernas una contra la otra sobre tu pecho para activar el core.'),
('1edca82b-bd6c-4a87-914f-d53cfddbb5fa', '20e34a9f-30bb-4c53-819f-40a90b54d75a', 'en', 'Cable Lateral Lunge', 'Side lunges with cable resistance. Can be with the cable to the side (resisting) or in front (assisting). Works the often neglected frontal plane of motion. Keep the supporting foot firmly planted.'),
('a3385bf7-993e-4acf-9e31-1761c2b352a0', '20e34a9f-30bb-4c53-819f-40a90b54d75a', 'es', 'Zancada lateral cable', 'Zancadas laterales con resistencia de cable. Puede ser con cable al lado (resistiendo) o al frente (asistiendo). Trabaja plano frontal de movimiento a menudo descuidado. Mantén pie de apoyo firmemente plantado.'),
('9d031beb-9a9a-447e-807a-721635768f9c', '2155f0eb-71ed-45b0-99f6-f553aa09db75', 'en', 'Low Pulley Row', 'Seated in front of the pulley, pull the handle toward the abdomen keeping the back straight. Objective: mid-back density. Cue: pull elbows back. Common error: swinging the trunk excessively.'),
('e7edc0ab-3311-4b54-b048-884388fd3211', '2155f0eb-71ed-45b0-99f6-f553aa09db75', 'es', 'Remo en polea baja', 'Sentado frente a la polea, tira del agarre hacia el abdomen manteniendo la espalda recta. Objetivo: densidad de la espalda media. Cue: tira de los codos hacia atrás. Error común: balancear el tronco excesivamente.'),
('d25e2c8a-e2a8-43e6-9034-58e5a6c3d733', '21842524-21cb-4934-8d13-0a8b92985a29', 'en', 'Reverse Lunges', 'Take a step backward and descend by flexing both knees until the back knee almost touches the ground. Keep the torso upright and weight distributed mainly on the front leg. This variation is more stable than the front lunge and allows for better movement control.'),
('09d5e7ec-111e-4a83-875c-42cf2c7de550', '21842524-21cb-4934-8d13-0a8b92985a29', 'es', 'Zancadas posteriores', 'Da un paso hacia atrás y desciende flexionando ambas rodillas hasta que la rodilla trasera casi toque el suelo. Mantén el torso erguido y el peso distribuido principalmente en la pierna delantera. Esta variación es más estable que la zancada frontal y permite mejor control del movimiento.'),
('c4008ee5-51b4-4d73-9a2a-bb08f0ea3459', '21af0ffa-3757-4a92-9ef7-bd2297871c83', 'es', 'Press Overhead alterno medio arrodillado con Kettlebell doble', 'En posición de caballero, presiona las Kettlebells alternativamente sobre la cabeza, desafiando el equilibrio en la base de apoyo.'),
('127b1bd7-79a3-40d4-ae61-01f11954e30f', '21cf146b-a422-4384-88c0-432a49cbe6e1', 'en', 'Ring Bent Arm Bent Body Press Handstand', 'On the rings, press your body from a bent position into a vertical handstand with arms bent at the start.'),
('2936ee61-9ea0-4af1-b15f-1a18fec27f92', '21cf146b-a422-4384-88c0-432a49cbe6e1', 'es', 'Bent Arm Bent Body Press Handstand en anillas', 'En las anillas, presiona el cuerpo desde una posición flexionada hasta la parada de manos vertical con los brazos doblados al inicio.'),
('c478a678-fb19-46c4-a187-b2695675e152', '21d8fe64-48d7-44db-a058-202870d05930', 'en', 'Double Kettlebell Front Rack Split Squat', 'With kettlebells in the rack position, perform a split squat lowering the back knee vertically, challenging torso stability.'),
('7ced07af-8631-4afc-97c7-02c57fd2db63', '21d8fe64-48d7-44db-a058-202870d05930', 'es', 'Sentadilla Split Front Rack con Kettlebell doble', 'Con Kettlebells en posición rack, realiza una sentadilla dividida bajando la rodilla trasera verticalmente, desafiando la estabilidad del torso.'),
('c42034d5-e575-4ff8-973f-4161dc4f2d1d', '21e84bed-cbe9-40c5-834b-ac8b9bdb6fdb', 'en', 'Landmine Zercher Skater Squat', 'Hold the Landmine bar in the crook of the elbows (Zercher) and perform a skater squat, lowering the back knee toward the floor.'),
('80f533e6-c663-4e65-82ee-ff973c67836c', '21e84bed-cbe9-40c5-834b-ac8b9bdb6fdb', 'es', 'Sentadilla patinadora Zercher en Landmine', 'Sujeta la barra Landmine en el pliegue de los codos (Zercher) y realiza una sentadilla patinadora, bajando la rodilla trasera hacia el suelo.'),
('26360d05-3614-44c7-9b4c-fd6360158261', '22403a43-8ffd-4cb9-af6b-2edc7bd9196a', 'en', 'Ab Wheel Kneeling Rollout', 'Kneeling, hold the wheel in front of you. Roll forward extending your body as far as you can without arching your lower back, then use your abs to return.'),
('fd8a62ef-f64f-4e45-b260-29aa8a63b378', '22403a43-8ffd-4cb9-af6b-2edc7bd9196a', 'es', 'Rollout de rodillas con rueda abdominal', 'De rodillas, sujeta la rueda frente a ti. Rueda hacia adelante extendiendo el cuerpo tanto como puedas sin arquear la espalda baja, luego usa el abdomen para regresar.'),
('a1b0d18f-5e5c-4dbd-9820-35b574b723ce', '2255347b-b5c2-42bc-b7e2-d8fa80fb47d9', 'en', 'Strict Kneeling Ab Rollout', 'Slide the ab wheel forward while keeping a firm core and return. Objective: rectus abdominis. Cue: don''t let your hips sag. Common error: arching the lower back when extending.'),
('eac4b556-365b-499d-be12-c3f686a7625d', '2255347b-b5c2-42bc-b7e2-d8fa80fb47d9', 'es', 'Ab rollout desde rodillas estricto', 'Desliza la rueda abdominal adelante manteniendo core firme y vuelve. Objetivo: recto abdominal. Cue: no dejes caer la cadera. Error común: arquear la espalda lumbar al estirar.'),
('3b520f36-1c66-4ff4-a6e3-18ec251accbd', '226e29cd-ea25-4008-9db0-c61ec6625dd0', 'es', 'TRX Sierra abdominal', 'En plancha con pies en agarres, desliza el cuerpo atrás y adelante moviendo solo hombros. Core bloqueado. Espalda neutra. No eleves el glúteo.'),
('6970eb27-1387-422c-97ca-874cd5dc2e46', '22af6770-5bb1-42d5-a5f9-dc8d813836ef', 'en', 'Ring Inverted Hang', 'Maintain a vertical upside-down body position hanging from the rings, stabilizing the position with locked arms and an active core.'),
('97b960f4-a341-4468-8178-26c8a00742a4', '22af6770-5bb1-42d5-a5f9-dc8d813836ef', 'es', 'Colgado invertido en anillas', 'Manten el cuerpo vertical boca abajo colgado de las anillas, estabilizando la posicion con los brazos bloqueados y el core activo.'),
('02cbfafa-81f2-44c0-8ccf-d3a3f3441e77', '22b292d9-8307-4e1e-b199-b1b28fb56fa0', 'en', 'Smith Machine Feet-Forward Quadriceps Squat', 'Guided squat with feet forward. Cue: back against the bar. Error: feet too far back.'),
('aa5460c7-c4a0-411a-8992-69da7b959819', '22b292d9-8307-4e1e-b199-b1b28fb56fa0', 'es', 'Sentadilla Smith pies adelantados cuádriceps', 'Sentadilla guiada con pies adelante. Cue: espalda contra barra. Error: pies muy atrás.'),
('45e47f8a-3c30-4c9d-93a0-caa703593f83', '22bfbcec-8e47-45ba-a9d9-2eea62433733', 'en', 'Battle Ropes Double Slams', 'Bring both ropes up and slam them against the floor with force using the entire body. Explosive power. Neutral back. Do not bend the lower back.'),
('2e8ac8e5-e460-496a-b826-0e0d0f8a9a92', '22bfbcec-8e47-45ba-a9d9-2eea62433733', 'es', 'Battle Ropes Golpes dobles', 'Lleva ambas cuerdas arriba y golpéalas contra el suelo con fuerza usando todo el cuerpo. Potencia explosiva. Espalda neutra. No dobles la espalda baja.'),
('b1642fdc-6047-441e-9efd-235839b0e9cd', '22cd7a43-3737-4e56-8e86-5f9aef5bb070', 'en', 'Landmine Russian Twist with Feet Elevated', 'Seated with feet in the air, hold the bar and rotate it from side to side crossing the torso for an advanced abdominal challenge.'),
('c50efa76-dd87-4840-b835-b4ed839eee65', '22cd7a43-3737-4e56-8e86-5f9aef5bb070', 'es', 'Russian Twist con pies elevados en Landmine', 'Sentado con los pies en el aire, sujeta la barra y gírala de lado a lado cruzando el torso para un reto abdominal avanzado.'),
('85512172-a8c6-4c29-b0cf-251bcf3e8cc2', '235f02cc-1884-4d90-9a7f-eaf61937f666', 'en', 'Bodyweight Side Plank', 'Lie on your side supported on one forearm. Lift your hips until your body forms a straight line and maintain the position by engaging the obliques.'),
('bc02f39d-845a-4615-91bc-8ea59d577e28', '235f02cc-1884-4d90-9a7f-eaf61937f666', 'es', 'Plank lateral', 'Acuéstate de lado apoyado en un antebrazo. Levanta las caderas hasta que el cuerpo forme una línea recta y mantén la posición activando los oblicuos.'),
('70116567-e2b9-467d-920d-24a51b526706', '2383fa64-7332-4dd0-a5b4-a8211e949670', 'en', 'Cable Straight Bar Front Raise', 'Back to the low pulley with the cable between the legs. Lift the straight bar forward to shoulder height.'),
('113263a5-1618-4d7c-8546-5e844015b08f', '2383fa64-7332-4dd0-a5b4-a8211e949670', 'es', 'Elevación frontal con barra recta en cable', 'De espaldas a la polea baja con el cable entre las piernas. Levanta la barra recta hacia adelante hasta la altura de los hombros.'),
('a6174866-2aec-4ab0-b794-49c028937532', '2393be28-bed0-4705-b5f4-654681651ca8', 'en', 'Dumbbell Bicep Curl', 'Standing or seated, with a dumbbell in each hand and arms extended, flex elbows bringing dumbbells toward shoulders. You can perform the movement alternating arms, simultaneously, or with wrist rotation (supinating curl). Keep elbows fixed.'),
('e7353e70-7241-4905-bb71-1fa61d896307', '2393be28-bed0-4705-b5f4-654681651ca8', 'es', 'Curl bíceps mancuernas', 'De pie o sentado, con una mancuerna en cada mano y los brazos extendidos, flexiona los codos llevando las mancuernas hacia los hombros. Puedes realizar el movimiento alternando brazos, simultáneamente, o con rotación de muñeca (curl supinador). Mantén los codos fijos.'),
('793e1df7-231f-4cea-bfde-d537f983904e', '23976a67-ed2a-4ff5-938c-d7c58432856f', 'en', 'TRX Side Plank with Rotation', 'In a side plank position with feet in the TRX, bring the free arm under the torso rotating the waist and extend it back upward.'),
('04bbbd0c-d980-4b57-8d01-2b2c68eefd50', '23976a67-ed2a-4ff5-938c-d7c58432856f', 'es', 'Side Plank con rotación en TRX', 'En posicion de plancha lateral con los pies en el TRX, lleva el brazo libre por debajo del torso rotando la cintura y vuelve a extenderlo hacia arriba.'),
('b5e2b202-ba8a-478a-b510-78a6c792d175', '23c7da08-d53c-4d5a-9d47-db86a4e672d5', 'en', 'Barbell Shrugs', 'Standing holding a bar with straight arms, lift shoulders toward ears contracting the trapezius and lower in a controlled manner.'),
('be5f55ca-e425-44d8-9686-b7d53af5bafe', '23c7da08-d53c-4d5a-9d47-db86a4e672d5', 'es', 'Encogimiento de hombros con barra', 'De pie sosteniendo una barra con los brazos estirados, eleva los hombros hacia las orejas contrayendo los trapecios y baja controladamente.'),
('cd5936d7-7c9c-4606-b675-cbf06b4b85b2', '23d6b994-067a-4311-af5d-9cbaf9313568', 'en', 'One-Arm Fitball Dumbbell Chest Press', 'Support the back on the Fitball holding a single dumbbell. Perform the chest press keeping hips high and the core stable to avoid rotating.'),
('46a62212-37a0-46f7-8ec8-7365fb5ddefd', '23d6b994-067a-4311-af5d-9cbaf9313568', 'es', 'Press de pecho con mancuerna a una mano en Fitball', 'Apoya la espalda en el Fitball sosteniendo una sola mancuerna. Realiza el press de pecho manteniendo las caderas altas y el core estable para evitar girar.'),
('37aca16f-a67e-4b52-af4d-8ab94692c42f', '23ee0621-5b4c-46e0-90e4-ce13e49c2c6d', 'en', 'Nordic Hamstring Curl', 'Kneeling with ankles anchored, lower the torso toward the floor in a slow and controlled manner using only your hamstrings.'),
('86886b40-1df0-419c-bd7b-793abba27bd5', '23ee0621-5b4c-46e0-90e4-ce13e49c2c6d', 'es', 'Curl Nórdico de isquiotibiales', 'De rodillas con los tobillos anclados, baja el torso hacia el suelo de forma lenta y controlada usando solo tus isquiotibiales.'),
('1923dd0a-2cab-4dc9-a4c0-6f444ab81f06', '240a151d-051b-4bbb-b245-3317c49975c1', 'en', 'Straight Bar Cable Bicep Curl', 'Flex the bar connected to low pulley maintaining tension. Objective: bicep hypertrophy. Cue: do not move elbows. Common error: swinging back with the spine.'),
('ac1277b2-b625-470b-bdb0-5d62f7a025c7', '240a151d-051b-4bbb-b245-3317c49975c1', 'es', 'Curl de bíceps en polea con barra recta', 'Flexiona la barra con palmas arriba. Objetivo: tensión constante. Cue: codos fijos a los costados. Error común: balancear el torso para ayudar a subir.'),
('bffa0305-95b9-40a5-82da-391821ea600c', '2424c046-7f4a-45ec-ad1d-742ce0337dc9', 'en', 'Simultaneous Dumbbell Floor Press', 'Floor press with weights. Cue: lower back supported. Error: lifting the back.'),
('3a5db284-6657-4ea9-b511-a9d797589f7f', '2424c046-7f4a-45ec-ad1d-742ce0337dc9', 'es', 'Floor Press mancuernas simultáneo', 'Press en suelo con pesas. Cue: lumbar apoyada. Error: despegar espalda.'),
('3d730e9a-5bc1-464c-950b-24494e4d5933', '2449179e-bea3-4f2c-a5a5-2c0db7f6a2e4', 'en', 'Seated Lateral Raises', 'Lift weights to the sides while seated. Objective: lateral deltoid. Cue: shoulders down. Error: swinging.'),
('dba44957-9157-40de-9da3-0679efb293cf', '2449179e-bea3-4f2c-a5a5-2c0db7f6a2e4', 'es', 'Elevaciones laterales sentado', 'Eleva pesas a los lados sentado. Objetivo: deltoides lateral. Cue: hombros bajos. Error: balanceo.'),
('ed6d6561-3587-4a98-a90a-05ceb836cb9a', '244d3b1a-e083-40e7-8ccf-9cc68ca161d0', 'en', 'Double Kettlebell Hollow Body Flutter Kicks', 'In a hollow body position, hold two kettlebells over your chest and perform controlled flutter kicks with your legs.'),
('edc9aca9-5860-43f3-a32e-9920902eb384', '244d3b1a-e083-40e7-8ccf-9cc68ca161d0', 'es', 'Hollow Body Flutter Kicks con Kettlebell doble', 'En posición de Hollow Body, sostén dos Kettlebells sobre tu pecho y realiza patadas de aleteo controladas con las piernas.'),
('11c1d6f4-ae56-461d-a240-76e1cc708dcd', '245130b7-1619-4bad-b7dd-fd7cbafffdbc', 'en', 'Bottoms Up Front Rack Slider Kettlebell Reverse Lunge', 'With two inverted kettlebells at the chest, slide one foot back on a slider in a controlled reverse lunge.'),
('e6501421-6e15-44d2-9791-0c089ef9ab8f', '245130b7-1619-4bad-b7dd-fd7cbafffdbc', 'es', 'Zancada inversa Slider Kettlebell Bottoms Up Front Rack', 'Con dos pesas rusas invertidas en el pecho, desliza un pie hacia atrás en un slider en una zancada inversa controlada.'),
('b17fa653-e18d-48f0-90a1-9707e5350a56', '24571e7f-85c9-491f-8703-e003a4aec53d', 'en', 'One-Arm Dumbbell Row', 'Support one hand and knee on a bench, keeping the back parallel to the floor. With the free hand, row the dumbbell toward the hip keeping the elbow close to the body. Avoid rotating the torso. This unilateral exercise allows for greater concentration on each side.'),
('a2c8c76f-b2f3-467f-a1b9-51d926d00a25', '24571e7f-85c9-491f-8703-e003a4aec53d', 'es', 'Remo a una mano mancuernas', 'Apoya una mano y rodilla en un banco, manteniendo la espalda paralela al suelo. Con la mano libre, rema la mancuerna hacia la cadera manteniendo el codo cerca del cuerpo. Evita rotar el torso. Este ejercicio unilateral permite mayor concentración en cada lado.'),
('b5131a2d-ce1a-44e9-814c-6d550ebafaec', '2472e46d-4e5b-485a-957a-a1bd13a9273b', 'en', 'Bodyweight Plate Plyometric Push Up', 'Perform an explosive push-up driving the body upward so that the hands land on elevated plates placed at the sides, working chest power.'),
('8eee2e7c-28e2-4083-a23d-7c775bed9948', '2472e46d-4e5b-485a-957a-a1bd13a9273b', 'es', 'Flexiones pliométricas con placa', 'Realiza una flexion explosiva empujando el cuerpo hacia arriba para que las manos aterricen sobre discos elevados situados a los lados, trabajando la potencia pectoral.'),
('948a56a3-4aec-481a-a622-56e0a0a5186e', '24809f67-b54b-42a6-b949-f99c8284f455', 'en', 'Barbell Back Rack Bulgarian Split Squat', 'Perform a split squat with the rear foot elevated while holding the barbell on your upper traps, keeping the torso upright.'),
('6a58e4e5-af9a-4fb0-bb4a-a2a34672a04b', '24809f67-b54b-42a6-b949-f99c8284f455', 'es', 'Sentadilla Búlgara búlgara con barra trasera', 'Realiza una sentadilla split con el pie trasero elevado sosteniendo la barra sobre los trapecios, manteniendo el torso erguido.'),
('dc46e6d7-8fe6-43cb-b826-8b2b8370e91f', '24e51369-c1dd-4dee-acc7-8db3e5ba81c0', 'es', 'Press Pallof con banda', 'De pie y de lado al anclaje, sujeta la banda al pecho y extiéndela al frente resistiendo que la banda te gire. Objetivo: anti-rotación del core. Cue: pies bien anclados al suelo. Error: girar el torso hacia el anclaje.'),
('62cb575a-20d3-4a73-ab3f-f2a3aa9109db', '24eb3623-97e9-40db-b7e3-f81ea33f3f52', 'en', 'Double Kettlebell Bottoms Up Overhead Alternating Cossack Squat', 'Hold two upside-down kettlebells locked out overhead. Perform a deep lateral squat alternating sides, requiring exceptional motor control and mobility.'),
('03eb4b5b-0ba5-4e31-a325-df2de29ad25b', '24eb3623-97e9-40db-b7e3-f81ea33f3f52', 'es', 'Sentadilla Cosaca alterna Overhead con Kettlebell doble Bottoms Up', 'Sostén dos Kettlebells invertidas bloqueadas sobre la cabeza. Realiza una sentadilla lateral profunda alternando lados, lo que exige un control motor y movilidad excepcionales.'),
('3ae61cf9-0769-483c-b8a7-be756e809a16', '255118ae-52e1-4d65-ba52-650d8b710973', 'en', 'Wide Grip Low Row', 'Pull the wide bar to the abdomen while seated. Objective: upper back. Cue: elbows back. Error: raising shoulders.'),
('b6feb058-309b-45dd-9349-1f674fbb4dc5', '255118ae-52e1-4d65-ba52-650d8b710973', 'es', 'Remo bajo agarre ancho', 'Tira barra ancha al abdomen sentado. Objetivo: espalda alta. Cue: codos atrás. Error: subir hombros.'),
('1ef6a783-b09a-44c6-adf8-606088b1045b', '255a9da6-43b4-447f-95da-d5a0aa827e92', 'en', 'Dumbbell Lateral Lunge (Arms Down)', 'Side step with weights at the sides. Cue: hips back. Error: tilting the torso.'),
('8bdf82df-a297-4a43-b077-0ad7ca117c05', '255a9da6-43b4-447f-95da-d5a0aa827e92', 'es', 'Zancada lateral mancuernas brazos abajo', 'Paso lateral con pesas a los lados. Cue: cadera atrás. Error: inclinar torso.'),
('6abae173-f93d-4952-b5ec-fb189d740415', '255b9a32-64e0-4ed0-b790-387d50b9e14e', 'en', 'Stability Ball Sit Up', 'Perform a full abdominal crunch while sitting on the stability ball or with legs resting on it, focusing the work on the rectus abdominis.'),
('adc38423-ad4f-4f0f-9d3a-b04fa06de32a', '255b9a32-64e0-4ed0-b790-387d50b9e14e', 'es', 'Sit Up con Fitball', 'Realiza una flexión abdominal completa sentado sobre el Fitball o con las piernas apoyadas en él, enfocando el trabajo en el recto abdominal.'),
('61be7dc1-5dc9-474a-9f8c-e143bb8dea96', '2566ef8c-3699-4473-aca3-f6e974fb8124', 'en', 'Barbell French Press', 'Lying on a bench, hold the bar with arms extended vertically. Lower the bar toward the forehead or behind the head flexing only the elbows. Keep elbows pointing forward and relatively together throughout the movement.'),
('27c0a7c5-794c-49a2-819c-b8384f34f4bb', '2566ef8c-3699-4473-aca3-f6e974fb8124', 'es', 'Press francés barra', 'Tumbado en banco, sostén la barra con brazos extendidos verticalmente. Desciende la barra hacia la frente o detrás de la cabeza flexionando solo los codos. Mantén los codos apuntando hacia adelante y relativamente juntos durante todo el movimiento.'),
('1a874a34-c40d-4246-9ef2-6df3ac8365ad', '257c23f1-194f-400a-b623-e234070865f3', 'en', 'Barbell 21s Curl', 'Advanced technique consisting of 7 repetitions from the starting position to the halfway point, 7 from the halfway point to the top, and 7 full repetitions, totaling 21 repetitions without rest. Provides a unique stimulus and intense bicep pump.'),
('d1459875-0fb6-4152-aab9-81a55c543f7d', '257c23f1-194f-400a-b623-e234070865f3', 'es', 'Curl 21s barra', 'Técnica avanzada que consiste en 7 repeticiones desde la posición inicial hasta la mitad, 7 desde la mitad hasta arriba, y 7 completas, totalizando 21 repeticiones sin descanso. Proporciona un estímulo único y una congestión intensa en el bíceps.'),
('6f58df78-82db-4f22-a1dd-7029fef89ea7', '25c05b88-7c63-4fdd-916e-2853471549f1', 'en', 'Machine Lateral Raises', 'Seated or standing depending on design, lift arms laterally against pads. The machine provides constant resistance and eliminates momentum. Excellent for isolating the middle deltoid in a controlled manner.'),
('70b89f17-c802-44f6-9aba-45686a743e39', '25c05b88-7c63-4fdd-916e-2853471549f1', 'es', 'Elevaciones laterales máquina', 'Sentado o de pie según el diseño, eleva los brazos lateralmente contra las almohadillas. La máquina proporciona resistencia constante y elimina el impulso. Excelente para aislar el deltoides medio de forma controlada.'),
('b3ed8da0-c355-41e8-944f-664dcd550e10', '25d45d3b-0365-427e-8bd3-3ff67ccb7278', 'en', 'Double Kettlebell Single Leg Romanian Deadlift', 'Hinge the torso forward while lifting one leg back, holding a kettlebell in each hand to work on balance and the posterior chain.'),
('56bfbfc6-5029-4bf0-b838-dccea838cbe2', '25d45d3b-0365-427e-8bd3-3ff67ccb7278', 'es', 'Peso muerto rumano a una pierna con Kettlebell doble', 'Baja el torso hacia adelante mientras elevas una pierna atrás, sosteniendo una Kettlebell en cada mano para trabajar el equilibrio y la cadena posterior.'),
('32e9bac4-432e-4cac-bb6e-d4aa1a73b67e', '25f39a79-e4da-433b-8ab3-81d81524bd23', 'en', 'Barbell Shrugs', 'With the bar hanging in front of the thighs, lift shoulders directly toward ears as high as possible. Hold contraction for one second and lower controlled. Do not rotate shoulders; movement is purely vertical. Develops upper trapezius.'),
('0fdb5162-8e68-436a-99ac-9716187e657d', '25f39a79-e4da-433b-8ab3-81d81524bd23', 'es', 'Shrugs barra', 'Con la barra colgando frente a los muslos, eleva los hombros directamente hacia las orejas lo más alto posible. Mantén la contracción por un segundo y desciende controladamente. No rotes los hombros; el movimiento es puramente vertical. Desarrolla los trapecios superiores.'),
('9f0b2846-e348-4043-ad95-fea299b84b18', '2674e3d0-8a57-43af-a9d9-be3f37bc881a', 'en', 'Ab Wheel Rollout', 'Slide the wheel forward from knees while keeping the abdomen contracted. Objective: core strength. Cue: do not let the hips sag. Common error: arching the lower back.'),
('83362350-f5e0-4313-b10a-92168688de58', '2674e3d0-8a57-43af-a9d9-be3f37bc881a', 'es', 'Rueda abdominal (Ab Wheel Rollout)', 'Desliza la rueda hacia adelante desde rodillas manteniendo el abdomen contraído. Objetivo: fuerza del core. Cue: no dejes que la cadera se hunda. Error común: arquear la espalda lumbar.'),
('e071dc87-2c37-4777-884c-fbe106f93253', '2698f490-35a7-49fa-a265-137d8c6bee05', 'en', 'Seated Pectoral Machine Flyes', 'Bring arms together in Pec Deck. Cue: chest out. Error: shrugging shoulders.'),
('bef7ffbb-df55-499c-af47-0e31c7c750b2', '2698f490-35a7-49fa-a265-137d8c6bee05', 'es', 'Aperturas máquina sentado pectoral', 'Junta brazos en Peck Deck. Cue: pecho fuera. Error: encoger hombros.'),
('9f27af03-a918-4eb4-84db-d3b61cca1c60', '26d75dfe-dc0a-4fff-bf35-8f687f33164c', 'en', 'Paused Barbell Squat', 'Lower into a squat and maintain the bottom position for 2 seconds before rising. Objective: power from the start. Cue: constant tension. Common error: relaxing and losing posture at the bottom.'),
('149212ef-9756-485f-94c3-079362bd3b39', '26d75dfe-dc0a-4fff-bf35-8f687f33164c', 'es', 'Sentadilla con pausa (barra)', 'Baja en sentadilla y mantén la posición fondo 2 segundos antes de subir. Objetivo: potencia de salida. Cue: tensión constante. Error común: relajarse y perder la postura abajo.'),
('d4925459-65ae-4140-af27-fb51e4179237', '26e35ad0-e399-4be5-86f1-7a6baed1deb4', 'en', 'Cable Bent-Knee External Hip Rotation', 'Standing with one leg hooked to the cable and knee bent at 90 degrees. Rotate the leg outward against the resistance.'),
('2df81608-e803-4448-8900-ec52b495a47d', '26e35ad0-e399-4be5-86f1-7a6baed1deb4', 'es', 'Rotación externa de cadera con rodilla doblada en cable', 'De pie con una pierna enganchada al cable y rodilla doblada a 90 grados. Rota la pierna hacia afuera contra la resistencia.'),
('6b515cc9-34cf-41b2-a72f-a4ddf98dc513', '26ea7a6a-2b95-4cfd-8f70-f261eca0311d', 'en', '45-Degree Bench Hip Extension', 'Lower and raise the torso locking the lower back to use only glutes and hams. Cue: squeeze glutes at the top. Error: hyperextending the back.'),
('4341fa2c-fd87-4cf0-9a99-99db6e42d3ce', '26ea7a6a-2b95-4cfd-8f70-f261eca0311d', 'es', 'Extensión cadera banco 45 grados', 'Baja y sube el torso bloqueando la zona lumbar para usar solo glúteos e isquios. Cue: aprieta glúteos arriba. Error: hiperextender la espalda.'),
('addc196e-0b56-4c8c-8d1c-82e1c7c5aff5', '26eb5af3-91df-4ae0-81dd-98a0e901ae9f', 'en', 'Slider Double Kettlebell Front Rack Lateral Lunge', 'Hold two Kettlebells at the chest (Front Rack). Use a slider under one foot to slide into a lateral lunge and rise back up.'),
('1c09c9aa-16eb-45a6-86ef-4a61b3663d52', '26eb5af3-91df-4ae0-81dd-98a0e901ae9f', 'es', 'Zancada lateral Front Rack con Slider y Kettlebell', 'Sostén dos Kettlebells en el pecho (Front Rack). Usa un slider bajo un pie para deslizarte en una zancada lateral y volver a subir.'),
('37a7f248-8b3a-47ee-8d8d-00ddd221d889', '26fc4f7e-f1d1-416d-82dc-fffe3cc1a5f2', 'en', 'Elastic Band Shoulder Press', 'Step on the band and push the ends over your head until arms are extended. Objective: deltoids. Cue: arms fully straightened at the top. Error: arching the lumbar area to compensate.'),
('8017f254-5fb4-4c35-b4b3-14d88e82c691', '26fc4f7e-f1d1-416d-82dc-fffe3cc1a5f2', 'es', 'Press de hombro con banda elástica', 'Pisa la banda y empuja los extremos sobre tu cabeza hasta extender los brazos. Objetivo: deltoides. Cue: brazos totalmente estirados arriba. Error: arquear la zona lumbar para compensar.'),
('8c51878e-2c39-4507-a248-26a3b4f93b69', '26ff931d-0709-4373-9dfa-d7842162c259', 'es', 'Zancada inversa contralateral a Press de hombro en Landmine', 'Realiza una zancada inversa cargando la barra en el hombro opuesto a la pierna que retrocede, y al subir completa un press de hombro.'),
('1309728c-c81c-44fe-bc1d-c9dc77afc5f7', '27010114-eec4-488b-a23c-5faeb6e0dfce', 'en', 'Kneeling Overhead Cable Rope Triceps Extension', 'Kneeling with your back to the pulley, extend your arms upward and forward using the rope, isolating the movement in the triceps.'),
('0be02864-dd98-4373-9b80-13b8e99c31f9', '27010114-eec4-488b-a23c-5faeb6e0dfce', 'es', 'Extensión Overhead de tríceps arrodillado con cuerda', 'De rodillas de espaldas a la polea, extiende los brazos hacia arriba y adelante usando la cuerda, aislando el movimiento en el triceps.'),
('c828472a-59a0-41a2-8883-f283603195bc', '274d6ddb-210d-4e14-863d-04f7fe0274b3', 'en', 'Bodyweight Foot Elevated Knee Over Toe Split Squat', 'With the rear foot on a bench, lower into a deep lunge driving the front knee over the toes to load the quadriceps.'),
('992eff99-5859-4d2b-9872-3dcc43967185', '274d6ddb-210d-4e14-863d-04f7fe0274b3', 'es', 'Sentadilla Búlgara rodilla sobre punta del pie (Pies elevados)', 'Con el pie trasero en banco, baja en zancada profunda llevando la rodilla delantera sobre los dedos para cargar el cuadriceps.'),
('d9fc1f4f-fcb6-4032-9889-3e7c61f6c5ba', '27509cdf-5a6b-422b-acb0-7cd5017c42a2', 'en', 'Fitball Hamstring Curl', 'Lying down, feet on the ball, lift hips and flex knees bringing the ball in. Posterior chain. High hips. Do not rest glutes when lowering.'),
('e0a63ce7-0d40-4c24-90cd-57ef1d84da1f', '27509cdf-5a6b-422b-acb0-7cd5017c42a2', 'es', 'Fitball Curl de isquios', 'Tumbado, pies en la bola, eleva cadera y flexiona rodillas trayendo la bola. Cadena posterior. Cadera alta. No apoyes el glúteo al bajar.'),
('ed34bf69-8ffb-4222-b903-cd6d31062751', '276ede27-9467-49c0-ae00-1f724a45011c', 'en', 'Tibialis Raises', 'Tibialis anterior elevation (dorsiflexion) to balance the ankle and aid in preventing shin splints/injuries.'),
('a6a43f24-3d12-4fc9-b56d-64f1fe4322fe', '276ede27-9467-49c0-ae00-1f724a45011c', 'es', 'Elevaciones de tibiales', 'Levanta la punta del pie hacia la espinilla con control. No balancees; busca quemazón en la parte frontal de la pierna.'),
('357d1443-7c6a-4836-a5fd-a7bae129b57b', '27824fea-c6be-42b6-aa31-b32f0007b8af', 'en', 'One-Arm One-Leg Push Ups', 'Push-up supported by only one hand and the opposite foot. Maximum challenge of stabilization and strength. Requires exceptional core control to prevent rotation. Only possible after mastering traditional one-arm push-ups.'),
('b48b74fd-7f77-4f89-a57b-9d213d6c8096', '27824fea-c6be-42b6-aa31-b32f0007b8af', 'es', 'Flexiones a un brazo y pierna', 'Flexión apoyado solo en una mano y el pie opuesto. Máximo desafío de estabilización y fuerza. Requiere control excepcional del core para evitar rotación. Solo posible tras dominar flexiones a un brazo tradicionales.'),
('0f166361-3105-4702-b9e2-a649eababb52', '279b1957-988b-4c0c-a335-988f99aafe4a', 'en', 'Alternating Single Arm Kettlebell Around the World High Catch to Squat', 'Pass the weight around the waist, catch it with both hands in front of the chest, and immediately perform a deep squat.'),
('f162bce6-7496-4ef5-858b-9aa28128b12c', '279b1957-988b-4c0c-a335-988f99aafe4a', 'es', 'Alrededor del mundo con captura para sentadilla', 'Pasa la pesa alrededor de la cintura, capturala con ambas manos frente al pecho y realiza una sentadilla profunda inmediatamente.'),
('5ecc3738-b344-4d04-90d1-929a54a2293a', '27cbc96a-0434-4e40-ac76-c94379e84b5e', 'en', 'Ring Straight Arm L Sit Straddle Press Handstand', 'From a ring L-sit, spread legs in a straddle and press with straight arms until reaching a vertical inverted position.'),
('53943e3d-8913-4931-866f-95d913b9d58f', '27cbc96a-0434-4e40-ac76-c94379e84b5e', 'es', 'Ring L-Sit Straddle Press a parada de manos', 'Desde un L-Sit en anillas, abre las piernas en V y presiona con los brazos rectos hasta alcanzar la posicion vertical invertida.'),
('5d2c44f2-dc99-49ef-9e02-337a9a19114d', '284681da-fd83-4cb1-9e4e-4cbb857d69d0', 'en', 'Hindu Push Ups', 'Begin in downward dog position, lower chest toward the floor in a fluid forward motion, then arch back lifting the chest as arms extend. Reverse movement to return. Combines strength, flexibility, and coordination in a continuous wave pattern.'),
('f71d84f2-72c2-4374-81d1-2c71a26f8bba', '284681da-fd83-4cb1-9e4e-4cbb857d69d0', 'es', 'Flexiones hindu', 'Comienza en posición de perro boca abajo, desciende el pecho hacia el suelo en un movimiento fluido hacia adelante, luego arquea la espalda elevando el pecho mientras los brazos se extienden. Invierte el movimiento para volver al inicio. Este ejercicio combina fuerza, flexibilidad y coordinación en un patrón ondulatorio continuo.'),
('021b9c0a-784d-4d79-a0dd-5553b5f9ac9f', '2847c1b6-27df-42ec-9baa-2b2831b57846', 'en', 'Double Kettlebell Bottoms Up Overhead Step Up', 'Perform a step up while maintaining two upside-down kettlebells locked out overhead, the ultimate challenge of stability and strength.'),
('6f00b1b3-a333-4349-a05b-cfa5bfe0c12b', '2847c1b6-27df-42ec-9baa-2b2831b57846', 'es', 'Step Up Overhead con Kettlebell doble Bottoms Up', 'Realiza un step up manteniendo dos Kettlebells invertidas bloqueadas sobre la cabeza, el reto máximo de estabilidad y fuerza.'),
('ca3d083c-26e3-4a59-bf16-cdf40bf7dcc9', '2852515f-4829-4015-af16-764d4337233c', 'en', 'Double Kettlebell Bottoms Up Bench Press', 'Lying on the bench, press two upside-down kettlebells toward the ceiling, focusing on grip control and shoulder stability.'),
('ae991326-02c7-46e3-80de-a56d913ae994', '2852515f-4829-4015-af16-764d4337233c', 'es', 'Press de banca con Kettlebell doble Bottoms Up', 'Tumbado en el banco, presiona dos Kettlebells invertidas hacia el techo, enfocándote en el control del agarre y estabilidad del hombro.'),
('3d6aaef9-1b3d-49ec-af97-94e155bbaa63', '28795b71-5318-47ab-8ea5-9185e9906f67', 'en', 'Fitball Crunch', 'Lying on the fitball with the lower back supported, perform torso flexions. The ball allows for a greater range of motion than the floor. Keep feet firm for stability. Do not pull on the neck; use the abdominals.'),
('0be2f862-a2d4-4155-9ab2-e42424ad3c8e', '28795b71-5318-47ab-8ea5-9185e9906f67', 'es', 'Crunch fitball', 'Tumbado sobre la fitball con la espalda baja apoyada, realiza flexiones de tronco. La pelota permite mayor rango de movimiento que el suelo. Mantén los pies firmes para estabilidad. No tires del cuello, usa los abdominales.'),
('6b0d9ee3-a6b1-471e-bb5c-7e7f7c05b861', '287ffea5-2140-40fd-bd7f-d522497b495a', 'en', 'Bicycle Crunches', 'Lying down, bring your elbow toward the opposite knee while straightening the other leg. Objective: obliques and rectus abdominis. Cues: fluid and rhythmic movement. Common error: pulling the neck with the hands.'),
('aa57e0c6-a5a6-4b5d-b8ef-9c8af7b7dae9', '287ffea5-2140-40fd-bd7f-d522497b495a', 'es', 'Abdominales tipo bicicleta', 'Tumbado, lleva el codo hacia la rodilla opuesta mientras estiras la otra pierna. Objetivo: oblicuos y recto abdominal. Cues: movimiento fluido y rítmico. Error común: tirar del cuello con las manos.'),
('c2e4c1d7-5b8a-40c2-9d97-68adebb1cec5', '2899bdf9-49ac-48e8-876f-402562ef4956', 'en', 'Dumbbell Bulgarian Split Squat', 'Perform a split squat with the back foot elevated on a bench, holding two dumbbells at the sides for added resistance.'),
('cc55df33-9fff-4deb-9292-c4d332c6269f', '2899bdf9-49ac-48e8-876f-402562ef4956', 'es', 'Sentadilla Split Búlgara con mancuernas', 'Realiza una sentadilla split con el pie trasero elevado en un banco, sosteniendo dos mancuernas a los lados para mayor resistencia.'),
('377f64a8-708b-468b-b75c-6d0716ea9f74', '28a176bc-0ad6-4281-9f59-624895e6fa26', 'en', 'Strict Mid Pulley Pectoral Flyes', 'Bring hands together in front on a pulley. Cue: elbows slightly bent. Error: shrugging shoulders.'),
('ef423e72-8c94-4391-83dc-4a81fb38a03f', '28a176bc-0ad6-4281-9f59-624895e6fa26', 'es', 'Aperturas pectoral polea media estricto', 'Junta manos al frente en polea. Cue: codos semiflexionados. Error: encoger hombros.'),
('9abcf108-7ae7-4f86-be50-2d7aaf9bad3a', '28bcdd2e-4d88-4604-9be2-d07949937811', 'en', 'Ring Tuck Planche', 'Support your weight on the rings with locked arms and knees tucked toward your chest, keeping your back parallel to the floor.'),
('cb5389b8-c684-48fe-9a5c-31735f4bdb1d', '28bcdd2e-4d88-4604-9be2-d07949937811', 'es', 'Plancha de pliegue de Anillas', 'Sostén tu peso en las anillas con brazos bloqueados y las rodillas encogidas hacia el pecho, manteniendo la espalda paralela al suelo.'),
('5c66e7dc-d0ef-47e9-821c-f13863f62244', '28be0175-4955-4b9b-861f-be31675d6f13', 'en', 'Explosive One-Arm Row', 'Unilateral row with maximum acceleration. Allows for using more weight than a strict row. The dumbbell should go up explosively but controlled on the descent. Do not let momentum compromise form.'),
('489cb36c-b4f6-4bce-952b-d6d9ac4fd1e3', '28be0175-4955-4b9b-861f-be31675d6f13', 'es', 'Remo un brazo explosivo', 'Remo unilateral con aceleración máxima. Permite usar más peso que remo estricto. La mancuerna debe subir explosivamente pero controlada en el descenso. No dejes que el impulso comprometa la forma.'),
('5ba3f5b5-f99f-4d59-a74a-61be9a7d149f', '28febd34-5c28-4804-adb6-f3ccf82a9e5f', 'en', 'Hiperextension on Fitball', 'Support abdomen on the Fitball with feet anchored. Raise the torso extending the lower back and squeeze glutes at the top.'),
('b47b57de-8eb8-46b5-a4f7-8cb8f5b49ef9', '28febd34-5c28-4804-adb6-f3ccf82a9e5f', 'es', 'Hiperextensión sobre Fitball', 'Apoya el abdomen en el Fitball con los pies anclados. Eleva el torso extendiendo la espalda baja y aprieta los glúteos en la parte superior.'),
('edb32ae4-0e9d-463d-a6e9-c39ca911f4ef', '2902fcaf-ded0-4d6f-bf01-70371946680a', 'en', 'Double Kettlebell Turkish Get Up', 'Perform the full Turkish Get Up while maintaining two kettlebells locked out overhead, an extreme challenge of coordination and strength.'),
('f2e81931-d4cc-4186-b2f0-669d403dab49', '2902fcaf-ded0-4d6f-bf01-70371946680a', 'es', 'Levantamiento turco con pesa rusa doble', 'Realiza el levantamiento turco completo manteniendo dos pesas rusas bloqueadas sobre la cabeza, un reto extremo de coordinacion y fuerza.'),
('1e1b6ebb-aa93-4e1e-8f5d-d05e07e92dd9', '29031d9c-3000-4682-bb1c-03e76b6735a9', 'en', 'Ipsilateral Overhead Slider Kettlebell Reverse Lunge', 'Hold a kettlebell overhead and slide the leg on the same side back on a slider. Requires great core control.'),
('859c91ff-0b35-4abf-8c2d-cfe816603550', '29031d9c-3000-4682-bb1c-03e76b6735a9', 'es', 'Zancada inversa Overhead ipsilateral con Slider y Kettlebell', 'Sostén una pesa rusa sobre la cabeza y desliza hacia atrás la pierna del mismo lado en un slider. Requiere un gran control del core.'),
('f8141165-b10c-4683-acfd-122498a8600e', '291bfc9d-c893-453d-a79c-1c657aac095b', 'en', 'TRX Push Ups', 'With feet in the TRX straps, perform push-ups. Instability increases core activation and the difficulty of the exercise. Keep the body completely straight and control the swaying of the straps.'),
('87454025-6cca-4f07-ae73-d92027a566b4', '291bfc9d-c893-453d-a79c-1c657aac095b', 'es', 'Flexiones TRX', 'Con los pies en las correas del TRX, realiza flexiones. La inestabilidad aumenta la activación del core y la dificultad del ejercicio. Mantén el cuerpo completamente recto y controla el balanceo de las correas.'),
('47a40bcc-c9b3-4b6e-8b8f-316536701a13', '294c8ea9-4c25-4eb9-9bcb-97aac3824164', 'en', 'Standing Calf Raises', 'Raise your heels seeking the maximum possible height and lower in a controlled manner. Objective: calf strength. Cue: knees straight but not locked. Common error: swinging the torso to rise.'),
('a34be02f-d0c5-4ed2-8969-37f386ef281a', '294c8ea9-4c25-4eb9-9bcb-97aac3824164', 'es', 'Elevación de talones de pie', 'Eleva los talones buscando la máxima altura posible y baja controladamente. Objetivo: fuerza del gemelo. Cue: rodillas estiradas pero no bloqueadas. Error común: balancear el torso para subir.'),
('c56eaf5e-ff36-4b95-89bd-b1bfdc6896d7', '296f56c6-5b16-4cc2-ba96-081afd16c3c4', 'en', 'Aztec Push Ups', 'Explosive push-up where you touch your feet with your hands in the air. Requires extreme explosive power and perfect coordination. One of the most difficult push-up variations. Progress with simpler explosive push-ups first.'),
('e9782684-08de-4148-bb1b-8b451c06b670', '296f56c6-5b16-4cc2-ba96-081afd16c3c4', 'es', 'Flexiones azteca', 'Flexión explosiva donde tocas los pies con las manos en el aire. Requiere potencia explosiva extrema y coordinación perfecta. Una de las variaciones más difíciles de flexiones. Progresa con flexiones explosivas más simples primero.'),
('01a206b8-40ba-4679-91c3-659d71c4691f', '2973645b-9cbb-403a-9483-a59db125e6ac', 'en', 'Double Dumbbell Seated Cuban Rotation', 'Seated, lift elbows to shoulder height (arms in L). Rotate dumbbells upward until forearms are vertical, then rotate back down.'),
('596b4328-7e89-47e1-9fc2-e2902ce5749a', '2973645b-9cbb-403a-9483-a59db125e6ac', 'es', 'Rotación cubana sentado con mancuernas', 'Sentado, levanta los codos a la altura de los hombros (brazos en L). Rota las mancuernas hacia arriba hasta que los antebrazos queden verticales, luego baja rotando.'),
('88d458dd-c5b4-47e6-b4d7-d3ad3eb25750', '298f2962-d130-4bd4-850d-aa07cde45c77', 'en', 'Alternating Double Dumbbell Tall Kneeling Overhead Press', 'Kneeling on both legs, press the dumbbells alternately overhead, keeping the torso perfectly upright.'),
('439c3da6-9260-40f1-b63a-079fdb07d4ae', '298f2962-d130-4bd4-850d-aa07cde45c77', 'es', 'Press Overhead arrodillado alterno con mancuernas', 'Arrodillado sobre ambas piernas, presiona las mancuernas alternativamente sobre la cabeza, manteniendo el tronco perfectamente vertical.'),
('746e3e0e-3a82-424f-9864-12f0f7810842', '29c141d3-c74b-466d-91a7-5fa130b599ab', 'en', 'Plyometric Ball Push Ups', 'Explosive push-ups with hands alternating on the ball. Develops power and coordination. One hand on the ball, the other on the floor, explode to switch. Requires explosive strength and control.'),
('921857c4-45e0-4315-8332-4d4de929d8fe', '29c141d3-c74b-466d-91a7-5fa130b599ab', 'es', 'Flexiones pliométricas balón', 'Flexiones explosivas con manos alternando sobre el balón. Desarrolla potencia y coordinación. Una mano en balón, otra en suelo, explota para cambiar. Requiere fuerza explosiva y control.'),
('b83acbfd-7258-4280-b6bf-4127a62d4013', '29e39d6f-11ee-497c-aa86-b210a10a3a5f', 'es', 'Volante (Steering Wheel) con disco', 'Sostén un disco frente a ti con brazos estirados. Gíralo de lado a lado simulando un volante para trabajar hombros y antebrazos.'),
('38e1a2bb-902e-4ad1-bb03-e6943f670d70', '2a0ef8a8-5b10-4b5a-9b04-fbd9b85e4738', 'en', 'Single Arm Kettlebell Bottoms Up Z Press', 'Sitting on the floor, press an upside-down kettlebell overhead, removing leg drive and challenging the grip.'),
('7641515a-0e0d-4851-b8e1-05c7f47fcb06', '2a0ef8a8-5b10-4b5a-9b04-fbd9b85e4738', 'es', 'Press en Z con pesa rusa de un solo brazo, de abajo hacia arriba', 'Sentado en el suelo, presiona una Kettlebell invertida sobre la cabeza, eliminando el impulso de las piernas y desafiando el agarre.'),
('82edcd10-9f18-434b-a7b8-fed055a2b4bf', '2a1132df-78af-4b9c-83a2-0d121183ac2b', 'en', 'Machine Reverse Fly', 'Seated facing the machine, open your arms backward working the rear deltoid. Also known as rear delt fly. Maintain a slight bend in the elbows and focus on bringing the shoulder blades together.'),
('78e054b1-48a1-484b-970f-de7350a09e90', '2a1132df-78af-4b9c-83a2-0d121183ac2b', 'es', 'Reverse fly máquina', 'Sentado de frente a la máquina, abre los brazos hacia atrás trabajando deltoides posterior. También conocido como rear delt fly. Mantén una ligera flexión en los codos y enfócate en juntar los omóplatos.'),
('01be65c9-f28b-4e2c-a3e6-17367e6e1f95', '2a2528a2-1e5e-4772-9f54-a8192d30fad4', 'en', 'L-sit Pull-ups', 'Hang from the bar and lift legs until they form a 90-degree angle with the torso, keeping them parallel to the floor. Perform pull-ups maintaining this L position throughout the movement. Requires exceptional core strength and hamstring flexibility.'),
('3d7492c3-f1f5-493b-8b33-6be048a4105f', '2a2528a2-1e5e-4772-9f54-a8192d30fad4', 'es', 'Dominadas L-sit', 'Cuelga de la barra y eleva las piernas hasta formar un ángulo de 90 grados con el torso, manteniéndolas paralelas al suelo. Realiza dominadas manteniendo esta posición de L durante todo el movimiento. Requiere fuerza excepcional en el core y flexibilidad en los isquiotibiales.'),
('956dd628-2ec0-4894-a27b-a4df82b90487', '2a4a8d2b-b31a-4f1d-a247-7a6c89400a91', 'en', 'Reverse Grip Incline Barbell Press', 'Bench press on incline bench with palms facing you. Cue: requires spotter. Error: losing bar control.'),
('8665bf54-8255-4430-8ce7-df29aa861e20', '2a4a8d2b-b31a-4f1d-a247-7a6c89400a91', 'es', 'Press inclinado agarre inverso barra', 'Press en banco inclinado con palmas hacia ti. Cue: requiere ayudante. Error: perder control barra.'),
('42e6df0f-1eca-466d-8709-b6595091083f', '2a4ab764-db08-4193-948e-c35a74b37552', 'en', 'Straight-Arm Pulldown', 'Perform a straight-arm pulldown on a cable machine. Keep the elbows slightly bent and pull the bar or rope toward the thighs while engaging the lats.'),
('88fe1188-b062-4c53-bfaf-88fb7c2d0657', '2a4ab764-db08-4193-948e-c35a74b37552', 'es', 'Jalón brazos rectos', 'Realiza un jalón con brazos rectos en polea. Mantén los codos ligeramente flexionados y lleva la barra o cuerda hacia los muslos activando el dorsal.'),
('ab63e1c0-8608-4119-9c65-54f2194eb831', '2aafdae1-62e6-45e8-bac1-7c8bc2d67253', 'en', 'One-Arm Cyclist Squat with Kettlebell (Front Rack)', 'With heels elevated, hold a kettlebell on a single shoulder and perform a squat, working on asymmetrical stability.'),
('a4e4a882-cbf1-489a-be20-3957362ec785', '2aafdae1-62e6-45e8-bac1-7c8bc2d67253', 'es', 'Sentadilla Ciclista con Kettlebell a una mano (Front Rack)', 'Con talones elevados, sujeta una Kettlebell en un solo hombro y realiza una sentadilla, trabajando la estabilidad asimetrica.'),
('aff4618b-bd36-40ee-bcb9-f13f8445dfb6', '2ad3fd19-0b36-4d3b-9fdf-45ddfe9aa655', 'en', 'Single Arm Ring Grip Push Up', 'Perform a push-up while supported on a single ring with one arm, keeping the body straight and balancing extreme instability.'),
('639e8f3f-d0ee-47e0-8f17-a9e2a8bf6dbb', '2ad3fd19-0b36-4d3b-9fdf-45ddfe9aa655', 'es', 'Push Up en anillas a una mano', 'Realiza una flexión apoyado en una sola anilla con un brazo, manteniendo el cuerpo recto y equilibrando la inestabilidad extrema.'),
('4eaeb499-db72-4631-9fcd-765d707d0164', '2ae25e37-2439-46aa-9e5f-bb58a8568971', 'en', 'Butterfly Sit Up', 'Sit with soles of feet together and knees out (butterfly). Lie down and then use arm momentum and abdominal strength to sit up and touch your feet.'),
('304b6e8f-b100-4fe7-9c65-a0a34dc41a3f', '2ae25e37-2439-46aa-9e5f-bb58a8568971', 'es', 'Sit Up Mariposa', 'Siéntate con las plantas de los pies juntas y las rodillas hacia afuera (mariposa). Acuéstate y luego usa el impulso de los brazos y fuerza abdominal para sentarte y tocar los pies.'),
('0cc133f4-b19c-4826-a2f9-defd52646392', '2aedb0e6-a0ba-49e0-89e0-04696cdec3f2', 'en', 'Bulgarian Ring Dips', 'Ring dips bringing the elbows back instead of to the sides. Extremely challenging for the triceps. Requires shoulder mobility. Progress from regular ring dips. Careful with shoulder position.'),
('137af3ee-abf7-4150-ad06-10641a7e80b7', '2aedb0e6-a0ba-49e0-89e0-04696cdec3f2', 'es', 'Fondos búlgaro en anillas', 'Fondos en anillas llevando los codos hacia atrás en lugar de a los lados. Extremadamente desafiante para los tríceps. Requiere movilidad de hombros. Progresa desde fondos regulares en anillas. Cuidado con la posición de hombros.'),
('8965485a-737a-4eb1-aa9a-0316269ce581', '2b04d86c-d153-4138-b4b1-1c5847e717fe', 'en', 'Ball Russian Twists', 'Seated with knees flexed and feet raised or on the floor, rotate the torso from side to side holding the ball. Touch the floor with the ball on each side. Keep the chest elevated and core contracted throughout the movement.'),
('2c1783a8-4781-4f8c-9646-6d7f7c265de6', '2b04d86c-d153-4138-b4b1-1c5847e717fe', 'es', 'Giros rusos balón', 'Sentado con rodillas flexionadas y pies elevados o en el suelo, rota el torso de lado a lado sosteniendo el balón. Toca el suelo con el balón en cada lado. Mantén el pecho elevado y el core contraído durante todo el movimiento.'),
('a53e93ef-9cd8-4e3e-a7dd-e37616b576e9', '2b08f192-1b98-4819-b66d-84daac425635', 'en', 'Strict Standing Calf Raises', 'Raise heels seeking maximum height while standing. Cue: control the descent. Error: swinging the body.'),
('cd727d6c-3565-4258-988b-aa45344c22b1', '2b08f192-1b98-4819-b66d-84daac425635', 'es', 'Elevación de talones de pie estricta', 'Eleva talones buscando máxima altura de pie. Cue: controla el descenso. Error: balancear el cuerpo.'),
('d66fd6dd-0afe-40e4-a0c4-a2ad4e769bbc', '2b0b8d9a-9108-4a58-95c7-83ab051290e8', 'en', 'Advanced Dragon Squat', 'Deep unilateral squat with the free leg fully extended behind. More extreme version requiring exceptional strength, balance, and mobility. The back leg must not touch the ground. Only for very advanced athletes.'),
('5f3f9ab5-c4f5-48fb-9469-7caf1135ad54', '2b0b8d9a-9108-4a58-95c7-83ab051290e8', 'es', 'Sentadilla dragon avanzada', 'Sentadilla unilateral profunda con la pierna libre extendida completamente detrás. Versión más extrema que requiere fuerza, equilibrio y movilidad excepcionales. La pierna trasera no debe tocar el suelo. Solo para atletas muy avanzados.'),
('328e1fd9-bac7-4892-a94a-5b0fe8058818', '2b0f5348-a37e-4e08-af19-b65489127536', 'en', 'One Arm Cable Row', 'Unilateral row with cable allowing for greater range of motion and concentration on each side. You can slightly rotate the torso at the end for more contraction. Keep core engaged to stabilize the position.'),
('d574b8f7-1386-4dfd-bd94-4293ffb503ed', '2b0f5348-a37e-4e08-af19-b65489127536', 'es', 'One arm row cable', 'Remo unilateral con cable que permite mayor rango de movimiento y concentración en cada lado. Puedes rotar ligeramente el torso al final para mayor contracción. Mantén el core activado para estabilizar la posición.'),
('7a095249-f627-4300-b215-0f6197d64d00', '2b13df73-1df0-40d0-b423-fa9d282b755b', 'es', 'Plancha fitball', 'Realiza plancha con antebrazos o pies sobre la fitball. La superficie inestable aumenta drásticamente la activación del core. Mantén el cuerpo completamente recto resistiendo el movimiento de la pelota. Comienza con intervalos cortos.'),
('a73bf6a3-bcf4-4e92-8d8b-194020b22854', '2b4be1f9-26ea-4180-af5b-6a6faed03435', 'en', 'Commando Pull-ups', 'Stand perpendicular to the bar with one hand in front of the other. Lift the body, bringing the head alternately to each side of the bar. This exercise requires greater core stabilization and works the muscles asymmetrically, improving control and unilateral strength.'),
('9e7f9357-2b85-4d8f-b98e-548c52dd114a', '2b4be1f9-26ea-4180-af5b-6a6faed03435', 'es', 'Dominadas commando', 'Colócate perpendicular a la barra con una mano delante de la otra. Eleva el cuerpo llevando la cabeza alternativamente a cada lado de la barra. Este ejercicio requiere mayor estabilización del core y trabaja los músculos de forma asimétrica, mejorando el control y la fuerza unilateral.'),
('b8ac8a49-dfcf-4053-86f7-1749848029d9', '2b6237d4-b9e3-4d93-b183-fdea5e207854', 'en', 'Bradford Press', 'Press alternating the bar in front of and behind the head without lowering it completely. Maintains constant tension in the deltoids. Named after Jim Bradford. Requires good shoulder mobility. Not recommended for everyone.'),
('6950cf90-6460-43d0-890d-8c9e9b74ab39', '2b6237d4-b9e3-4d93-b183-fdea5e207854', 'es', 'Press bradford', 'Press alternando la barra delante y detrás de la cabeza sin bajarla completamente. Mantiene tensión constante en deltoides. Nombrado por Jim Bradford. Requiere buena movilidad de hombros. No recomendado para todos.'),
('222b3ae2-1b11-4ea9-8312-bb9da2761d5a', '2b717f49-a98e-4a92-b6a7-bcad5ed4a1ed', 'en', 'Single Arm Dumbbell Incline Bench Prone Row', 'Lie face down on the bench and row a single dumbbell toward your hip, isolating the work on one side of the back.'),
('9c8af36a-9cff-4a96-9852-e9723d6e2b42', '2b717f49-a98e-4a92-b6a7-bcad5ed4a1ed', 'es', 'Remo prono en banco inclinado con mancuerna a una mano', 'Acuéstate boca abajo en el banco y rema una sola mancuerna hacia la cadera, aislando el trabajo en un lado de la espalda.'),
('5e538f54-39bd-4f88-bd51-377f78f8b152', '2b83f4b8-aad8-4222-b34b-fa4c048f6ea9', 'en', 'Lateral walk with Miniband (Ankles)', 'Place the band around the ankles. In an athletic position, walk laterally dragging feet or taking controlled steps, maintaining tension.'),
('8de87e44-740c-4e14-8081-9bfc8b443703', '2b83f4b8-aad8-4222-b34b-fa4c048f6ea9', 'es', 'Caminata lateral con Miniband (Tobillos)', 'Coloca la banda alrededor de los tobillos. En posición atlética, camina lateralmente arrastrando los pies o dando pasos controlados, manteniendo tensión.'),
('354d7b6b-45a3-4177-8d53-4202b2027e37', '2b881d15-0ec5-401a-89cf-109845e052c6', 'en', 'Single Arm Dumbbell Bird Dog Row', 'In a quadruped position, extend the leg opposite to the arm performing the dumbbell row, working the back and anti-rotational core.'),
('e2d41b54-e64b-4dd7-9ccb-81475f4ecfd8', '2b881d15-0ec5-401a-89cf-109845e052c6', 'es', 'Bird Dog Row con mancuerna', 'En posicion de cuadrupedia, extiende la pierna opuesta al brazo que realiza el remo con mancuerna, trabajando la espalda y el core antirotacional.'),
('3133570a-1c26-4a99-8c46-8bb4954e2b37', '2bf6184a-bd05-42b0-b939-109d023f2424', 'en', '180-Degree Turn Vertical Jump', 'Jump vertically and perform a half turn, landing stable facing the starting point. Cue: look forward upon landing. Common error: landing with feet misaligned.'),
('f336b1c6-7703-48ed-b486-d757650169af', '2bf6184a-bd05-42b0-b939-109d023f2424', 'es', 'Salto vertical giro 180', 'Salta verticalmente y gira media vuelta, aterrizando estable de frente al punto de inicio. Cue: mirada al frente al caer. Error común: caer con pies desalineados.'),
('8f562b0a-8212-47d4-8b65-b6691c67af0c', '2c278f2c-2804-45b7-825f-5b924c545918', 'en', 'Seated Shoulder Press', 'Seated with a backrest, push dumbbells overhead. Cue: lower until elbows form 90 degrees. Error: clashing the weights at the top.'),
('17a14dc1-59f3-4614-af96-0ad17839c13c', '2c278f2c-2804-45b7-825f-5b924c545918', 'es', 'Press de hombro sentado', 'Sentado con respaldo, empuja mancuernas sobre la cabeza. Cue: baja hasta que los codos formen 90 grados. Error: chocar las pesas arriba.'),
('25bf985b-7418-4c57-8e30-79ba991375a3', '2c585288-f929-4dd9-b680-7c3401e25e14', 'en', 'Classic Push Ups', 'Place hands on the floor shoulder-width apart with fingers pointing forward. Keep the body completely straight from head to heels. Descend in a controlled manner by flexing the elbows until the chest almost touches the floor, then push forcefully to return to the starting position. Keep the core engaged throughout the movement.'),
('5733f1ad-94e5-483c-a0be-be391a46a2f6', '2c585288-f929-4dd9-b680-7c3401e25e14', 'es', 'Flexiones clásicas', 'Coloca las manos en el suelo a la anchura de los hombros con los dedos apuntando hacia adelante. Mantén el cuerpo completamente recto desde la cabeza hasta los talones. Desciende controladamente flexionando los codos hasta que el pecho casi toque el suelo, luego empuja con fuerza para volver a la posición inicial. Mantén el core activado durante todo el movimiento.'),
('c4cf1867-ed91-42c0-9c44-f993c1f2bcde', '2c6fd3cf-25f7-436d-9c0a-2a7c29c69042', 'en', 'Dumbbell Man Makers', 'Complex exercise combining burpee, row, and press. From a standing position with dumbbells, perform a burpee keeping hands on dumbbells, add a row with each arm in plank position, jump feet toward hands, and finish with a clean and press.'),
('f21aca92-f779-4832-b77d-56a90e5c8fbb', '2c6fd3cf-25f7-436d-9c0a-2a7c29c69042', 'es', 'Man makers mancuernas', 'Ejercicio complejo que combina burpee, remo y press. Desde posición de pie con mancuernas, realiza un burpee manteniendo las manos en las mancuernas, añade un remo con cada brazo en posición de plancha, salta los pies hacia las manos y finaliza con un clean y press.'),
('9a00c64f-14e6-434f-9da4-1711109e2495', '2c92c059-bcea-491f-9cf4-2d13906dd417', 'en', 'Low Pulley Gironda Row', 'Seated row with narrow grip emphasizing retraction. Cue: high chest. Error: bending the back.'),
('ab253c2e-0d64-40b9-bf7a-210dc43336a7', '2c92c059-bcea-491f-9cf4-2d13906dd417', 'es', 'Remo Gironda en polea baja', 'Remo sentado con agarre estrecho enfatizando retracción. Cue: pecho alto. Error: doblar la espalda.'),
('e9bb9573-2f25-4f8e-a2d0-fc306346aa5c', '2cc75ccb-e3b4-41ee-a602-d7876ef752ec', 'es', 'TRX Zancada suspendida', 'Un pie en el agarre, realiza una zancada con la otra pierna. Gran desafío de estabilidad. Rodilla delantera alineada. No pierdas la verticalidad.'),
('72c49919-f218-4161-b363-e342a44f2e38', '2ce1c6c1-abd7-4332-8d98-2596ad2f1872', 'en', 'TRX T-Flyes', 'Open arms laterally in TRX. Objective: upper back. Cue: straight elbows. Error: shrugging shoulders.'),
('1cbded25-6d43-438c-b306-b1b480656c98', '2ce1c6c1-abd7-4332-8d98-2596ad2f1872', 'es', 'TRX Aperturas T', 'Abre brazos lateral en TRX. Objetivo: espalda alta. Cue: codos rectos. Error: encoger hombros.'),
('dd5bc5d9-ab68-47f6-a1be-d9ac6b0dabe9', '2cf0e2aa-4e70-4b28-83d8-9349acd4ef53', 'en', 'Alternating Single Arm Kettlebell Pendlay Row', 'With the torso parallel to the floor, row one kettlebell from the ground while the other rests, alternating arms with each repetition.'),
('130ea2a5-1950-4cc1-abea-6384ca793cd3', '2cf0e2aa-4e70-4b28-83d8-9349acd4ef53', 'es', 'Remo Pendlay alterno a una mano con Kettlebell', 'Con el torso paralelo al suelo, rema una pesa rusa desde el suelo mientras la otra descansa, alternando brazos en cada repeticion.'),
('dbec09ee-e271-441a-ab1c-55f61bd9d253', '2d09a632-35cd-4810-af35-7aad230fcf8c', 'en', 'Cable Concentration Curl', 'With low pulley, perform unilateral curls focusing on bicep isolation. Can be done standing or seated, keeping the working arm slightly forward. Constant cable tension intensifies muscle work.'),
('bd4da47d-6fcd-4d2c-a75d-498d465a93ea', '2d09a632-35cd-4810-af35-7aad230fcf8c', 'es', 'Curl concentrado cable', 'Con polea baja, realiza curls unilaterales concentrándote en el aislamiento del bíceps. Puedes hacerlo de pie o sentado, manteniendo el brazo que trabaja ligeramente adelantado. La tensión constante del cable intensifica el trabajo muscular.'),
('b1b9f486-2de7-4820-ad92-78973aaaec27', '2d17d0ae-8d2f-488c-8373-d430888ddc22', 'en', 'Ring Straddle L Sit', 'Support your body on the rings with your legs spread in a V-shape and lifted parallel to the ground, keeping your arms locked.'),
('9a8c34d4-e34a-4383-a84c-cfac0c75c2fc', '2d17d0ae-8d2f-488c-8373-d430888ddc22', 'es', 'Straddle L-Sit en anillas', 'Sostén tu cuerpo en las anillas con las piernas abiertas en forma de V y levantadas paralelas al suelo, manteniendo los brazos bloqueados.'),
('8bb05f65-d711-4c33-b149-70b08d638eeb', '2d2a5ead-2a2e-402b-a912-b63705b4e6d3', 'en', 'Paused Bench Press', 'Bench press with a 2-3 second pause with the bar on the chest. Eliminates bounce and stretch reflex. Standard in powerlifting competition. Maintain tension during the pause. Develops strength from a dead position.'),
('a2011163-afdc-4316-a584-606bc354611f', '2d2a5ead-2a2e-402b-a912-b63705b4e6d3', 'es', 'Press banca con pausa', 'Press banca con pausa de 2-3 segundos con la barra en el pecho. Elimina rebote y stretch reflex. Estándar en competición de powerlifting. Mantén tensión durante la pausa. Desarrolla fuerza desde posición muerta.'),
('a9a96ec7-d932-4bd0-a001-fab20c93b0ce', '2d4083a8-680c-40a2-82f5-a38a6038321f', 'en', 'Single Arm Kettlebell Staggered Stance Swing', 'Perform a single-arm swing while keeping one foot slightly back (split stance), increasing the stability challenge on the lead leg.'),
('7428d068-bafd-4ea9-84e4-8dde1c12d785', '2d4083a8-680c-40a2-82f5-a38a6038321f', 'es', 'Swing con Kettlebell a una mano en postura escalonada', 'Realiza un swing con un brazo manteniendo un pie ligeramente retrasado (postura split), aumentando el reto de estabilidad en la pierna delantera.'),
('653a4432-275b-4dde-afb4-c65f0b36c8b0', '2d7f88db-aba9-4484-99b0-64a884eefae0', 'es', 'Press banca cerrado', 'Manos algo más cerradas que el press normal. Codos cerca del cuerpo. Baja al pecho y empuja fuerte sin perder línea.'),
('da820a7c-ede0-4172-b2af-154782d613aa', '2d8334eb-579d-4af1-a858-36f48feecad6', 'en', 'Double Dumbbell Seesaw Z Press', 'Sitting on the floor with legs in a V, perform a continuous alternating press with dumbbells, requiring maximum lumbar verticality.'),
('6b6886a6-e1db-49ad-a1eb-8f181e7c2ee1', '2d8334eb-579d-4af1-a858-36f48feecad6', 'es', 'Press Z Seesaw con mancuernas', 'Sentado en el suelo con piernas en V, realiza un press alterno continuo con mancuernas, exigiendo máxima rectitud lumbar.'),
('09af006b-8b63-4482-8afb-aedf82fa546d', '2d879e98-29f0-4335-8f6c-3f379168f38e', 'en', 'Skater Squat', 'Lower into a squat on one leg while bringing the knee of the other leg toward the floor behind you, keeping the torso slightly leaned.'),
('54c26688-e1d9-46b5-89ae-8d6963b26552', '2d879e98-29f0-4335-8f6c-3f379168f38e', 'es', 'Sentadilla patinadora (Skater Squat)', 'Baja en sentadilla con una pierna mientras llevas la rodilla de la otra pierna hacia el suelo por detrás, manteniendo el torso ligeramente inclinado.'),
('02c05409-2d8f-4568-b3d0-bf41759ae77f', '2da13872-5938-44ff-ae03-051cf1c6d592', 'es', 'Zancada de patinador explosiva', 'Versión más potente del salto de patinador buscando máxima altura y distancia. Cue: empuje agresivo desde el lateral del pie. Error común: falta de control en el aterrizaje.'),
('27231bed-cd0e-4e04-8aaf-7395a0030d25', '2daeaf64-ea87-462f-b57e-c4a627335f4e', 'en', 'TRX Hip Press', 'Lying with heels in the straps, perform hip raises. Similar to the glute bridge but with added instability. Strongly squeeze glutes at the top and maintain position.'),
('b05faf7a-e1f6-4f0c-b92e-c61fb6f53552', '2daeaf64-ea87-462f-b57e-c4a627335f4e', 'es', 'Hip press TRX', 'Tumbado con talones en las correas, realiza elevaciones de cadera. Similar al puente de glúteo pero con la inestabilidad añadida. Aprieta fuertemente los glúteos en la parte superior y mantén la posición.'),
('6a222b79-9875-4bcb-ad26-a89b7fb9fd93', '2dcf2ee8-cec7-4310-afff-bfdaf087bf96', 'en', 'Suspension Archer Row', 'Hold the TRX with one hand. Pull the body up while the other arm extends to the side (like an archer). Return and switch arms.'),
('59c17679-dc06-40b0-88e5-504a8a32f922', '2dcf2ee8-cec7-4310-afff-bfdaf087bf96', 'es', 'Remo Arquero en TRX', 'Sostén el TRX con una mano. Tira del cuerpo hacia arriba mientras el otro brazo se extiende hacia el lado (como un arquero). Regresa y cambia de brazo.'),
('b697cb11-71c0-4852-8db1-f6e26acc3ba1', '2e14390a-a7d2-4962-be01-5520ce77d701', 'en', 'Ring Muscle up', 'Muscle up on gymnastic rings. Much more difficult than on a bar due to instability. Requires false grip transition and great control. Technique is crucial. Progress with assisted muscle ups and slow transitions.'),
('eae64c5c-84be-4628-ae7f-2a1a5ec4bce6', '2e14390a-a7d2-4962-be01-5520ce77d701', 'es', 'Muscle up en anillas', 'Muscle up en anillas gimnásticas. Mucho más difícil que en barra debido a la inestabilidad. Requiere transición de falso agarre y gran control. La técnica es crucial. Progresa con muscle ups asistidos y transiciones lentas.'),
('f7bdf292-2c42-4419-8bc5-6bfd5dfc396a', '2e1acaac-5b02-4d74-bec8-ad43656dae4f', 'en', 'Kneeling Balance on Fitball', 'Maintain a kneeling position on the Fitball seeking constant balance, activating all stabilizing core muscles.'),
('e157f14f-74be-488a-a7c3-e14d552ce5f9', '2e1acaac-5b02-4d74-bec8-ad43656dae4f', 'es', 'Equilibrio de rodillas sobre Fitball', 'Mantente en posicion de rodillas sobre el Fitball buscando el equilibrio constante, activando todos los musculos estabilizadores del core.'),
('90cc8408-ebb1-4956-8ea1-bc88181b543c', '2e40f498-780f-4360-b7b5-f2e6db2c7164', 'en', 'Seated Band Bicep Curl', 'Seated, step on the band and flex arms maintaining constant tension. Objective: bicep pump. Cues: fixed elbows and straight back. Common error: shrugging shoulders when rising.'),
('288d2993-358d-4b51-9ab5-4b3f6b34a586', '2e40f498-780f-4360-b7b5-f2e6db2c7164', 'es', 'Curl de bíceps sentado con banda', 'Sentado, pisa la banda y flexiona los brazos manteniendo tensión constante. Objetivo: bombeo de bíceps. Cues: codos fijos y espalda recta. Error común: encoger los hombros al subir.'),
('6e1c2665-1207-4d9f-9309-347498f880f1', '2e41dcad-859b-4308-9bd8-eb699b194e59', 'en', 'Single Leg Cable Hamstring Curl', 'Lying face down, flex the leg attached to the cable, bringing the heel toward the glute to isolate the hamstring.'),
('d49a5934-40ba-4484-b897-ad35224e1120', '2e41dcad-859b-4308-9bd8-eb699b194e59', 'es', 'Curl de isquiotibiales a una pierna en polea', 'Tumbado boca abajo, flexiona la pierna enganchada al cable llevando el talón hacia el glúteo para aislar el isquiotibial.'),
('3fa1c50e-dfee-43e2-8d1c-7cb134aedc21', '2e423632-7331-47de-8dd0-d98dc129bc12', 'en', 'Ring Full Front Lever Pull Up', 'Maintain a full Front Lever body position and pull the rings toward your hips, lifting the torso while keeping it parallel to the ground.'),
('731ec311-6a34-4e52-ba8d-2ee7c0ca7514', '2e423632-7331-47de-8dd0-d98dc129bc12', 'es', 'Full Front Lever Pull Up en anillas', 'Manten el cuerpo estirado en Front Lever y tira de las anillas hacia la cadera elevando el torso paralelo al suelo.'),
('5a062e4f-8d1a-4add-a27a-1967a5752d2a', '2e831f74-7d0c-4bc7-8614-8c7ea4d18a41', 'en', 'Butterfly Pull-ups', 'Most advanced and efficient version of kipping with a continuous circular motion. Allows for maximum speed and volume. Requires excellent technique and conditioning. High risk of injury if executed incorrectly. Master kipping first.'),
('fa3da60c-9867-495d-8a91-af35bcf1066b', '2e831f74-7d0c-4bc7-8614-8c7ea4d18a41', 'es', 'Dominadas mariposa', 'Versión más avanzada y eficiente del kipping con movimiento circular continuo. Permite máxima velocidad y volumen. Requiere excelente técnica y acondicionamiento. Alto riesgo de lesión si se ejecuta incorrectamente. Domina kipping primero.'),
('12f7239a-4eb0-4da4-a09c-2741b82c371d', '2eb5caee-cb71-4e49-9c36-572157e41b8c', 'en', 'L-Push Ups', 'Push-ups maintaining body in L position (horizontal legs). Combines difficulty of L-sit with vertical push-ups. Requires exceptional shoulder strength and flexibility. Progress with assisted versions.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('0767faa2-0ca5-4ea4-87e7-289fe66dcc0a', '2eb5caee-cb71-4e49-9c36-572157e41b8c', 'es', 'Flexiones en L', 'Flexiones manteniendo el cuerpo en posición de L (piernas horizontales). Combina la dificultad del L-sit con flexiones verticales. Requiere fuerza excepcional en hombros y flexibilidad. Progresa con versiones asistidas.'),
('98d61846-35ad-4f99-99f4-c57871383095', '2ecfb758-7832-457d-990b-1b06e012b0bb', 'en', 'Ab Wheel Rollout', 'From knees, roll forward extending the body as much as possible without touching the ground. Keep back neutral and core contracted. Return to start with control. One of the best core exercises.'),
('6555e13a-d8d1-493f-8911-fe959f912a2f', '2ecfb758-7832-457d-990b-1b06e012b0bb', 'es', 'Roll out rueda abdominal', 'Desde rodillas, rueda hacia adelante extendiendo el cuerpo lo más posible sin tocar el suelo. Mantén la espalda neutra y el core contraído. Vuelve a la posición inicial con control. Uno de los mejores ejercicios para el core.'),
('bb65131c-bfcb-4e34-abfb-4716a8ae0913', '2ecfce7f-5084-48de-a5f5-75ffb79b3d8a', 'en', 'Staggered Push Ups', 'Push-ups with one hand elevated on a surface while the other is on the floor. Creates challenging asymmetrical work. Alternate hand positions or perform sets per side. Good progression toward one-arm push-ups.'),
('0de4ca9f-3f3a-413b-a7b3-2e0f751de57b', '2ecfce7f-5084-48de-a5f5-75ffb79b3d8a', 'es', 'Flexiones escalonadas', 'Flexiones con una mano elevada en una superficie mientras la otra está en el suelo. Crea un trabajo asimétrico desafiante. Alterna la posición de las manos o realiza series por lado. Buena progresión hacia flexiones a un brazo.'),
('03c89dfc-5d40-47b6-84d3-d1f016d5f63a', '2ed6ab66-447c-4d41-b429-77232e74d472', 'en', 'Plyometric Shoulder Tap Push Up', 'Perform an explosive push-up and touch your shoulders with your hands in the air before landing. Develops upper body power. Cue: lock the abdomen to avoid snaking. Common error: not pushing enough to allow time for the tap.'),
('e05148ce-9b09-42ef-b5e0-a52d3a12500f', '2ed6ab66-447c-4d41-b429-77232e74d472', 'es', 'Flexión pliométrica a hombros', 'Realiza una flexión explosiva y toca tus hombros con las manos en el aire antes de caer. Desarrolla potencia en el tren superior. Cue: bloquea el abdomen para no serpentear. Error común: no empujar lo suficiente para dar tiempo al toque.'),
('37b7f5ed-d22f-4d63-8e22-9de931818c22', '2ef70db1-030a-4d5f-9e6c-888180d35f8c', 'en', 'Low Pulley Unilateral Lat Row', 'Row with one arm while seated. Cue: full stretch. Error: rotating torso.'),
('e2bf8889-904f-4653-b8d7-84dbfcf342c5', '2ef70db1-030a-4d5f-9e6c-888180d35f8c', 'es', 'Remo unilateral polea baja dorsal', 'Rema a un brazo sentado. Cue: estira total. Error: rotar torso.'),
('5afaf681-734a-4a35-9c62-27bd0938dbbe', '2f0ba226-e03c-4f53-9d65-8caf7b2ca6c1', 'es', 'Tuck Ups', 'Siéntate en el suelo y encoge rodillas hacia el pecho mientras elevas el torso. Objetivo: abdominales y flexores de cadera. Cues: equilibrio sobre el glúteo. Error común: apoyar las manos para ayudarse excesivamente.'),
('0c4208f8-d9d4-48ab-9ae3-80a023eb0325', '2f196e0d-1e1a-431f-b091-42757a650917', 'en', 'Unilateral Dumbbell Triceps Extension', 'Raise a dumbbell behind the neck with one arm and extend. Objective: triceps long head. Cues: elbow to ceiling. Common error: moving arm laterally.'),
('1adf9e3f-f11f-4de8-8bb9-e08174c75ba2', '2f196e0d-1e1a-431f-b091-42757a650917', 'es', 'Extensión de tríceps unilateral con mancuerna', 'Eleva una mancuerna tras la nuca con un brazo y extiende. Objetivo: cabeza larga tríceps. Cues: codo al techo. Error común: mover el brazo lateralmente.'),
('3b287f82-cae6-4a65-b14f-1c1faa924b84', '2f776183-e4b0-4805-85d4-b08e4f6fab4a', 'en', 'One-Arm Overhead Squat', 'Squat maintaining a dumbbell overhead with one arm. Stabilization and mobility challenge. Requires strong core to resist lateral flexion. Alternate arms. Excellent for identifying and correcting imbalances.'),
('2a383dba-11dd-4ccd-a111-0e07d6240936', '2f776183-e4b0-4805-85d4-b08e4f6fab4a', 'es', 'Sentadilla overhead un brazo', 'Sentadilla manteniendo una mancuerna overhead con un brazo. Desafío de estabilización y movilidad. Requiere core fuerte para resistir flexión lateral. Alterna brazos. Excelente para identificar y corregir desequilibrios.'),
('93052f2f-59e0-474d-96d4-5f04aef653bf', '2f882300-5a8c-4de8-907c-22092b5bb090', 'en', 'Dumbbell Goblet Squat', 'Hold a dumbbell vertically in front of the chest with both hands. Perform a deep squat maintaining elbows inside the knees.'),
('688f36a5-593a-4018-8b63-3668a0c26b3c', '2f882300-5a8c-4de8-907c-22092b5bb090', 'es', 'Sentadilla Goblet con mancuerna', 'Sostén una mancuerna verticalmente frente al pecho con ambas manos. Realiza una sentadilla profunda manteniendo los codos por dentro de las rodillas.'),
('a112ecad-ad22-4db4-afa5-47a68e2b3a6a', '30082f11-1315-4816-9065-119644e47837', 'en', 'Slider Double Kettlebell Bottoms Up Overhead Lateral Lunge', 'Hold two inverted Kettlebells (Bottoms Up) overhead. Slide one leg laterally using a slider, lower the hip and return.'),
('b36c9062-d718-4df7-94d3-2c3fce1cdeb5', '30082f11-1315-4816-9065-119644e47837', 'es', 'Zancada lateral con Kettlebell Bottoms Up y Slider', 'Sostén dos Kettlebells invertidas (Bottoms Up) sobre la cabeza. Desliza una pierna lateralmente usando un slider, baja la cadera y regresa.'),
('46488dfb-3237-463d-a3cb-55b1012acc5f', '302f112a-8fbd-43fc-aca2-81e40a7e0ccf', 'en', 'Tiger Bend Push Ups', 'From a push-up with forearms on the floor, extend to a normal push-up position. Intensely works the triceps with a unique movement pattern. Requires exceptional strength and control. Also called Hindu push-ups.'),
('1fd22e9d-f89e-492a-90d2-19c46b476066', '302f112a-8fbd-43fc-aca2-81e40a7e0ccf', 'es', 'Flexiones tiger bend', 'Desde flexión con antebrazos en el suelo, extiende a posición de flexión normal. Trabaja intensamente los tríceps con un patrón de movimiento único. Requiere fuerza y control excepcionales. También llamadas flexiones hindu.'),
('74bd0bed-1e13-4fc8-a79c-855c6ef1e93b', '3030d5fa-33fc-4e07-b0c1-0f502770ab64', 'en', 'Seated Soleus Machine', 'Raise heels while seated in a machine. Objective: soleus. Cue: maximum contraction. Error: bouncing.'),
('fec68748-21bf-4535-927c-bceb800f2278', '3030d5fa-33fc-4e07-b0c1-0f502770ab64', 'es', 'Sóleo máquina sentado', 'Eleva talones máquina sentado. Objetivo: sóleo. Cue: máxima contracción. Error: rebotar.'),
('40527e14-7c99-4a9a-ac51-8a4ed6c6f509', '3049d49a-8a6e-4ea9-b058-64efa95cf77f', 'en', 'Double Kettlebell Press', 'Press with two kettlebells simultaneously. Higher total load and stabilization challenge. Requires double clean technique first. Kettlebells can be pressed together or with rotation. Develops symmetrical strength.'),
('e4c88acf-debd-4436-be04-93c0523f0fd9', '3049d49a-8a6e-4ea9-b058-64efa95cf77f', 'es', 'Press doble kettlebell', 'Press con dos kettlebells simultáneamente. Mayor carga total y desafío de estabilización. Requiere técnica de clean doble primero. Las kettlebells pueden presionarse juntas o con rotación. Desarrolla fuerza simétrica.'),
('1cf2723a-e1a4-48e2-a27f-70a0f5d71a30', '305b61d7-0601-4ab8-bb8f-96d4b7e04bc6', 'en', 'Double Kettlebell Front Rack Knee Over Toe Split Squat', 'With kettlebells in a front rack position, lower into a split squat allowing the front knee to pass the tip of the foot.'),
('669fca2c-505b-4557-b8bc-0637900beaea', '305b61d7-0601-4ab8-bb8f-96d4b7e04bc6', 'es', 'Sentadilla Búlgara Front Rack con Kettlebell doble rodilla sobre dedos', 'Con Kettlebells en rack frontal, baja en sentadilla split permitiendo que la rodilla delantera sobrepase la punta del pie.'),
('3e8288b7-c007-48d2-854c-b97ae685e56e', '3063ebe9-d92d-4ef1-ac67-f7ba93125723', 'en', 'Barbell Semi-Stiff Leg Deadlift', 'Lower the bar brushing the legs with fixed knees (minimal flexion). Objective: maximum hamstring stretch. Cue: hips backward. Common error: curving the lumbar area when descending.'),
('4f5e103f-b05a-4cbb-b086-c50758651881', '3063ebe9-d92d-4ef1-ac67-f7ba93125723', 'es', 'Peso muerto piernas semi-rígidas con barra', 'Baja la barra rozando las piernas con rodillas fijas (mínima flexión). Objetivo: estiramiento máximo de isquios. Cue: cadera hacia atrás. Error común: curvar la zona lumbar al descender.'),
('deeacbf6-c5fd-4871-b60a-ba0ca627dfef', '3067ee34-0e6b-492c-bc5e-41d54db0499d', 'en', 'Double Dumbbell Cuban Rotation', 'Standing, perform a high row and then externally rotate the shoulders to bring the dumbbells overhead. Reverse the movement.'),
('bc35aa37-9f3e-4f09-83df-a4ab17909bda', '3067ee34-0e6b-492c-bc5e-41d54db0499d', 'es', 'Rotación cubana con mancuernas', 'De pie, realiza un remo alto y luego rota externamente los hombros para llevar las mancuernas por encima de la cabeza. Invierte el movimiento.'),
('4425b8cb-ca5e-41c4-a60b-43482a8577bf', '307545af-fe47-44db-9c05-af71f4d1d7b8', 'en', 'Isometric Squat with Fitball', 'Hold the squat against the wall with the ball on your back and squeeze your knees. Objective: quadriceps and adductor endurance. Cues: knees at 90 degrees. Common error: lifting heels off the floor.'),
('45888adf-cef9-4955-ae3f-63128fcd3d0f', '307545af-fe47-44db-9c05-af71f4d1d7b8', 'es', 'Sentadilla isométrica con fitball', 'Mantén la sentadilla contra la pared con la bola en la espalda y aprieta las rodillas. Objetivo: resistencia de cuádriceps y aductores. Cues: rodillas a 90 grados. Error común: despegar los talones del suelo.'),
('f0fa5442-384d-4a84-9898-044dec5109dc', '3086853b-85eb-4817-81b2-7d4833fe68bc', 'en', 'Overhead Cable Triceps Extension', 'With back to the pulley, extend arms overhead. Objective: long head of the triceps. Cue: fully straighten arms. Common error: arching the lower back excessively.'),
('b8f595cd-657a-481c-be66-0c34f60e55be', '3086853b-85eb-4817-81b2-7d4833fe68bc', 'es', 'Tríceps Overhead con cable', 'De espaldas a la polea, extiende los brazos sobre la cabeza. Objetivo: cabeza larga del tríceps. Cue: estira los brazos por completo. Error común: arquear la zona lumbar excesivamente.'),
('7e0fd975-163b-49b6-a4ae-6624af24d6f2', '308aaada-35e9-4dda-8726-fb4f3b85a7e3', 'en', 'Lateral Barbell Burpee', 'Perform a burpee parallel to a barbell and jump laterally over it to repeat. Combines cardio and agility. Cue: jump with feet together. Common error: stepping on the bar when jumping.'),
('5a33c645-2e31-4087-98cb-2e513ab9c921', '308aaada-35e9-4dda-8726-fb4f3b85a7e3', 'es', 'Burpee lateral sobre barra', 'Realiza un burpee paralelo a una barra y salta lateralmente sobre ella para repetir. Combina cardio y agilidad. Cue: salta con pies juntos. Error común: pisar la barra al saltar.'),
('a9cbf997-ff6b-4f6b-88f8-556a3a91cc2e', '309506b4-3b2b-4fa5-81ea-cd72106707eb', 'en', 'Machine Shrugs', 'Standing or seated depending on design, lift shoulders against resistance. The machine provides stability and allows using heavy loads safely. Maintain top contraction and avoid rotating shoulders.'),
('8c21e29d-b226-4e95-8588-f892993e2317', '309506b4-3b2b-4fa5-81ea-cd72106707eb', 'es', 'Shrugs máquina', 'De pie o sentado según el diseño, eleva los hombros contra la resistencia. La máquina proporciona estabilidad y permite usar cargas pesadas de forma segura. Mantén la contracción superior y evita rotar los hombros.'),
('abfc2912-b04e-4407-bf24-12a3e950b4da', '30a88ab2-a850-4d82-a6ae-863ab182e1d3', 'en', 'Barbell Good Morning', 'With the bar on the trapezius as in a squat, lean forward from the hips keeping the knees slightly flexed. Descend until the torso is almost parallel to the floor. Return up by contracting glutes and hamstrings. Requires perfect technique.'),
('26000b94-edbf-4515-b6a7-862e0c8f75ff', '30a88ab2-a850-4d82-a6ae-863ab182e1d3', 'es', 'Good morning barra', 'Con la barra sobre los trapecios como en sentadilla, inclínate hacia adelante desde las caderas manteniendo las rodillas ligeramente flexionadas. Desciende hasta que el torso esté casi paralelo al suelo. Vuelve a la posición inicial contrayendo glúteos e isquiotibiales. Requiere técnica perfecta.'),
('a2031417-e8fe-4e5f-bcaa-576c52f685d8', '30da3eab-f4c8-4083-a9ae-49ea1e45059f', 'en', 'Lying Leg Curl', 'Face down, flex knees bringing the roller to the glutes. Cue: keep hips glued to the bench. Error: lifting the pelvis during flexion.'),
('4869db16-8c08-41e5-8986-99298774679c', '30da3eab-f4c8-4083-a9ae-49ea1e45059f', 'es', 'Curl de piernas acostado', 'Boca abajo, flexiona rodillas llevando el rodillo a los glúteos. Cue: mantén la cadera pegada al banco. Error: levantar la pelvis al flexionar.'),
('1b2b22f4-8961-469c-94ec-94cf41383006', '31104a16-0524-49f7-b8de-e7b512ec52a2', 'en', 'Z bar Wide Grip Strict Bicep Curl', 'With your hands on the wide part of the Z bar and your back against the wall, perform the curl without using body momentum.'),
('6fcbef3f-a4e5-486a-b8b5-6a866ae3e562', '31104a16-0524-49f7-b8de-e7b512ec52a2', 'es', 'Curl de bíceps estricto agarre ancho con barra Z', 'Con las manos en la parte ancha de la barra Z y la espalda contra la pared, realiza el curl sin usar impulso del cuerpo.'),
('33d77dfb-3187-4dab-beb6-e45bf6c22f55', '31126017-f194-4999-9fc4-d3cdab15ab84', 'en', 'Incline Cable Flyes', 'Cable flyes on an incline bench to isolate the pectoral with continuous tension throughout the entire range of motion.'),
('1df9129c-9550-4f99-91a1-1064d9fe9bb1', '31126017-f194-4999-9fc4-d3cdab15ab84', 'es', 'Aperturas inclinadas en cable', 'Codo semiflexionado, abre hasta estirar pectoral sin dolor y cierra ‘abrazando’ al frente. Control total.'),
('be0d3831-dab4-460c-9b91-ea1ef3234250', '3142943b-1fd0-45e8-9ba9-b4e1b579d488', 'en', 'One-Arm Ring Passive Hang', 'Hang from a single ring with one arm fully extended. Maintain position to work grip strength and scapular stability.'),
('944ae52a-1a47-4722-babf-2cb840e5fda3', '3142943b-1fd0-45e8-9ba9-b4e1b579d488', 'es', 'Colgado pasivo a una mano en anilla', 'Cuélgate de una sola anilla con un brazo completamente extendido. Mantén la posición para trabajar la fuerza de agarre y la estabilidad escapular.'),
('00180b4c-4b8a-4f96-b11f-792dfd85912c', '316c4535-ccc6-44e0-9736-bb10fac43887', 'en', 'Trap Bar Overhead Press', 'Standing inside the trap bar, grip the side handles and press the bar overhead until elbows are locked, keeping the core tight.'),
('7640fbe8-3115-4084-896b-b62ef086dee5', '316c4535-ccc6-44e0-9736-bb10fac43887', 'es', 'Press Overhead con barra Trap', 'De pie dentro de la barra Trap, sujeta las asas laterales y presiona la barra sobre la cabeza hasta bloquear los codos, manteniendo el core firme.'),
('50cb04ed-8142-439a-a6df-382e8a00e65d', '318ae0bf-37a8-4027-bc37-7a30160e4e03', 'en', 'Diamond Push Ups', 'Place hands together under the chest forming a diamond with index fingers and thumbs touching. Keep elbows close to the body during the descent to maximize triceps activation. Lower controlled until chest touches hands and push forcefully back up. Requires more triceps strength than traditional push-ups.'),
('eaef3d68-1018-41be-b53f-d03e05720fd4', '318ae0bf-37a8-4027-bc37-7a30160e4e03', 'es', 'Flexiones diamante', 'Coloca las manos juntas bajo el pecho formando un diamante con los dedos índices y pulgares unidos. Mantén los codos cerca del cuerpo durante el descenso para maximizar la activación del tríceps. Baja controladamente hasta que el pecho toque las manos y empuja con fuerza para volver arriba. Este ejercicio requiere mayor fuerza en los tríceps que las flexiones tradicionales.'),
('feaef43b-db94-46d5-944a-8177b9833e42', '31a8b19d-0f2f-458b-9476-fdad149c558e', 'en', 'Broad jumps', 'Stand with feet hip-width apart, descend into a half squat, and swing arms back. Explode forward jumping as far as possible. Land with both feet simultaneously, cushioning with the knees. Excellent for developing horizontal power.'),
('25b094e3-7d18-4869-8602-ab79c151c5b8', '31a8b19d-0f2f-458b-9476-fdad149c558e', 'es', 'Broad jumps', 'Colócate con los pies al ancho de las caderas, desciende a media sentadilla y balancea los brazos hacia atrás. Explota hacia adelante saltando lo más lejos posible. Aterriza con ambos pies simultáneamente amortiguando con las rodillas. Excelente para desarrollar potencia horizontal.'),
('a778fbb0-ab4d-4edd-97f3-fbeb3ea2452d', '31b73e40-c4ad-4e5b-be3a-fce7a5898336', 'en', 'Parallette Archer Push Up', 'Archer push-up variant on parallette bars, allowing for a greater range of motion and depth in the descent.'),
('021a0299-8037-4686-bafa-afd139ec1bc8', '31b73e40-c4ad-4e5b-be3a-fce7a5898336', 'es', 'Push up de arquero paralelo', 'Variante de la flexion de arquero sobre las barras paralelas, permitiendo un mayor rango de movimiento y profundidad en el descenso.'),
('26c1e5ad-3378-4e79-bfb0-4b364c9ef996', '31c60b86-d58c-4b4c-8208-0d41eb7b2793', 'en', 'Skater Jump with Hold', 'Perform a lateral jump and balance on the landing leg for 2 seconds before returning. Focused on proprioception. Cue: nail the landing without moving the foot. Common error: lowering the chest too close to the ground.'),
('a7dcca9c-857b-431d-bf57-84ea37554067', '31c60b86-d58c-4b4c-8208-0d41eb7b2793', 'es', 'Salto de patinador con parada', 'Realiza un salto lateral y mantén el equilibrio sobre la pierna de aterrizaje durante 2 segundos antes de volver. Enfocado en la propiocepción. Cue: clava el aterrizaje sin mover el pie. Error común: bajar el pecho demasiado al suelo.'),
('0853179b-60a7-4c13-b2ee-33a17f4784dd', '31e92e1d-56e4-4f01-b05b-fdaa6ac10b15', 'en', 'Coordinated Kettlebell Windmill', 'Weight up, descend laterally to touch the floor with the free hand while looking at the weight. Objective: shoulder stability and obliques. Cue: straight top leg. Common error: bending the knee on the weight side.'),
('5d5d76b0-bdb2-4c99-b17f-dbd28850bc95', '31e92e1d-56e4-4f01-b05b-fdaa6ac10b15', 'es', 'Kettlebell Windmill coordinado', 'Pesa arriba, desciende lateralmente para tocar el suelo con la mano libre mirando la pesa. Objetivo: estabilidad de hombro y oblicuos. Cue: pierna superior estirada. Error común: doblar la rodilla del lado de la carga.'),
('0dfb2f46-63a0-48d3-9107-97c7a5ef4b88', '324e0921-d508-4cc4-9114-7b621fba0e74', 'en', 'Alternating Single Arm Kettlebell Alternating Staggered Stance Swing', 'Execute a swing alternating both the arm and the foot position each rep, coordinating the weight shift in a split stance.'),
('cd191146-cc2f-4fb8-bde2-2bc4e9a592f7', '324e0921-d508-4cc4-9114-7b621fba0e74', 'es', 'Swing con Kettlebell alterno en postura escalonada', 'Ejecuta un swing alternando el brazo y la posicion de los pies en cada repeticion, coordinando el cambio de peso en postura split.'),
('a0e75071-143f-4d65-8f7d-3036415fd832', '3293bcef-2b74-4c07-9d4c-4955ed64e503', 'en', 'Strict Pendlay Row', 'Row bar from the floor each rep with parallel torso. Cue: no momentum. Error: lumbar jerks.'),
('191ddbb4-d329-4c0d-9b86-933fe7fb8187', '3293bcef-2b74-4c07-9d4c-4955ed64e503', 'es', 'Remo Pendlay estricto', 'Rema barra desde el suelo cada repetición con torso paralelo. Cue: sin impulso. Error: tirones lumbares.'),
('c30c5d63-1c2f-4507-9be1-38fd991a1e40', '32a22877-789d-4b55-95e5-c5aefa093845', 'en', 'Stable T-Push Ups', 'Push-up and rotate to the side, lifting one arm. Cue: straight body. Error: losing balance.'),
('ff683b47-323e-40a7-8e5d-7cc81b5784fc', '32a22877-789d-4b55-95e5-c5aefa093845', 'es', 'Flexiones en T estables', 'Flexión y rota a lateral elevando brazo. Cue: cuerpo recto. Error: perder equilibrio.'),
('ac73d6f2-0b92-497d-9dcb-05fd5b6baac2', '32a7c301-9f0e-47a8-8fd9-a45f7803b151', 'en', 'Cable Reverse Crunch', 'Lie on your back with feet hooked to the low pulley. Bring knees toward the chest lifting the hips off the floor against resistance.'),
('1dbd3a16-245d-43c4-966d-648d6793ffab', '32a7c301-9f0e-47a8-8fd9-a45f7803b151', 'es', 'Crunch inverso con cable', 'Acuéstate boca arriba con los pies enganchados a la polea baja. Lleva las rodillas hacia el pecho levantando la cadera del suelo contra la resistencia.'),
('4a1ce2ec-ec51-4474-a3a4-998f4bc1023e', '32b46b32-069d-452a-90ea-18eba87c6979', 'en', 'Barbell Reverse Grip Front Raise', 'Hold the bar with palms up (supine) and lift it in front of you to shoulder height with straight arms.'),
('75f994de-c528-4f84-ba27-fe68fbbbb7bd', '32b46b32-069d-452a-90ea-18eba87c6979', 'es', 'Elevación frontal con agarre inverso y barra', 'Sujeta la barra con las palmas hacia arriba (supino) y elévala frente a ti hasta la altura de los hombros con los brazos rectos.'),
('c5653ef5-5fc6-4eff-b1be-c2391f346db7', '32e19ab6-fe17-4c54-8f2d-07a47f4e5c6f', 'en', 'Static Kettlebell Windmill', 'Weight up, lean the torso to touch the opposite foot while looking at the weight. Objective: shoulder and core stability. Cue: straight top leg. Common error: bending the knee on the weight side.'),
('074fcb67-11cf-41e7-9ff8-6efa17072a20', '32e19ab6-fe17-4c54-8f2d-07a47f4e5c6f', 'es', 'Kettlebell Windmill estático', 'Pesa arriba, inclina el torso para tocar el pie opuesto mirando la pesa. Objetivo: estabilidad de hombro y core. Cue: pierna superior recta. Error común: doblar la rodilla del lado de la pesa.'),
('b8b2b279-0196-4204-8c0f-b7a3731f1659', '3372f96a-f0c1-4221-8c1a-84125a37a34d', 'es', 'Pull-over en polea alta', 'Brazos casi rectos, baja la barra/cuerda hacia muslos sin ‘tirar’ con bíceps. Mantén costillas controladas.'),
('5a448554-9cdd-49e4-83b1-bed0408450ee', '338c25cf-136f-4ef2-8b9f-8432b9f998e6', 'en', 'Single Arm Landmine Tall Kneeling Shoulder Press', 'Kneeling on both legs, press the end of the bar upward in an arc, working shoulders and core in a stable manner.'),
('b6d3a511-552a-4db7-a7ef-24b0907d0786', '338c25cf-136f-4ef2-8b9f-8432b9f998e6', 'es', 'Press de hombros de Rodillas alto con minas terrestres de un solo brazo', 'Arrodillado sobre ambas piernas, presiona el extremo de la barra hacia arriba en arco, trabajando hombros y core de forma estable.'),
('b8ec2e8d-3a2d-4285-9008-2d73ddcfbbc1', '33b76dbd-ad2e-45e9-a531-455c39f20579', 'es', 'Push press barra', 'Press de hombros asistido con impulso de piernas. Realiza un pequeño dip (flexión de rodillas) y usa la extensión explosiva de piernas para ayudar a presionar la barra sobre la cabeza. Permite usar más peso que el press estricto y desarrolla potencia.'),
('4d701d4e-f97a-4f4d-9903-c1513019b03c', '33c7b455-0870-4e1b-8d97-fce1ad4fbb01', 'en', 'Ring Full Front Lever', 'Hold the body fully extended and parallel to the floor facing the ceiling, hanging from the rings with locked arms.'),
('c70a0f88-abd9-4f20-8c8f-317fe6e70e07', '33c7b455-0870-4e1b-8d97-fce1ad4fbb01', 'es', 'Full Front Lever en anillas', 'Manten el cuerpo totalmente estirado y paralelo al suelo de cara al techo, colgado de las anillas con los brazos bloqueados.'),
('60eb6a4d-9615-41d9-898f-83dfdaa1e180', '33ddae5a-f60b-4ded-94fd-f5a38ba39dd9', 'en', 'Cable Rear Delt Raises', 'Leaning forward or standing with the torso parallel to the floor, perform cable rear raises. Can be done unilaterally or bilaterally. Focus on the rear deltoid and avoid using momentum. Keep a slight bend in the elbow.'),
('146ba037-6ddc-4788-a6ca-dc9c8f9bd411', '33ddae5a-f60b-4ded-94fd-f5a38ba39dd9', 'es', 'Elevaciones posteriores cable', 'Inclinado hacia adelante o de pie con el torso paralelo al suelo, realiza elevaciones posteriores con cable. Puedes hacerlo unilateral o bilateral. Enfócate en el deltoides posterior y evita usar impulso. Mantén una ligera flexión en el codo.'),
('1e8ac710-c7fa-406f-9762-70cad6894250', '33fcada7-fb00-4997-a101-422ed9d32f5d', 'en', 'Plate Lu Raise', 'Hold a plate or light dumbbell in each hand. Perform a full lateral raise until the weights touch above the head.'),
('f2485daf-4fa5-45ef-b0af-14f42beb3042', '33fcada7-fb00-4997-a101-422ed9d32f5d', 'es', 'Elevación Lu con discos', 'Sostén un disco o mancuerna ligera en cada mano. Realiza una elevación lateral completa hasta que las pesas se toquen por encima de la cabeza.'),
('3ddf9572-cf49-4c3c-bc09-6dd78caff481', '33fe9899-6ead-421e-b428-b9183f47550e', 'en', 'Single Arm Suspension Contralateral Pistol Squat', 'Hold a single TRX strap with the arm opposite to the supporting leg while performing a deep single-leg squat.'),
('862a06e3-536a-402f-ad9c-68cdfc6543a2', '33fe9899-6ead-421e-b428-b9183f47550e', 'es', 'Sentadilla con pistola contralateral con TRX de un solo brazo', 'Sujeta una sola correa de TRX con el brazo opuesto a la pierna de apoyo mientras realizas una sentadilla profunda a una pierna.'),
('1c777ab1-a6ce-4550-bce7-463d28431920', '3413c11e-8280-42d5-80c2-8c2de1a60629', 'en', 'Kettlebell Snatch', 'Bring the weight from the floor to above the head in a single explosive movement. Hip drive. Arm close to the ear. Do not hit your forearm with the weight.'),
('8408b216-cae4-4845-bc1e-3be538033fa1', '3413c11e-8280-42d5-80c2-8c2de1a60629', 'es', 'Kettlebell Snatch', 'Lleva la pesa desde el suelo hasta encima de la cabeza en un solo movimiento explosivo. Golpe de cadera. Brazo pegado a la oreja. No golpees tu antebrazo con la pesa.'),
('7137f87f-ade2-44df-acbb-d7989127a858', '341cf7ae-5949-4cfc-b178-b0c851b59f39', 'en', 'Low Pulley Rope Bicep Curl', 'Flex bicep with rope on low pulley. Cue: pull ends apart at the top. Error: swinging arms.'),
('f4b13a14-a4d7-4cd4-8de1-b0a169c0d791', '341cf7ae-5949-4cfc-b178-b0c851b59f39', 'es', 'Curl de bíceps polea baja cuerda', 'Flexiona el bíceps con cuerda en polea baja. Cue: abre extremos arriba. Error: balancear brazos.'),
('d20a5933-4df6-4f85-984f-b84985794397', '347e571c-a9fd-4b51-ae25-4b3d863c56f3', 'en', 'One-Arm Ball Toss', 'Push the medicine ball from the shoulder with a single arm as hard as possible. Unilateral power. Cue: use the core to stabilize. Common error: leaning the body to one side when tossing.'),
('4d2b0913-52e9-45f8-9cf1-fef502a50bf8', '347e571c-a9fd-4b51-ae25-4b3d863c56f3', 'es', 'Lanzamiento de balón a una mano', 'Empuja el balón medicinal desde el hombro con un solo brazo lo más fuerte posible. Potencia unilateral. Cue: usa el core para estabilizar. Error común: inclinar el cuerpo hacia un lado al lanzar.'),
('b0861ab2-6220-490a-be84-c17e48489e8d', '349bb768-ae6f-46d5-ba3e-80aef5be1cf1', 'en', 'Farmers Walk', 'Walk a distance carrying heavy dumbbells at your sides. Cue: shoulders back and down, short steps. Error: letting the weight swing your arms.'),
('f00cbd30-8d5d-4bba-bea4-ff5272ea5ce4', '349bb768-ae6f-46d5-ba3e-80aef5be1cf1', 'es', 'Paseo del granjero', 'Camina una distancia cargando mancuernas pesadas a los lados. Cue: hombros atrás y abajo, pasos cortos. Error: dejar que el peso balancee tus brazos.'),
('94e0b9fa-4bb8-4128-928c-2f46da2b7329', '34d9f966-784e-4666-8d5f-d881e783b175', 'en', 'Hanging Knee Elevation', 'Hanging from a bar, lift knees toward the chest in a controlled manner. Objective: lower abdominal. Cue: do not swing. Common error: using leg momentum to rise.'),
('dd9a47f8-4920-443a-a50d-a390d800e1bc', '34d9f966-784e-4666-8d5f-d881e783b175', 'es', 'Elevación de rodillas colgado', 'Colgado de barra, eleva las rodillas hacia el pecho de forma controlada. Objetivo: abdominal inferior. Cue: no te balancees. Error común: usar el impulso de las piernas para subir.'),
('922859a5-580f-477e-8ae8-8b90f7e6c6b7', '34f71bab-7793-4536-8183-23e3961f8ed4', 'en', 'Stability Ball Feet Elevated Crunch', 'Lie face up and place calves on the Fitball. With hands behind the head, contract the abdomen to lift shoulders off the floor. Lower slowly without pulling on the neck.'),
('99e1d4e5-8728-4b00-bc9f-01b480106eb3', '34f71bab-7793-4536-8183-23e3961f8ed4', 'es', 'Crunch elevado con pies en Fitball', 'Acuéstate boca arriba y coloca las pantorrillas sobre el Fitball. Con las manos detrás de la cabeza, contrae el abdomen para levantar los hombros del suelo. Baja lentamente sin tirar del cuello.'),
('9e36acfb-e319-4314-9d0e-90f89188d3fb', '34fbec39-5777-405d-b108-c8954fb96f50', 'en', 'Single Arm Kettlebell Front Rack Squat', 'Hold a kettlebell in the rack position on one shoulder. Perform a deep squat while keeping the torso upright and the elbow of the loaded arm raised to stabilize the weight.'),
('4cc0bbd6-a52a-4be4-81d2-1015b8ab1d08', '34fbec39-5777-405d-b108-c8954fb96f50', 'es', 'Sentadilla frontal a una mano con Kettlebell', 'Sostén una pesa rusa en posición de rack sobre un hombro. Realiza una sentadilla profunda manteniendo el torso erguido y el codo de la carga elevado para estabilizar el peso.'),
('2c09be89-caec-4068-8229-f2ec3fa434c2', '350290d8-5d35-49e0-80e1-5d74a17603b5', 'en', 'Lateral Rollout', 'Roll at a diagonal angle to the sides instead of straight. Emphasizes the obliques. Alternate sides or complete sets per side. Maintain control throughout the movement avoiding excessive rotation.'),
('beb72232-a608-4816-8cb6-96188859d80d', '350290d8-5d35-49e0-80e1-5d74a17603b5', 'es', 'Roll out lateral', 'Rueda en ángulo diagonal hacia los lados en lugar de recto. Enfatiza los oblicuos. Alterna los lados o completa series por lado. Mantén el control durante todo el movimiento evitando la rotación excesiva.'),
('116493da-f995-4182-9539-5dbfb772914f', '351aee73-333f-4f36-abfa-ee2f7427e7da', 'en', 'Lower Cable Crossovers', 'With pulleys in a low position, perform the movement by bringing hands up and toward the center. This variation works the upper portion of the pectoral more. Keep the core engaged to avoid excessively arching the back.'),
('f14574c5-5b6b-43e3-a384-c2575cd93ae3', '351aee73-333f-4f36-abfa-ee2f7427e7da', 'es', 'Cruces inferiores cable', 'Con las poleas en posición baja, realiza el movimiento llevando las manos hacia arriba y al centro. Esta variación trabaja más la porción superior del pectoral. Mantén el core activado para evitar arquear excesivamente la espalda.'),
('a569d33d-7118-40f8-a6a7-3858e338898c', '354eeebc-1742-4455-8c00-7ec61edde651', 'en', 'Lying Hamstring Curl', 'Lying face down, flex knees bringing heels toward the glutes. Keep hips glued to the bench to avoid arching the back. Control the movement in both phases and squeeze at the peak of the contraction.'),
('d2220f91-2398-4b22-8fd3-8968ad39a52d', '354eeebc-1742-4455-8c00-7ec61edde651', 'es', 'Curl femoral tumbado', 'Tumbado boca abajo, flexiona las rodillas llevando los talones hacia los glúteos. Mantén las caderas pegadas al banco para evitar arquear la espalda. Controla el movimiento en ambas fases y aprieta al máximo en la contracción.'),
('b4d70009-ec9d-487c-b29c-e529a2464537', '3550e2e3-b086-4309-b2bf-21a71b71ba4e', 'en', 'Double Kettlebell Overhead Step Up', 'Step up onto the bench while maintaining two kettlebells locked out overhead, demanding maximum shoulder stability and core control.'),
('52431b72-8b71-4411-bbe7-13253a6e668b', '3550e2e3-b086-4309-b2bf-21a71b71ba4e', 'es', 'Step Up Overhead con Kettlebell doble', 'Sube al banco manteniendo dos Kettlebells bloqueadas sobre la cabeza, exigiendo máxima estabilidad de hombros y control del core.'),
('8c111d1d-2388-4e4c-91ad-897850c027d2', '3551d26f-51ad-40b3-aa6d-eeea43af951f', 'en', 'EZ Bar Spider Curl', 'Chest on an incline bench, flex hanging arms. Objective: isolated biceps. Cue: fixed elbows. Error: swinging.'),
('c02bf1e1-a7f1-420f-932a-edf4b13c91b8', '3551d26f-51ad-40b3-aa6d-eeea43af951f', 'es', 'Curl araña barra Z', 'Pecho en banco inclinado, flexiona brazos colgando. Objetivo: bíceps aislado. Cue: codos fijos. Error: balanceo.'),
('93bea0c2-c0cf-4b8f-b692-e8bdef7b7d65', '3552a917-6230-4db8-a22e-be3a9acf1ab2', 'en', 'Back Barbell Split Squat', 'With the bar on the shoulders and one foot forward, lower the back knee toward the floor while keeping the torso upright and rise controlled.'),
('0804a2fe-2ef8-4b1c-8a5a-d69a84230c9a', '3552a917-6230-4db8-a22e-be3a9acf1ab2', 'es', 'Sentadilla Split con barra trasera', 'Con la barra sobre los hombros y un pie adelantado, baja la rodilla trasera hacia el suelo manteniendo el torso erguido y sube controladamente.'),
('07a7df50-c557-4680-bda0-46f473c69de5', '3554fc00-3874-4b53-af15-62e5c248ec7b', 'en', 'Alternating Single Arm Dumbbell Power Snatch', 'Perform the Snatch motion with one hand, lower the dumbbell safely, and repeat alternating the arm with each rep.'),
('05f916f2-990a-4ab2-98d9-7924589697c8', '3554fc00-3874-4b53-af15-62e5c248ec7b', 'es', 'Power Snatch alterno a una mano con mancuerna', 'Realiza el movimiento de Snatch con una mano, baja la mancuerna de forma segura y repite alternando el brazo en cada repeticion.'),
('0d0e012a-c9ce-44db-a0bf-4826fd8604ec', '35629ce0-d38e-478e-ab1c-e3558b7da433', 'en', 'Trap Bar Tall Kneeling Overhead Press', 'Kneeling on both legs (Tall Kneeling), grip the trap bar handles and press it vertically overhead.'),
('625f8b5c-92f8-4334-b82f-49c6825663d6', '35629ce0-d38e-478e-ab1c-e3558b7da433', 'es', 'Press Overhead de rodillas con barra Trap', 'Arrodillado sobre ambas piernas (Tall Kneeling), sujeta la barra Trap por las asas y presionala verticalmente sobre la cabeza.'),
('293efad9-5a0d-46ef-88da-805803d41c7f', '358320d7-bc4e-4219-8737-89c2f62f8b19', 'en', 'Single Arm Kettlebell Bottoms Up Overhead Contralateral Knee Over Toe Split Squat', 'With one foot elevated, hold an upside-down kettlebell overhead with the arm opposite to the front leg and perform a split squat.'),
('c6ca907d-6802-4b0e-86f4-1b764b82a174', '358320d7-bc4e-4219-8737-89c2f62f8b19', 'es', 'Sentadilla Búlgara Overhead contralateral con Kettlebell Bottoms Up', 'Con un pie elevado, sostén la pesa rusa invertida sobre la cabeza con el brazo opuesto a la pierna delantera y realiza la sentadilla.'),
('7e7c7161-b7dc-4549-8804-5d9048b4d9e1', '3598a045-72f1-4546-b5c2-d730200f0eaa', 'en', 'Ring Advanced Tuck Front Lever', 'Maintain the Front Lever position with straight arms and a flat back, but with knees pulled away from the chest at a 90-degree angle.'),
('884f1007-33d4-4ff6-92f0-5f6c221ed1d1', '3598a045-72f1-4546-b5c2-d730200f0eaa', 'es', 'Advanced Tuck Front Lever en anillas', 'Mantén la posicion de Front Lever con los brazos rectos y la espalda plana, pero con las rodillas separadas del pecho formando un angulo de 90 grados.'),
('de8eac38-4bc2-4908-9aa0-0ddfff526ad2', '360693dc-74d1-4cc4-be8c-cd2b19836ba4', 'en', 'Diagonal Pogo Jump', 'Fast jumps on the balls of the feet in a diagonal zigzag trajectory. Improves lateral and frontal agility. Cue: electric ground contacts. Common error: losing the line of movement.'),
('e7d8768b-a631-40a4-8afa-259f51e901f1', '360693dc-74d1-4cc4-be8c-cd2b19836ba4', 'es', 'Salto pogo diagonal', 'Saltos rápidos sobre puntas de pies en trayectoria de zigzag diagonal. Mejora la agilidad lateral y frontal. Cue: contactos eléctricos en el suelo. Error común: perder la línea de movimiento.'),
('16338a7e-ed27-422c-a8b2-f53bce38c503', '362e733c-b23d-4643-adb1-00f44c367ff9', 'en', 'Dumbbell Calf Raises', 'Standing with a dumbbell in each hand at the sides, rise onto the toes as high as possible. Hold maximum contraction for one second and descend slowly. You can perform the exercise on a step for greater range of motion.'),
('e2a6253c-5c83-4707-aabb-6efb06a3a4f1', '362e733c-b23d-4643-adb1-00f44c367ff9', 'es', 'Elevaciones pantorrilla mancuernas', 'De pie con una mancuerna en cada mano a los lados, elévate sobre las puntas de los pies lo más alto posible. Mantén la contracción máxima por un segundo y desciende lentamente. Puedes realizar el ejercicio en un step para mayor rango de movimiento.'),
('11220729-1be8-45d7-8136-6b18cbda058a', '36796f2e-a615-4ab3-99f7-9f608a1f4af9', 'en', 'Single Arm Kettlebell Bottoms Up Front Rack Walking Lunge', 'Walk performing lunges with an upside-down kettlebell on one shoulder, creating a high demand for lateral stabilization and grip strength.'),
('fbc3dfdb-5bfc-4678-80b7-d7690810eff1', '36796f2e-a615-4ab3-99f7-9f608a1f4af9', 'es', 'Zancada caminando Front Rack con Kettlebell a una mano Bottoms Up', 'Camina realizando zancadas con una Kettlebell invertida en un hombro, lo que genera una gran demanda de estabilización lateral y de agarre.'),
('03c9ec28-129a-47d0-ad7d-9abc24458d55', '3681c7e5-aa97-4540-940e-9503d1df8dff', 'es', 'Planche push ups', 'Desde la posición de planche (cuerpo horizontal sostenido solo por las manos), realiza flexiones manteniendo el cuerpo paralelo al suelo sin apoyo de los pies. Es uno de los ejercicios de peso corporal más difíciles, requiriendo años de entrenamiento progresivo.'),
('7c0cd1f5-e548-4831-97d9-36491d277757', '3689d89a-fb3d-4c8f-bcda-3118cca90c04', 'en', 'Single Arm Dumbbell Prone Row', 'Lying face down on a bench, row a single dumbbell toward your side, focusing on the isolation of the latissimus dorsi.'),
('637618d2-43a0-4add-9d1a-07fe38641ec2', '3689d89a-fb3d-4c8f-bcda-3118cca90c04', 'es', 'Remo prono con mancuerna a una mano', 'Tumbado boca abajo sobre un banco, rima una sola mancuerna hacia tu costado, enfocándote en el aislamiento del dorsal ancho.'),
('7e7bec77-04c6-47b4-97fe-4338dadeb729', '36a7c074-c2a0-427e-87fb-8f50a44833fc', 'en', 'Staggered Stance Mace Slam', 'Strike a tire using a macebell from a staggered stance, focusing the effort on core rotation and power.'),
('64b8b1c8-4fd4-4bf1-984b-aaf27d438f78', '36a7c074-c2a0-427e-87fb-8f50a44833fc', 'es', 'Slam con maza en postura escalonada', 'Golpea un neumatico utilizando una maza (macebell) desde una postura escalonada, enfocando el esfuerzo en la rotacion y potencia del core.'),
('b0bdda3b-e497-487a-a2ed-cba7a7f364f0', '36e1c561-ade8-4ce5-b30e-b8394fbf7dbe', 'en', 'Vertical Jump Squat', 'Explosive squat ending in a maximum jump. Cue: land on your toes. Error: landing with stiff legs.'),
('4fbf3f18-633d-41f9-b99a-7fe73fc86ade', '36e1c561-ade8-4ce5-b30e-b8394fbf7dbe', 'es', 'Sentadilla con salto vertical', 'Sentadilla explosiva terminando en salto máximo. Cue: aterriza con las puntas. Error: aterrizaje con piernas rígidas.'),
('fcf9418b-74e4-4b77-8a3e-987a3189b8f8', '36fda61c-c995-4c20-9cf8-be9c7499aa8d', 'es', 'Peso muerto velocidad', 'Peso muerto con 50-70% del máximo enfocándose en velocidad explosiva. Desarrolla potencia. Mantén técnica perfecta a pesar de la velocidad. Útil para romper mesetas. Descansa completamente entre series.'),
('74c7b61d-8376-4171-ae97-b0ea4852da86', '37064e38-6523-4201-8461-46040b60e8ca', 'en', 'Miniband Quadruped Hip Extension', 'On all fours with the band around your knees, kick upward with one leg to isolate the glute against the resistance.'),
('8e839022-a3bb-44d8-97dc-00b0a8ade367', '37064e38-6523-4201-8461-46040b60e8ca', 'es', 'Extensión de cadera en cuadrupedia con Miniband', 'En cuatro puntos con la banda en las rodillas, patea hacia arriba con una pierna para aislar el glúteo contra la resistencia.'),
('a46e98cd-65ca-416c-ba2a-22ec5725d523', '37163481-1acf-4b6f-b6a3-6c8504ec21eb', 'en', 'Sit Up', 'Lie on your back with knees bent. Lift the full torso off the floor using abdominals until sitting upright, then lower while controlling the movement.'),
('772c65b7-e351-466a-8109-f0aa47ecf71f', '37163481-1acf-4b6f-b6a3-6c8504ec21eb', 'es', 'Sit Up', 'Acuéstate boca arriba con las rodillas dobladas. Levanta el torso completo del suelo usando los abdominales hasta quedar sentado, luego baja controlando el movimiento.'),
('615a4180-d966-4acc-816e-0ddcd81d5524', '3718dc21-31c5-48b3-b706-6f0927a0bbe3', 'en', 'Battle ropes mountain climber', 'Alternate between mountain climbers and waves with the ropes. Perform several climber reps, then incorporate the ropes. Requires exceptional coordination and stamina. Keep transitions fluid between movements.'),
('29f80af9-dba3-430f-b41f-43d3aaf92d1e', '3718dc21-31c5-48b3-b706-6f0927a0bbe3', 'es', 'Battle ropes mountain climber', 'Alterna entre mountain climbers y ondas con las cuerdas. Realiza varias repeticiones de climbers, luego incorpora las cuerdas. Requiere coordinación excepcional y resistencia. Mantén las transiciones fluidas entre movimientos.'),
('1ca9dba0-ed79-4f94-b151-5ef8fda8dbf7', '37468db5-467a-4968-baab-a2833395cc5d', 'en', 'Overhead Rope Cable Triceps Extension', 'Perform an overhead rope cable triceps extension facing away from a high pulley. Bring the rope overhead and extend the elbows while keeping the upper arms stable.'),
('e4a19223-2887-4b04-873c-45817aaa2174', '37468db5-467a-4968-baab-a2833395cc5d', 'es', 'Cuerda para triceps de espaldas a polea alta', 'Realiza una extensión de tríceps con cuerda de espaldas a una polea alta. Lleva la cuerda por encima de la cabeza y extiende los codos manteniendo los brazos estables.'),
('97cd159c-8efa-46f5-bc27-eb6b48e92edc', '374924cc-c39d-4758-88ca-c0848f3acf00', 'en', 'Barbell Clean', 'Bring the bar from the floor to shoulders in an explosive movement. Cue: full hip extension, fast elbows. Error: pulling only with the arms.'),
('c65c3d53-0e7c-4b81-80d5-81a7d61e858d', '374924cc-c39d-4758-88ca-c0848f3acf00', 'es', 'Clean con barra', 'Lleva la barra del suelo a los hombros en un movimiento explosivo. Cue: extensión total de cadera, codos rápidos. Error: tirar solo con los brazos.'),
('514227de-98a3-4609-b203-b7119d9e4051', '37543c6d-b3e4-45e3-a7b4-084e8c2af009', 'en', 'Double Kettlebell Gorilla Row', 'Standing with legs apart and two kettlebells on the floor. Lean over and row one weight while pushing the other against the floor, alternating sides.'),
('ba8c830c-2fac-40ce-a2a7-575310c23f61', '37543c6d-b3e4-45e3-a7b4-084e8c2af009', 'es', 'Gorilla Row con Kettlebell doble', 'De pie con piernas separadas y dos pesas rusas en el suelo. Inclínate y rema una pesa mientras empujas la otra contra el suelo, alternando lados.'),
('6ba7a6c2-93c3-46f8-b4d4-c6f0358b97f7', '37b86011-9862-42ee-bcb2-10c0ec36c6a2', 'en', 'Ring Full Planche', 'Extreme static position where the body is held horizontal supported only by the hands on the rings with locked arms.'),
('d1226e32-c64d-408e-b831-8c4b94af182a', '37b86011-9862-42ee-bcb2-10c0ec36c6a2', 'es', 'Anillas Plancha Completa', 'Posicion estatica extrema donde el cuerpo se mantiene horizontal apoyado solo en las manos en las anillas con brazos bloqueados.'),
('64f016cc-5bbf-4bc0-96e4-7b09b3964005', '37dd543c-5d70-4cad-80e9-0f07ad80f56f', 'en', 'Behind-the-Neck Barbell Step-up', 'Step onto the box with a barbell. Objective: unilateral strength. Cue: push with the upper leg. Error: jumping.'),
('ebd3ff6c-3d82-4eae-a6a3-39f72ceeb371', '37dd543c-5d70-4cad-80e9-0f07ad80f56f', 'es', 'Step-up con barra nuca', 'Sube cajón con barra. Objetivo: fuerza unilateral. Cue: empuja pierna arriba. Error: saltar.'),
('1f3ec1ae-fa19-43b5-ae8a-3af53ddd6979', '37e23814-ab7d-4712-9bfe-a1c969191302', 'en', 'Barbell Floor Press', 'Floor press with a barbell. Objective: lockout strength. Cue: triceps touch the floor softly. Error: bouncing.'),
('6d6aefbe-f7b2-470e-a926-406b5ddede0b', '37e23814-ab7d-4712-9bfe-a1c969191302', 'es', 'Floor Press barra', 'Press en suelo con barra. Objetivo: fuerza de bloqueo. Cue: tríceps tocan suelo suave. Error: rebotar.'),
('1463a651-cc13-45ab-9353-86123363e8c7', '37ea5f10-beb2-48c5-903c-976397c7a3c9', 'es', 'Pike a una pierna sobre Fitball', 'En plancha con un pie sobre el Fitball y el otro extendido arriba. Eleva las caderas hacia el techo manteniendo la pierna de apoyo recta, formando una V invertida.'),
('f0611984-9434-485c-84d3-30de2948a853', '37fbe299-ef85-4df2-af34-84d92e283729', 'en', 'Double Kettlebell Overhead Pistol Squat', 'Deep single-leg squat while holding two kettlebells locked out overhead, the highest level of weighted balance.'),
('8eca9dd7-1fc6-4a1d-a03e-247cf85380c1', '37fbe299-ef85-4df2-af34-84d92e283729', 'es', 'Sentadilla con pistola por encima de la cabeza con doble pesa rusa', 'Sentadilla profunda a una pierna manteniendo dos Kettlebells bloqueadas sobre la cabeza, el nivel mas alto de equilibrio con peso.'),
('775ab7e7-eb71-4358-a023-2a8bcb800796', '380112c2-ec6e-499f-aadb-5d7c940e2ac9', 'en', 'Plate Seated Steering Wheel', 'Sitting with a straight back, hold a plate in front of you with straight arms and rotate it from side to side like a steering wheel.'),
('c35a36f8-76dc-4ebc-b763-a376333c0526', '380112c2-ec6e-499f-aadb-5d7c940e2ac9', 'es', 'Volante sentado con disco', 'Sentado con la espalda recta, sujeta un disco frente a ti con los brazos estirados y gíralo de lado a lado como si fuera un volante.'),
('271b795c-1ead-46a8-8a69-f8663ec3f771', '3804d33b-5a05-4cab-aef7-1b15f7252464', 'en', 'Gironda Row', 'Gironda style row for lat/back emphasis, seeking range and scapular contraction with clean technique.'),
('994cf56d-2d86-4744-ae9e-f3ec3aae7c13', '3804d33b-5a05-4cab-aef7-1b15f7252464', 'es', 'Remo Gironda', 'Tira llevando codos hacia atrás, pecho estable y escápulas se juntan al final. Evita balancear el tronco.'),
('57b0e35a-61b9-451d-bc84-6297f7223b5e', '381004c5-7421-4e41-9706-abe256101e71', 'es', 'Woodchopper con mancuerna', 'Sujeta una mancuerna con ambas manos. Inicia el movimiento desde un lado de la cadera y eleva la pesa en diagonal hacia el hombro contrario, girando el torso. Controla el descenso. Objetivo: fuerza rotacional del core y oblicuos. Cue: pivota sobre el pie trasero para proteger la rodilla. Error común: mover solo los brazos sin rotar el tronco.'),
('6f286bf7-689f-46f9-99f9-e7a4319073d8', '381fbf9f-77e7-40c8-a1bc-166cd55859b5', 'es', 'Zancada atrás con elevación de rodilla', 'Realiza una zancada hacia atrás y sube la rodilla al pecho al volver a la posición de pie. Objetivo: equilibrio dinámico y piernas. Cues: clava el pie de apoyo. Error común: realizar el movimiento con prisa perdiendo el control.'),
('4cce43f5-f72f-4f51-8b52-fdcfde2a1c0a', '383712ef-e856-4a95-a6df-f0b420d4856d', 'en', 'Ankle Jumps with Hip Rotation', 'Short toe jumps rotating the hip 90 degrees with each jump. Agility. Upright body. Do not land flat-footed.'),
('38c561b2-9fe5-4266-ba8c-eb072ee7f9f3', '383712ef-e856-4a95-a6df-f0b420d4856d', 'es', 'Saltos de tobillo con rotación de cadera', 'Saltos cortos de puntera girando la cadera 90 grados en cada salto. Agilidad. Cuerpo erguido. No apoyes el pie plano.'),
('f5036e72-efd7-43d3-b557-3c7bc1d5cf9d', '383b660a-f4b4-43bf-af90-5945bd6d57e1', 'es', 'Peso muerto rumano a una pierna en Landmine', 'Realiza un peso muerto rumano sobre una sola pierna sujetando la barra Landmine con el brazo opuesto, mejorando equilibrio y estabilidad lateral.'),
('0443eef4-0b6c-4f1a-8941-e82c53856830', '383e202c-4373-4356-9ea1-f17e40e5105c', 'en', 'Dumbbell Bench Press', 'Lying on a flat bench, push the dumbbells from the chest. Objective: pushing strength and pectoral stability. Cue: control the descent. Common error: clashing the weights loudly at the top.'),
('71f41225-d586-41cb-84ed-516a63bf71c0', '383e202c-4373-4356-9ea1-f17e40e5105c', 'es', 'Press de banca con mancuernas', 'Tumbado en banco plano, empuja las mancuernas desde el pecho. Objetivo: fuerza de empuje y estabilidad pectoral. Cue: controla el descenso. Error común: chocar las pesas ruidosamente arriba.'),
('60aa4c55-4608-47d7-93b2-9b55b9d48ff7', '38535754-39b2-4bd0-89d8-71bcf7745848', 'en', 'Alternating Double Kettlebell Bottoms Up Bench Press', 'Lying down, alternate pressing two upside-down kettlebells, holding one up while the other lowers, challenging motor control.'),
('5b4f6322-e2c9-454b-9306-711662d98986', '38535754-39b2-4bd0-89d8-71bcf7745848', 'es', 'Press de banca alterno con Kettlebell doble Bottoms Up', 'Tumbado, alterna el press de dos Kettlebells invertidas, manteniendo una en alto mientras la otra baja, desafiando el control motor.'),
('d030798f-06fe-4e6b-8233-47a524568df0', '38556616-33c5-47f0-a4b3-22488ab7957b', 'en', 'Ring Support Hold', 'Hold yourself in a vertical position on the rings with straight and locked arms, stabilizing the body against the shaking.'),
('6ed84c12-b751-4411-b64c-ba086bde23d2', '38556616-33c5-47f0-a4b3-22488ab7957b', 'es', 'Ring Support Hold', 'Mantente en posicion vertical sobre las anillas con los brazos estirados y bloqueados, estabilizando el cuerpo contra el temblor.'),
('24d134ea-ef53-41eb-b2a0-87518764b5e8', '388d28b2-b73a-432b-84fc-51c62d3b8c89', 'en', 'Pulley Glute Kickback', 'Facing the pulley, extend leg backward. Cue: do not arch the lower back when kicking. Error: rotating hip to the side.'),
('27f28557-890d-457c-8cff-8f75b4c319fb', '388d28b2-b73a-432b-84fc-51c62d3b8c89', 'es', 'Patada de glúteo en polea', 'De frente a la polea, extiende la pierna hacia atrás. Cue: no arquees la espalda baja al patear. Error: girar la cadera hacia un lado.'),
('8153195b-f5cd-4163-903d-6d8d6260d6c8', '38a86f34-d757-4035-8cc5-09eef1291d86', 'en', 'V-Sit Medicine Ball Toss', 'Seated in a V-sit, throw the ball laterally. Oblique power. Legs raised. Do not touch the floor with your feet.'),
('378a4ae1-066e-4a9c-8280-83bf8d477876', '38a86f34-d757-4035-8cc5-09eef1291d86', 'es', 'Lanzamiento de balón medicinal en V', 'Sentado en V, lanza el balón lateralmente. Potencia de oblicuos. Piernas elevadas. No toques el suelo con los pies.'),
('d06d7574-3e00-44aa-89a7-a561af0ff0d5', '38fbcd38-14b0-4e10-8dd2-7c5ffbb95e4c', 'en', 'Kneeling Barbell Rollout', 'Kneeling, hold a barbell loaded with small plates. Slide the bar forward extending the body without arching the back and return using the abdomen.'),
('c8e812cf-d9be-4579-b82d-3b70c8f22cd4', '38fbcd38-14b0-4e10-8dd2-7c5ffbb95e4c', 'es', 'Rollout de rodillas con barra', 'De rodillas, sujeta una barra cargada con discos pequeños. Desliza la barra hacia adelante extendiendo el cuerpo sin arquear la espalda y regresa usando el abdomen.'),
('894e2fa2-1468-422e-9158-c933ab60f324', '390a015a-9090-4438-af06-1ae1a1f1cbe7', 'en', 'Depth Jump to Unilateral Landing', 'Drop from a box and land on a single leg, sticking the balance. Cue: cushion softly with knee aligned. Common error: heavy landing on the heel.'),
('e9968384-b43d-416b-bb86-61c4811e942c', '390a015a-9090-4438-af06-1ae1a1f1cbe7', 'es', 'Salto profundidad aterrizaje unilateral', 'Cae de un cajón y aterriza sobre una sola pierna clavando el equilibrio. Cue: amortigua suave con la rodilla alineada. Error común: caída pesada con el talón.'),
('e4801cea-238e-42ef-9071-c74ea65e2685', '3916e712-b610-4e86-938f-c47af2b162cf', 'es', 'Plancha up-down', 'Comienza en plancha sobre antebrazos y transiciona a plancha alta extendiendo un brazo a la vez hasta apoyarte en las manos. Luego regresa a la posición de antebrazos. Alterna el brazo que inicia el movimiento. Mantén las caderas estables evitando la rotación durante las transiciones.'),
('5ee8de3b-d0fd-498c-92e0-a8cce721c2d8', '3919b162-ec0e-43dc-86f5-baed6fbb33d3', 'en', 'Dead hang', 'Hang from the bar to decompress shoulders and activate grip, lats, and scapular musculature.'),
('d2b87b8d-d762-4a25-a45d-226630e3f12e', '3919b162-ec0e-43dc-86f5-baed6fbb33d3', 'es', 'Dead hang', 'Cuelga con agarre firme 20–30s. Hombros activos (ligera depresión escapular) si buscas control y estabilidad.'),
('09c81b3a-911f-4afe-afed-1aed98b1da0e', '3927f0ec-f495-434c-8d8e-ac14d03861c2', 'en', 'Dumbbell Hammer Bicep Curl', 'Flex weights with neutral grip (palms facing each other). Cue: elbows tucked. Error: swinging body.'),
('e756afa5-d5f0-47a3-84bb-1f039ead16b9', '3927f0ec-f495-434c-8d8e-ac14d03861c2', 'es', 'Curl de bíceps martillo mancuernas', 'Flexiona pesas con agarre neutro (palmas enfrentadas). Cue: codos pegados. Error: balancear cuerpo.'),
('7ca1b414-7afc-4cba-9bc0-7f877569dce2', '393c069f-bda1-4d39-b122-6228c6ba6e4c', 'es', 'Progresiones palanca', 'Serie de ejercicios progresivos hacia palanca frontal y posterior: tuck, advanced tuck, straddle, half lay, full. Cada progresión requiere semanas o meses de trabajo. Paciencia y consistencia son clave. Trabaja negativos y estáticos.'),
('85e3f7cf-8273-4e8a-ac73-9baa4b1b5d82', '3982c4a4-5bc2-46d7-883d-9a19e498f7a9', 'en', 'Battle Ropes Power Jumps', 'Jump and slam ropes. Objective: total power. Cue: high jump. Error: stiff landing.'),
('518c41fe-4b4a-4a95-a427-5750d86f2192', '3982c4a4-5bc2-46d7-883d-9a19e498f7a9', 'es', 'Battle ropes saltos potencia', 'Salta y golpea cuerdas. Objetivo: potencia total. Cue: salto alto. Error: aterrizaje rígido.'),
('07b3f5cf-92b6-456f-a09e-d85354706e65', '3993991e-0cc2-4118-b658-e47ee058039f', 'en', 'Double Kettlebell Bottoms Up Overhead Knee Over Toe Split Squat', 'Split squat with elevated foot and upside-down kettlebells locked overhead, driving the front knee over the toes.'),
('89ed2ae3-93c1-4bdb-ac5a-90990c9168d6', '3993991e-0cc2-4118-b658-e47ee058039f', 'es', 'Sentadilla Búlgara Overhead con Kettlebell doble Bottoms Up', 'Sentadilla split con pie elevado y Kettlebells invertidas bloqueadas arriba, llevando la rodilla delantera sobre los dedos.'),
('5af8223c-ca60-4509-80ab-72001cc30ddc', '39eeda8b-3815-447c-940e-a747b9c5ba24', 'en', 'Pistol Squat', 'Perform a deep squat on a single leg while keeping the other leg extended forward without touching the ground.'),
('394410d2-d6c6-4f06-85fc-03ab818d8041', '39eeda8b-3815-447c-940e-a747b9c5ba24', 'es', 'Sentadilla Pistola (Pistol Squat)', 'Realiza una sentadilla profunda sobre una sola pierna mientras mantienes la otra pierna extendida hacia adelante sin tocar el suelo.'),
('7900879e-4945-4708-8f52-1a06b9b5634b', '3a0140b6-51e2-4d8f-977b-7f5cdccd76c3', 'en', 'Suspension Knee Tuck', 'Place feet in the TRX stirrups and get into a plank position. Bring both knees toward the chest simultaneously and then extend them back to the starting position.'),
('75e480f7-ef27-4394-b396-528758af75f8', '3a0140b6-51e2-4d8f-977b-7f5cdccd76c3', 'es', 'Knee Tuck en TRX', 'Coloca los pies en los estribos del TRX y ponte en posición de plancha. Lleva ambas rodillas hacia el pecho simultáneamente y luego extiéndelas de nuevo a la posición inicial.'),
('8c2b44b0-7054-4147-b995-aa31fddea15d', '3a0353ba-55bf-4d34-bbae-0326e5362e1c', 'en', 'Barbell Bicep Curl', 'Standing, hold a bar with supinated grip (palms up). Flex elbows to lift the bar toward the chest and lower controlled.'),
('558fa0ae-e061-4b9d-be5e-23296874152e', '3a0353ba-55bf-4d34-bbae-0326e5362e1c', 'es', 'Curl de bíceps con barra', 'De pie, sostén una barra con agarre supino (palmas arriba). Flexiona los codos para levantar la barra hacia el pecho y baja controlado.'),
('7076fe65-3664-43bd-a719-7c735eb98189', '3a293767-95cc-4ca9-9bf2-f14f29aefbf0', 'en', 'Seated Overhead EZ Bar Triceps Extension', 'Sit holding an EZ bar overhead. Lower the bar behind the neck flexing elbows and extend back up.'),
('e1c042be-236b-405c-a709-474160064cf5', '3a293767-95cc-4ca9-9bf2-f14f29aefbf0', 'es', 'Extensión de tríceps Overhead sentado con barra Z', 'Siéntate sosteniendo una barra Z sobre la cabeza. Baja la barra por detrás de la nuca flexionando los codos y extiende de nuevo hacia arriba.'),
('cb2473b7-8322-46a9-acc5-4960c3140ccf', '3a7df41a-0ce3-477e-b72f-1e2e1d7285b1', 'en', 'One-Arm Bottoms Up Kettlebell Cyclist Thruster', 'Perform a cyclist thruster holding the kettlebell inverted (bottom up), which demands extreme shoulder and core stability control.'),
('aec85501-f903-4e7b-9337-0f3b6f2562d1', '3a7df41a-0ce3-477e-b72f-1e2e1d7285b1', 'es', 'Thruster Ciclista a una mano con Kettlebell Bottoms Up', 'Realiza un thruster ciclista sosteniendo la Kettlebell invertida (fondo arriba), lo que exige un control extremo de la estabilidad del hombro y del core.'),
('bc1c3b12-cad6-411a-8302-933bffd2c3d9', '3a88303c-a4d2-47fa-89d1-e5f78f5fd342', 'en', 'Supinated Barbell Yates Row', 'Bent-over row with palms facing up at 45 degrees. Objective: lower lat and biceps. Cue: pull toward the navel. Common error: using leg momentum to lift.'),
('63852be1-acb0-4aee-885d-84634d61db21', '3a88303c-a4d2-47fa-89d1-e5f78f5fd342', 'es', 'Remo Yates supinado con barra', 'Remo inclinado con palmas hacia arriba a 45 grados. Objetivo: dorsal inferior y bíceps. Cue: tira hacia el ombligo. Error común: usar balanceo de piernas para subir.'),
('98623409-105b-4dc6-a994-2e5c05194394', '3a8a5928-efdf-4071-844d-685aa0f009a9', 'en', 'Romanian Deadlift', 'Perform a Romanian deadlift by pushing the hips back with a slight knee bend. Lower the load under control while keeping the back neutral and return by extending the hips.'),
('b4b90e08-532b-49eb-91a1-fb328d1e9f00', '3a8a5928-efdf-4071-844d-685aa0f009a9', 'es', 'Peso muerto rumano', 'Realiza un peso muerto rumano llevando la cadera hacia atrás con una ligera flexión de rodillas. Baja la carga de forma controlada manteniendo la espalda neutra y vuelve extendiendo la cadera.'),
('10473b6a-48a8-4903-8a60-873934550b44', '3a9713f8-65fb-4560-b114-99ff2a12941b', 'en', 'Seated Hip Abduction with Miniband', 'Sit on the edge of a bench with a band above the knees. Push your knees outward against the band while keeping your feet planted.'),
('9a29d7ca-04d1-4612-85a3-36dcf1a1f4c1', '3a9713f8-65fb-4560-b114-99ff2a12941b', 'es', 'Abducción de cadera sentado con Miniband', 'Siéntate en el borde de un banco con una banda sobre las rodillas. Separa las rodillas hacia afuera contra la banda manteniendo los pies plantados.'),
('eb50cbfa-1b2f-48ca-81ba-6dd3b6f204d0', '3aaada73-a02e-4b53-9d86-4a3c17ee40b1', 'en', 'Front Lat Pulldown', 'Perform a front lat pulldown on a cable machine. Pull the bar toward the upper chest by bringing the shoulder blades together and control the return phase.'),
('dcb486a5-6a4a-40b1-9002-e3802f0b5776', '3aaada73-a02e-4b53-9d86-4a3c17ee40b1', 'es', 'Jalones frontales', 'Realiza un jalón frontal al pecho en polea. Tira de la barra hacia la parte alta del pecho juntando las escápulas y controla la fase de subida.'),
('c470ba52-6972-414e-b580-480df22a530e', '3aaff64e-d282-427f-8f3d-036240f19530', 'en', 'Bent Over Barbell Row', 'Lean forward with knees slightly bent and back straight. Pull the bar toward the lower abdomen keeping elbows close to the body. Squeeze shoulder blades at the top. Keep the torso position stable throughout the exercise.'),
('5c2a0961-ab57-42d9-b21c-54648ff8e062', '3aaff64e-d282-427f-8f3d-036240f19530', 'es', 'Remo inclinado barra', 'Inclínate hacia adelante con las rodillas ligeramente flexionadas y la espalda recta. Tira de la barra hacia el abdomen inferior manteniendo los codos cerca del cuerpo. Aprieta los omóplatos en la parte superior. Mantén la posición del torso estable durante todo el ejercicio.'),
('db57a1ae-78f4-411d-a444-d7ff030f9566', '3abc1e3b-1de6-406e-a73d-4713d495a65c', 'en', 'Double Kettlebell Bottoms Up Overhead Pistol Squat', 'Perform a pistol squat while holding two upside-down kettlebells locked overhead, the most challenging stability exercise.'),
('bfd7a8c5-c0b0-473f-83a4-eecebefff3b3', '3abc1e3b-1de6-406e-a73d-4713d495a65c', 'es', 'Sentadilla con pistola por encima de la cabeza con pesas rusas dobles de abajo hacia arriba', 'Realiza una sentadilla pistola manteniendo dos Kettlebells invertidas bloqueadas sobre la cabeza, el ejercicio de estabilidad mas dificil.'),
('b64b38d0-f255-42ac-aec5-558b56507d8a', '3abfff53-f4ea-4e53-a232-a9915516098c', 'en', 'Decline EZ Bar Skull Crusher', 'On a decline bench, perform elbow extension bringing the EZ bar toward the forehead, providing a different tension angle for the triceps.'),
('98510a3e-6821-4e33-8149-66f9d4c1f725', '3abfff53-f4ea-4e53-a232-a9915516098c', 'es', 'Skull Crusher en banco declinado con barra Z', 'En un banco declinado, realiza la extension de codos llevando la barra Z hacia la frente, proporcionando un angulo diferente de tension para el triceps.'),
('4592182f-6a3f-4c5b-be8f-3270eab29a1c', '3b13d84c-832f-473e-982c-feed30fa6d63', 'en', 'Fitball Russian Twists', 'Seated on the fitball or with back supported on it, perform torso rotations. Instability increases the core challenge. You can hold additional weight for higher intensity. Maintain balance during the movement.'),
('a37a13ee-6c7a-44e5-b476-f30d26529200', '3b13d84c-832f-473e-982c-feed30fa6d63', 'es', 'Giros rusos fitball', 'Sentado sobre la fitball o con la espalda apoyada en ella, realiza rotaciones de torso. La inestabilidad aumenta el desafío del core. Puedes sostener peso adicional para mayor intensidad. Mantén el equilibrio durante el movimiento.'),
('1f9a0bb1-fe92-473c-a3e4-19f84c8beb33', '3b7a9c3a-0ccd-4f45-b30a-3dda6695f413', 'en', 'Neutral Seated Incline Hammer Curl', 'Hammer curl on 45-degree bench. Cue: elbows back. Error: moving shoulders.'),
('181a7941-fe50-4652-8b9d-67d697946bbd', '3b7a9c3a-0ccd-4f45-b30a-3dda6695f413', 'es', 'Curl martillo sentado inclinado neutro', 'Curl martillo en banco a 45 grados. Cue: codos atrás. Error: mover hombros.'),
('108c1286-ec08-4dc2-9987-9ffc293fd662', '3b97cd47-c9c2-41b9-99e6-243058adbcf3', 'es', 'Press pecho declinado máquina trayectoria', 'Press sentado hacia abajo. Cue: retrae escápulas. Error: despegar hombros.'),
('73388083-2c55-435d-834e-24fc0973fb54', '3bafbe8d-c781-44d3-8754-1f282e0c54ee', 'en', 'Kettlebell Windmill', 'With a kettlebell extended overhead, perform a controlled lateral flexion touching the floor with the free hand. Keep your eyes on the kettlebell. Requires flexibility, mobility, and shoulder stability. Excellent for the core and lateral chains.'),
('c87a448c-0d44-4e59-bf29-b1ee556a2341', '3bafbe8d-c781-44d3-8754-1f282e0c54ee', 'es', 'Molino de viento kettlebell', 'Con kettlebell extendida sobre la cabeza, realiza una flexión lateral controlada tocando el suelo con la mano libre. Mantén la vista en la kettlebell. Requiere flexibilidad, movilidad y estabilidad del hombro. Excelente para el core y cadenas laterales.'),
('c494bf6e-18a6-4177-a4a2-88d7317515c2', '3bb65159-bbe7-44a3-9e9c-43c45c33f240', 'en', 'Battle Rope Russian Twist', 'Seated with knees bent, move the ends of the battle ropes from side to side across the abdomen with power.'),
('925635bd-1ce2-40d2-9d11-73ab8aa47a05', '3bb65159-bbe7-44a3-9e9c-43c45c33f240', 'es', 'Russian Twist con cuerdas de batalla', 'Sentado con rodillas flexionadas, mueve los extremos de las cuerdas de batalla de un lado a otro cruzando el abdomen con potencia.'),
('e0409423-b4f0-4171-96d1-703850f75524', '3bd0e4f8-9cef-4c70-b0d3-29fa46b5380a', 'en', 'Cable Shoulder Press', 'With low pulleys on both sides or a single pulley, perform shoulder press. The cable provides unique resistance that challenges stabilization. Can be done seated or standing, unilateral or bilateral depending on your goal.'),
('51342ee4-1ec3-4c67-9d99-559becbfb0aa', '3bd0e4f8-9cef-4c70-b0d3-29fa46b5380a', 'es', 'Press hombros cable', 'Con poleas bajas a ambos lados o una sola polea, realiza press de hombros. El cable proporciona una resistencia única que desafía la estabilización. Puedes hacerlo sentado o de pie, unilateral o bilateral según tu objetivo.'),
('83764a91-0d3d-4d8e-a155-3c243e1720a3', '3be4c796-5ca9-4dd1-904b-85ef1f88d36a', 'es', 'Zancada inversa Overhead contralateral con Slider y Kettlebell', 'Sostén una pesa rusa sobre la cabeza. Desliza hacia atrás la pierna del lado opuesto usando un slider, manteniendo el brazo bloqueado.'),
('4b0d70a1-8131-4ae2-aadb-a9f631da6784', '3bf01985-3f13-41ea-a354-60ebe086590d', 'en', 'Ring Dead Hang to Front Lever Pull Up', 'Hang from the rings and lift the body to a horizontal position (Front Lever) then perform a pull-up while maintaining horizontality.'),
('1099ee6d-6b03-40fb-b0a0-de4b6cc814cd', '3bf01985-3f13-41ea-a354-60ebe086590d', 'es', 'Ring Dead Hang para tirar hacia arriba de la palanca delantera', 'Cuelgate de las anillas y eleva el cuerpo hasta posicion horizontal (Front Lever) para luego realizar una dominada manteniendo la horizontalidad.'),
('d4448500-eaf9-4507-8a57-847d71e4277a', '3c13aec4-c2b2-48b0-830f-ad910eea22a8', 'en', 'Front Lunges', 'Take a wide step forward and descend vertically by flexing both knees until they form 90-degree angles. The front knee should not pass the tip of the foot. Push with the front heel to return to the starting position. Alternate legs or complete all repetitions with one leg.'),
('3bbdc255-b4c9-4890-970a-9a2b600f776b', '3c13aec4-c2b2-48b0-830f-ad910eea22a8', 'es', 'Zancadas frontales', 'Da un paso amplio hacia adelante y desciende verticalmente flexionando ambas rodillas hasta formar ángulos de 90 grados. La rodilla delantera no debe sobrepasar la punta del pie. Empuja con el talón delantero para volver a la posición inicial. Alterna las piernas o completa todas las repeticiones con una pierna.'),
('7d896289-6e16-4735-88f2-0b50d6ec89f1', '3c45089e-ff21-42bf-b1e9-085332eef1a2', 'en', 'EZ Bar Preacher Curl', 'Arm supported on a bench, flex the EZ bar to protect wrists. Objective: bicep brachii. Cue: fully straighten the arm at the bottom. Common error: lifting the elbow off the support.'),
('fadbc35c-72ac-4c8d-a166-07fc774d51f1', '3c45089e-ff21-42bf-b1e9-085332eef1a2', 'es', 'Curl predicador con barra Z', 'Brazo apoyado en banco, flexiona la barra Z para proteger muñecas. Objetivo: bíceps braquial. Cue: estira el brazo totalmente abajo. Error común: levantar el codo del apoyo.'),
('d6e2db21-0e9c-45a2-88a1-a0c81cfaaf9f', '3c4734d5-fc14-48fe-b028-387377ee18fd', 'en', 'Ballistic Mace Curl', 'Perform a dynamic curl passing the mace weight from one hand to another with a controlled swinging motion to work biceps and stability.'),
('bb4f529d-6dcf-4245-a5dd-67d07e6c19ae', '3c4734d5-fc14-48fe-b028-387377ee18fd', 'es', 'Curl balístico con maza', 'Realiza un curl dinámico pasando el peso de la maza de una mano a otra con un movimiento de balanceo controlado para trabajar bíceps y estabilidad.'),
('f24539f0-fbe8-4395-9fd6-1dea439a8ac8', '3ca76d30-76ca-41b6-ba21-c3eb91586981', 'en', 'EZ Bar French Press', 'Lying down, lower the bar toward the forehead flexing only elbows. Triceps isolation. Elbows tucked. Do not move arms from the shoulder.'),
('5416f4d2-5d44-41ee-a2e6-29aa84954478', '3ca76d30-76ca-41b6-ba21-c3eb91586981', 'es', 'Press francés con barra Z', 'Tumbado, baja la barra hacia la frente flexionando solo codos. Aislamiento tríceps. Codos cerrados. No muevas los brazos desde el hombro.'),
('df3513db-b5d5-4a2e-a4f6-70345ea90c52', '3d2d5bc0-f3f7-49a3-8038-0aadfffa6c65', 'en', 'Standing Rollout', 'The most difficult ab wheel progression. From a standing position, lean and roll forward to full extension, then return to standing. Requires exceptional core strength and years of progression. Start with partial ranges.'),
('84bb17ff-4bed-42bd-8904-d5431bad5769', '3d2d5bc0-f3f7-49a3-8038-0aadfffa6c65', 'es', 'Rodamiento de pie', 'La progresión más difícil del ab wheel. Desde posición de pie, inclínate y rueda hacia adelante hasta extensión completa, luego vuelve a ponerte de pie. Requiere fuerza de core excepcional y años de progresión. Comienza con rangos parciales.'),
('c49089a2-002f-431e-8c5f-0827db011cfe', '3d56857f-3707-4fa4-b227-449a3db2ef0f', 'en', 'Monster Walks', 'Place a miniband around the legs and walk with controlled steps while keeping constant tension on the band. Keep the knees aligned and the hips stable.'),
('3e8a1a84-20c9-4b55-b1c5-053d6b56601a', '3d56857f-3707-4fa4-b227-449a3db2ef0f', 'es', 'Monster walks', 'Coloca una minibanda alrededor de las piernas y camina con pasos controlados manteniendo tensión constante en la banda. Mantén las rodillas alineadas y la cadera estable.'),
('898911d2-803e-4f91-bd23-9b7d6a1c289a', '3d69344f-4335-412e-9112-a231732e8678', 'en', 'Kettlebell Goblet Lunge', 'Hold the weight at the chest and perform alternating lunges. Core stability. Front knee aligned. Do not lean the torso forward.'),
('35147d70-8260-4095-9a9f-f726cfb01794', '3d69344f-4335-412e-9112-a231732e8678', 'es', 'Kettlebell Goblet Lunge', 'Sostén la pesa al pecho y realiza zancadas alternas. Estabilidad central. Rodilla delantera alineada. No inclines el torso adelante.'),
('2bf56a14-269d-4f8d-9335-1373d156c760', '3d696dad-940a-4356-99b2-b4b8741a5510', 'en', 'Machine Quadriceps Extension', 'Seated in the machine, extend knees to full extension. Adjust backrest so knees align with rotation axis. Especially control the eccentric phase. Excellent for isolating the quadriceps.'),
('02f62908-0ce7-4f13-8f4e-cf20be3e430d', '3d696dad-940a-4356-99b2-b4b8741a5510', 'es', 'Extensión cuádriceps máquina', 'Sentado en la máquina, extiende las rodillas hasta la extensión completa. Ajusta el respaldo para que las rodillas estén alineadas con el eje de rotación. Controla especialmente la fase excéntrica. Excelente para aislar el cuádriceps.'),
('8beabce0-ca86-4f6c-8725-fb120226102e', '3da5d349-4b50-416a-9f9d-3e6d4633b760', 'en', 'Single Arm Kettlebell Bottoms Up Half Kneeling Contralateral Overhead Press', 'In a half-kneeling position, press an upside-down kettlebell with the arm opposite to the leading knee, stabilizing the unstable load.'),
('5eed501e-709e-4355-b788-2beeea2a8150', '3da5d349-4b50-416a-9f9d-3e6d4633b760', 'es', 'Pesa rusa con un solo brazo, de abajo hacia arriba, medio de Rodillas, Press aérea contralateral', 'En posicion de caballero, presiona una Kettlebell invertida con el brazo opuesto a la rodilla adelantada, estabilizando la carga inestable.'),
('08cf0894-a6c5-429b-977a-9c25e3e3eb00', '3e81b502-802c-407f-a839-2d4bc511aac9', 'en', 'Barbell Squat Snatch', 'Lift the bar from the floor to overhead in a single explosive motion, catching it in a deep squat position.'),
('dc1e6e50-4d65-4a98-bcb4-304bbae8d130', '3e81b502-802c-407f-a839-2d4bc511aac9', 'es', 'Squat Snatch con barra', 'Lleva la barra desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, recibiendola en una sentadilla profunda.'),
('576c0590-0485-430e-a4f5-191e17ec60a8', '3eaa6d7f-146a-46b8-b8b1-b93e7cb1d617', 'en', 'Standing Calf Raise', 'Perform a standing calf raise. Lift the heels until standing on the toes, briefly hold the contraction at the top, and lower under control.'),
('227db2e3-2137-42b4-83dd-a755ba7381f8', '3eaa6d7f-146a-46b8-b8b1-b93e7cb1d617', 'es', 'Gemelo de pie', 'Realiza una elevación de gemelos de pie. Eleva los talones hasta ponerte de puntillas, mantén una breve contracción arriba y baja de forma controlada.'),
('e26d70a8-fcf8-4866-a0ad-76f4c267511a', '3edde710-508c-45e8-a93a-02dd12cfc266', 'en', 'Battle Rope Alternating Outward Circle', 'Move both ends of the rope in alternating outward circles while maintaining a solid leg base.'),
('14ae7506-9d4b-4c1a-89d8-6a090d4b3739', '3edde710-508c-45e8-a93a-02dd12cfc266', 'es', 'Círculo exterior alterno con cuerda de batalla', 'Mueve ambos extremos de la cuerda realizando círculos hacia afuera de forma alterna, manteniendo una base de piernas sólida.'),
('b09be938-36c3-4608-81c5-9fca25ff5bbf', '3ee140cb-2ee5-4829-a269-6f11b833986e', 'en', 'Battle Ropes Alternating', 'Basic alternating waves moving each arm up and down. It is the fundamental movement with battle ropes. Keep a steady pace and breathe regularly. Start with short intervals and progress gradually.'),
('dbb4c223-745c-40c7-8fc3-3d24dd93a769', '3ee140cb-2ee5-4829-a269-6f11b833986e', 'es', 'Battle ropes alternating', 'Ondas alternadas básicas subiendo y bajando cada brazo. Es el movimiento fundamental con battle ropes. Mantén un ritmo constante y respira regularmente. Comienza con intervalos cortos y progresa gradualmente.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('24e65f7c-af62-4cfd-9ef2-3b2f8caf946f', '3ee884ef-6204-4870-817f-f9ccb87b585d', 'en', 'Alternating Single Arm Landmine Shoulder Press', 'Alternate the shoulder press by switching the bar from one hand to the other in front of the chest for each rep on the Landmine.'),
('682033e8-41ab-4944-a2f9-6844cb458b6d', '3ee884ef-6204-4870-817f-f9ccb87b585d', 'es', 'Press de hombros alterno en Landmine', 'Alterna el press vertical de hombro pasando la barra de una mano a otra frente al pecho en cada repeticion sobre la barra Landmine.'),
('55c235b6-c14d-4491-9170-46d077f3bd0c', '3f32da2a-2eae-4d52-b003-dc8764b12c2d', 'en', 'Paused Rollout', 'Rollout with a 2-5 second pause in the most extended position. Dramatically increases time under tension. Maintain controlled breathing during the pause. The back must remain neutral.'),
('21f06aa2-9a98-411d-b6d4-45cd002af317', '3f32da2a-2eae-4d52-b003-dc8764b12c2d', 'es', 'Rodamiento con pausa', 'Roll out con pausa de 2-5 segundos en la posición más extendida. Aumenta dramáticamente el tiempo bajo tensión. Mantén respiración controlada durante la pausa. La espalda debe permanecer neutra.'),
('d2a39291-b798-4a63-828a-b32874484531', '3f39fbcc-03dc-4eeb-9917-a7d43323cabb', 'en', 'Dumbbell Rear Delt Raises', 'Hinge forward from the hips with knees slightly bent. With arms hanging, lift the dumbbells laterally to shoulder height. Focus on squeezing shoulder blades at the end of the movement. Works the rear deltoid.'),
('ccdd4f90-bcc6-419d-8965-ce49f0017dfd', '3f39fbcc-03dc-4eeb-9917-a7d43323cabb', 'es', 'Elevaciones posteriores mancuernas', 'Inclínate hacia adelante desde las caderas con las rodillas ligeramente flexionadas. Con los brazos colgando, eleva las mancuernas lateralmente hasta la altura de los hombros. Enfócate en juntar los omóplatos al final del movimiento. Trabaja el deltoides posterior.'),
('31145068-b9be-4fda-a392-739d7898ca92', '3fa391e3-80ea-499a-89dd-d84942b7dc49', 'en', 'Unilateral Reverse Grip Cable Triceps Extension', 'High pulley extension with palms up. Cue: isolate triceps. Error: moving the shoulder.'),
('d2ded66a-5c3b-4370-86bd-d56e09c6de2b', '3fa391e3-80ea-499a-89dd-d84942b7dc49', 'es', 'Extensión tríceps unilateral invertido cable', 'Extensión polea alta palmas arriba. Cue: aísla tríceps. Error: mover hombro.'),
('01c8d263-8bae-47a6-acff-e29bea2a2ad2', '3fd968fb-4ca8-4b4a-925b-fe4b945bebbf', 'en', 'Band Row', 'Anchor the band in front of you or step on the center. Lean forward slightly and pull the ends toward your abdomen, squeezing the shoulder blades at the end. Keep elbows close to the body during the movement to maximize back activation.'),
('a436c32a-63f1-4726-9cd5-08b4b6a2f459', '3fd968fb-4ca8-4b4a-925b-fe4b945bebbf', 'es', 'Remo con banda', 'Ancla la banda frente a ti o pisa el centro. Inclínate ligeramente hacia adelante y tira de los extremos hacia tu abdomen, apretando los omóplatos al final. Mantén los codos cerca del cuerpo durante el movimiento para maximizar la activación de la espalda.'),
('a0565990-acce-4acb-9933-26e6a241f121', '403ffdfa-7070-452e-8ce9-4beb09e361e2', 'en', 'Single Arm Kettlebell Squat Clean', 'Explosively lift the kettlebell from the floor to the shoulder and catch it by immediately dropping into a deep squat before standing up.'),
('b9ff136b-aec3-4f42-9377-fd5e936ac2dc', '403ffdfa-7070-452e-8ce9-4beb09e361e2', 'es', 'Squat Clean con Kettlebell a una mano', 'Lleva la Kettlebell desde el suelo hasta el hombro de forma explosiva y recíbela bajando inmediatamente a una sentadilla profunda antes de ponerte de pie.'),
('50cbb1ea-359b-443a-81e5-b69afae1e769', '407fae2b-7b55-4791-908f-eab611e1737d', 'es', 'Push Press alterno con mancuernas', 'Genera potencia con las piernas para presionar las mancuernas alternativamente sobre la cabeza, manteniendo el ritmo y control del core.'),
('3a04f627-e268-4383-bf11-93ebc85f04e6', '40a6b04b-1078-4037-9341-4e5a4d672976', 'en', 'Short Lever Copenhagen Plank', 'Perform a short lever Copenhagen plank with the knee or lower leg supported on a bench. Keep the hips lifted and the trunk aligned while engaging the adductors.'),
('286e91b2-0fa6-4cdb-b73c-849aac2a3189', '40a6b04b-1078-4037-9341-4e5a4d672976', 'es', 'Copenhagen corto', 'Realiza una plancha Copenhagen de palanca corta apoyando la rodilla o la parte baja de la pierna sobre un banco. Mantén la cadera elevada y el tronco alineado mientras activas los aductores.'),
('622555cd-1c8a-4f98-8d90-dd9907929b09', '40aeb84b-094e-40a5-a963-6d2e8f2ab304', 'en', 'One-Arm Bottoms Up Overhead Cyclist Squat with Kettlebell', 'Cyclist squat maintaining a single inverted kettlebell overhead, challenging core and shoulder balance.'),
('0fa5dd75-5489-455d-af1b-0bb41bcf0259', '40aeb84b-094e-40a5-a963-6d2e8f2ab304', 'es', 'Sentadilla Ciclista Overhead con Kettlebell a una mano Bottoms Up', 'Sentadilla ciclista manteniendo una sola Kettlebell invertida sobre la cabeza, desafiando el equilibrio del core y el hombro.'),
('31703672-811e-4244-a87d-9adacd455336', '40d09188-ef1b-4266-9602-ee179f6771d4', 'en', 'One-Arm Landmine Thruster', 'Perform a deep squat and, upon rising, explosively press the Landmine bar with one arm.'),
('42377890-298e-4899-973f-e7712f8d4ae9', '40d09188-ef1b-4266-9602-ee179f6771d4', 'es', 'Thruster a una mano en Landmine', 'Realiza una sentadilla profunda y, al subir, presiona explosivamente la barra Landmine con un solo brazo.'),
('6752f009-f360-457d-bb3c-9cf3a390a506', '4101ef04-85b9-4f51-9e4a-9fd8c5b52328', 'es', 'Peso muerto rumano con Miniband', 'Pisa la banda y sujeta los extremos. Inclina el torso hacia adelante empujando la cadera atrás y manteniendo la espalda recta.'),
('b3e51492-409f-4f49-bf4a-2afc477ee792', '411219ed-6ec6-4dcb-87af-ce6ce231f1d2', 'en', 'Double Kettlebell Swing', 'Hold a kettlebell in each hand and swing them explosively between your legs and up to chest height using your hips.'),
('eebb95fe-46a1-4f29-8f3c-8abae3d597c4', '411219ed-6ec6-4dcb-87af-ce6ce231f1d2', 'es', 'Swing con Kettlebell doble', 'Sujeta una Kettlebell en cada mano y balancéalas explosivamente entre las piernas y hasta la altura del pecho usando la cadera.'),
('25252395-c698-4d13-997f-48e5e67c94e9', '4155ac5e-59c9-43ec-bc75-eaa21862138b', 'en', 'Alternating Double Dumbbell Spider Curl', 'Prone on an incline bench, perform the bicep curl alternating arms in a controlled manner without moving the shoulders.'),
('d1356e01-e694-4d3b-a053-ce0d47ed6717', '4155ac5e-59c9-43ec-bc75-eaa21862138b', 'es', 'Spider Curl alterno con mancuernas', 'Boca abajo en banco inclinado, realiza el curl de biceps alternando los brazos de forma controlada sin mover los hombros.'),
('5978832c-344f-4d8e-9975-56f54771b45e', '4168aeed-6bfb-4a3c-930f-4338b7c027f3', 'en', 'Barbell Overhead Bulgarian Split Squat', 'Perform a split squat with the foot elevated and the bar locked out overhead, requiring maximum stability and mobility.'),
('a14948cf-d938-4675-bea3-4cc46e2d167c', '4168aeed-6bfb-4a3c-930f-4338b7c027f3', 'es', 'Sentadilla Búlgara Overhead con barra', 'Realiza una sentadilla split con el pie elevado y la barra bloqueada sobre la cabeza, requiriendo maxima estabilidad y movilidad.'),
('a19f8bd2-440d-49e6-9021-4717788fb142', '41816208-ea67-49f5-a60d-ff3b4a45f330', 'en', 'Barbell Climb', 'Using a vertical or simulated bar, perform a climbing movement from the floor using core and arm strength to lift the torso.'),
('2394cb35-93b2-459f-88e1-2fbe9544e2f9', '41816208-ea67-49f5-a60d-ff3b4a45f330', 'es', 'Subida por la barra', 'Utilizando una barra vertical o simulada, realiza un movimiento de escalada desde el suelo usando la fuerza del core y los brazos para elevar el torso.'),
('d87d1548-3b0c-43fd-a4ef-b0454a95be53', '41ac82e8-83d2-409c-9961-1f6dcb2bdd7f', 'en', 'Suspension Atomic Push Up', 'Perform a push-up with feet in the TRX cradles and, immediately after, explosively tuck your knees toward your chest.'),
('c1e9edae-7c61-46d1-9994-64b9891ab2b3', '41ac82e8-83d2-409c-9961-1f6dcb2bdd7f', 'es', 'TRX Atómica Push Up', 'Realiza una flexion con los pies en los estribos del TRX y, inmediatamente después, encoge las rodillas hacia el pecho de forma explosiva.'),
('841a932f-d56c-443b-905e-1d75d716bd03', '41da9b82-43db-40d0-8e6a-221bfafd6074', 'en', 'Double Kettlebell Renegade Row', 'In a plank position on two kettlebells, row one weight to your hip while stabilizing the body with the other arm.'),
('d5082a28-05f4-42ea-ab0b-3e1e0b8f6fd0', '41da9b82-43db-40d0-8e6a-221bfafd6074', 'es', 'Remo renegado doble con pesa rusa', 'En posicion de plancha sobre dos Kettlebells, rima una pesa hacia tu cadera mientras estabilizas el cuerpo con el otro brazo.'),
('f1e40305-ba84-4d09-ae8e-65cfac70c672', '420a265d-6059-4390-8e33-fceefc8510f8', 'en', 'Seated Machine Row', 'Seated with your chest supported, pull the handles back. The chest support eliminates momentum and protects the lower back. Focus on bringing your shoulder blades together at the end of the movement. Various grip positions available.'),
('ead1e4ce-6ec5-489a-824c-04f334d2e462', '420a265d-6059-4390-8e33-fceefc8510f8', 'es', 'Remo sentado máquina', 'Sentado con el pecho apoyado, tira de los agarres hacia atrás. El soporte del pecho elimina el impulso y protege la espalda baja. Enfócate en juntar los omóplatos al final del movimiento. Varias posiciones de agarre disponibles.'),
('7b1f71d9-fdbf-4658-8d55-9700869cb65f', '421418b6-3e6d-431a-8d6c-41916055234b', 'en', 'Ring Back Lever Pullout', 'From a horizontal Back Lever position, pull on the rings to lift the body into a vertical inverted position.'),
('6c46d43d-68b4-4078-8063-4066953db7a1', '421418b6-3e6d-431a-8d6c-41916055234b', 'es', 'Back Lever Pullout en anillas', 'Desde la posicion horizontal de Back Lever, tira de las anillas para elevar el cuerpo hasta quedar en posicion invertida vertical.'),
('069c0547-fbf6-4ac9-8939-3458829a2069', '42548bd5-e040-44fb-8703-dfbfe2d35c74', 'es', 'Press Overhead agarre inverso con barra', 'Sujeta la barra con las palmas hacia ti (supino). Presiona el peso sobre la cabeza manteniendo los codos hacia adelante para un mayor enfoque en el deltoides frontal.'),
('136992fa-a0c3-4938-90d3-8ee2ad695a95', '426d5fe4-c8b3-434b-ac2c-dfc293afc75c', 'en', 'Explosive Push Up to Downward Dog', 'Explosive push-up ending by jumping into downward dog position (inverted V). Combines pushing power with dynamic mobility. Requires coordination and explosiveness. Excellent for athletes needing fast transitions.'),
('c5a686ca-1ec3-401b-9cf5-baa5d7757498', '426d5fe4-c8b3-434b-ac2c-dfc293afc75c', 'es', 'Flexiones explosivas a perro boca abajo', 'Flexión explosiva que termina saltando a posición de perro boca abajo (V invertida). Combina potencia de empuje con movilidad dinámica. Requiere coordinación y explosividad. Excelente para atletas que necesitan transiciones rápidas.'),
('779e5bb2-af8d-4b4a-b328-5c7227d3a2fb', '428d58c8-0328-4983-bdb8-8393305ee3d6', 'en', 'Barbell Front Rack Alternating Curtsy Lunge', 'With the bar in a front rack position, perform a lunge by crossing one leg behind the other (curtsy), alternating sides.'),
('9f3c3aa8-1e3e-4ee1-bce8-315e42ed53b8', '428d58c8-0328-4983-bdb8-8393305ee3d6', 'es', 'Soporte frontal con barra, Zancada con reverencia alterna', 'Con la barra en posicion de rack frontal, realiza una zancada cruzando una pierna por detras de la otra (reverencia), alternando lados.'),
('635145f8-c3f7-4a0e-8a0f-18c179ae4f45', '42baefcf-621c-45bf-8aca-bf7b073e0bfa', 'en', 'Kettlebell Power Jump', 'Hold the kettlebell with both hands and perform an explosive vertical jump. Weighted power. Cue: neutral back, high chest. Common error: rounding shoulders due to the weight.'),
('75114d9a-ffad-492b-a438-ff2d68e01468', '42baefcf-621c-45bf-8aca-bf7b073e0bfa', 'es', 'Salto de potencia con kettlebell', 'Sostén la kettlebell con ambas manos y realiza un salto vertical explosivo. Potencia lastrada. Cue: espalda neutra, pecho alto. Error común: redondear hombros por el peso.'),
('257d8b6f-5d26-4e3f-a1f4-c20958692003', '42bc61c8-95d9-4134-ae7c-91120a98b466', 'en', 'Isometric Superman', 'Lift chest and legs face down. Objective: lower back. Cues: look at the floor. Common error: neck jerks.'),
('5479dac4-f91b-4c3c-94bc-fe11a413c647', '42bc61c8-95d9-4134-ae7c-91120a98b466', 'es', 'Superman isométrico', 'Eleva pecho y piernas boca abajo. Objetivo: lumbar. Cues: mira al suelo. Error común: tirones de cuello.'),
('65ce90c2-fbe7-4538-afb4-faac794fad92', '42f76106-c09e-4fd0-8a22-ce6d127bec50', 'es', 'Zancada inversa contralateral con Slider y Kettlebell', 'Sostén una pesa rusa en una mano (maleta). Desliza hacia atrás la pierna contraria al brazo que carga el peso (contralateral) en una zancada.'),
('fbba3b56-2b25-47f7-9a4f-61c718c4b5da', '43064c22-7b48-4c86-b36e-9a89a7aa8d78', 'en', 'Advanced Tuck Back Lever on Rings', 'Maintain the back lever position with a flat back and knees away from the chest forming a 90-degree angle.'),
('43d512f2-4bf4-4c47-b877-63b32b4d4604', '43064c22-7b48-4c86-b36e-9a89a7aa8d78', 'es', 'Advanced Tuck Back Lever en anillas', 'Manten la posicion de back lever con la espalda plana y las rodillas separadas del pecho formando un angulo de 90 grados.'),
('84ae568b-dd1a-448f-834c-1efa73fab690', '430b7250-e263-41e4-8a65-3c56c3ac3eb9', 'en', 'Pull-ups', 'Pull your own body toward the bar until your chin clears it. Objective: lat pulling strength. Cue: chest toward the bar. Common error: using leg swinging (kipping) without control.'),
('5f8a4a96-0e16-48eb-ab02-3be15cb62387', '430b7250-e263-41e4-8a65-3c56c3ac3eb9', 'es', 'Dominadas', 'Tira de tu propio cuerpo hacia la barra hasta que la barbilla la pase. Objetivo: fuerza de tracción dorsal. Cue: pecho hacia la barra. Error común: usar balanceo de piernas (kipping) sin control.'),
('ad416de5-b9a8-400c-a5b4-7f839503f343', '431d98fa-0838-44fe-8ecd-6f804bb145a5', 'en', 'Stiff Leg Deadlift', 'With the bar in front of the thighs, lower the load keeping legs almost straight and neutral back, focusing the stretch on the hamstrings.'),
('614e16bd-0a90-4deb-a405-4bf2ccce3330', '431d98fa-0838-44fe-8ecd-6f804bb145a5', 'es', 'Peso muerto con piernas rígidas', 'Con la barra frente a los muslos, baja la carga manteniendo las piernas casi estiradas y la espalda neutra, enfocando el estiramiento en los isquiotibiales.'),
('7297fe68-72f6-4f76-95c2-de7ec03ba074', '432574f9-fa2f-4906-b38a-4766b27c2c44', 'en', 'Double Dumbbell Half Kneeling Overhead Press', 'In a half-kneeling position, perform a shoulder press with both dumbbells simultaneously, challenging pelvic stability.'),
('8cc4fceb-9684-4f50-a80d-1365ea4ccc1a', '432574f9-fa2f-4906-b38a-4766b27c2c44', 'es', 'Press de hombros medio arrodillado con mancuernas', 'En posicion de caballero, realiza un press de hombros con ambas mancuernas simultaneamente, desafiando la estabilidad de la pelvis.'),
('c76110e2-a965-4f44-b050-cc42b20de96f', '4335c304-8b9f-4cfe-8cbd-58865bc651a4', 'en', 'Ring Standing Rollout', 'From a standing position, hinge and extend arms into the rings until the body is parallel to the floor, pulling back up with core strength.'),
('a26cd3ef-d49b-42e2-a346-d4ea3585ac4b', '4335c304-8b9f-4cfe-8cbd-58865bc651a4', 'es', 'Rollout de pie en anillas', 'Desde posicion de pie, inclinate y extiende los brazos en las anillas hasta que el cuerpo quede paralelo al suelo, volviendo a subir con fuerza abdominal.'),
('8aed9808-45eb-4f6e-abd7-d6f4542dd8ef', '436612f2-8807-437b-887c-491ba5186333', 'en', 'Staggered Plyometric Push Up', 'Explosive push-up switching hand positions (one forward, one back) with each jump. Cue: switch hands quickly. Common error: losing torso alignment.'),
('d5f106b1-0615-4cc2-b61a-2b589d8fcbac', '436612f2-8807-437b-887c-491ba5186333', 'es', 'Flexión pliométrica escalonada', 'Flexión explosiva cambiando la posición de las manos (una adelantada y otra retrasada) en cada salto. Cue: cambia manos rápido. Error común: perder la alineación del torso.'),
('57af539a-12a2-46a8-b2e5-a02dc7c5c3d2', '4371cfe0-7dbb-47de-9d15-47690194a165', 'es', 'Prensa pies parte inferior', 'Pies abajo en plataforma. Cue: rodillas fuera. Error: talones aire.'),
('7c6ff317-ee09-4cba-a65a-5e86d3d0e898', '4379c473-2954-4d08-973b-502a0fb070b3', 'en', 'TRX Hamstring Curl', 'Lying down, heels in TRX, raise hips and flex knees bringing feet to glutes. Objective: posterior power. Cue: hips always high. Common error: dropping glutes to the floor when flexing.'),
('dd7bcb05-ccfd-4f71-8a19-bf648e3ae5a7', '4379c473-2954-4d08-973b-502a0fb070b3', 'es', 'TRX Curl de isquiotibiales', 'Tumbado, talones en TRX, eleva cadera y flexiona rodillas trayendo pies al glúteo. Objetivo: potencia posterior. Cue: cadera siempre alta. Error común: bajar el glúteo al suelo al flexionar.'),
('33e9e757-add6-4693-a338-f8196d5583a0', '4379dcfb-7a21-4bc4-888d-e6bb9174683a', 'en', 'Double Kettlebell Bottoms Up Z Press', 'Perform the military press sitting on the floor holding two upside-down kettlebells, maximizing stability and strength work.'),
('12e3130f-a4c8-4dd9-a457-59d722f886dd', '4379dcfb-7a21-4bc4-888d-e6bb9174683a', 'es', 'Press en Z con pesas rusas dobles de abajo hacia arriba', 'Realiza el press militar sentado en el suelo sosteniendo dos Kettlebells invertidas, maximizando el trabajo de estabilidad y fuerza.'),
('7ad8943c-1cb8-4b5f-b32d-904e13db8ddd', '43867f08-fff5-4889-9f25-341ebe212485', 'en', 'One Arm Snatch', 'Bring the dumbbell from the floor to overhead in an explosive movement. Unilateral version of the Olympic snatch. Requires power and coordination. The movement must be fluid and continuous. Alternate arms.'),
('f4514088-c9fc-4164-a484-fa48366f6c3c', '43867f08-fff5-4889-9f25-341ebe212485', 'es', 'Arranque un brazo', 'Lleva la mancuerna del suelo a overhead en un movimiento explosivo. Versión unilateral del arranque olímpico. Requiere potencia y coordinación. El movimiento debe ser fluido y continuo. Alterna brazos.'),
('a194718e-e6c1-4a07-b274-ae78155d1d52', '43882d91-ff34-4eb2-941a-db0c6c5c82be', 'es', 'Wall Squat unilateral 90 grados', 'Mantén sentadilla pared a un pie. Cue: rodilla a 90. Error: apoyar manos.'),
('b402c4a0-04d4-4f9c-8e5c-a6562f9d4efa', '438c474b-ac94-41ef-a855-cb258b1c7477', 'en', 'Seated Supinating Bicep Curl', 'Start neutral and rotate palm up as you lift. Cue: maximum rotation at the top. Error: swinging.'),
('3f014c8a-b1ca-48f5-b5d8-17900d698a70', '438c474b-ac94-41ef-a855-cb258b1c7477', 'es', 'Curl bíceps supinación sentado', 'Inicia neutro y gira palma arriba al subir. Cue: máximo giro arriba. Error: balanceo.'),
('4eecc9f8-03d4-4b29-a7d4-1cb20dcde7f8', '43a1192e-3132-44cd-a9e8-063c68c5be8f', 'en', 'A-Skips', 'Jump rhythmically lifting one knee to the chest and coordinating with the opposite arm. Focus on fast metatarsal contact. Keep torso upright. Do not drop the heel.'),
('fb785a40-0bb6-4a0f-9515-174ff3193f1f', '43a1192e-3132-44cd-a9e8-063c68c5be8f', 'es', 'Saltos A (A-Skips)', 'Salta rítmicamente elevando una rodilla al pecho y coordinando con el brazo contrario. Enfoque en el contacto rápido del metatarso. Mantén el torso erguido. No dejes caer el talón.'),
('9d829b9f-1c56-42ca-be9c-9f792e223b37', '43d76e9f-c0f6-4d7d-a4a1-7403a057d1b3', 'en', 'Double Dumbbell Single Leg Bent Over Row', 'Perform a bent-over row holding two dumbbells while standing on a single leg, challenging balance and the posterior chain.'),
('9cd68ed3-ce64-4bdd-af1c-849cc52bc041', '43d76e9f-c0f6-4d7d-a4a1-7403a057d1b3', 'es', 'Remo inclinado con una sola pierna y dos mancuernas', 'Realiza un remo inclinado sosteniendo dos mancuernas mientras te mantienes sobre una sola pierna, desafiando el equilibrio y la cadena posterior.'),
('5996f321-a906-4351-8980-5df1040416c5', '43e5f5a0-2189-4ac5-8d8e-9b794869ca91', 'en', 'Cable Seated Crunch', 'Sit on a bench or on the floor in front of the high pulley. Hold the rope behind the neck and flex the spine downward by contracting the abdominals.'),
('6fe4b42e-ffa2-4bc9-a83d-87022585a9e2', '43e5f5a0-2189-4ac5-8d8e-9b794869ca91', 'es', 'Crunch sentado con cable', 'Siéntate en un banco o en el suelo frente a la polea alta. Sostén la cuerda detrás del cuello y flexiona la columna hacia abajo contrayendo los abdominales.'),
('03048d14-d818-40ff-9e2d-6ddc4892fc66', '43f8bf66-0b56-42fc-9ab2-7b50c2c7e2d6', 'en', 'Band Hammer Bicep Curl', 'Step on the band and hold the ends with a neutral grip (palms facing each other). Perform elbow curls maintaining this hand position. This grip emphasizes the brachialis and brachioradialis in addition to the bicep, developing arm thickness.'),
('c62cc30f-9d93-414e-a670-cc1925bf310e', '43f8bf66-0b56-42fc-9ab2-7b50c2c7e2d6', 'es', 'Flexión bíceps martillo banda', 'Pisa la banda y sujeta los extremos con agarre neutro (palmas enfrentadas). Realiza flexiones de codo manteniendo esta posición de las manos. Este agarre enfatiza el braquial y braquiorradial además del bíceps, desarrollando grosor en el brazo.'),
('459fafc6-c795-4cd3-bb3f-2c1a614828bd', '441fda2c-4887-4feb-866e-4b9b54a75ad7', 'en', 'Ring Straight Arm L Sit Straddle Press Handstand', 'From a ring L-sit, spread legs into a straddle and press with locked arms until reaching a vertical handstand.'),
('8a733739-724c-49d8-a35e-39a8a103b122', '441fda2c-4887-4feb-866e-4b9b54a75ad7', 'es', 'Ring Brazo recto L-Sit a horcajadas Press Parada de manos', 'Desde un L-sit en anillas, abre las piernas en V y presiona con los brazos bloqueados hasta alcanzar la parada de manos vertical.'),
('3d8cc23a-5f96-45dd-9338-c062ac75a230', '4423fa72-a0f3-4ff8-bb50-a62e2f34d690', 'en', 'Macebell Offset Bicep Curl', 'Hold the mace with one hand closer to the weight than the other. Perform the curl while controlling the asymmetrical leverage to work biceps and forearms.'),
('fd343ad6-2a0a-40d4-82a0-7b444dd29509', '4423fa72-a0f3-4ff8-bb50-a62e2f34d690', 'es', 'Curl de bíceps offset con maza', 'Sujeta la maza con una mano mas cerca del peso que la otra. Realiza el curl controlando la palanca asimétrica para trabajar bíceps y antebrazos.'),
('c08b78b0-00fb-465f-983f-4f1bdcb5c578', '44322b28-4bcc-423e-b090-8753ed30942c', 'en', 'Barbell Upright Row', 'Raise the bar close to the body up to the chest by raising the elbows. Shoulders and upper back. Head straight. Do not jerk.'),
('bb733087-b11d-4753-985f-58cd887050e0', '44322b28-4bcc-423e-b090-8753ed30942c', 'es', 'Remo al mentón con barra', 'Sube la barra pegada al cuerpo hasta el pecho elevando codos. Hombros y espalda alta. Cabeza recta. No des tirones bruscos.'),
('867f0206-23a3-4ce1-b8f0-141fca6c0a7d', '44c11fc1-00e6-43fb-b983-e3fa41ed7c88', 'en', 'Lower Back Machine', 'Back extension on a specific machine. Strengthens spinal erectors safely and controlled. Important for lower back health. Avoid hyperextending and keep the movement controlled.'),
('b7083a97-789e-4678-82b6-f917fb6f9d28', '44c11fc1-00e6-43fb-b983-e3fa41ed7c88', 'es', 'Lower back máquina', 'Extensión de espalda en máquina específica. Fortalece los erectores espinales de forma segura y controlada. Importante para la salud de la espalda baja. Evita hiperextender y mantén el movimiento controlado.'),
('e6513d88-82f3-4696-94f5-6ad44fa299bd', '44d2fc47-a0c5-4041-8d3f-7ea3a966a0e3', 'en', 'Snatch Grip Deadlift', 'Deadlift with a very wide grip as in an Olympic snatch. Increases range of motion and upper back activation. Requires greater mobility. Use straps if grip limits. Excellent for trapezius development.'),
('e9e616e7-ffc8-4a8f-8577-bdeee90be0aa', '44d2fc47-a0c5-4041-8d3f-7ea3a966a0e3', 'es', 'Peso muerto agarre arranque', 'Peso muerto con agarre muy amplio como en arranque olímpico. Aumenta el rango de movimiento y la activación de espalda alta. Requiere mayor movilidad. Usa straps si el agarre limita. Excelente para desarrollo de trapecios.'),
('54ca477a-3eab-41f9-bfee-de116002e324', '44e235d0-a2e7-4a4d-b136-1909fb66183e', 'en', 'Cross Jump', 'Jump forming a cross: center, forward, center, back, center, right, center, left. Agility. Cue: feet always together. Common error: losing the jump sequence.'),
('8d6c9e47-5172-4179-9972-cebf8ecae7e9', '44e235d0-a2e7-4a4d-b136-1909fb66183e', 'es', 'Salto en cruz', 'Salta formando una cruz: centro, adelante, centro, atrás, centro, derecha, centro, izquierda. Agilidad. Cue: pies juntos siempre. Error común: perder la secuencia de saltos.'),
('c29c0b35-e4f9-4a65-8f28-8facf6f86726', '44e35bc6-6d7b-40ec-b15d-0f92ef3c8044', 'en', 'Double Kettlebell Clean to Overhead Press', 'Perform a clean with two kettlebells to the chest and press them simultaneously overhead in a power movement.'),
('ce1dc866-a7e0-414c-9d51-bc22c5c721c6', '44e35bc6-6d7b-40ec-b15d-0f92ef3c8044', 'es', 'Clean a Press Overhead con Kettlebell doble', 'Realiza una cargada con dos Kettlebells al pecho y presionalas simultaneamente sobre la cabeza en un movimiento de potencia.'),
('9e5ee928-f804-4509-b933-b2ab187dc6a3', '44ec3e73-16ca-4baa-9588-1c6dc985e7a4', 'en', 'Double Kettlebell Feet Elevated Push Up', 'Place feet elevated on a bench and hands on two kettlebells. Perform a deep push-up taking advantage of the extra space between the weights.'),
('cc279c45-e078-4acf-9ae3-b67202a6d6d4', '44ec3e73-16ca-4baa-9588-1c6dc985e7a4', 'es', 'Doble Push Up Con Pies Elevados Con Pesa Rusa', 'Coloca los pies elevados en un banco y las manos sobre dos Kettlebells. Realiza una flexion profunda aprovechando el espacio extra entre las pesas.'),
('af873e87-8673-4d3e-8c15-a7c17f03b4c9', '44f479a8-b886-4c6a-9259-71ef0eea4f11', 'en', 'Hamstring walk', 'From a glute bridge position, walk your heels forward until legs are almost fully extended and return taking short steps.'),
('ab5c80b0-860f-4c9d-9225-83887e30e639', '44f479a8-b886-4c6a-9259-71ef0eea4f11', 'es', 'Caminata de isquiotibiales', 'Desde la posición de puente de glúteo, camina con los talones hacia adelante hasta estirar casi por completo las piernas y regresa dando pasos cortos.'),
('24a2f8e5-f561-4a5e-80e9-45e459318c02', '451e120f-4fa1-4706-ab86-0c258d611399', 'en', 'Hanging Inverted Bar Crunch', 'Hang upside down from a bar with knees hooked (or using gravity boots). Contract the abdomen to lift the torso toward the knees.'),
('6321d24e-eac7-4d1e-b42e-9d56bc5e440e', '451e120f-4fa1-4706-ab86-0c258d611399', 'es', 'Crunch invertido colgado en barra', 'Cuélgate boca abajo de una barra con las rodillas enganchadas (o usando botas de gravedad). Contrae el abdomen para elevar el torso hacia las rodillas.'),
('798ba3ee-5689-4dba-9e12-2cc8e38c85d4', '4559a64f-2746-4ce8-a50d-9090ee9a2cc3', 'en', 'Knee-to-Standing Rollout', 'Dynamic transition from knees to standing position during rollout. Start from knees, extend fully, then bring feet toward the wheel to finish standing. Progression toward full standing rollout.'),
('3b2f00de-e487-4874-9e61-19caf51174c4', '4559a64f-2746-4ce8-a50d-9090ee9a2cc3', 'es', 'Rodamiento rodillas a pie', 'Transición dinámica desde rodillas a posición de pie durante el roll out. Comienza desde rodillas, extiende completamente, luego lleva los pies hacia la rueda para terminar de pie. Progresión hacia roll out completo de pie.'),
('663db0fd-163a-447f-80d5-3c6b6fcf26d5', '455a8548-412a-4889-8338-cc46a7ea1d66', 'es', 'Press Arnold sentado', 'Sentado con mancuernas frente a los hombros y palmas hacia ti. Rota las muñecas mientras empujas hacia arriba hasta que las palmas miren al frente. Objetivo: deltoides completo. Cue: movimiento fluido sin tirones. Error: arquear la espalda baja excesivamente.'),
('a2a35e87-fe1c-42ce-a9aa-c6144a25497a', '459d0f70-f2b0-48c5-9d91-ee6ad244d3b5', 'en', 'Parallel Bar L-Sit', 'Supported on parallel bars, keep legs straight in front forming an L. Objective: core strength and shoulder stability. Cues: shoulders down and away from ears. Common error: hunching the chest and bending knees.'),
('46495960-8ea3-4a26-87bc-79d587e55aec', '459d0f70-f2b0-48c5-9d91-ee6ad244d3b5', 'es', 'L-Sit en paralelas', 'Apoyado en barras paralelas, mantén las piernas estiradas al frente formando una L. Objetivo: fuerza de core y estabilidad de hombros. Cues: hombros abajo y lejos de orejas. Error común: encoger el pecho y doblar rodillas.'),
('70ef1523-84e3-4457-9de0-93b6a260a1cc', '45a14af9-f213-453e-b909-e5e1bd51b5c4', 'es', 'Puente de glúteo estricto', 'Eleva cadera con pies en suelo. Cue: talones cerca del glúteo. Error: apoyar solo la parte alta de la espalda.'),
('1b1d1121-f061-472a-8304-908d3ee1260d', '45fdbaa6-4379-4da5-a4ef-3086887b8323', 'en', 'Single Arm Kettlebell Overhead Ipsilateral Step Up', 'Hold a kettlebell high overhead and step up onto the bench with the leg on the same side, challenging core balance.'),
('cbadfc77-d047-4546-ad69-be5e4d18c1d6', '45fdbaa6-4379-4da5-a4ef-3086887b8323', 'es', 'Step Up Overhead ipsilateral con Kettlebell a una mano', 'Mantén una Kettlebell en alto sobre la cabeza y sube al banco con la pierna del mismo lado, desafiando el equilibrio del core.'),
('18503dac-c901-4474-bc24-791814d8a8e6', '4621886f-e93a-4c1d-9edd-d8ad869e7f61', 'en', 'Close Grip Barbell Bench Press', 'Lie on the bench and grip the bar with hands at shoulder width. Lower the bar to the chest keeping elbows tucked to the torso.'),
('67056273-3c87-4257-a8f9-2f6674266040', '4621886f-e93a-4c1d-9edd-d8ad869e7f61', 'es', 'Press de banca agarre cerrado con barra', 'Acuéstate en el banco y agarra la barra con las manos a la anchura de los hombros. Baja la barra al pecho manteniendo los codos pegados al torso.'),
('0058add2-b6a6-4015-80d4-5e3f7442e594', '46227deb-5fa5-493c-8a90-3f99f25ff7fc', 'en', 'Alternating Dumbbell Shoulder Press', 'Perform an alternating dumbbell shoulder press. Press one dumbbell overhead while the other remains stable, alternating arms each repetition.'),
('14d6ff09-9a9a-4d23-99f0-30a39fe47941', '46227deb-5fa5-493c-8a90-3f99f25ff7fc', 'es', 'Press frontal alterno', 'Realiza un press frontal alterno con mancuernas. Empuja una mancuerna por encima de la cabeza mientras la otra se mantiene estable, alternando ambos brazos.'),
('6c76aec4-b3ae-459e-997b-38564c68a3b4', '4649d14a-9e9f-4cab-b0b2-dac9e36abb6a', 'en', 'TRX Triceps Press', 'Back to the anchor, arms straightened in front of the forehead. Flex elbows lowering the body and extend. Tucked elbows. Do not arch the back.'),
('bb60e893-6a3d-4ba0-8068-7b165e80905d', '4649d14a-9e9f-4cab-b0b2-dac9e36abb6a', 'es', 'TRX Press de tríceps', 'De espaldas al anclaje, brazos estirados frente a la frente. Flexiona codos bajando el cuerpo y extiende. Codos cerrados. No arquees la espalda.'),
('5fd00b2d-2c21-42bf-891e-a36f57fc3b4e', '46e5a2ca-c3cb-458f-9884-55c7ffc44b09', 'en', 'Single Arm Kettlebell Suitcase Contralateral Bulgarian Split Squat', 'Perform the split squat with an elevated foot holding the kettlebell at one side with the arm opposite to the supporting leg.'),
('ae582e0f-c92f-433e-bf6f-cd7dd4317858', '46e5a2ca-c3cb-458f-9884-55c7ffc44b09', 'es', 'Sentadilla Búlgara búlgara contralateral en maleta con pesa rusa de un solo brazo', 'Realiza la sentadilla split con el pie elevado sosteniendo la Kettlebell en un lateral con el brazo opuesto a la pierna de apoyo.'),
('50b2f74a-ed7c-4b58-923a-1a9918882c45', '470ef360-6cfd-48f4-a80c-e2203009e069', 'en', 'Fitball Lumbar Extensions', 'Raise torso with abdomen on the ball. Objective: erectors. Cue: look at the floor. Error: hyperextending.'),
('6fa64a0a-4823-47d4-b284-7109e41afe7f', '470ef360-6cfd-48f4-a80c-e2203009e069', 'es', 'Extensiones fitball lumbares', 'Eleva torso con abdomen en bola. Objetivo: erectores. Cue: mira suelo. Error: hiperextender.'),
('ad34313c-aa3b-4665-a393-0c31aa100f8d', '471df754-7d97-4fb1-ba54-303c1199ea37', 'en', 'Single Arm Dumbbell Single Leg Contralateral Bent Over Row', 'Balance on one leg while rowing with the arm on the opposite side, strengthening the back and cross-core stability.'),
('f14a209a-f694-4078-829e-d78f13a0d8bc', '471df754-7d97-4fb1-ba54-303c1199ea37', 'es', 'Remo inclinado a una pierna contralateral con mancuerna', 'Manten el equilibrio sobre una pierna mientras remas con el brazo del lado opuesto, fortaleciendo la espalda y la estabilidad cruzada del core.'),
('0c679cce-4572-44d3-b7c0-011138fc5bf5', '4729b2f3-444b-43a3-9da8-6a2019e1a435', 'en', 'Pulley Face Pull', 'Pull the rope toward the face, opening elbows. Cue: thumbs back. Error: forward neck.'),
('58d08730-57fd-43d3-9a24-e6189ffb355d', '4729b2f3-444b-43a3-9da8-6a2019e1a435', 'es', 'Face Pull con polea', 'Tira de la cuerda hacia la cara abriendo codos. Cue: pulgares atrás. Error: adelantar cuello.'),
('913e8b23-ac98-4a83-a2b1-b1457da216e9', '4743c985-491f-4242-9ea1-9fa920a0dde4', 'en', 'Waiter Walk', 'Walk with a dumbbell held overhead with one arm like a waiter with a tray. Requires exceptional shoulder and core stability. Keep the arm completely vertical. Alternate arms. Excellent for shoulder health.'),
('87554594-d99d-4cbf-a751-cd44577e7e4d', '4743c985-491f-4242-9ea1-9fa920a0dde4', 'es', 'Caminata camarero', 'Camina con mancuerna sostenida overhead con un brazo como camarero con bandeja. Requiere estabilidad de hombro y core excepcionales. Mantén el brazo completamente vertical. Alterna brazos. Excelente para salud del hombro.'),
('23a672a8-ab57-4588-a41a-f535592ceb56', '47521034-2fda-478d-9276-4ff45e37ab05', 'en', 'Barbell Seal Row', 'Row lying face down on an elevated bench. Objective: isolated back. Cue: no momentum. Error: neck jerks.'),
('7b49caad-244d-40f7-a6d0-5676b555dbd6', '47521034-2fda-478d-9276-4ff45e37ab05', 'es', 'Remo Seal con barra', 'Rema tumbado boca abajo en banco elevado. Objetivo: espalda aislada. Cue: sin impulso. Error: tirones cuello.'),
('b29ab67e-b2ce-4efc-8450-e42a4f76cee7', '475f9ba5-f3b0-4450-a921-d27a1ab6e3c2', 'en', 'Wide Grip Lat Pulldown', 'Pull the bar toward the upper chest. Cue: imagine pulling your elbows down. Error: swinging the body backward.'),
('77df403a-e665-497e-a2b8-a1c8b00ce644', '475f9ba5-f3b0-4450-a921-d27a1ab6e3c2', 'es', 'Jalón al pecho agarre ancho', 'Tira de la barra hacia la parte superior del pecho. Cue: imagina que tiras de los codos hacia abajo. Error: balancear el cuerpo hacia atrás.'),
('00f6c6c7-f325-43b1-8ac1-401d9df1738a', '4761197e-6e4d-49df-b0dc-6e1a194016c5', 'en', 'Kettlebell Swing', 'Swing the kettlebell between the legs and raise it to shoulder height with an explosive hip movement. The momentum should come from the hips, not the arms. Keep the back straight and the core engaged. Foundation of kettlebell training.'),
('a37c4794-51c1-4d19-a752-0bb8aca02e66', '4761197e-6e4d-49df-b0dc-6e1a194016c5', 'es', 'Swing kettlebell', 'Balancea la kettlebell entre las piernas y elévala hasta la altura de los hombros con un movimiento explosivo de caderas. El impulso debe venir de las caderas, no de los brazos. Mantén la espalda recta y el core activado. Fundamento del entrenamiento con kettlebell.'),
('6064f96b-e972-43e9-b32b-66a0c83c3964', '476cb441-47d8-446c-a63d-576f38d895c3', 'en', 'Slider Kneeling Reach Push Up', 'Kneeling, perform a push-up while sliding one hand forward on a slider, alternating arms to challenge the core.'),
('b9942df8-047f-41c7-97a2-1c2fcaf9c5cb', '476cb441-47d8-446c-a63d-576f38d895c3', 'es', 'Flexión con alcance de rodillas sobre Slider', 'De rodillas, realiza una flexion mientras deslizas una mano hacia adelante sobre un slider, alternando brazos para desafiar el core.'),
('70f6013f-f169-4566-8126-85c844cc9a97', '48013afa-f182-4913-8c89-c4e83cc01651', 'en', 'Single Arm Ring Kneeling Rollout', 'Extreme rollout variant using only one arm to stabilize and slide the ring, minimizing side-core assistance.'),
('58b91a78-247c-4709-b790-88c05d79837e', '48013afa-f182-4913-8c89-c4e83cc01651', 'es', 'Rollout de rodillas con Anillas de un solo brazo', 'Variante extrema del rollout utilizando solo un brazo para estabilizar y desplazar la anilla, minimizando la ayuda del core lateral.'),
('536c007d-6643-4e42-8d1e-2124f82367f2', '4803f93c-ba58-4973-856b-b27bbeead329', 'en', 'Bodyweight Chest Roll to Straight Body Press Handstand', 'Roll on your chest from the floor and use momentum and strength to press your straight body into a vertical handstand.'),
('ca9df2f5-eb61-4518-8c88-31ae7082dba3', '4803f93c-ba58-4973-856b-b27bbeead329', 'es', 'Chest Roll a Straight Body Press Handstand', 'Rueda sobre el pecho desde el suelo y utiliza la inercia y fuerza para presionar el cuerpo recto hasta la parada de manos vertical.'),
('257387db-a7df-404f-a5c1-395e1a22c681', '4823caec-0bb1-42c5-817f-778c73e0e5d6', 'en', 'Battle Ropes Waves', 'Create alternating or simultaneous waves with the ropes. Maintain an athletic position with slightly bent knees. The movement should come from the shoulders, not the arms. Keep the core activated for stability.'),
('df7124d8-1447-45a5-a0ce-3fff84d93037', '4823caec-0bb1-42c5-817f-778c73e0e5d6', 'es', 'Battle ropes waves', 'Crea ondas alternadas o simultáneas con las cuerdas. Mantén una posición atlética con rodillas ligeramente flexionadas. El movimiento debe venir de los hombros, no de los brazos. Mantén el core activado para estabilidad.'),
('59168ad4-09d8-4224-91e6-56cc2ba540f7', '484d29bf-7a0f-48a7-8c3e-cb0d87f9a682', 'en', 'Double Kettlebell Bottoms Up Seesaw Decline Bench Press', 'From a decline position, alternate the press of upside-down kettlebells, working the lower chest and rotator cuff stability.'),
('e3717026-a40f-44eb-8d52-eb3c8841c66b', '484d29bf-7a0f-48a7-8c3e-cb0d87f9a682', 'es', 'Press de banca declinado Seesaw con Kettlebell doble Bottoms Up', 'Desde una posición declinada, alterna el press de Kettlebells invertidas, trabajando la parte inferior del pecho y la estabilidad del manguito rotador.'),
('4b6a455b-76da-43da-b2a6-cc4f0b75f70a', '48546596-4f0e-4403-a12e-880771367b0c', 'en', 'Static Hollow Body Hold', 'Keep legs and shoulders raised from the floor forming a curve with the body. Objective: isometric core strength. Cue: squeeze glutes and abdomen. Common error: arching lower back during hold.'),
('c7b6d681-2221-42d7-bb79-b4eaa1265d44', '48546596-4f0e-4403-a12e-880771367b0c', 'es', 'Hollow body hold estático', 'Mantén piernas y hombros elevados del suelo formando una curva con el cuerpo. Objetivo: fuerza isométrica del core. Cue: aprieta glúteos y abdomen. Error común: arquear la espalda lumbar durante la espera.'),
('e343ff07-1ad1-44fe-9b14-8487d0dcc0eb', '4876ac82-cfbb-4eff-8aeb-64834c14db60', 'en', 'Double Indian Club Lateral Arm Circles', 'Perform controlled lateral circular movements with both Indian Clubs to improve shoulder mobility and joint health.'),
('124d6d55-045e-4d5a-a180-a639ea01a3e3', '4876ac82-cfbb-4eff-8aeb-64834c14db60', 'es', 'Círculos laterales de brazos con Indian Club doble', 'Realiza movimientos circulares laterales controlados con ambos Indian Clubs para mejorar la movilidad y la salud articular del hombro.'),
('d35a6d53-81d0-4e60-ba4b-4ed2b7c92419', '4884c799-7d50-4cec-a9e7-ffa43f4bef3e', 'en', 'Barbell Front Rack Cyclist Squat', 'Elevate your heels and perform a squat with the bar in front rack position, focusing the stimulus on the quads due to the upright posture.'),
('a78ec2e3-21b1-400e-b92e-27f2a8318ac4', '4884c799-7d50-4cec-a9e7-ffa43f4bef3e', 'es', 'Sentadilla Ciclista Front Rack con barra', 'Eleva los talones y realiza una sentadilla con la barra en posición de rack frontal, enfocando el estímulo en los cuádriceps debido a la verticalidad.'),
('a7434a8e-2dd0-4819-91a4-2cabe692a648', '48afdddd-11cc-4e56-b0b2-bbf2c140d503', 'en', 'Bodyweight Full Planche', 'Support your body extended and horizontal parallel to the floor resting only on your hands with locked elbows and core under maximum tension.'),
('26040547-de6a-4bc9-8968-8ffcd2f5e939', '48afdddd-11cc-4e56-b0b2-bbf2c140d503', 'es', 'Plancha completa', 'Sostén el cuerpo estirado y horizontal paralelo al suelo apoyado solo en las manos con codos bloqueados y core en maxima tension.'),
('13e469d0-4113-432d-992a-b167ebb40abc', '48bd90e9-9981-4240-938e-03183b2a0190', 'en', 'Double Kettlebell Overhead Squat', 'Lower into a deep squat while keeping two kettlebells locked out overhead, requiring extreme mobility and scapular stability.'),
('10cd03e4-1c1e-420e-a0b4-738c85e1797a', '48bd90e9-9981-4240-938e-03183b2a0190', 'es', 'Sentadilla Overhead con Kettlebell doble', 'Baja en sentadilla profunda manteniendo dos Kettlebells bloqueadas sobre la cabeza, lo que requiere movilidad extrema y estabilidad escapular.'),
('1c8885c0-745c-4826-a958-220448063210', '48ff20ba-8069-4fe1-a983-b16d720fe3ee', 'es', 'Zancada frontal corporal', 'Da un paso al frente bajando la cadera y empuja para volver. Objetivo: potencia de piernas. Cue: mantén el torso erguido. Error común: permitir que el talón delantero se levante del suelo.'),
('970deede-fd02-4293-bb36-edbabbc9d7a6', '49074aef-3fad-410a-a30e-307f278fa0eb', 'en', 'Half-Kneeling Barbell Shoulder Press', 'In a half-kneeling position with one knee on the floor, press the bar overhead keeping the torso vertical and the abdomen contracted to stabilize the movement.'),
('377af03e-a51b-477b-93d9-ee3c16970a60', '49074aef-3fad-410a-a30e-307f278fa0eb', 'es', 'Press de hombros con barra medio arrodillado', 'En posición de caballero con una rodilla en el suelo, presiona la barra sobre la cabeza manteniendo el torso vertical y el abdomen contraído para estabilizar el movimiento.'),
('04e55025-c334-448f-8a52-3327bde65d16', '49080d43-523c-4d2c-8967-6b407e0c365a', 'en', 'Anti-rotational Pallof Press', 'Anti-rotational core push, resisting cable torque and keeping pelvis and ribs stable.'),
('5d32fff5-d466-468a-a325-76c1bf4709fa', '49080d43-523c-4d2c-8967-6b407e0c365a', 'es', 'Pallof press anti-rotación', 'Aléjate de la polea, empuja al frente y resiste la rotación. Glúteos y abdomen firmes, respiración controlada.'),
('16b04c57-801b-4349-a73e-7a5ac519f316', '499126a6-994b-43cd-89a3-b1fcbbe047d2', 'en', 'Double Kettlebell Prone Row', 'Lying face down on an elevated bench, row both kettlebells toward your sides by squeezing the scapulae and keeping elbows close to the torso.'),
('519b249e-c942-458f-8e50-6a25a76080f1', '499126a6-994b-43cd-89a3-b1fcbbe047d2', 'es', 'Remo prono con Kettlebell doble', 'Tumbado boca abajo en un banco elevado, rema ambas pesas rusas hacia los costados apretando las escápulas y manteniendo los codos cerca del torso.'),
('0a89f134-9667-4f81-be60-c6ea4e0cf04b', '49d25cd8-9777-4acf-aa20-9a7c05e40018', 'en', 'Stability Ball Dead Bug', 'Lie face up holding a Fitball between your hands and knees. Extend the opposite arm and leg toward the floor while maintaining pressure on the ball with the remaining limbs. Return to the starting position and alternate.'),
('aff0bdaf-92b8-48ff-b29e-09a323256c03', '49d25cd8-9777-4acf-aa20-9a7c05e40018', 'es', 'Dead Bug con Fitball', 'Acuéstate boca arriba sosteniendo un Fitball entre las manos y las rodillas. Extiende el brazo y la pierna opuestos hacia el suelo mientras mantienes la presión sobre el balón con las extremidades restantes. Regresa a la posición inicial y alterna.'),
('ec4325eb-aa2c-47ea-89df-1d8f00d07ea8', '49d933df-9925-4995-83a3-1982d262851b', 'es', 'Plancha lateral con Hip Dips', 'En plancha lateral, baja la cadera al suelo y elévala de nuevo. Objetivo: fuerza de los oblicuos. Cue: mantén el hombro estable y alineado. Error común: rotar el tronco hacia adelante.'),
('3b1af32c-4fea-4e16-9a1b-b8731a274619', '49e1ceb5-e2f8-4437-be84-fa2bf559a365', 'en', 'Unilateral Dumbbell Shoulder Press', 'Push a single dumbbell overhead while the other arm is free or stabilizing. Objective: shoulder strength and core stability. Cue: do not allow the body to tilt laterally. Error: locking the elbow abruptly.'),
('223f0bd4-303d-4201-836b-140b382d3218', '49e1ceb5-e2f8-4437-be84-fa2bf559a365', 'es', 'Press de hombros unilateral con mancuerna', 'Empuja una sola mancuerna sobre la cabeza mientras el otro brazo está libre o estabilizando. Objetivo: fuerza de hombros y estabilidad del core. Cue: no permitas que el cuerpo se incline lateralmente. Error: bloquear el codo bruscamente.'),
('235a58cb-a462-424e-8fc1-727baba31a73', '4a045fcc-6090-498b-b9de-1e6d1ef94f0b', 'es', 'Press pecho cable', 'De pie entre dos poleas ajustadas a la altura del pecho, empuja los agarres hacia adelante hasta que se junten frente al pecho. Mantén una ligera inclinación hacia adelante y los codos ligeramente flexionados. Proporciona tensión constante en los pectorales.'),
('6e69b803-298c-4224-9920-a62d036c1006', '4a2068a4-dbcf-46b5-af41-e161a27b8319', 'en', 'Jump Ball Slam', 'Perform a maximum vertical jump and slam the ball against the ground right upon landing. Synchronized total power. Cue: maximum jump height. Common error: lack of coordination between landing and slam.'),
('154c7db1-005e-4e43-bb03-c1960328027a', '4a2068a4-dbcf-46b5-af41-e161a27b8319', 'es', 'Slam de balón con salto', 'Realiza un salto vertical máximo y golpea el balón contra el suelo justo al aterrizar. Potencia total sincronizada. Cue: máxima altura de salto. Error común: descoordinación entre aterrizaje y golpe.'),
('e84a2a31-de8f-491a-8b75-d1f592b07397', '4a27f194-2219-42ef-afb4-7fbd7939558a', 'en', 'Rotational Box Jump', 'Jump onto a box rotating 90 or 180 degrees in the air. Improves agility and landing control. Cue: arms coordinated with the turn. Common error: landing noisily on the box.'),
('48e3187e-f7dd-4aaf-bb76-d763091bef0a', '4a27f194-2219-42ef-afb4-7fbd7939558a', 'es', 'Salto al cajón con rotación', 'Salta a un cajón girando 90 o 180 grados en el aire. Mejora la agilidad y el control del aterrizaje. Cue: brazos coordinados con el giro. Error común: aterrizar ruidosamente sobre el cajón.'),
('afd707a7-2eda-446f-b19d-2178eaf5687b', '4a4d6b0c-6c39-4339-914b-d803b5028117', 'en', 'TRX Cuban Press', 'In TRX: high row, external shoulder rotation until hands are up, and overhead press maintaining tension on the straps.'),
('760db30e-83c8-41b2-8b47-e7a50cd7ab27', '4a4d6b0c-6c39-4339-914b-d803b5028117', 'es', 'Press Cubano en TRX', 'En TRX: remo alto, rotación externa de hombros hasta manos arriba, y press overhead manteniendo tensión en las correas.'),
('d56bd0c2-39ed-4b97-8a38-759e0bae577f', '4a53cd78-a559-4ba1-8fa5-e7a8b2d3525c', 'en', 'One-Leg Rotational Toss', 'Lateral medicine ball throw while balancing on a single leg. Cue: lock the hip. Common error: rotating only with the arms due to instability.'),
('f7f28c25-5e0b-4c77-b482-5ef5ac55f518', '4a53cd78-a559-4ba1-8fa5-e7a8b2d3525c', 'es', 'Lanzamiento rotacional una pierna', 'Lanzamiento lateral de balón medicinal manteniendo el equilibrio sobre una sola pierna. Cue: fija la cadera. Error común: rotar solo con los brazos por inestabilidad.'),
('27415cd2-ad22-45b4-8f2d-889087b98a4a', '4a88eef3-bad0-4461-8b89-20f6be037b86', 'en', '360-Degree Vertical Jump', 'Jump vertically and perform a full rotation in the air before landing stable. Extreme spatial coordination. Cue: initiate rotation with arms. Common error: losing balance upon landing.'),
('f81d1651-5c15-4499-bab5-d93ff61849b3', '4a88eef3-bad0-4461-8b89-20f6be037b86', 'es', 'Salto vertical 360 grados', 'Salta verticalmente y realiza un giro completo en el aire antes de aterrizar estable. Coordinación espacial extrema. Cue: inicia el giro con los brazos. Error común: perder el equilibrio al aterrizar.'),
('83062435-4bb8-4dca-bcbf-e6ca452ebcc4', '4b080ebd-d7f7-4fd0-b8bc-fda0fc25517d', 'en', 'Cable Lateral Raises', 'With a low pulley, perform lateral raises with the cable crossing in front of or behind the body. Constant cable resistance maintains tension in the middle deltoid throughout the movement. Especially control the eccentric phase.'),
('ea031afb-85d9-4081-84e5-b8562663940c', '4b080ebd-d7f7-4fd0-b8bc-fda0fc25517d', 'es', 'Elevaciones laterales cable', 'Con polea baja, realiza elevaciones laterales con el cable cruzando por delante o detrás del cuerpo. La resistencia constante del cable mantiene tensión en el deltoides medio durante todo el movimiento. Controla especialmente la fase excéntrica.'),
('3f450021-5a3c-4332-8ed0-28ae7c8f4d45', '4b235a22-99a7-45d4-8980-178b2c677c62', 'es', 'Pull Up excéntrico en barra', 'Salta a la posición alta de la dominada prono y controla el descenso bajando lo más lento posible para ganar fuerza de tracción.'),
('fb01c971-3b62-4885-bfa5-3dbc1e1f6b10', '4b3f6afa-1e1e-4595-9938-234f88a36567', 'en', 'Front Barbell Squat', 'Rest the bar on your front deltoids and lower into a squat maintaining a vertical torso. Objective: emphasis on quadriceps and core stability. Cues: elbows always high and parallel to the ground. Common error: letting the elbows drop, causing the bar to roll forward.'),
('2883640b-46c6-436f-b097-a688006eee4a', '4b3f6afa-1e1e-4595-9938-234f88a36567', 'es', 'Sentadilla con barra frontal', 'Apoya la barra sobre tus deltoides frontales y baja en sentadilla manteniendo el torso vertical. Objetivo: énfasis en cuádriceps y estabilidad del core. Cues: codos siempre altos y paralelos al suelo. Error común: dejar que los codos caigan, haciendo que la barra ruede hacia adelante.'),
('abfad358-b678-4039-9075-c2e8d4d09ca4', '4b6c17ff-95a3-44eb-b293-ede1fca4aec1', 'es', 'Pike en TRX', 'Con los pies en los estribos del TRX y las manos en el suelo, eleva la cadera hacia el techo manteniendo las piernas rectas para formar una V invertida.'),
('3b28deea-fc94-4f16-b994-b3e50d3c7f99', '4b6c7a98-1748-4d0c-a3f0-d89347f73d85', 'en', 'Unilateral Landmine Barbell Row', 'Row with one arm using an anchored bar. Objective: lats. Cue: flat back. Error: rotating torso.'),
('08c68c62-5283-4e7a-8607-64520b3fce8e', '4b6c7a98-1748-4d0c-a3f0-d89347f73d85', 'es', 'Remo Landmine unilateral barra', 'Rema a un brazo en barra anclada. Objetivo: dorsal. Cue: espalda plana. Error: rotar torso.'),
('b979289f-f540-438b-95d4-1f43c0917b05', '4b945881-9c22-4917-9ae6-a03b3ebab51d', 'en', 'Single Arm Kettlebell Bottoms Up Front Rack Ipsilateral Bulgarian Split Squat', 'With one foot elevated, hold the upside-down kettlebell on the shoulder of the same side as the front leg, requiring maximum unilateral stability.'),
('54137d97-bc61-4795-afdf-de9d0450fcfd', '4b945881-9c22-4917-9ae6-a03b3ebab51d', 'es', 'Sentadilla Búlgara ipsilateral de abajo hacia arriba con pesa rusa de un solo brazo', 'Con un pie elevado, sujeta la Kettlebell invertida en el hombro del mismo lado que la pierna delantera, exigiendo maxima estabilidad unilateral.'),
('24505fe3-85f8-47c5-b1cf-9a1f289d20f6', '4b9d3b67-5c45-48c8-98e3-d8b9ccb8647c', 'en', 'Incline Dumbbell Press', 'Incline dumbbell press for upper pectoral, prioritizing range and stability with wrist and scapulae control.'),
('5a583b26-4c3f-47e3-a279-56a6dbf0ad2b', '4b9d3b67-5c45-48c8-98e3-d8b9ccb8647c', 'es', 'Press inclinado con mancuernas (45°)', 'Escápulas estables, baja controlado y sube sin perder tensión. Mantén mancuernas alineadas con antebrazo.'),
('1002e98c-dc72-403c-83f0-f98f1739a32d', '4ba76616-1df9-41ca-a9c3-ac00b1009be5', 'en', 'Parallel Bar Dips', 'Hold yourself on parallel bars with arms extended and body vertical. Descend by flexing elbows until shoulders are at or slightly below the level of the elbows. Push forcefully to return up. Lean slightly forward for greater emphasis on pectorals.'),
('0fce2b17-9162-4c63-930a-c76db59ed90c', '4ba76616-1df9-41ca-a9c3-ac00b1009be5', 'es', 'Fondos en paralelas', 'Sujétate en barras paralelas con los brazos extendidos y el cuerpo vertical. Desciende flexionando los codos hasta que los hombros estén al nivel o ligeramente por debajo de los codos. Empuja con fuerza para volver arriba. Inclínate ligeramente hacia adelante para mayor énfasis en pectorales.'),
('d6eb2362-34bb-4cdc-9aa9-44477a3f14e8', '4bd0491c-56e7-4ea7-980a-176808548aeb', 'es', 'Zancada inversa Goblet con mancuerna y Slider', 'Sostén una mancuerna en posición de copa y desliza un pie hacia atrás en un slider bajando en zancada, manteniendo el torso vertical.'),
('23e088d7-caa0-49e0-a5b1-4f61b0fe5a74', '4bdb4129-fc4a-4c52-857d-cda1ea02f781', 'en', 'Push Up', 'In a plank position, lower the chest toward the floor by flexing the elbows and return to the starting position by extending them completely.'),
('89cc5dc9-49b8-4559-8895-08f7c6a3747e', '4bdb4129-fc4a-4c52-857d-cda1ea02f781', 'es', 'Flexión (Push Up)', 'En posicion de plancha, baja el pecho hacia el suelo flexionando los codos y vuelve a la posicion inicial extendiéndolos por completo.'),
('1469474c-fea9-4fce-90f1-61d6ed5f457f', '4c48f2cc-cd30-4c7e-8395-46716414b3b0', 'en', 'Lateral Single Leg Hurdle Jump', 'Jump over a hurdle laterally supporting and landing with the same leg. Critical unilateral stability. Cue: keep knee aligned with the second toe. Common error: excessive wobbling upon landing.'),
('4806639e-5375-451d-8886-7e120f305739', '4c48f2cc-cd30-4c7e-8395-46716414b3b0', 'es', 'Salto de valla a una pierna lateral', 'Salta una valla lateralmente apoyándote y aterrizando con la misma pierna. Estabilidad unilateral crítica. Cue: mantén la rodilla alineada con el segundo dedo del pie. Error común: tambaleo excesivo al aterrizar.'),
('2145966c-2f4a-4d4a-b3e0-9d3e8ca4689d', '4c566809-f819-4c13-88d3-600f428ca8db', 'en', 'Alternating Double Kettlebell Thruster', 'Perform a squat and alternate the arm that does the overhead press as you stand up, keeping the other kettlebell stable in rack position.'),
('d9822f09-7a8c-40e9-b8c8-a20508785db5', '4c566809-f819-4c13-88d3-600f428ca8db', 'es', 'Thruster con Kettlebell', 'Realiza una sentadilla y alterna el brazo que realiza el press vertical al subir, manteniendo la otra pesa estable en posicion rack.'),
('3431d37e-dd8c-43bb-a0a5-d7d15ef1f687', '4c58602c-e0f5-48d7-9e4c-d16266a3d40b', 'en', 'Double Kettlebell Turkish Sit Up to Z Press', 'Execute a Turkish Sit Up with two kettlebells and, once seated, perform a Z Press overhead keeping the torso upright.'),
('fc1bb021-c0bf-409f-85bc-e0fa8ef0ae02', '4c58602c-e0f5-48d7-9e4c-d16266a3d40b', 'es', 'Turkish Sit Up a Press Z con Kettlebell doble', 'Ejecuta un Turkish Sit Up con dos Kettlebells y, una vez sentado, realiza un Press Z sobre la cabeza manteniendo el torso vertical.'),
('5317b95b-b054-4ef1-b82c-fb33de4769cf', '4c5c6719-7fc7-4d59-a1dc-facea2f6d449', 'en', 'Ab Wheel Rollout', 'Perform an ab wheel rollout. From the knees or standing, roll the wheel forward while keeping the core engaged and return without losing lower-back position.'),
('9993a29f-56a5-43b2-bfc4-42bf33242f99', '4c5c6719-7fc7-4d59-a1dc-facea2f6d449', 'es', 'Rueda abdominal', 'Realiza un rollout con rueda abdominal. Desde rodillas o de pie, desplaza la rueda hacia delante manteniendo el abdomen activo y vuelve sin perder la posición lumbar.'),
('9af8fa7a-f3f3-41c3-a9fe-8e060446b999', '4c663c7f-48ac-4bb5-875a-b7967fd728eb', 'en', 'Dumbbell Devil Press', 'Perform a Burpee with hands on dumbbells. Upon rising, use hip momentum to bring both weights overhead (swing/snatch).'),
('f7a76deb-f370-44a0-9e2d-41b7f782ccc4', '4c663c7f-48ac-4bb5-875a-b7967fd728eb', 'es', 'Devil Press con mancuernas', 'Realiza un Burpee con las manos sobre mancuernas. Al subir, usa el impulso de la cadera para llevar ambas pesas sobre la cabeza (swing/snatch).'),
('56e0cc73-0ffd-4454-b5e5-dd46b412f35f', '4c850905-e896-4640-941c-672185f17398', 'en', 'Mountain Climbers on Medicine Ball', 'Hands on the ball, perform the mountain climber movement. Stability challenge. Firm core. Do not let the ball roll away.'),
('aaf1808a-f370-4573-bdd6-f64f48c78d27', '4c850905-e896-4640-941c-672185f17398', 'es', 'Escaladores sobre balón medicinal', 'Manos sobre el balón, realiza el movimiento de escalador. Desafío de estabilidad. Core firme. No dejes que el balón ruede lejos.'),
('048a2673-8c8b-4e79-af39-9ffe3eb2078d', '4cbbab21-5699-4fb9-ac58-05efda2824d6', 'en', 'High Pulley Rope Row (Face Pull)', 'Pull the rope toward your forehead, separating the ends and bringing your thumbs back. Objective: shoulder health. Cue: open elbows to the sides. Error: jutting the neck forward when pulling.'),
('a16b1220-891c-47dd-af38-48609211cc81', '4cbbab21-5699-4fb9-ac58-05efda2824d6', 'es', 'Remo alto en polea con cuerda (Face Pull)', 'Tira de la cuerda hacia tu frente separando los extremos y llevando los pulgares hacia atrás. Objetivo: salud de hombro. Cue: abre los codos hacia los lados. Error: adelantar el cuello al tirar.'),
('24e41ad4-f829-48c1-a176-96ec31e9bd63', '4ccb1e9f-8877-4f3a-a24a-37f315c1d634', 'en', 'Single Arm Kettlebell Bottoms Up Overhead Ipsilateral Step Up', 'Keep an upside-down kettlebell locked out above and step up with the same-side leg, challenging asymmetrical balance.'),
('55725fd4-7a76-46ce-bd09-a6b9638f967c', '4ccb1e9f-8877-4f3a-a24a-37f315c1d634', 'es', 'Step Up Overhead ipsilateral con Kettlebell a una mano Bottoms Up', 'Mantén una Kettlebell invertida bloqueada arriba y sube al banco con la pierna del mismo lado, desafiando el equilibrio asimétrico.'),
('0f0e8bfa-4feb-4867-aea0-7420c75caa90', '4ce3fdcf-b651-4462-a8d1-047faad7c7e9', 'en', 'Double Kettlebell Outside Half Snatch', 'Drive two kettlebells outside your legs to overhead and lower them to the rack position before the next swing.'),
('fcdad111-b945-450a-ac6f-589714bff3bd', '4ce3fdcf-b651-4462-a8d1-047faad7c7e9', 'es', 'Outside Half Snatch con Kettlebell doble', 'Lleva dos pesas por fuera de las piernas hasta por encima de la cabeza y bajalas a la posicion rack antes del siguiente balanceo.'),
('d393ba32-cbe1-4080-a4a8-4fe74473695e', '4cef48e5-85af-4cbc-9872-45b007a082aa', 'en', 'Double Dumbbell Tall Kneeling Seesaw Overhead Press', 'Kneeling on both legs, press the dumbbells alternately overhead in a fluid and constant motion.'),
('6728d80e-0989-4c14-a75e-dffbf1e89f5c', '4cef48e5-85af-4cbc-9872-45b007a082aa', 'es', 'Press Overhead Seesaw arrodillado con mancuernas', 'De rodillas sobre ambas piernas, presiona las mancuernas alternativamente sobre la cabeza en un movimiento fluido y constante.'),
('bac4889a-e58a-4aef-9c68-4877bc1e9c0f', '4cfadf8f-87ea-48b0-b3f7-50f4c3c2d0d7', 'en', 'Sissy Squat with Dumbbell', 'Lean back by flexing the knees while keeping the hips extended. Objective: quadriceps isolation. Cue: straight body from shoulder to knee. Common error: flexing the hip when lowering.'),
('10bc5b38-53b1-4d05-847f-978a69dc7a44', '4cfadf8f-87ea-48b0-b3f7-50f4c3c2d0d7', 'es', 'Sentadilla Sissy con mancuerna', 'Inclínate hacia atrás flexionando rodillas mientras mantienes la cadera extendida. Objetivo: aislamiento de cuádriceps. Cue: cuerpo recto de hombro a rodilla. Error común: flexionar la cadera al bajar.'),
('1b62175b-36fb-49fc-8a64-ae437c7e1887', '4d15872d-f06a-4901-84a9-e4b06a529a61', 'en', 'Quick Take-off Frog Jump', 'From a squat, perform a short jump and immediately take off into the next. Minimum ground time. Heels supported when landing. Do not round the back.'),
('92ce5423-ddfd-4adc-9656-82da344d56a7', '4d15872d-f06a-4901-84a9-e4b06a529a61', 'es', 'Salto de rana con despegue rápido', 'Desde sentadilla, realiza un salto corto y sal inmediatamente hacia el siguiente. Mínimo tiempo en suelo. Talones apoyados al caer. No redondees la espalda.'),
('8b3f7ad6-4539-43f7-b9b5-a2ed7955408b', '4d4848b3-7d25-4c8a-91c0-5e721fcb4f17', 'en', 'Half Kneeling Alternating Kettlebell Halo', 'In a half-kneeling position, perform halos around the head with the kettlebell, resisting the movement of the torso.'),
('440405f2-d2f4-4222-b2a6-85e414936a47', '4d4848b3-7d25-4c8a-91c0-5e721fcb4f17', 'es', 'Halo alterno de rodillas (Half Kneeling) con Kettlebell', 'En posición de caballero, realiza halos alrededor de la cabeza con la pesa rusa, resistiendo el movimiento del torso.'),
('23b25267-3b5a-4446-8b22-3b3c24fd80e2', '4dd67613-3345-4562-b527-c8f0f649f064', 'en', 'Bodyweight Bulgarian Split Squat', 'Rest one foot back on a bench and perform a deep squat with the front leg, keeping the torso upright.'),
('046ca0d0-db1c-491f-9f01-9e9603ab67f4', '4dd67613-3345-4562-b527-c8f0f649f064', 'es', 'Sentadilla Búlgara búlgara', 'Apoya un pie atras en un banco y realiza una sentadilla profunda con la pierna delantera, manteniendo el torso erguido.'),
('2f1db195-69a3-4705-a96c-e8db34a68f10', '4dd976c2-3cfb-46cb-aa32-dbd56c09f3ce', 'en', 'Bench Tricep Dips', 'Hands on the edge of the bench, lower the hips by flexing the elbows. Cue: back close to the bench. Error: moving the body too far away from the bench.'),
('def63928-9739-445e-be58-372cd4cde75e', '4dd976c2-3cfb-46cb-aa32-dbd56c09f3ce', 'es', 'Dips en banco para tríceps', 'Manos en borde de banco, baja la cadera flexionando codos. Cue: espalda pegada al banco. Error: alejar demasiado el cuerpo del banco.'),
('e432adb9-a307-4cc5-8f9b-3065e8507f2d', '4dd9c263-582a-4114-9beb-8bdd6f39df45', 'en', 'Band Monster Walk', 'With the band around the ankles, adopt a quarter-squat position. Walk forward taking wide diagonal steps, maintaining constant tension. The movement should look like a monster walking. Keep the torso upright and knees aligned.'),
('8f2d48fc-1759-4d4f-b0ea-ff9062803c46', '4dd9c263-582a-4114-9beb-8bdd6f39df45', 'es', 'Monster walk con banda', 'Con la banda alrededor de los tobillos, adopta una posición de cuarto de sentadilla. Camina hacia adelante dando pasos amplios en diagonal, manteniendo la tensión constante. El movimiento debe parecer el caminar de un monstruo. Mantén el torso erguido y las rodillas alineadas.'),
('be5966ed-6441-4985-a97e-8de07ee45594', '4dda3874-db65-443a-a5d4-66711024287b', 'en', 'Lateral Long Jump', 'Jump sideways as far as possible, landing with both feet. Explosive lateral power. Cue: use arms for lateral momentum. Common error: landing with knees together.'),
('709b2209-6b42-49c7-9705-69911d0ff5e9', '4dda3874-db65-443a-a5d4-66711024287b', 'es', 'Salto de longitud lateral', 'Salta de lado lo más lejos posible aterrizando con ambos pies. Potencia lateral explosiva. Cue: usa los brazos para el impulso lateral. Error común: aterrizar con las rodillas juntas.'),
('e0a522c1-be02-4adb-85db-f1bbfd09c74c', '4ded2a0a-3e93-428c-89f2-06ca70bb6544', 'en', 'Single Arm Kettlebell Thruster', 'Execute a deep squat with a kettlebell in rack and use the upward momentum to drive it overhead in a vertical press.'),
('28872399-2606-4d3f-8bd2-a0e25d742ec3', '4ded2a0a-3e93-428c-89f2-06ca70bb6544', 'es', 'Thruster con Kettlebell a una mano', 'Ejecuta una sentadilla profunda con una pesa en rack y utiliza el impulso de subida para lanzarla sobre la cabeza en un press vertical.'),
('7d2fc27a-8d70-4983-95b4-1455a39d3431', '4e1a1c4e-8703-476c-9d63-8564b294d150', 'en', 'Double Kettlebell Bottoms Up Clean to Sots Press', 'Execute a military press from the bottom of a squat holding upside-down kettlebells, the ultimate challenge of mobility and grip.'),
('f71ae310-1354-410c-8cfb-536d7d31e86f', '4e1a1c4e-8703-476c-9d63-8564b294d150', 'es', 'Doble Kettlebell desde abajo hacia arriba limpio para Sots Press', 'Ejecuta un press militar desde la posicion baja de la sentadilla sosteniendo las Kettlebells invertidas, el reto maximo de movilidad y agarre.'),
('c1892a1e-3929-41b3-9896-f77cd58451e6', '4e211af1-cacb-453d-9888-b52690686129', 'en', 'Single Arm Dumbbell Cyclist Thruster', 'With heels elevated, execute a deep squat with a dumbbell on the shoulder and finish by pressing it overhead during the ascent.'),
('b62d27c0-fc03-4262-9dd1-241d85b55a7f', '4e211af1-cacb-453d-9888-b52690686129', 'es', 'Thruster Ciclista a una mano con mancuerna', 'Con talones elevados, ejecuta una sentadilla profunda con una mancuerna en el hombro y termina presionándola sobre la cabeza en la subida.'),
('7dddf170-45e3-4bf2-b966-5971ada5d45e', '4e348580-50b3-4b92-adf3-0e20f70887d7', 'en', 'Full Back Lever on Rings', 'Maintain the body fully stretched and parallel to the floor face down hanging from the rings.'),
('b3f1c777-0fe5-46e4-913d-99bda33cf628', '4e348580-50b3-4b92-adf3-0e20f70887d7', 'es', 'Full Back Lever en anillas', 'Mantén el cuerpo totalmente estirado y paralelo al suelo boca abajo colgado de las anillas.'),
('a61fd3c7-41ad-4173-b772-27c423fc41ef', '4e6f9c6f-c35a-4441-a59c-e54b453a4be9', 'en', 'Barbell Front Raises', 'Lift the bar forward with straight arms to eye level. Objective: anterior deltoid. Cue: do not use hip momentum. Common error: swinging the torso back to lift the weight.'),
('2db6bc15-6ada-468f-9da9-255053ad259a', '4e6f9c6f-c35a-4441-a59c-e54b453a4be9', 'es', 'Elevaciones frontales con barra', 'Eleva la barra al frente con brazos rectos hasta la altura de los ojos. Objetivo: deltoides anterior. Cue: no uses el impulso de la cadera. Error común: balancear el torso hacia atrás para subir el peso.'),
('7ab06652-7505-4adc-ad90-8931af02ac18', '4e81adf7-3cdc-476f-a04f-93128c9a2dad', 'es', 'Tuck L-Sit', 'Apoya las manos en el suelo o paralelas y levanta las rodillas hacia el pecho manteniendo los brazos bloqueados y la cadera en el aire.'),
('4c6ddebe-4e10-4fef-ab7e-f5b7b7cc8b4c', '4e8f8abe-b784-4c5a-8557-7daf1666a614', 'en', 'Alternating Single Arm Parallette Push Up', 'Perform push-ups on parallettes alternating support on a single arm in each descent to maximize intensity.'),
('e3b2b780-0fc0-4344-ac03-3ef1eaaf3a0b', '4e8f8abe-b784-4c5a-8557-7daf1666a614', 'es', 'Flexiones alternadas en paralelo con un solo brazo', 'Realiza flexiones sobre las paralelas alternando el apoyo de un solo brazo en cada descenso para maximizar la intensidad.'),
('a02741cc-d465-4f18-895d-6245a5fd752a', '4ec0bb04-373a-4cbf-a71a-82a5680e5d87', 'en', 'Parallette L Sit', 'Hold yourself on the parallettes with arms straight. Lift legs straight in front of you until forming a 90-degree angle and hold the position.'),
('96ce154a-8478-41b5-8a1d-1247fc0d02ae', '4ec0bb04-373a-4cbf-a71a-82a5680e5d87', 'es', 'L-Sit en paralelas', 'Sostente sobre las paralelas con los brazos estirados. Levanta las piernas rectas frente a ti hasta formar un ángulo de 90 grados y mantén la posición.'),
('bb6ca7ad-40df-413d-8523-f2f06b32d25f', '4ee95eaa-488f-4d44-86a5-45feba1e6cf6', 'es', 'Pike TRX', 'En plancha con pies en las correas, eleva las caderas llevando el cuerpo a posición de V invertida. Trabaja intensamente hombros y core. Mantén las piernas rectas y controla el movimiento en ambas direcciones.'),
('e1dbfb22-08ae-4cc6-83f1-857a249f821e', '4ee98f68-07c8-4a7d-831e-c3687db82b94', 'en', 'Single Arm Cable Single Leg Romanian Deadlift', 'Perform a single-leg Romanian deadlift while holding the low pulley handle with the opposite arm, stabilizing the hip.'),
('5f90cb8e-b809-4b8a-b8d3-5ec242ace461', '4ee98f68-07c8-4a7d-831e-c3687db82b94', 'es', 'Peso muerto rumano a una pierna con cable a una mano', 'Realiza un peso muerto rumano sobre una pierna mientras sujetas el mango de la polea baja con el brazo opuesto, estabilizando la cadera.'),
('58b3d5b8-7031-4792-81be-e2c30586e2d6', '4eea648e-0f1d-4675-a0aa-b0e7fefcb26d', 'en', 'Standing Rollout', 'From a standing position, lean and roll forward until full extension, then return to a standing position. Requires exceptional core strength and flexibility. It is the most difficult progression of the exercise.'),
('b5a56e42-2af3-435e-af8f-ae3f16c4e5a9', '4eea648e-0f1d-4675-a0aa-b0e7fefcb26d', 'es', 'Roll out de pie', 'Desde posición de pie, inclínate y rueda hacia adelante hasta extensión completa, luego vuelve a ponerte de pie. Requiere fuerza excepcional del core y flexibilidad. Es la progresión más difícil del ejercicio.'),
('9bb80e60-cdb2-4543-8b73-7169a8c5240a', '4f1ce2bf-e764-4281-8c6c-21b6b8ef3234', 'en', 'Rigid Feet Together Pogo Jump', 'Pogo jumps keeping knees locked (straight legs) to isolate the ankle. Cue: bounce like a spring. Common error: flexing knees due to fatigue.'),
('6651dd47-59f1-4466-934f-2281f269b86c', '4f1ce2bf-e764-4281-8c6c-21b6b8ef3234', 'es', 'Salto pogo pies juntos rígidos', 'Saltos pogo manteniendo las rodillas bloqueadas (piernas rectas) para aislar el tobillo. Cue: rebota como un muelle. Error común: flexionar las rodillas por fatiga.'),
('d2b9c4d2-cc2b-4857-8986-53255992b36e', '4f662146-7070-4252-84ad-2ca2a9574cdf', 'en', 'One-Arm Cable Front Raise', 'Back to the low pulley, grab the handle with one hand. Lift the arm straight forward to shoulder height.'),
('46ef601f-7145-4ade-b956-e29de2b3b152', '4f662146-7070-4252-84ad-2ca2a9574cdf', 'es', 'Elevación frontal a una mano con cable', 'De espaldas a la polea baja, agarra el mango con una mano. Levanta el brazo recto hacia adelante hasta la altura del hombro.'),
('44949eb0-06c6-4e28-a52f-376ac6b9b0cb', '4f6677ea-6cae-4c12-a5be-5b33a58d9eae', 'en', 'Bodyweight Kneeling Side Plank', 'Support yourself on one forearm and the knee of the same side on the ground. Lift your hips maintaining a straight line from head to knees.'),
('15e13303-797e-4e92-b3e9-b7e16049d66a', '4f6677ea-6cae-4c12-a5be-5b33a58d9eae', 'es', 'Plank lateral de rodillas', 'Apoya un antebrazo y la rodilla del mismo lado en el suelo. Eleva la cadera manteniendo una linea recta desde la cabeza a las rodillas.'),
('7133165a-4a10-43ce-86b6-bc05df1b3200', '4f770740-6ab9-4682-ae75-bae4e1eb4438', 'en', 'Eccentric Bar Chin Up', 'Jump to the top position of the supinated pull-up and lower yourself extremely slowly until arms are fully straightened.'),
('4c08a56c-470c-4e45-974c-bdfc8d267c67', '4f770740-6ab9-4682-ae75-bae4e1eb4438', 'es', 'Chin Up excéntrico en barra', 'Salta a la posición superior de la dominada supina y baja de forma extremadamente lenta hasta que los brazos estén completamente estirados.'),
('20dd3c40-05e2-4bba-905f-ce30301df0ad', '4f9b1ae7-2a4d-4435-a494-07301371a8fa', 'en', 'Kettlebell Renegade Row', 'In a push-up position on the weights, perform an alternating row. Core stability. Body as a solid unit. Do not rotate the hip when rowing.'),
('66380657-892f-4b87-9de5-6427e0e3ca08', '4f9b1ae7-2a4d-4435-a494-07301371a8fa', 'es', 'Kettlebell Renegade Row', 'En posición de flexión sobre las pesas, realiza un remo alterno. Estabilidad de core. Cuerpo en bloque. No rotes la cadera al remar.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('9af5764f-c8d8-4f7c-b581-f68bdb8f8d11', '4fb46d99-4612-4598-94e7-08663b402b6d', 'en', 'Pull-up Bar Passive Hang', 'Hold the bar and maintain dead weight for time. Cue: firm grip. Error: shrugging shoulders.'),
('1d07b642-ddf6-4f21-8677-1396f66c55d5', '4fb46d99-4612-4598-94e7-08663b402b6d', 'es', 'Colgado pasivo en barra dominadas', 'Sujeta la barra y mantén el peso muerto por tiempo. Cue: agarre firme. Error: encoger los hombros.'),
('f17922ec-cd9d-46bf-899c-8550afa00af7', '4fc2f28b-4bdd-4517-96b2-c481bfa6a403', 'en', 'One-Arm Reverse Grip Cable Bicep Curl', 'Perform a single arm curl on low pulley with a prone grip (palm down) to isolate forearm and bicep work.'),
('827a1567-222e-4074-8263-12de161e30ca', '4fc2f28b-4bdd-4517-96b2-c481bfa6a403', 'es', 'Curl de bíceps agarre inverso a una mano con cable', 'Realiza un curl a un solo brazo en polea baja con el agarre prono (palma abajo) para aislar el trabajo del antebrazo y bíceps.'),
('0377406e-bcdc-4e4d-9357-68e9fe015c3d', '50130e19-add3-4ffa-91a0-8609182f0188', 'en', 'Stability Ball Cable Russian Twist', 'Rest your back on the stability ball and rotate your torso side to side pulling the cable, keeping hips stable.'),
('cf3261a1-3b04-455c-8930-6359d61d3b2f', '50130e19-add3-4ffa-91a0-8609182f0188', 'es', 'Russian Twist sobre Fitball con cable', 'Apoya la espalda en el Fitball y gira el torso de lado a lado tirando del cable, manteniendo las caderas estables.'),
('3acde0fa-ec1f-4256-906e-cde6b5cdd139', '5024a46c-b8e9-4e62-94a2-b105b629a6bc', 'en', 'Miniband Knee Hover Quadruped Fire Hydrant', 'On all fours with a band, lift one knee laterally while the other knee remains off the ground for constant tension.'),
('d951458b-869c-478c-bea9-07bc92ecff8a', '5024a46c-b8e9-4e62-94a2-b105b629a6bc', 'es', 'Fire Hydrant en cuadrupedia con rodilla flotante y Miniband', 'En cuadrupedia con banda, levanta una rodilla lateralmente mientras la otra rodilla permanece sin tocar el suelo para tension constante.'),
('9183ece9-ed96-46c1-a412-957eb9a75769', '50485213-d2d8-48a3-a70b-58b15406c813', 'en', 'Two-Handed Tricep Overhead Extension', 'Hold a dumbbell overhead and lower it behind the neck. Cue: elbows tucked forward. Error: arching the lower back.'),
('784e012a-e36e-4ee9-bcbf-45ec23446890', '50485213-d2d8-48a3-a70b-58b15406c813', 'es', 'Copa de tríceps a dos manos', 'Sujeta una mancuerna sobre la cabeza y bájala por detrás de la nuca. Cue: codos cerrados hacia adelante. Error: arquear la espalda lumbar.'),
('5b794866-0c45-4897-83be-1284aab0ed71', '505c8bc3-6a03-4dc4-bac1-5466ecf0ab00', 'en', 'Kneeling Landmine Oblique Twist', 'In a half-kneeling position, rotate the Landmine bar from the shoulder on the side of the supported knee toward the opposite hip explosively.'),
('b14140cc-b00c-4049-a7f1-ceefba819c74', '505c8bc3-6a03-4dc4-bac1-5466ecf0ab00', 'es', 'Giro oblicuo de rodillas en Landmine', 'En posición de caballero, gira la barra Landmine desde el hombro del lado de la rodilla apoyada hacia la cadera opuesta de forma explosiva.'),
('32b39265-5c34-4e05-a509-12657e0b6b2c', '5089c8b3-194d-4027-adb6-acc848fb7244', 'es', 'Zancada inversa alterna con mancuernas', 'Desde de pie con mancuernas, da un paso largo hacia atrás bajando la cadera. Mantén el torso erguido y regresa al centro.'),
('069dd8b5-b9cf-4748-b135-837722f117e7', '50cd7040-fb8f-4541-85cb-02fc9eeaa890', 'es', 'Plancha RKC', 'Aprieta glúteos fuerte, mete costillas y empuja antebrazos al suelo. Busca máxima tensión, no solo aguantar tiempo.'),
('c5fe257e-3fb7-412a-b127-8c543f4ddd25', '50e47853-cc6d-48b0-91b9-785d2638fe19', 'en', 'Passive Bar Hang', 'Hold the pull-up bar and stay suspended for time. Objective: grip strength and spinal decompression. Cue: firm grip and total relaxation. Common error: shrugging shoulders toward ears.'),
('264b67de-f6a1-4481-be85-26b546f02e9f', '50e47853-cc6d-48b0-91b9-785d2638fe19', 'es', 'Colgado pasivo en barra', 'Sujeta la barra de dominadas y mantente suspendido por tiempo. Objetivo: fuerza de agarre y descompresión espinal. Cue: agarre firme y relajación total. Error común: encoger los hombros hacia las orejas.'),
('af910787-575a-4638-9abd-59347c2141fa', '51026931-39c2-4468-8966-e5c0b5856c4b', 'en', 'Bodyweight Copenhagen Plank', 'In a side plank with the top foot on a bench and the bottom one free, keep the hips elevated working the adductors intensely.'),
('b6474a9f-b986-4f15-94cb-1c0e1a5faa45', '51026931-39c2-4468-8966-e5c0b5856c4b', 'es', 'Copenhagen Plank', 'En plancha lateral con el pie superior en banco y el inferior libre, mantén la cadera elevada trabajando intensamente los aductores.'),
('6a165d8d-4a5e-4e4e-a727-1a1c5c3caa44', '511bb99a-f2b6-4aed-b96d-208559c6c364', 'en', 'Standing Dumbbell Concentration Curl', 'Standing, lean forward supporting one hand on something stable. With the other arm hanging freely, perform a curl focusing on the bicep.'),
('3d164b58-b480-4b94-8317-d6a6fa7bddf0', '511bb99a-f2b6-4aed-b96d-208559c6c364', 'es', 'Curl concentrado de pie con mancuerna', 'De pie, inclínate hacia adelante apoyando una mano en algo estable. Con el otro brazo colgando libremente, realiza un curl concentrándote en el bíceps.'),
('7e27f77c-942a-41b1-8f98-08f1ce86914c', '5158de68-07b4-4419-aa6a-678ae09932b0', 'es', 'Press Pallof estático cable', 'Resiste la rotación del cable extendiendo brazos al frente. Cue: pies clavados. Error: girar el torso.'),
('0fedc47a-cb75-4acd-9771-4accd1b74bfd', '5175bece-30f4-4143-8a83-313272a91770', 'en', 'Single Arm Dumbbell Half Kneeling Ipsilateral Overhead Press', 'In a half-kneeling position, press the dumbbell overhead with the arm on the same side as the kneeling knee (ipsilateral).'),
('bbf9edd3-2268-4147-9d2f-baf48fc907a9', '5175bece-30f4-4143-8a83-313272a91770', 'es', 'Press de hombros ipsilateral medio arrodillado con mancuerna', 'En posicion de caballero, presiona la mancuerna sobre la cabeza con el brazo del mismo lado que la rodilla apoyada (ipsilateral).'),
('8b501ca4-3f16-4f5b-8e9a-3f2c9b5cf0f0', '518ef945-a940-479d-9470-18dbb4d0b4d0', 'es', 'Push Press con barra', 'Press de hombro usando un pequeño impulso de piernas para superar el punto crítico. Cue: dip corto y explosivo. Error: bajar la barra golpeando clavículas.'),
('6e5893f4-5442-4572-be65-da410f626c41', '51a2ce48-9acd-4b9b-a59c-dd690790d7d8', 'en', 'Arm Opening Vertical Jump', 'Jump and open arms laterally in the air before lowering them. Improves dynamic scapular mobility. Cue: fully stretch arms. Common error: lack of jump height.'),
('bf90ef3c-25e2-4c9d-9e45-3bfdeeb68b42', '51a2ce48-9acd-4b9b-a59c-dd690790d7d8', 'es', 'Salto vertical apertura brazos', 'Salta y abre los brazos lateralmente en el aire antes de volver a bajarlos. Mejora la movilidad escapular dinámica. Cue: estira los brazos por completo. Error común: falta de altura en el salto.'),
('0bb41767-caea-40dd-ab21-e655ac07bb89', '51b4201c-cf7d-403a-966b-6f35e49147ab', 'en', 'Box Jump with Top Pause', 'Jump onto the box and maintain the landing position for 3 seconds with absolute control. Cue: silent landing. Common error: straightening immediately upon landing.'),
('ca2eb414-d48b-4df6-b5b6-430d028557c1', '51b4201c-cf7d-403a-966b-6f35e49147ab', 'es', 'Salto al cajón pausa superior', 'Salta al cajón y mantén la posición de aterrizaje 3 segundos con control absoluto. Cue: aterrizaje silencioso. Error común: estirarse inmediatamente al caer.'),
('561e2bf7-1115-429d-af56-fda6d12a5b43', '51f484a7-6fd4-4a7a-8922-29306a3d748a', 'en', 'Double Kettlebell Front Rack Low Switch Cossack Squat', 'Perform the side switch in a Cossack squat staying as close to the floor as possible with kettlebells in front rack.'),
('d897e93b-ceda-47c8-b539-21a8442fdb1a', '51f484a7-6fd4-4a7a-8922-29306a3d748a', 'es', 'Sentadilla cosaca con cambio bajo Front Rack con Kettlebell doble', 'Realiza el cambio de lado en la sentadilla cosaca manteniéndote lo mas cerca del suelo posible con las pesas en rack frontal.'),
('248e22f7-ecfb-448e-b9f8-bf40adc79474', '52007bc7-174c-4251-b0f2-14cccfe47089', 'en', 'Sit Ups with Weight Plate', 'Abdominal sit-up with weight at the chest. Objective: core strength. Cue: lower slowly. Error: lifting feet.'),
('a9134ef5-56dc-4f1d-b31a-624c4c90298c', '52007bc7-174c-4251-b0f2-14cccfe47089', 'es', 'Sit ups con disco', 'Incorporación abdominal con peso al pecho. Objetivo: fuerza core. Cue: baja lento. Error: despegar pies.'),
('8d0e2e40-2c89-4e51-9778-7b5b9c6ff076', '529e4e8e-df93-438c-b352-e6bae02d4c7f', 'en', 'High Cable Bar Bicep Curl', 'Standing in front of a high pulley, grab the straight bar. Keeping elbows high, flex arms to bring the bar toward the forehead.'),
('e158f6c5-7346-460e-948e-9d1211058e7b', '529e4e8e-df93-438c-b352-e6bae02d4c7f', 'es', 'Curl de bíceps alto con barra en cable', 'De pie frente a una polea alta, agarra la barra recta. Manteniendo los codos en alto, flexiona los brazos para llevar la barra hacia la frente.'),
('83651ba7-b147-4b0c-9706-ac1a5f726e5e', '52b89ce8-bd74-4736-ad41-1f29732fb3a4', 'en', 'Machine Hamstring Curl', 'Lying or seated, flex knees against the machine roller. Objective: hamstring isolation. Cue: keep hips fixed to the bench. Common error: jerking with the lower back.'),
('571ab6a1-99ac-4444-aec4-4ae7ca5f9655', '52b89ce8-bd74-4736-ad41-1f29732fb3a4', 'es', 'Curl femoral en máquina', 'Tumbado o sentado, flexiona las rodillas contra el rodillo de la máquina. Objetivo: aislamiento del isquiotibial. Cue: mantén la cadera fija al banco. Error común: realizar tirones con la espalda baja.'),
('50aff2ad-f163-4419-a87a-777c64541138', '52b96c88-1b02-4347-b3d4-51ca7f32b9a5', 'en', 'Barbell Deficit Snatch Grip Deadlift', 'Perform a deadlift with a wide grip while standing on an elevated platform, significantly increasing the range of motion and back demand.'),
('a2989adf-2f87-4cf7-8864-bcae5ec7809c', '52b96c88-1b02-4347-b3d4-51ca7f32b9a5', 'es', 'Peso muerto Snatch Grip con déficit con barra', 'Realiza un peso muerto con agarre ancho sobre una plataforma elevada, aumentando significativamente el recorrido y demanda de la espalda.'),
('bfa77da4-e711-4270-9a6b-134b4e09df22', '52c26109-05be-4330-8d61-c6f9bf2a8ddf', 'en', 'Dumbbell Sumo Squat', 'Wide feet, toes pointed out, hold the weight down. Adductor focus. Straight back. Knees aligned with feet.'),
('c7ecc7be-e56a-4866-bb47-a76584a25e41', '52c26109-05be-4330-8d61-c6f9bf2a8ddf', 'es', 'Sentadilla sumo con mancuerna', 'Pies anchos, punta hacia afuera, sujeta la pesa abajo. Enfoque aductores. Espalda recta. Rodillas alineadas con los pies.'),
('a7b97114-07f1-4320-8e61-7b42c572edb8', '52db2bf3-3f51-4145-ae35-da28fd853ece', 'en', 'Bosu Dynamic Mountain Climbers', 'Hands on the flat side of the Bosu, bring knees to chest quickly. Objective: cardio and unstable core. Cue: core very tight. Common error: Bosu shaking out of control.'),
('7a6dca9d-f1f6-4dcb-9bcc-9df903ec841f', '52db2bf3-3f51-4145-ae35-da28fd853ece', 'es', 'Bosu Escaladores dinámicos', 'Manos en lado plano del bosu, lleva rodillas al pecho rápidamente. Objetivo: cardio y core inestable. Cue: core muy apretado. Error común: que el bosu tiemble fuera de control.'),
('7dfdee6b-1345-4937-afe1-a620458b6008', '5323a9df-095d-4a4a-a3a8-6bbc2a2f068e', 'es', 'Press militar mancuernas pie', 'Press hombros de pie. Objetivo: hombro y core. Cue: no inclinar atrás. Error: usar piernas.'),
('bc641b59-fa92-4456-9fc1-e9767c21a79c', '53390d02-3393-4179-96b3-207f7a305f31', 'en', 'Alternating Cossack Squat', 'From a standing position with legs very wide, shift weight to one side by flexing one knee while keeping the other leg fully straight and the torso upright.'),
('8babf3e4-c5cf-429b-92ce-82240b9caf2c', '53390d02-3393-4179-96b3-207f7a305f31', 'es', 'Sentadilla cosaca alterna', 'Desde una posicion de pie con las piernas muy abiertas, desplaza el peso hacia un lado flexionando una rodilla mientras mantienes la otra pierna completamente estirada y el torso erguido.'),
('c3459be2-b745-4053-99aa-d3820776eaa8', '5369016c-24f0-4259-8848-6fc557512de9', 'en', 'Single Arm Kettlebell Front Rack Ipsilateral Bulgarian Split Squat', 'Perform a Bulgarian split squat with an elevated foot holding the kettlebell in a front rack position on the same side as the front leg.'),
('2278d8e7-01d4-46a9-9be8-a3333518f63b', '5369016c-24f0-4259-8848-6fc557512de9', 'es', 'Sentadilla Búlgara búlgara ipsilateral con rack frontal y pesa rusa de un solo brazo', 'Realiza una sentadilla búlgara con el pie elevado sosteniendo la Kettlebell en posicion rack en el mismo lado de la pierna delantera.'),
('3cab0a2d-8895-4c0f-a7bd-72b70626a1c7', '53a2b9e5-62c9-4184-8d0f-07050e760d69', 'en', 'Slider Mountain Climber', 'In a plank position with feet on sliders, slide the knees alternately toward the chest in a fluid and fast motion without lifting the hips.'),
('ebb7e644-60f7-4662-85fb-71f959923f05', '53a2b9e5-62c9-4184-8d0f-07050e760d69', 'es', 'Mountain Climber con Slider', 'En posición de plancha con los pies sobre sliders, desliza las rodillas alternativamente hacia el pecho de forma fluida y rápida sin levantar las caderas.'),
('a3bda9fd-d913-40af-9a3f-ddd6fc348281', '53b819b0-0402-4f84-8f17-c4845d4d8c2d', 'en', 'Trap Bar Floor Press', 'Lying on the floor inside the Trap bar, press the weight upward starting from a position with elbows supported.'),
('f20e167a-99b9-4871-aca1-d24b581074e0', '53b819b0-0402-4f84-8f17-c4845d4d8c2d', 'es', 'Floor Press con barra Trap', 'Tumbado en el suelo dentro de la barra Trap, presiona el peso hacia arriba partiendo de una posicion con los codos apoyados.'),
('6b562abf-6777-4030-ad6c-d1be58d5afa5', '53c2109d-2b2a-4f92-a961-843a3e820d4a', 'es', 'Peso muerto Trap Bar (agarre alto)', 'Levanta la barra hexagonal usando las asas superiores para reducir el rango de movimiento. Objetivo: fuerza general con menor estrés lumbar. Cue: saca pecho y espalda plana. Error común: rodillas hacia adentro al subir.'),
('ac139c6b-419a-449a-9899-d0098673e40d', '5440b510-b8b6-41df-907e-b233510cb07d', 'en', 'Battle Rope Alternating Inward Circle', 'Perform alternating inward circles with the ends of the battle rope, engaging shoulders and core.'),
('268c8b5f-7f0a-4e03-9ad9-6aea7d843679', '5440b510-b8b6-41df-907e-b233510cb07d', 'es', 'Círculo hacia adentro alterno con cuerda de batalla', 'Realiza círculos hacia adentro de forma alterna con los extremos de la cuerda de batalla, activando hombros y core.'),
('802bc66b-587c-40b7-b265-28c3d5291f81', '544e9c3b-c572-4e19-9783-d735069bb8ee', 'es', 'Press sots kettlebell', 'Press desde la posición más baja de sentadilla. Requiere movilidad excepcional en hombros, caderas y tobillos. Nombrado por Viktor Sots. Comienza con peso muy ligero. Construye fuerza en posiciones extremas.'),
('a1a59545-d324-4ab0-9c65-9d105cb0c846', '54697f58-6c3a-47b3-a9d0-7bfdee394809', 'en', 'Strict Seated Barbell Good Mornings', 'Seated, lean torso forward with barbell on shoulders. Cue: flat back. Error: lowering too fast.'),
('06fdbe20-5d69-482b-bf04-bf5a65385b06', '54697f58-6c3a-47b3-a9d0-7bfdee394809', 'es', 'Buenos días sentado barra estricto', 'Sentado, inclina torso adelante con barra en hombros. Cue: espalda plana. Error: bajar muy rápido.'),
('7cc7bd7c-ddbb-43b1-a2cf-6521d59217fb', '547269f1-ec6e-4058-8094-bb84a4836a29', 'en', 'Strict Dead Bug', 'On your back, lower opposite arm and leg while keeping the lower back glued. Cue: very slow movement. Error: lifting the back off the floor.'),
('75416640-e8ae-4559-b90f-6bd15dfbe91f', '547269f1-ec6e-4058-8094-bb84a4836a29', 'es', 'Dead Bug estricto', 'Boca arriba, baja brazo y pierna contraria manteniendo lumbar pegada. Cue: movimiento muy lento. Error: despegar la espalda del suelo.'),
('0f8e3bdc-0e25-42f7-a676-123479433f4a', '54880b1f-49ce-475e-b1a1-ff57fc80ad08', 'en', 'Abductor Machine', 'Seated in the machine, separate your legs against resistance working the hip abductors. Keep the back supported and avoid using momentum. Control both the concentric and eccentric phases of the movement.'),
('d08db61d-58ed-414a-a0be-91433c537225', '54880b1f-49ce-475e-b1a1-ff57fc80ad08', 'es', 'Abductor máquina', 'Sentado en la máquina, separa las piernas contra la resistencia trabajando los abductores de cadera. Mantén la espalda apoyada y evita usar impulso. Controla tanto la fase concéntrica como la excéntrica del movimiento.'),
('e6e35a3d-0883-4c9d-b204-6e6a4a158faa', '549b4716-2fbc-4b79-8657-21aad1dfc2ef', 'es', 'Zancada búlgara con salto', 'Con el pie trasero en banco, realiza un salto vertical con la pierna delantera. Potencia unilateral máxima. Cue: mantén el equilibrio al caer. Error común: que la rodilla pase excesivamente la punta del pie.'),
('09d3626c-6534-4f4a-a135-d3a870080423', '54c2e1e5-4b31-42d1-9fde-01e5ab1102d2', 'en', 'Chest pass', 'Explosive chest pass like in basketball. Can be done against a wall or with a partner. Develops horizontal power in the upper body. Keep elbows out and push with the entire body.'),
('3c001d6b-4766-4e09-9c6f-478a5dd16c7b', '54c2e1e5-4b31-42d1-9fde-01e5ab1102d2', 'es', 'Chest pass', 'Pase de pecho explosivo como en baloncesto. Puede hacerse contra pared o con compañero. Desarrolla potencia horizontal en el tren superior. Mantén los codos hacia afuera y empuja con todo el cuerpo.'),
('a80a14be-b24d-43a0-b4fd-b083655ecba0', '54ebca98-6bf6-4e9e-b047-52405de0198a', 'es', 'Plancha TRX', 'Plancha con pies o antebrazos en las correas del TRX. La inestabilidad aumenta drásticamente la activación del core. Mantén el cuerpo completamente recto resistiendo el balanceo de las correas.'),
('9f5fa4a9-9bd0-4378-8697-82e1381cc791', '54f81747-4f20-4cec-9c09-a5507639b6e8', 'es', 'Preacher curl máquina', 'Con los brazos apoyados en el soporte inclinado, realiza curls. La posición elimina completamente el impulso y proporciona máximo aislamiento. Ten cuidado de no hiperextender los codos en la posición inferior.'),
('60837b41-6d8b-4f3c-9cd9-d662884652a7', '54fe3d35-556b-41d3-a7e0-c9e545f40656', 'en', 'Single Arm Kettlebell Bottoms Up Front Rack Carry', 'Walk while holding an upside-down kettlebell in the rack position, which multiplies the challenge on the grip and shoulder stabilizers.'),
('a31bfe5b-b77a-40e0-ac95-912fb058c5f9', '54fe3d35-556b-41d3-a7e0-c9e545f40656', 'es', 'Caminata Front Rack con Kettlebell a una mano Bottoms Up', 'Camina sosteniendo una pesa rusa invertida en posición de rack, lo que multiplica el desafío sobre el agarre y los estabilizadores del hombro.'),
('1d0537ea-30db-4692-907f-03ace56fc269', '5506a6d5-c823-4697-9037-8f7b5b75d3db', 'en', 'One-Leg Long Jump', 'Jump forward as far as possible with one leg and land with the same leg. Extreme unilateral control. Cue: maintain balance when landing. Common error: letting the knee collapse inward.'),
('bbedb02f-46ab-42c6-b908-476df1cd18c3', '5506a6d5-c823-4697-9037-8f7b5b75d3db', 'es', 'Salto de longitud a una pierna', 'Salta hacia adelante lo más lejos posible con una sola pierna y aterriza con la misma pierna. Control unilateral extremo. Cue: mantén el equilibrio al caer. Error común: dejar que la rodilla colapse hacia adentro.'),
('c055e0df-ccac-4338-92e7-b66cbac223d8', '5532e282-0a58-4511-b626-b18e0346f394', 'en', 'Toe Touch Vertical Jump', 'Jump and extend legs forward to touch toes with hands. Cue: quick abdominal explosion. Common error: not raising legs high enough.'),
('d2d32b9c-34a3-4861-a716-ba782ca1674f', '5532e282-0a58-4511-b626-b18e0346f394', 'es', 'Salto vertical con toque de puntas', 'Salta y extiende las piernas al frente para tocar las puntas de los pies con las manos. Cue: explosión abdominal rápida. Error común: no elevar las piernas lo suficiente.'),
('ba6eb415-52c6-4e88-b170-72d25bda18db', '5538935c-60d2-4bc5-bd0f-dc3f8ba54266', 'en', 'Band Squat', 'Step on the center of the band with both feet and hold the ends at shoulder height. Perform a normal squat with the additional resistance of the band that increases progressively as you rise. Maintain constant tension in the band throughout the movement.'),
('9c2bba5e-6f7f-4305-aac0-af98e645b4bb', '5538935c-60d2-4bc5-bd0f-dc3f8ba54266', 'es', 'Sentadilla con banda', 'Pisa el centro de la banda con ambos pies y sujeta los extremos a la altura de los hombros. Realiza una sentadilla normal con la resistencia adicional de la banda que aumenta progresivamente al subir. Mantén la tensión constante en la banda durante todo el movimiento.'),
('a43edbdb-7cbc-4806-998e-29e2cd4bedd4', '55460653-2250-45fe-89fe-5a922a184700', 'en', 'Single Arm Ring Chin Up', 'Perform a chin-up using only one arm hanging from the ring, the highest level of unilateral pulling strength.'),
('d64c264a-683e-449a-a6a1-ca793e71d8b9', '55460653-2250-45fe-89fe-5a922a184700', 'es', 'Chin Up a una mano en anillas', 'Realiza una dominada supina utilizando solo un brazo colgado de la anilla, el nivel mas alto de fuerza de traccion unilateral.'),
('0bf888b9-d2ab-483a-b3d7-714f34d1793c', '5553d449-3632-4642-96aa-801b91c72c5b', 'es', 'Plancha lateral', 'Apóyate lateralmente sobre un antebrazo y el lateral del pie, manteniendo el cuerpo completamente alineado. Eleva las caderas para formar una línea recta desde la cabeza hasta los pies. Puedes elevar el brazo libre hacia el techo para mayor dificultad. Trabaja los oblicuos y mejora la estabilidad lateral.'),
('565f50d8-c717-44ff-8466-a72a5974d4e0', '5556c737-ef66-4e8a-92f7-c203930a2322', 'en', 'Double Dumbbell Seated Good Morning', 'Seated on the edge of a bench with dumbbells on your shoulders, hinge your torso forward keeping the back straight and rise with your lower back.'),
('edccaba5-bce5-4fe4-856c-97d19f12c1c1', '5556c737-ef66-4e8a-92f7-c203930a2322', 'es', 'Buenos días sentado con mancuernas', 'Sentado en el borde de un banco con mancuernas sobre los hombros, inclina el torso hacia adelante manteniendo la espalda recta y sube con los lumbares.'),
('e97e7d46-f98a-482b-a92a-51027926b978', '556f7604-66f9-4073-bcd1-736a605f0d7c', 'en', 'Single Arm Dumbbell Spider Curl', 'Face down on an incline bench, perform a bicep curl with one arm letting it hang vertically to eliminate momentum.'),
('4b4886d9-81d6-40b3-bed5-4f1f20d2df1a', '556f7604-66f9-4073-bcd1-736a605f0d7c', 'es', 'Spider Curl con mancuerna a una mano', 'Boca abajo en banco inclinado, realiza un curl de biceps con un solo brazo dejandolo colgar verticalmente para eliminar el impulso.'),
('04095df0-4da6-4cb0-b1ac-5fe566f0579b', '5583b4d8-7170-46b7-a341-5e28a635c6a2', 'en', 'Shrugs', 'Lift shoulders toward ears keeping arms straight. Objective: trapezius hypertrophy. Cue: do not rotate shoulders in circles. Common error: bending elbows to lift the weight.'),
('6fbcfe61-2a6f-49c6-b406-8b5416e78a3c', '5583b4d8-7170-46b7-a341-5e28a635c6a2', 'es', 'Encogimientos de hombros (Shrugs)', 'Eleva los hombros hacia las orejas manteniendo los brazos rectos. Objetivo: hipertrofia del trapecio. Cue: no rotes los hombros en círculos. Error común: doblar los codos para subir el peso.'),
('ac4c056c-ab9b-4333-841f-b779323f17e2', '55aecc8b-8d86-4a44-8c48-a0b07122c357', 'es', 'Zancada alternada con salto', 'Salta desde una posición de zancada y cambia de pierna en el aire repetidamente. Objetivo: potencia y resistencia de piernas. Cue: torso erguido siempre. Error común: golpear la rodilla trasera contra el suelo.'),
('f44c774c-4f6f-463f-8c85-ac1006133ac5', '55b23e51-ab1c-499f-b529-39be35130e42', 'en', 'Battle ropes in and out', 'Move the ropes horizontally, bringing them together and apart. Works the shoulders in the horizontal plane. Keep arms parallel to the ground. Vary the speed for different stimuli.'),
('c79bf580-d637-4d47-8f6e-96730d84fb25', '55b23e51-ab1c-499f-b529-39be35130e42', 'es', 'Battle ropes in and out', 'Mueve las cuerdas horizontalmente juntándolas y separándolas. Trabaja los hombros en el plano horizontal. Mantén los brazos paralelos al suelo. Varía la velocidad para diferentes estímulos.'),
('33149133-fb36-4942-99c8-84dc88bf3dc5', '55c2cb94-37b3-4e44-8eb4-2cd0252d3ee5', 'en', 'Fitball Hip Thrust', 'With upper back supported on the fitball or feet on it, perform hip thrusts. Instability increases muscle activation. Strongly squeeze glutes at the top. Control movement in both phases.'),
('382a12be-05d4-4301-8eca-e58d72dbe1f0', '55c2cb94-37b3-4e44-8eb4-2cd0252d3ee5', 'es', 'Hip thrust fitball', 'Con la espalda alta apoyada en la fitball o los pies sobre ella, realiza empujes de cadera. La inestabilidad aumenta la activación muscular. Aprieta fuertemente los glúteos en la parte superior. Controla el movimiento en ambas fases.'),
('b2a6a9aa-86d6-4b9a-afdf-5f9b81138ad2', '55dd7508-7838-4d6f-9c4a-2a303d7c83b1', 'en', 'Kneeling Cable Face Pull', 'In a half-kneeling position, pull the rope toward the face, separating hands and rotating shoulders externally.'),
('f89a4a82-851c-4ecc-a24e-68551f258d4a', '55dd7508-7838-4d6f-9c4a-2a303d7c83b1', 'es', 'Face Pull de rodillas con cable', 'En posición de caballero (una rodilla abajo), tira de la cuerda hacia la cara separando las manos y rotando hombros externamente.'),
('6b16cfeb-cab6-49db-88aa-3d856df0992a', '55e561dd-e84f-4210-839b-f195b0f782c6', 'en', 'Strict Diamond Push Ups', 'Hands together forming a diamond under the chest. Triceps focus. Straight body. Do not flare elbows out.'),
('d987c096-95dd-4ec5-bacc-0666618a7e64', '55e561dd-e84f-4210-839b-f195b0f782c6', 'es', 'Flexiones diamante estricto', 'Manos juntas formando un diamante bajo el pecho. Enfoque tríceps. Cuerpo recto. No abras los codos hacia afuera.'),
('ded6d564-4fd5-4492-85e3-ee783a7470f4', '55ed3cc4-4dc2-431f-96de-3e3d40cd8d56', 'es', 'Press Overhead alterno de rodillas con Kettlebell doble', 'De rodillas sobre ambas piernas, presiona las pesas rusas alternativamente sobre la cabeza manteniendo el core firme.'),
('adb0cf9e-b18f-4583-ba5d-1be273fc7a05', '560e5281-f504-4c49-9998-bacd9552d686', 'en', 'One-Leg L-Sit on Parallel Bars', 'Hold yourself on parallel bars and lift one straight leg in front of you while the other remains bent or supported, alternating to work the core.'),
('9ef46474-1c71-4f74-b034-fcbb3632c03b', '560e5281-f504-4c49-9998-bacd9552d686', 'es', 'L-Sit a una pierna en paralelas', 'Sostente en las paralelas y levanta una pierna estirada frente a ti mientras la otra permanece doblada o apoyada, alternando para trabajar el core.'),
('4a70366c-bf42-4cae-a587-8f7d30be6481', '562aca0e-49c6-4b47-b1e8-5f44b4c74c5a', 'en', 'Pin Squat', 'Start the movement from the low position with the bar on the rack''s safety pins. Eliminates the eccentric phase and the elastic reflex. Strengthens weak points. Adjust height according to your sticking point.'),
('ff8fbe3a-b8fc-4d2c-9d7f-3d99458240af', '562aca0e-49c6-4b47-b1e8-5f44b4c74c5a', 'es', 'Sentadilla desde pines', 'Comienza el movimiento desde la posición baja con la barra en los seguros del rack. Elimina la fase excéntrica y el reflejo elástico. Fortalece puntos débiles. Ajusta la altura según tu punto de estancamiento.'),
('a3fd0c22-d847-445f-b5eb-2b730e1e27a4', '56acd050-e450-4a46-904a-b3b9004e57c5', 'en', 'Contralateral Kneeling Dumbbell Shoulder Press', 'In a half-kneeling position (one knee supported), perform a shoulder press with the arm opposite to the front knee (contralateral) to increase core stability demand.'),
('50e4a05f-3e9f-42f8-aacc-8181483e3265', '56acd050-e450-4a46-904a-b3b9004e57c5', 'es', 'Press de hombros contralateral de rodillas con mancuerna', 'En posición de caballero (una rodilla apoyada), realiza un press de hombro con el brazo opuesto a la rodilla delantera (contralateral) para aumentar la demanda de estabilidad del core.'),
('bd4996ca-2bda-46c1-9cb2-d48e78cf6fcc', '56b3ee48-a1b5-48b5-9798-3224e4f7e897', 'es', 'Peso muerto una pierna TRX', 'RDL unilateral con TRX para asistencia de equilibrio. Permite enfocarse en el patrón de movimiento sin preocuparse tanto por el balance. Mantén la pierna trasera alineada con el torso durante todo el movimiento.'),
('bb5b10fc-43e2-454d-a7bc-20e9b8b55cdb', '56f7ecba-bf7e-4a96-9975-8ea31dbf7809', 'en', 'Ipsilateral Bottoms Up Overhead Slider Kettlebell Reverse Lunge', 'Hold an inverted kettlebell overhead and slide the leg on the same side on a slider. The most demanding stability exercise.'),
('b3b042f0-3480-4d82-ab2f-2f4a6e57b968', '56f7ecba-bf7e-4a96-9975-8ea31dbf7809', 'es', 'Zancada inversa Overhead ipsilateral Slider Kettlebell Bottoms Up', 'Sostén una pesa rusa invertida sobre la cabeza y desliza la pierna del mismo lado en un slider. El ejercicio de estabilidad mas exigente.'),
('4097a604-5bfb-4c20-a085-7a89da1bc485', '57226dc9-94e8-49eb-9c6f-3fa8ddf73370', 'en', 'Seated Reverse Grip Barbell Shoulder Press', 'Seated on a bench, perform a military press with a supinated grip, lowering the bar to the upper chest and fully extending the arms.'),
('9d5bd8f5-8211-484e-b896-801d929ba0a6', '57226dc9-94e8-49eb-9c6f-3fa8ddf73370', 'es', 'Press de hombros sentado agarre inverso con barra', 'Sentado en un banco, realiza un press militar con agarre supino, bajando la barra hasta la parte superior del pecho y extendiendo completamente los brazos.'),
('07c46a13-2597-4b21-8d0c-e9649a723011', '572e7775-f508-452d-9576-d3093d326e83', 'en', 'Incline Bench Plyometric Push Up', 'Hands on a bench, push forcefully so hands leave the surface and land softly. Ideal for intro to pushing power. Cue: cushion the fall with flexed elbows. Common error: locking elbows sharply on landing.'),
('e29fb670-b1b0-4a77-b949-c7b936614acb', '572e7775-f508-452d-9576-d3093d326e83', 'es', 'Flexión pliométrica sobre banco', 'Manos en un banco, empuja con fuerza para despegar las manos y vuelve a caer suavemente. Ideal para iniciación en potencia de empuje. Cue: amortigua la caída con codos flexionados. Error común: bloquear codos bruscamente al aterrizar.'),
('842ee5d8-e6e8-45cf-bc3b-019abe038f18', '574283ab-c2e8-4ce7-9db2-4cf155eaf3f2', 'es', 'Press Overhead a una mano con Kettlebell', 'Desde la posición de rack (pesa en el antebrazo), empuja la pesa rusa verticalmente hasta bloquear el brazo y baja con control.'),
('24aca685-47e4-4aef-8cfc-1d749a5d5859', '574889ba-f9b3-4618-9f4e-91ac36b34828', 'en', 'Parallette Mountain Climber', 'Place hands on parallette bars in a plank position. Bring one knee toward the chest and alternate quickly with the other leg, keeping back straight and abdomen contracted.'),
('e5936918-8d45-4964-b7b7-fc2b02b58378', '574889ba-f9b3-4618-9f4e-91ac36b34828', 'es', 'Mountain Climber en paralelas', 'Coloca las manos sobre las barras paralelas en posición de plancha. Lleva una rodilla hacia el pecho y alterna rápidamente con la otra pierna, manteniendo la espalda recta y el abdomen contraído.'),
('46c25646-0190-4509-a62a-09adbe57a0d6', '5756b533-86be-4dbc-a08c-1f59001785b9', 'en', 'Strict Neutral Grip Pull-ups', 'Pull up on parallel bars until chin clears. Objective: back and biceps with less wrist stress. Cue: squeeze shoulder blades. Common error: not going all the way down.'),
('953f92be-f98a-47b2-855e-891ab2733ee7', '5756b533-86be-4dbc-a08c-1f59001785b9', 'es', 'Dominadas con agarre neutro estricto', 'Sube en barras paralelas hasta pasar barbilla. Objetivo: espalda y bíceps con menor estrés muñeca. Cue: junta escápulas. Error común: no bajar del todo.'),
('b0136d40-f5d1-4231-a6fc-c9e3cd77dd38', '5762c0af-8ed2-4449-85ae-0e2e31ef2d6e', 'en', 'Leg Extension', 'Perform leg extensions on a machine. Extend the knees until the quadriceps contract and lower under control without losing position.'),
('88e00832-f6ba-40b3-bead-c3c77d718c67', '5762c0af-8ed2-4449-85ae-0e2e31ef2d6e', 'es', 'Extensiones de cuadriceps', 'Realiza extensiones de cuádriceps en máquina. Extiende las rodillas hasta contraer el cuádriceps y baja de forma controlada sin perder la posición.'),
('e98daf96-aedb-4cc6-ba91-fe97c1170130', '576eb53b-0126-4dfb-871c-26ae58dfb6c0', 'en', 'One-Arm Landmine Hack Squat', 'With your back to the Landmine bar, rest the end on one shoulder and perform a squat, taking advantage of the angle to emphasize the quadriceps.'),
('0e005e44-6fc2-4355-8c38-e0544e050791', '576eb53b-0126-4dfb-871c-26ae58dfb6c0', 'es', 'Sentadilla Hack a una mano en Landmine', 'De espaldas a la barra Landmine, apoya el extremo en un hombro y realiza una sentadilla, aprovechando el ángulo para enfatizar los cuádriceps.'),
('09c6b2bb-e453-4bb8-b3d1-edff78b2f691', '5774af89-b666-4b4e-9483-db0950623906', 'en', 'Barbell Pendlay Row', 'With the torso parallel to the floor, explosively lift the bar from the floor to touch the abdomen and return it to the floor on each rep.'),
('cb59f19c-054b-410d-b293-45ecbb19dc55', '5774af89-b666-4b4e-9483-db0950623906', 'es', 'Remo Pendlay con barra', 'Con el torso paralelo al suelo, levanta la barra explosivamente desde el suelo hasta tocar el abdomen y regrésala al suelo en cada repetición.'),
('40da152c-8adf-4a18-8c23-2026d1acfe01', '57c0056d-275e-459f-a529-2ef7eed02db9', 'es', 'Plancha frontal', 'Apoya los antebrazos y las puntas de los pies en el suelo, manteniendo el cuerpo completamente recto desde la cabeza hasta los talones. Contrae el abdomen y glúteos para mantener la posición. Evita que las caderas se eleven o desciendan. Mantén la respiración regular durante todo el ejercicio.'),
('7f295871-28bf-415e-b2c8-376d44697067', '57dc22ed-c32a-46bd-8ae5-529711a737d6', 'en', 'Paused Deadlift', 'Deadlift with a 2-3 second pause at mid-height (knees). Eliminates stretch reflex and increases time under tension. Strengthens weak points. Use less weight than a regular deadlift.'),
('73f61b45-6d56-4418-b77e-342eb458c3bc', '57dc22ed-c32a-46bd-8ae5-529711a737d6', 'es', 'Peso muerto con pausa', 'Peso muerto con pausa de 2-3 segundos a media altura (rodillas). Elimina el reflejo de estiramiento y aumenta tiempo bajo tensión. Fortalece puntos débiles. Usa menos peso que el peso muerto regular.'),
('0107fe09-5035-4bb8-85a6-5864e72781ff', '586e098b-da86-469c-a981-6385c2d21435', 'en', 'Box Jump with One-Leg Controlled Descent', 'Jump onto the box with two legs but lower slowly using only one leg. Emphasizes eccentric control. Cue: stable knee when lowering. Common error: dropping heavily.'),
('2b505570-94c7-4376-af45-da725398243b', '586e098b-da86-469c-a981-6385c2d21435', 'es', 'Salto al cajón con una pierna bajada controlada', 'Salta al cajón con dos piernas pero baja lentamente usando solo una pierna. Enfatiza el control excéntrico. Cue: rodilla estable al bajar. Error común: dejarse caer pesadamente.'),
('41f34c9c-bf63-4bda-9c02-65e544e171dc', '587e3719-e12a-4876-859c-5270284b713a', 'en', 'Ring Strap Bulgarian Handstand Push Up', 'Perform a handstand with your legs supported by the ring straps for stability and execute vertical push-ups.'),
('47e340ee-f890-4bd2-aebb-2ea189a3dcc9', '587e3719-e12a-4876-859c-5270284b713a', 'es', 'Handstand Push Up búlgaro en anillas', 'Realiza una parada de manos con las piernas apoyadas en las correas de las anillas para estabilidad y ejecuta flexiones verticales.'),
('4f231cb2-8137-4a22-8d95-6f74a9300826', '591a0882-7753-441c-b083-4b2c4fcd1f49', 'en', 'Close Grip Parallel Bar Push Up', 'Place hands on parallel bars at less than shoulder width. Lower the chest while keeping the elbows close to the body to emphasize the triceps.'),
('5fa86e16-adbd-4a65-a0f2-ac9771b1c0b6', '591a0882-7753-441c-b083-4b2c4fcd1f49', 'es', 'Push Up agarre cerrado en paralelas', 'Coloca las manos en las barras paralelas a una anchura menor que los hombros. Baja el pecho manteniendo los codos pegados al cuerpo para enfatizar los tríceps.'),
('0f2c7054-0f94-4a43-808e-d02945961e64', '591f560f-8294-4572-8cf7-051e26e99531', 'en', 'Dumbbell Goblet Squat', 'Hold a dumbbell vertically against the chest with both hands, as if holding a chalice. Perform the squat maintaining the torso more upright than in a traditional squat. Excellent for learning correct technique and improving mobility.'),
('9e5887e3-7f0f-495a-861e-e8929cf0bd01', '591f560f-8294-4572-8cf7-051e26e99531', 'es', 'Goblet squat mancuernas', 'Sujeta una mancuerna verticalmente contra el pecho con ambas manos, como si sostuvieras un cáliz. Realiza la sentadilla manteniendo el torso más erguido que en la sentadilla tradicional. Excelente para aprender la técnica correcta y mejorar la movilidad.'),
('e4a09fcb-a33f-4a2c-8ec4-df0e64b7e54e', '59267759-1184-4ae4-921b-4ace3043ff65', 'en', 'TRX Lunges', 'With the back foot in the TRX strap, perform lunges. The instability of the strap increases stabilization work and allows for a greater range of motion. Also known as TRX Bulgarian split squat.'),
('15db626a-6629-43a6-8178-28bbc335934e', '59267759-1184-4ae4-921b-4ace3043ff65', 'es', 'Zancadas TRX', 'Con el pie trasero en la correa del TRX, realiza zancadas. La inestabilidad de la correa aumenta el trabajo de estabilización y permite mayor rango de movimiento. También conocido como sentadilla búlgara en TRX.'),
('47f12faf-78e7-4d50-9d6a-f0e331c1eafd', '593346cf-1688-4b40-95bf-9665c7025c04', 'en', 'Wrestler Toss Battle Ropes', 'Simulate a wrestler toss movement with the ropes. Explosive diagonal movement from top to bottom alternating sides. Involves core rotation. Maintain a low athletic posture.'),
('b4822089-8b11-40e4-a8cb-2b346179e5a8', '593346cf-1688-4b40-95bf-9665c7025c04', 'es', 'Lanzamiento luchador battle ropes', 'Simula movimiento de lanzamiento de luchador con las cuerdas. Movimiento diagonal explosivo de arriba hacia abajo alternando lados. Involucra rotación del core. Mantén postura atlética baja.'),
('659d62de-070d-46d0-bafb-c8c612d784eb', '5952eaec-0bf6-4e8c-8f03-89a6cfffe485', 'es', 'Peso muerto rumano kettlebell', 'Baja pesa rusa pegada a piernas. Objetivo: isquios. Cue: espalda plana. Error: doblar rodillas.'),
('b25a1a98-e257-4c0b-945a-d5093241055e', '5964076c-94ac-4048-8d36-a1104702805b', 'en', 'Single Arm Barbell Standing Rollout', 'From a standing position, hinge and roll the barbell forward with a single hand until the body is extended, then return under control.'),
('cd9c9178-0b9f-4caf-9ac1-57055a0aabb2', '5964076c-94ac-4048-8d36-a1104702805b', 'es', 'Rollout de pie con barra a una mano', 'Desde posicion de pie, inclinate y desplaza la barra hacia adelante con una sola mano hasta extender el cuerpo, volviendo luego bajo control.'),
('54e563a0-4794-46f9-ad9c-86b734314c3a', '596d1fd9-0ef0-4f81-b569-12c457dcac06', 'en', 'Cable Squat', 'Using a low anchored cable or a specific machine, perform squats with cable resistance. It provides a different resistance curve than free weights. Useful for rehabilitation or as a training variation.'),
('22607090-5ed1-47f4-a5d5-3e19f84a483e', '596d1fd9-0ef0-4f81-b569-12c457dcac06', 'es', 'Sentadilla cable', 'Con un cable anclado bajo o usando una máquina específica, realiza sentadillas con la resistencia del cable. Proporciona una curva de resistencia diferente a las pesas libres. Útil para rehabilitación o como variación en el entrenamiento.'),
('5e081412-0d37-46c9-a92a-081ced5bbaa9', '597228bb-154f-451a-ba22-9a74fd234447', 'en', 'Lateral Jump over Obstacle', 'Jump with feet together sideways over a hurdle or low box. Improves coordination and power in the frontal plane. Cue: knees up to clear the object. Common error: landing with stiff legs.'),
('09a0b9ae-50b0-4fa8-97cc-f857c794d27f', '597228bb-154f-451a-ba22-9a74fd234447', 'es', 'Salto lateral sobre obstáculo', 'Salta con pies juntos de lado sobre una valla o cajón bajo. Mejora la coordinación y potencia en el plano frontal. Cue: rodillas arriba para superar el objeto. Error común: aterrizar con las piernas rígidas.'),
('2b4ebbe7-8c90-4b70-bd79-5063b68d7bd4', '598cee37-48e6-4d3c-a527-c56c78b13918', 'en', 'Box Jump with Unilateral Landing', 'Jump onto the box with two feet but exit by landing and stabilizing on only one leg. Braking control. Aligned knee. Avoid lateral swaying.'),
('b8cd187f-8db3-4358-b71d-7813c43907e3', '598cee37-48e6-4d3c-a527-c56c78b13918', 'es', 'Salto a cajón con salida unilateral', 'Salta al cajón con dos pies pero sal de él aterrizando y estabilizando sobre una sola pierna. Control de frenado. Rodilla alineada. Evita el balanceo lateral.'),
('7fc13a5d-9ea0-49c6-aa16-9e0b91c0a4b5', '59a92b98-f3a0-45dc-b656-a76cb115b63c', 'en', 'Battle Rope Feet Elevated Russian Twist', 'Seated with feet in the air, slam the ends of the battle ropes alternately to each side of the torso.'),
('10b3a9fc-6b5f-443d-9c41-4e5088058fdb', '59a92b98-f3a0-45dc-b656-a76cb115b63c', 'es', 'Russian Twist con pies elevados y cuerdas de batalla', 'Sentado con pies en el aire, golpea los extremos de las cuerdas de batalla alternativamente a cada lado del torso.'),
('bf11a722-a8da-439c-96f1-9348f9417030', '59b036bf-6734-4c4b-b3e8-0f1ee39f19b8', 'es', 'Puente de glúteo con mancuerna', 'Eleva cadera con una mancuerna apoyada en la pelvis. Objetivo: glúteo mayor. Cues: aprieta arriba 2 segundos. Error común: arquear lumbar.'),
('8fd57e18-1ad5-42f7-b32c-ba88d426d370', '59bf043b-894d-4fca-a27d-33cd7aa1d2a4', 'en', 'Parallette Straddle Planche', 'Maintain the body horizontal supported only by the hands on the parallettes with legs open in a V-shape to reduce leverage.'),
('18512fd0-1788-4782-8d3f-087a9531d625', '59bf043b-894d-4fca-a27d-33cd7aa1d2a4', 'es', 'Plancha paralela a horcajadas', 'Manten el cuerpo horizontal apoyado solo en las manos en las paralelas con las piernas abiertas en V para reducir la palanca.'),
('6cc130b8-dedb-42a3-a1bc-7ebcc665dc53', '59c33c9d-323a-4c7b-8e00-4a433dddbd96', 'es', 'Zancada caminando Overhead con barra', 'Camina realizando zancadas mientras sostienes una barra bloqueada sobre la cabeza con un agarre ancho, exigiendo estabilidad total del core.'),
('783a855a-b366-4fa2-b91b-fc2b563a527c', '59c656c3-a799-43ad-8c62-516bafc46e86', 'en', 'Double Kettlebell Bottoms Up Seesaw Floor Press', 'Lying on the floor, press the upside-down kettlebells alternately, which limits elbow travel and maximizes triceps tension.'),
('85895435-3808-424a-9517-1b411d472c32', '59c656c3-a799-43ad-8c62-516bafc46e86', 'es', 'Floor Press Seesaw con Kettlebell doble Bottoms Up', 'Tumbado en el suelo, presiona las Kettlebells invertidas de forma alterna, lo que limita el recorrido del codo y maximiza la tensión del tríceps.'),
('32a03477-7e48-49ea-bb97-6a683e9b143c', '59e9f6d5-fe7a-4231-8912-bd3d81cd5317', 'en', 'Wide Grip Barbell Bicep Curl', 'Flex bar with hands wide for short head focus. Cue: full range. Error: not straightening arms at the bottom.'),
('717078c6-6a86-4113-ba32-3f53b23289b4', '59e9f6d5-fe7a-4231-8912-bd3d81cd5317', 'es', 'Curl bíceps barra agarre ancho', 'Flexiona barra manos separadas para cabeza corta. Cue: rango completo. Error: no estirar brazos abajo.'),
('4dd634df-d875-4ed9-b325-421c7dfb009b', '59ed1b89-4612-4bb1-9b56-8090248f3fa3', 'en', 'Low Pulley Pectoral Flyes', 'From low pulleys, bring hands together in front of the upper chest. Objective: clavicular head of the pectoral. Cue: elbows slightly bent. Common error: shrugging shoulders upward.'),
('637d3516-9935-4db4-b44d-55250720fc0f', '59ed1b89-4612-4bb1-9b56-8090248f3fa3', 'es', 'Cruces de polea baja pectoral', 'Desde poleas bajas, junta las manos frente a la parte superior del pecho. Objetivo: haz clavicular del pectoral. Cue: codos semiflexionados. Error común: encoger los hombros hacia arriba.'),
('f837b3fc-0674-4f28-9106-9cf7cefea3b0', '59ff6ea7-2116-41ca-9fce-57f1dcce61c4', 'en', 'Side Shuffle Burpee', 'Perform a burpee and take a quick side step before the next one. Increases agility. Cue: short and fast steps. Common error: dragging feet.'),
('f319361f-4ff1-4035-83a6-0a9d3590df3c', '59ff6ea7-2116-41ca-9fce-57f1dcce61c4', 'es', 'Burpee desplazamiento lateral', 'Realiza un burpee y da un paso lateral rápido antes del siguiente. Aumenta la agilidad. Cue: pasos cortos y veloces. Error común: arrastrar los pies.'),
('7aeee464-dbb6-4d15-9ee4-cc5828329bed', '5a05c9a6-70fa-426a-b400-f868fc6705d8', 'en', 'Superband Pull Through', 'Hold the band between your legs and extend the hips forcefully by squeezing the glutes, mimicking a deadlift motion.'),
('38347062-8ba7-44d8-b1bc-6930aab8a7bf', '5a05c9a6-70fa-426a-b400-f868fc6705d8', 'es', 'Pull Through con banda elástica', 'Sujeta la banda entre las piernas y extiende la cadera con fuerza apretando los glúteos, emulando el movimiento de un peso muerto.'),
('7c928f95-3842-4b3e-b0e5-55ec5cb90529', '5a0d509e-e580-473e-ab2c-758f83a76b92', 'en', 'Single Arm Kettlebell Side Swing', 'Swing the kettlebell side to side in front of your body, intensely working on core rotation and stability.'),
('3ee83c2e-63a1-4c8a-a45b-dcc88041f357', '5a0d509e-e580-473e-ab2c-758f83a76b92', 'es', 'Side Swing con Kettlebell a una mano', 'Balancea la pesa rusa de lado a lado por delante del cuerpo, trabajando de forma intensa la rotacion y estabilidad del core.'),
('5d2f5448-faaa-4be0-b4d3-ada2a2d57225', '5a12251a-f5f1-40bf-bc3d-41ae46db2821', 'en', 'Low Pulley Crossed Adduction', 'Cross the leg in front on the pulley. Cue: straight back. Error: bending the knee.'),
('89719238-0685-4b39-b056-3b914d77a690', '5a12251a-f5f1-40bf-bc3d-41ae46db2821', 'es', 'Abductores polea baja cruzados aducción', 'Cruza pierna por delante en polea. Cue: espalda recta. Error: doblar rodilla.'),
('a15386fe-c699-440c-96dd-8495012da5af', '5a44d5e6-8670-41f4-bbed-5ca7b7d598f6', 'en', 'Alternating Single Arm Dumbbell Squat Snatch', 'Execute single-arm Squat Snatches, alternating hands on the ground after each complete repetition.'),
('53cd783e-8911-4964-ae46-0d9fa9c0311e', '5a44d5e6-8670-41f4-bbed-5ca7b7d598f6', 'es', 'Squat Snatch alterno a una mano con mancuerna', 'Ejecuta sentadillas Snatch con un solo brazo, alternando de mano en el suelo despues de cada repeticion completa.'),
('790fd890-28d9-44fe-9fb5-db53e1bd70eb', '5a704174-049b-44ff-b944-b0ad7a25152e', 'en', 'TRX Bicep Curl', 'Leaned back, flex elbows bringing hands toward your temples while keeping the body straight. Objective: biceps. Cue: keep elbows high and fixed. Error: dropping hips during the movement.'),
('4dc1c86f-6e4b-419e-baa6-53c39beaf935', '5a704174-049b-44ff-b944-b0ad7a25152e', 'es', 'Curl de bíceps en TRX', 'Inclinado hacia atrás, flexiona los codos llevando las manos hacia tus sienes mientras mantienes el cuerpo recto. Objetivo: bíceps. Cue: mantén los codos altos y fijos. Error: bajar la cadera durante el movimiento.'),
('53a814ee-f619-4ed8-8555-43cb281ed2a0', '5a9091d8-ddcc-4da2-a8e1-76adac6af9cf', 'en', 'In-and-Out Plyometric Push Up', 'Alternate between diamond push-up and wide push-up with each explosive jump. Cue: active hands. Common error: lack of push to switch positions.'),
('6b58eff5-70ef-4082-b9a9-0f84dd7f5c7c', '5a9091d8-ddcc-4da2-a8e1-76adac6af9cf', 'es', 'Flexión pliométrica manos juntas-separadas', 'Alterna entre flexión diamante y flexión abierta en cada salto explosivo. Cue: manos activas. Error común: falta de empuje para cambiar la posición.'),
('430975d9-89d1-4dd8-9216-d6f35b749c91', '5a915278-4f4d-4cd2-a659-6ca66d631ad3', 'es', 'Plancha con toques de pie', 'Desde plancha frontal, eleva la cadera y toca el pie opuesto con la mano, alternando. Objetivo: estabilidad de core y flexibilidad dinámica. Cues: exhala al subir. Error común: no volver a la posición de plancha recta.'),
('470a9a62-c641-4a73-9598-66997822f697', '5a958f9e-1042-4bd5-bbb9-4738cf071a9a', 'en', 'Heels-Elevated Squat', 'Squat with heels elevated on plates or wedges. Increases quadriceps emphasis and allows for greater depth if ankle mobility is limited. Popular among bodybuilders. Does not replace mobility work.'),
('7526dd1e-c516-4b93-bbcd-b8694e638265', '5a958f9e-1042-4bd5-bbb9-4738cf071a9a', 'es', 'Sentadilla talones elevados', 'Sentadilla con talones elevados en discos o cuñas. Aumenta el énfasis en cuádriceps y permite mayor profundidad si hay limitación de movilidad en tobillos. Popular entre culturistas. No sustituye trabajo de movilidad.'),
('20bfc759-9b11-445c-bdc2-d7ddb3121930', '5b681ef2-d5ea-47d0-ae97-a7e9c38d79aa', 'en', 'Kneeling Plyometric Push Up', 'Beginner version: push from the knees so hands leave the ground. Objective: base power. Cue: maintain straight hip-shoulder line. Common error: letting the pelvis drop.'),
('06ee7802-d72a-4e12-b9a3-58785828ea72', '5b681ef2-d5ea-47d0-ae97-a7e9c38d79aa', 'es', 'Flexión pliométrica desde rodillas', 'Iniciación: empuja desde las rodillas para que las manos despeguen. Objetivo: potencia base. Cue: mantén línea recta cadera-hombro. Error común: dejar caer la pelvis.'),
('6b8aa736-610c-474b-b652-33405c0f473c', '5b7161c3-e08b-442d-abf6-51679920c36e', 'es', 'Zancada inversa Overhead con Slider y Kettlebell Bottoms Up', 'Sostén dos Kettlebells invertidas sobre la cabeza y desliza un pie hacia atrás en un slider para realizar una zancada inversa de alta inestabilidad.'),
('9f3795a1-7a02-4293-b8d2-e4e658239133', '5b76c675-63c9-4dbf-90ad-ec91168eb2be', 'en', 'Alternating Single Arm Kettlebell Snatch', 'Drive the kettlebell from the floor to overhead in a single explosive motion, alternating hands each repetition.'),
('f7ccdfa7-dafd-4598-a958-bddeaf626059', '5b76c675-63c9-4dbf-90ad-ec91168eb2be', 'es', 'Snatch alterno con Kettlebell a una mano', 'Lleva la Kettlebell desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, alternando la mano en cada repeticion.'),
('f4896faf-9754-4a68-b326-5051b9e49044', '5b9c740a-df5e-46e3-9e6d-030034a3b060', 'en', 'Pulley Rope Triceps Pushdown', 'Pull the rope down flaring the ends. Cue: shoulders low. Error: elbows forward.'),
('264f21d9-f2b2-4fab-be7e-49f33e56cd8b', '5b9c740a-df5e-46e3-9e6d-030034a3b060', 'es', 'Tríceps pushdown con cuerda polea', 'Tira de cuerda abajo abriendo extremos. Cue: hombros bajos. Error: adelantar codos.'),
('e4344c87-c9f3-492f-88dc-e54eae1161af', '5c37d7f1-87e8-4727-8ada-3b6a24b4b0e2', 'es', 'Plancha lateral dinámica', 'En posición de plancha lateral, baja la cadera al suelo y elévala de nuevo repetidamente. Objetivo: oblicuos y estabilidad. Cue: cuerpo alineado como un bloque. Error: dejar que el hombro se hunda.'),
('a3e25b80-1820-4a7d-b6da-c3b116bfb5b4', '5ca98bd4-e7fb-48ef-8d6c-24fc6b1e9dc2', 'en', 'Bent Knee Reverse Hyperextension on Fitball', 'Support torso on the Fitball and, with knees bent, raise legs toward the ceiling contracting glutes and lumbar area.'),
('330a7b2c-b18c-476d-b225-152629ef818a', '5ca98bd4-e7fb-48ef-8d6c-24fc6b1e9dc2', 'es', 'Hiperextensión inversa con rodilla doblada sobre Fitball', 'Apoya el torso sobre el Fitball y, con las rodillas dobladas, eleva las piernas hacia el techo contrayendo los gluteos y la zona lumbar.'),
('267213d9-a2ea-4644-a357-84024350148f', '5cab2d89-a9f0-4ea4-9c53-e628214a1e93', 'en', 'Double Kettlebell Bottoms Up Clean to Overhead Press', 'Clean and press two upside-down kettlebells simultaneously, the ultimate challenge for coordination, grip, and shoulder strength.'),
('1f35d5b1-9961-47d5-9f2f-0aa919a0b43e', '5cab2d89-a9f0-4ea4-9c53-e628214a1e93', 'es', 'Clean a Press Overhead con Kettlebell doble Bottoms Up', 'Carga y presiona simultaneamente dos Kettlebells invertidas, el reto definitivo de coordinacion, agarre y fuerza de hombros.'),
('e03811f4-c942-47ce-b273-ee059e61b52f', '5cd3a76f-615c-4422-975b-fe4f0835e6f9', 'en', 'One-Arm Dumbbell Triceps Extension', 'Raise and lower a dumbbell behind the neck with a single arm. Objective: triceps isolation. Cue: use the other arm to stabilize the elbow. Common error: moving the arm laterally losing tension.'),
('b38ef421-c809-466b-aaa7-8a754ef3b964', '5cd3a76f-615c-4422-975b-fe4f0835e6f9', 'es', 'Extensión de tríceps con mancuerna a una mano', 'Eleva y baja una mancuerna tras la nuca con un solo brazo. Objetivo: aislamiento de tríceps. Cue: usa el otro brazo para estabilizar el codo. Error común: mover el brazo lateralmente perdiendo tensión.'),
('a618aee1-67d4-47a2-b38c-b678fba7cff6', '5ceddd00-76aa-48f7-bb62-ddc9e589b0f7', 'en', 'One-Leg Box Jump', 'Jump onto a box or elevated platform using only one leg. Requires exceptional unilateral power. Start with low heights and progress. Land with the same leg and maintain balance. High risk if technique is not mastered.'),
('2962d43f-4f33-45ee-a3bc-76a1198940be', '5ceddd00-76aa-48f7-bb62-ddc9e589b0f7', 'es', 'Salto cajón una pierna', 'Salto a cajón o plataforma elevada usando solo una pierna. Requiere potencia unilateral excepcional. Comienza con alturas bajas y progresa. Aterriza con la misma pierna y mantén el equilibrio. Alto riesgo si no se domina la técnica.'),
('9d1ab1d1-2fa6-4513-ab23-fb9b76c6892d', '5d2f129d-3eaf-4954-8269-cf5ead81153b', 'en', 'Seated Soleus Raise', 'Perform seated soleus raises. With the knees bent, lift the heels until on the toes and lower under control.'),
('5c89b6d1-883e-4ac8-8a45-c89a7b63dc15', '5d2f129d-3eaf-4954-8269-cf5ead81153b', 'es', 'Sóleo sentado', 'Realiza elevaciones de sóleo sentado. Con las rodillas flexionadas, eleva los talones hasta ponerte de puntillas y baja de forma controlada.'),
('c784f766-9de7-493a-9ba3-ca7ec28ef079', '5d30bf99-52cb-4a9d-9617-7becec6e9c7d', 'en', 'Asymmetrical load', 'Walk or stand with very different weights in each hand. Tremendously challenges core stabilization. The difference can be 2:1 or more. Maintain perfectly vertical posture resisting the lean.'),
('62e85900-5ddd-4bb2-90dd-0ae37014d4c2', '5d30bf99-52cb-4a9d-9617-7becec6e9c7d', 'es', 'Carga asimétrica', 'Camina o permanece de pie con pesos muy diferentes en cada mano. Desafía tremendamente la estabilización del core. La diferencia puede ser 2:1 o más. Mantén postura perfectamente vertical resistiendo la inclinación.'),
('e5d1f51d-4a62-4d58-82fb-6c2fb648f22f', '5d432a93-f240-4577-bae9-2f3c2f1e6f79', 'en', 'Pec Deck (Machine Flyes)', 'Seated, bring the handles together in front of the chest maintaining a slight elbow bend. Cue: squeeze at the center. Error: exaggerating the initial stretch.'),
('54d09766-d29f-4a72-a55b-cbca8347f505', '5d432a93-f240-4577-bae9-2f3c2f1e6f79', 'es', 'Pec Deck (Aperturas máquina)', 'Sentado, junta los agarres frente al pecho manteniendo ligera flexión de codo. Cue: aprieta al centro. Error: exagerar el estiramiento inicial.'),
('9a622a34-e30e-4406-a57c-95779bed0958', '5d47abb6-225d-4dc2-8248-83025c3f52fe', 'en', 'Bodyweight Forearm Plank Alternating Knee to Elbow', 'In a forearm plank position, drive one knee laterally toward the elbow on the same side and return, alternating legs.'),
('43af379c-061a-4aa1-8560-2dc188418097', '5d47abb6-225d-4dc2-8248-83025c3f52fe', 'es', 'Plank de antebrazos con rodilla a codo alterna', 'En posición de plancha sobre antebrazos, lleva una rodilla lateralmente hacia el codo del mismo lado y regresa, alternando piernas.'),
('d4c59227-8102-4427-af55-8171cd003b11', '5d4a65c2-0e4d-4181-8930-403ca55613bf', 'en', 'Cossack Squat', 'Adopt a very wide stance and descend toward one side completely flexing that knee while the opposite leg remains extended. Alternate between both sides in a fluid movement. Improves hip mobility, adductor flexibility, and unilateral leg strength.'),
('9bcb6552-410b-43bd-b2fc-c0d72e3cfb93', '5d4a65c2-0e4d-4181-8930-403ca55613bf', 'es', 'Sentadilla cossack', 'Adopta una postura muy amplia y desciende hacia un lado flexionando completamente esa rodilla mientras la pierna opuesta permanece extendida. Alterna entre ambos lados en un movimiento fluido. Mejora la movilidad de caderas, la flexibilidad de aductores y la fuerza unilateral de las piernas.'),
('533a70c9-45c2-4db9-bd4f-457584ec894b', '5d55aeeb-7e54-41a1-9802-7bb344178037', 'en', 'Slam Ball Russian Twist', 'Sit with knees bent and torso leaned back. Hold the medicine ball and rotate torso from side to side, touching the ball on the floor near your hip.'),
('274a200d-1395-4630-851b-ccba85264946', '5d55aeeb-7e54-41a1-9802-7bb344178037', 'es', 'Russian Twist con balón medicinal', 'Siéntate con las rodillas dobladas y el torso inclinado hacia atrás. Sostén el balón medicinal y gira el torso de lado a lado, tocando el balón en el suelo cerca de tu cadera.'),
('d099f6c9-91f0-421b-9db3-3d37eaafc79b', '5d7b96d7-48c8-4067-a27b-4e2035a2b85f', 'en', 'Bear crawl slam', 'Perform bear crawl dragging the ball, stopping periodically to perform a slam. Combines quadrupedal locomotion with explosive movements. Keep the back flat during the crawl.'),
('21aeb245-e9d4-444d-a90d-a8c6222777a0', '5d7b96d7-48c8-4067-a27b-4e2035a2b85f', 'es', 'Bear crawl slam', 'Realiza bear crawl arrastrando el balón, detente periódicamente para realizar un slam. Combina locomoción en cuadrupedia con movimientos explosivos. Mantén la espalda plana durante el crawl.'),
('f1e419a7-8f5d-42e4-b8ac-d2251da46d1b', '5dbacc42-8c5c-4e73-934d-e11b3886faf0', 'en', 'Seated Kettlebell Halo', 'Seated on the floor, pass the weight around the head. Core stability. Straight back. Do not move the neck.'),
('dd84b667-0dbb-4b3e-ae17-33dd4eb00047', '5dbacc42-8c5c-4e73-934d-e11b3886faf0', 'es', 'Kettlebell Halo sentado', 'Sentado en el suelo, pasa la pesa alrededor de la cabeza. Estabilidad de core. Espalda recta. No muevas el cuello.'),
('c46e6763-1868-43d2-9760-531b63d20572', '5dfd3197-443d-443e-b8c6-1c0b96d67ca5', 'en', 'Plank Shoulder Taps', 'In a plank position, tap the opposite shoulder with the hand without moving the hip. Cue: spread feet for stability. Error: lateral hip swaying.'),
('5834d5a5-f591-45b4-99a4-9764de61381d', '5dfd3197-443d-443e-b8c6-1c0b96d67ca5', 'es', 'Shoulder Taps en plancha', 'En plancha, toca el hombro opuesto con la mano sin mover la cadera. Cue: abre pies para estabilidad. Error: balanceo lateral de cadera.'),
('6a5e568f-ee6c-45b2-983b-ab3eaa4d575e', '5dffdf5c-8f72-40e4-8e13-03d52afab239', 'en', 'Seated Dumbbell Calf Raises', 'Seated with a dumbbell resting on the thighs, raise the heels as high as possible. Objective: soleus. Cue: full range of motion. Error: letting the weight slip from the thighs.'),
('c4c3209c-caba-4efd-b7d2-818eb62f69b5', '5dffdf5c-8f72-40e4-8e13-03d52afab239', 'es', 'Elevación de talones sentado con mancuerna', 'Sentado con una mancuerna apoyada sobre los muslos, eleva los talones lo máximo posible. Objetivo: sóleo. Cue: rango de movimiento completo. Error: dejar que la pesa resbale de los muslos.'),
('c5a2199c-bb22-4fd7-a15e-8af50a440b0b', '5e108061-8675-465a-aa7d-e01c61c629e4', 'en', 'Seated Calf Raises', 'Raise heels with knees flexed. Focuses on the soleus. Cue: full range of motion. Error: bouncing the weight.'),
('ebddbbd4-bd03-4de1-8f9c-f702d32ff2d5', '5e108061-8675-465a-aa7d-e01c61c629e4', 'es', 'Elevación de talones sentado', 'Eleva talones con rodillas flexionadas. Enfoca en el sóleo. Cue: rango completo de movimiento. Error: rebotar el peso.'),
('934ce7e9-ee0c-4cde-8b7a-49030323709c', '5e3f4ba8-d7ad-4388-bded-a63e8fd15f10', 'en', 'Wide Low Pulley Row', 'Pull the wide bar to the sternum while seated. Objective: upper back. Cue: chest out. Error: hunching.'),
('8467640d-44ea-410d-b66a-46e270acc36d', '5e3f4ba8-d7ad-4388-bded-a63e8fd15f10', 'es', 'Remo polea baja ancho', 'Tira barra ancha al esternón sentado. Objetivo: espalda alta. Cue: saca pecho. Error: encorvarse.'),
('35736c37-217e-4e7d-9e4a-ce553c479310', '5e45611f-4cdd-4f29-9289-3b8a24078064', 'en', 'Double Contact Skater Jump', 'Perform a lateral jump and add a small bounce on the spot before jumping to the other side. Impact control. Neutral back. Do not lose verticality.'),
('e1dcc0df-0618-4003-8932-202f27f1270b', '5e45611f-4cdd-4f29-9289-3b8a24078064', 'es', 'Salto de patinador con doble contacto', 'Realiza un salto lateral y añade un pequeño rebote en el sitio antes de saltar al otro lado. Control de impacto. Espalda neutra. No pierdas la verticalidad.'),
('de897d7d-02fe-4e6e-b3f2-c01818d6fff7', '5e845892-3737-4962-88ff-dd48fb5411ba', 'en', 'Bench Dips', 'Place your hands on the edge of a bench with fingers facing forward and feet on the floor. Descend by flexing elbows to 90 degrees keeping the back close to the bench. Push with triceps to return up. You can raise feet on another bench to increase difficulty.'),
('782c3775-0f31-4a9a-9578-a38a8193e099', '5e845892-3737-4962-88ff-dd48fb5411ba', 'es', 'Fondos en banco', 'Coloca las manos en el borde de un banco con los dedos hacia adelante y los pies en el suelo. Desciende flexionando los codos hasta 90 grados manteniendo la espalda cerca del banco. Empuja con los tríceps para volver arriba. Puedes elevar los pies en otro banco para aumentar la dificultad.'),
('67f5569d-7423-4252-ae27-dc1dcb4c586c', '5ea2c067-0015-417f-bbb2-d1b7216cf217', 'es', 'Puente de glúteo unilateral', 'Eleva la cadera manteniendo una pierna estirada en el aire. Fuerza unilateral. Core firme. No arquees la espalda baja.'),
('bb03dfaf-0269-46e7-a2b5-800a30950335', '5eb80ff3-ec06-46b7-8089-77cc121baf06', 'en', 'Pistol Squat', 'Perform a full squat on a single leg while the other is held extended forward. Requires exceptional strength, balance, and flexibility in ankles and hips. Lower controlfully to the lowest possible position and push forcefully back up without losing balance.'),
('1d44cfe2-fdb4-4e5a-829f-07fbfe4dd0b4', '5eb80ff3-ec06-46b7-8089-77cc121baf06', 'es', 'Sentadilla pistol', 'Realiza una sentadilla completa sobre una sola pierna mientras la otra se mantiene extendida al frente. Requiere fuerza excepcional, equilibrio y flexibilidad en tobillos y caderas. Desciende controladamente hasta la posición más baja posible y empuja con fuerza para volver arriba sin perder el equilibrio.'),
('873e7bfa-f275-4a60-b973-161a0e4bec7b', '5ebff291-5314-46eb-afc6-17494f2a4d2c', 'en', 'Cable Quadriceps Extension', 'Seated with ankle strap connected to low pulley, extend the knee to full extension. Similar to the extension machine but with variable cable resistance. Keep the back supported and control the movement in both phases.'),
('ffc06bb3-e166-4af2-9dd5-91f11e0aae3f', '5ebff291-5314-46eb-afc6-17494f2a4d2c', 'es', 'Extensión cuádriceps cable', 'Sentado con tobillera conectada a polea baja, extiende la rodilla hasta la extensión completa. Similar a la máquina de extensiones pero con la resistencia variable del cable. Mantén la espalda apoyada y controla el movimiento en ambas fases.'),
('ce2dd3d9-b5bf-40b0-9912-806612d2e8a3', '5ed15c31-0c53-4638-b7e0-b8339a78e757', 'en', 'Double Dumbbell Tall Kneeling Overhead Press', 'Kneeling on both legs (Tall Kneeling), press both dumbbells overhead while keeping the core and glutes contracted.'),
('178faca6-bd12-446f-8e89-3112fb99c002', '5ed15c31-0c53-4638-b7e0-b8339a78e757', 'es', 'Press Overhead arrodillado con mancuernas', 'De rodillas sobre ambas piernas (Tall Kneeling), presiona ambas mancuernas sobre la cabeza manteniendo el core y gluteos contraidos.'),
('8cd95483-57f8-44d4-8cd5-b2bc951acfc1', '5ee16458-a4df-4fe3-938b-79e9ae01d949', 'en', 'Dumbbell Shoulder Press', 'Push dumbbells overhead from shoulder height. Objective: shoulder strength. Cues: lower to 90 degrees. Common error: clashing weights loudly at the top.'),
('da568daa-22e6-4fab-9016-6584444f52b4', '5ee16458-a4df-4fe3-938b-79e9ae01d949', 'es', 'Press de hombros con mancuernas', 'Empuja las mancuernas sobre la cabeza desde la altura de los hombros. Objetivo: fuerza de hombros. Cues: baja hasta 90 grados. Error común: chocar las pesas ruidosamente arriba.'),
('4269cbfd-65a3-4670-95f9-de2d3d964cf7', '5ef0f729-a1ed-49d6-8539-f47f8391e193', 'en', 'Lateral Star Jump', 'Jump laterally and in the air perform the arm and leg extension in X. Lateral agility. Cue: soft landing on balls of feet. Common error: lack of torso control.'),
('f5768b10-cb85-4d6c-a93e-c3a021839554', '5ef0f729-a1ed-49d6-8539-f47f8391e193', 'es', 'Salto de estrella lateral', 'Salta lateralmente y en el aire realiza la extensión de brazos y piernas en X. Agilidad lateral. Cue: aterrizaje suave con puntas. Error común: falta de control del torso.'),
('d4bf6229-2fcc-4a5f-899b-c3ab20c7f93c', '5ef2677e-7b3f-4937-8487-ef7aea5211f5', 'en', 'Alternating Single Arm Kettlebell Bottoms Up Clean to Overhead Press', 'Perform a clean catching the weight upside down and press overhead, alternating arms each rep with full control.'),
('295fbc23-87b7-43c6-8d8b-e418084d617b', '5ef2677e-7b3f-4937-8487-ef7aea5211f5', 'es', 'Clean a Press Overhead alterno con Kettlebell a una mano Bottoms Up', 'Realiza una cargada recibiendo la pesa invertida y presiona sobre la cabeza, alternando el brazo en cada repeticion con control total.'),
('8a970884-259c-41ab-bc5f-ab2681319110', '5f028f60-ac31-4c61-82a1-c85b6238d859', 'en', 'T-Renegade Row', 'Renegade row followed by a rotation to a T position (side plank with arm raised). Combines pulling with rotation and stabilization. Alternate sides. Keep hips stable during the entire complex movement.'),
('57f420f6-909a-4f4b-8905-9e1a2c9d1188', '5f028f60-ac31-4c61-82a1-c85b6238d859', 'es', 'Renegade row en T', 'Renegade row seguido de rotación a posición T (plancha lateral con brazo elevado). Combina tracción con rotación y estabilización. Alterna lados. Mantén caderas estables durante todo el movimiento complejo.'),
('f19efead-d3de-4905-8a8d-88ffd19d6fc2', '5f2f06b3-25a4-45af-96e0-bdfc2216002d', 'en', 'Band-Assisted Pistol Squat', 'Perform a pistol squat using an elastic band as support to reduce the load and improve balance during the movement.'),
('182bac19-62bf-4d70-a795-699a95e3c853', '5f2f06b3-25a4-45af-96e0-bdfc2216002d', 'es', 'Sentadilla Pistola asistida con banda', 'Realiza una sentadilla pistola usando una banda elástica como soporte para reducir la carga y mejorar el equilibrio durante el movimiento.'),
('582dad16-931d-4ab9-aac4-01fac2a4725d', '5f70bad7-015e-4f58-9ce5-130a83e9ca50', 'en', 'Unilateral Bench Supported Row', 'Chest on the bench, row with one dumbbell. Cue: full stretch at the bottom. Error: rotating the torso.'),
('5c5fb195-4a67-401a-b726-4dfcd29b102f', '5f70bad7-015e-4f58-9ce5-130a83e9ca50', 'es', 'Remo apoyado banco unilateral', 'Pecho en banco, rema con una mancuerna. Cue: estira total abajo. Error: rotar torso.'),
('c5d0f643-0fa4-4827-a8f6-168aee42df06', '5f76ebc3-eb9c-463b-802c-98c40a068259', 'en', 'Open Slider Mountain Climber', 'In a plank position with sliders, slide the right foot to the outside of the right hand, return and repeat with the left side.'),
('551f92db-3620-4a98-92c4-43a4a673c6a8', '5f76ebc3-eb9c-463b-802c-98c40a068259', 'es', 'Mountain Climber abierto con Slider', 'En posición de plancha con sliders, desliza el pie derecho hacia el exterior de la mano derecha, regresa y repite con el lado izquierdo.'),
('a474dba7-1ff4-42f5-9680-ef8fdfe624d0', '5fae2b37-ff70-43a6-aaf2-85d1d144184e', 'en', 'Box Jump with Side Steps', 'Jump onto the box, lower with quick side steps and repeat on the other side. Agility. Cue: fast feet on the floor. Common error: jumping backward noisily.'),
('9cf520de-0500-4a60-94c2-efb2caeb2e27', '5fae2b37-ff70-43a6-aaf2-85d1d144184e', 'es', 'Salto cajón pasos laterales', 'Salta al cajón, baja con pasos laterales rápidos y repite del otro lado. Agilidad. Cue: pies veloces en el suelo. Error común: saltar hacia atrás ruidosamente.'),
('6b012f95-760e-40c9-ab2e-9e60e9fefff3', '603f33ba-77fc-4488-a30c-6e85d4a903e4', 'en', 'Medicine Ball Clean', 'Bring the ball from the floor to shoulders in an explosive movement. Simulates Olympic clean. Gripping the ball is more challenging than a bar. Use legs to generate power, not just arms.'),
('e22dd93e-adbd-4125-a666-04dffa82ee95', '603f33ba-77fc-4488-a30c-6e85d4a903e4', 'es', 'Cargada balón medicinal', 'Lleva el balón del suelo a los hombros en movimiento explosivo. Simula cargada olímpica. El agarre del balón es más desafiante que una barra. Usa las piernas para generar potencia, no solo los brazos.'),
('90a3994c-0c78-4fc1-8be3-d8f9f8976982', '60560dc8-3e70-433b-918e-8dddfcfa8dbe', 'en', 'Alternating Double Bottoms Up Kettlebell Floor Press', 'Perform floor press alternating arms with inverted kettlebells, continuously challenging load balance.'),
('9a0109a7-4103-4167-9db7-2d8856c3edbf', '60560dc8-3e70-433b-918e-8dddfcfa8dbe', 'es', 'Floor Press alterno con Kettlebell doble Bottoms Up', 'Realiza press de suelo alternando brazos con Kettlebells invertidas, desafiando continuamente el equilibrio de la carga.'),
('82080254-abb4-443d-b64e-ce76b90e8dea', '605714c3-f5ef-49d5-a953-78d705ec191f', 'es', 'Press banca agarre inverso', 'Palmas hacia ti en press de banca. Objetivo: pecho superior y tríceps. Cue: agarre seguro. Error: usar demasiado peso.'),
('6d51a14b-23f3-4599-b684-a8abf1d67b66', '605a3e3e-eb8d-4332-b991-87674f79e480', 'en', 'Half Lay Back Lever on Rings', 'Maintain the body parallel to the floor with back and hips straight, but with knees flexed at 90 degrees.'),
('bf54f8d3-34c6-4869-9ce2-2d21bb3cac9c', '605a3e3e-eb8d-4332-b991-87674f79e480', 'es', 'Half Lay Back Lever en anillas', 'Mantén el cuerpo paralelo al suelo con la espalda y caderas rectas, pero con las rodillas flexionadas a 90 grados.'),
('13cdaa5c-18e4-46ad-a5b4-67cf8968ee07', '6060a4f9-faec-4b4b-8c2e-661727c84218', 'en', 'Alternating Dumbbell Bench Press', 'Lying on a flat bench, keep one dumbbell up while lowering the other toward the chest. Alternate arms. Objective: core stability and unilateral pectoral strength. Cue: keep the core very firm to prevent the body from rotating. Common error: letting the waiting arm descend due to fatigue.'),
('f151eaa9-7877-45ef-b43d-ff6e766d92cb', '6060a4f9-faec-4b4b-8c2e-661727c84218', 'es', 'Press de banca con mancuernas alterno', 'Tumbado en banco plano, mantén una mancuerna arriba mientras bajas la otra hacia el pecho. Alterna brazos. Objetivo: estabilidad del core y fuerza pectoral unilateral. Cue: mantén el core muy firme para evitar que el cuerpo rote. Error común: dejar que el brazo en espera descienda por fatiga.'),
('7f097228-7510-4040-9125-d6f01fe92f4d', '6075955a-d0d7-4bda-9b5b-d60d53a033e7', 'en', 'Double Kettlebell Front Rack Alternating Cossack Squat', 'With kettlebells in rack position, perform a deep lateral squat to one side while keeping the other leg straight, and alternate.'),
('e2fe61c1-8c65-40f4-a960-01550bab78f6', '6075955a-d0d7-4bda-9b5b-d60d53a033e7', 'es', 'Sentadilla Cosaca alterna Front Rack con Kettlebell doble', 'Con Kettlebells en posición rack, realiza una sentadilla lateral profunda hacia un lado manteniendo la otra pierna estirada, y alterna.'),
('20fb0b95-53b8-4f30-8ff6-b4bd3e779533', '607f6bba-a07a-4ed0-b7dc-25988ef241ac', 'en', 'Side-Lying Hip Abduction', 'Lying on your side, lift the upper leg without rotating the pelvis. Objective: isolation of the gluteus medius. Cue: toes pointing forward. Common error: turning the toes toward the ceiling.'),
('79dc03a0-6cd1-4206-b39c-13e721cb0123', '607f6bba-a07a-4ed0-b7dc-25988ef241ac', 'es', 'Abducción de cadera tumbado de lado', 'Tumbado lateralmente, eleva la pierna superior sin rotar la pelvis. Objetivo: aislamiento del glúteo medio. Cue: punta del pie mirando al frente. Error común: girar la punta del pie hacia el techo.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('db67652a-3d94-4139-acb6-e476ec46b81f', '6087612f-58d6-4c94-a0c0-c7b32b859a07', 'en', 'Decline Barbell Press', 'Lower the bar to the lower pectoral on a decline bench. Objective: lower chest. Cue: feet secured. Error: lowering to the neck.'),
('f8e08829-e528-495e-8c8e-e9648299c6bb', '6087612f-58d6-4c94-a0c0-c7b32b859a07', 'es', 'Press declinado con barra', 'Baja la barra al pectoral inferior en banco declinado. Objetivo: pecho inferior. Cue: pies sujetos. Error: bajar al cuello.'),
('d5e942b5-043b-4947-9f51-524aa16800ca', '608ad231-ea17-4c4b-9a75-788fc9dcae3a', 'en', 'Battle Ropes Outer Circles', 'Perform outward circles with the ropes simultaneously. Focus on shoulders and stability. Feet firm. Do not cave in the chest.'),
('222ccc82-4422-4c93-b6c8-f59c2c2973bc', '608ad231-ea17-4c4b-9a75-788fc9dcae3a', 'es', 'Battle Ropes Círculos exteriores', 'Realiza círculos hacia afuera con las cuerdas de forma simultánea. Enfoque en hombros y estabilidad. Pies firmes. No cierres el pecho.'),
('31ee22eb-7616-4079-a773-86cc012dfd42', '6090ad63-1847-4a5e-9749-44ec4261034b', 'en', 'Reverse Lunges', 'Step back and lower the back knee. More stable than the front lunge. Cue: weight on the front heel. Error: tilting the torso too far forward.'),
('079d4140-e8ae-49dc-94f5-48057f29ef32', '6090ad63-1847-4a5e-9749-44ec4261034b', 'es', 'Zancadas traseras', 'Da un paso atrás y baja la rodilla trasera. Más estable que la zancada frontal. Cue: peso en el talón delantero. Error: inclinar el torso demasiado adelante.'),
('184fe88b-354e-4af8-9125-fcacbd3901c9', '60ed860c-19c0-4677-9b31-0edbb71d73c8', 'en', 'One-Arm Bottoms Up Kettlebell Floor Press', 'Press a single inverted kettlebell from the floor, isolating work on one side of the chest and maximizing shoulder control.'),
('ac351047-c8e7-4e09-9146-02cd7ac4316a', '60ed860c-19c0-4677-9b31-0edbb71d73c8', 'es', 'Floor Press a una mano con Kettlebell Bottoms Up', 'Presiona una sola pesa rusa invertida desde el suelo, aislando el trabajo en un lado del pecho y maximizando el control del hombro.'),
('4360fbbf-e44a-400c-a910-6ed0c155dbad', '60f66581-c622-4c61-b0cb-fed87ef290c5', 'en', 'Kneeling One-Arm Lat Pulldown', 'Kneel in front of a high pulley. Perform a vertical pulldown with a single arm, keeping the torso stable and vertical.'),
('62739523-a687-4b9b-ab9f-5ee236bf4d66', '60f66581-c622-4c61-b0cb-fed87ef290c5', 'es', 'Jalón al pecho a una mano de rodillas', 'Arrodíllate frente a una polea alta. Realiza un jalón vertical con un solo brazo, manteniendo el torso estable y vertical.'),
('eba2e753-f2b9-4828-bacc-2bcf14060bb3', '6111c4be-8b02-4f2b-a734-01f74d4c51f4', 'en', 'Cable Pull Through', 'Back to the low pulley, grab the rope between your legs. Push hips back and then extend forcefully using the glutes.'),
('03a3b462-1b99-4b47-8874-74bd18cd6135', '6111c4be-8b02-4f2b-a734-01f74d4c51f4', 'es', 'Cable Pull Through', 'De espaldas a la polea baja, agarra la cuerda entre las piernas. Empuja la cadera hacia atrás y luego extiende con fuerza usando los glúteos.'),
('024a176c-8e60-4b8e-afce-e83fb0abdf6f', '611f6548-b1f1-4d38-add6-8ee93c0caa44', 'en', 'Rhythmic Flutter Kicks', 'Move legs up and down alternately a few centimeters from the floor. Objective: lower abdominal endurance. Cue: lumbar area glued to the floor. Common error: lifting the lower back off the floor.'),
('9034feec-5a00-4b80-8da2-aef2c3b02dcf', '611f6548-b1f1-4d38-add6-8ee93c0caa44', 'es', 'Flutter kicks rítmicos', 'Mueve las piernas arriba y abajo alternadamente a pocos centímetros del suelo. Objetivo: resistencia abdominal inferior. Cue: zona lumbar pegada al suelo. Error común: despegar la espalda baja del suelo.'),
('ca654757-a0b2-4ab0-9069-a27c31d74dd4', '612dcc45-0d3f-4796-81fd-851aee53a355', 'en', 'Band Kickbacks', 'On all fours with the band around one foot and anchored under the hands, extend the leg back and up against the resistance. Keep the back neutral and squeeze the glute at the top. Avoid excessively arching the lower back.'),
('0080acdb-a214-477e-ac7b-d8bdd2afa29d', '612dcc45-0d3f-4796-81fd-851aee53a355', 'es', 'Kickbacks con banda', 'En cuadrupedia con la banda alrededor de un pie y anclada bajo las manos, extiende la pierna hacia atrás y arriba contra la resistencia. Mantén la espalda neutra y contrae el glúteo en la parte superior. Evita arquear excesivamente la espalda baja.'),
('6aba751a-8b68-4eaf-b837-7e98d61cb254', '612e8919-74b5-4d83-9b46-fba0db1683fe', 'en', 'Dead bug', 'Lie on your back with arms extended toward the ceiling and knees bent at 90 degrees. Slowly extend the right arm backward while extending the left leg without touching the floor. Return to start and alternate. Keep the lower back glued to the floor throughout the movement.'),
('f8dcb8c7-01cf-4d05-a9d9-2e1e6568fc5a', '612e8919-74b5-4d83-9b46-fba0db1683fe', 'es', 'Dead bug', 'Túmbate boca arriba con brazos extendidos hacia el techo y rodillas flexionadas a 90 grados. Lentamente extiende el brazo derecho hacia atrás mientras extiendes la pierna izquierda sin tocar el suelo. Vuelve al inicio y alterna. Mantén la espalda baja pegada al suelo durante todo el movimiento.'),
('e254fc3d-3fb0-4f1a-915e-8f2984537f94', '614da850-b822-49f1-8c4c-a324b7a4b69d', 'es', 'Zancada inversa Front Rack con Slider y Kettlebell doble', 'Sostén dos pesas rusas en posición de Front Rack (pecho). Desliza un pie hacia atrás usando un slider para realizar una zancada inversa controlada.'),
('99810e56-3dce-467b-b379-7b23a61286cd', '615f5b9c-00a6-4169-b95e-34d53183ef4e', 'en', 'Seated Dumbbell Rear Delt Flyes', 'Seated leaning forward, lift weights laterally for the upper back. Objective: rear deltoid. Cue: elbows outward. Common error: swinging the torso for momentum.'),
('3f002386-850b-4069-93b9-c4934d451144', '615f5b9c-00a6-4169-b95e-34d53183ef4e', 'es', 'Pájaros sentado con mancuernas', 'Sentado inclinado adelante, eleva las pesas lateralmente para la espalda alta. Objetivo: deltoides posterior. Cue: codos hacia afuera. Error común: balancear el tronco para dar impulso.'),
('36dca93d-0fb8-43eb-8096-b18a3c7181ef', '61800ff7-c4f2-40dc-84e2-affde813deb0', 'en', 'Chest-Supported Machine Row', 'Perform a chest-supported machine row. Pull the handles toward the torso by squeezing the shoulder blades together and control the return without losing chest support.'),
('1e043460-f25d-4906-a66d-8bb34ce3c273', '61800ff7-c4f2-40dc-84e2-affde813deb0', 'es', 'Remo pecho apoyado máquina', 'Realiza un remo con el pecho apoyado en máquina. Tira de los agarres hacia el torso juntando las escápulas y controla la vuelta sin perder el apoyo del pecho.'),
('047e1a5a-7683-4fdb-bb30-bd0f469b8745', '6196c7f4-82da-49e8-a87a-d637a93c89fa', 'en', 'Kettlebell Alternating Halo to Horn Grip Bottoms Up Squat', 'Perform a halo around the head and finish in a deep squat while holding the kettlebell upside down by the horns.'),
('b3ab91da-9610-4b63-bd9b-c0c66f5c1ef6', '6196c7f4-82da-49e8-a87a-d637a93c89fa', 'es', 'Halo alterno a Sentadilla Bottoms Up con Kettlebell', 'Realiza un halo alrededor de la cabeza y termina en una sentadilla profunda sosteniendo la Kettlebell invertida por los cuernos.'),
('c2dae31c-dd14-4844-abe4-94fc0adf3fac', '61bdc9d1-e0e6-4e02-8be0-3716a92930df', 'en', 'Incline Bench Prone Y-Raise with Dumbbells', 'Lie face down on an incline bench. Lift arms in a Y shape to work the lower trapezius and shoulders.'),
('9beedc7d-95a6-4747-bfc3-0939ca575976', '61bdc9d1-e0e6-4e02-8be0-3716a92930df', 'es', 'Elevación Y prono en banco inclinado con mancuernas', 'Acuéstate boca abajo en un banco inclinado. Levanta los brazos en forma de Y para trabajar el trapecio inferior y hombros.'),
('cde118fb-4030-429f-8883-504d2ddf98ed', '61e7018f-6d7c-4759-ad52-26dd19dde72b', 'en', 'Cable Chest Pulldown', 'Seated at the pulldown machine, grab the bar with hands wider than shoulders. Pull the bar toward the upper chest while leaning slightly back. Control the ascent by resisting the weight. Excellent for beginners who cannot do pull-ups.'),
('a2dbd0c1-b333-4dcf-a620-ae742e0409e2', '61e7018f-6d7c-4759-ad52-26dd19dde72b', 'es', 'Jalón pecho cable', 'Sentado en la máquina de jalón, agarra la barra con las manos más separadas que los hombros. Tira de la barra hacia el pecho superior inclinándote ligeramente hacia atrás. Controla el ascenso resistiendo el peso. Excelente para principiantes que no pueden hacer dominadas.'),
('83cc1f84-d9dd-4137-9e43-4061b86d85e7', '62548205-08ea-4f10-bcff-1d20e8866ba9', 'en', 'Ring Side Plank Reach Through', 'In a side plank position with feet in the rings, reach your free arm under your torso by rotating at the waist and return to vertical.'),
('a4b17097-8808-4f85-8779-3bed7ad9410f', '62548205-08ea-4f10-bcff-1d20e8866ba9', 'es', 'Side Plank con rotación en anillas', 'En posición de plancha lateral con los pies en las anillas, lleva el brazo libre por debajo del torso rotando la cintura y vuelve a la vertical.'),
('3d364a3d-34b1-4bce-b44c-c5f559b4c0fd', '626bb054-927d-46ef-a744-564b2e2d894b', 'en', 'Machine Abdominal Crunch', 'Seated or lying down depending on the design, flex the torso against resistance. The machine provides progressive resistance unlike traditional crunches. Avoid pulling with your arms and focus on abdominal contraction.'),
('85139019-ce71-4031-a83c-eb9fa94fac51', '626bb054-927d-46ef-a744-564b2e2d894b', 'es', 'Abdominal crunch máquina', 'Sentado o tumbado según el diseño, flexiona el tronco contra la resistencia. La máquina proporciona resistencia progresiva a diferencia de los crunches tradicionales. Evita tirar con los brazos y enfócate en la contracción abdominal.'),
('1ad2de5d-2004-448c-8b66-d173231ffb1b', '627a44ad-c66b-48e6-bb49-8e99a97a7fbb', 'en', 'Landmine Standing Oblique Twist', 'Standing, hold the end of the bar with both hands and rotate it laterally from side to side tracing an arc, engaging the obliques.'),
('1b31ef9d-5062-48e8-a235-978f37218588', '627a44ad-c66b-48e6-bb49-8e99a97a7fbb', 'es', 'Giro oblicuo de pie en Landmine', 'De pie, sujeta el extremo de la barra con ambas manos y rótala lateralmente de un lado a otro trazando un arco, activando los oblicuos.'),
('a3b2a36c-d986-4445-bd0a-f705d921377a', '629d3c49-f564-4967-b136-2b7dd79cfbf7', 'en', 'Rings Turned Out L-Sit', 'Perform an L-Sit on the rings while keeping the palms facing forward, which significantly increases difficulty and stability.'),
('cb939eff-abb9-4ffd-8736-f634104baf93', '629d3c49-f564-4967-b136-2b7dd79cfbf7', 'es', 'L-Sit con anillas giradas', 'Realiza un L-Sit en las anillas manteniendo las palmas mirando hacia adelante, lo que incrementa notablemente la dificultad y estabilidad.'),
('6c8bd45b-2fb0-4f3c-9aa1-dce626fdad9b', '629f3c26-ab37-4050-a180-4a812996a090', 'en', 'Hex Bar Deadlift', 'Inside the hex bar, lower hips and lift. Safer for the back. Cue: push the floor with your feet. Error: knees caving in.'),
('3e997b63-6b3d-427e-9301-147f4dcc22ad', '629f3c26-ab37-4050-a180-4a812996a090', 'es', 'Peso muerto con barra hexagonal', 'Dentro de la barra hexagonal, baja cadera y levanta. Más seguro para la espalda. Cue: empuja el suelo con los pies. Error: rodillas hacia adentro.'),
('620514d3-699f-43ad-9d78-6d00134d2523', '62af9ece-a4ee-43c3-8eb2-454f41bc0e89', 'en', 'V-Grip Landmine Row', 'Straddling the landmine bar, pull toward the abdomen with a narrow grip. Cue: flat back. Error: jerks with the lumbar zone.'),
('8b58c9e9-d88f-42df-b344-e660222d9ecd', '62af9ece-a4ee-43c3-8eb2-454f41bc0e89', 'es', 'Remo Landmine con agarre V', 'A horcajadas sobre la barra landmine, tira hacia el abdomen con agarre estrecho. Cue: espalda plana. Error: tirones con la zona lumbar.'),
('be3303f1-f2bf-4c97-9080-2e9f306651ab', '62b1a98e-1ff3-49c4-a188-42f61bcfd919', 'en', 'Standing Glute Kickback with Miniband', 'Standing with the band on the ankles. Kick one leg backward keeping the knee straight, using only the glute to move the leg.'),
('c184d5c0-ae4a-435b-95f0-f219acc9e0fb', '62b1a98e-1ff3-49c4-a188-42f61bcfd919', 'es', 'Patada de glúteo de pie con Miniband', 'De pie con la banda en los tobillos. Patea una pierna hacia atrás manteniendo la rodilla recta, usando solo el glúteo para mover la pierna.'),
('4e366b1f-b9ef-43dd-a444-8555a23f2b0f', '62bc677f-b876-409b-a7eb-6c62c6f39bdb', 'en', 'Kettlebell Sumo Deadlift High Pull', 'From a sumo deadlift, lift the weight toward the chin with an explosive movement. Objective: total power. Cue: high elbows at the top. Common error: using only the arms instead of hip power.'),
('26a1ecd4-84ff-4761-b69a-8c844f941d9b', '62bc677f-b876-409b-a7eb-6c62c6f39bdb', 'es', 'Kettlebell Sumo Deadlift High Pull', 'Desde peso muerto sumo, eleva la pesa hacia el mentón con un movimiento explosivo. Objetivo: potencia total. Cue: codos altos arriba. Error común: usar solo los brazos en lugar de la potencia de cadera.'),
('39cca800-3967-4376-8834-23e3fe93fde4', '6313147f-0670-451f-89bc-317799ac6ffc', 'en', 'Heel Touch Vertical Jump', 'Jump and flex knees to touch heels with hands behind glutes. Cue: high jump to allow time. Common error: throwing the trunk forward when jumping.'),
('54256b52-f844-4cd7-bded-84f447960197', '6313147f-0670-451f-89bc-317799ac6ffc', 'es', 'Salto vertical con toque de talones', 'Salta y flexiona las rodillas para tocar los talones con las manos detrás de los glúteos. Cue: salto alto para tener tiempo. Error común: tirar el tronco hacia adelante al saltar.'),
('ef08625e-cc01-4859-a52c-d518f1b3165d', '63285570-fdca-42d0-b232-5999afb89c51', 'en', 'Macebell Offset Bent Over Row', 'Hold the mace with one hand closer to the weight than the other. Perform a bent-over row resisting the asymmetrical load of the tool.'),
('1aedd3bd-be94-4580-bc82-dfc66b3698f6', '63285570-fdca-42d0-b232-5999afb89c51', 'es', 'Remo inclinado con maza (Offset)', 'Sujeta la maza con una mano mas cerca del peso que la otra. Realiza un remo inclinado resistiendo la carga asimetrica de la herramienta.'),
('8a355ccb-7291-4c67-a53a-7e4606778ad9', '6332e158-7c6e-4804-9716-ac2deefd4818', 'es', 'Press un brazo cable', 'Press horizontal unilateral de pie. Requiere tremenda estabilización del core para resistir rotación. Más funcional que press bilateral. Permite mayor rango de movimiento. Mantén caderas cuadradas.'),
('0a50aa74-95b6-4047-a78a-3970a3f26ad1', '6347bc1f-fc85-4b4b-bee3-fc4181ec568b', 'en', 'Single Arm Kettlebell Spider Curl', 'Prone on an incline bench, perform a bicep curl with a kettlebell letting the arm hang vertically to isolate the muscle.'),
('4018f177-2618-49fe-8ac7-4eff4d73a8b4', '6347bc1f-fc85-4b4b-bee3-fc4181ec568b', 'es', 'Spider Curl con Kettlebell a una mano', 'Boca abajo en banco inclinado, realiza un curl de bíceps con una Kettlebell dejando el brazo colgar verticalmente para aislar el músculo.'),
('73fe1b52-6f1b-4cab-9644-045bf497e01b', '6359bb2b-a6f2-49b8-91b0-c8280e4698e1', 'en', 'Parallette Crow Pose', 'On the parallettes, rest your knees on your triceps and lean forward lifting your feet off the ground to balance the body.'),
('a4da21e5-392e-497e-819e-e2e965bb7dd9', '6359bb2b-a6f2-49b8-91b0-c8280e4698e1', 'es', 'Postura del cuervo paralelo', 'En las paralelas, apoya las rodillas en los tríceps e inclínate hacia adelante despegando los pies del suelo para equilibrar el cuerpo.'),
('8bd8f5f7-0640-47d5-a363-b0ffe63d7925', '63665876-ab73-4d93-9c92-8d7cc20b4d7d', 'en', 'Behind the Neck Cable Pulldown', 'Similar to the lat pulldown but bringing the bar behind the head to the level of the neck. Requires good shoulder mobility. Do not go too low to avoid injury. Some experts advise against this exercise due to potential risk.'),
('b8df9227-0ea7-4d97-952c-2fb2be1dc507', '63665876-ab73-4d93-9c92-8d7cc20b4d7d', 'es', 'Jalón tras nuca cable', 'Similar al jalón al pecho pero llevando la barra detrás de la cabeza hasta la altura de la nuca. Requiere buena movilidad de hombros. No bajes demasiado para evitar lesiones. Algunos expertos desaconsejan este ejercicio por el riesgo potencial.'),
('07c96575-dce2-48c4-a646-28e9a8d82749', '6369fb53-02f0-4be0-979e-1efc1f112caf', 'en', 'Kettlebell Deadlift', 'Kettlebell between feet, lower with straight back, grip the handle and rise extending the hip. Objective: glutes and hamstrings. Cue: push the floor with your heels. Error: rounding the back at the start.'),
('09ad7fd3-4c71-4ee1-a7f0-e5dd92849a16', '6369fb53-02f0-4be0-979e-1efc1f112caf', 'es', 'Peso muerto con kettlebell', 'Pesa rusa entre los pies, baja con la espalda recta, sujeta el asa y elévate extendiendo la cadera. Objetivo: glúteos e isquios. Cue: empuja el suelo con los talones. Error: redondear la espalda al inicio.'),
('242b7902-3a90-44be-9fd1-c0b2cb49c9e0', '6391579c-b6f4-4461-8ca2-6ee716259eea', 'en', 'Landmine Thruster', 'Hold the end of the bar with both hands, descend into a squat and explosively push the bar forward and up upon rising.'),
('a8a1ffce-ca54-4ab2-8c6b-151b1461794f', '6391579c-b6f4-4461-8ca2-6ee716259eea', 'es', 'Thruster en Landmine', 'Sujeta el extremo de la barra con ambas manos, baja en sentadilla y empuja explosivamente la barra hacia adelante y arriba al subir.'),
('b3220e18-166d-447a-92db-1f787e034b3c', '63957eda-5492-4526-b258-267d1f2b7c2c', 'en', 'Battle Ropes Plank', 'In a plank position, move one rope at a time while maintaining core stability. Extremely challenging for the core. Avoid rotating hips while alternating arms. Start with short intervals.'),
('480cc26f-d1e5-4e25-a070-30f7d6c6c67d', '63957eda-5492-4526-b258-267d1f2b7c2c', 'es', 'Battle ropes plank', 'En posición de plancha, mueve una cuerda por vez manteniendo la estabilidad del core. Extremadamente desafiante para el core. Evita rotar las caderas mientras alternas los brazos. Comienza con intervalos cortos.'),
('2769d7db-c149-4f12-9c5c-a424e016f5f8', '639a618a-3a11-4f9d-a85d-96e7c15118e8', 'en', 'Explosive Cable Woodchopper', 'Woodchopper with maximum speed and power. The cable should move explosively in the concentric phase but controlled in the eccentric. Develops rotational power for sports. Keep arms relatively extended.'),
('1bffd15a-dab1-42b1-aadb-b447c9ed262f', '639a618a-3a11-4f9d-a85d-96e7c15118e8', 'es', 'Leñador explosivo cable', 'Woodchopper con máxima velocidad y potencia. El cable debe moverse explosivamente en la fase concéntrica pero controlado en la excéntrica. Desarrolla potencia rotacional para deportes. Mantén brazos relativamente extendidos.'),
('74539942-6f38-4426-a8cc-ab2d20040b27', '63b72b29-de6a-4901-83c1-70756513a1dc', 'en', 'Barbell Zercher Squat', 'Bar in the crook of the elbows, lower into a deep squat. Cue: very upright torso. Error: letting the bar move away from the body.'),
('7cc78bf7-36cd-4fe6-8d8d-099c3fa3187b', '63b72b29-de6a-4901-83c1-70756513a1dc', 'es', 'Sentadilla Zercher con barra', 'Barra en el pliegue de los codos, baja en sentadilla profunda. Cue: torso muy erguido. Error: dejar que la barra se aleje del cuerpo.'),
('26e6bda4-89e5-4e5f-b4f7-8ddcd406c898', '63c79ac0-9f0f-41a3-9f1b-84de9a2af590', 'en', 'Frog Pump', 'Lie on your back with the soles of your feet together and knees open. Raise hips quickly squeezing glutes and lower.'),
('9cd158e2-1f15-454f-8628-efa202bf3e86', '63c79ac0-9f0f-41a3-9f1b-84de9a2af590', 'es', 'Frog Pump', 'Acuéstate boca arriba con las plantas de los pies juntas y rodillas abiertas. Eleva las caderas rápidamente apretando los glúteos y baja.'),
('0c448534-4af2-4811-b689-fee1b346b405', '63e6895b-a245-4fe5-83d8-89246024b7d4', 'es', 'Plancha lateral con rotación', 'En plancha lateral, pasa el brazo libre por debajo del cuerpo y vuelve a extenderlo hacia el techo. Objetivo: oblicuos y estabilidad escapular. Cues: core muy firme en el giro. Error común: dejar caer la cadera hacia el suelo al rotar.'),
('613ed2ae-ae7a-4ba0-a5d4-426d4a35ba75', '640686a4-ca8a-4b6b-bcf6-c08d6f4f466a', 'en', 'Pogo Jack Jump', 'Fast bounces alternating feet open and closed (like a plyometric jumping jack). Cue: minimum contact time. Common error: landing on heels.'),
('14492f05-bf56-4bca-9ac1-6540b07e7eae', '640686a4-ca8a-4b6b-bcf6-c08d6f4f466a', 'es', 'Salto pogo jack', 'Rebotes rápidos alternando pies abiertos y cerrados (como jumping jack pero pliométrico). Cue: tiempo de contacto mínimo. Error común: apoyar talones.'),
('26a5b7c8-1c12-45d0-97e1-981f7e125500', '642a6c58-eab9-4ab5-a2f7-8321ee04c3e4', 'es', 'Zancada inversa Overhead con Slider y Kettlebell doble', 'Sostén dos pesas rusas bloqueadas sobre la cabeza. Desliza un pie hacia atrás en una zancada inversa usando un slider, manteniendo la estabilidad de los brazos.'),
('24d33f82-9060-4495-8621-bae891c04b23', '642ea1aa-5610-4413-bdfc-254817d3e05c', 'en', 'Band Deadlift', 'Step on the center of the band with feet hip-width apart. Hold the ends and hinge from the hips with a straight back, like a conventional deadlift. The band provides progressive resistance, being most intense at the top of the movement.'),
('8248fddd-2ef3-41ed-a69a-9df746fa23f5', '642ea1aa-5610-4413-bdfc-254817d3e05c', 'es', 'Deadlift con banda', 'Pisa el centro de la banda con los pies al ancho de las caderas. Sujeta los extremos e inclínate desde las caderas con la espalda recta, como en un peso muerto convencional. La banda proporciona resistencia progresiva, siendo más intensa en la parte superior del movimiento.'),
('0b37a69e-110e-46d3-8eb2-44f17dce629a', '64d5626f-e211-493f-bc8d-42ae627356ab', 'en', 'Low Pulley Upright Row to Chin', 'Pull the bar to the chin using a pulley. Cue: elbows up. Error: sudden jerks.'),
('f56aa592-bee4-44a7-b6e9-76c84611a5f5', '64d5626f-e211-493f-bc8d-42ae627356ab', 'es', 'Remo cuello polea baja barra mentón', 'Tira barra al mentón polea. Cue: codos arriba. Error: tirones bruscos.'),
('acb88eaa-ccdb-487a-8c4f-e566af0e1e8b', '65060417-e7d5-4fd6-9604-372275b0396e', 'en', 'Machine Shoulder Press', 'Seated with back supported, press upward following the machine''s path. Can have neutral or prone grip according to design. Ideal for beginners or high-volume work with safety.'),
('c3876f2f-bcb3-428a-b1be-5eebfd4852d5', '65060417-e7d5-4fd6-9604-372275b0396e', 'es', 'Press hombros máquina', 'Sentado con la espalda apoyada, presiona hacia arriba siguiendo la trayectoria de la máquina. Puede tener agarre neutro o pronado según el diseño. Ideal para principiantes o para trabajo de alto volumen con seguridad.'),
('7c0f2e40-06d0-47d1-8132-d42fbe9a741a', '65262863-5694-4d64-9753-ef2f34920e1d', 'en', 'Fire hydrant', 'On all fours, keep the knee bent at 90 degrees and lift the leg laterally until the thigh is parallel to the floor. Avoid rotating the hip or arching the back. Lower in a controlled manner without touching the floor. This exercise specifically activates the gluteus medius.'),
('d8186b3e-dfe4-4a32-be07-1fc8298522b3', '65262863-5694-4d64-9753-ef2f34920e1d', 'es', 'Fire hydrant', 'En cuadrupedia, mantén la rodilla flexionada a 90 grados y eleva lateralmente la pierna hasta que el muslo esté paralelo al suelo. Evita rotar la cadera o arquear la espalda. Desciende controladamente sin tocar el suelo. Este ejercicio activa específicamente el glúteo medio.'),
('cce9e938-3b47-47fa-9994-33a64603723e', '654c9bec-1825-4a8d-9c08-8d72a1bdac8d', 'en', 'Medicine Ball Slam', 'Throw the ball against the floor with maximum force using the whole body. Objective: total power and core. Cue: full extension before the slam. Common error: rounding the back when releasing the ball.'),
('7862d77b-88ee-4ccc-92e4-d86c3102f758', '654c9bec-1825-4a8d-9c08-8d72a1bdac8d', 'es', 'Slam de balón medicinal', 'Lanza el balón contra el suelo con máxima fuerza usando todo el cuerpo. Objetivo: potencia total y core. Cue: extensión total previa al golpe. Error común: redondear la espalda al soltar el balón.'),
('25e14cc8-1888-4123-abd9-e801c0cd931c', '657f45b9-ce99-4d3d-88ec-115941050313', 'en', 'Human Flag', 'Hold the body horizontally sideways, gripping a vertical bar. Requires exceptional strength in the core, lats, and shoulders. One of the most impressive demonstrations of relative strength. Progress with negatives and staggered positions.'),
('2b5c765e-31b6-4bd3-8720-7f290f83164b', '657f45b9-ce99-4d3d-88ec-115941050313', 'es', 'Bandera humana', 'Sostén el cuerpo horizontal lateralmente agarrado a una barra vertical. Requiere fuerza excepcional en core, dorsales y hombros. Una de las demostraciones más impresionantes de fuerza relativa. Progresa con negativos y posiciones escalonadas.'),
('22e4bb9f-03e0-4819-b520-be27629315c8', '6582cada-a4ca-4f8b-92e9-8e6995e72c7e', 'es', 'Zancada hacia adelante alterna con mancuernas', 'Da un paso adelante con mancuernas a los lados. Baja la rodilla trasera hasta casi tocar el suelo y regresa a la posición inicial de un impulso.'),
('54337b8a-319c-40f4-8316-b62c6b9ffa22', '6623843b-e89d-4618-be68-809f98de59cc', 'en', 'Squat Throw', 'Perform a full squat and upon rising, throw the ball upward or forward explosively. Develops total body power. Can be done against a wall or outdoors. Coordinate legs and arms.'),
('f27be14a-bf27-4f97-8df2-6eac191e8446', '6623843b-e89d-4618-be68-809f98de59cc', 'es', 'Squat throw', 'Realiza una sentadilla completa y al subir lanza el balón hacia arriba o hacia adelante explosivamente. Desarrolla potencia en todo el cuerpo. Puede hacerse contra pared o al aire libre. Coordina piernas y brazos.'),
('069adc4a-1d26-415a-ac3f-155bbded09d0', '664ed498-6ac8-4a9f-adb3-857dd69370d3', 'en', 'Single Arm Kettlebell Prone Row', 'Lying face down on a bench, row the kettlebell toward your hip with a single arm to isolate the lat without involving the lower back.'),
('f5b10d52-93e0-449d-b08e-ce22839239fd', '664ed498-6ac8-4a9f-adb3-857dd69370d3', 'es', 'Remo prono con Kettlebell a una mano', 'Tumbado boca abajo sobre un banco, rima la pesa rusa hacia tu cadera con un solo brazo para aislar el dorsal sin involucrar la zona lumbar.'),
('b83eed05-76f8-4180-93ac-0f11a9afad37', '66a0d31c-78de-47ec-9d0a-acb504162f75', 'en', 'Superman Push Ups', 'Explosive push-up where the entire body leaves the ground with arms and legs extended. Requires exceptional power. The body must remain completely horizontal in the air. Progress with clap push-ups and other explosive variations.'),
('7646064a-566d-45eb-a033-ed0654ee7a7f', '66a0d31c-78de-47ec-9d0a-acb504162f75', 'es', 'Flexiones superman', 'Flexión explosiva donde el cuerpo completo despega del suelo con brazos y piernas extendidos. Requiere potencia excepcional. El cuerpo debe quedar completamente horizontal en el aire. Progresa con flexiones clap y otras variaciones explosivas.'),
('8abcc1ff-03e2-460e-9b41-948267d19a41', '66a613b9-e84f-47e6-913e-1f0b6cac3476', 'en', 'Incline Dumbbell Bicep Curl', 'Seated curl on 45-degree bench for maximum stretch. Cue: fixed elbows. Error: moving shoulders.'),
('55c5abdb-e180-4e13-aaab-6ebfbbe6cc8a', '66a613b9-e84f-47e6-913e-1f0b6cac3476', 'es', 'Curl de bíceps inclinado mancuerna', 'Curl sentado en banco a 45 grados para máximo estiramiento. Cue: codos fijos. Error: mover hombros.'),
('8a4dfb1b-139b-4ff4-9c7c-384ce6cc702d', '66d6fca2-58e5-4f68-b529-bf89f2839688', 'en', 'Bodyweight Loaded Beast to Alternating Kick Through', 'From quadruped with hovering knees, shift your weight back and spring into a rotation kicking underneath the body, alternating sides.'),
('e5390d19-c797-4471-bc7d-00751674a038', '66d6fca2-58e5-4f68-b529-bf89f2839688', 'es', 'De Bestia cargada a Kick Through alterno', 'Desde cuadrupedia con rodillas elevadas, desplaza el peso atrás y lánzate a un giro pateando por debajo del cuerpo, alternando lados.'),
('c7979bc4-b31e-44af-8e99-50219fa4d6bf', '66d902a4-58da-437c-86f9-0a94c8d12937', 'en', 'Horn Grip Kettlebell Slider Lateral Lunge', 'Hold a kettlebell by the horns in front of the chest and slide one leg to the side on a slider in a controlled manner.'),
('21569002-1e30-4040-8247-f64bb25ba78d', '66d902a4-58da-437c-86f9-0a94c8d12937', 'es', 'Zancada lateral con Slider y Kettlebell (Horn)', 'Sujeta una Kettlebell por los cuernos frente al pecho y desliza una pierna hacia el lado sobre un slider de forma controlada.'),
('1418d395-e7ac-4101-ac7c-3053d10d270b', '66f3fdff-6636-4c30-b79f-f237895b25cc', 'es', 'Plank frontal a una mano sobre Fitball', 'Realiza una plancha sobre los antebrazos en un Fitball, pero levantando un brazo para quedar apoyado solo en uno, aumentando el reto de estabilidad.'),
('34a7f96a-111a-4bec-be0b-c47bbf34309a', '6763aab6-2a0a-4640-9fda-c75dc78fd57e', 'en', 'Overhead Cable Triceps Extension', 'Extend cable overhead with back to the pulley. Cue: full stretch. Error: arching the lower back.'),
('ee587c91-3181-4a3f-9060-ad804347522b', '6763aab6-2a0a-4640-9fda-c75dc78fd57e', 'es', 'Extensión tríceps overhead polea', 'Extiende cable sobre cabeza de espaldas a la polea. Cue: estira total. Error: arquear lumbar.'),
('23fe72cf-0ce0-411f-af2e-b7718a018104', '676fae14-a2da-45af-a16c-261af549f9f2', 'en', 'Resisted run in place', 'Simulate sprinting at maximum speed with a band around the waist pulling back. Pushing power. Chest high. Do not drag feet.'),
('0c802309-5ee0-453c-b7d5-4de1fd4622fa', '676fae14-a2da-45af-a16c-261af549f9f2', 'es', 'Carrera en el sitio con resistencia', 'Simula carrera a máxima velocidad con una banda en la cintura que tira hacia atrás. Potencia de empuje. Pecho alto. No arrastres los pies.'),
('09001f6d-a077-41ad-8bd3-def110c7b1f0', '6770e326-49b4-4d8a-a1a8-582cd510b054', 'en', 'Reverse Dumbbell Flyes', 'Leaning forward with the torso parallel to the ground, lift dumbbells laterally. Objective: rear deltoid. Cue: imagine you are pushing with your elbows outward. Error: swinging the torso to lift the weights.'),
('1c5b9d5d-3632-4656-b6b9-adeab2ec6ad7', '6770e326-49b4-4d8a-a1a8-582cd510b054', 'es', 'Aperturas inversas con mancuernas', 'Inclinado hacia adelante con el torso paralelo al suelo, eleva las mancuernas lateralmente. Objetivo: deltoides posterior. Cue: imagina que empujas con los codos hacia afuera. Error: balancear el torso para subir las pesas.'),
('1a5449ea-a0de-4592-9d07-c9d1a7aacbf9', '67a49860-9787-4365-a171-7a5249047624', 'en', 'Single Arm Kettlebell Front Rack Ipsilateral Step Up', 'Hold the kettlebell in the rack position and step up onto the bench with the same-side leg, resisting the asymmetrical load on the torso.'),
('4a224915-e6a4-4181-99bc-469d2655c126', '67a49860-9787-4365-a171-7a5249047624', 'es', 'Step Up ipsilateral Front Rack con Kettlebell a una mano', 'Sujeta la Kettlebell en posición rack y sube al banco con la pierna del mismo lado, resistiendo la carga asimétrica sobre el tronco.'),
('ee0d1522-3f3a-4325-b1d4-213fbf030622', '67db9f92-68fe-42e9-9fa8-f3b0cfb6055b', 'en', 'Cable Fire Hydrant', 'In a quadruped position lateral to the low pulley, attach the cable to your knee and perform a hip abduction, lifting the leg to the side.'),
('a13931dd-5bfc-40f7-9765-76f38ff0fab0', '67db9f92-68fe-42e9-9fa8-f3b0cfb6055b', 'es', 'Fire Hydrant en polea', 'En posicion de cuadrupedia lateral a la polea baja, sujeta el cable a tu rodilla y realiza una abduccion de cadera levantando la pierna hacia el lado.'),
('56e36d0f-f6e2-49d5-8305-2bf1df0e29d9', '67dfb407-9666-4518-a22b-717c09a0a493', 'en', 'Medicine Ball V Up', 'Lie down holding a medicine ball with arms extended. Simultaneously raise torso and straight legs to touch the ball with your feet at the highest point.'),
('17fe0964-3fb6-4e09-91e5-ca0bed3e86a2', '67dfb407-9666-4518-a22b-717c09a0a493', 'es', 'V-Up con balón medicinal', 'Acuéstate sosteniendo un balón medicinal con las manos extendidas. Levanta simultáneamente el torso y las piernas rectas para tocar el balón con los pies en el punto más alto.'),
('ae04f017-f97c-4f14-bc7a-bc02e1a1d5c6', '682169e4-c090-4da3-b1eb-3eb6d6969537', 'en', 'Ring German Hang Pullout', 'From a German Hang position (maximum shoulder stretch), pull the body up until reaching an inverted position.'),
('e19f75a2-bdab-46c9-a3f8-d2eb61abdef1', '682169e4-c090-4da3-b1eb-3eb6d6969537', 'es', 'German Hang Pullout en anillas', 'Desde la posicion de German Hang (estiramiento maximo de hombro), tira del cuerpo hacia arriba hasta quedar en posicion invertida.'),
('09bed0df-64c0-4020-a6bf-33cc0db74ac1', '688cd53a-cc69-4672-8d7d-8ec7d9dde549', 'en', 'Dumbbell Flyes', 'Lie on a bench with arms extended over the chest and a slight bend in the elbows. Open arms in a wide arc, lowering the dumbbells until you feel a stretch in the chest. Bring the dumbbells back together over the chest, squeezing the pectorals.'),
('89a91471-6777-42b8-ab8e-bc0a7181f5a8', '688cd53a-cc69-4672-8d7d-8ec7d9dde549', 'es', 'Aperturas mancuernas', 'Túmbate en banco con los brazos extendidos sobre el pecho y una ligera flexión en los codos. Abre los brazos en arco amplio descendiendo las mancuernas hasta sentir un estiramiento en el pecho. Vuelve a juntar las mancuernas sobre el pecho apretando los pectorales.'),
('2e24cc7f-3c93-4ec9-882a-0e1045f9cecf', '68e37d97-ece2-4d5f-b091-5473408bb42c', 'en', 'Parallette Feet Elevated Close Grip Push Up', 'With feet on a bench and hands on parallettes shoulder-width apart, perform push-ups by lowering deeply to emphasize the triceps.'),
('2da006e4-8ff4-45e0-b18c-bd37499e5ee8', '68e37d97-ece2-4d5f-b091-5473408bb42c', 'es', 'Pies Paralelos Elevados Empuñadura Cerrada Empuje Hacia Arriba', 'Con los pies en banco y manos en paralelas a la anchura de hombros, realiza flexiones bajando profundamente para enfatizar los triceps.'),
('8af8925e-da69-47cf-8501-ae57d4335c56', '68ec9442-186d-4742-bb17-c7ba49c6e1ea', 'en', 'Kneeling Barbell Shoulder Press', 'Kneeling on both legs, press the bar overhead. This position eliminates leg help and demands greater lumbar control.'),
('906438e3-458e-4d0d-b060-a8dda16c2e10', '68ec9442-186d-4742-bb17-c7ba49c6e1ea', 'es', 'Press de hombros con barra arrodillado', 'Arrodillado sobre ambas piernas, presiona la barra sobre la cabeza. Esta posición elimina la ayuda de las piernas y exige un mayor control lumbar.'),
('47ff5373-c307-4551-875e-3d8bafa18d3c', '68ff3708-4444-41f0-bf14-d8ceaf53b914', 'en', 'One-Arm Rollout', 'Rollout using only one arm. Requires extreme anti-rotation strength. Start with very short ranges from knees. The free arm can be on the back or extended. Alternate arms for balanced development.'),
('ea67043f-b894-4ce6-a57b-026ae310520b', '68ff3708-4444-41f0-bf14-d8ceaf53b914', 'es', 'Rodamiento un brazo', 'Roll out usando solo un brazo. Requiere fuerza anti-rotación extrema. Comienza con rangos muy cortos desde rodillas. El brazo libre puede estar en la espalda o extendido. Alterna brazos para desarrollo equilibrado.'),
('1f3b03d6-73b4-43ab-9dff-f943821a687a', '691d0774-d545-4f68-998a-a922edfa86e5', 'en', 'Unilateral Behind the Neck Triceps Extension', 'Raise and lower a dumbbell behind the neck with a single arm. Objective: long head of the triceps. Cue: elbow points to the ceiling. Common error: moving the arm laterally losing tension.'),
('0c2bea08-ce37-4208-be22-f51f38765a4b', '691d0774-d545-4f68-998a-a922edfa86e5', 'es', 'Extensión de tríceps tras nuca unilateral', 'Eleva y baja una mancuerna tras la nuca con un solo brazo. Objetivo: cabeza larga del tríceps. Cue: codo apunta al techo. Error común: mover el brazo lateralmente perdiendo tensión.'),
('0be55d8d-d54d-4c3e-9ed0-1c79d8a50ffc', '6944aafc-fc99-4a40-853b-c68db5111703', 'en', 'Ring Straight Arm Pike Press Handstand', 'From an inverted hang, lower to a pike position and press with locked arms back into a vertical handstand.'),
('b23570db-2500-47aa-b9f9-9aaf0ade3781', '6944aafc-fc99-4a40-853b-c68db5111703', 'es', 'Pike Press Handstand con brazos rectos en anillas', 'Desde la posicion de colgado invertido, baja a posicion de pica y presiona con los brazos bloqueados hasta la parada de manos vertical.'),
('03e9c3f5-f9f9-4b42-8197-953e05d2a9cc', '69860d20-6b10-4a61-aea2-44b1c22ba23e', 'en', 'One-Arm Lateral Indian Club Rotation', 'Hold an Indian Club with one hand and perform internal and external lateral rotations to strengthen the rotator cuffs.'),
('0fe62691-422b-4c79-a567-2d18300f0a2f', '69860d20-6b10-4a61-aea2-44b1c22ba23e', 'es', 'Rotación lateral a una mano con Indian Club', 'Sostén un Indian Club con una mano y realiza rotaciones internas y externas laterales para fortalecer los manguitos rotadores.'),
('6c43f42d-0a9d-41b4-aa2b-69382a6c3266', '698fc5cd-9f68-4e73-b84f-66d9b29c6c15', 'en', 'Parallel Bar Side Plank', 'Support one hand on the parallel bar and place the body sideways in a straight line. Maintain the position activating obliques and the stabilizing shoulder.'),
('908ebd0f-dec5-40b7-bfc0-1d7e8467e940', '698fc5cd-9f68-4e73-b84f-66d9b29c6c15', 'es', 'Side Plank en paralelas', 'Apoya una mano en la paralela y coloca el cuerpo de lado en línea recta. Mantén la posición activando los oblicuos y el hombro estabilizador.'),
('0c49838b-b25c-4c2c-820a-20a7884ab2b7', '69a3decd-2eaf-4786-9b0f-a66aaad711c3', 'en', 'High Band Triceps Pushdown', 'Push the band downward. Cue: elbows fixed to sides. Error: flaring elbows out while lowering.'),
('16234a18-5a4b-42d7-a0ab-07f39a620f7f', '69a3decd-2eaf-4786-9b0f-a66aaad711c3', 'es', 'Tríceps con banda alta', 'Empuja la banda hacia abajo. Cue: codos fijos a costados. Error: separar codos al bajar.'),
('4a425255-76a7-465e-bc1e-6efa48ffa991', '69af50d3-5b26-4840-9dd5-142117aa2ce1', 'es', 'Zancada con salto explosivo', 'Desde zancada, salta verticalmente buscando máxima altura y aterriza en la misma posición. Potencia de salida. Rodilla delantera estable. No golpees la rodilla trasera.'),
('83db6d68-5f95-43ff-856f-9abc6730f82c', '69b1e1f5-5ce1-46f6-a00a-c2ea29e6195e', 'en', 'Wall Facing Squat', 'Stand in front of a wall with your feet close to it. Lower into a squat avoiding touching the wall with your torso, which corrects posture.'),
('57f260f4-9ae5-4105-aa58-e64ec86c5d22', '69b1e1f5-5ce1-46f6-a00a-c2ea29e6195e', 'es', 'Sentadilla frente a la pared', 'Ponte frente a una pared con los pies cerca de ella. Baja en sentadilla evitando tocar la pared con el torso, lo que corrige la postura.'),
('72731ec8-3db1-410b-a8b7-daeb8ada698a', '69b23ccf-09a7-4e45-be57-4f479e9543be', 'en', 'Single Arm Kettlebell Tactical Snatch', 'An explosive snatch where you switch the kettlebell between hands in mid-air during the descent phase, before the next swing.'),
('87aaa37a-3ec2-4c56-b0d3-1dfb1f107e45', '69b23ccf-09a7-4e45-be57-4f479e9543be', 'es', 'Arranque táctico con pesa rusa de un solo brazo', 'Un snatch explosivo donde intercambias la Kettlebell de mano en el aire durante la fase de descenso, antes del siguiente balanceo.'),
('9791a831-1c0b-4e7f-98bc-47692fdc23cc', '69bd9c4b-882c-4925-8f6b-8b04b24ebefb', 'en', 'Single Arm Dumbbell Side Plank Reach Through', 'In a side plank position, hold a dumbbell with the free arm extended upward. Lower the dumbbell crossing it under the torso and raise it again.'),
('0b5c5715-96c9-4511-ad35-3986cc61ea5d', '69bd9c4b-882c-4925-8f6b-8b04b24ebefb', 'es', 'Plank lateral con alcance y mancuerna', 'En posición de Plank lateral, sostén una mancuerna con el brazo libre extendido hacia arriba. Baja la mancuerna cruzándola por debajo del torso y vuelve a elevarla.'),
('10d26f3b-852d-4780-866b-f723e99bfa41', '69e57dfa-db7d-4708-9780-4ca53c3d799d', 'en', 'Skater Jump', 'Jump laterally from one foot to the other, imitating a skating motion. Seek distance and landing control. Objective: lateral power and hip stability. Cue: land softly with the knee aligned with the foot. Common error: excessively rotating the torso.'),
('0628ad1a-06c0-4193-bc08-be12f4e61d96', '69e57dfa-db7d-4708-9780-4ca53c3d799d', 'es', 'Salto de patinador', 'Salta lateralmente de un pie al otro imitando el movimiento de patinaje. Busca distancia y control en el aterrizaje. Objetivo: potencia lateral y estabilidad de cadera. Cue: aterriza suave con la rodilla alineada al pie. Error común: rotar el tronco excesivamente.'),
('22ea6ead-0039-4c0a-969f-30e9f6303428', '69f2cd47-fffc-475f-8629-20801dfc8bc6', 'es', 'Zancada inversa contralateral con Slider y Kettlebell (Front Rack)', 'Sostén una pesa rusa en el pecho (front rack) y desliza hacia atrás la pierna del lado opuesto usando un slider para trabajar la estabilidad cruzada.'),
('7c1b3468-b47f-47b9-8faf-b7d17044ffbd', '6a01d020-3903-43bf-aee3-86c1c8c5b097', 'en', 'Ring Handstand Lower to Back Lever', 'From a handstand position on rings, lower your body under control while keeping arms straight until reaching a Back Lever position.'),
('dbb29472-5b6f-4ea8-b323-0e0f757ac4eb', '6a01d020-3903-43bf-aee3-86c1c8c5b097', 'es', 'Parada de manos en anillas a Back Lever', 'Desde una posicion de parada de manos en anillas, baja el cuerpo de forma controlada manteniendo los brazos rectos hasta quedar en posicion de Back Lever.'),
('6986667e-f47f-4a73-a13a-1006b62972e2', '6a0c6745-5677-437a-a134-a4cc66f7cd09', 'es', 'Push Jerk alterno con Kettlebell doble', 'Utiliza un impulso explosivo de piernas para elevar las pesas rusas alternativamente, recepcionando el peso con los brazos bloqueados.'),
('118862e3-20d5-4c95-ab11-9c7bb4f94954', '6a62d35b-b5aa-4674-bb97-1abe5ab9cae5', 'en', 'Tibialis Anterior Raise', 'Raise the toe toward the shin against resistance or a wall. Cue: maximum range. Error: moving the knee.'),
('81435b10-e810-4936-bb93-dd109f1bc23c', '6a62d35b-b5aa-4674-bb97-1abe5ab9cae5', 'es', 'Elevación tibial anterior', 'Eleva la punta del pie hacia la espinilla contra resistencia o pared. Cue: rango máximo. Error: mover la rodilla.'),
('87957878-b7c5-47ba-98e4-8b48a82f5f4f', '6aaff30f-694e-4bbe-9dd1-d74c814d772e', 'en', 'Alternating Single Arm Kettlebell Dead Clean', 'Perform the shoulder clean from the floor alternating arms each repetition, working unilateral power in a coordinated manner.'),
('2e99fcde-348a-462e-977b-5bd117fc7a62', '6aaff30f-694e-4bbe-9dd1-d74c814d772e', 'es', 'Clean alterno con Kettlebell a una mano desde el suelo', 'Realiza la cargada al hombro desde el suelo alternando el brazo en cada repeticion, trabajando la potencia unilateral de forma coordinada.'),
('b87f3307-ca8d-4d04-b9e0-7497f5ed3a72', '6b09dd52-4b91-4746-9668-9732af66db91', 'en', 'EZ Bar Wide Grip Bicep Curl', 'Hold the EZ bar with hands wider than shoulder width. Perform the curl to emphasize the short (inner) head of the bicep.'),
('f4da1951-d2fd-44ae-a9f9-fb0c9a239546', '6b09dd52-4b91-4746-9668-9732af66db91', 'es', 'Curl de bíceps agarre ancho con barra Z', 'Sostén la barra Z con las manos más separadas que el ancho de los hombros. Realiza el curl para enfatizar la cabeza corta (interna) del bíceps.'),
('f46e388d-91e8-4b16-8f56-a065e77ed970', '6b113673-4a5d-4db9-9169-df31c2a10fc5', 'en', 'Incline Barbell Press 30-45°', 'Chest press on incline bench with barbell. Objective: clavicular head of the pectoral. Cue: lower the bar to the upper chest. Common error: lowering the bar toward the neck.'),
('3cd5cdd1-4b1b-425f-93fb-e963bb94c39c', '6b113673-4a5d-4db9-9169-df31c2a10fc5', 'es', 'Press inclinado barra 30-45°', 'Press de pecho en banco inclinado con barra. Objetivo: haz clavicular del pectoral. Cue: baja la barra a la parte superior del pecho. Error común: bajar la barra hacia el cuello.'),
('26d8dc2e-a8fe-430c-82e2-13522a8804c0', '6b5a5550-a3e7-40f8-8502-aac2485e02a3', 'en', 'Bottoms Up with Fitball', 'Lying on your back, hold the Fitball with your feet and lift your legs and hips toward the ceiling, peeling the lower back off the floor under control.'),
('56781ce1-a7b7-4709-a791-43b937483445', '6b5a5550-a3e7-40f8-8502-aac2485e02a3', 'es', 'Bottoms Up con Fitball', 'Tumbado boca arriba, sujeta el Fitball con los pies y eleva las piernas y la cadera hacia el techo despegando la zona lumbar del suelo bajo control.'),
('b6bdc3be-6cf0-48b2-88e4-fa91d9f6519f', '6b5d1f69-ddd7-4580-adb1-4369449f6942', 'en', 'Cable Rope Skullcrusher', 'Lie on a flat bench using a low pulley behind your head. Extend your arms toward the ceiling separating the rope at the top.'),
('588baa2a-1fa0-4bb9-863f-d6be8cd92f0f', '6b5d1f69-ddd7-4580-adb1-4369449f6942', 'es', 'Rompecráneos con cuerda en polea (Skullcrusher)', 'Acuéstate en un banco plano usando una polea baja detrás de la cabeza. Extiende los brazos hacia el techo separando la cuerda en el tope.'),
('22de19c9-cad5-4464-a3ed-044863fb1c0e', '6ba021f2-3a29-4e1e-b125-e324a3267b03', 'en', 'Leg Press', 'Perform a leg press with the feet placed on the platform. Lower under control to a comfortable depth and push by extending the legs without aggressively locking the knees.'),
('2d407f7c-06d6-4239-a49a-a6d884e0fa0d', '6ba021f2-3a29-4e1e-b125-e324a3267b03', 'es', 'Prensa', 'Realiza una prensa de piernas colocando los pies sobre la plataforma. Baja de forma controlada hasta una profundidad cómoda y empuja extendiendo las piernas sin bloquear agresivamente las rodillas.'),
('d61c6d83-04b6-42e6-b455-7c17270ae2a4', '6babda62-f8b7-43c3-aec4-cbfba722db27', 'en', 'Mace Torch Press', 'Press the mace vertically overhead keeping it perfectly balanced as if it were a lit torch.'),
('ce004fdc-7ba6-421f-a8ac-6f6432094e4f', '6babda62-f8b7-43c3-aec4-cbfba722db27', 'es', 'Torch Press con maza', 'Presiona la maza verticalmente sobre la cabeza manteniéndola perfectamente equilibrada como si fuera una antorcha encendida.'),
('e1b71698-7d06-4b5c-98a0-0bcbe1a663af', '6bb27ab9-3bae-4907-9ffd-3ce5ecca1c35', 'en', 'Kettlebell Gorilla Row', 'Bent over with two weights on the floor, row alternately while the other weight serves as support. Objective: back and rotational stability. Cues: flat back and knees flexed. Common error: moving hips excessively.'),
('5fc3f18d-8bc2-4b2e-aa61-c66f2d92c61a', '6bb27ab9-3bae-4907-9ffd-3ce5ecca1c35', 'es', 'Gorilla Row con kettlebell', 'Inclinado con dos pesas en el suelo, rema alternativamente mientras la otra pesa sirve de apoyo. Objetivo: espalda y estabilidad rotacional. Cues: espalda plana y rodillas flexionadas. Error común: mover excesivamente la cadera.'),
('58306a9d-03cc-4d93-abbd-e7eec946bba3', '6bbd1c6f-8ee5-47b3-8dea-dfbe52d1d502', 'en', 'Sprints in Place', 'Simulate running at maximum speed by alternately raising knees. Objective: cardiovascular capacity. Cue: high knees and coordinated arms. Common error: landing with flat feet.'),
('2ae07b0a-b684-473d-8c5d-a49941e102c6', '6bbd1c6f-8ee5-47b3-8dea-dfbe52d1d502', 'es', 'Sprints en el sitio', 'Simula carrera a máxima velocidad elevando rodillas alternadamente. Objetivo: capacidad cardiovascular. Cue: rodillas altas y brazos coordinados. Error común: aterrizar con el pie plano.'),
('74d3ee95-7a13-4bb0-af9f-8e0e44ca3a65', '6bcebade-4d33-46d0-9c04-fd4e21a76f69', 'en', 'Kettlebell Romanian Deadlift', 'Lower the kettlebell close to your legs with semi-stiff knees and hips back. Objective: hamstrings. Cues: back flat as a board. Common error: bending knees too much turning it into a squat.'),
('3e1dc57f-a374-430b-b1be-66934ebdb06b', '6bcebade-4d33-46d0-9c04-fd4e21a76f69', 'es', 'Peso muerto estilo rumano con kettlebell', 'Baja la pesa rusa pegada a tus piernas con rodillas semi-rígidas y cadera atrás. Objetivo: isquiotibiales. Cues: espalda plana como una tabla. Error común: doblar demasiado las rodillas convirtiéndolo en sentadilla.'),
('17b59f26-fd09-4e59-a777-76f5900d23aa', '6be50ed3-bc62-41c5-aee0-d5410be2c932', 'en', 'Dynamic Hurdle Step with Jump', 'Simulate stepping over a hurdle with one leg and add a vertical jump at the end. Mobility and power. Neutral back. Do not rotate torso excessively.'),
('958b7444-b6ab-4086-92c3-d3e390807662', '6be50ed3-bc62-41c5-aee0-d5410be2c932', 'es', 'Paso de valla dinámico con salto', 'Simula el paso de una valla con una pierna y añade un salto vertical al final. Movilidad y potencia. Espalda neutra. No gires el torso excesivamente.'),
('6916084b-e1a0-4192-8c22-5adfa9ba47e1', '6c4850fe-d511-44e0-b35a-1ab605711e11', 'es', 'Plancha (Plank)', 'Mantén el cuerpo recto apoyado en antebrazos y puntas de pies. Objetivo: resistencia del core. Cue: aprieta glúteos y ombligo hacia adentro. Error común: dejar caer la cadera hacia el suelo.'),
('5ffba2bc-0a73-4732-b8a7-38bfe81238ad', '6c7c8108-71f5-4b12-880f-31777aa56cbf', 'en', 'Gravity Boots Inverted Sit Up', 'Hanging upside down with gravity boots, perform a full abdominal crunch by lifting your torso toward your knees.'),
('9b0419d0-bf74-420f-8542-98e32cdadfa8', '6c7c8108-71f5-4b12-880f-31777aa56cbf', 'es', 'Sit Up invertido con botas de gravedad', 'Colgado boca abajo con botas de gravedad, realiza una flexion abdominal completa elevando el torso hacia las rodillas.'),
('80924c7b-f2d8-45f5-84e1-64c52a472191', '6ca749b9-7255-4d7d-b9c6-a3b5a23e87ae', 'en', 'Cable Crossover for Mid Chest', 'Perform a cable crossover for the mid chest with the pulleys set at mid height. Bring the hands together in front of the chest while keeping a slight bend in the elbows and control the return.'),
('f18adc8d-760c-4770-b734-ef755f745c54', '6ca749b9-7255-4d7d-b9c6-a3b5a23e87ae', 'es', 'Cruce de poleas para pecho medio', 'Realiza un cruce de poleas para pecho medio colocando las poleas a una altura media. Junta las manos delante del pecho manteniendo una ligera flexión de codos y controla la vuelta.'),
('68be1232-fb85-4bc6-a44c-1672d0db922b', '6cd16910-0305-4a2a-9d36-0681daa4df4b', 'en', 'Band Assisted Pull-up', 'Hang an elastic band from the bar and place a foot or knee in it. Perform pull-ups with the help of the band''s rebound.'),
('206d95ac-1bab-4aa2-9417-7dc8dae0aada', '6cd16910-0305-4a2a-9d36-0681daa4df4b', 'es', 'Dominada asistida con banda', 'Cuelga una banda elástica de la barra y coloca un pie o rodilla en ella. Realiza dominadas con la ayuda del rebote de la banda.'),
('7d39c3d5-1be5-4b54-b9ca-c7781e477aec', '6cd2c05e-558b-431b-a010-c207f5c15e9c', 'en', 'Isometric Pallof Hold', 'Perform an isometric Pallof hold with a cable or band. Stand sideways to the anchor point, extend the arms in front of the chest, and resist rotation while keeping the trunk stable.'),
('12489a31-e1d5-4c34-8933-e9c56ae9b3da', '6cd2c05e-558b-431b-a010-c207f5c15e9c', 'es', 'Pallof isométrico', 'Realiza un Pallof isométrico con cable o banda. Colócate de lado al punto de anclaje, extiende los brazos delante del pecho y resiste la rotación manteniendo el tronco estable.'),
('574ab0af-c4fa-4bec-9937-b5fd0c1007ea', '6cfe1d1f-d4c8-491c-ab76-c26e76af7a57', 'en', 'Cocoon Crunch', 'Lie on your back and simultaneously tuck knees toward chest and lift torso to hug your legs, then return to the extended position.'),
('0c01979a-59b7-4595-b1e9-a95efba147a8', '6cfe1d1f-d4c8-491c-ab76-c26e76af7a57', 'es', 'Cocoon Crunch', 'Acuéstate boca arriba y, de forma simultánea, encoge las rodillas hacia el pecho y eleva el torso para abrazar tus piernas, regresando luego a la posicion extendida.'),
('680d874a-37b6-4117-98a5-9f18266b4999', '6d395b4d-6621-4002-b5ce-12d84a440b0b', 'en', 'TRX Atomic Pushup', 'Pushup + knees to chest in TRX. Objective: chest and core. Cue: fluid. Error: sagging lower back.'),
('05479501-bf90-4a98-a105-7b4b62278208', '6d395b4d-6621-4002-b5ce-12d84a440b0b', 'es', 'TRX Atomic Pushup', 'Flexión + rodillas pecho TRX. Objetivo: pecho y core. Cue: fluido. Error: hundir lumbar.'),
('9b5341a1-f85a-4d66-9f08-82a4489a3114', '6db5061c-7f9f-465c-a26f-5a363bb06578', 'en', 'Narrow Grip Barbell Floor Press', 'Floor press with hands together. Cue: elbows touch the floor softly. Error: bouncing.'),
('07b0b05b-6c51-4398-a768-e331a0c34b29', '6db5061c-7f9f-465c-a26f-5a363bb06578', 'es', 'Floor Press barra agarre estrecho', 'Press en suelo manos juntas. Cue: codos tocan suelo suave. Error: rebotar.'),
('2965d7a9-6186-4b1d-bc21-840ac3ccb4e7', '6e299057-5bbb-409c-bb26-a73b3d12f48e', 'en', 'Meadows Row', 'Using a landmine bar sideways, grab the thick end of the bar and row toward the side of the torso. Objective: upper back thickness. Cue: elbow out to emphasize rear deltoids. Error: rotating the lower back too much.'),
('b12ce241-e90f-4ca5-b864-9f83e9bf2e84', '6e299057-5bbb-409c-bb26-a73b3d12f48e', 'es', 'Remo Meadows', 'Uso de barra landmine de lado, agarra el extremo grueso de la barra y rema hacia el costado del torso. Objetivo: grosor de espalda alta. Cue: codo hacia afuera para enfatizar deltoides posterior. Error: rotar demasiado la espalda baja.'),
('83fdb235-94ba-4d39-ba18-a488a7c4e1c6', '6e2bf996-c5bf-4630-9924-9d915c67ace4', 'en', 'Lateral Lunge with Explosive Center Jump', 'Side step and return with a jump. Cue: push hard. Error: dragging the foot.'),
('5c589503-0bec-44ed-9767-a9f2c31abc66', '6e2bf996-c5bf-4630-9924-9d915c67ace4', 'es', 'Zancada lateral salto explosivo centro', 'Paso lateral y vuelve con salto. Cue: empuja fuerte. Error: arrastrar pie.'),
('138a6946-c9d9-4d14-a074-d003b02f3336', '6e324865-6fad-4fe3-bc98-b51ef5a43efd', 'en', 'Dumbbell Step Up to Bench', 'With a dumbbell in each hand, place one full foot on a bench or step. Push with the heel of the elevated foot to step up completely. Descend controlled with the same leg. Complete all reps on one side before switching.'),
('51f83bfe-b2dc-4735-842b-179e7e57a526', '6e324865-6fad-4fe3-bc98-b51ef5a43efd', 'es', 'Subida al banco mancuernas', 'Con una mancuerna en cada mano, coloca un pie completo sobre un banco o step. Empuja con el talón del pie elevado para subir completamente. Desciende controladamente con la misma pierna. Completa todas las repeticiones de un lado antes de cambiar.'),
('dc6253c2-819d-4e6c-aa11-82434463c377', '6e40678e-35d6-474e-b5ef-2c1429d1d7b3', 'es', 'Press Overhead de rodillas (Half Kneeling) con Kettlebell doble', 'En posición de caballero (una rodilla apoyada), realiza un press de hombros con dos pesas rusas, desafiando el equilibrio.'),
('058aa174-fdf6-4d2c-b1ec-4f496a6fcba3', '6e79b3cf-f092-43ef-bdfc-db15e425e6bf', 'en', 'Double Kettlebell Incline Bench Prone Row', 'Lying face down on an incline bench, row two kettlebells simultaneously toward the waist, contracting the lats.'),
('27531601-a4a2-4bc3-9e2f-fd2d0f6074b9', '6e79b3cf-f092-43ef-bdfc-db15e425e6bf', 'es', 'Remo prono en banco inclinado con Kettlebell doble', 'Tumbado boca abajo en un banco inclinado, rema dos pesas rusas simultaneamente hacia la cintura contrayendo los dorsales.'),
('35d70fb3-d8aa-4aac-9af1-0d0c6e26a065', '6ea29050-6872-4807-8737-1bd0a07a2769', 'en', 'Barbell Thruster', 'Hold the bar in a front rack position. Perform a deep squat and, upon rising, use the momentum to perform a shoulder press.'),
('75b510ad-f435-44fc-a1db-99b5327d656f', '6ea29050-6872-4807-8737-1bd0a07a2769', 'es', 'Thruster con barra', 'Sostén la barra en posición de rack frontal. Realiza una sentadilla profunda y, al subir, aprovecha el impulso para hacer un press de hombros.'),
('81085795-a7ca-4191-944b-979d332c64f2', '6ea57950-7ee9-40b4-b48d-993b669cd8bb', 'en', 'Low Pulley Front Raises', 'With back to the pulley, lift cable forward. Cue: straight arms. Error: arching lower back.'),
('fc2d4b71-fdd7-45c4-b189-a0fc00c4ab6a', '6ea57950-7ee9-40b4-b48d-993b669cd8bb', 'es', 'Elevaciones frontales polea baja', 'De espaldas, eleva cable al frente. Cue: brazos rectos. Error: arquear lumbar.'),
('2ba6ed3b-4cf4-4025-98c1-42ac4e925c12', '6ee199cb-d5ef-4494-a2ab-06365e25baa0', 'en', 'High Pulley Crunch (Kneeling)', 'Kneeling, hold the rope behind the neck and flex the torso toward the floor. Objective: weighted abdominals. Cue: exhale sharply on the way down. Common error: pulling with the arms instead of the abdomen.'),
('195deaee-7f03-496b-92af-68071892ceb7', '6ee199cb-d5ef-4494-a2ab-06365e25baa0', 'es', 'Crunch en polea alta (de rodillas)', 'De rodillas, sujeta la cuerda tras la nuca y flexiona el torso hacia el suelo. Objetivo: abdominales con carga. Cue: exhala fuerte al bajar. Error común: tirar con los brazos en lugar del abdomen.'),
('611862ac-134f-4278-83bf-d9e6ba037cba', '6f12cc9a-beae-4a8a-91c0-3ceadd40d7e3', 'en', 'Machine Row', 'Pull the machine handles toward the torso with the chest supported. Objective: upper back development. Cue: squeeze shoulder blades back. Common error: using body weight to jerk the weight.'),
('7034fd77-3b9e-4b0c-8ca3-1b471ab24d3e', '6f12cc9a-beae-4a8a-91c0-3ceadd40d7e3', 'es', 'Remo en máquina', 'Tira de los agarres de la máquina hacia el torso con el pecho apoyado. Objetivo: desarrollo de la espalda alta. Cue: junta las escápulas atrás. Error común: usar el peso del cuerpo para dar tirón.'),
('e1f903c6-7b92-4111-8286-4112a2eb28f6', '6f2b1074-174b-445e-a90f-958fe0485608', 'es', 'Press pecho máquina', 'Sentado o tumbado según el diseño, empuja los agarres hasta la extensión completa de brazos. La trayectoria fija de la máquina proporciona estabilidad, ideal para principiantes o para trabajar hasta el fallo de forma segura.'),
('e7b8efe6-a1df-4a96-bb0b-ca3148296245', '6f5122d2-3bee-4b22-9df7-7dc2e36754fd', 'en', 'Unilateral High Pulley Triceps Kickback', 'Without grip (cable only), extend the arm back while leaning. Objective: total triceps isolation. Cue: locked shoulder. Common error: moving elbow up and down.'),
('133ea64a-a931-4cff-a255-54cbc8296536', '6f5122d2-3bee-4b22-9df7-7dc2e36754fd', 'es', 'Patada de tríceps unilateral en polea alta', 'Sin agarre (solo cable), extiende el brazo hacia atrás inclinado. Objetivo: aislamiento total tríceps. Cue: hombro bloqueado. Error común: mover el codo arriba y abajo.'),
('b6dbfd84-339b-41e2-9d62-ded09d90abd1', '6f8e86f7-d621-4bce-abe8-78f10c4edf7d', 'en', 'Slider Knee Tuck', 'In a plank position with feet on sliders, tuck the knees toward the chest sliding your feet across the floor and return to the starting position.'),
('fcf8d99d-e3bd-4757-a7ff-b0144d530579', '6f8e86f7-d621-4bce-abe8-78f10c4edf7d', 'es', 'Knee Tuck con Slider', 'En posicion de plancha con los pies sobre sliders, encoge las rodillas hacia el pecho deslizando los pies por el suelo y vuelve a la posicion inicial.'),
('64307b6e-91ae-4e8a-99aa-6e53db03952e', '6f92eead-24f4-4e9c-ac1d-5cc915234081', 'en', 'Bodyweight Knee Hover Quadruped Fire Hydrant', 'Perform a hip abduction on all fours while keeping both knees off the ground, challenging core stability.'),
('03e7207c-c612-42bc-88c5-ef8d6b89ef4b', '6f92eead-24f4-4e9c-ac1d-5cc915234081', 'es', 'Fire Hydrant en cuadrupedia con rodilla flotante', 'Realiza una abduccion de cadera en cuadrupedia manteniendo ambas rodillas despegadas del suelo, desafiando la estabilidad del core.'),
('2b3c5b19-0b76-4913-baa9-6f5b3fc530f3', '6fa9504a-823c-43af-a070-3313861291ab', 'en', 'Mountain Climbers', 'In a high plank position, alternately bring knees toward the chest in a fast and continuous movement, as if running in a horizontal position. Keep hips low and core engaged. Increase speed for higher cardiovascular intensity and abdominal work.'),
('6f7af400-e605-4228-abeb-7291c1a30fbb', '6fa9504a-823c-43af-a070-3313861291ab', 'es', 'Mountain climbers', 'En posición de plancha alta, lleva alternadamente las rodillas hacia el pecho en un movimiento rápido y continuo, como si estuvieras corriendo en posición horizontal. Mantén las caderas bajas y el core activado. Aumenta la velocidad para mayor intensidad cardiovascular y trabajo abdominal.'),
('626d8db9-2a88-4fbd-934f-a57eb3fdce16', '6fead02c-0870-4e78-98fa-56984bfddfd6', 'en', 'Neutral Machine Row', 'Pull the handles toward you with palms facing each other. Cue: chest against the support. Error: using the feet to give momentum to the weight.'),
('4be5ba63-d901-45d4-ab12-dc6e6822df4e', '6fead02c-0870-4e78-98fa-56984bfddfd6', 'es', 'Remo en máquina neutro', 'Tira de los agarres hacia ti con palmas enfrentadas. Cue: pecho contra el soporte. Error: usar los pies para dar impulso al peso.'),
('2082f016-1208-445e-8262-1376f5d755f4', '6ff25618-18fd-402a-9e90-4fd89b734fc2', 'en', 'Prone Cobra on Fitball', 'Lie face down on the Fitball. Lift the torso and rotate arms outward with thumbs up, squeezing the shoulder blades.'),
('12f59831-8118-463e-945e-2d5c2062ce84', '6ff25618-18fd-402a-9e90-4fd89b734fc2', 'es', 'Cobra prono en Fitball', 'Acuéstate boca abajo sobre el Fitball. Levanta el torso y gira los brazos hacia afuera con los pulgares hacia arriba, apretando los omóplatos.'),
('d87a2486-ab01-43ba-af46-6a7aba898c30', '70017d8f-1365-456b-9a9d-8f7dd88813ad', 'en', 'Battle Ropes Slam Burpee', 'Full burpee ending with rope slams instead of a jump. Hold the ropes throughout the burpee or release and retake them. One of the most exhausting combinations. Requires mental endurance.'),
('dd1e5e23-10d6-43b5-9079-4612f121a9cd', '70017d8f-1365-456b-9a9d-8f7dd88813ad', 'es', 'Burpee golpeo battle ropes', 'Burpee completo terminando con slams de cuerdas en lugar de salto. Mantén las cuerdas durante todo el burpee o suéltalas y retómalas. Una de las combinaciones más agotadoras. Requiere resistencia mental.'),
('367b425c-ae80-4467-bfeb-02671cbca261', '70040fec-09f3-498f-ad55-bc3b823b27b6', 'en', 'Fitball Windshield Wipers', 'Lying on your back holding the Fitball with your feet, swing your legs from side to side without touching the floor to work the obliques.'),
('07fb4b21-eaad-49b8-9626-c9ac0e492a17', '70040fec-09f3-498f-ad55-bc3b823b27b6', 'es', 'Limpiaparabrisas con Fitball', 'Tumbado boca arriba sujetando el Fitball con los pies, balancea las piernas de lado a lado sin tocar el suelo para trabajar los oblicuos.'),
('6955eb02-f9f5-478a-8b6c-f4667e789147', '704ca888-3e20-450f-bee1-43be033fe608', 'en', 'Unilateral Standing Machine Hamstring Curl', 'Flex leg in vertical machine. Objective: hamstrings. Cue: hips glued. Error: lower back.'),
('53149df1-a116-4352-92f2-e9e50f3d933f', '704ca888-3e20-450f-bee1-43be033fe608', 'es', 'Curl femoral de pie unilateral máquina', 'Flexiona pierna máquina vertical. Objetivo: isquios. Cue: cadera pegada. Error: lumbar.'),
('ca3950ab-4734-44c1-b06b-ae7c15b2081b', '7057a50f-4a04-4463-9859-8d0a6990a050', 'es', 'Wall Sit con abducción de cadera y Minibanda', 'Realiza una sentadilla isométrica apoyado en la pared (Wall Sit) con una banda sobre las rodillas. Separa las rodillas contra la resistencia de la banda y vuelve a juntarlas sin perder la postura.'),
('1343a81e-2358-48f8-83df-647702830002', '70627e69-2bc3-49a1-ba37-f692d1226d2e', 'en', 'Slider Parallette Knee Tuck', 'Support yourself on parallettes and, with feet on sliders, slide your knees toward your chest in a controlled manner using the abdominals.'),
('3ab414e0-a7a9-4c78-ad7c-a3018b599fb2', '70627e69-2bc3-49a1-ba37-f692d1226d2e', 'es', 'Knee Tuck en paralelas con Slider', 'Sostente en las paralelas y, con los pies en sliders, desliza las rodillas hacia el pecho de forma controlada usando los abdominales.'),
('a8b726f7-c496-4a97-913c-882d15035805', '70767ff9-9adb-47cb-bc68-cf3ebad5c5bd', 'en', 'Wide Grip Pull-ups', 'Pull-ups with hands significantly wider than shoulder-width. Emphasizes the outer portion of the lats. Reduces bicep involvement. Harder than normal grip. Avoid excessively wide grip to protect shoulders.'),
('5897346c-4e3a-444a-8ff7-4d4c6e88e1c8', '70767ff9-9adb-47cb-bc68-cf3ebad5c5bd', 'es', 'Dominadas agarre amplio', 'Dominadas con las manos separadas significativamente más que el ancho de hombros. Enfatiza la porción externa de los dorsales. Reduce la participación del bíceps. Más difícil que el agarre normal. Evita agarre excesivamente amplio para proteger hombros.'),
('bcee0bb3-b098-4ed6-9506-2244d6fc84de', '709ef2d3-6fcb-4b84-803f-54a1892524ca', 'en', 'High Pulley Flyes', 'High pulleys, bring hands together below. Objective: lower chest. Cue: fixed elbows. Error: shrugging shoulders.'),
('7e9e56a3-1622-4e8f-81e5-f6b56f98f866', '709ef2d3-6fcb-4b84-803f-54a1892524ca', 'es', 'Aperturas polea alta', 'Poleas altas, junta manos abajo. Objetivo: pecho inferior. Cue: codos fijos. Error: encoger hombros.'),
('65f9e204-e7f4-4eab-afd7-65c44363904f', '70a32bae-e905-438e-8560-41fe6466635f', 'en', 'Bench Supported Row', 'Chest supported on an incline bench, row with dumbbells. Objective: back without lumbar load. Cue: squeeze shoulder blades. Error: lifting the chest off the bench.'),
('4e806a84-db03-421e-9242-7a76c1c9e8f8', '70a32bae-e905-438e-8560-41fe6466635f', 'es', 'Remo apoyado en banco', 'Pecho apoyado en banco inclinado, rema con mancuernas. Objetivo: espalda sin carga lumbar. Cue: junta escápulas. Error: despegar el pecho del banco.'),
('69e427d2-224b-435a-a853-cf3696e47472', '70cdf5dc-798f-4f73-b6df-99c1b9b22d7c', 'en', 'Assisted Hip Airplane', 'Perform an assisted hip airplane using a wall or support. Hinge on one leg, open and close the hip under control while maintaining balance and pelvic stability.'),
('747aa774-65be-439f-b42e-205cf59f23ab', '70cdf5dc-798f-4f73-b6df-99c1b9b22d7c', 'es', 'Hip airplane asistido', 'Realiza un hip airplane asistido apoyándote en una pared o soporte. Inclínate sobre una pierna, abre y cierra la cadera de forma controlada manteniendo el equilibrio y la pelvis estable.'),
('bdd4184c-9b1a-40cd-ae55-0a4373461f8e', '70da069f-4f76-4745-bba0-6cd87238c901', 'en', 'Lateral Bosu Plyometric Push Up', 'One hand on Bosu and one on the floor, jump explosively to switch positions. Cue: stabilize the shoulder on the Bosu. Common error: losing form due to instability.'),
('2debd0cd-ca25-4463-ba36-311d63e92f03', '70da069f-4f76-4745-bba0-6cd87238c901', 'es', 'Flexión pliométrica sobre bosu lateral', 'Una mano en bosu y otra en suelo, salta explosivamente para cambiar posiciones. Cue: estabiliza el hombro en el bosu. Error común: pérdida de forma por inestabilidad.'),
('38aa81a6-e8e3-4dc8-b98a-7410ff59be88', '70e6141b-4401-4fba-af8b-34fc10f21def', 'en', 'Single Arm Clubbell Outside Pullover', 'Bring the club from the same-side shoulder outward and upward in a controlled arc to improve joint stability.'),
('4d45342b-aa91-4161-a43e-7013ebab3e44', '70e6141b-4401-4fba-af8b-34fc10f21def', 'es', 'Outside Pullover con maza a una mano', 'Lleva la maza desde el hombro del mismo lado hacia afuera y arriba describiendo un arco controlado para mejorar la estabilidad articular.'),
('7cabf39e-36cc-48f4-ac70-d43e359b8953', '70fb35c8-7e06-4f96-b647-a3fd49cdf706', 'en', 'Lateral Ski Jump', 'Short and fast lateral jumps with feet together, imitating a skier. Cue: maintain a slightly leaned torso. Common error: separating feet too much.'),
('50b10e1f-2b81-44c2-bc19-b4227a080183', '70fb35c8-7e06-4f96-b647-a3fd49cdf706', 'es', 'Salto de esquí lateral', 'Saltos laterales cortos y rápidos con pies juntos, imitando un esquiador. Cue: mantén el torso ligeramente inclinado. Error común: separar demasiado los pies.'),
('5c041442-20ab-4910-a419-95b8b06d6dfe', '70fba0f6-2fdf-4ad0-8186-bd53e28c712d', 'en', 'Kneeling Kettlebell Hip to Halo', 'Kneeling, move the weight from one hip, cross it over the body and perform a halo around the head. Repeat alternating.'),
('ca6e93f0-a011-4cd5-a4d0-6078066b5dbf', '70fba0f6-2fdf-4ad0-8186-bd53e28c712d', 'es', 'Hip to Halo de rodillas con Kettlebell', 'De rodillas, mueve la pesa desde una cadera, crúzala por el cuerpo y realiza un halo alrededor de la cabeza. Repite alternando.'),
('8f50934c-1939-41b8-9e9e-b27b581cddc9', '712b6b30-5a83-4f0e-a59f-8406c8f3639c', 'en', 'Floor Diamond Push Ups', 'Hands together forming a diamond, elbows tucked. Cue: lower until chest touches hands. Error: flaring elbows out.'),
('0431590e-114d-43bd-bbd8-6af38ebaac50', '712b6b30-5a83-4f0e-a59f-8406c8f3639c', 'es', 'Flexiones diamante suelo', 'Manos juntas formando un diamante, codos pegados. Cue: baja hasta tocar las manos con el pecho. Error: abrir codos hacia afuera.'),
('e6ce6a94-b0b3-4b67-a07c-7c2271794db1', '712c0599-c83b-4d8f-9c4a-1ff63f739698', 'en', 'Knee Band Vertical Jump', 'Jump vertically with a circular band on knees to force abduction. Cue: push knees outward. Common error: knees collapsing when jumping.'),
('6b1ff250-5756-4266-bff1-7cb5bde085dd', '712c0599-c83b-4d8f-9c4a-1ff63f739698', 'es', 'Salto vertical banda rodillas', 'Salta verticalmente con banda circular en rodillas para forzar la abducción. Cue: empuja las rodillas hacia afuera. Error común: que las rodillas colapsen al saltar.'),
('8cefed38-e223-445a-8e8f-3adf2d759f4f', '71360d73-7747-4cf4-bfac-5ef8cdf812bc', 'en', 'Overhead Medicine Ball Lunge', 'Lunges while keeping the ball overhead with extended arms. Challenges core and shoulder stability while working the legs. Can be static or walking. Keep the ball stable.'),
('f13ee666-c31e-4f2d-9d99-ccfb73bfa569', '71360d73-7747-4cf4-bfac-5ef8cdf812bc', 'es', 'Zancada overhead balón medicinal', 'Zancadas manteniendo el balón sobre la cabeza con brazos extendidos. Desafía la estabilidad del core y hombros mientras trabajas las piernas. Puede ser estático o caminando. Mantén el balón estable.'),
('f059bbac-8a00-4e9d-a3f3-8f4e6c52aaba', '7140a93c-4856-4583-b468-1266ea17eeda', 'en', 'Double Kettlebell Push Press', 'With two kettlebells in rack position, slightly flex your knees and use leg drive to push the weights overhead.'),
('9bfd37d6-c5fc-435a-ac8a-350697852ed0', '7140a93c-4856-4583-b468-1266ea17eeda', 'es', 'Push Press con Kettlebell doble', 'Con dos pesas rusas en rack, flexiona ligeramente las rodillas y usa el impulso de las piernas para empujar las pesas sobre la cabeza.'),
('c83be48f-e7ff-45d4-a707-676e69ffa626', '71655f7f-df48-4c4f-b1ec-c992f1ed87e6', 'en', 'Cable Rope Tall Kneeling High to Low Chop', 'Kneeling sideways to the high pulley, pull the rope diagonally toward the opposite hip while rotating the torso in a controlled manner.'),
('86fe26c4-cc90-49b2-827b-cf7aeca5f725', '71655f7f-df48-4c4f-b1ec-c992f1ed87e6', 'es', 'Woodchop alto a bajo arrodillado con cuerda', 'Arrodillado de lado a la polea alta, tira de la cuerda diagonalmente hacia la cadera opuesta rotando el torso de forma controlada.'),
('e1f64144-47c3-42be-a205-07c7a4b323c9', '71721b34-d770-4db1-a37a-5f57946636f8', 'en', 'Alternating Double Dumbbell Prone Row', 'Lie face down on an incline bench and row the dumbbells alternately toward your hip, squeezing the lat on each ascent.'),
('5c2bb162-d9a3-47f1-8516-853398f0ecf0', '71721b34-d770-4db1-a37a-5f57946636f8', 'es', 'Remo prono alterno con mancuernas', 'Acuéstate boca abajo en un banco inclinado y rema las mancuernas alternativamente hacia tu cadera, apretando el dorsal en cada subida.'),
('ec476723-9cf2-4e8a-8172-d23319ddb0a1', '71b1124e-c2e8-4da7-90a6-d3455ed74d66', 'en', 'Hindu Push Up', 'Start in an inverted V position, lower the chest toward the floor performing an arc and end with the torso upright looking forward. Return to the starting position by reversing the arc. Objective: pushing strength and mobility. Cues: fluid and controlled movements. Common error: performing a normal push-up without the arching motion.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('1894ec09-bdde-4bfd-95a8-52936f109bf8', '71b1124e-c2e8-4da7-90a6-d3455ed74d66', 'es', 'Flexión hindú', 'Inicia en posición de V invertida, baja el pecho hacia el suelo realizando un arco y termina con el torso erguido mirando al frente. Vuelve a la posición inicial revirtiendo el arco. Objetivo: fuerza de empuje y movilidad. Cues: movimientos fluidos y controlados. Error común: realizar una flexión normal sin el movimiento de arco.'),
('3ba8cc19-d3e7-4e30-b57f-e304ed6fecc6', '71bdfdc9-98d9-4af4-9a4b-876a66648242', 'es', 'Plancha lateral rotación bajo cuerpo', 'En plancha lateral, pasa brazo por debajo. Cue: core firme. Error: bajar cadera.'),
('5a24568a-412a-403f-a022-d6830aedee0e', '72604f63-086b-4215-afd6-25710e5fba45', 'en', 'Barbell Deficit Deadlift', 'Perform a deadlift standing on a small platform to increase the initial range of motion and hamstring stretch.'),
('62ba8f9c-087f-4bf0-a9ee-9a54cbcaf4f2', '72604f63-086b-4215-afd6-25710e5fba45', 'es', 'Peso muerto con déficit con barra', 'Realiza un peso muerto subido a una plataforma pequeña para aumentar el rango de movimiento inicial y el estiramiento de isquiotibiales.'),
('4d21beb7-1d11-42bb-a956-b20ba195349d', '728ec8e8-8e0a-4efd-bc2c-eb8321c9b5d4', 'en', 'Explosive Squat', 'Lower into a squat and rise as fast as possible without feet leaving the floor. Cue: powerful push. Error: rounding the back.'),
('f91a8c68-e67e-44f4-8683-8cc5395f7bf7', '728ec8e8-8e0a-4efd-bc2c-eb8321c9b5d4', 'es', 'Sentadilla explosiva', 'Baja en sentadilla y sube lo más rápido posible sin despegar pies. Cue: empuje potente. Error: redondear espalda.'),
('13711cea-25ad-494f-8ef0-692547fabb49', '72a8be89-f41b-4d21-be3b-d8a70e9e1b16', 'en', 'Battle ropes lunges', 'Perform lunges while keeping the ropes in motion. They can be static, alternating, or walking. The coordination challenge is high. Keep the torso upright and the waves consistent.'),
('8c3fdfe9-1966-40c2-b1f6-16c2a8aa9a29', '72a8be89-f41b-4d21-be3b-d8a70e9e1b16', 'es', 'Battle ropes lunges', 'Realiza zancadas mientras mantienes las cuerdas en movimiento. Pueden ser estáticas, alternadas o caminando. El desafío de coordinación es alto. Mantén el torso erguido y las ondas consistentes.'),
('cbf5065a-8b19-46b4-830b-a265e6626dad', '72f740d2-4250-444c-8ebe-010372de6b64', 'es', 'Push Press a una mano con mancuerna', 'Realiza un press explosivo sobre la cabeza con una sola mancuerna, utilizando las piernas para generar potencia inicial.'),
('dc48ba5e-f2f7-4d97-9983-3eb332849ad9', '7346da1e-a553-4885-90bb-0f08fa651d24', 'en', 'Leaning Kettlebell Press', 'Overhead press while leaning laterally in the opposite direction. Intensely works the anti-lateral flexion core. Keep hips and shoulders square. Popular in strongman training.'),
('77f02f78-33ce-439a-b8ac-1acbd5d29148', '7346da1e-a553-4885-90bb-0f08fa651d24', 'es', 'Press inclinado kettlebell', 'Press overhead mientras te inclinas lateralmente en dirección opuesta. Trabaja el core anti-flexión lateral intensamente. Mantén cadera y hombros cuadrados. Popular en entrenamiento de strongman.'),
('5348549e-cb45-4ab9-97eb-9ba6a4a40761', '738eba83-c427-4cb2-95fd-bd97293afe11', 'en', 'Hip Thrust on Fitball', 'Support the upper back on the Fitball. Lower hips toward the floor and push up squeezing glutes until aligning the body.'),
('09a14ab9-8667-47f7-afcd-ce948560f082', '738eba83-c427-4cb2-95fd-bd97293afe11', 'es', 'Hip Thrust sobre Fitball', 'Apoya la parte superior de la espalda en el Fitball. Baja las caderas hacia el suelo y empuja hacia arriba apretando los glúteos hasta alinear el cuerpo.'),
('6ae117f9-386d-43e5-8ac6-e92eb6f60791', '73abfd11-93f3-438d-aaec-7b9dc444c94e', 'es', 'Pullover con mancuerna', 'Tumbado, lleva una mancuerna tras la cabeza con brazos casi rectos y vuelve. Objetivo: dorsal y serrato. Cue: codos fijos, no los dobles. Error común: arquear la espalda lumbar excesivamente.'),
('81c92189-8839-4caa-b0f3-0ba981b29a4f', '73d8d4c1-17b4-438e-932b-1146dff01470', 'en', 'Miniband Lateral Walks', 'Place a miniband around the legs and perform controlled lateral steps. Keep tension on the band, knees aligned, and hips stable.'),
('80ca133e-7244-48d8-9477-026ce62cf7f3', '73d8d4c1-17b4-438e-932b-1146dff01470', 'es', 'Pasos laterales con minibanda', 'Coloca una minibanda alrededor de las piernas y realiza pasos laterales controlados. Mantén tensión en la banda, rodillas alineadas y cadera estable.'),
('2975824f-f653-4a7e-af7b-887397824728', '73dfe53a-07a1-471b-802e-2a126376250e', 'es', 'Zancada estática pie bosu', 'Split squat con pie delantero en bosu. Objetivo: estabilidad. Cue: baja vertical. Error: tambaleo.'),
('5c394b34-4581-4f49-8bb9-4b460c533910', '73f8d356-ac8d-4a13-85b5-d83d2d115e98', 'en', 'Wall Slide Squat', 'Perform a squat by sliding your back against the wall to guide the movement, ensuring that the knees follow the line of the feet.'),
('6d858dfa-7ad8-4d78-8844-e8b6c2a102d6', '73f8d356-ac8d-4a13-85b5-d83d2d115e98', 'es', 'Sentadilla con deslizamiento en pared', 'Realiza una sentadilla deslizando la espalda contra la pared para guiar el movimiento, asegurando que las rodillas sigan la línea de los pies.'),
('4bb21b34-6a61-49a4-adc7-babbc8d0bea5', '74010f3a-7d9c-4df9-8d57-a0423097ebdd', 'en', 'Stability Ball Feet Elevated Frog Pump', 'Perform the frog pump movement with the soles of your feet together resting on the stability ball to increase instability and range of motion.'),
('83c2528f-3765-4d2c-aeb9-edd5cd5bc4dc', '74010f3a-7d9c-4df9-8d57-a0423097ebdd', 'es', 'Frog Pump con pies elevados en Fitball', 'Realiza el movimiento de Frog Pump con las plantas de los pies juntas y apoyadas sobre el Fitball para aumentar la inestabilidad y el rango de movimiento.'),
('280ea39f-dcbc-4840-b745-dcf785d229f1', '744c6d7d-f066-43f3-9243-3e97b6718959', 'en', 'Kettlebell Juggling', 'Controlled kettlebell tosses and catches. Includes flips, rotations, and passes. Develops coordination, timing, and grip strength. Start with a light kettlebell. Requires space and a safe surface.'),
('72b3e3dd-0b00-4314-8c10-abd46e0320ab', '744c6d7d-f066-43f3-9243-3e97b6718959', 'es', 'Malabares kettlebell', 'Lanzamientos y recepciones controladas de kettlebell. Incluye flips, rotaciones y pases. Desarrolla coordinación, timing y fuerza de agarre. Comienza con kettlebell ligera. Requiere espacio y superficie segura.'),
('a38483ac-3855-4c02-800d-e9e871b1fd70', '74513de3-f39b-4e31-9de1-930178d94ff4', 'en', 'Double Kettlebell Spider Curl', 'Perform a bicep curl leaning face down on an incline bench using two kettlebells for a different grip stimulus.'),
('fc3e6835-edc2-494c-aa73-23cc2bcba467', '74513de3-f39b-4e31-9de1-930178d94ff4', 'es', 'Spider Curl con Kettlebell doble', 'Realiza un curl de biceps apoyado boca abajo en un banco inclinado utilizando dos pesas rusas para un estimulo de agarre diferente.'),
('f5b043d5-8e3d-48da-8b75-706f9df1240e', '745b4404-e943-4ed3-9ff3-05c900d224ee', 'en', 'Machine Adductor Controlled Closure', 'Close legs while seated. Cue: control the opening. Error: quick movements.'),
('0128053f-701b-4d55-8d96-0d9a468b3f86', '745b4404-e943-4ed3-9ff3-05c900d224ee', 'es', 'Máquina aductores cierre controlado', 'Cierra piernas sentado. Cue: controla apertura. Error: movimientos rápidos.'),
('1d73f18f-ac75-4c39-986c-fc48e2bdd89f', '749fbc0d-8ad2-4639-8ab2-04aba803047f', 'en', 'Squat Thrust', 'From a standing position, descend into a squat and place hands on the floor. Jump both feet back into a plank position in one explosive movement. Immediately jump feet back toward hands and stand up. Similar to a burpee but without the push-up or final jump.'),
('c934ef13-369f-46fe-8f21-6c4ce47ffbcc', '749fbc0d-8ad2-4639-8ab2-04aba803047f', 'es', 'Squat thrust', 'Desde posición de pie, desciende a sentadilla y coloca las manos en el suelo. Salta con ambos pies hacia atrás a posición de plancha en un movimiento explosivo. Inmediatamente salta con los pies de vuelta hacia las manos y levántate. Es similar al burpee pero sin flexión ni salto final.'),
('c3588107-cde8-4982-b9b0-fea8233b8a31', '74ac50f3-eac2-4947-b0a3-8fda4bc64ac6', 'es', 'Zancada con salto y cambio de altura', 'Salta desde el suelo para aterrizar en zancada sobre un escalón o banco bajo. Potencia de elevación. Rodilla alineada. Evita movimientos inestables del pie.'),
('77f11b4d-356f-4caf-8e1d-47f41f493abb', '74b0c425-1d99-4f7c-afbd-3dd52b2fa02e', 'en', 'Barbell Clean and Jerk', 'Two-phase Olympic lift: first a clean to bring the bar to the shoulders, followed by a jerk to bring it overhead. The jerk can be split or power. Requires exceptional power, coordination, and technique.'),
('06ae958c-c579-4c4d-b706-99000a58132f', '74b0c425-1d99-4f7c-afbd-3dd52b2fa02e', 'es', 'Envión barra', 'Levantamiento olímpico de dos fases: primero una cargada para llevar la barra a los hombros, seguida de un jerk (empuje) para llevarla sobre la cabeza. El jerk puede ser split (tijera) o power (pies paralelos). Requiere potencia, coordinación y técnica excepcionales.'),
('36d71165-6fa3-4ada-b901-32b9b9cbb133', '74b2dde1-43b5-4ce2-8480-45aeb87b5008', 'en', 'Goblet Squat', 'Squat with a goblet pattern without load (or minimal) to warm up the hip/knee and practice depth with control.'),
('3132af8e-8816-4c66-b38a-d0c505bc1db5', '74b2dde1-43b5-4ce2-8480-45aeb87b5008', 'es', 'Goblet squat (peso corporal)', 'Pies firmes, rodillas siguen la línea de los pies, torso estable. Baja controlado y sube empujando el suelo.'),
('89b1ba4c-d2be-436d-986d-ccefb3523cdd', '754a70c6-88f7-426d-bcc6-2003582e1819', 'en', 'Barbell Standing Rollout', 'From a standing position, roll the barbell forward extending your body completely until close to the floor and return.'),
('81c6f420-08b6-4b97-88b6-a4c009420408', '754a70c6-88f7-426d-bcc6-2003582e1819', 'es', 'Rollout de pie con barra', 'Desde posicion de pie, desplaza la barra hacia adelante extendiendo el cuerpo por completo hasta quedar cerca del suelo y regresa.'),
('b1eb51db-4767-4569-a92b-04ee78eea0be', '758f4763-9993-4693-a881-9eadd8148b0d', 'en', 'One-Leg Medicine Ball Slam', 'Slam ball standing on one leg. Extreme balance and stabilization challenge. Keep the supporting knee slightly flexed. Alternate legs. The core must work intensely to maintain stability.'),
('0a54e575-e60b-47fb-9ea0-ec2cb9e37995', '758f4763-9993-4693-a881-9eadd8148b0d', 'es', 'Golpeo una pierna balón medicinal', 'Slam ball parado en una pierna. Desafío extremo de equilibrio y estabilización. Mantén la rodilla de apoyo ligeramente flexionada. Alterna piernas. El core debe trabajar intensamente para mantener estabilidad.'),
('9fc9489a-b2ab-4ca0-9706-2d872df11d8f', '75a8a86f-37a8-485e-8995-f183a603b52e', 'es', 'Zancada frontal mancuernas', 'Paso adelante con pesas. Objetivo: cuádriceps. Cue: rodilla 90 grados. Error: levantar talón.'),
('3e5412fb-7aee-400c-9b90-53c85b212bf0', '75ae55c2-f790-4c54-9a7c-1b15c32236b0', 'en', 'Slow Controlled Mountain Climbers', 'Knee to elbow holding for 2 seconds. Objective: stable core. Cues: do not move hips. Common error: lifting glute.'),
('ad1ca006-a396-4a89-9c03-a05a83f4c59d', '75ae55c2-f790-4c54-9a7c-1b15c32236b0', 'es', 'Escaladores lentos controlados', 'Rodilla a codo manteniendo 2 segundos. Objetivo: core estable. Cues: no muevas cadera. Error común: elevar glúteo.'),
('6cc72ea1-2d3a-4f23-b0b3-3a784d0a4e5c', '75cb1f33-b763-4166-9e73-67d7160c0c13', 'en', 'Superband Hollow Body Hold', 'Perform a hollow body hold while pulling on an elastic band anchored behind you, forcing greater abdominal contraction.'),
('5eebbd3e-ba3c-491d-ae71-bb7d293a819e', '75cb1f33-b763-4166-9e73-67d7160c0c13', 'es', 'Hollow Body Hold con banda elástica', 'Realiza un Hollow Body mientras tiras de una banda elástica anclada detrás de ti, forzando una mayor contracción abdominal.'),
('817ba243-e520-4c7a-943c-5a8dc1ce4f1c', '75cd62f1-1af7-4a06-bf6b-fc16f44037d4', 'en', 'Alternating Kettlebell Halo', 'Hold the kettlebell by the horns upside down. Make controlled circles around your head, keeping the core firm.'),
('adcd9aba-01ef-4fcf-b1ec-7518a08746b3', '75cd62f1-1af7-4a06-bf6b-fc16f44037d4', 'es', 'Halo alterno con Kettlebell', 'Sostén la pesa rusa por los cuernos boca abajo. Haz círculos controlados alrededor de tu cabeza, manteniendo el core firme.'),
('8252ff9c-ba28-4954-85b5-89c1c3b9477d', '75de208a-6ded-452c-bdf0-ce4fd8a65a2e', 'en', 'Floor Seated One-Arm Cable Lat Pulldown', 'Sit on the floor. Pull the high pulley with one hand toward your side, maximizing range of motion and lat stretch.'),
('6999ffc5-247c-4e24-a018-ae0c7328f13b', '75de208a-6ded-452c-bdf0-ce4fd8a65a2e', 'es', 'Jalón al pecho sentado en suelo con cable a una mano', 'Siéntate en el suelo. Tira de la polea alta con una mano hacia el costado, maximizando el rango de movimiento y el estiramiento del dorsal.'),
('cf54c59d-4af2-4dd8-abfd-c310ecfca938', '76001fc6-39c4-466f-afea-e699ee218671', 'es', 'Zancada atrás con déficit', 'Desde escalón hacia atrás. Objetivo: mayor rango glúteo. Cue: baja controlado. Error: desequilibrio.'),
('3bc53b7c-6ae2-4572-af4f-334fea534d4f', '7603f63f-be6c-4a58-b7f0-da2a7aa876d6', 'en', 'TRX Chest Fly', 'Leaning forward, open arms laterally holding the TRX handles. Objective: chest with instability. Cue: rigid body at all times. Common error: flexing elbows too much, turning it into a press.'),
('2f2e4df1-7c88-4caf-84f2-181cf9cb600e', '7603f63f-be6c-4a58-b7f0-da2a7aa876d6', 'es', 'TRX Chest Fly', 'Inclinado adelante, abre los brazos lateralmente sujetando los agarres de TRX. Objetivo: pectoral con inestabilidad. Cue: cuerpo rígido en todo momento. Error común: flexionar demasiado los codos convirtiéndolo en un press.'),
('5128d420-57ec-4278-8fd2-60609739f3b8', '7658c5d0-2587-44ae-a11f-edeacfd4efb3', 'en', 'Slam Ball', 'Lift the ball overhead and slam it against the ground with maximum force. Pick it up on the bounce and repeat. Full body exercise that develops power and is excellent for stress relief. Use legs and core.'),
('9565d638-7ec2-475d-8bc5-1fad5275eeb7', '7658c5d0-2587-44ae-a11f-edeacfd4efb3', 'es', 'Slam ball', 'Eleva el balón sobre la cabeza y golpéalo contra el suelo con máxima fuerza. Recógelo al rebotar y repite. Ejercicio de cuerpo completo que desarrolla potencia y es excelente para liberar estrés. Usa las piernas y el core.'),
('254a9f9d-d9b0-48dc-bbf7-0b8c2965f0f6', '767c497e-e210-434d-b9bd-1ec500892ec7', 'en', 'Superband Prone Shoulder Dislocates', 'Lying face down, hold the band and pass it from your glutes to in front of your head without your arms touching the floor.'),
('20a3ca58-975e-4386-a5c8-64c900eb75d6', '767c497e-e210-434d-b9bd-1ec500892ec7', 'es', 'Dislocaciones de hombro prono con banda', 'Tumbado boca abajo, sujeta la banda y pasala desde tus gluteos hasta por delante de tu cabeza sin que los brazos toquen el suelo.'),
('aae4f43e-d1f8-451b-9f32-fa4fdc4a43c4', '7684725c-cbd5-43c5-8763-dbb69b39ec20', 'en', 'Unilateral Kettlebell Swing', 'One-arm swing. Objective: power and core. Cue: switch arms in the air. Error: rotating shoulder.'),
('fc0e10c0-39dd-4361-ba87-78c130b62011', '7684725c-cbd5-43c5-8763-dbb69b39ec20', 'es', 'Kettlebell Swing unilateral', 'Swing a una mano. Objetivo: potencia y core. Cue: cambio brazo en aire. Error: rotar hombro.'),
('0aee2c6d-86e8-49c1-b62e-1c4f91ddd228', '7692f01b-eb1a-467e-ac6f-7513e87cb665', 'en', 'Slider Single Leg Eccentric Hamstring Curl', 'In a single-leg bridge position, slowly slide the heel forward on the slider controlling the descent until the leg is fully extended.'),
('450a49d2-15cf-43b6-b9a5-b7fc1675cd18', '7692f01b-eb1a-467e-ac6f-7513e87cb665', 'es', 'Curl excéntrico de isquiotibiales a una pierna con Slider', 'En posición de puente a una pierna, desliza el talón lentamente hacia adelante sobre el slider controlando el descenso hasta estirar la pierna por completo.'),
('7cbaee5c-2acd-4103-b270-97044a1787fb', '76a867a9-c370-40ad-9854-7b0f882702ae', 'en', 'Double Kettlebell Bottoms Up Overhead Squat', 'Deep squat while maintaining two upside-down kettlebells locked out overhead, requiring absolute stability control.'),
('8dc5f23b-0a3b-419c-82c5-590af4761656', '76a867a9-c370-40ad-9854-7b0f882702ae', 'es', 'Sentadilla Overhead con Kettlebell doble Bottoms Up', 'Sentadilla profunda manteniendo dos Kettlebells invertidas bloqueadas sobre la cabeza, requiere un control absoluto de la estabilidad.'),
('11db8be4-3add-40b4-be96-bc96670ee9f5', '76a991ff-9ae2-4b69-8577-b5e5db483421', 'es', 'Push Jerk con Kettlebell doble', 'Impulsa dos pesas rusas con las piernas y métete debajo flexionando las rodillas de nuevo para recibirlas con brazos bloqueados.'),
('7548973a-3c13-4c66-a812-d966d5d8cca3', '76aae0e2-8d2b-4785-99fe-8d2a90ac1794', 'en', 'Iron Cross', 'On rings, maintain a vertical body with arms extended horizontally forming a cross. Classic gymnastics ring element. Requires exceptional strength and specific preparation of connective tissue. Progress with assistance.'),
('a42f6b49-d84e-4589-b541-d8eb77273b30', '76aae0e2-8d2b-4785-99fe-8d2a90ac1794', 'es', 'Cruz de hierro', 'En anillas, mantén el cuerpo vertical con brazos extendidos horizontalmente formando una cruz. Elemento clásico de gimnasia en anillas. Requiere fuerza excepcional y preparación específica de tejido conectivo. Progresa con asistencias.'),
('6a175e89-aa38-4b32-8b97-e3399c349bf0', '76ea1bcb-ad23-4e1c-a0ac-a9e01b120342', 'en', 'Dynamic Lateral Lunges', 'Move to one side lowering the hip and return to the center. Cue: firm straight leg. Error: tilting the torso laterally.'),
('d78088fd-bc1f-453d-adde-78888e4ab30c', '76ea1bcb-ad23-4e1c-a0ac-a9e01b120342', 'es', 'Zancadas laterales dinámicas', 'Desplázate a un lado bajando la cadera y vuelve al centro. Cue: pierna estirada firme. Error: inclinar el torso lateralmente.'),
('dacaa8ac-1d4b-42a5-9ec3-c05d43eef359', '770a0099-7b86-4062-a037-3639273ca2fe', 'en', 'Alternating Front Rack Dumbbell Cossack Squat', 'Perform alternating lateral squats holding two dumbbells in rack position on the shoulders.'),
('1e82ff8e-6e1d-43f4-9a3d-3faaa09f0880', '770a0099-7b86-4062-a037-3639273ca2fe', 'es', 'Sentadilla cosaca alterna Front Rack con mancuernas', 'Realiza sentadillas laterales alternas sosteniendo dos mancuernas en posicion de rack sobre los hombros.'),
('768e99ba-b868-450c-b736-2b3b161e3ab9', '770a81bd-4aa7-40e2-91ac-9d8bc26859ba', 'en', 'Straight Bar Cable Triceps Extension', 'Push the bar down locking the elbows. Cue: elbows glued to the body. Error: moving shoulders.'),
('6996e901-e94f-43f5-b8c9-962389368c8a', '770a81bd-4aa7-40e2-91ac-9d8bc26859ba', 'es', 'Extensión tríceps polea barra recta', 'Empuja barra hacia abajo bloqueando codos. Cue: codos pegados al cuerpo. Error: mover hombros.'),
('3059bae8-97f7-437f-ac61-b6cafb726f1c', '7717c59f-81fd-4871-a1aa-ad8580312ed8', 'en', 'Seated Neutral Dumbbell Shoulder Press', 'Palms facing each other, push weights up. Cue: elbows forward. Error: clashing weights.'),
('dc2f1875-b801-4db1-b12b-4a29d3f098f5', '7717c59f-81fd-4871-a1aa-ad8580312ed8', 'es', 'Press hombros sentado neutro mancuernas', 'Palmas enfrentadas, empuja pesas arriba. Cue: codos al frente. Error: chocar pesas.'),
('249a44d3-933c-4b82-9664-c191be26dc09', '7752875b-baff-49f5-a847-d05703009f7b', 'en', 'Kettlebell Horn Grip Skater Squat', 'Hold the kettlebell by the horns in front of your chest and lower into a single-leg squat, keeping the torso upright and balanced.'),
('ff97e382-1cec-4de5-b33c-929d10160534', '7752875b-baff-49f5-a847-d05703009f7b', 'es', 'Sentadilla patinadora con agarre de bocina y pesa rusa', 'Sujeta la Kettlebell por los cuernos frente al pecho y baja en sentadilla sobre una pierna, manteniendo el torso erguido y equilibrio.'),
('5e9cc64e-3fab-4837-8681-88d43332cfb7', '7757754c-0b0c-49d7-8e89-fd7f84ed9b79', 'en', 'Straight-Arm Superman', 'Face down, lift chest and legs off the floor simultaneously. Objective: spinal erectors. Cue: look toward the floor to protect the neck. Common error: performing sudden movements or head jerks.'),
('74f1ccb2-773b-4d5f-a750-318ca24e2a59', '7757754c-0b0c-49d7-8e89-fd7f84ed9b79', 'es', 'Superman brazos estirados', 'Boca abajo, eleva pecho y piernas del suelo simultáneamente. Objetivo: erectores espinales. Cue: mira hacia el suelo para proteger el cuello. Error común: realizar movimientos bruscos o tirones de cabeza.'),
('257b8cfe-9f99-43b3-a0c6-ee3bbda65284', '778d98af-f001-447d-9be3-0943e5287d1f', 'en', 'Alternating Double Kettlebell Cyclist Thruster', 'Execute a squat with heels elevated and, upon rising, perform a vertical press alternating the pushing arm each rep.'),
('f7e8b396-f915-4102-af5c-93600aa473c0', '778d98af-f001-447d-9be3-0943e5287d1f', 'es', 'Thruster Ciclista alterno con Kettlebell doble', 'Ejecuta una sentadilla con talones elevados y, al subir, realiza un press vertical alternando el brazo que empuja en cada repeticion.'),
('f8b7090e-b779-43cd-83a0-6270070b69ef', '779b34a8-91d9-416f-bca6-455c5f3d5a47', 'en', 'Barbell Deficit Deadlift', 'Perform conventional deadlift from an elevated platform of 5-10 cm. This deficit increases range of motion and exercise difficulty. Requires greater mobility and strength in the starting position. Excellent for improving floor strength.'),
('9ac4347e-ea80-4f8c-afbd-499acb9b2b61', '779b34a8-91d9-416f-bca6-455c5f3d5a47', 'es', 'Peso muerto deficitario barra', 'Realiza el peso muerto convencional desde una plataforma elevada de 5-10 cm. Este déficit aumenta el rango de movimiento y la dificultad del ejercicio. Requiere mayor movilidad y fuerza en la posición inicial. Excelente para mejorar la fuerza desde el suelo.'),
('e474a733-2ec5-42fe-bab0-85d5a95f8b70', '779dab4a-d6be-4966-b781-d73091213231', 'en', 'One-Arm Dumbbell Thruster', 'Perform a Thruster (squat + press) holding a single dumbbell on one side, maintaining core balance.'),
('b742396c-4c9c-4b53-8ae3-64fc19239dcb', '779dab4a-d6be-4966-b781-d73091213231', 'es', 'Thruster con mancuerna a un brazo', 'Realiza un Thruster (sentadilla + press) sosteniendo una sola mancuerna en un lado, manteniendo el equilibrio del core.'),
('b5ec0857-fe2e-4f9f-a2ec-95ffb803093f', '77cebf45-71b1-456f-b47b-756891e6654c', 'en', 'Alternating Single Arm Kettlebell Swing', 'Perform a swing with a single arm and switch the kettlebell to the other hand at the peak of the arc, in front of your face.'),
('75b30788-ad1b-4d0c-81e9-cbbff9f3d05f', '77cebf45-71b1-456f-b47b-756891e6654c', 'es', 'Swing con Kettlebell alterno a una mano', 'Realiza un swing con un solo brazo e intercambia la pesa rusa de mano en el punto mas alto del arco, frente al rostro, manteniendo el ritmo.'),
('b0d92d0a-de3f-437e-8798-b29624f915ae', '77d9f84c-8c1d-465e-82d7-1247d9b3bad1', 'es', 'Puente de glúteo con marcha', 'En puente de glúteo, eleva una pierna y luego la otra sin bajar la cadera. Cue: estabilidad de pelvis. Error: que la cadera caiga al levantar un pie.'),
('945a10f6-824e-469d-95a1-133b95f91f5b', '77f7bdd3-41f9-4477-8207-05183160d4ca', 'en', 'Narrow Grip Barbell Bicep Curl', 'Flex bar with hands close for long head focus. Cue: fixed elbows. Error: swinging the torso.'),
('980b9a58-ff4a-49e3-9e59-5d17f24e533d', '77f7bdd3-41f9-4477-8207-05183160d4ca', 'es', 'Curl bíceps barra agarre estrecho', 'Flexiona barra manos juntas para cabeza larga. Cue: codos fijos. Error: balancear el torso.'),
('c6f55586-d8d9-4321-b22f-eeab0ac99b89', '77f94dc1-be9e-411f-96d2-e3ffd4d65ead', 'en', 'Ring Eccentric Chin Up', 'With a supine grip (palms toward you), jump to the top position. Lower slowly while controlling the descent until arms are straight.'),
('7896afd6-905e-4a7b-a78f-7e4d830d929d', '77f94dc1-be9e-411f-96d2-e3ffd4d65ead', 'es', 'Chin Up excéntrico en anillas', 'Con agarre supino (palmas hacia ti), salta a la posición superior. Baja lentamente controlando el descenso hasta estirar los brazos.'),
('16a7d26f-7b17-4e57-ba82-4584eed13432', '782c0c6c-0b88-43e1-b4da-c9db0148db90', 'en', 'Decline Dumbbell Flyes', 'Open arms on a decline bench. Objective: lower chest. Cue: control the opening. Error: clashing weights.'),
('d398bcd6-46d7-4da2-8a17-decfd0186d92', '782c0c6c-0b88-43e1-b4da-c9db0148db90', 'es', 'Aperturas declinadas mancuerna', 'Abre brazos banco declinado. Objetivo: pecho inferior. Cue: controla apertura. Error: chocar pesas.'),
('c47e7f5e-cf73-4795-8465-06b9db36f947', '783e6de0-dd60-4e71-ac59-52a8613daf30', 'en', 'Sumo Squat', 'Adopt a stance wider than shoulder-width with toes pointing out at a 45-degree angle. Descend while keeping the knees aligned with the toes. This variation emphasizes glute and adductor work. Keep the torso upright throughout the movement.'),
('4cb814b6-7cb2-46bc-8a9d-c4fe079e7c60', '783e6de0-dd60-4e71-ac59-52a8613daf30', 'es', 'Sentadilla sumo', 'Adopta una postura más amplia que el ancho de los hombros con los pies apuntando hacia afuera en un ángulo de 45 grados. Desciende manteniendo las rodillas alineadas con las puntas de los pies. Esta variación enfatiza más el trabajo de glúteos y aductores. Mantén el torso erguido durante todo el movimiento.'),
('f6fd49f0-f02c-4180-ba4e-3662afba42a4', '784a57da-d944-4a67-aee6-1c980d86f8da', 'en', 'Kettlebell Russian Twist', 'Seated with knees bent, rotate your torso side to side moving a kettlebell in front of your abdomen without touching the floor.'),
('97933217-3ce3-4dcb-aba3-75db49213b4e', '784a57da-d944-4a67-aee6-1c980d86f8da', 'es', 'Russian Twist con Kettlebell', 'Sentado con rodillas flexionadas, gira el torso de lado a lado moviendo una Kettlebell frente al abdomen sin tocar el suelo.'),
('95a71b7b-6839-4a8d-8e55-1660e6f3d665', '7851f266-2ae8-4fcd-8220-54d71d65323b', 'en', 'Side Lying Hip Adduction', 'Lying on your side, lift the lower leg crossing in front of the upper one. Objective: adductor strength. Cue: keep the body aligned. Common error: bending the knee of the active leg.'),
('f3743511-aeb4-4d15-a25f-79ea3140134f', '7851f266-2ae8-4fcd-8220-54d71d65323b', 'es', 'Aducción de cadera tumbado lateral', 'Tumbado de lado, eleva la pierna inferior cruzando por delante de la superior. Objetivo: fuerza de aductores. Cue: mantén el cuerpo alineado. Error común: doblar la rodilla de la pierna activa.'),
('ccb84087-07b3-49a7-ba2b-f4b5d6b6a8ca', '786be329-a465-4141-b887-83ab0847d181', 'es', 'Zancada inversa alterna en TRX', 'Sujeta el TRX y da un paso largo hacia atrás bajando la rodilla trasera hacia el suelo. Alterna de pierna en cada repetición.'),
('777bd63d-2a19-4499-89c7-37bf019f15ed', '789d6817-95ca-4d52-86c4-d30fb567f426', 'en', 'Medicine Ball Mountain Climbers', 'Mountain climbers with hands on a medicine ball. Instability multiplies core work. Keep the ball stable while alternating knees. Controlled speed to maintain correct form.'),
('a9175566-5c81-4eb1-8a74-cecf652d42ad', '789d6817-95ca-4d52-86c4-d30fb567f426', 'es', 'Escalador balón medicinal', 'Mountain climbers con manos sobre balón medicinal. La inestabilidad multiplica el trabajo del core. Mantén el balón estable mientras alternas rodillas. Velocidad controlada para mantener forma correcta.'),
('2bb8cac9-f8ba-423f-8513-a0001ff288f0', '78a7a4d6-4b32-4376-89b3-93848de6af8f', 'en', 'Barbell Triceps Pushdown', 'Push the pulley bar down locking the elbows. Objective: triceps isolation. Cue: keep chest high and shoulders back. Common error: using body weight to push.'),
('31545d5b-9670-47df-ac30-ee9403f4890d', '78a7a4d6-4b32-4376-89b3-93848de6af8f', 'es', 'Tríceps pushdown con barra', 'Empuja la barra de la polea hacia abajo bloqueando los codos. Objetivo: aislamiento del tríceps. Cue: mantén el pecho alto y hombros atrás. Error común: usar el peso del cuerpo para empujar.'),
('6b17fff2-407f-4718-afc6-948899884c74', '78e5e76f-ff40-4113-99c5-5b6f5e54d588', 'es', 'Puente de Glúteo con pies elevados', 'Acuéstate con los talones en un banco. Eleva la cadera hacia el techo apretando los glúteos y baja de forma controlada.'),
('34997a47-e7ba-4df1-91ba-c347a884f244', '78f058eb-afb0-4ef8-939d-9854340d6fdc', 'en', 'Double Dumbbell Half Kneeling Seesaw Overhead Press', 'In a half-kneeling position, alternate the vertical press with dumbbells, using the core to prevent any lateral swaying of the torso.'),
('ad097a86-cdd4-4037-a7a8-bb4481b05bb6', '78f058eb-afb0-4ef8-939d-9854340d6fdc', 'es', 'Press Overhead Seesaw medio arrodillado con mancuernas', 'En posición de caballero, alterna el press vertical con mancuernas, utilizando el core para evitar cualquier balanceo lateral del torso.'),
('c9563edf-7ff9-455a-b48c-3a936ff2642c', '78f40a83-3c22-4aee-ab39-d5b4d9f7f5f5', 'en', 'Dumbbell Crush Grip Otis Up', 'Lie down holding a dumbbell with both hands against the chest (squeezing it). Perform a full sit-up and press the dumbbell upward at the end of the movement.'),
('3a5f426a-63b9-4053-ae05-87f006173ae7', '78f40a83-3c22-4aee-ab39-d5b4d9f7f5f5', 'es', 'Otis Up con agarre Crush', 'Acuéstate sosteniendo una mancuerna con ambas manos contra el pecho (apretándola). Realiza un sit-up completo y presiona la mancuerna hacia arriba al final del movimiento.'),
('bd6fbc41-604d-4861-842f-567c9650e259', '79037792-e636-42a6-b4a7-3fbc9bd486e5', 'es', 'Zancada de péndulo', 'Realiza una zancada frontal y, sin apoyar el pie al volver, pasa directamente a una zancada trasera. Objetivo: equilibrio y fuerza de piernas. Cues: torso erguido en todo el recorrido. Error común: movimientos rápidos y descontrolados.'),
('550b6571-b2ec-4f53-b497-675cc4a94c60', '79211d39-f918-4fd0-8e45-f28e88a5c4e1', 'en', 'Supinated Grip Machine Lat Row', 'Pull toward the abdomen with palms up. Cue: elbows tucked. Error: shrugging traps.'),
('6549008b-7881-4e4a-be81-73324e167aba', '79211d39-f918-4fd0-8e45-f28e88a5c4e1', 'es', 'Remo máquina agarre supinado dorsal', 'Tira hacia abdomen palmas arriba. Cue: codos pegados. Error: encoger trapecios.'),
('83f8d064-eba6-4a87-9be7-5ffaa6e0c73a', '7929e200-80e7-4484-adfa-ea9097877a30', 'es', 'Puente de glúteo a una pierna', 'Acuéstate con una rodilla doblada y la otra pierna estirada en el aire. Empuja con el talón apoyado para elevar la cadera usando solo un glúteo.'),
('f777b90a-6a4f-4b4d-8666-ac763e8ed281', '793ba3a8-46dd-4742-8165-898633ae70e7', 'en', 'Overhead Double Kettlebell Slider Lateral Lunge', 'Hold two kettlebells locked overhead and slide one foot laterally on a slider, lowering the hip with absolute control.'),
('6d4ffe50-ff4b-49e5-acd1-3fb13a3c3de9', '793ba3a8-46dd-4742-8165-898633ae70e7', 'es', 'Zancada lateral Overhead con Slider y Kettlebell doble', 'Sostén dos Kettlebells bloqueadas sobre la cabeza y desliza un pie lateralmente sobre un slider, bajando la cadera con control absoluto.'),
('adc7d273-0f8f-411f-99c1-74985a0c543e', '793d2816-a09d-434f-b1c7-59e800d9ae2f', 'es', 'Plank lateral con mancuerna', 'En posición de Plank lateral, sostén una mancuerna con el brazo libre extendido hacia el techo. Mantén la posición estable y las caderas elevadas.'),
('2f357bc0-3569-4d50-b232-e5fe3b5c50d2', '7998ce21-1b86-4e31-b612-5c82b8ebbc75', 'en', 'Vertical Jump with Ball Toss', 'Jump seeking height and toss a ball upward simultaneously. Total power. Soft landing. Do not lose sight of the ball.'),
('30a7d728-241c-4aa7-803e-47bd9208f019', '7998ce21-1b86-4e31-b612-5c82b8ebbc75', 'es', 'Salto vertical con lanzamiento de balón', 'Salta buscando altura y lanza el balón hacia arriba simultáneamente. Potencia total. Aterrizaje suave. No pierdas de vista el balón.'),
('787de2be-090f-445a-a89e-47785bd55659', '799959de-c667-48d8-95e2-f2436487ff80', 'es', 'Zancada con rotación de balón', 'Realiza una zancada y gira el balón hacia el lado de la pierna adelantada. Coordinación. Espalda erguida. No dejes que la rodilla baile.'),
('444a1ec5-6160-4bcf-9ccc-aa7d39a4c95a', '79aec148-b057-4598-aa7c-537ae69ac7da', 'en', 'Staggered Stance Sledgehammer Slam', 'With one foot in front of the other, hit a tire with a heavy sledgehammer using a full arc motion, activating the core and shoulders.'),
('34e415b0-eb0f-41a4-9901-6b02225fcf3e', '79aec148-b057-4598-aa7c-537ae69ac7da', 'es', 'Slam de martillo en postura escalonada', 'Con un pie delante del otro, golpea un neumatico con un martillo pesado usando un movimiento de arco completo, activando el core y los hombros.'),
('517c4bce-e306-4215-8982-ac7866d9c294', '79c85823-3ebb-440f-acdd-c6e4dc8defc8', 'en', 'Reverse Barbell Bicep Curl', 'Flex bar with palms down. Objective: forearm. Cue: firm grip. Error: too much weight.'),
('281f27d0-0ed6-4c43-82e3-166678293552', '79c85823-3ebb-440f-acdd-c6e4dc8defc8', 'es', 'Curl bíceps invertido barra', 'Flexiona barra palmas abajo. Objetivo: antebrazo. Cue: agarre firme. Error: mucho peso.'),
('e0732264-b9f2-4fe2-92df-929c8cac15a1', '79c97c65-7378-4ebf-bb5d-ce96d1696f83', 'en', 'Battle ropes figure 8', 'Create figure-eight patterns with the ropes. Requires coordination and movement control. Can be done vertically or horizontally. Keep the pattern wide and fluid for maximum effectiveness.'),
('2d68edb6-162a-42f9-ad21-add287920250', '79c97c65-7378-4ebf-bb5d-ce96d1696f83', 'es', 'Battle ropes figure 8', 'Crea patrones en forma de ocho con las cuerdas. Requiere coordinación y control del movimiento. Puede hacerse vertical u horizontalmente. Mantén el patrón amplio y fluido para máxima efectividad.'),
('b4fe9903-1008-4ea8-9867-833ae956dafd', '79f46dda-fde0-40f1-bc77-da8d9d41cddd', 'es', 'Peso muerto rumano en Landmine', 'De pie frente al extremo de la barra, inclina el torso hacia adelante empujando la cadera atrás para trabajar los isquiotibiales con un peso guiado.'),
('a92af24b-6c59-4b93-84f2-90e0084dade3', '7a0552b2-63c8-49b9-86ee-38729674818c', 'en', 'Single Arm Landmine Shoulder Press', 'Hold the end of the bar over one shoulder and press forward and up in an arc following the bars natural path.'),
('ad8402fe-97ed-4782-9480-ae80f85ae6b6', '7a0552b2-63c8-49b9-86ee-38729674818c', 'es', 'Press de hombros a una mano en Landmine', 'Sujeta el extremo de la barra sobre un hombro y presiona hacia adelante y arriba en arco siguiendo la trayectoria natural de la barra.'),
('b05de542-8f48-4cc4-a9b5-9e90f916546d', '7a0ebb8b-9b67-4e38-b6a5-1b7ca9c873a2', 'es', 'Press Z alterno (Seesaw) con Kettlebell', 'Sentado en el suelo, realiza un press alterno continuo (uno sube, otro baja) manteniendo el tronco rígido y sin arquear la espalda.'),
('f5a851b4-dece-41f4-a007-a74e36bb59a3', '7a141405-d610-4b5e-a14f-df97883b115c', 'en', 'Single Arm Dumbbell Power Snatch', 'Drive a dumbbell from the floor to overhead in a single explosive motion, using leg power.'),
('bb79550a-5016-4565-bee9-61f424ad6fad', '7a141405-d610-4b5e-a14f-df97883b115c', 'es', 'Power Snatch a una mano con mancuerna', 'Lleva una mancuerna desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, usando la potencia de las piernas.'),
('4b3d2f5b-dd38-4d43-bee6-2260238c4c91', '7a21316c-9d02-43bf-b544-f594aaf3cb41', 'es', 'Press Z alterno con Kettlebell', 'Sentado en el suelo con piernas en V, realiza press de hombros alternando brazos, manteniendo el torso perfectamente vertical.'),
('669f9f3d-14fb-443d-b4da-ae555e45a9ab', '7a653e30-eb21-4f60-9137-aef96df16655', 'en', 'Superman', 'Lie face down with arms extended forward. Simultaneously lift chest, arms, and legs off the floor by contracting the lower back and glutes. Hold the position for a second looking at the floor to avoid hyperextending the neck. Lower controlled and repeat.'),
('2fbf2c35-4194-4d15-82f6-202a45d6ba9e', '7a653e30-eb21-4f60-9137-aef96df16655', 'es', 'Superman', 'Túmbate boca abajo con brazos extendidos al frente. Simultáneamente eleva el pecho, brazos y piernas del suelo contrayendo la espalda baja y glúteos. Mantén la posición por un segundo mirando al suelo para no hiperextender el cuello. Desciende controladamente y repite.'),
('7559ae90-5b29-4d63-87b7-0fa226c07edb', '7a68eea8-6138-4fb1-9df6-c9c681d0626d', 'en', 'Single Arm Landmine Row to Rotational Shoulder Press', 'Row the bar to your side and, in one fluid motion, rotate your body to finish by pressing the load overhead.'),
('0db38780-df9e-4e4d-9da0-b6f116e17a5e', '7a68eea8-6138-4fb1-9df6-c9c681d0626d', 'es', 'Remo a una mano a press rotacional en Landmine', 'Rema la barra hacia tu costado y, en un movimiento fluido, gira el cuerpo para terminar presionando la carga sobre la cabeza.'),
('4464ac8f-129c-4e20-8e45-3a5e50531323', '7a8f22e0-f24f-43fd-9c36-4daf6cf4a350', 'en', 'Machine Chest Press', 'Seated, push the handles forward. Total control. Cue: keep scapulae retracted against the bench. Error: lifting shoulders when pushing.'),
('0c347f4c-dcfa-4725-ae1f-ef56c08e2d93', '7a8f22e0-f24f-43fd-9c36-4daf6cf4a350', 'es', 'Press de pecho en máquina', 'Sentado, empuja los agarres hacia adelante. Control total. Cue: mantén escápulas retraídas contra el banco. Error: despegar hombros al empujar.'),
('95214fc1-d7a8-4a9b-89ee-f7636e371240', '7acb3a77-e350-4d26-beb7-c29f635077de', 'en', 'Single Arm Kettlebell Pendlay Row', 'With the torso parallel to the ground, explosively lift the kettlebell from the floor toward the hip and return it to a dead stop.'),
('a0347ec3-b71d-46d2-92ce-d8712c09a4ed', '7acb3a77-e350-4d26-beb7-c29f635077de', 'es', 'Remo Pendlay a una mano con Kettlebell', 'Con el torso paralelo al suelo, levanta explosivamente la pesa rusa desde el suelo hacia la cadera y regrésala a una parada muerta.'),
('29469684-d910-4b1a-8f0b-729f5b0a6aeb', '7adcb5d1-2898-47c8-826c-87010b5c9ade', 'en', 'Prone Dumbbell Row', 'Lie face down on a flat or slightly inclined bench. Row the dumbbells upward contracting the back.'),
('74f7d1ac-ba34-4977-abec-e15991312e6c', '7adcb5d1-2898-47c8-826c-87010b5c9ade', 'es', 'Remo prono con mancuernas', 'Acuéstate boca abajo en un banco plano o ligeramente inclinado. Rema las mancuernas hacia arriba contrayendo la espalda.'),
('385046ec-d9f9-4c23-ac0d-ed91f0292b99', '7ae257a3-bf9c-46b6-b40c-5c395c0e1ed7', 'en', 'Lateral Rollout', 'Roll at a 45-degree diagonal angle to each side. Emphasizes obliques while maintaining rectus abdominis work. Control the return to center. Keep hips square to maximize lateral work.'),
('d9992cda-7339-45d4-8ed0-0c3c29d50120', '7ae257a3-bf9c-46b6-b40c-5c395c0e1ed7', 'es', 'Rodamiento lateral', 'Rueda en ángulo diagonal de 45 grados hacia cada lado. Enfatiza oblicuos mientras mantiene trabajo del recto abdominal. Controla el retorno al centro. Mantén caderas cuadradas para maximizar el trabajo lateral.'),
('666ca8bf-c86a-42f9-91ea-7091a5d15e27', '7aeb3023-7574-4328-811e-70527cad2b97', 'en', 'One-Arm Swing', 'Swing with only one hand increasing the anti-rotation challenge. Allows for a greater range of motion. The free arm can be extended for balance. Alternate hands each set or within the set.'),
('c7527ccd-0384-4086-8aeb-f359ad63a6ac', '7aeb3023-7574-4328-811e-70527cad2b97', 'es', 'Swing un brazo', 'Swing con una sola mano aumentando el desafío anti-rotación. Permite mayor rango de movimiento. El brazo libre puede estar extendido para balance. Alterna manos cada serie o dentro de la serie.'),
('618f7fcc-c492-478b-8b34-526e8cb70244', '7bcfdcdf-17c6-4da6-b4b7-b7caec119318', 'es', 'Plancha lateral con pierna elevada', 'En plancha lateral, sube y baja la pierna superior. Estabilidad y fuerza. Cadera alta. No dejes caer el cuerpo adelante.'),
('23d56911-aa93-4708-bd21-a1e44ff19f61', '7bdb28a2-b0a1-4740-8a9d-b27d42182c8f', 'en', 'Cable Face Pull', 'Standing in front of a high pulley with a rope, pull the ends toward the face, separating hands and rotating shoulders externally.'),
('797de442-7ce8-47c7-9cb5-27d09f675f2c', '7bdb28a2-b0a1-4740-8a9d-b27d42182c8f', 'es', 'Face Pull con cable', 'De pie frente a la polea alta con cuerda, tira de los extremos hacia la cara separando las manos y rotando los hombros externamente.'),
('c9b0ff5d-6392-4bae-8943-ddb86465ec90', '7bdfb502-306e-4382-9198-07cda9fa6863', 'en', '30-Degree Incline Flyes', 'Open arms on a slight incline bench. Cue: elbows bent. Error: clashing weights.'),
('cc9c529e-65fe-4762-a90b-0d490ecc4465', '7bdfb502-306e-4382-9198-07cda9fa6863', 'es', 'Aperturas inclinadas 30 grados', 'Abre brazos en banco inclinado suave. Cue: codos flexionados. Error: chocar pesas.'),
('72c6f8a5-f8eb-4098-afc8-5c5233ddb72e', '7bedcfcd-ac74-4ae3-b9dd-0cb9189bdde6', 'en', 'One-Arm Cable Row', 'Unilateral row allowing controlled torso rotation. More functional than a strict row. Rotation should come from the core, not momentum. Excellent for racket sports and martial arts.'),
('9a5950cc-a9d5-4327-a260-71d6f970bca5', '7bedcfcd-ac74-4ae3-b9dd-0cb9189bdde6', 'es', 'Remo un brazo cable', 'Remo unilateral permitiendo rotación controlada del torso. Más funcional que remo estricto. La rotación debe venir del core, no de impulso. Excelente para deportes de raqueta y artes marciales.'),
('5d7d7a05-98c6-4dcc-9bff-cd9934a811f2', '7c043ada-815d-4b19-b7cf-f218dc0bbdaa', 'es', 'Posición L en anillas', 'Mantén posición de L-sit en anillas. La inestabilidad añade dificultad significativa comparado con paralelas. Requiere fuerza de core y estabilización de hombros. Progresa desde L-sit en paralelas o suelo primero.'),
('15377634-de6b-4596-aa39-da2487b3f4f3', '7c39058e-4149-45e4-bfba-8a78a82e9679', 'es', 'Woodchoppers cable', 'Con polea alta o baja, realiza un movimiento diagonal de rotación como si cortaras leña. Involucra todo el core con énfasis en oblicuos. Mantén los brazos relativamente extendidos y rota desde el torso, no solo los brazos.'),
('4560022b-c14a-4778-9916-0ccfe6872dec', '7c7a058e-2e5f-4420-80f1-0ff6585363f0', 'en', 'Hack Squat', 'On the hack machine, with the back supported on the inclined backrest, perform squats. This position reduces stress on the lower back while maintaining high quadriceps activation. Vary foot position for different emphasis.'),
('a19aaa95-8534-45c7-8b97-f3bb44e04a56', '7c7a058e-2e5f-4420-80f1-0ff6585363f0', 'es', 'Sentadilla hack', 'En la máquina hack, con la espalda apoyada en el respaldo inclinado, realiza sentadillas. Esta posición reduce el estrés en la espalda baja mientras mantiene alta activación de cuádriceps. Varía la posición de pies para diferentes énfasis.'),
('167f4939-b34e-4b00-8959-8d87c005e4ee', '7c7facbf-3e32-463d-9552-e159344a1e1d', 'es', 'Power Clean a Press de hombros con barra', 'Realiza una cargada de potencia (Clean) para llevar la barra a los hombros y termina con un press militar por encima de la cabeza.'),
('04c3a8dd-6504-4fff-94a2-281756f678cb', '7c937659-1b65-4230-8254-23c8ccbe1fb0', 'en', 'High Pulley Crunch', 'Kneeling, hold the rope behind the neck and flex the torso toward the floor. Objective: weighted abdominals. Cue: exhale on the way down and squeeze the core. Common error: pulling the cable with the arms.'),
('cc2c09fb-df55-4e76-86f7-24a812a4f6b4', '7c937659-1b65-4230-8254-23c8ccbe1fb0', 'es', 'Crunch en polea alta', 'De rodillas, sujeta la cuerda tras la nuca y flexiona el torso hacia el suelo. Objetivo: abdominales con carga. Cue: exhala al bajar y aprieta el core. Error común: tirar del cable con los brazos.'),
('cdce7b00-d74f-4a54-9133-884685ce0017', '7c94e492-8027-4aae-880d-df2688abcbb3', 'en', 'Dumbbell Deadlift', 'With a dumbbell in each hand in front of the thighs, hinge from the hips keeping the back straight and knees slightly flexed. Lower dumbbells close to legs until feeling hamstring stretch. Rise by contracting glutes.'),
('7a311df7-19dd-46d5-b9a5-3eef75dc2b2d', '7c94e492-8027-4aae-880d-df2688abcbb3', 'es', 'Peso muerto mancuernas', 'Con una mancuerna en cada mano frente a los muslos, inclínate desde las caderas manteniendo la espalda recta y las rodillas ligeramente flexionadas. Desciende las mancuernas cerca de las piernas hasta sentir estiramiento en isquiotibiales. Vuelve arriba contrayendo glúteos.'),
('e2a05c94-7970-4a22-bbc7-3b73df692540', '7cb2c054-3696-42f2-a684-53306b4d53f1', 'en', 'Barbell Sumo Back Squat', 'Perform a squat with the bar behind the neck and a wide foot stance, emphasizing work on the adductors and glutes.'),
('c200d1b5-2672-4af2-a5f4-d25ec1a8bd0a', '7cb2c054-3696-42f2-a684-53306b4d53f1', 'es', 'Sentadilla trasera Sumo con barra', 'Realiza una sentadilla con la barra tras la nuca y una apertura de pies ancha, enfatizando el trabajo en los aductores y glúteos.'),
('73bbca7e-a469-49f7-ae6d-4102fa914c7c', '7ccb4d55-1b09-40ca-8a59-e2861ef05d0b', 'en', 'Kettlebell Cossack Squat', 'With the weight at the chest, descend to one side keeping the other leg straight and the heel on the floor. Objective: unilateral strength and hip mobility. Cues: chest high and knee aligned with the foot. Common error: lifting the heel of the supporting leg.'),
('e7d59b47-f2af-493e-afc7-e5aa948fa449', '7ccb4d55-1b09-40ca-8a59-e2861ef05d0b', 'es', 'Sentadilla cosaca con kettlebell', 'Con la pesa al pecho, desciende hacia un lado manteniendo la otra pierna estirada y el talón en el suelo. Objetivo: fuerza unilateral y movilidad de cadera. Cues: pecho alto y rodilla alineada con el pie. Error común: levantar el talón de la pierna de apoyo.'),
('d8455e2a-5ee5-4806-a27e-d8613ca52cf5', '7cea55ec-6545-4d2d-9f4a-332694fcaa21', 'es', 'TRX Sentadilla a una pierna (Pistol)', 'Sujeta los agarres para equilibrio y realiza una sentadilla profunda con una pierna. Espalda recta. Rodilla alineada. No despegues el talón del suelo.'),
('e7a4f1ce-54f3-4413-86e0-ad33525fc8c1', '7d18da46-6ed1-4a3a-b92f-19d26c630d09', 'en', 'V-Grip Low Pulley Row', 'Pull the V-handle toward the abdomen while seated. Cue: straight back, elbows back. Error: swinging the torso.'),
('dc029710-5b22-4dfa-8d27-d44b8e4d6f94', '7d18da46-6ed1-4a3a-b92f-19d26c630d09', 'es', 'Remo en polea baja agarre V', 'Tira del agarre hacia el abdomen sentado. Cue: espalda recta, codos atrás. Error: balancear el torso.'),
('8a2f20f3-1f03-42f9-8f37-a194f92d779e', '7d2dc762-7636-42b6-80db-a484add05d1c', 'en', 'Alternating Single Arm Landmine Thruster', 'Perform a squat while holding the end of the bar with one hand and, as you stand, press it overhead, alternating arms each rep.'),
('7697f5e1-3b9f-4363-8606-558ac9b99b74', '7d2dc762-7636-42b6-80db-a484add05d1c', 'es', 'Thruster alterno a una mano en Landmine', 'Realiza una sentadilla sosteniendo el extremo de la barra con una mano y, al subir, presiónala sobre la cabeza, alternando brazos en cada repetición.'),
('c5eacc84-c4bb-4916-95b2-14d7105a41b9', '7d887ccc-ea95-479b-bc19-3992b3139a5f', 'en', 'Cable Pallof Press', 'Standing perpendicular to the cable at chest height, extend arms forward resisting rotation. It''s an anti-rotation exercise that strengthens the core functionally. Hold the extended position for 2-3 seconds before returning.'),
('a4c5c7cd-e6d2-471d-a2c3-8e4c68338c44', '7d887ccc-ea95-479b-bc19-3992b3139a5f', 'es', 'Pallof press cable', 'De pie perpendicular al cable a la altura del pecho, extiende los brazos al frente resistiendo la rotación. Es un ejercicio anti-rotación que fortalece el core de manera funcional. Mantén la posición extendida 2-3 segundos antes de volver.'),
('35618434-6d34-4ddf-b846-c53270d0225f', '7dbe994b-b905-4a78-b706-b8e07ef9ec11', 'es', 'Push Jerk alterno con mancuernas', 'Alterna el movimiento de jerk sobre la cabeza con mancuernas, combinando potencia explosiva y estabilidad unilateral.'),
('153ed806-fbb1-4eb0-8595-bcb49d2b7284', '7e1a76a7-3ee3-4cdd-99cb-ab8ff78984af', 'en', 'Side Lying Leg Elevation', 'Lying on your side, lift the upper leg without rotating the hip upward. Objective: abductors and gluteus medius. Cues: toes pointing forward. Common error: turning toes toward the ceiling.'),
('9e3654ac-5152-4912-b97b-510e131ff2d1', '7e1a76a7-3ee3-4cdd-99cb-ab8ff78984af', 'es', 'Elevación de pierna lateral tumbado', 'Tumbado de lado, eleva la pierna superior sin rotar la cadera hacia arriba. Objetivo: abductores y glúteo medio. Cues: punta del pie mirando al frente. Error común: girar la punta del pie hacia el techo.'),
('45a3fbc2-a259-4685-bf95-d556bbcc6798', '7e2136ba-837d-49fe-8b90-7f86789dd408', 'en', 'Double Kettlebell Bottoms Up Seesaw Bench Press', 'Lying on the bench, alternate the press of two upside-down kettlebells, requiring extreme grip control and shoulder stability.'),
('72a1a92e-15dd-4d61-a41f-fb520b7df6e7', '7e2136ba-837d-49fe-8b90-7f86789dd408', 'es', 'Press de banca Seesaw con Kettlebell doble Bottoms Up', 'Tumbado en el banco, alterna el press de dos Kettlebells invertidas, exigiendo un control extremo del agarre y la estabilidad de hombros.'),
('943ec7f7-6c1e-4543-9a70-7eb7d452e422', '7ea0aa64-6216-4e41-8380-62611d2212bb', 'en', 'One-Arm Front Rack Dumbbell Squat', 'Hold a dumbbell on one shoulder (rack position) and perform a deep squat, resisting the asymmetrical load.'),
('e4f20486-b32f-43f5-a9f1-edc3035587d2', '7ea0aa64-6216-4e41-8380-62611d2212bb', 'es', 'Sentadilla Front Rack con mancuerna a una mano', 'Sostén una mancuerna sobre un hombro (posición de rack) y realiza una sentadilla profunda, resistiendo la carga asimétrica.'),
('e735f1de-98d0-43a8-a246-ea3309a0adb7', '7ebc2744-710b-4ef0-9db6-a7e84b22fb72', 'en', 'Parallette Full Planche', 'Hold your body completely horizontal and parallel to the floor on the parallettes, supported only by the hands with locked arms.'),
('17d2e347-b034-4a5a-9000-466724410ad4', '7ebc2744-710b-4ef0-9db6-a7e84b22fb72', 'es', 'Plancha completa paralela', 'Sostén el cuerpo completamente horizontal y paralelo al suelo sobre las paralelas, apoyado solo en las manos con los brazos bloqueados.'),
('deca05e1-dc9d-4246-b506-51e348b9b6da', '7efd11a1-1f6c-420d-a0a5-591588cfcca0', 'en', 'Diamond Push Up', 'In a push-up position, bring hands together forming a diamond with index fingers and thumbs. Lower the chest toward the hands keeping the elbows close to the body.'),
('9527fd3c-1d47-4ef7-b589-6a5b8dbb863c', '7efd11a1-1f6c-420d-a0a5-591588cfcca0', 'es', 'Push Up diamante', 'En posición de flexión, junta las manos formando un diamante con índices y pulgares. Baja el pecho hacia las manos manteniendo los codos pegados al cuerpo.'),
('a29fe1a4-471f-42ed-afd6-20c8374ee863', '7fca143d-e31b-4ca0-8cce-3067a40df7c8', 'en', 'T-Bar Row', 'With one end of the bar anchored, hold the other end with a V-grip and pull toward your chest. Objective: back density. Cue: flat back always. Error: using jerks from the lower back to rise.'),
('26fcd88e-1964-4dd1-a49d-40489e4d508f', '7fca143d-e31b-4ca0-8cce-3067a40df7c8', 'es', 'Remo en punta con barra (T-Bar Row)', 'Con un extremo de la barra anclado, sujeta el otro extremo con un agarre en V y tira hacia tu pecho. Objetivo: densidad de espalda. Cue: espalda plana siempre. Error: dar tirones con la espalda baja para subir.'),
('257b7047-80bc-4c4d-a1ca-557f0737cab1', '7fd10d5e-9761-4d7e-8b67-155fc527148e', 'en', 'Incline Barbell Press 30-45 Degrees', 'Chest press on incline bench with barbell. Cue: bar to upper chest. Error: lowering to the neck.'),
('7f0ff8e5-0fb8-455a-b780-891ee74fdec7', '7fd10d5e-9761-4d7e-8b67-155fc527148e', 'es', 'Press inclinado con barra 30-45 grados', 'Press de pecho en banco inclinado con barra. Cue: barra a parte alta pecho. Error: bajar al cuello.'),
('e0a13861-de80-4f2c-b664-41d395919e86', '7ffac95d-e282-4db0-9b2f-0be42484918c', 'en', 'Double Kettlebell Alternating Cossack Squat Thruster', 'Alternating deep lateral squat with kettlebell overhead press, combining maximum mobility and vertical power.'),
('216d5bc4-cff7-49c5-969a-69c4bd3b4d74', '7ffac95d-e282-4db0-9b2f-0be42484918c', 'es', 'Thruster Cosaco alterno con Kettlebell doble', 'Sentadilla lateral profunda alternada con press de Kettlebells sobre la cabeza, combinando maxima movilidad y potencia vertical.'),
('fbebd87f-1096-4f38-b241-e2ecc2cb1ec8', '8000b248-ad8b-4af4-9d53-7f866a11eb72', 'en', 'Leg Elevated Crunches', 'Legs at 90 degrees, lift shoulders. Cue: lower back against the floor. Error: pulling on the neck.'),
('fd3778a5-2640-4f52-bba6-2e213df8c711', '8000b248-ad8b-4af4-9d53-7f866a11eb72', 'es', 'Crunches piernas elevadas', 'Piernas a 90 grados, eleva hombros. Cue: lumbar contra el suelo. Error: tirar del cuello.'),
('8a22ce03-f390-4ac1-b4cb-744bc3e2c3ae', '800f81e6-1b5f-41d7-824e-28ecc8ad6858', 'en', 'Barbell Hip Thrust', 'Heavy barbell hip thrust for maximum overload. Use a pad for comfort. The bench should be at shoulder blade height. Pause at maximum contraction. One of the best exercises for glute development.'),
('b1e6be02-4d2a-4177-949d-2927e19e8f85', '800f81e6-1b5f-41d7-824e-28ecc8ad6858', 'es', 'Empuje cadera con barra', 'Hip thrust con barra pesada para máxima sobrecarga. Usa pad para comodidad. El banco debe estar a la altura de los omóplatos. Pausa en la contracción máxima. Uno de los mejores ejercicios para desarrollo de glúteos.'),
('b52aaddb-ff13-4b65-a995-601559830a4f', '802f1714-6e1a-415a-b94e-558edb8e2a86', 'en', 'Maltese', 'Extreme planche variation with arms fully extended laterally forming a cross. Considered one of the hardest elements in gymnastics. Requires superhuman shoulder strength and years of specific preparation.'),
('f668466b-355d-4e6d-a237-5a3386faf3ea', '802f1714-6e1a-415a-b94e-558edb8e2a86', 'es', 'Maltese', 'Variación extrema del planche con brazos completamente extendidos lateralmente formando una cruz. Considerado uno de los elementos más difíciles en gimnasia. Requiere fuerza sobrehumana en hombros y años de preparación específica.'),
('f5b8d38e-252c-4cf3-bdf3-32451d5737d1', '802f2689-7499-488e-acb9-f8d69679f728', 'en', 'Push Up with Shoulder Tap', 'Perform a push-up and, when rising, tap the opposite shoulder with one hand while maintaining stability. Objective: core and pectoral. Cue: do not swing hips when tapping the shoulder. Error: lifting glutes too high.'),
('a353b12b-0788-4ea8-b556-a54400ce3d25', '802f2689-7499-488e-acb9-f8d69679f728', 'es', 'Flexión de brazos con toque de hombro', 'Realiza una flexión y, al subir, toca el hombro opuesto con una mano manteniendo la estabilidad. Objetivo: core y pectoral. Cue: no balancees la cadera al tocar el hombro. Error: elevar demasiado el glúteo.'),
('4f46503b-fcfc-4237-82d6-47d4291a36d5', '806727d5-048b-4629-8a79-0ddcb0c9ab40', 'en', 'Low Machine Row', 'Rowing variation with a more horizontal trajectory. Can be seated or standing leaning forward depending on the design. Works the back from a different angle than the high row. Keep chest up and shoulder blades active.'),
('204b70fa-1af2-4061-929c-ab0f4017ea5c', '806727d5-048b-4629-8a79-0ddcb0c9ab40', 'es', 'Remo bajo máquina', 'Variación de remo con trayectoria más horizontal. Puede ser sentado o de pie inclinado según el diseño. Trabaja la espalda desde un ángulo diferente al remo alto. Mantén el pecho elevado y los omóplatos activos.'),
('2f314765-39e2-4571-a498-03eb2ee77759', '80a77509-1a10-46c3-b63b-6d16e25a5130', 'en', 'Double Kettlebell Turkish Sit Up', 'Perform a sit up while keeping two kettlebells extended vertically over your chest, demanding great abdominal control.'),
('80f84b97-6db0-4c89-97e2-ded8df184981', '80a77509-1a10-46c3-b63b-6d16e25a5130', 'es', 'Turkish Sit Up con Kettlebell doble', 'Realiza un sit up manteniendo dos Kettlebells extendidas verticalmente sobre el pecho, exigiendo un gran control abdominal.'),
('5083d71b-9b9b-4850-b333-4a8947af2267', '80ad72c7-0936-40e1-b918-92177809dff3', 'es', 'Woodchoppers balón', 'Movimiento diagonal de arriba hacia abajo simulando cortar leña. Comienza con el balón sobre un hombro y llévalo diagonalmente hacia la cadera opuesta. Involucra todo el core con énfasis en oblicuos. Mantén los brazos extendidos.'),
('54b1f3b0-e2b3-4239-a1c0-1e4921d906d6', '80b40d0a-a5a1-492f-9af5-847243aefdc9', 'en', 'Hip Thrust', 'Support the upper part of the back on a bench with feet firmly planted on the floor. From this elevated position, descend hips and then push explosively upward contracting glutes. In the top position, the torso should be parallel to the floor. Keep chin toward chest.'),
('bbd2ad01-4d6d-45b1-ac62-ae328a46a02c', '80b40d0a-a5a1-492f-9af5-847243aefdc9', 'es', 'Hip thrust', 'Apoya la parte superior de la espalda en un banco con los pies firmemente plantados en el suelo. Desde esta posición elevada, desciende las caderas y luego empuja explosivamente hacia arriba contrayendo los glúteos. En la posición superior, el torso debe estar paralelo al suelo. Mantén la barbilla hacia el pecho.'),
('5ce49e4e-f73d-4b57-8db4-306a32aae058', '80c1aad1-1252-465e-8b1c-3c831de76e34', 'en', 'Dumbbell Shrugs', 'With a heavy dumbbell in each hand at the sides, lift shoulders toward ears as high as possible. Hold contraction for one second and lower controlled. Avoid rotating shoulders; movement should be purely vertical.'),
('93464838-0a51-4e95-87b7-8d8984360125', '80c1aad1-1252-465e-8b1c-3c831de76e34', 'es', 'Shrugs mancuernas', 'Con una mancuerna pesada en cada mano a los lados, eleva los hombros hacia las orejas lo más alto posible. Mantén la contracción por un segundo y desciende controladamente. Evita rotar los hombros; el movimiento debe ser puramente vertical.'),
('8b72d7f5-cb5e-4958-9785-9888055260ed', '80c307e9-0a07-4802-9e6d-04dac1329e0a', 'en', 'Landmine Low Hold Lateral Lunge', 'Hold the end of the landmine bar at a low position and perform a deep lateral lunge, keeping your back flat and core engaged.'),
('7c75ba6f-f29f-459c-9db2-88a7b83c14ee', '80c307e9-0a07-4802-9e6d-04dac1329e0a', 'es', 'Zancada lateral agarre bajo en Landmine', 'Sujeta el extremo de la barra Landmine a una altura baja y realiza una zancada lateral profunda, manteniendo la espalda recta y el core activado.'),
('52c34e3a-8199-4427-8830-b31e345b83d6', '80c8a232-2fc3-4cee-96aa-f1ae76908612', 'es', 'Pullover con maza', 'Realiza un movimiento de pullover llevando la maza por encima de la cabeza y regresando al pecho, enfocando el trabajo en el dorsal ancho.'),
('10cc0e65-c443-4b6b-a1ea-532bf26acd3d', '80caeae6-9d7d-4f95-b041-dbae7e4fe0aa', 'en', 'Single Arm Kettlebell Bottoms Up Front Rack Contralateral Step Up', 'Hold an upside-down kettlebell at the chest and step up with the opposite leg, stabilizing the unstable load.'),
('ba801b70-57a3-4927-8f90-62af784aa781', '80caeae6-9d7d-4f95-b041-dbae7e4fe0aa', 'es', 'Step Up contralateral Front Rack con Kettlebell a una mano Bottoms Up', 'Sujeta una Kettlebell invertida en el pecho y sube al banco con la pierna contraria, estabilizando la carga inestable.'),
('86877a8b-3a4a-4b24-b8a0-c05f06c53838', '80dc05db-9582-47ff-b65e-5cf7b9cf48a5', 'es', 'Press banca agarre cerrado', 'Press con manos separadas al ancho de hombros o menos. Transfiere el énfasis a los tríceps. Los codos deben mantenerse más pegados al cuerpo. Cuidado con las muñecas. Excelente constructor de tríceps para mejorar el lockout del press regular.'),
('5f9aca14-b18e-4f92-8be0-97dabcc2c1d0', '81085ac1-f964-42bf-874f-5f13b9cd4383', 'en', 'Barbell Hip Thrust', 'With the upper back supported on a bench and the bar on the hips (use a pad), push hips upward until the torso is parallel to the floor. Strongly squeeze glutes at the top. Descend controlled without touching the floor.'),
('5a8f879b-6ba7-461a-ac2d-a1e23bfbfbd6', '81085ac1-f964-42bf-874f-5f13b9cd4383', 'es', 'Hip thrust barra', 'Con la parte superior de la espalda apoyada en un banco y la barra sobre las caderas (usa almohadilla), empuja las caderas hacia arriba hasta que el torso esté paralelo al suelo. Aprieta fuertemente los glúteos en la parte superior. Desciende controladamente sin tocar el suelo.'),
('e851a628-0f55-428c-a947-b539afd78b98', '8136213c-a08c-4703-924a-c2cc4c8544a0', 'en', 'Barbell Hang Squat Clean to Thruster', 'From a hang position, clean the bar into a deep squat and use the ascent to press the bar overhead in a thruster.'),
('e1dbf021-bc74-4ac4-86a5-bc5b501770c3', '8136213c-a08c-4703-924a-c2cc4c8544a0', 'es', 'Hang Squat Clean a Thruster con barra', 'Desde posicion colgada, carga la barra en sentadilla profunda y aprovecha la subida para presionar la barra sobre la cabeza en un thruster.'),
('42f4541e-fea3-4c59-b51d-cbe25c375a2d', '8149e643-0025-42f0-8241-b91410ba1e67', 'en', 'Band Assisted Vertical Jump', 'Jump with a band anchored above assisting the rise. Focus on takeoff speed. Cue: instantaneous takeoff. Common error: over-relying on the band.'),
('cc0c439d-283d-4410-9dd5-f0c61e8033c1', '8149e643-0025-42f0-8241-b91410ba1e67', 'es', 'Salto vertical asistido banda', 'Salta con una banda anclada arriba que te ayuda a subir. Enfoque en la velocidad de despegue. Cue: despegue instantáneo. Error común: depender demasiado de la banda.'),
('37eb303c-f6cb-4ce3-8874-5aec9b3faab7', '8153da50-80c9-4259-ab57-f74464a49c70', 'en', 'Cable Deadlift', 'With low pulley and straight bar, perform the deadlift movement. The cable changes the resistance vector compared to the free barbell. Keep back straight and push hips back. Useful for learning the movement pattern.'),
('36cf17e8-549c-420a-8915-707f54b42de7', '8153da50-80c9-4259-ab57-f74464a49c70', 'es', 'Peso muerto cable', 'Con polea baja y barra recta, realiza el movimiento de peso muerto. El cable cambia el vector de resistencia comparado con la barra libre. Mantén la espalda recta y empuja las caderas hacia atrás. Útil para aprender el patrón de movimiento.'),
('cae0b4dd-49a8-495a-8a79-d31543ff6518', '815dd95e-5bee-4279-bbab-b10b3ffce48d', 'en', 'Unilateral Low Row with Core Rotation', 'Row and rotate the trunk slightly when stretching. Cue: control the rotation. Error: lumbar jerks.'),
('e7860ee8-193d-4b78-9abd-8aae5518221d', '815dd95e-5bee-4279-bbab-b10b3ffce48d', 'es', 'Remo bajo unilateral rotación core', 'Rema y rota tronco leve al estirar. Cue: controla giro. Error: tirones lumbares.'),
('055b6405-0d5f-41b4-8c68-18fccfa5f514', '819a6dd7-eefc-42d4-8e48-9f18299258b7', 'es', 'Press pecho máquina sentado', 'Empuja agarres máquina. Objetivo: pectoral. Cue: espalda pegada. Error: despegar hombros.'),
('47648e26-32df-462a-b554-5ee41bf129b6', '81a8db34-ea1e-496f-9f5e-a853d66a285f', 'en', 'Double Kettlebell Squat Clean', 'Explosively lift two kettlebells from the floor to the shoulders, catching the weight in a deep squat position.'),
('23a6e5bf-c11b-4bc4-bf81-9c98e2fdca39', '81a8db34-ea1e-496f-9f5e-a853d66a285f', 'es', 'Squat Clean con Kettlebell doble', 'Lleva dos Kettlebells desde el suelo hasta los hombros de forma explosiva, recibiendo el peso en una posición de sentadilla profunda.'),
('ed3d9bad-35a0-48ad-a1f3-7e6afb1638db', '81c85cf8-f78b-4df2-99e6-c1cbc11af3cb', 'en', 'Crunches with Legs Elevated at 90 Degrees', 'Lying down with legs in the air, lift shoulders while squeezing the abdomen. Objective: upper rectus abdominis. Cue: look at the ceiling to avoid pulling on the neck. Common error: separating the lower back from the floor.'),
('1f0b6a01-fdd1-40ac-babb-c5a6e8f6f6d2', '81c85cf8-f78b-4df2-99e6-c1cbc11af3cb', 'es', 'Crunches con piernas elevadas a 90 grados', 'Tumbado con piernas en el aire, eleva los hombros apretando el abdomen. Objetivo: recto abdominal superior. Cue: mira al techo para no tirar del cuello. Error común: separar la zona lumbar del suelo.'),
('86f7d352-d47a-45b4-a9cb-a22ef3d9ad3d', '81e937d6-6493-438f-8ddb-9f0251099ad6', 'en', 'TRX Atomic Push Up', 'Combines a push-up with a crunch with feet in TRX. Perform a push-up and on the way up, bring knees to the chest. Very complete exercise that works chest, triceps, and core intensely.'),
('862b5d2d-00f0-4e43-82d7-d3b4d1108358', '81e937d6-6493-438f-8ddb-9f0251099ad6', 'es', 'Atomic push up TRX', 'Combina una flexión con un crunch con los pies en TRX. Realiza una flexión y al subir lleva las rodillas hacia el pecho. Ejercicio muy completo que trabaja pecho, tríceps y core intensamente.'),
('e376c12c-0686-47e0-954e-9ec9c780af85', '81f6aba7-ab6f-4ccc-bfff-f73e3d54a841', 'en', 'Seated Barbell Shoulder Press', 'Sit on a bench with a backrest. Lower the bar to the chin and press vertically until arms are straightened.'),
('242d1b1f-d2b7-4ceb-8604-559897a1da68', '81f6aba7-ab6f-4ccc-bfff-f73e3d54a841', 'es', 'Press de hombros sentado con barra', 'Siéntate en un banco con respaldo. Baja la barra hasta la barbilla y presiona verticalmente hasta estirar los brazos.'),
('e6a5cd5a-be5a-42de-9d04-e69de1da4bcd', '82296623-8248-4ba2-8bf3-10c875064b98', 'en', 'Heel-to-Glute Jumps with Vertical Jump', 'Jump and bring heels to glutes explosively. Improves leg recovery speed. Straight back. Do not lean forward.'),
('3163362b-fe0c-4723-beaf-44c00d62270b', '82296623-8248-4ba2-8bf3-10c875064b98', 'es', 'Saltos talón a glúteo con salto vertical', 'Salta y lleva los talones a los glúteos de forma explosiva. Mejora la velocidad de recuperación de pierna. Espalda recta. No te inclines hacia adelante.'),
('5419b548-ef58-4eb2-9ec8-c66e6a0d02de', '82417703-75ba-4307-950b-5fa0b31ef61e', 'en', 'Donkey kicks', 'From all fours, keep the knee bent at 90 degrees and lift the leg back and up, as if pushing the ceiling with the sole of your foot. Contract the glute at the top of the movement. Keep the back neutral and avoid arching it excessively.'),
('6a7406aa-e42d-4232-bded-d27cab43e321', '82417703-75ba-4307-950b-5fa0b31ef61e', 'es', 'Donkey kicks', 'Desde cuadrupedia, mantén la rodilla flexionada a 90 grados y eleva la pierna hacia atrás y arriba, como si empujaras el techo con la planta del pie. Contrae el glúteo en la parte superior del movimiento. Mantén la espalda neutra y evita arquearla excesivamente.'),
('f8fbbcd2-d0f8-464e-a4fd-f2561a513bb8', '827a548e-1cc0-4d6b-83ea-6476c30c754b', 'es', 'Puente de glúteo a una pierna con pie en Fitball', 'Acuéstate con un pie sobre el Fitball. Eleva la cadera usando esa pierna mientras equilibras el balón inestable y la otra pierna en el aire.'),
('09ba1991-3c0c-4ef2-bcf3-692010ecf1f0', '827e5b52-6117-4548-9e0e-39206ec60a72', 'en', 'Single Leg Deadlift (Bodyweight)', 'Balance on one leg and lower torso while the other leg extends back. Objective: balance and posterior chain. Cue: keep back flat. Error: rotating hip outward.'),
('88bd4620-40b7-4b8f-b905-87252f485793', '827e5b52-6117-4548-9e0e-39206ec60a72', 'es', 'Peso muerto con una sola pierna (sin peso)', 'Mantén el equilibrio en una pierna y baja el torso mientras la otra pierna se extiende atrás. Objetivo: equilibrio y cadena posterior. Cue: mantén la espalda plana. Error: girar la cadera hacia afuera.'),
('5820aeea-1668-4127-a83b-c422a75091ed', '829ab4e3-f95c-4f31-9f50-b03dfeda3739', 'en', 'Dumbbell Complex', 'Series of 4-6 exercises performed without releasing the dumbbells. Example: deadlift, row, clean, press, squat, lunge. All reps of one exercise before moving to the next. Brutal for conditioning. Choose appropriate weight for the weakest exercise.'),
('2e81163f-77f1-4711-a02e-3f3bf4f35473', '829ab4e3-f95c-4f31-9f50-b03dfeda3739', 'es', 'Complejo mancuernas', 'Serie de 4-6 ejercicios realizados sin soltar las mancuernas. Ejemplo: deadlift, row, clean, press, squat, lunge. Todas las reps de un ejercicio antes de pasar al siguiente. Brutal para acondicionamiento. Elige peso apropiado para ejercicio más débil.'),
('dad78187-9bb6-45c0-9bd7-8b9a7db9a1d9', '82c8c093-a32d-4561-afe4-8646f8e16084', 'en', 'Stepped Band Bicep Curl', 'Step on the band and flex arms. Variable resistance. Elbows glued. Do not move wrists.'),
('96ee7d85-6669-4517-a65c-e7b8fd3f9ebb', '82c8c093-a32d-4561-afe4-8646f8e16084', 'es', 'Curl de bíceps con banda pisada', 'Pisa la banda y flexiona brazos. Resistencia variable. Codos pegados. No muevas las muñecas.'),
('8e42e25a-e47d-42f1-9046-29d796bd4ef4', '82f3ee55-ffe4-45ba-8554-d4657691380e', 'en', 'TRX Oblique Crunch', 'Similar to the crunch but bringing the knees toward one side, alternating. Intensely works the obliques. Keep the torso stable and avoid excessive hip rotation during the movement.'),
('57d44570-049c-476b-a952-d2c49421258d', '82f3ee55-ffe4-45ba-8554-d4657691380e', 'es', 'Oblique crunch TRX', 'Similar al crunch pero llevando las rodillas hacia un lado, alternando. Trabaja intensamente los oblicuos. Mantén el torso estable y evita rotar excesivamente las caderas durante el movimiento.'),
('edcb1292-0304-419b-af57-10a5e9dc247f', '83258c8b-dcba-4525-94e1-703825d47467', 'en', 'Decline Dumbbell Press', 'Dumbbell press on a decline bench. Objective: lower fibers. Cue: control the descent. Error: clashing weights.'),
('1b188e06-890c-4f7d-a70f-08d668fb3f40', '83258c8b-dcba-4525-94e1-703825d47467', 'es', 'Press declinado con mancuernas', 'Press en banco declinado con mancuernas. Objetivo: fibras inferiores. Cue: controla el descenso. Error: chocar pesas.'),
('7b858f68-89d9-4e97-9a23-8e1d4390f842', '835cbcfd-6484-4ea9-af91-848725fa695a', 'en', 'Cable Reverse Fly', 'With crossed cables or on a specific machine, perform rear deltoid openings. Keep arms slightly bent and focus on bringing the shoulder blades together at the end. Excellent for improving posture and balancing shoulder development.'),
('b515e560-6537-45d1-81dc-cc3c0dcb2a9b', '835cbcfd-6484-4ea9-af91-848725fa695a', 'es', 'Reverse fly cable', 'Con cables cruzados o en máquina específica, realiza aperturas posteriores para deltoides posterior. Mantén los brazos ligeramente flexionados y enfócate en juntar los omóplatos al final. Excelente para mejorar la postura y equilibrar el desarrollo del hombro.'),
('6e853d79-8829-4cce-8319-b7393ae1d0fa', '83a247ca-748a-4ce4-a300-0b5aedc56f28', 'en', 'Dumbbell Bulgarian Split Squat Knee-over-Toe', 'Perform a Bulgarian split squat with dumbbells at your sides, allowing the front knee to pass the foot to load the quadriceps.'),
('519965f2-28d3-4b8d-92c9-c68eea32968f', '83a247ca-748a-4ce4-a300-0b5aedc56f28', 'es', 'Sentadilla Búlgara con mancuernas rodilla sobre punta del pie', 'Realiza una sentadilla búlgara con mancuernas a los lados permitiendo que la rodilla delantera sobrepase el pie para cargar el cuadriceps.'),
('e5a2c384-c253-4658-8248-1e651c5a3d4f', '83a554dd-0279-4602-807e-891d99176692', 'en', 'Barbell Floor Press', 'Lying on the floor, lower the bar until your triceps touch the ground and then explosively press back up.'),
('e894e102-a660-4b98-afb3-f6d4f6ec67d5', '83a554dd-0279-4602-807e-891d99176692', 'es', 'Press de suelo con barra', 'Tumbado en el suelo, baja la barra hasta que los tríceps toquen el suelo y luego presiona explosivamente hacia arriba.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('89749648-4e80-4744-a56c-bfecfc959912', '84163055-1c04-4c45-a20b-8b6eccb2bf4d', 'en', 'Kettlebell Sumo Squat', 'Very wide feet and toes pointed out, hold the weight down and lower into a deep squat. Objective: adductors and glute. Cue: keep knees aligned with feet. Error: rounding the lumbar back.'),
('929655f7-9570-423c-a464-86c519527c2e', '84163055-1c04-4c45-a20b-8b6eccb2bf4d', 'es', 'Sentadilla sumo con kettlebell', 'Pies muy anchos y puntas hacia afuera, sujeta la pesa abajo y baja en sentadilla profunda. Objetivo: aductores y glúteo. Cue: mantén las rodillas alineadas con los pies. Error: redondear la espalda lumbar.'),
('f5a9b421-396f-4d7c-9067-39772ab1b9e6', '84383691-c1f4-449e-80ce-def20ac0f998', 'en', 'Ring Kneeling Rollout', 'Kneeling, hold the rings and slide your arms forward extending your body under control, returning using abdominal strength.'),
('756ef809-0a9e-4aa2-80a2-e3b68a0f6865', '84383691-c1f4-449e-80ce-def20ac0f998', 'es', 'Rollout de rodillas en anillas', 'De rodillas, sujeta las anillas y desliza los brazos hacia adelante extendiendo el cuerpo bajo control, regresando mediante la fuerza abdominal.'),
('3f76be3f-cfff-49a2-a00a-600c72c2b5b7', '845dde79-265e-443f-a1c7-5b61bfa81ab7', 'es', 'Press Pallof rotacional dinámico', 'Extiende cable y gira levemente resistiendo. Cue: core bloqueado. Error: mover cadera.'),
('437bd830-2bc8-4c40-9ab8-4828d6ad1da4', '8464fafe-5ff2-465e-ab5e-884a022c0e66', 'es', 'Turkish Sit Up con mancuerna a una mano', 'Acuéstate con un brazo extendido sujetando una mancuerna. Realiza un sit up manteniendo el brazo perfectamente vertical en todo momento.'),
('56db0cad-c9a6-47e4-81ff-ed22f9eeb5ea', '848832dd-64b5-404b-bc31-1e366ef9e293', 'es', 'Peso muerto rumano a una pierna con barra', 'Sostén la barra y baja el torso hacia adelante mientras elevas una pierna hacia atrás, manteniendo el equilibrio sobre la pierna de apoyo.'),
('76e42ff5-5027-4e43-8e55-fd9e9bba7ff5', '8493dd78-6a41-451b-9db2-6abfe34158eb', 'en', 'Seated Band Abductor', 'Separate knees with a band while seated. Objective: gluteus medius. Cue: chest high. Error: closing too fast.'),
('09a0d421-ba31-4adb-8524-529c9c35637b', '8493dd78-6a41-451b-9db2-6abfe34158eb', 'es', 'Abductor sentado banda', 'Separa rodillas con banda sentado. Objetivo: glúteo medio. Cue: pecho alto. Error: cerrar rápido.'),
('78cb36e2-1ad1-4ca2-b75d-d02caba83f9a', '84dc0a1e-bdc6-486f-9342-b54de8e703a5', 'en', 'Bulgarian Ring Row', 'Perform a ring row with a wider grip and elbows flexed to the sides to focus work on the upper back and rear deltoids.'),
('180d222d-bd26-4615-bf8a-0963335dfa8a', '84dc0a1e-bdc6-486f-9342-b54de8e703a5', 'es', 'Remo búlgaro en anillas', 'Realiza un remo en anillas con un agarre más ancho y los codos flexionados hacia los lados para enfocar el trabajo en la parte superior de la espalda y deltoides posteriores.'),
('93d7295e-1289-4174-99e6-d61e243e91ee', '8503bcdc-0cf8-4932-8cbf-89407b276c8a', 'en', 'Ankle and Hip Mobility', 'Perform a mobility sequence focused on the ankle and hip, working through controlled ranges to improve squat, lunge, and running positions.'),
('e0195907-1ceb-4a19-a00d-61866273539f', '8503bcdc-0cf8-4932-8cbf-89407b276c8a', 'es', 'Movilidad tobillo-cadera', 'Realiza una secuencia de movilidad enfocada en tobillo y cadera, trabajando rangos controlados para mejorar la posición de sentadilla, zancada y carrera.'),
('bb91f97d-ee0a-47b6-9a00-3a91a8e92715', '850b353a-d122-4699-8788-704eac0d47ed', 'en', 'Unilateral Cable Lateral Raises', 'Lift the cable laterally with one arm. Cue: shoulder down. Error: using trapezius excessively.'),
('25128c9f-a455-4e3b-99b8-135747ea2135', '850b353a-d122-4699-8788-704eac0d47ed', 'es', 'Elevaciones laterales cable unilateral', 'Eleva el cable lateralmente con un solo brazo. Cue: hombro abajo. Error: usar trapecio excesivamente.'),
('d3997ca0-1c1f-488c-91f3-1be7cbef010c', '850b5321-886c-413d-9345-e27d167e4543', 'es', 'Pull-through polea baja cadera', 'Tira cuerda entre piernas de espaldas. Cue: espalda plana. Error: tirar con brazos.'),
('96c9c94f-991c-4d66-b5d2-5a5313ee9761', '852ff93e-15ec-4aef-a616-1894ffe0891e', 'en', 'Pogo Jumps', 'Fast bounces with minimal knee flexion to work ankle stiffness and foot reactivity.'),
('bab0454f-9a83-4e00-8be6-833cb4c0be54', '852ff93e-15ec-4aef-a616-1894ffe0891e', 'es', 'Saltos pogo (rebotes rápidos)', 'Rebota corto y rápido, tronco alto, tobillo elástico. Evita colapsar rodillas hacia dentro.'),
('45078033-c8dc-448c-a8b9-bc502bfdfdc4', '8543650d-836a-4e2b-bb3c-051d573d303d', 'en', 'Wide Parallel Bar Push Up', 'Place hands on the parallel bars wider than shoulder width. Lower the chest deeply to stretch the pectoral before pushing up.'),
('5fc58e51-388e-46b2-8943-b1bb3e9419a4', '8543650d-836a-4e2b-bb3c-051d573d303d', 'es', 'Push Up ancho en paralelas', 'Coloca las manos en las paralelas más ancho que los hombros. Baja el pecho profundamente para estirar el pectoral antes de empujar hacia arriba.'),
('f8d0bae6-8229-4d43-863f-70cbd10bab26', '85443804-57fd-4294-aa59-0ba93020ea7e', 'en', 'Lying Leg Elevation', 'Lie on your back with hands under glutes. Keeping legs straight and together, lift them until vertical and lower slowly without touching the floor.'),
('6b7dadf0-857c-4564-86a7-35f1e3d04b82', '85443804-57fd-4294-aa59-0ba93020ea7e', 'es', 'Elevación de piernas tumbado', 'Acuéstate boca arriba con las manos bajo los glúteos. Manteniendo las piernas rectas y juntas, levántalas hasta que estén verticales y bájalas lentamente sin tocar el suelo.'),
('304251c1-66ef-44aa-9d46-d682d1a61dea', '854c05c7-dc3c-488b-b8fe-c75735e104f9', 'en', 'Overhead EZ Bar Triceps Extension', 'Standing, hold an EZ bar with arms extended overhead. Lower the bar behind the head bending elbows and then extend.'),
('c3c17bc2-2ac9-45f6-b77c-6eb678c30387', '854c05c7-dc3c-488b-b8fe-c75735e104f9', 'es', 'Extensión de tríceps Overhead con barra Z', 'De pie, sostén una barra Z con los brazos extendidos sobre la cabeza. Baja la barra detrás de la cabeza doblando los codos y luego extiende.'),
('5e076312-9c6a-477a-a6ec-6954e986da3c', '85537bfe-d628-449f-be49-70640e47bb79', 'es', 'Peso muerto un brazo', 'Peso muerto sujetando la barra con una sola mano en el centro. Desafío extremo de agarre y estabilización anti-rotación. Usa menos peso. Alterna manos. Excelente para fuerza funcional y del core.'),
('ce6fa745-c9d2-4778-be37-d2b8ad908f0e', '85625cf9-e586-4307-8eda-dc226856d5f5', 'en', 'Dumbbell Crush Grip Spider Curl', 'Supported on an incline bench, press two dumbbells against each other while performing the curl to increase muscle activation.'),
('37d0a58c-bb4a-4535-b047-e73981b897da', '85625cf9-e586-4307-8eda-dc226856d5f5', 'es', 'Spider Curl agarre Crush con mancuernas', 'Apoyado en banco inclinado, presiona dos mancuernas una contra la otra mientras realizas el curl para aumentar la activacion muscular.'),
('8fe28d4d-71a1-41eb-b58f-60d5179353bd', '85652945-2e8c-4313-aafc-ba63baa71ccd', 'en', 'Double Kettlebell Seesaw Overhead Press', 'Press one kettlebell up while simultaneously lowering the other continuously, creating a constant see-saw motion.'),
('32da60e3-94c0-4df3-9ff8-5754f4805c02', '85652945-2e8c-4313-aafc-ba63baa71ccd', 'es', 'Press Overhead Seesaw con Kettlebell doble', 'Presiona una Kettlebell hacia arriba mientras bajas la otra simultáneamente de forma continua, creando un movimiento de balancín constante.'),
('e6d7c5ef-e2b0-4a65-b632-1b7203fc7064', '857190a0-3899-403a-9a30-d7e885668518', 'en', 'Decline Close Grip Barbell Bench Press', 'Perform a bench press on a decline bench with hands together on the bar, focusing the work on the lower pectoral and the triceps.'),
('e522616a-8ed7-4945-8957-4e9b81678e58', '857190a0-3899-403a-9a30-d7e885668518', 'es', 'Press de banca declinado agarre cerrado con barra', 'Realiza un press de banca en un banco declinado con las manos juntas en la barra, enfocando el trabajo en la parte inferior del pectoral y el triceps.'),
('b4851931-a0c8-467f-9a34-1f1f8dd3e29e', '85ada012-58ae-44d9-b04b-43744b0c7fc9', 'en', 'Overhead Barbell Slider Lateral Lunge', 'Hold a bar overhead with locked arms. Place one foot on a slider and slide it laterally lowering into a deep lunge, keeping the bar stable above.'),
('5e7efab2-940d-4fc8-b57c-abafa23a4453', '85ada012-58ae-44d9-b04b-43744b0c7fc9', 'es', 'Zancada lateral Overhead con barra y Slider', 'Sostén una barra sobre la cabeza con brazos bloqueados. Coloca un pie sobre un slider y deslízalo lateralmente bajando en una zancada profunda, manteniendo la barra estable arriba.'),
('806d6549-b60b-4d60-9189-4984dcce3754', '863148d4-9367-4764-b637-78350be42c87', 'en', 'Single Leg Slam', 'Slam ball performed on one leg. Increases the balance challenge and core activation. Alternate legs or complete sets per side. Keep the supporting knee slightly flexed.'),
('4202d03f-5b29-40b4-876a-297e216e4cd0', '863148d4-9367-4764-b637-78350be42c87', 'es', 'Single leg slam', 'Slam ball realizado sobre una pierna. Aumenta el desafío de equilibrio y la activación del core. Alterna las piernas o completa series por lado. Mantén la rodilla de apoyo ligeramente flexionada.'),
('632415a8-c1cd-4e87-a947-2bb489aa8d8b', '8650ff35-6c95-4a4b-9ab5-99dd72df0737', 'en', 'Double Indian Club Lateral Rotations', 'Perform controlled lateral circles with both Indian Clubs to improve shoulder joint mobility and health.'),
('09ecd4d5-2bec-439f-ba50-db951929aab5', '8650ff35-6c95-4a4b-9ab5-99dd72df0737', 'es', 'Rotaciones laterales con Indian Club doble', 'Realiza círculos laterales controlados con ambos Indian Clubs para mejorar la movilidad y salud de la articulación del hombro.'),
('fd2303f6-cc86-47b7-bead-db35278fffc8', '868d3148-9062-42fb-8716-62838ffcbf35', 'en', 'Single Arm Kettlebell Contralateral Single Leg Romanian Deadlift', 'Perform a single-leg Romanian deadlift holding the kettlebell in the hand opposite to the supporting leg, increasing the cross-stability challenge.'),
('da7ef71a-bc83-4801-9f48-49d7e5477e1c', '868d3148-9062-42fb-8716-62838ffcbf35', 'es', 'Peso muerto rumano a una pierna contralateral con Kettlebell', 'Realiza un peso muerto rumano a una pierna sosteniendo la Kettlebell con la mano opuesta a la pierna de apoyo, aumentando el reto de estabilidad cruzada.'),
('400ffd67-5447-4d29-80fc-648ee3ffcb35', '869b66e7-9c59-448a-a727-7453e81953b3', 'en', 'Cable Internal Shoulder Rotation', 'Similar to external rotation but rotating inward crossing the body. Works the internal rotators of the shoulder. Keep the elbow fixed at your side and use appropriate resistance to maintain control throughout the movement.'),
('3b5589b5-1ef6-4fb5-9fbd-4a628cd087c1', '869b66e7-9c59-448a-a727-7453e81953b3', 'es', 'Rotación interna hombro cable', 'Similar a la rotación externa pero rotando hacia adentro cruzando el cuerpo. Trabaja los rotadores internos del hombro. Mantén el codo fijo al costado y usa resistencia apropiada para mantener el control durante todo el movimiento.'),
('592f6a40-d028-457b-9903-75e0e8644824', '86ae9fa6-d634-4b17-874b-d0ba4fdf74e2', 'en', 'Slow Mountain Climbers', 'Bring knee to elbow maintaining abdominal contraction for 2 sec. Cue: maximum tension. Error: moving hips up.'),
('7f78ce7f-bad6-4219-8604-3a708243a029', '86ae9fa6-d634-4b17-874b-d0ba4fdf74e2', 'es', 'Escaladores lentos', 'Lleva rodilla a codo manteniendo la contracción abdominal 2 seg. Cue: máxima tensión. Error: mover la cadera arriba.'),
('0eb2edae-99d0-48b0-8796-c957365788aa', '86b53421-8eb6-4232-b598-b8c00da0d4da', 'en', 'Single Arm Kettlebell Bottoms Up Overhead Contralateral Step Up', 'Step up onto the bench with the leg opposite to the hand holding an upside-down kettlebell overhead, working on cross-stability.'),
('38608bc4-2cc7-4310-8836-042632d8a4ca', '86b53421-8eb6-4232-b598-b8c00da0d4da', 'es', 'Step Up Overhead contralateral con Kettlebell a una mano Bottoms Up', 'Sube al banco con la pierna opuesta a la mano que sostiene una Kettlebell invertida sobre la cabeza, trabajando la estabilidad cruzada.'),
('41909eef-270c-45b7-bd2d-5956b8aa08a8', '86b9deb1-0e62-4351-a6cc-b71b6e210cfd', 'en', 'TRX Muscle up', 'Modified version of the muscle up using TRX. Body inclination determines difficulty. Allows practicing the transition from pulling to pushing. Progression toward bar or ring muscle ups.'),
('e8bbc8f5-55b9-47fc-8c4b-b38135f476ee', '86b9deb1-0e62-4351-a6cc-b71b6e210cfd', 'es', 'Muscle up TRX', 'Versión modificada del muscle up usando TRX. La inclinación del cuerpo determina la dificultad. Permite practicar la transición de tracción a empuje. Progresión hacia muscle up en barra o anillas.'),
('3ab186c9-6fb3-428b-a558-332a339ee325', '86e7360f-fbf2-4375-8ecd-39d4e8371cf3', 'en', 'Front Rack Bulgarian Split Squat Knee-over-Toe', 'Perform a split squat with the foot elevated and the bar in a front rack position, allowing the front knee to pass the toes under control.'),
('6e76c165-94e9-4974-aa24-7a1b1c514be0', '86e7360f-fbf2-4375-8ecd-39d4e8371cf3', 'es', 'Sentadilla Búlgara Front Rack rodilla sobre punta del pie', 'Realiza una sentadilla split con el pie elevado y la barra en posicion de rack frontal, permitiendo que la rodilla delantera sobrepase los dedos del pie bajo control.'),
('555a8fd6-2b41-41b7-8ddc-d93094914c25', '86e7591d-b617-48b4-953a-19567e812960', 'en', 'One-Arm Chest-Supported Machine Row', 'Pull one handle in the machine. Cue: stretch the shoulder. Error: rotating trunk.'),
('e0b64f6d-d055-4b15-859a-c6df83067793', '86e7591d-b617-48b4-953a-19567e812960', 'es', 'Remo máquina un brazo apoyo pecho', 'Tira de un agarre en máquina. Cue: estira hombro. Error: rotar tronco.'),
('e935a49e-c9a4-4472-b76c-1141c297aeb0', '873f16cf-f086-40e7-b8c5-2bb0b8d20b6c', 'en', 'Vertical Leg Toe Touch Crunches', 'Lift shoulders trying to touch feet in the air. Cue: lower back to the floor. Error: pulling on the neck.'),
('9521f999-ce77-4583-b19c-6b815e4e079f', '873f16cf-f086-40e7-b8c5-2bb0b8d20b6c', 'es', 'Crunches manos pies elevados verticales', 'Eleva hombros buscando tocar pies en aire. Cue: lumbar al suelo. Error: tirar cuello.'),
('eb503702-4af8-44a9-9c5d-f0be2b390c93', '877e0a86-3940-4c51-a22e-171cad638547', 'en', 'Oblique Crunch with Feet on Fitball', 'Lie on the floor with heels on the fitball. Place one hand behind the head and lift the torso, rotating to bring the elbow toward the opposite knee.'),
('e4c8ee93-85d1-4617-bb05-690be6481675', '877e0a86-3940-4c51-a22e-171cad638547', 'es', 'Crunch oblicuo con pies en Fitball', 'Acuéstate en el suelo con los talones sobre el Fitball. Coloca una mano detrás de la cabeza y eleva el torso girando para llevar el codo hacia la rodilla opuesta.'),
('03af2caf-9af2-48ac-b184-9f0cb58874e6', '87d276ea-24f4-415d-936c-a1d4fd1ad188', 'en', '180-Degree Jump Burpee', 'Perform a burpee and end with a jump turning a half-turn in the air. Improves orientation and coordination. Cue: land cushioning with knees. Common error: getting dizzy when turning without a fixed point.'),
('041b1041-ee4e-4943-9e08-5c4c918f7bbf', '87d276ea-24f4-415d-936c-a1d4fd1ad188', 'es', 'Burpee con salto 180 grados', 'Realiza un burpee y termina con un salto girando media vuelta en el aire. Mejora la orientación y coordinación. Cue: aterriza amortiguando con rodillas. Error común: marearse al girar sin un punto fijo.'),
('7dd566d9-954b-4575-8e1b-0ad943cb8206', '87e7039f-c765-4acd-9af1-da467b87c35c', 'en', 'Bosu Squat', 'Standing squats on the round side of the Bosu. Challenges balance and proprioception while strengthening legs. Start with partial squats and progress. Keep eyes forward and core engaged for stability.'),
('65ad5dd4-400a-47b7-80f4-80ed919ff77f', '87e7039f-c765-4acd-9af1-da467b87c35c', 'es', 'Squat bosu', 'Sentadillas de pie sobre el lado redondo del bosu. Desafía el equilibrio y la propiocepción mientras fortalece las piernas. Comienza con sentadillas parciales y progresa. Mantén la vista al frente y el core activado para estabilidad.'),
('1a9dc212-1b0d-48c5-a651-cf62e396c745', '87e9e4c7-e091-4dcd-a8b7-a441eb736f51', 'en', 'Pulley Triceps Kickback', 'Torso leaning, extend arm back. Total isolation. Arm parallel to the floor. Do not move the shoulder.'),
('311293bb-781f-4265-ba05-4a66f7b11d93', '87e9e4c7-e091-4dcd-a8b7-a441eb736f51', 'es', 'Patada de tríceps en polea', 'Torso inclinado, extiende el brazo atrás. Aislamiento total. Brazo paralelo al suelo. No muevas el hombro.'),
('93572cd4-ec32-4d4f-9b1e-6fdca2d05049', '87eb0c00-1983-49a5-8609-4b54a13fb513', 'en', 'Barbell Front Rack Bulgarian Split Squat', 'With one foot elevated on a bench, hold the barbell in a front rack position on your shoulders and perform a deep split squat.'),
('2999ef3f-a4c8-47f7-95e1-5ea39b4daa25', '87eb0c00-1983-49a5-8609-4b54a13fb513', 'es', 'Sentadilla Búlgara búlgara con barra frontal', 'Con un pie elevado en banco, sujeta la barra en posicion de rack frontal sobre los hombros y realiza una sentadilla split profunda.'),
('61b79072-973f-4926-9afa-2ad0c9af2ace', '87f1ea96-c5f8-4af7-991e-4bc16d9358ad', 'en', 'Bodyweight Kneeling Forearm Plank', 'Rest your forearms and knees on the floor. Keep your body in a straight line from head to knees, engaging the core and preventing the hips from sagging.'),
('493a3be7-31b9-4163-b398-3453f825d4d7', '87f1ea96-c5f8-4af7-991e-4bc16d9358ad', 'es', 'Plank de rodillas con antebrazos', 'Apoya los antebrazos y las rodillas en el suelo. Mantén el cuerpo en línea recta desde la cabeza hasta las rodillas, activando el abdomen y evitando que la cadera caiga.'),
('db118692-b188-4743-8649-1e7e39555b38', '882f4efc-ac86-478f-8af8-35688e94f442', 'en', 'Granny Toss', 'Throw the ball upward as high as possible from a squat position. Total body power. Cue: eyes on the ball to catch it. Common error: rounding the back when picking the ball off the floor.'),
('af5f445c-32a1-4bbe-ba5c-6bbdf80dabfa', '882f4efc-ac86-478f-8af8-35688e94f442', 'es', 'Lanzamiento granny toss', 'Lanza el balón hacia arriba lo más alto posible desde una posición de sentadilla. Potencia total del cuerpo. Cue: mirada en el balón para recibirlo. Error común: redondear la espalda al recoger el balón del suelo.'),
('979a269d-7bee-40e5-981b-9c482bcd5999', '88b476d9-6f6e-4437-8cb3-e31d7b6b379d', 'en', 'Lateral Raises', 'Lift dumbbells laterally to shoulder height. Objective: lateral deltoid. Cue: pour water while rising. Common error: lifting the weight above the shoulder line.'),
('98ea8cc9-2184-42e6-bb56-62e2d204e499', '88b476d9-6f6e-4437-8cb3-e31d7b6b379d', 'es', 'Elevaciones laterales', 'Eleva mancuernas lateralmente hasta la altura de los hombros. Objetivo: deltoides lateral. Cue: vierte agua al subir. Error común: elevar el peso por encima de la línea de los hombros.'),
('531a391b-cbcb-4c93-9e1d-7ed64f3de796', '88e2d177-d4d2-4939-a21f-ace8214cad3a', 'en', 'Jump Squat', 'Perform a normal squat and on the way up, explode upward into a maximum vertical jump. Land softly cushioning with flexed knees and continue immediately with the next repetition. This exercise develops explosive power in the legs and improves athletic capacity.'),
('1c814162-4565-4cf0-a5fe-3862c2117c06', '88e2d177-d4d2-4939-a21f-ace8214cad3a', 'es', 'Sentadilla jump', 'Realiza una sentadilla normal y al subir, explota hacia arriba en un salto vertical máximo. Aterriza suavemente amortiguando con las rodillas flexionadas y continúa inmediatamente con la siguiente repetición. Este ejercicio desarrolla potencia explosiva en las piernas y mejora la capacidad atlética.'),
('d8edb8a8-d181-40af-bada-8db3f834c8c2', '891181ff-0a97-403b-b9eb-6be1f8e2548e', 'en', 'Single Arm Kettlebell Side to Side Swing', 'Swing the kettlebell from side to side in front of the body in a lateral arc, challenging the core rotational stability.'),
('dc12b262-b307-4f78-a526-6244f79f4cf5', '891181ff-0a97-403b-b9eb-6be1f8e2548e', 'es', 'Side to Side Swing con Kettlebell a una mano', 'Balancea la Kettlebell de un lado al otro por delante del cuerpo en un arco lateral, desafiando la estabilidad rotacional del core.'),
('b44d9b6e-233d-456e-b2fb-1b1efb60cf60', '8913568c-fb05-4cc1-80ca-d778c9363a9d', 'en', 'Single Leg Hamstring Curl on Fitball', 'Perform a hamstring curl on the fitball using only one leg, keeping the other elevated to increase intensity.'),
('1d479e3f-dfd0-43ee-b7e0-8907dc6454c9', '8913568c-fb05-4cc1-80ca-d778c9363a9d', 'es', 'Curl de isquiotibiales a una pierna en Fitball', 'Realiza un curl de isquiotibiales sobre el Fitball usando solo una pierna, manteniendo la otra elevada para aumentar la intensidad.'),
('de966e13-2338-462e-b664-2c960c420f4c', '891b642b-0be8-475d-8fd3-a2de72aca974', 'en', 'Shoulder and Lat Mobility', 'Perform a mobility sequence focused on the shoulder and lats, aiming to improve range of motion without pain while maintaining controlled breathing.'),
('e3aca7a8-0048-4418-b123-0d4d235782be', '891b642b-0be8-475d-8fd3-a2de72aca974', 'es', 'Movilidad de hombro y dorsal', 'Realiza una secuencia de movilidad enfocada en hombro y dorsal, buscando mejorar el rango de movimiento sin dolor y manteniendo una respiración controlada.'),
('39d85126-8c29-43f5-8f04-cc43c0797539', '89224e66-7c98-4c84-b39e-063d569f345f', 'en', 'Straight Bar Cable Triceps Extensions', 'Push the bar down locking the elbows at the end of the movement. Objective: triceps. Cue: keep elbows glued to the sides. Error: moving arms from the shoulder.'),
('13496d88-1046-4d2c-bd0c-5c3a98327908', '89224e66-7c98-4c84-b39e-063d569f345f', 'es', 'Extensiones de tríceps en polea con barra recta', 'Empuja la barra hacia abajo bloqueando los codos al final del movimiento. Objetivo: tríceps. Cue: mantén los codos pegados a los costados. Error: mover los brazos desde el hombro.'),
('1a1b911c-1975-4ae9-b68b-d9d4ff77e9b6', '89287df9-6bf0-43f9-a702-9b990492c651', 'en', 'Unilateral High Pulley Pulldown', 'Pull the stirrup handle to the shoulder. Objective: isolated lat. Cue: elbow to pocket. Error: rotating torso.'),
('7876b758-a729-4975-a2b4-b0d533396e97', '89287df9-6bf0-43f9-a702-9b990492c651', 'es', 'Jalón unilateral polea alta', 'Tira estribo a hombro. Objetivo: dorsal aislado. Cue: codo al bolsillo. Error: rotar torso.'),
('7a1bc9f0-4cb2-4dbb-a5d4-3b1d20e6d562', '89388b2f-4a25-4d6c-8980-4d0edc263fd6', 'en', 'Single Arm Dumbbell Neck Extension', 'Lower weight behind the neck with one hand. Cue: elbow to the ceiling. Error: moving arm laterally.'),
('d053d154-f440-4e23-8686-ae97720f7ef9', '89388b2f-4a25-4d6c-8980-4d0edc263fd6', 'es', 'Extensión nuca mancuerna un brazo', 'Baja pesa tras nuca a una mano. Cue: codo al techo. Error: mover brazo lateral.'),
('4bc32722-568e-4a14-abbf-8348c92bae7b', '8945dd2d-1e28-4ac0-8580-8b85a5a37849', 'en', 'Single Arm Kettlebell Half Kneeling Contralateral Overhead Press', 'In a half-kneeling position, press the weight overhead with the arm opposite to the front leg, challenging torso stability.'),
('06142eea-77b4-4dd6-b262-d592a96cf951', '8945dd2d-1e28-4ac0-8580-8b85a5a37849', 'es', 'Press de hombros contralateral con pesa rusa, medio de Rodillas y con un solo brazo', 'En posicion de caballero, presiona la pesa sobre la cabeza con el brazo opuesto a la pierna delantera, retando la estabilidad del torso.'),
('163abda8-6feb-4ac6-b0d4-c4e6c7d9ffd9', '895c8c8f-a898-4706-b033-ccdbb2abb90d', 'en', 'Archer Pull-ups', 'Pull-ups directing most of the weight toward one arm while the other assists minimally. Excellent progression toward one-arm pull-ups. Alternate sides or complete sets per side. Keep the assisting arm as straight as possible.'),
('221b0328-761a-457a-a461-903dfddceb8a', '895c8c8f-a898-4706-b033-ccdbb2abb90d', 'es', 'Dominadas archer', 'Dominadas dirigiendo la mayor parte del peso hacia un brazo mientras el otro asiste mínimamente. Excelente progresión hacia dominadas a un brazo. Alterna lados o completa series por lado. Mantén el brazo de asistencia lo más recto posible.'),
('9b29c504-0544-4666-a9e8-e98e6fdfe3a5', '899e00b1-86be-4d57-82b7-b15548cba3c9', 'en', 'Double Kettlebell Swing', 'Swing with two kettlebells simultaneously. Requires greater strength and stabilization. The kettlebells must move in sync. Wider foot stance than single swing. Progress after mastering the single swing perfectly.'),
('2eb19c14-0436-45fe-b79e-613678668e22', '899e00b1-86be-4d57-82b7-b15548cba3c9', 'es', 'Swing doble kettlebell', 'Swing con dos kettlebells simultáneamente. Requiere mayor fuerza y estabilización. Las kettlebells deben moverse sincronizadas. Más ancho de pies que swing simple. Progresa desde dominar swing simple perfectamente.'),
('20673efa-8d36-4559-bead-4323fd662b6a', '89dbe6cb-467a-437a-83b8-be91543c4b47', 'en', 'Straight-Arm Superman Eyes on Floor', 'Lift chest and legs face down. Cue: look down. Error: neck jerks.'),
('2eafc455-e038-4ace-9f00-14bf6129722d', '89dbe6cb-467a-437a-83b8-be91543c4b47', 'es', 'Superman brazos estirados mirada suelo', 'Eleva pecho y piernas boca abajo. Cue: mira abajo. Error: tirones cuello.'),
('d566c6e4-df94-45a0-8d53-92a222764666', '8a2e8cb2-0d8c-4fd9-b5dd-12a48ded6521', 'en', 'Dumbbell Farmers Walk', 'Walk carrying weights at the sides. Cue: short and firm steps. Error: shrugging shoulders.'),
('0a600c69-00da-4d6b-aebd-7417426b0f17', '8a2e8cb2-0d8c-4fd9-b5dd-12a48ded6521', 'es', 'Paseo del granjero con mancuernas', 'Camina cargando pesas a los lados. Cue: pasos cortos y firmes. Error: encoger hombros.'),
('bd14c837-903a-4341-a9a0-48bd6087fe60', '8a36134e-d2cd-42a0-b27c-59c40c9cf2b9', 'en', 'Band External Shoulder Rotation', 'With the elbow glued to your side and flexed at 90 degrees, hold the band and rotate the forearm outward against resistance. Keep the elbow immobile throughout the movement. Essential for rotator cuff health and injury prevention.'),
('20fda563-79af-4b37-9379-9e0061ea803a', '8a36134e-d2cd-42a0-b27c-59c40c9cf2b9', 'es', 'Rotación externa hombro banda', 'Con el codo pegado al costado y flexionado a 90 grados, sujeta la banda y rota el antebrazo hacia afuera contra la resistencia. Mantén el codo inmóvil durante todo el movimiento. Esencial para la salud del manguito rotador y prevención de lesiones.'),
('b0e21f9a-5b58-4d4a-ba17-89b9d730174e', '8a4b0a01-0a1d-4af5-bdfc-ba926c4adf93', 'en', 'One Arm Push Ups', 'Perform push-ups using only one arm while the other is kept behind the back. Requires exceptional strength and core stabilization. Feet should be wider apart than in normal push-ups to maintain balance. Descend controlfully avoiding torso rotation.'),
('5b8ccf3b-5553-4c30-9b43-de0f6eb89adc', '8a4b0a01-0a1d-4af5-bdfc-ba926c4adf93', 'es', 'One arm push ups', 'Realiza flexiones utilizando solo un brazo mientras el otro se mantiene detrás de la espalda. Requiere fuerza excepcional y estabilización del core. Los pies deben estar más separados que en flexiones normales para mantener el equilibrio. Desciende controladamente evitando la rotación del torso.'),
('8cc335bc-de35-4179-ab0b-a1b81d8caaaa', '8a71d4eb-3612-4345-8632-583a46eafd35', 'en', 'Cross Over Plyometric Push Up', 'In the air, cross your hands before returning to the support position. Extreme upper body coordination. Cue: violent takeoff. Common error: not opening hands in time when landing.'),
('5675dc51-6d43-4be7-b18c-cb7ff274fcf1', '8a71d4eb-3612-4345-8632-583a46eafd35', 'es', 'Flexión pliométrica cruzada', 'En el aire, cruza las manos antes de volver a la posición de apoyo. Coordinación extrema de tren superior. Cue: despegue violento. Error común: no abrir las manos a tiempo al aterrizar.'),
('c8157796-19a4-4832-b71a-8dafd5b80b1d', '8a8cfb7a-89ab-4d5a-981e-3aa113e140f6', 'en', 'Fast Alternating Lunges', 'Quick leg change in a lunge position. Cue: maintain balance. Error: not lowering the back knee.'),
('a36cf185-02fc-45ea-9909-6936ee2bc83e', '8a8cfb7a-89ab-4d5a-981e-3aa113e140f6', 'es', 'Zancadas alternas rápidas', 'Cambio rápido de piernas en zancada. Cue: mantén el equilibrio. Error: no bajar la rodilla trasera.'),
('c16a1d31-d1f6-4a22-bf03-9e9728b8574d', '8a9bf5ba-1b43-460b-89d6-672c650cc2c7', 'en', 'Squat', 'Flex knees and hips lowering the body with an upright torso. Keep heels supported and knees aligned with feet.'),
('8a47ddfd-6c88-414f-8dce-ce336855279d', '8a9bf5ba-1b43-460b-89d6-672c650cc2c7', 'es', 'Sentadilla', 'Flexiona rodillas y cadera bajando el cuerpo con el torso erguido. Mantén los talones apoyados y las rodillas alineadas con los pies.'),
('a3702e01-4851-4366-9c68-1adc4fc8fcd5', '8ab1ef0e-6397-481e-83e9-1c9f7317668f', 'en', 'Double Kettlebell Cyclist Squat (Front Rack)', 'With heels elevated on a wedge and kettlebells in rack position, perform a deep squat emphasizing quadriceps work.'),
('aa33b7b2-171e-4e2c-a8f3-0638a9194ae7', '8ab1ef0e-6397-481e-83e9-1c9f7317668f', 'es', 'Sentadilla Ciclista con Kettlebell doble (Front Rack)', 'Con los talones elevados sobre una cuña y Kettlebells en posicion rack, realiza una sentadilla profunda enfatizando el trabajo de los cuadriceps.'),
('0a2d31ab-713e-4842-bb15-f61775e8efe2', '8afbbc66-5a77-47d2-aff9-cc5f73365a02', 'en', 'Mountain Climbers', 'In plank, bring knees to chest alternating quickly. Cue: back flat as a board. Error: bouncing hips upward.'),
('6206bbf0-03a4-4ed0-915a-5d86e96c98d8', '8afbbc66-5a77-47d2-aff9-cc5f73365a02', 'es', 'Escaladores (Mountain Climbers)', 'En plancha, lleva rodillas al pecho alternando rápidamente. Cue: espalda plana como una tabla. Error: rebotar la cadera hacia arriba.'),
('8edc46b7-4a71-4d5b-9d83-4469f80220e7', '8aff49a5-d3eb-427d-8428-d9c805b6a141', 'en', 'Lateral Jumps', 'Jump laterally from one leg to the other seeking distance. Cue: land with stability. Error: knee collapse.'),
('1c72fd19-b152-47a5-ba86-e8f46f19b87d', '8aff49a5-d3eb-427d-8428-d9c805b6a141', 'es', 'Saltos laterales', 'Salta lateralmente de una pierna a la otra buscando distancia. Cue: aterriza con estabilidad. Error: colapso de rodilla.'),
('db49e82d-288a-46e1-8ceb-739d3bc397f7', '8b0f1632-eb8a-44d7-b9a3-2a0cfb24df25', 'es', 'Plank slam', 'Desde plancha alta, toma el balón con una mano y golpéalo contra el suelo alternando lados. Requiere estabilidad excepcional del core. Mantén las caderas quietas mientras realizas el movimiento.'),
('51a1af5e-24bb-4229-99c8-ac68c4c33fb0', '8b2cbec1-5803-4c71-bc17-67cd0218b02c', 'en', 'Seated Leg Curl with Flexed Feet', 'Flex knees while seated. Cue: active feet. Error: lifting glutes.'),
('33d02da0-3e41-4978-9b24-397a63ad7e69', '8b2cbec1-5803-4c71-bc17-67cd0218b02c', 'es', 'Leg Curl sentado pies flexionados', 'Flexiona rodillas sentado. Cue: pies activos. Error: levantar glúteo.'),
('08db582b-d71c-4e94-be9f-ba49e5ff8af7', '8b352ca2-34aa-4d9a-b72f-5143d0a524b4', 'en', 'Kettlebell Swing', 'Swing the kettlebell between your legs and use an explosive hip hinge to drive it up to chest height.'),
('6142ad4e-ffb2-452b-87d1-d13257941bc6', '8b352ca2-34aa-4d9a-b72f-5143d0a524b4', 'es', 'Swing con Kettlebell', 'Balancea la pesa rusa entre las piernas y utiliza un empuje explosivo de cadera para elevarla hasta la altura del pecho.'),
('ea625f17-bf78-4bbf-a46d-444c59c66b4b', '8b68041a-219d-41c8-b5ef-049d10ed0306', 'en', 'Decline roll out', 'Roll out with knees or feet elevated on a bench. Significantly increases difficulty by changing the angle. Requires greater strength and stability. Progress gradually by increasing the height.'),
('7410216d-83e3-42f5-841d-db388a84a7c1', '8b68041a-219d-41c8-b5ef-049d10ed0306', 'es', 'Decline roll out', 'Roll out con las rodillas o pies elevados en un banco. Aumenta significativamente la dificultad al cambiar el ángulo. Requiere mayor fuerza y estabilidad. Progresa gradualmente aumentando la altura.'),
('cd742c05-b1a3-4f8d-9190-27e8d04378fc', '8b827ed8-eb0e-4411-977e-4208f4ad08ec', 'en', 'Ring Dips', 'Dips on gymnastic rings with maximum instability. Significantly harder than on parallel bars. Keep rings close to the body. Start with negatives and assists. Develops shoulder stabilizers.'),
('65ab3647-b1c3-41ff-9f8b-975cad67fb6e', '8b827ed8-eb0e-4411-977e-4208f4ad08ec', 'es', 'Fondos en anillas', 'Fondos en anillas gimnásticas con máxima inestabilidad. Significativamente más difícil que en paralelas. Mantén las anillas pegadas al cuerpo. Comienza con negativas y asistencias. Desarrolla estabilizadores del hombro.'),
('56d9a812-b40c-4488-bdd1-36d2c771a687', '8b860ad9-2741-4f68-9ffa-107406e3c610', 'en', 'Cable Double Bicep Curl', 'Arms in a cross position, flex toward the temples. Cue: elbows high and fixed. Error: moving elbows forward or down.'),
('1233160c-5904-4cfd-ae94-01862b1f01a3', '8b860ad9-2741-4f68-9ffa-107406e3c610', 'es', 'Curl doble bíceps en polea', 'Brazos en cruz, flexiona hacia las sienes. Cue: codos altos y fijos. Error: mover los codos hacia adelante o abajo.'),
('7bfda41e-41d2-430c-96f4-816fc5169c33', '8bd48f5f-cd86-4566-a567-2085f9425b7f', 'en', 'Plate Russian Twist', 'Rotate the torso with weight from side to side while seated. Cue: straight back. Error: moving only the arms.'),
('8a839c99-86fd-4c8d-ac74-de3fd23e2690', '8bd48f5f-cd86-4566-a567-2085f9425b7f', 'es', 'Giros rusos con disco', 'Gira el torso con peso de lado a lado sentado. Cue: espalda recta. Error: mover solo los brazos.'),
('8b864d63-a87a-4bdc-b1a3-8bac2f77c837', '8bdafdc6-bbbb-4c72-a9de-fbf5858e37ea', 'en', 'Narrow Grip Barbell Shoulder Press', 'Military press with hands together for triceps. Cue: elbows forward. Error: arching the lumbar.'),
('aaa63b3b-4a4b-483f-bcec-0258e0de2000', '8bdafdc6-bbbb-4c72-a9de-fbf5858e37ea', 'es', 'Press hombros barra agarre estrecho', 'Press militar con manos juntas para tríceps. Cue: codos hacia adelante. Error: arquear la lumbar.'),
('11f56e9a-f46a-4877-95cc-880e571a78ab', '8be68853-8a81-44f1-a827-e0d9a1707b48', 'en', 'Incline Bench Rear Delt Flyes', 'Chest on bench, lift weights laterally. Objective: rear deltoid. Cue: elbows out. Error: squeezing shoulder blades together.'),
('d924523b-a266-4d98-9c3d-6c149ecf20d9', '8be68853-8a81-44f1-a827-e0d9a1707b48', 'es', 'Pájaros banco inclinado', 'Pecho en banco, eleva pesas lateralmente. Objetivo: deltoides posterior. Cue: codos fuera. Error: juntar escápulas.'),
('d191077e-4a03-4b9d-b5e2-1dba890fee13', '8bfcbfdb-97f4-4abe-b497-2125bb20a7d3', 'en', 'Landmine Meadows Row', 'Row with one arm using the end of the landmine bar from the side. Cue: elbow outward. Error: rotating hip.'),
('f7802cd6-f7c0-4e15-b588-15f1c860c85b', '8bfcbfdb-97f4-4abe-b497-2125bb20a7d3', 'es', 'Meadows Row landmine', 'Rema a un brazo con extremo de barra landmine de lado. Cue: codo hacia afuera. Error: rotar cadera.'),
('b325d63b-13ed-4591-b4a6-49df07a00f3f', '8c109722-6763-46d9-9fde-a4d76cff5716', 'en', 'Slam Ball Feet Elevated Russian Twist', 'With feet in the air, rotate the torso from side to side touching the floor with the heavy medicine ball to work the obliques.'),
('40ecc1dd-d3d3-4b31-a93a-146310e5016a', '8c109722-6763-46d9-9fde-a4d76cff5716', 'es', 'Russian Twist con pies elevados y Slam Ball', 'Con los pies en el aire, gira el torso de lado a lado tocando el suelo con el balón medicinal pesado para trabajar los oblicuos.'),
('f326e515-a9ed-40d6-9598-d92ca715eb05', '8c2108b5-5406-42ab-a7c1-a95a0af8a940', 'en', 'Stable Wide Grip Push Ups', 'Hands beyond shoulder-width, lower chest to floor. Objective: emphasis on outer pectoral. Cue: elbows at 45 degrees. Common error: allowing hips to sag.'),
('3f474e3d-fb9c-4910-ac09-efb56b063893', '8c2108b5-5406-42ab-a7c1-a95a0af8a940', 'es', 'Flexiones con manos anchas estables', 'Manos más allá de la anchura de hombros, baja el pecho al suelo. Objetivo: énfasis en pectoral externo. Cue: codos a 45 grados. Error común: permitir que la cadera se hunda.'),
('7cc5b6b0-498c-4bac-959f-74c4cae9381a', '8c47ba13-df4a-4e1b-9ca0-34cc2440c23c', 'en', 'Parallette L Sit to Tuck Planche', 'Perform the dynamic transition from an L-Sit position to a Tuck Planche, always keeping arms locked and the core under maximum tension.'),
('749bd56d-4572-4ab1-8186-425e8cfae6e5', '8c47ba13-df4a-4e1b-9ca0-34cc2440c23c', 'es', 'L-Sit a Tuck Planche en paralelas', 'Realiza la transición dinámica desde una posición de L-Sit hasta una Tuck Planche, manteniendo siempre los brazos bloqueados y el core en máxima tensión.'),
('eb2753e5-5e21-4acf-ab86-6dd46a0e217f', '8c7697c2-5fb8-4a8f-9f9f-aa04fc2e1d28', 'en', 'Knee-to-Elbow Vertical Jump', 'Jump and bring one knee toward the opposite elbow in the air. Core dynamism. Cue: quick torso rotation. Common error: not jumping high enough for the touch.'),
('6bc3d909-c723-4891-90be-0c7ec2a26bf5', '8c7697c2-5fb8-4a8f-9f9f-aa04fc2e1d28', 'es', 'Salto vertical rodilla a codo', 'Salta y lleva una rodilla hacia el codo opuesto en el aire. Dinamismo de core. Cue: giro rápido del torso. Error común: no saltar lo suficiente para el toque.'),
('502e7d81-f163-4eca-90d1-9130fdc6ce7b', '8c9bd24d-6132-4590-adea-2bcc0ddaac5a', 'en', 'One-Arm Dumbbell Cuban Press', 'Standing, perform an upright row, externally rotate the shoulder 90 degrees, and finish with a military press. Reverse the movement.'),
('95514041-d0f4-4d74-9414-820dec479640', '8c9bd24d-6132-4590-adea-2bcc0ddaac5a', 'es', 'Press Cubano a una mano con mancuerna', 'De pie, realiza un remo vertical, rota externamente el hombro 90 grados y termina con un press militar. Invierte el movimiento.'),
('b354c2dc-c684-452a-9491-9acee98b1b63', '8cd8aeb3-dbc1-4b99-9e06-afb4265d69e2', 'en', 'Curtsy Lunge Jump', 'Curtsy lunges alternating with explosive jumps. Works glutes from multiple angles with a plyometric component. Requires exceptional coordination and balance. Keep the torso upright during the movement.'),
('b8513a96-849e-4b3c-8f0e-d980ec220e62', '8cd8aeb3-dbc1-4b99-9e06-afb4265d69e2', 'es', 'Zancada reverencia salto', 'Zancadas cruzadas (curtsy lunges) alternando con saltos explosivos. Trabaja glúteos desde múltiples ángulos con componente pliométrico. Requiere coordinación y equilibrio excepcionales. Mantén el torso erguido durante el movimiento.'),
('61a4e2e6-8a34-4a50-8bc3-599f8d57ebf8', '8cd8c30a-311b-4a3b-889a-e040763ebb50', 'en', 'TRX Skater Squat', 'Use the TRX as support while performing a skater squat, bringing the free knee toward the floor behind the supporting heel.'),
('fc556f81-e14f-4d88-9f94-d0a4a16a818e', '8cd8c30a-311b-4a3b-889a-e040763ebb50', 'es', 'Sentadilla patinadora en TRX', 'Usa el TRX como soporte mientras realizas una sentadilla patinadora, llevando la rodilla libre hacia el suelo por detrás del talón de apoyo.'),
('ccbb0f26-21eb-4d35-8b3d-20302d395503', '8d4d6e06-f086-4cf1-af91-b9ab560779b3', 'en', 'Hanging Knee Elevation on Bar', 'Hanging from a bar, bring knees toward the chest in a controlled manner. Objective: lower abdominal strength. Cue: do not swing. Common error: using leg momentum to perform the movement.'),
('10392af1-d49e-4471-ac85-b02e600ca2df', '8d4d6e06-f086-4cf1-af91-b9ab560779b3', 'es', 'Elevación de rodillas colgado en barra', 'Colgado de barra, lleva las rodillas hacia el pecho de forma controlada. Objetivo: fuerza abdominal inferior. Cue: no te balancees. Error común: usar el impulso de las piernas para realizar el movimiento.'),
('7772bbb8-ae12-4dad-af23-fc178fcfdfc8', '8d62e416-119b-473d-bcd5-2f29586e7c40', 'en', 'Alternating Double Dumbbell Half Kneeling Overhead Press', 'In a half-kneeling position, alternate the dumbbell overhead press, increasing the demand for lateral core stability.'),
('e085fa36-5416-418a-aa31-a5c96365744e', '8d62e416-119b-473d-bcd5-2f29586e7c40', 'es', 'Press Overhead medio arrodillado alterno con mancuernas', 'En posicion de caballero, alterna el press de hombros con mancuernas, lo que incrementa la demanda de estabilidad lateral del core.'),
('2c7657a7-f3c3-4253-80de-6651c2b6e3c9', '8da952f7-083f-4811-a812-94c2c941fc91', 'en', 'Standing EZ-Bar Curl', 'Perform a standing EZ-bar biceps curl. Keep the elbows close to the body, curl the bar under control, and avoid swinging the torso.'),
('e9d26f93-e515-4b4a-ae83-1fe77f7dc250', '8da952f7-083f-4811-a812-94c2c941fc91', 'es', 'Curl barra Z de pie', 'Realiza un curl de bíceps de pie con barra Z. Mantén los codos cerca del cuerpo, eleva la barra de forma controlada y evita balancear el tronco.'),
('1cdb1cd7-bde0-4736-80ba-62e7eaf0dc9e', '8e46fb66-169d-4d4d-9d22-e052aa917f93', 'en', 'Ring Row', 'Hold the rings and lean the body back. Keeping the body aligned, pull the chest toward the rings and return to the starting position by extending the arms.'),
('2cbcc42e-5bc8-4841-9868-ce8ebe5ea0ac', '8e46fb66-169d-4d4d-9d22-e052aa917f93', 'es', 'Remo en anillas', 'Sujeta las anillas e inclina el cuerpo hacia atrás. Manteniendo el cuerpo alineado, tira del pecho hacia las anillas y regresa a la posición inicial extendiendo los brazos.'),
('b52c7ce7-2198-43eb-afcb-86b473652144', '8e4b9f4a-758a-40a0-9c02-21a54233e897', 'es', 'Typewriter pull ups', 'Realiza una dominada y en la posición superior, desplázate lateralmente llevando la barbilla de una mano a la otra manteniendo la altura. Es como escribir en una máquina de escribir en la barra. Requiere fuerza isométrica excepcional y control del movimiento lateral.'),
('9a734018-25f8-412b-b76c-fac2c53199bf', '8e611e2f-c9d7-4873-b83b-909449f7a724', 'en', 'Cable Reverse Lunge', 'Backward lunges with frontal cable resistance. Adds an anterior stabilization component. Keep torso upright resisting the cable''s pull. Excellent for athletes needing deceleration.'),
('9b4ca84c-b2a0-4c6b-bdb8-d4336ad70842', '8e611e2f-c9d7-4873-b83b-909449f7a724', 'es', 'Zancada posterior cable', 'Zancadas hacia atrás con resistencia de cable frontal. Añade componente de estabilización anterior. Mantén torso erguido resistiendo la tracción del cable. Excelente para atletas que necesitan desaceleración.'),
('ae22c10e-c1d3-4647-aa29-bee12bbb1c5f', '8ecda888-e899-447f-b281-2b2b9860f82b', 'en', 'Double Kettlebell Front Rack Step Up', 'Step up onto a bench while holding two kettlebells at the chest (front rack), keeping elbows up and the torso upright.'),
('565a9b0c-340f-4167-b31f-afdcf82b5bf1', '8ecda888-e899-447f-b281-2b2b9860f82b', 'es', 'Step Up Front Rack con Kettlebell doble', 'Sube a un banco sosteniendo dos pesas rusas en el pecho (front rack), manteniendo los codos arriba y el torso erguido.'),
('e2063e95-9908-4543-b932-efbf45084bf8', '8ee3d6c9-ef70-48b1-afab-f95e7ec8a74b', 'en', 'Battle Ropes Single Arm Waves', 'Single arm waves. Objective: shoulder/endurance. Cue: core locked. Error: rotating torso.'),
('d3583604-136f-4c3d-bb94-c16d7ae282ef', '8ee3d6c9-ef70-48b1-afab-f95e7ec8a74b', 'es', 'Battle ropes ondas un brazo', 'Ondas brazo solo. Objetivo: hombro/resistencia. Cue: core bloqueado. Error: rotar torso.'),
('381d2766-d975-495e-b638-fbbe0c881878', '8f05d372-8d09-4bf0-83ad-13d109d13994', 'es', 'Plank frontal a una mano con pies elevados sobre Fitball', 'Apoya un antebrazo en el suelo y coloca ambos pies sobre el Fitball inestable mientras mantienes la plancha con un solo apoyo de brazo.'),
('8a6a83f5-535e-47dd-b836-7b392913ae24', '8ffa287b-b5f5-425b-88f3-aa00211c023d', 'es', 'Zancada caminando con barra tras nuca', 'Camina realizando zancadas con una barra apoyada sobre los trapecios, manteniendo el equilibrio y el core activado en cada paso.'),
('298d0bf3-a117-46cb-a629-480580eda9b2', '900a8049-24e8-4661-82b5-45635303906a', 'en', 'Double Kettlebell Half Kneeling Seesaw Overhead Press', 'In a half-kneeling position, alternate the shoulder press with two kettlebells in a rhythmic motion, challenging torso balance.'),
('820aeb61-e247-4e24-be96-387d0213f6a4', '900a8049-24e8-4661-82b5-45635303906a', 'es', 'Press Overhead Seesaw medio arrodillado con Kettlebell doble', 'En posición de caballero, alterna el press de hombros con dos Kettlebells en un movimiento rítmico, desafiando el equilibrio del torso.'),
('ee24934f-4a70-4bc0-9f8c-7c3922e0ebc2', '9022dbe3-a937-4fd8-9e52-5e346371a5eb', 'en', 'Bench Squat', 'Lower the hips as in a normal squat until your glutes lightly touch the bench and return up immediately.'),
('80a741af-fc92-43fb-a81f-ece3c22c306d', '9022dbe3-a937-4fd8-9e52-5e346371a5eb', 'es', 'Sentadilla a banco', 'Baja la cadera como en una sentadilla normal hasta que tus glúteos toquen ligeramente el banco y vuelve a subir inmediatamente.'),
('2ee21b0a-b166-4505-8fdf-1f74876d5ee2', '9041bfc4-8d4a-4a10-9ff7-17338f5da966', 'en', 'Seated Behind the Neck Triceps Extension', 'Hold a dumbbell with both hands and lower it behind the head. Closed elbows. Straight back. Do not arch the lower back.'),
('136a0fa0-91d0-4e21-a2e0-2d78f601245c', '9041bfc4-8d4a-4a10-9ff7-17338f5da966', 'es', 'Extensión de tríceps tras nuca sentado', 'Sujeta una mancuerna con ambas manos y bájala tras la cabeza. Codos cerrados. Espalda recta. No arquees la zona lumbar.'),
('931eae7e-97fa-4937-bd6d-ad89ab359563', '9047bce5-d1f6-43ea-b68f-6e10ed4cbdfc', 'en', 'Double Kettlebell Thruster', 'Hold two kettlebells in rack, lower into a deep squat, and use the upward inertia to press both weights to the ceiling.'),
('76453fc2-3aed-49ba-9cbb-c683d5809912', '9047bce5-d1f6-43ea-b68f-6e10ed4cbdfc', 'es', 'Thruster con Kettlebell doble', 'Sujeta dos Kettlebells en rack, baja en sentadilla profunda y aprovecha la inercia de la subida para presionar ambas pesas al techo.'),
('1f13f849-bea4-45aa-a1a1-95a7c7113628', '906149cb-71a7-4a62-8194-fc5b24c977a5', 'en', 'Weighted Dips', 'Weighted dips on parallel bars for pectorals and triceps, controlling depth and avoiding shoulder collapse.'),
('52da964c-5f97-49e1-8c57-5365fc2cb5a6', '906149cb-71a7-4a62-8194-fc5b24c977a5', 'es', 'Fondos lastrados', 'Baja con control hasta rango cómodo, pecho abierto y hombros estables. Sube empujando sin rebotar abajo.'),
('1f8315a6-b7b9-427d-942f-550961600c19', '909f416c-70af-440d-9534-f7c08ee91279', 'en', 'Dumbbell Triceps Kickback', 'Torso leaning, extend the arm backward keeping the elbow fixed. Objective: lateral triceps head isolation. Cue: lock the arm up for 1 second. Common error: swinging the dumbbell like a pendulum.'),
('11531f79-edd4-49a6-85d6-cd508b89605c', '909f416c-70af-440d-9534-f7c08ee91279', 'es', 'Patada de tríceps con mancuerna', 'Torso inclinado, extiende el brazo hacia atrás manteniendo el codo fijo. Objetivo: aislamiento de la cabeza lateral del tríceps. Cue: bloquea el brazo arriba 1 segundo. Error común: balancear la mancuerna como un péndulo.'),
('0ae04518-438f-4b7a-8594-15fd7b2afeeb', '90b18419-e8d7-4d9d-b642-3df05d63a754', 'en', 'Rotational Toss with Step', 'Take a step forward while throwing the ball laterally against a wall. Dynamic power. Cue: pivot the back foot. Common error: dragging the back foot instead of pivoting.'),
('826ea5a1-2c5f-4eb2-aa81-1ba59ab5f178', '90b18419-e8d7-4d9d-b642-3df05d63a754', 'es', 'Lanzamiento rotacional con paso', 'Realiza un paso hacia adelante mientras lanzas el balón lateralmente contra una pared. Potencia dinámica. Cue: pivota el pie trasero. Error común: arrastrar el pie trasero en lugar de pivotar.'),
('816167ac-54a2-439f-9b95-d72ef936d0f1', '90dc3775-8b77-45b9-984f-b182e38ff669', 'en', 'Parallette Push Up', 'Grip the parallettes and place body in plank position. Lower chest beyond hand level for greater range of motion, then push up until arms are extended.'),
('900fc41b-ea63-4539-8634-52b4e928d851', '90dc3775-8b77-45b9-984f-b182e38ff669', 'es', 'Flexiones en paralelas', 'Agarra las paralelas y coloca el cuerpo en posición de plancha. Baja el pecho más allá del nivel de las manos para un mayor rango de movimiento, luego empuja hacia arriba hasta extender los brazos.'),
('7be979e1-cda7-4b64-9f4a-593cf5638ac0', '912357f1-43c1-4b44-9b4e-2f153cbdec01', 'en', 'Semi-Stiff Leg Deadlift', 'Lower the bar brushing the legs with knees almost locked (minimal flexion). Objective: maximum hamstring stretch. Cue: push hips far back. Common error: rounding the lumbar area when lowering.'),
('cc97bfeb-4c50-435b-9b0e-a58ac843478e', '912357f1-43c1-4b44-9b4e-2f153cbdec01', 'es', 'Peso muerto con piernas semi-rígidas', 'Baja la barra rozando las piernas con las rodillas casi bloqueadas (mínima flexión). Objetivo: estiramiento máximo de isquiotibiales. Cue: lleva la cadera muy atrás. Error común: redondear la zona lumbar al bajar.'),
('4dddab1b-bb77-4b64-b389-0e73391db5c0', '91259ef7-b72a-4003-88b7-252e1145f221', 'en', 'Superband Alternating Shoulder Dislocates', 'Perform the shoulder dislocation movement by passing arms alternately overhead to improve joint mobility.'),
('fb5cc836-ae8d-479b-b7ec-ef47c40ba114', '91259ef7-b72a-4003-88b7-252e1145f221', 'es', 'Dislocaciones alternas de hombro con banda elástica', 'Realiza el movimiento de dislocacion de hombro pasando los brazos de forma alterna sobre la cabeza para mejorar la movilidad articular.'),
('91ac69ab-3fc6-4943-92cd-18927d7422db', '914e0ff0-dbd2-4db8-817c-f2b64f6ef5e5', 'en', 'Kettlebell Goblet Squat', 'Hold the kettlebell against the chest with both hands like a chalice. Perform squats maintaining the torso upright. The position of the weight helps maintain better posture. Excellent for learning correct squat technique.'),
('29a60d6c-2512-44de-92b8-e4fb1b0a3f0b', '914e0ff0-dbd2-4db8-817c-f2b64f6ef5e5', 'es', 'Goblet squat kettlebell', 'Sostén la kettlebell contra el pecho con ambas manos como un cáliz. Realiza sentadillas manteniendo el torso erguido. La posición del peso ayuda a mantener mejor postura. Excelente para aprender la técnica correcta de sentadilla.'),
('8743aa17-1da2-4bd6-b5f7-0eff84469bfd', '9163316e-0fb9-45a8-b46b-fb5116f2817d', 'en', 'Lateral Depth Jump', 'Drop from a box and immediately jump laterally over an obstacle. Improves force absorption and redirection. Cue: minimum ground contact time. Common error: letting the knee cave inward.'),
('3f40dba0-c5fe-49b6-bbbd-781e3f74c424', '9163316e-0fb9-45a8-b46b-fb5116f2817d', 'es', 'Salto de profundidad lateral', 'Cae de un cajón y salta lateralmente de forma inmediata sobre un obstáculo. Mejora la absorción de fuerza y redirección. Cue: contacto mínimo con el suelo. Error común: dejar que la rodilla se hunda hacia adentro.'),
('701cdbc7-dcc1-4950-9411-b8b8194a5634', '91919c61-0c5a-421e-bda1-d13b89c02723', 'en', 'Single Arm Kettlebell Suitcase Deadlift', 'Lift the kettlebell from the floor with one hand at the side of your body, keeping the back straight and avoiding lateral leaning.'),
('00a836d1-6d1c-4bf1-938d-9de6fa4697ef', '91919c61-0c5a-421e-bda1-d13b89c02723', 'es', 'Peso muerto maleta con Kettlebell a una mano', 'Levanta la Kettlebell del suelo con una mano a un costado del cuerpo, manteniendo la espalda recta y evitando inclinaciones laterales.'),
('a11468b3-948f-43d2-8928-1acfc88e59b4', '91a3e724-3f96-4745-a947-7637c28aa343', 'es', 'Plank bosu', 'Plancha con antebrazos o manos sobre el bosu. La inestabilidad multiplica la activación del core. Puede hacerse con el lado redondo hacia arriba o abajo según el nivel. Resiste activamente el movimiento manteniendo el cuerpo alineado.'),
('e1e23d29-ff89-46c9-b2c7-7d2cab5d1d51', '925d3517-b417-4350-af4f-3f42263db8dd', 'es', 'Puente de glúteo isométrico con extensión alterna', 'Mantén la posición alta del puente de glúteo. Sin bajar la cadera, extiende una pierna hacia adelante, regresa y cambia de pierna alternativamente.'),
('3a16653b-d79a-4304-9fcf-b4e7a3fa09d4', '92a1bb97-9eb3-48ee-937a-613b801c9c8c', 'en', 'Ring Feet Elevated Bulgarian Row', 'Perform a ring row with feet elevated and elbows flared out to emphasize the rear delts and upper back.'),
('82d5b336-0d6c-49cc-a32a-513417d21274', '92a1bb97-9eb3-48ee-937a-613b801c9c8c', 'es', 'Anillas Pies Remo Búlgaro Elevado', 'Realiza un remo en anillas con pies elevados y codos abiertos hacia afuera para enfatizar el deltoides posterior y la parte alta de la espalda.'),
('97506416-58f4-4687-91a1-4b01d94c0f57', '92a77dc9-fbda-4686-ba6f-3bff28509a67', 'en', 'TRX Pistol Squat', 'Single-leg squat using TRX for minimal assistance. Allows learning the movement pattern with support. Gradually reduce TRX dependency. Keep the heel planted and the knee aligned.'),
('bb535d84-8890-44f4-bd83-2cffc699564f', '92a77dc9-fbda-4686-ba6f-3bff28509a67', 'es', 'Sentadilla pistol TRX', 'Sentadilla a una pierna usando TRX para asistencia mínima. Permite aprender el patrón de movimiento con apoyo. Reduce gradualmente la dependencia del TRX. Mantén el talón plantado y la rodilla alineada.'),
('36fd7f98-d511-42cf-93ec-78d3745e0871', '92d8153d-4d04-4ddc-9049-05e9dfa9355f', 'en', 'Alternating Single Arm Kettlebell Half Kneeling Around the World High Catch', 'Kneeling in a split stance, pass the kettlebell around your waist switching hands and performing a high catch in front of the chest.'),
('0a42fb1c-cb05-44bf-a224-c9028a0e823e', '92d8153d-4d04-4ddc-9049-05e9dfa9355f', 'es', 'Around the World medio arrodillado con captura alta', 'Arrodillado en posicion de caballero, pasa la pesa rusa alrededor de tu cintura intercambiandola de mano y realizando una captura alta frente al pecho.'),
('8887c53b-8a2e-4bb9-99a9-bfccf29fbae1', '932d05ca-0d5a-4b50-9f01-600d45649f1d', 'en', 'Unilateral High Pulley Row', 'Kneeling or seated, pull a stirrup handle toward the shoulder with one arm. Objective: isolated lat. Cue: elbow toward the side pocket. Common error: rotating the trunk excessively toward the pulley.'),
('1bb06f77-775b-4294-9329-a57e5671f88b', '932d05ca-0d5a-4b50-9f01-600d45649f1d', 'es', 'Remo unilateral en polea alta', 'De rodillas o sentado, tira de un estribo hacia el hombro con un solo brazo. Objetivo: dorsal aislado. Cue: codo hacia el bolsillo lateral. Error común: rotar el tronco excesivamente hacia la polea.'),
('88ef166b-3572-4230-8846-8792aad824e5', '93391b55-2840-4f1e-a7b2-06032e1e04ea', 'en', 'Incline Close Grip EZ Bar Bench Press', 'Lying on an incline bench, hold the EZ bar with a narrow grip. Lower the bar toward the upper chest flexing the elbows and extend arms forcefully to work the triceps.'),
('a6d19025-a9bf-473d-82d7-3cc1210764a1', '93391b55-2840-4f1e-a7b2-06032e1e04ea', 'es', 'Press de banca inclinado agarre cerrado con barra Z', 'Tumbado en un banco inclinado, sujeta la barra Z con un agarre estrecho. Baja la barra hacia la parte superior del pecho flexionando los codos y extiende los brazos con fuerza para trabajar el triceps.'),
('85c974b2-b413-4f51-b239-a5a92c1e0afa', '937cfd17-7edf-4252-9ce2-0518ae2c6a22', 'en', 'Anderson Squat', 'Similar to a pin squat but starting from the lowest possible position. Named after Paul Anderson. Develops absolute strength from an unfavorable position. Progress by gradually raising the pins.'),
('9c323631-8e21-4635-bff3-e4da68badc1e', '937cfd17-7edf-4252-9ce2-0518ae2c6a22', 'es', 'Sentadilla anderson', 'Similar a sentadilla desde pines pero comenzando desde la posición más baja posible. Nombrada por Paul Anderson. Desarrolla fuerza absoluta desde posición desfavorable. Progresa subiendo gradualmente los pines.'),
('0cef0cea-b7f3-4d44-aaf5-9d631a68c897', '93991735-524f-4c21-ae48-c68691ace3c6', 'en', 'Dumbbell Windmill', 'With a dumbbell extended overhead, perform a controlled lateral flexion touching the floor with the free hand while keeping your eyes on the dumbbell. Requires great flexibility in hips and hamstrings, as well as shoulder stability.'),
('ca3c8d58-e026-487f-af4f-0d8680b7c286', '93991735-524f-4c21-ae48-c68691ace3c6', 'es', 'Molino de viento mancuernas', 'Con una mancuerna extendida sobre la cabeza, realiza una flexión lateral controlada tocando el suelo con la mano libre mientras mantienes la vista en la mancuerna. Requiere gran flexibilidad en caderas y isquiotibiales, además de estabilidad del hombro.'),
('c0ed5429-eb91-4bdb-b002-70025975b430', '93c92e31-f5a5-4c3d-82bd-fd9ec3623f45', 'en', 'Bent Over Barbell Row', 'Torso at 45 degrees, pull the bar toward the navel retracting the scapulae. Cue: elbows back. Error: standing up during the set due to fatigue.'),
('c4b7426c-e2c9-4946-8bec-054df79f8a39', '93c92e31-f5a5-4c3d-82bd-fd9ec3623f45', 'es', 'Remo con barra inclinado', 'Torso a 45 grados, tira de la barra hacia el ombligo retrayendo escápulas. Cue: codos hacia atrás. Error: erguirse durante la serie por fatiga.'),
('2ca8f08d-9ca7-44b0-9576-d27ed6f88d0e', '93d593fe-5f88-48ab-98e1-7984b1aa5573', 'en', 'Cable Bicep Curl', 'With a low pulley and a straight or EZ bar, perform curls keeping elbows fixed at your sides. The cable provides constant tension throughout the entire range of motion, even at the top position where dumbbells lose tension.'),
('c4919d6e-a6ab-4008-a1f4-9adf34058933', '93d593fe-5f88-48ab-98e1-7984b1aa5573', 'es', 'Curl bíceps cable', 'Con la polea baja y una barra recta o EZ, realiza curls manteniendo los codos fijos a los costados. El cable proporciona tensión constante durante todo el rango de movimiento, incluso en la posición superior donde las mancuernas pierden tensión.'),
('0a4bf74e-0ded-4074-a452-f261fb10b904', '94532bf8-78b3-48c6-bc53-6ce891ae72cb', 'en', 'Lateral Ball Slam', 'Throw the medicine ball against the ground to your side without rotating the trunk excessively. Oblique explosive force. Cue: straight arms at the start. Common error: letting the ball hit your feet.'),
('58121f20-6a65-48e4-84d5-facbc1cccd8d', '94532bf8-78b3-48c6-bc53-6ce891ae72cb', 'es', 'Slam lateral de balón', 'Lanza el balón medicinal contra el suelo a tu lado sin rotar el tronco excesivamente. Fuerza explosiva de oblicuos. Cue: brazos estirados al inicio. Error común: dejar que el balón golpee tus pies.'),
('d02a50c6-883e-40f5-8696-2c833075205a', '94918148-fce8-4f27-8db3-ebd801227d1e', 'en', 'Ring Plank', 'Perform a plank by supporting your hands or forearms on the rings, resisting their instability to activate the core.'),
('a6a9d5d2-ee39-49d8-9369-773df18c2331', '94918148-fce8-4f27-8db3-ebd801227d1e', 'es', 'Ring Plank', 'Realiza una plancha apoyando las manos o antebrazos en las anillas, resistiendo la inestabilidad de las mismas para activar el core.'),
('2800148e-8aab-4ae2-85aa-6a4b3a0b593e', '94d50791-9be5-4b1b-a58e-5140a37b2945', 'en', 'Jump Squat', 'Explosive squat jumping off the ground. Cue: land on your toes. Error: stiff landing.'),
('fea7c85c-e6c4-4f47-aca4-9c7c141b24c9', '94d50791-9be5-4b1b-a58e-5140a37b2945', 'es', 'Sentadilla con salto', 'Sentadilla explosiva despegando del suelo. Cue: aterriza con las puntas. Error: aterrizaje rígido.'),
('58f22851-b9af-415f-ad39-515927e6d3a7', '94e36f1b-d510-4077-b67a-c8543af81b98', 'en', 'Circle roll out', 'Perform full circles with the wheel instead of straight lines. Extremely challenging for the core. Start with small circles and increase gradually. Alternate directions for balanced work.'),
('8a98a563-fd33-41bd-9d62-8d550bb748fe', '94e36f1b-d510-4077-b67a-c8543af81b98', 'es', 'Circle roll out', 'Realiza círculos completos con la rueda en lugar de líneas rectas. Extremadamente desafiante para el core. Comienza con círculos pequeños y aumenta gradualmente. Alterna direcciones para trabajo equilibrado.'),
('532feb05-0311-45b1-8690-aa1466664e3d', '9501ecb2-c1a7-4079-b1e2-8a86221fdedb', 'en', 'Ring Scapular Pull Up', 'Hang from the rings and perform small lifts by activating only the scapulae, keeping your arms completely straight.'),
('ab9366c2-9f76-4a1b-bb0c-22ec5e2fbfa5', '9501ecb2-c1a7-4079-b1e2-8a86221fdedb', 'es', 'Anillas Escapular Pull Up', 'Cuelgate de las anillas y realiza pequeñas elevaciones activando solo las escapulas, manteniendo los brazos completamente rectos.'),
('bad65201-3afb-4cf2-8ea6-9da0c5fd1098', '950a0386-b819-42de-ac51-c45e160e72fe', 'es', 'Press pecho polea pie un pie delante', 'Empuja cables al frente de pie. Cue: base estable. Error: inclinar torso.'),
('e9a27595-7e69-4916-a3cc-e450ec0fabd5', '9513a12c-f28b-41b3-8086-8c81c6f806df', 'en', 'Seated Plate Lu Raise', 'Seated, perform a full lateral raise with plates or light dumbbells until they touch over the head, emphasizing the lateral deltoid.'),
('c890c179-c3a5-4224-90d2-62379c6826f9', '9513a12c-f28b-41b3-8086-8c81c6f806df', 'es', 'Elevación Lu sentado con discos', 'Sentado, realiza una elevacion lateral completa con discos o mancuernas ligeras hasta que se toquen sobre la cabeza, enfatizando el deltoides lateral.'),
('b27f3892-92fa-429a-b44e-c31d0b634a55', '95141383-8fee-45c8-8390-c8aec1caf43f', 'en', 'Frog Jump', 'Long jump starting from a deep squat and ending in a squat. Hip extension power. Cue: arms forward when jumping. Common error: rounding the lower back upon landing.'),
('188265ab-14f6-4d19-bbd1-fe649a170461', '95141383-8fee-45c8-8390-c8aec1caf43f', 'es', 'Salto de rana', 'Salto largo partiendo de una sentadilla profunda y terminando en sentadilla. Potencia de extensión de cadera. Cue: brazos hacia adelante al saltar. Error común: redondear la espalda baja al aterrizar.'),
('39aeb133-555f-4d4a-bad4-206383fe6954', '95479d10-865d-4c33-87cb-b12f36d36d1f', 'en', 'Barbell Thruster', 'Combines a front squat with a shoulder press in a fluid continuous movement. Descend into a front squat and upon rising use the momentum to press the bar overhead. Excellent metabolic exercise that develops power and endurance.'),
('44a184f9-7012-4828-a773-1ff88793a214', '95479d10-865d-4c33-87cb-b12f36d36d1f', 'es', 'Thruster barra', 'Combina una sentadilla frontal con un press de hombros en un movimiento fluido continuo. Desciende en sentadilla frontal y al subir usa el impulso para presionar la barra sobre la cabeza. Excelente ejercicio metabólico que desarrolla potencia y resistencia.'),
('f6f15377-ecb0-430d-8587-aa049d2b8260', '954c2c21-a706-47f7-9d49-8f15cedb23cd', 'en', 'Cable Rope Staggered Stance High to Low Chop', 'Standing with one foot in front of the other, pull the cable from above crossing the body downward, using the core to rotate.'),
('83cbad01-2f3b-4ffe-843c-6ecae1188831', '954c2c21-a706-47f7-9d49-8f15cedb23cd', 'es', 'Woodchop alto a bajo con cable (Staggered)', 'De pie con un pie delante del otro, tira del cable desde arriba cruzando el cuerpo hacia abajo, usando el core para rotar.'),
('4e8dd58f-2924-46ef-af8b-03365651f412', '955bc951-fc8b-4700-bade-f83d4ca51d75', 'en', 'Hollow Body Hold', 'Lie face up and press the lower back against the floor. Raise legs and shoulders simultaneously, forming a banana with the body. Maintain position.'),
('35c3391d-363c-478d-98d6-e89c7ad92f0d', '955bc951-fc8b-4700-bade-f83d4ca51d75', 'es', 'Hollow Body Hold', 'Acuéstate boca arriba y presiona la espalda baja contra el suelo. Levanta las piernas y los hombros simultáneamente, formando una banana con el cuerpo. Mantén la posición.'),
('624b02d6-d40e-43db-9a36-5f30d885ec57', '95c584f4-8d23-42d8-8432-f6337e28d47f', 'en', 'Kneeling Ab Wheel Rollout', 'Slide the wheel forward maintaining abdominal contraction and return. Powerful core. Neutral back. Do not let the hips sag to the floor.'),
('dbac0d0c-1ed0-4fbb-9ac4-302c577f5169', '95c584f4-8d23-42d8-8432-f6337e28d47f', 'es', 'Rueda abdominal rodillas', 'Desliza la rueda adelante manteniendo el abdomen contraído y vuelve. Core potente. Espalda neutra. No dejes caer la cadera al suelo.'),
('b19f40c4-5e06-49ce-9f3a-7cb1bc3f24a5', '95e48c8f-c33f-4b85-9bec-02cfed8a9d42', 'en', 'Unilateral Dumbbell Row', 'One foot and hand on a bench, pull the dumbbell toward the hip with the other arm. Cue: back parallel to the floor. Error: rotating the trunk while pulling.'),
('1d5c898f-277b-4040-bfda-e84350b5f439', '95e48c8f-c33f-4b85-9bec-02cfed8a9d42', 'es', 'Remo unilateral con mancuerna', 'Un pie y mano en banco, tira de la mancuerna hacia la cadera con el otro brazo. Cue: espalda paralela al suelo. Error: girar el tronco al tirar.'),
('12339341-402b-436d-8061-0409a3c9ff7e', '962de55a-b673-4af2-a974-eebab72506f9', 'en', 'Single Arm Kettlebell Front Rack Contralateral Step Up', 'Hold the kettlebell in the rack position on one shoulder and step up onto the bench with the opposite leg, keeping the core tight.'),
('71d95e36-a13f-44c1-864a-7db4f9dcfab2', '962de55a-b673-4af2-a974-eebab72506f9', 'es', 'Step Up contralateral Front Rack con Kettlebell a una mano', 'Sostén la Kettlebell en posición de rack en un hombro y sube al banco con la pierna opuesta, manteniendo el core firme.'),
('48d58425-1a1f-47fc-8675-b1e895e133ef', '9658419f-7220-42f2-a9bc-4ecdea7a0cfd', 'en', 'Barbell Reverse Curl', 'Perform curls with a prone grip (palms down). This grip emphasizes the brachioradialis and the forearm extensors. Use less weight than in traditional curls and keep your wrists firm throughout the movement.'),
('7395820b-0586-48cf-b244-ad3a6e64fe09', '9658419f-7220-42f2-a9bc-4ecdea7a0cfd', 'es', 'Reverse curl barra', 'Realiza curls con agarre prono (palmas hacia abajo). Este agarre enfatiza el trabajo del braquiorradial y los extensores del antebrazo. Usa menos peso que en el curl tradicional y mantén las muñecas firmes durante todo el movimiento.'),
('7d276863-482b-4658-8c60-b66e3c6ca945', '965b6ed5-1cd0-4758-96d4-8bdacd418418', 'en', 'Barbell Staggered Stance Push Press', 'With one foot slightly forward, use an explosive leg drive to push the barbell from the shoulders to overhead.'),
('3970cb98-61c4-4333-973f-ada97f35178a', '965b6ed5-1cd0-4758-96d4-8bdacd418418', 'es', 'Press de empuje en posición escalonada con barra', 'Con un pie ligeramente adelantado, utiliza un impulso explosivo de piernas para empujar la barra desde los hombros hasta sobre la cabeza.'),
('93a1c042-eb66-40f4-8c8f-539cbe717e0e', '966e89d2-e321-4750-b1b0-d827348ed647', 'en', 'Bodyweight Reverse Lunge', 'Step back lowering the knee toward the floor and return to the center. Objective: leg strength and stability. Cue: front knee at 90 degrees. Common error: hitting the back knee against the floor.'),
('5680c68e-d490-4868-b020-490594ea2d0e', '966e89d2-e321-4750-b1b0-d827348ed647', 'es', 'Zancada trasera corporal', 'Da un paso atrás bajando la rodilla hacia el suelo y vuelve al centro. Objetivo: fuerza de piernas y estabilidad. Cue: rodilla delantera a 90 grados. Error común: golpear la rodilla trasera contra el suelo.'),
('0e9fd43d-097b-4f39-81e8-c68560cc3e3e', '966f7f92-74de-44b0-b47b-ae9d6ecadaa5', 'en', 'Back Ball Toss', 'Throw the ball forward by quickly rotating the body 180 degrees. Extreme rotational coordination. Cue: rotate on a central axis. Common error: unstable throw due to lack of balance.'),
('a3456982-9dd5-45f0-bc10-7d1e40a10f03', '966f7f92-74de-44b0-b47b-ae9d6ecadaa5', 'es', 'Lanzamiento balón espaldas', 'Lanza el balón hacia adelante girando el cuerpo rápidamente 180 grados. Coordinación rotacional extrema. Cue: gira sobre un eje central. Error común: lanzamiento inestable por falta de equilibrio.'),
('da02f06c-cf21-4db1-ac8f-1c6a205bb8fd', '96779fa3-fc27-42a8-8a6e-0076f6b8e048', 'en', 'Slider Eccentric Hamstring Curl', 'In a glute bridge position, slowly slide your heels forward on the sliders, controlling the descent until legs are straight.'),
('6d4fdf9d-837a-44f9-9e2c-30008c006db1', '96779fa3-fc27-42a8-8a6e-0076f6b8e048', 'es', 'Curl excéntrico de isquiotibiales con Slider', 'En posicion de puente de gluteo, desliza los talones lentamente hacia adelante sobre los sliders controlando el descenso hasta estirar las piernas.'),
('03bda3b8-5347-4971-9b5e-15e3b16182d7', '967927e1-35da-4b8f-8e2b-b8f4be2eb9a0', 'en', 'Battle Ropes Spirals', 'Perform circular movements with both ropes, inward or outward. Works shoulders from different angles. Keep circles wide and controlled. The core must remain stable.'),
('734713df-08ca-4310-a071-0b304f9a109d', '967927e1-35da-4b8f-8e2b-b8f4be2eb9a0', 'es', 'Battle ropes spirals', 'Realiza movimientos circulares con ambas cuerdas, hacia adentro o hacia afuera. Trabaja los hombros desde diferentes ángulos. Mantén los círculos amplios y controlados. El core debe mantenerse estable.'),
('a7ca3639-316c-4482-96d0-dd944c2610b8', '96858e3a-4495-4398-9a28-bfcc380fbc91', 'en', 'Cable Hip Rotation', 'Standing sideways to the pulley. With the outer leg straight, perform a sweeping circular or rotational movement crossing the body.'),
('6cadae30-9eee-4ec0-b5fd-4ce479bc9f2d', '96858e3a-4495-4398-9a28-bfcc380fbc91', 'es', 'Rotación de cadera con cable', 'De pie de lado a la polea. Con la pierna exterior estirada, realiza un movimiento de barrido circular o rotacional cruzando el cuerpo.'),
('1611c752-0441-4214-a7e2-9a1451cfabcf', '969c8f3e-3ce6-43bd-ab22-4099ae4514be', 'en', 'Ring Circle Front Lever', 'Maintain the Front Lever position and perform controlled circular movements with the body to challenge core and lat stability.'),
('52baa34e-1c30-483c-a8fb-efc7ea5a1abc', '969c8f3e-3ce6-43bd-ab22-4099ae4514be', 'es', 'Front Lever circular en anillas', 'Manten la posicion de Front Lever y realiza movimientos circulares controlados con el cuerpo para desafiar la estabilidad del core y dorsales.'),
('8f5c9d2d-c4c5-4904-81f2-e876bc07a4a9', '96a63078-7500-491b-9cf5-53be6cd1be2d', 'en', 'Bear crawl', 'Crawling on all fours with knees close to the ground. Total stability. Active core. Do not lift hips too much.'),
('0ab5df12-fa24-4e07-83ee-bdadbc2c022b', '96a63078-7500-491b-9cf5-53be6cd1be2d', 'es', 'Caminata de oso', 'Desplazamiento a cuatro patas con rodillas cerca del suelo. Estabilidad total. Core activo. No levantes mucho la cadera.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('19c2ea73-63c8-48c0-b911-8548ed5f1e68', '96d09d0e-e5a3-4a00-a851-e8c8d3d5d663', 'en', 'Neutral Grip Lat Pulldown', 'Perform a neutral grip lat pulldown. Pull the handle toward the upper chest while keeping the torso stable and controlling the return.'),
('56abb2c4-e69c-47fa-960f-34526c11e33c', '96d09d0e-e5a3-4a00-a851-e8c8d3d5d663', 'es', 'Jalón pecho agarre neutro', 'Realiza un jalón al pecho con agarre neutro. Lleva el agarre hacia la parte alta del pecho manteniendo el torso estable y controlando la subida.'),
('bed727fb-d066-4cb7-9ed5-eedcf5797ced', '973ddb94-aa99-4ffe-83bc-a65031b765d4', 'en', 'Forward and Back Pogo Jump', 'Short fast jumps crossing a line forward and back. Objective: foot speed. Cue: look forward, not at the ground. Common error: landing on the heel with each jump.'),
('40926e6e-3cfe-467d-9612-cd52f1b3d741', '973ddb94-aa99-4ffe-83bc-a65031b765d4', 'es', 'Salto pogo adelante y atrás', 'Saltos cortos rápidos cruzando una línea adelante y atrás. Objetivo: rapidez de pies. Cue: mirada al frente, no al suelo. Error común: apoyar el talón en cada salto.'),
('c820f648-23b8-4340-98b4-4a164122e084', '9748ff89-4439-4a75-8a3e-812ac4aed475', 'en', 'Kneeling Cable Pull Through', 'Kneeling with back to the pulley, hold the rope between your legs. Flex the hips and then extend forcefully squeezing the glutes.'),
('44326d53-1fb1-45f3-9a89-cb8d1d97e872', '9748ff89-4439-4a75-8a3e-812ac4aed475', 'es', 'Cable Pull Through arrodillado', 'Arrodillado de espaldas a la polea, sujeta la cuerda entre las piernas. Flexiona la cadera y luego extiende con fuerza apretando los gluteos.'),
('c40bf3df-7a51-485e-b4ec-d0c46966e3d8', '974aea91-b2cb-4742-aac1-ca6e9ad96aaa', 'en', 'Cable Shrugs', 'With low pulley or lateral cables, perform shoulder shrugs. Cable allows different resistance angles compared to dumbbells or barbell. Maintain top contraction and avoid rotating shoulders. Develops upper trapezius.'),
('cb710f5e-5916-4567-9416-1c72d0e81d75', '974aea91-b2cb-4742-aac1-ca6e9ad96aaa', 'es', 'Shrugs cable', 'Con polea baja o cables laterales, realiza elevaciones de hombros. El cable permite diferentes ángulos de resistencia comparado con mancuernas o barra. Mantén la contracción superior y evita rotar los hombros. Desarrolla los trapecios superiores.'),
('fee9d61d-63f5-4702-af3a-78a98d46a562', '97534af0-5725-42f6-b565-463ed7b34feb', 'en', 'Low Pulley Rope Row', 'Seated, pull the rope toward the abdomen opening the ends at the final point. Objective: upper back and retractors. Cues: chest out and retract scapulae. Common error: performing jerks with the lumbar zone.'),
('606e96c0-cd26-44bd-a9fd-ecef8051377b', '97534af0-5725-42f6-b565-463ed7b34feb', 'es', 'Remo en polea baja con cuerda', 'Sentado, tira de la cuerda hacia el abdomen abriendo los extremos al final. Objetivo: espalda alta y retractores. Cues: saca pecho y retrae escápulas. Error común: realizar tirones con la zona lumbar.'),
('fe60762f-82aa-4e3a-af22-63e2463d564a', '97aed981-75e7-424d-b29e-fc6a9aaa99e6', 'es', 'Prensa piernas', 'Sentado o tumbado en la máquina, empuja la plataforma extendiendo las piernas. No bloquees completamente las rodillas en la extensión. La posición de los pies determina el énfasis muscular: más alto para glúteos, más bajo para cuádriceps.'),
('099d96ba-81d8-4ded-91c4-7a4694473444', '97bb6d1c-1dff-4790-9598-099d3a7a286b', 'en', 'Depth Jump', 'Drop from a height and immediately perform a maximum vertical jump upon landing. Trains the stretch-shortening cycle. Advanced plyometric method. Start with low heights (30-40cm) and progress carefully.'),
('9e20f8c7-17cf-4470-9a6c-38515de60ccd', '97bb6d1c-1dff-4790-9598-099d3a7a286b', 'es', 'Salto en profundidad', 'Déjate caer desde una altura y al aterrizar realiza inmediatamente un salto vertical máximo. Entrena el ciclo estiramiento-acortamiento. Método pliométrico avanzado. Comienza con alturas bajas (30-40cm) y progresa cuidadosamente.'),
('e7029233-2c81-4b03-b2a2-6ef5b8b43c07', '97d51b34-c363-4e55-b7e0-b379b10458db', 'en', 'Dumbbell Spider Curl', 'Chest supported on incline bench looking down, let arms hang and flex the weights. Objective: extreme bicep isolation. Cues: elbows perpendicular to floor. Common error: swinging dumbbells to gain inertia.'),
('2a8ea013-304d-4c2c-87c5-830dfdae745d', '97d51b34-c363-4e55-b7e0-b379b10458db', 'es', 'Spider Curl con mancuernas', 'Pecho apoyado en banco inclinado mirando hacia abajo, deja colgar los brazos y flexiona las pesas. Objetivo: aislamiento extremo del bíceps. Cues: codos perpendiculares al suelo. Error común: balancear las mancuernas para ganar inercia.'),
('08a14c55-203e-486f-aeda-4ccd46ea6f2d', '97f16f44-fda0-4df6-b180-41af4f5e1e68', 'en', 'Battle Ropes Russian Twists', 'Seated with the ropes, perform Russian twists moving the ropes from side to side. The weight and inertia of the ropes significantly increase difficulty. Keep feet elevated for higher intensity.'),
('373f6af2-faca-43bd-b4e2-762ff8d28cca', '97f16f44-fda0-4df6-b180-41af4f5e1e68', 'es', 'Giros rusos battle ropes', 'Sentado con las cuerdas, realiza giros rusos moviendo las cuerdas de lado a lado. El peso y la inercia de las cuerdas aumentan significativamente la dificultad. Mantén los pies elevados para mayor intensidad.'),
('fc4720ee-49d3-4773-bc02-415bf90b258a', '97ff3b1e-2c90-44ad-8bac-eb400fc217b0', 'en', 'Saw Dumbbell Row', 'Row with a slight pendular swing. Objective: lower lat. Cue: fully stretch at the bottom. Error: rotating trunk.'),
('27e69053-83e5-4649-a080-e5175af7ac30', '97ff3b1e-2c90-44ad-8bac-eb400fc217b0', 'es', 'Remo mancuerna sierra', 'Remo con ligero balanceo pendular. Objetivo: dorsal inferior. Cue: estira total abajo. Error: rotar tronco.'),
('85944205-e5de-489a-be97-5bab3566ffef', '9806d84d-ea57-4660-aee3-228cb3164e09', 'en', 'Fitball Back Extension', 'Lying face down on the Fitball with pelvis supported, perform back extensions. Allows for a natural and safe range of motion. Avoid hyperextending. You can cross arms over chest or extend them for greater difficulty.'),
('d543dd54-1f1d-4f5c-b41d-5a6e90866ae0', '9806d84d-ea57-4660-aee3-228cb3164e09', 'es', 'Extensión de espalda fitball', 'Tumbado boca abajo sobre la fitball con la pelvis apoyada, realiza extensiones de espalda. Permite un rango de movimiento natural y seguro. Evita hiperextender. Puedes cruzar los brazos sobre el pecho o extenderlos para mayor dificultad.'),
('da504491-eea1-4357-ab52-93db2f9d58d4', '9890e657-a04a-4590-ae7a-59ca73768efc', 'en', 'Parallette Dive Bomber Push Up', 'From an inverted V position on parallettes, lower the chest in a forward arc and push up by extending the arms, mimicking a bomber flight.'),
('987c1c34-d00a-4e42-9bdb-db34ad8c9525', '9890e657-a04a-4590-ae7a-59ca73768efc', 'es', 'Push Up Parallette Dive Bomber', 'Desde posicion de V invertida en paralelas, baja el pecho en arco hacia adelante y sube extendiendo los brazos, imitando el vuelo de un bombardero.'),
('e0297288-b564-4c35-83c1-9c4043e4f7a5', '98df1db4-63a0-4f78-8a65-8c136b32353a', 'en', 'Single Arm Suspension Push Up', 'Hold a single TRX strap and lean forward to perform a one-arm push-up, challenging total core stability.'),
('701d7ce8-1e35-465e-8471-0efb6f9f0be5', '98df1db4-63a0-4f78-8a65-8c136b32353a', 'es', 'Flexiones con TRX de un solo brazo', 'Sujeta una sola correa de TRX e inclina el cuerpo para realizar una flexion con un solo brazo, desafiando la estabilidad total del core.'),
('3128e496-3c44-4859-a02e-2473b6e35d94', '98f4e7b1-8b36-42ce-a964-53106c90accd', 'en', 'Cross-foot Pogo Jump', 'Fast pogo jumps crossing one foot in front of the other alternately. Cue: foot agility. Common error: tripping due to lack of coordination.'),
('d78b1a0d-d945-4dd8-84ec-f0092a201899', '98f4e7b1-8b36-42ce-a964-53106c90accd', 'es', 'Salto pogo con pies cruzados', 'Saltos pogo rápidos cruzando un pie por delante del otro alternadamente. Cue: agilidad de pies. Error común: tropiezos por falta de coordinación.'),
('0ea4eeef-3e72-4d79-af95-e289203e36c4', '99446b69-b554-4f05-8ed6-594e8e8e2248', 'en', 'Weighted Pull-ups', 'Pull-ups with additional weight using a belt, vest, or dumbbell between feet. Allows for progressive overload when body weight is not enough. Maintain strict technique. Progress gradually with added weight.'),
('06298981-f279-4423-8736-3da347210be1', '99446b69-b554-4f05-8ed6-594e8e8e2248', 'es', 'Dominadas con peso', 'Dominadas con peso adicional usando cinturón, chaleco o mancuerna entre pies. Permite sobrecarga progresiva cuando el peso corporal no es suficiente. Mantén técnica estricta. Progresa gradualmente con el peso añadido.'),
('be00f30d-f1d3-4139-b5e5-f439e13eb93c', '9948fd28-6cb9-422a-9032-79e57c0edd5a', 'en', 'Explosive Step Up with Knee Drive', 'Step explosively onto a bench and drive the opposite knee high at the end. Unilateral power. Cue: push with the heel of the supported foot. Common error: driving with the back leg.'),
('28b3b253-beac-4728-9814-78837b09ccf0', '9948fd28-6cb9-422a-9032-79e57c0edd5a', 'es', 'Step up explosivo con rodilla', 'Sube explosivamente a un banco y eleva la rodilla contraria alto al final. Potencia unilateral. Cue: empuja con el talón del pie apoyado. Error común: impulsarse con la pierna de atrás.'),
('fbcc96fc-df12-42da-9b18-8c8a4d97aacb', '9960e4d4-06e5-4cc0-98b9-540d176a1479', 'es', 'Puente de glúteo con abducción y Miniband', 'Realiza un puente de glúteo con una banda sobre las rodillas. En la posición alta, separa las rodillas (abducción), ciérralas y luego baja la cadera.'),
('f11ba13d-1efc-4e72-a5a4-c7f676d71b14', '998bef50-7f2c-43c9-b473-bd684ead792f', 'en', 'Kipping Pull-ups', 'Pull-ups using body momentum (swing) to complete more repetitions. Popular in CrossFit. Allows for higher volume but with less muscle tension per rep. Requires specific technique to avoid injury. Does not replace strict pull-ups.'),
('eb2bb202-bcdc-4255-84e1-50dad756177f', '998bef50-7f2c-43c9-b473-bd684ead792f', 'es', 'Dominadas kipping', 'Dominadas usando impulso del cuerpo (balanceo) para completar más repeticiones. Popular en CrossFit. Permite mayor volumen pero con menos tensión muscular por repetición. Requiere técnica específica para evitar lesiones. No sustituye dominadas estrictas.'),
('3c964fd2-345d-47f6-8725-00d54cb020fa', '99cd6755-ce51-4f9c-973a-9eeb2af70831', 'en', 'Speed Squat', 'Squats with 50-60% of max focusing on explosive speed. Westside method. Develops power and speed. 8-12 sets of 2-3 reps with short rests. Maintain maximum acceleration throughout the movement.'),
('8552a951-5e0a-492a-b9c3-922c28cb81c2', '99cd6755-ce51-4f9c-973a-9eeb2af70831', 'es', 'Sentadilla velocidad', 'Sentadillas con 50-60% del máximo enfocándose en velocidad explosiva. Método Westside. Desarrolla potencia y velocidad. 8-12 series de 2-3 reps con descansos cortos. Mantén aceleración máxima en todo el movimiento.'),
('e4921cbe-e119-49bb-88b4-fb46d3cfdc89', '99d43b23-5a0f-4ad1-8446-98d45c15d076', 'en', 'Double Kettlebell Cossack Squat Thruster', 'Perform a deep lateral Cossack squat with kettlebells in rack and press them overhead upon returning to the center position.'),
('ce59bc36-754b-4b28-8389-1dd66d8f239e', '99d43b23-5a0f-4ad1-8446-98d45c15d076', 'es', 'Thruster Cosaco con Kettlebell doble', 'Realiza una sentadilla cosaca lateral profunda con Kettlebells en rack y presionalas sobre la cabeza al volver a la posicion central.'),
('f24d55e8-af02-4af9-af96-edbbbd9c1ec4', '99db6791-8329-444f-9df8-d279b70f9536', 'en', 'Standing Single Leg Cable Hamstring Curl', 'Standing facing the pulley, flex one leg backward bringing the heel to the glute against the cable''s resistance.'),
('553f7995-9fb6-424f-b6dd-6ab3584d7707', '99db6791-8329-444f-9df8-d279b70f9536', 'es', 'Curl de isquiotibiales de pie a una pierna con cable', 'De pie frente a la polea, flexiona una pierna hacia atrás llevando el talón al glúteo contra la resistencia del cable.'),
('caa8716c-0560-4255-8619-2f1c095646fb', '99f2b634-aff6-4b37-b666-3f6a158e1cff', 'en', 'Alternating Double Kettlebell Sots Press', 'From the deep squat, alternate the arm pressing the kettlebells overhead while keeping the torso vertical.'),
('560815d5-4dcc-4c65-99e5-1888291aeab8', '99f2b634-aff6-4b37-b666-3f6a158e1cff', 'es', 'Press Sots alternado con doble pesa rusa', 'Desde la sentadilla profunda, alterna el brazo que presiona las Kettlebells sobre la cabeza manteniendo el tronco vertical.'),
('e8697874-98b8-4a18-b263-fc53acfc4d64', '99fea4c6-0f40-4fd8-92e1-aa6da5808009', 'en', 'Flat Bench Dumbbell Flyes', 'Open arms laterally with dumbbells and bring them together at the top. Objective: pectoral stretch and isolation. Cues: elbows slightly bent. Common error: lowering so much that you overstretch the shoulder.'),
('52a614d9-02d5-47ab-ac46-0c59dec0595b', '99fea4c6-0f40-4fd8-92e1-aa6da5808009', 'es', 'Aperturas con mancuernas en banco plano', 'Abre los brazos lateralmente con mancuernas y junta arriba. Objetivo: estiramiento y aislamiento pectoral. Cues: codos semiflexionados. Error común: bajar tanto que estires el hombro en exceso.'),
('394f9a56-45cb-4075-b7cf-78d6165e150a', '9a2c1874-448b-4500-88b0-ff1b96c54861', 'en', 'Dynamic Lateral Skips', 'Lateral displacement lifting knees and coordinating arms. Improves agility and hip mobility. Chest high. Do not cross feet.'),
('2d15f566-8340-412d-a2c7-b2bf02cd8831', '9a2c1874-448b-4500-88b0-ff1b96c54861', 'es', 'Skips laterales dinámicos', 'Desplazamiento lateral elevando rodillas y coordinando brazos. Mejora la agilidad y movilidad de cadera. Pecho alto. No cruces los pies.'),
('87aeda60-33ff-4220-bb05-a90cac6629c2', '9a31cb3e-7b7e-4031-96c6-1a6ea8461f2e', 'en', 'Incline Dumbbell Curl', 'Seated on a bench inclined at 45 degrees, flex the dumbbells. Objective: maximum bicep stretch. Cue: keep elbows pointing toward the floor. Common error: moving shoulders forward.'),
('0c2bb82e-e658-4c5b-bf78-3ece3b8b2481', '9a31cb3e-7b7e-4031-96c6-1a6ea8461f2e', 'es', 'Curl inclinado con mancuerna', 'Sentado en banco inclinado a 45 grados, flexiona las mancuernas. Objetivo: estiramiento máximo del bíceps. Cue: mantén los codos apuntando al suelo. Error común: mover los hombros hacia adelante.'),
('6d41c546-25d1-43b9-b5b5-3354df7901aa', '9a5f7013-2cc4-41df-8411-052042bae214', 'en', 'Block Pull', 'Perform a deadlift starting with the barbell plates on elevated blocks to reduce travel and focus on the back.'),
('6636a724-bdbf-4643-8f89-a1569068f625', '9a5f7013-2cc4-41df-8411-052042bae214', 'es', 'Peso muerto desde bloques (Block Pull)', 'Realiza un peso muerto iniciando con los discos de la barra sobre bloques elevados para reducir el recorrido y enfocar la espalda.'),
('652ef185-e9de-4b20-b9b5-c0f82b702b5e', '9a670088-4c55-4184-abb0-acffca82441b', 'en', 'Plyometric Hand Clap Push Up', 'Explosive push-up with a clap in front of the face. Requires hand speed. Cue: explosive shoulder push. Common error: neck misalignment from looking at hands.'),
('71914924-6875-4319-a91f-a54c76da8382', '9a670088-4c55-4184-abb0-acffca82441b', 'es', 'Flexión pliométrica palmada aérea', 'Flexión explosiva con palmada frente a la cara. Requiere velocidad de manos. Cue: empuje de hombros explosivo. Error común: desalineación del cuello por mirar las manos.'),
('cc706c27-c231-4e47-8a51-c6b50f26910f', '9a6f308f-3572-45cd-a444-354f8d84214d', 'en', 'Hanging Leg Elevation', 'Hanging from a bar, lift straight legs to 90 degrees or more. Cue: do not swing. Error: using momentum to lift legs.'),
('655d5794-2127-4a5a-80d4-a1c798c349d2', '9a6f308f-3572-45cd-a444-354f8d84214d', 'es', 'Elevación de piernas colgado', 'Colgado de barra, eleva piernas estiradas hasta 90 grados o más. Cue: no te balancees. Error: usar el impulso para subir las piernas.'),
('024ea1c0-5771-4085-8fa3-8cdecfa7bf27', '9ab80d37-1c2f-4809-8fbf-d8c343bd39ca', 'en', 'Kettlebell Bicep Curl', 'Flex two kettlebells. Objective: biceps. Cue: firm grip. Error: swinging.'),
('7763b42f-4377-4a3c-9743-4651c4b8f593', '9ab80d37-1c2f-4809-8fbf-d8c343bd39ca', 'es', 'Curl bíceps kettlebells', 'Flexiona dos pesas rusas. Objetivo: bíceps. Cue: agarre firme. Error: balanceo.'),
('83c259da-2ba3-4c6c-9295-3933d919b2db', '9ad935ab-7d89-4247-8da4-411da8f4b419', 'en', 'Spartan Push Ups', 'Perform an explosive push-up and switch hand positions in the air, alternating one hand forward and one hand back. Requires explosive power and coordination. Land softly and continue with the next switch. Develops upper body power and agility.'),
('ad6933de-4274-4606-a722-609176c6d8ad', '9ad935ab-7d89-4247-8da4-411da8f4b419', 'es', 'Flexiones espartanas', 'Realiza una flexión explosiva y en el aire cambia la posición de las manos, alternando entre una mano adelantada y otra atrasada. Requiere potencia explosiva y coordinación. Aterriza suavemente y continúa con el siguiente cambio. Este ejercicio desarrolla potencia y agilidad en el tren superior.'),
('305e61a4-9149-43ad-b0b3-2b997630694f', '9ade28f5-cb6a-4bf5-9113-6a13af98571b', 'en', 'Lateral walk with Miniband (Feet)', 'With the band around the feet (insteps). Keep legs apart and walk laterally, maximizing gluteus medius activation.'),
('335f6b4f-0144-469d-863b-a46517b83e16', '9ade28f5-cb6a-4bf5-9113-6a13af98571b', 'es', 'Caminata lateral con Miniband (Pies)', 'Con la banda alrededor de los pies (empeines). Mantén las piernas separadas y camina lateralmente, maximizando la activación del glúteo medio.'),
('d755a22c-394d-47c0-8796-d850f43bfbf8', '9ae5a3e0-4145-49c8-ad0d-3fb543985d73', 'en', 'Lateral Band Steps', 'Lateral displacement maintaining band tension. Gluteus medius activation. Knees out. Do not drag feet.'),
('b029fea9-eaa3-483e-8561-71943845110a', '9ae5a3e0-4145-49c8-ad0d-3fb543985d73', 'es', 'Pasos laterales con banda', 'Desplazamiento lateral manteniendo tensión en la banda. Activación de glúteo medio. Rodillas fuera. No arrastres los pies.'),
('84c57dd6-c555-4c05-973f-412005a837d8', '9af6046f-4627-4ab7-a176-5e1aae2f84fa', 'en', 'Goblet Squat', 'Hold a dumbbell or kettlebell to the chest and lower into a squat. Cue: elbows touch the inside of the knees. Error: lifting heels.'),
('cb436e80-3dae-4c69-94e7-8b7d219fcf53', '9af6046f-4627-4ab7-a176-5e1aae2f84fa', 'es', 'Sentadilla de copa (Goblet Squat)', 'Sujeta una mancuerna o pesa rusa al pecho y baja en sentadilla. Cue: codos tocan cara interna de rodillas. Error: despegar talones.'),
('f49cca61-c9de-4f5b-baab-ef9d02cb8b52', '9b417bf1-a679-4d89-9f9f-04e8b83174b7', 'en', 'Medicine ball chest press', 'Standing in front of a wall, throw the ball forcefully from the chest and receive it as it bounces. The explosive movement develops power in the pectorals. Keep the core engaged and use the entire body in the throw.'),
('0ec1bcd5-f6e3-4a40-8bbb-7a57a4152ed4', '9b417bf1-a679-4d89-9f9f-04e8b83174b7', 'es', 'Chest press balón medicinal', 'De pie frente a una pared, lanza el balón con fuerza desde el pecho y recíbelo al rebotar. El movimiento explosivo desarrolla potencia en el pectoral. Mantén el core activado y usa todo el cuerpo en el lanzamiento.'),
('4b2da166-52cf-4495-a75d-30c51d7ac906', '9b4d3dc7-7123-4377-847f-226b26cdd0ef', 'en', 'Rotational Cable Row', 'Combines rowing with full torso rotation. Highly functional movement for sports. Start sideways to the cable and end facing it. Total movement control. Power from hips and core.'),
('d28fc51a-84bf-48c2-a2a5-9b2ece12648b', '9b4d3dc7-7123-4377-847f-226b26cdd0ef', 'es', 'Remo rotacional cable', 'Combina remo con rotación completa del torso. Movimiento altamente funcional para deportes. Comienza de lado al cable y termina mirando hacia él. Control total del movimiento. Potencia desde caderas y core.'),
('eeeadfee-cbfe-40f2-a216-e3c243e0df13', '9b51a52a-c188-4fec-bbdb-5d2026b81d5f', 'en', 'Single Arm Kettlebell Front Rack Carry', 'Walk while holding a kettlebell in the rack position on one shoulder, strongly engaging the obliques to prevent the weight from tilting the torso laterally.'),
('1429b417-6b34-4efb-980c-c48ecd8c79b2', '9b51a52a-c188-4fec-bbdb-5d2026b81d5f', 'es', 'Caminata Front Rack con Kettlebell a una mano', 'Camina manteniendo una pesa rusa en posición de rack sobre un hombro, activando fuertemente los oblicuos para evitar que el peso incline el torso lateralmente.'),
('2d8f754a-320b-46be-bf17-0198d5e31831', '9b55b358-c13c-46fd-bdd4-d2b9e9c83f6f', 'en', 'Unilateral Low Pulley Row', 'Seated, row with a single arm seeking maximum stretch. Objective: isolated lat. Cue: fully stretch the lat when returning. Common error: rotating the torso excessively.'),
('837d6a55-6c93-4070-adf9-0ff7b4738b30', '9b55b358-c13c-46fd-bdd4-d2b9e9c83f6f', 'es', 'Remo unilateral en polea baja', 'Sentado, rema a un solo brazo buscando máximo estiramiento. Objetivo: dorsal aislado. Cue: estira total el dorsal al volver. Error común: rotar el torso excesivamente.'),
('c4520577-2ebc-4eec-8293-4586bc04a04a', '9b87652d-64d1-4c92-82fa-b12e60900b30', 'en', 'Star Jump Burpee', 'Perform a burpee and end the vertical jump by opening arms and legs in the air. High metabolic demand. Cue: close legs again before landing. Common error: landing with stiff legs.'),
('cb86dbf9-7477-4268-85a9-1c63c4c940fb', '9b87652d-64d1-4c92-82fa-b12e60900b30', 'es', 'Burpee con salto de estrella', 'Realiza un burpee y termina el salto vertical abriendo brazos y piernas en el aire. Alta demanda metabólica. Cue: vuelve a cerrar piernas antes de aterrizar. Error común: aterrizar con las piernas rígidas.'),
('f52e870f-f810-4234-a6fa-a755ab7104db', '9b9a528f-7374-4f51-9d67-a3c3a6034a6e', 'en', 'Reverse Crunches', 'Lying down, lift the hips off the floor bringing knees toward the chest. Objective: lower rectus abdominis. Cues: lower back flat at the start. Common error: using excessive leg swinging.'),
('166ea5cb-e482-4a41-8858-f16ef06ac21b', '9b9a528f-7374-4f51-9d67-a3c3a6034a6e', 'es', 'Crunches inversos', 'Tumbado, eleva la cadera del suelo llevando las rodillas hacia el pecho. Objetivo: recto abdominal inferior. Cues: lumbar pegada al inicio. Error común: usar excesivo balanceo de piernas.'),
('81c34570-4938-470b-9a84-c78f6f5ea5d1', '9bb808c0-e2b9-462d-8cf6-fdfcb65af36e', 'en', 'Monster Walk with Miniband (Thighs)', 'With a band above the knees, take diagonal steps forward and out, keeping the knees apart and hips low.'),
('5fe789f4-d6d0-4bda-b645-66be701e7b21', '9bb808c0-e2b9-462d-8cf6-fdfcb65af36e', 'es', 'Monster Walk con Miniband (Muslos)', 'Con una banda sobre las rodillas, da pasos hacia adelante y afuera en diagonal, manteniendo las rodillas separadas y la cadera baja.'),
('1231d634-c2a7-4da3-b2af-ab1dd2a97670', '9bbf9765-50b7-491a-85be-d733254eb9be', 'en', 'Abdominal Crunches', 'Lying down, lift only the shoulders off the floor while squeezing the abdomen. Cue: look at the ceiling, do not pull on the neck. Error: lifting the lower back off the floor.'),
('dde2ce0d-d5ce-49b3-ba02-3eea3c9a3cdc', '9bbf9765-50b7-491a-85be-d733254eb9be', 'es', 'Crunches abdominales', 'Tumbado, eleva solo los hombros del suelo apretando el abdomen. Cue: mira al techo, no tires del cuello. Error: levantar la zona lumbar del suelo.'),
('3af8ec10-c54b-496b-a57d-f890932c39e2', '9beef3cf-d8f2-4504-8e4d-5063a399d73c', 'en', 'Jump Squat', 'Perform a squat and finish with a maximum vertical jump. Objective: explosive power. Cue: land on toes to cushion. Common error: landing with stiff legs.'),
('183768f2-a64b-4ef1-8d80-4c89cbed4484', '9beef3cf-d8f2-4504-8e4d-5063a399d73c', 'es', 'Sentadilla con salto (Jump Squat)', 'Realiza una sentadilla y termina con un salto vertical máximo. Objetivo: potencia explosiva. Cue: aterriza con las puntas para amortiguar. Error común: aterrizar con las piernas rígidas.'),
('6191f733-129f-4497-89a0-ab510c1f993b', '9c010d07-c688-4339-8e00-447401b3db17', 'en', 'Long Jump with 90-Degree Turn', 'Jump forward and rotate 90 degrees in the air to land sideways. Cue: control lateral landing. Common error: losing lateral balance when landing.'),
('c6ef28c4-ee9c-427b-befd-a4ace3fec113', '9c010d07-c688-4339-8e00-447401b3db17', 'es', 'Salto longitud giro 90', 'Salta hacia adelante y gira 90 grados en el aire para aterrizar de lado. Cue: controla el aterrizaje lateral. Error común: perder el equilibrio lateral al caer.'),
('982fc917-8c10-4cfd-a5c5-37d0a1131f0c', '9c03a7fb-ff28-4159-8265-0664c7c70594', 'en', 'Single Arm Suspension Bicep Curl', 'Hold a single TRX strap and lean back. Perform the curl by flexing the elbow toward your forehead working unilateral stability.'),
('5a750ed1-6a83-4f59-9c19-bca7603ddb26', '9c03a7fb-ff28-4159-8265-0664c7c70594', 'es', 'Curl de bíceps con TRX de un solo brazo', 'Sujeta una sola correa de TRX e inclina el cuerpo. Realiza el curl flexionando el codo hacia tu frente trabajando la estabilidad unilateral.'),
('c3466d94-0f76-479e-9492-87ca004ecf97', '9c64f789-02d6-4112-9b4c-d9d0af801449', 'en', 'Wall Fitball Squat', 'Place a Fitball between your back and the wall. Perform a squat sliding the ball as you lower, keeping the torso upright.'),
('4a97f335-9d99-406f-a253-42227982fce9', '9c64f789-02d6-4112-9b4c-d9d0af801449', 'es', 'Sentadilla con Fitball en pared', 'Coloca un Fitball entre tu espalda y la pared. Realiza una sentadilla deslizando el balón mientras bajas, manteniendo el torso erguido.'),
('a6501092-7e4a-491b-a167-222e9532bf0d', '9c7949f6-7d94-4f28-9929-1da712cf41b1', 'en', 'Dumbbell Rear Delt Flyes', 'Torso tilted parallel to the floor, lift dumbbells laterally. Objective: rear deltoid and rhomboids. Cue: imagine pushing outward with the elbows. Common error: squeezing shoulder blades together too quickly, reducing shoulder work.'),
('c05447f5-f471-4872-8be2-a0c0aa778993', '9c7949f6-7d94-4f28-9929-1da712cf41b1', 'es', 'Pájaros con mancuernas', 'Torso inclinado paralelo al suelo, eleva mancuernas lateralmente. Objetivo: deltoides posterior y romboides. Cue: imagina que empujas con los codos hacia afuera. Error común: juntar las escápulas demasiado rápido restando trabajo al hombro.'),
('47a697b4-93b3-4d45-befe-5254ed68700e', '9c8949e6-c173-43d2-be00-961d01d98b6b', 'en', 'Seated Cable Row', 'Seated with your feet on the supports, pull the handle toward your abdomen while keeping your back straight. Allow a slight torso movement but avoid excessive swinging. Squeeze your shoulder blades at the end of the movement for maximum contraction.'),
('1e03a1e3-fc0a-4e30-8ba8-04e3584748b3', '9c8949e6-c173-43d2-be00-961d01d98b6b', 'es', 'Remo sentado cable', 'Sentado con los pies en los soportes, tira del agarre hacia el abdomen manteniendo la espalda recta. Permite un ligero movimiento del torso pero evita el balanceo excesivo. Aprieta los omóplatos al final del movimiento para máxima contracción.'),
('0852cf6e-59e0-4011-888b-d0a98785df42', '9c8c31a4-dab2-4622-ac6a-e6dfa8585100', 'en', 'Single Leg Calf Raises', 'On the edge of a step, rise on a single foot and descend as far as possible. Objective: calf strength. Cue: slow and controlled movement. Error: bouncing at the bottom of the movement.'),
('5dc67d6c-e19d-4feb-8424-61952e354344', '9c8c31a4-dab2-4622-ac6a-e6dfa8585100', 'es', 'Elevación de talones a una pierna', 'En el borde de un escalón, elévate sobre un solo pie y desciende lo máximo posible. Objetivo: fuerza del gemelo. Cue: movimiento lento y controlado. Error: rebotar en la parte inferior del movimiento.'),
('b6c70fe5-060c-4f3f-8ff2-0f58a55f46d3', '9cea5a00-8e09-4376-8b37-4bfd7821f399', 'en', 'Glute Bridge', 'Lie on your back with knees bent and feet flat on the floor near the glutes. Raise hips by contracting glutes until forming a straight line from knees to shoulders. Maintain the top position by squeezing glutes and descend controlled without touching the floor.'),
('1f2c7b52-b868-45eb-bf53-699c2c42a0a3', '9cea5a00-8e09-4376-8b37-4bfd7821f399', 'es', 'Glute bridge', 'Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo cerca de los glúteos. Eleva las caderas contrayendo los glúteos hasta formar una línea recta desde las rodillas hasta los hombros. Mantén la posición superior apretando los glúteos y desciende controladamente sin tocar el suelo.'),
('29eb07fd-ead1-47e2-aa0e-a3baed05515e', '9d3c31f8-4a76-4a3a-97f4-55772f51605d', 'en', 'Single Arm Rollout', 'Rollout using only one arm on the wheel. Requires exceptional anti-rotation strength. Start with very short ranges. Free arm can be on the back or extended for balance.'),
('62235bef-f81f-4575-926f-ee6543dd0345', '9d3c31f8-4a76-4a3a-97f4-55772f51605d', 'es', 'Roll out single arm', 'Roll out usando solo un brazo en la rueda. Requiere fuerza anti-rotación excepcional. Comienza con rangos muy cortos. El brazo libre puede estar en la espalda o extendido para equilibrio.'),
('a72d3cdc-e15d-4921-ad5e-bf396adb57d9', '9d474e23-bf06-4d61-8e9d-5346977ee14a', 'es', 'Plancha comando cadera quieta', 'Pasa de antebrazos a manos. Cue: cadera fija. Error: balancear cuerpo.'),
('6c79ca1d-3668-4110-8d46-b7902101c08d', '9d4e44bb-6938-4e1a-8cc4-8b744511b92d', 'en', 'Inchworms', 'From standing, lower hands to the floor and walk them out to a plank position, then walk feet toward hands. Objective: core and flexibility. Cue: keep knees as straight as possible. Error: letting hips sag in the plank.'),
('9f91eb92-eba9-40be-89bc-d48d0e50e881', '9d4e44bb-6938-4e1a-8cc4-8b744511b92d', 'es', 'Gusanos (Inchworms)', 'Desde pie, baja las manos al suelo y camina con ellas hasta posición de plancha, luego camina con los pies hacia las manos. Objetivo: core y flexibilidad. Cue: mantén las rodillas lo más rectas posible. Error: dejar caer la cadera en la plancha.'),
('467aa8e8-6710-44f9-b7ea-1c95667abfa9', '9d9a7469-5e0a-42bb-b2d8-ebaa3292fbf9', 'en', 'T-Push Up', 'Perform a push-up and when rising rotate the body to one side, lifting one arm toward the ceiling. Objective: pushing strength and balance. Cues: keep the body straight at all times. Common error: losing control of the supporting shoulder when rotating.'),
('12bf1a62-3ad4-4fd5-ae0f-ebd277de1d02', '9d9a7469-5e0a-42bb-b2d8-ebaa3292fbf9', 'es', 'Flexión en T', 'Realiza una flexión y al subir rota el cuerpo hacia un lado elevando un brazo hacia el techo. Objetivo: fuerza de empuje y equilibrio. Cues: mantén el cuerpo recto en todo momento. Error común: perder el control del hombro de apoyo al rotar.'),
('ce4a47fc-6cbd-4ee8-b847-0118f790ee61', '9dd106d2-614e-4cc2-bdf3-ba142ed1504e', 'en', 'Battle Rope Tornado', 'Continuous circular motion with both ropes creating a tornado pattern. Requires exceptional coordination and endurance. The movement must be fluid and controlled. Periodically alternate directions.'),
('16795460-5c70-4ace-8b0d-0e5a9842b118', '9dd106d2-614e-4cc2-bdf3-ba142ed1504e', 'es', 'Tornado battle ropes', 'Movimiento circular continuo con ambas cuerdas creando un patrón de tornado. Requiere coordinación y resistencia excepcionales. El movimiento debe ser fluido y controlado. Alterna direcciones periódicamente.'),
('04aa4eb2-add9-4149-80d0-0ba5233b40e9', '9e091ca5-2662-4741-b8e1-d06e20fb90e6', 'en', 'Barbell Squat Clean to Thruster', 'Bring the bar from the floor to shoulders in a full squat and use the upward momentum to perform a vertical overhead press.'),
('a6f4fc61-81e5-42c3-8765-2087a8fae072', '9e091ca5-2662-4741-b8e1-d06e20fb90e6', 'es', 'Squat Clean a Thruster con barra', 'Lleva la barra desde el suelo a los hombros en sentadilla completa y usa el impulso de la subida para realizar un press vertical sobre la cabeza.'),
('01e2a961-3885-44cc-a2f2-972995aabe42', '9e204716-a368-471f-82f5-c1d44c34a541', 'en', 'Seated Barbell Military Press', 'Push the bar overhead without leg drive. Pure strength. Core tucked. Do not arch the back at the end.'),
('84553573-7614-483d-951e-8922505b88d1', '9e204716-a368-471f-82f5-c1d44c34a541', 'es', 'Press militar con barra sentado', 'Empuja la barra sobre la cabeza sin impulso de piernas. Fuerza pura. Core apretado. No arquees la espalda al final.'),
('6fa2e6e7-2cc0-430d-8ac3-77d4f81abac6', '9e43cc32-2fa4-4bbe-8de5-0221be4bc924', 'es', 'Plank to roll out', 'Comienza en plancha con manos en la rueda y realiza pequeños rodamientos. Combina isométrico con movimiento. Mantén las caderas bajas y evita arquear la espalda. Excelente para desarrollar control.'),
('a9836188-af70-4b92-80cc-eeb92ec5d131', '9e4f9374-7729-45fc-970d-718dedbc6ca8', 'es', 'Press pecho con banda', 'Ancla la banda detrás de ti a la altura del pecho. Sujeta los extremos y realiza un movimiento de press hacia adelante, extendiendo completamente los brazos. La resistencia de la banda proporciona tensión constante, especialmente en la fase final del movimiento.'),
('18ae26b7-b8cc-484e-ba99-910451254ddf', '9e5cf242-153e-45ad-b5a9-88e17582f09a', 'en', 'Ring Push Ups', 'Push-ups with hands on low rings. Instability multiplies difficulty and muscle activation. Start with higher rings for less difficulty. Keep rings still during the movement.'),
('b7f80ab3-ebdb-489e-a693-b1af49977f56', '9e5cf242-153e-45ad-b5a9-88e17582f09a', 'es', 'Flexiones en anillas', 'Flexiones con manos en anillas bajas. La inestabilidad multiplica la dificultad y activación muscular. Comienza con anillas más altas para menor dificultad. Mantén las anillas quietas durante el movimiento.'),
('688beab7-bc2c-43fa-a209-61f2101d4876', '9e87364a-12ae-4aad-ada3-922f01b22129', 'en', 'Dumbbell Shoulder Press', 'Seated or standing, with a dumbbell in each hand at shoulder height, press upward until arms are fully extended. Keep the core engaged to stabilize the spine. Lower in a controlled manner until elbows form 90 degrees.'),
('f670f791-871e-4ca4-9805-fa9ea92590d8', '9e87364a-12ae-4aad-ada3-922f01b22129', 'es', 'Press hombros mancuernas', 'Sentado o de pie, con una mancuerna en cada mano a la altura de los hombros, presiona hacia arriba hasta extender completamente los brazos. Mantén el core activado para estabilizar la columna. Desciende controladamente hasta que los codos formen 90 grados.'),
('c6878386-1016-4267-ad04-3bceefea0556', '9e9197e5-4805-488f-a6d8-45eac66521f5', 'en', 'EZ Bar Preacher Bicep Curl', 'Support arms on preacher bench and flex EZ bar. Objective: brachialis bicep isolation. Cues: fully straighten arm at the bottom. Common error: lifting elbows from the support.'),
('61b91a05-ccc8-45f2-a002-8f577e4d7459', '9e9197e5-4805-488f-a6d8-45eac66521f5', 'es', 'Curl de bíceps predicador con barra Z', 'Apoya los brazos en el banco predicador y flexiona la barra Z. Objetivo: aislamiento del bíceps braquial. Cues: estira el brazo totalmente abajo. Error común: levantar los codos del soporte.'),
('93d992f9-ebb9-4403-aa07-352806610ef2', '9eb370e1-e734-4d95-aaf4-39a909f29ff8', 'en', 'Leg Press Toe Calf Raise', 'Push the platform only with the toes. Cue: full range. Error: locked knees.'),
('0345c068-327b-43d2-83b8-7737e4e9a934', '9eb370e1-e734-4d95-aaf4-39a909f29ff8', 'es', 'Elevación talones prensa puntas', 'Empuja plataforma solo con puntas. Cue: rango total. Error: rodillas bloqueadas.'),
('f05f01b7-ea36-4ab4-8586-ccd686839ff1', '9eb8d5be-f445-4a71-ac12-636bc0766c6d', 'en', 'Lateral Pogo Jump', 'Jump side to side quickly over an imaginary line. Keep ankles rigid and ground contact time to a minimum. Objective: ankle reactivity. Cue: bounce on the balls of feet, do not support heels. Common error: flexing knees too much.'),
('c9ef2882-9b20-4a9a-a34a-3f2d4a5026db', '9eb8d5be-f445-4a71-ac12-636bc0766c6d', 'es', 'Salto pogo lateral', 'Salta de lado a lado rápidamente sobre una línea imaginaria. Mantén los tobillos rígidos y el tiempo de contacto con el suelo al mínimo. Objetivo: reactividad del tobillo. Cue: rebota sobre las puntas, no apoyes talones. Error común: flexionar demasiado las rodillas.'),
('bb8681c8-fcdf-4ae0-a668-41b5350be8cd', '9eba3286-c1c2-4058-83f2-bbce205f702f', 'en', 'Incline Dumbbell Flyes', 'On a 45-degree bench, open arms laterally with dumbbells and close at the center. Objective: upper pectoral isolation. Cue: imagine you are hugging a giant cylinder. Common error: lowering the weights excessively, overstretching the shoulder.'),
('720aa4cf-af4b-460f-b3f3-c1b1ab0040b1', '9eba3286-c1c2-4058-83f2-bbce205f702f', 'es', 'Aperturas en banco inclinado con mancuernas', 'En banco a 45 grados, abre los brazos lateralmente con mancuernas y cierra al centro. Objetivo: aislamiento del pectoral superior. Cue: imagina que abrazas un cilindro gigante. Error común: bajar las pesas excesivamente estirando de más el hombro.'),
('7d57e575-48e1-40b5-9184-62943295c6e2', '9ecf5c23-1770-4000-9cac-ba45dff35de8', 'en', 'Fitball Hamstring Curl', 'Lying with heels on the fitball, lift hips and flex knees rolling the ball toward the glutes. Keep hips elevated throughout the movement. The instability significantly increases the difficulty.'),
('b48295ba-b523-4090-af8e-739c76f3baf5', '9ecf5c23-1770-4000-9cac-ba45dff35de8', 'es', 'Curl isquios fitball', 'Tumbado con talones sobre la fitball, eleva las caderas y flexiona las rodillas rodando la pelota hacia los glúteos. Mantén las caderas elevadas durante todo el movimiento. La inestabilidad aumenta significativamente la dificultad.'),
('f8034ade-6471-4b75-9a7b-9697f07725dd', '9efa252e-ae26-4b61-bc36-7485f5af2a8a', 'en', 'Double Dumbbell Renegade Row', 'From a plank position on dumbbells, row one weight to your hip while stabilizing the body with the other arm and core, alternating sides.'),
('62d827b2-d042-4a84-8392-0d23f4dd6812', '9efa252e-ae26-4b61-bc36-7485f5af2a8a', 'es', 'Remo renegado doble con mancuernas', 'Desde posicion de plancha sobre mancuernas, rema una pesa hacia tu cadera mientras estabilizas el cuerpo con el otro brazo y el core, alternando lados.'),
('e2225f4f-c225-490f-8fd4-4addece4fadd', '9f2369ba-7e5c-4f8a-ad1d-59eb3cde8b45', 'en', 'Double Bottoms Up Cyclist Squat with Kettlebell (Front Rack)', 'Perform a cyclist squat with heels elevated holding two inverted kettlebells in front rack position.'),
('7f930735-d443-4693-a61f-9b4c4dd86334', '9f2369ba-7e5c-4f8a-ad1d-59eb3cde8b45', 'es', 'Sentadilla Ciclista con Kettlebell doble Bottoms Up (Front Rack)', 'Realiza una sentadilla ciclista con los talones elevados sujetando dos Kettlebells invertidas en posicion de rack frontal.'),
('bdcc4c6d-bd6b-4b36-a374-9213818987e6', '9f32f085-3dc5-4593-a04c-fd2f91c849d4', 'en', 'One-Arm Bar Passive Hang', 'Hang from a fixed bar using only one hand. Maintain position to develop extreme grip strength and scapular health.'),
('82b8495c-a449-43cd-9851-4ba3a77d2a1d', '9f32f085-3dc5-4593-a04c-fd2f91c849d4', 'es', 'Colgado pasivo a una mano en barra', 'Cuélgate de una barra fija usando solo una mano. Mantén la posición para desarrollar fuerza de agarre extrema y salud escapular.'),
('dd19a675-6ada-4a6a-a7e2-ecec5b1d65b1', '9f403e30-eaea-4104-ba78-fc992d42955c', 'en', 'Seated Hamstring Curl', 'Seated with legs extended, flex knees against resistance. This position provides a different hamstring stretch compared to the lying version. Keep the back supported throughout the movement.'),
('7141ae01-781c-4da4-a1b2-d3739c6590f4', '9f403e30-eaea-4104-ba78-fc992d42955c', 'es', 'Curl femoral sentado', 'Sentado con las piernas extendidas, flexiona las rodillas contra la resistencia. Esta posición proporciona un estiramiento diferente del isquiotibial comparado con la versión tumbada. Mantén la espalda apoyada durante todo el movimiento.'),
('36785be1-a6e2-47d3-bb1d-7b3ac1180aff', '9f515786-ab34-4604-94c8-8254d0b49e68', 'en', 'Double Kettlebell Suitcase Step Up', 'Step up onto a bench while holding two kettlebells at your sides, driving through the front leg to full extension.'),
('b472f86f-c134-4cb8-9773-537c190d9c24', '9f515786-ab34-4604-94c8-8254d0b49e68', 'es', 'Step Up con Kettlebell doble (Maleta)', 'Sube a un banco sosteniendo dos Kettlebells a los lados del cuerpo, empujando con la pierna delantera hasta la extensión completa.'),
('9903c57a-bae7-4110-9953-3b9055888636', '9f85734e-3932-46f4-af46-9855f2b2baf6', 'en', 'Hamstring Sliders', 'Lie on your back with your heels on a sliding surface, lift the hips, and extend the legs under control. Bend the knees to return while engaging the hamstrings.'),
('c5d2642e-9669-4c9f-a800-474ab611f17e', '9f85734e-3932-46f4-af46-9855f2b2baf6', 'es', 'Hamstring sliders', 'Tumbado boca arriba con los talones sobre una superficie deslizante, eleva la cadera y extiende las piernas de forma controlada. Flexiona las rodillas para volver activando los isquiotibiales.'),
('1ad44674-c607-44d0-b021-2becacb8e768', '9fcd1862-d321-4ef4-b395-e65941199062', 'en', 'Strict Prone Grip Pull-ups', 'Pull up until the chin clears the bar with palms facing forward. Cue: chest to the bar. Error: using momentum.'),
('616077bd-d297-4f32-8ec3-9f5b645edba5', '9fcd1862-d321-4ef4-b395-e65941199062', 'es', 'Dominadas agarre prono estricto', 'Sube hasta pasar la barbilla con palmas al frente. Cue: pecho a la barra. Error: usar balanceo.'),
('60b143cb-9fdc-446f-915a-5ec942df0492', '9fe3e1b5-9a2c-4c2f-a618-585df5d36218', 'en', 'Lateral Broad Jumps', 'Jump laterally seeking maximum possible distance. Power in the frontal plane. Stable landing. Do not let the knee cave in.'),
('0063f1c6-0a14-4d7b-9bc0-51f2851b17cf', '9fe3e1b5-9a2c-4c2f-a618-585df5d36218', 'es', 'Saltos de amplitud lateral', 'Salta lateralmente buscando la máxima distancia posible. Potencia en el plano frontal. Aterrizaje estable. No dejes que la rodilla se hunda.'),
('f34a5c66-7b9e-44b8-8897-136bd1e28661', '9fffabe0-920f-4315-9f64-a586616ca367', 'es', 'Peso muerto rígido barra', 'Baja barra rodillas casi bloqueadas. Objetivo: estirar isquios. Cue: cadera atrás. Error: curvar lumbar.'),
('e77a5a5b-26d7-4105-9f8e-a737257b8b33', 'a0411742-b6dd-4edc-b98b-09cdc9d4f22e', 'en', 'Dumbbell Skater Jump', 'Skater jump while holding a light dumbbell at the chest. Weighted power. Cue: control weight inertia. Common error: swinging the dumbbell away from the chest.'),
('88ed8aa3-7e49-45aa-aa9f-6818b21944cb', 'a0411742-b6dd-4edc-b98b-09cdc9d4f22e', 'es', 'Salto patinador con mancuerna', 'Salto de patinador sosteniendo una mancuerna ligera en el pecho. Potencia lastrada. Cue: controla la inercia del peso. Error común: balancear la mancuerna lejos del pecho.'),
('615e4485-22f9-460d-bdab-d115372ab1f1', 'a044db64-26e5-4ed1-879e-c5abeff7e893', 'en', 'Barbell Split Squat', 'Keep feet in a lunge position and lower the back knee toward the floor with the bar on the shoulders. Objective: unilateral hypertrophy. Cues: lower vertically and maintain a neutral back. Common error: leaning the torso too far forward.'),
('4eb7941d-c5d5-437c-bd34-3e42aca9afab', 'a044db64-26e5-4ed1-879e-c5abeff7e893', 'es', 'Sentadilla Split con barra', 'Mantén los pies en posición de zancada y baja la rodilla trasera hacia el suelo con la barra en hombros. Objetivo: hipertrofia unilateral. Cues: baja de forma vertical y mantén la espalda neutra. Error común: inclinar el torso demasiado adelante.'),
('d0500dd2-f0dc-418e-b52a-63b18ae2b626', 'a04b552e-902b-48c3-8357-2cffdd4b9024', 'en', 'Single Arm Kettlebell Half Kneeling Swing', 'From a half-kneeling position, perform a short lateral swing, forcing the core to stabilize the trunk without the help of standing up.'),
('d81cdbd3-55b9-4664-86e9-99a0c036265a', 'a04b552e-902b-48c3-8357-2cffdd4b9024', 'es', 'Swing medio arrodillado con Kettlebell a una mano', 'Desde posicion de caballero, realiza un swing lateral corto, forzando al core a estabilizar el tronco sin la ayuda de la bipedestacion.'),
('e7996922-c89d-490e-95c1-8f47a2fcd368', 'a0b62d9f-107c-468c-99e6-c296a971f8c6', 'en', 'Kettlebell Flow', 'Continuous sequence of movements without pauses: swing, clean, press, squat, etc. Create your own flow or follow established sequences. Excellent metabolic conditioning. Technique must not be compromised by fatigue.'),
('9f8efba8-8e20-4640-aa40-4d8ad27d1452', 'a0b62d9f-107c-468c-99e6-c296a971f8c6', 'es', 'Flujo kettlebell', 'Secuencia continua de movimientos sin pausas: swing, clean, press, squat, etc. Crea tu propio flujo o sigue secuencias establecidas. Excelente acondicionamiento metabólico. La técnica no debe comprometerse por la fatiga.'),
('0cb005b9-7049-403d-bf9c-92b79666f114', 'a0b7f536-49fa-4d21-b6e9-7aa4c8cb1dcd', 'en', 'Bulgarian Split Squat Jump', 'With one foot elevated behind, perform a split squat and jump explosively with the front leg.'),
('d66bbc4d-2336-4253-8d6e-e6d7c73ee272', 'a0b7f536-49fa-4d21-b6e9-7aa4c8cb1dcd', 'es', 'Salto en Sentadilla Split Búlgara', 'Con un pie elevado atrás, realiza una sentadilla split y salta de forma explosiva con la pierna delantera.'),
('adac1998-4bcd-453c-8e27-c7c36c2abd4e', 'a109bae6-f172-44e5-be4a-c20ddb5c3e13', 'en', 'Upright Barbell Row', 'Raise the bar close to the torso to chest height, bringing the elbows above the wrists. Objective: lateral deltoid and trapezius. Cue: do not jerk with your back. Common error: raising the bar too close to the neck abruptly.'),
('6ce38f18-dd06-4ecd-b938-6e54c6d19b21', 'a109bae6-f172-44e5-be4a-c20ddb5c3e13', 'es', 'Remo vertical con barra', 'Eleva la barra pegada al torso hasta la altura del pecho subiendo los codos por encima de las muñecas. Objetivo: deltoides lateral y trapecio. Cue: no des tirones con la espalda. Error común: subir la barra demasiado cerca del cuello de forma brusca.'),
('02fc3ab7-d1ca-401a-80f6-fdc0c8027435', 'a1167d6c-7b40-437a-ab05-617fc75dc7df', 'en', 'Triceps Bench Dips', 'Hands on one bench and feet on another, lower and rise. Triceps power. High chest. Do not lower beyond a right angle.'),
('68fcf708-9699-4799-9bf8-2429bd775947', 'a1167d6c-7b40-437a-ab05-617fc75dc7df', 'es', 'Fondos entre bancos tríceps', 'Manos en un banco y pies en otro, baja y sube. Potencia de tríceps. Pecho alto. No bajes más allá del ángulo recto.'),
('3c933938-0f0f-4030-8eeb-a25dae1e0a8c', 'a1ad8b55-236f-439b-a08e-83d47fa2df48', 'en', 'Single Arm Alternating Devil Press', 'Perform a Burpee with one hand on a dumbbell. Upon standing, lift that dumbbell overhead and switch hands on the next rep.'),
('6d3f521f-3cc2-4dcf-8288-b7194d0d0fcc', 'a1ad8b55-236f-439b-a08e-83d47fa2df48', 'es', 'Devil Press alterno a una mano con mancuerna', 'Realiza un Burpee con una mano en una mancuerna. Al levantarte, eleva esa mancuerna sobre la cabeza y cambia de mano en la siguiente repetición.'),
('c54d96c2-b2ac-4e4a-b35b-ec1f3313bd56', 'a1aed24e-0cd5-4c5c-9128-d8e1b0c8400f', 'en', 'Bodyweight Glute Bridge', 'Lie on your back with knees bent and feet flat on the floor. Lift your hips toward the ceiling by squeezing your glutes until your body forms a straight line from shoulders to knees. Lower slowly.'),
('c9027b9b-df6e-4bca-851b-10a7fbc6623a', 'a1aed24e-0cd5-4c5c-9128-d8e1b0c8400f', 'es', 'Puente de Glúteo', 'Acuéstate boca arriba con las rodillas dobladas y los pies planos en el suelo. Levanta las caderas hacia el techo apretando los glúteos hasta que el cuerpo forme una línea recta desde los hombros hasta las rodillas. Baja lentamente.'),
('a32c841e-a4ee-4e9d-9b71-22242e9f916e', 'a1b24c36-0b71-4911-ac6a-8ae2ae313501', 'en', 'Hurdle Jump with Double Bounce', 'Jump a hurdle and perform a small quick bounce before the next jump. Improves timing. Cue: elastic bounce. Common error: bouncing too high, draining energy.'),
('1e6247b3-80ca-4721-aed3-d4e348ee6cf4', 'a1b24c36-0b71-4911-ac6a-8ae2ae313501', 'es', 'Salto valla rebote doble', 'Salta una valla y realiza un pequeño rebote rápido antes del siguiente salto. Mejora el timing. Cue: rebote elástico. Error común: rebote demasiado alto que quita energía.'),
('a5cd7267-7616-4e9d-9587-e1e1c06d19e3', 'a1dcdd52-62d4-45a1-b6ff-c64c309c8607', 'es', 'Pike Pushups elevados', 'Pies en banco en posición de V invertida, baja la frente hacia el suelo. Objetivo: fuerza de hombros. Cue: codos hacia atrás en diagonal. Error común: abrir los codos hacia afuera lateralmente.'),
('2886fa79-3b25-4b99-9a6b-f4ea51d757ea', 'a1effa06-508a-4002-9960-a4d3c75a5d28', 'en', 'Incline Barbell Bench Press', 'On an incline bench (30-45 degrees), lower the bar to the upper chest and push upward to work the upper pectoral.'),
('86158ede-5978-40a1-b861-a11a06fe345f', 'a1effa06-508a-4002-9960-a4d3c75a5d28', 'es', 'Press de banca inclinado con barra', 'En un banco inclinado (30-45 grados), baja la barra a la parte superior del pecho y empuja hacia arriba para trabajar el pectoral superior.'),
('150dac9a-f73d-4f43-b929-d1fb930b98ad', 'a225fd6f-7478-4cbf-a45f-4e66863f2c04', 'en', 'Single Arm Cable Half Kneeling Contralateral Shoulder External Rotation 90 Degrees', 'Kneel sideways to the pulley. With the outer arm raised to 90 degrees, rotate the shoulder backward pulling the cable, keeping the elbow aligned with the shoulder.'),
('da0db1a9-e2d8-42a2-a58a-1caf59ad61dc', 'a225fd6f-7478-4cbf-a45f-4e66863f2c04', 'es', 'Rotación externa de hombro 90º en rodillas con cable', 'Arrodíllate de lado a la polea. Con el brazo exterior elevado a 90 grados, rota el hombro hacia atrás tirando del cable, manteniendo el codo alineado con el hombro.'),
('88a2fef3-671e-4b77-bc2f-336eb6b47b69', 'a2271c65-170c-4e2d-84d3-23dd480652e4', 'en', 'Barbell Zottman Curl', 'Although traditionally done with dumbbells, you can simulate the movement with a bar by performing the concentric phase with a supine grip and switching to prone for the eccentric. Works biceps on the way up and brachioradialis on the way down.'),
('20e082b9-c3a4-484f-b1de-cf496fab5dde', 'a2271c65-170c-4e2d-84d3-23dd480652e4', 'es', 'Zottman curl barra', 'Aunque tradicionalmente se hace con mancuernas, puedes simular el movimiento con barra realizando la fase concéntrica con agarre supino y cambiando a prono para la excéntrica. Trabaja bíceps en la subida y braquiorradial en la bajada.'),
('452dcc6f-888f-4cd0-be43-8d7eb7058808', 'a2287b32-51a9-4210-b2ab-a02c8759924a', 'en', 'Dumbbell Squat', 'Hold a dumbbell in each hand at your sides. Perform a normal squat keeping the dumbbells hanging naturally. This variation is more comfortable for beginners than the barbell squat and allows for a lower center of gravity.'),
('481af46d-5086-4909-b611-917ab0548bbd', 'a2287b32-51a9-4210-b2ab-a02c8759924a', 'es', 'Sentadilla mancuernas', 'Sujeta una mancuerna en cada mano a los lados del cuerpo. Realiza una sentadilla normal manteniendo las mancuernas colgando naturalmente. Esta variación es más cómoda para principiantes que la sentadilla con barra y permite un centro de gravedad más bajo.'),
('4f66fd84-b290-4bce-ad7f-374889a1f9c5', 'a22e5e04-123d-4a58-ba3a-41c2173af6f1', 'en', 'TRX Triceps Extension', 'Leaning forward with arms extended overhead, flex the elbows bringing hands toward the head. Keep elbows fixed and the body straight. The further you lean, the greater the difficulty.'),
('637f87d3-7b13-402e-895c-03fad29af0ad', 'a22e5e04-123d-4a58-ba3a-41c2173af6f1', 'es', 'Extensión tríceps TRX', 'Inclinado hacia adelante con brazos extendidos sobre la cabeza, flexiona los codos llevando las manos hacia la cabeza. Mantén los codos fijos y el cuerpo recto. Cuanto más inclinado, mayor dificultad.'),
('49d75e6d-86a5-492c-8e14-19efe53a1942', 'a2316ed6-f94a-4eef-b91a-3ca70febf032', 'en', 'Guillotine Press', 'Lower bar to the neck with a wide grip. Objective: upper chest fibers. Cue: elbows open. Error: excess weight.'),
('e09915ca-5f82-4c84-9b3d-b4785f45601e', 'a2316ed6-f94a-4eef-b91a-3ca70febf032', 'es', 'Press guillotina', 'Baja barra al cuello agarre ancho. Objetivo: fibras superiores pecho. Cue: codos abiertos. Error: exceso peso.'),
('a6d3f6f6-e861-4a54-8ed0-a05fd7967ee3', 'a23da5c7-3181-4073-9a6a-1295f2539c54', 'en', 'Leg Press Calf Raises', 'Push the platform only with the toes. Objective: calves. Cues: full range. Common error: locked knees.'),
('ea6fa70e-4c95-4256-bd2f-4f955a80323e', 'a23da5c7-3181-4073-9a6a-1295f2539c54', 'es', 'Elevación de talones en máquina de prensa', 'Empuja plataforma solo con puntas. Objetivo: gemelos. Cues: rango total. Error común: rodillas bloqueadas.'),
('9d5938a3-d149-4c61-bf50-395a1e974a83', 'a267e7a0-fc3c-4c09-8db5-e794132992b2', 'en', 'Alternating Battle Ropes Jumps', 'Jump alternating legs (like running in place jumping) while maintaining waves. Extremely cardiovascularly demanding. Coordinate jump rhythm with waves. Keep core activated.'),
('78f935de-8d4e-47a3-9a63-b1dd5704c225', 'a267e7a0-fc3c-4c09-8db5-e794132992b2', 'es', 'Saltos alternados battle ropes', 'Saltos alternando piernas (como correr en el sitio saltando) mientras mantienes ondas. Extremadamente demandante cardiovascularmente. Coordina el ritmo de saltos con las ondas. Mantén core activado.'),
('e5a1a937-8467-403c-b891-44a0da162717', 'a27ec17d-a0e5-49c7-a5de-7d7c1442d9e0', 'en', 'Bicycle Crunch with Miniband', 'Place a Miniband around the feet. Perform the bicycle movement, bringing the elbow to the opposite knee while extending the other leg against the resistance of the band.'),
('64d6c623-6cb2-47c3-a060-743c459a482c', 'a27ec17d-a0e5-49c7-a5de-7d7c1442d9e0', 'es', 'Bicycle Crunch con Miniband', 'Coloca una Miniband alrededor de los pies. Realiza el movimiento de bicicleta, llevando el codo a la rodilla contraria mientras extiendes la otra pierna contra la resistencia de la banda.'),
('17bf4450-a4c2-4ed2-80fb-5386a737b8ab', 'a2bf7f52-15f6-4d87-b515-f785ff075af9', 'es', 'V-Ups alternos', 'Toca pie contrario con mano contraria elevando torso y pierna. Cue: coordinación y control. Error: doblar la rodilla al subir.'),
('26e5f5fe-8f21-4d32-b7e6-83a41c2f43e5', 'a2f1afea-431b-4bed-a796-c161c3dddf7a', 'en', 'Frontal Hurdle Jump', 'Jump forward over a hurdle with feet together. Focused on vertical jump power and translation. Cue: lift knees high. Common error: landing flat-footed or on heels.'),
('d558ea48-9dbd-459d-8d96-90cf2e6818c3', 'a2f1afea-431b-4bed-a796-c161c3dddf7a', 'es', 'Salto de valla frontal', 'Salta hacia adelante sobre una valla con pies juntos. Enfocado en la potencia de salto vertical y traslación. Cue: eleva rodillas alto. Error común: aterrizar con el pie plano o los talones.'),
('233d14c2-1690-49aa-9249-ac468ebe35e6', 'a305909a-f75f-47d2-a5d2-55f0d0ee30f8', 'en', 'Safety Bar Squat', 'Squat using a safety squat bar (SSB) with handles. Changes the center of gravity making the exercise more challenging. More comfortable for shoulders with issues. Excellent variation to prevent adaptation.'),
('b5f3626e-71be-4d42-b4a0-eb578052dfba', 'a305909a-f75f-47d2-a5d2-55f0d0ee30f8', 'es', 'Sentadilla barra seguridad', 'Sentadilla usando barra de seguridad (SSB) con manijas. Cambia el centro de gravedad haciendo el ejercicio más desafiante. Más cómodo para hombros con problemas. Excelente variación para prevenir adaptación.'),
('89d16fce-5762-4194-b7fb-f0ff6a7bec65', 'a30d146d-d8ce-452a-a922-2ec19530a4cb', 'en', 'Soleus', 'Specific work for the soleus (deep calf), usually with bent knee, for ankle endurance and running.'),
('28b30d16-9043-4af1-bd82-3abcd3663cfd', 'a30d146d-d8ce-452a-a922-2ec19530a4cb', 'es', 'Sóleo', 'Realiza elevaciones de talón con rodilla flexionada, rango completo y pausa arriba. Control en la bajada.'),
('1e8584ab-56a1-4685-ba12-fd5467d56530', 'a343c8b0-07ad-46aa-ab83-52298ee2ac89', 'es', 'Curl bíceps con barra Z agarre supino', 'Flexiona barra Z para proteger muñecas. Cue: rango completo. Error: usar impulso de piernas.'),
('9eebac65-cdf3-48e2-8e08-e9b35dbda535', 'a352f541-28e9-460d-b91c-d49b62e7b139', 'en', 'Heel-to-Glute Pogo Jump', 'Jump quickly on the balls of feet bringing heels to glutes with each bounce. Cue: knees point to the ground. Common error: bending hips forward.'),
('693fd5e2-8594-4c99-a3c0-5e0a4d112d4d', 'a352f541-28e9-460d-b91c-d49b62e7b139', 'es', 'Salto pogo talones al glúteo', 'Salta rápidamente sobre puntas de pies llevando talones a glúteos en cada rebote. Cue: rodillas apuntan al suelo. Error común: doblar la cadera hacia adelante.'),
('4f094d03-9bcb-4cde-99ef-7c08a2758a7c', 'a3601251-435f-4b9b-9a6c-0a6065756428', 'en', 'Single Arm Kettlebell Windmill', 'With a kettlebell held overhead and feet wide, hinge your torso laterally toward the free foot while keeping your eyes on the weight.'),
('455443b4-51d7-4fdd-8f95-550a1c6af655', 'a3601251-435f-4b9b-9a6c-0a6065756428', 'es', 'Windmill con Kettlebell a una mano', 'Con una Kettlebell sobre la cabeza y pies anchos, inclina el torso lateralmente hacia el pie libre manteniendo la vista en la pesa.'),
('acde0ea6-2e32-47f8-8882-8b2f670bc10e', 'a3affb5a-ed3e-4e2f-8970-035ce871675a', 'en', 'Elastic Band Monster Walk', 'Band on knees or ankles, walk forward and backward keeping the knees out in a half squat. Objective: gluteus medius. Cue: do not let the band bring your knees together. Error: dragging feet.'),
('fd776e65-642c-4b58-aa8b-487947916702', 'a3affb5a-ed3e-4e2f-8970-035ce871675a', 'es', 'Monster Walk con banda elástica', 'Banda en rodillas o tobillos, camina hacia adelante y atrás manteniendo las rodillas hacia afuera en media sentadilla. Objetivo: glúteo medio. Cue: no dejes que la banda junte tus rodillas. Error: arrastrar los pies.'),
('ef0319ec-1b6c-4693-be7e-2ca4c185ccdd', 'a3bc0818-cd0d-4c20-a49a-9e2e980bc6af', 'en', 'Barbell Clean', 'Olympic lift that brings the bar from the floor to shoulders in an explosive movement. Requires perfect technique: first pull to knees, second explosive pull with triple extension (ankles, knees, hips), and receiving in a partial front squat.'),
('d9f153b6-fea0-4590-8a6b-d58ddfaba807', 'a3bc0818-cd0d-4c20-a49a-9e2e980bc6af', 'es', 'Cargada barra', 'Levantamiento olímpico que lleva la barra desde el suelo hasta los hombros en un movimiento explosivo. Requiere técnica perfecta: primera tracción hasta las rodillas, segunda tracción explosiva con extensión triple (tobillos, rodillas, caderas), y recepción en sentadilla frontal parcial.'),
('55dbfd18-df70-4d85-a64d-18a14bbc0eb1', 'a3d74d5f-9e27-4580-8a6e-e4e9c02c6651', 'en', 'Crunch on Fitball', 'Lie with the lower back supported on the fitball and feet firm on the floor. Perform an abdominal crunch lifting the shoulders.'),
('e75a0935-d1f0-4e2f-81ac-af017bcfc5d6', 'a3d74d5f-9e27-4580-8a6e-e4e9c02c6651', 'es', 'Crunch sobre Fitball', 'Acuéstate con la espalda baja apoyada en el Fitball y los pies firmes en el suelo. Realiza un encogimiento abdominal (crunch) elevando los hombros.'),
('8644738e-8b69-451f-b4b7-04fcb643dc22', 'a4031669-49c8-4b9d-bf83-867abdf76800', 'en', 'Band Hip Abduction', 'Standing with the band around your ankles, lean slightly for balance. Lift one leg laterally while keeping it straight, resisting the tension of the band. Keep the torso upright and avoid leaning toward the opposite side.'),
('64b3c631-b883-4989-98fe-b2d9a513bf53', 'a4031669-49c8-4b9d-bf83-867abdf76800', 'es', 'Abducción cadera con banda', 'De pie con la banda alrededor de los tobillos, apóyate ligeramente para mantener el equilibrio. Eleva lateralmente una pierna manteniéndola recta, resistiendo la tensión de la banda. Mantén el torso erguido y evita inclinarte hacia el lado opuesto.'),
('3fb60e65-48b0-4f1e-a390-e96de6d683c9', 'a40d064f-7784-4577-9db7-a4398973998c', 'en', 'Dumbbell Concentration Curl', 'Seated, support the elbow on the inner thigh and flex the weight. Objective: bicep isolation. Cue: arm completely vertical. Common error: using the shoulder to help at the start of the movement.'),
('b541bea4-f3e2-4f25-b4da-d72e575efd53', 'a40d064f-7784-4577-9db7-a4398973998c', 'es', 'Curl concentrado con mancuerna', 'Sentado, apoya el codo en la cara interna del muslo y flexiona la pesa. Objetivo: aislamiento del bíceps. Cue: brazo totalmente vertical. Error común: usar el hombro para ayudar al inicio del movimiento.'),
('27e75e57-ffa5-4b79-89fa-9fcd7fe6573c', 'a41e92a4-14fc-4dc6-9e48-1d5604b855e3', 'en', 'Reverse Nordic', 'Kneeling on the floor, lean the torso backward keeping the body straight from knees to shoulders, stretching the quadriceps.'),
('156b9b7e-122c-4710-967b-169aeddaa196', 'a41e92a4-14fc-4dc6-9e48-1d5604b855e3', 'es', 'Nórdico inverso', 'De rodillas en el suelo, inclina el torso hacia atrás manteniendo el cuerpo recto desde las rodillas a los hombros, estirando los cuádriceps.'),
('5a8c154e-d446-4228-bca7-d0145370a7c4', 'a4358eba-56f1-4cc5-92a2-a36f5c97db8f', 'en', 'Battle Rope Sprawl', 'Combines sprawls (burpee without push-up) with battle rope waves. Perform waves, release ropes, sprawl, retake ropes and repeat. Extreme metabolic exercise. Maintain fast transitions.'),
('5efeecb3-f0c7-468a-9c2a-d7c2026e3ed2', 'a4358eba-56f1-4cc5-92a2-a36f5c97db8f', 'es', 'Sprawl battle ropes', 'Combina sprawls (burpee sin flexión) con ondas de battle ropes. Realiza ondas, suelta las cuerdas, sprawl, vuelve a tomar las cuerdas y repite. Ejercicio metabólico extremo. Mantén transiciones rápidas.'),
('01ae783d-b979-4b89-b18e-737ed5146ba6', 'a44d2d3c-73f4-46ac-a22b-3833c1b4cc44', 'en', 'Cable Hip Thrust', 'With cable anchored low and positioned on the hips, perform hip thrusts. The cable provides unique horizontal resistance compared to the barbell. Strongly squeeze glutes at the top of the movement.'),
('1c493fe8-c215-4a07-8099-c2da062b775d', 'a44d2d3c-73f4-46ac-a22b-3833c1b4cc44', 'es', 'Hip thrust cable', 'Con cable anclado bajo y posicionado sobre las caderas, realiza empujes de cadera. El cable proporciona resistencia horizontal única comparada con la barra. Aprieta fuertemente los glúteos en la parte superior del movimiento.'),
('e85a6ba5-908c-47e3-b111-813411f906b5', 'a4f1c955-4217-48e0-9a3d-90c80a3fc0aa', 'en', 'Paused Squat', 'Squat with a 2-3 second pause in the lowest position. Eliminates bounce and increases time under tension. Improves strength coming out of the hole. Common in powerlifting. Maintain tension during the pause.'),
('1785e123-cece-4d94-b489-b3bbdeea5786', 'a4f1c955-4217-48e0-9a3d-90c80a3fc0aa', 'es', 'Sentadilla con pausa', 'Sentadilla con pausa de 2-3 segundos en la posición más baja. Elimina rebote y aumenta tiempo bajo tensión. Mejora fuerza en la salida del hoyo. Común en powerlifting. Mantén tensión durante la pausa.'),
('9b5702fa-b227-4613-a04a-9b72d60b3e60', 'a505742f-3194-45f4-ab39-a8eeab63ce86', 'en', 'Rope Climb', 'Climb up a vertical rope using foot technique for assistance. Full functional exercise that develops exceptional grip strength. Learn appropriate safety technique. Start with thicker ropes and progress.'),
('b5b1b6fe-0f38-4862-9a64-4b9e7e5fd93e', 'a505742f-3194-45f4-ab39-a8eeab63ce86', 'es', 'Trepar cuerda', 'Sube por una cuerda vertical usando técnica de pies para asistencia. Ejercicio funcional completo que desarrolla fuerza de agarre excepcional. Aprende técnica de seguridad apropiada. Comienza con cuerdas más gruesas y progresa.'),
('163c8508-6eaa-4256-9682-446c7c912c80', 'a52c6338-af2b-4194-848c-cbd584557853', 'en', 'Medicine Ball Jump Burpee', 'Perform a burpee and end by jumping laterally over a medicine ball. Precision and power. Cue: do not lose sight of the ball when jumping. Common error: tripping over the ball.'),
('bf32deaf-2382-429b-b226-0b496f984a5e', 'a52c6338-af2b-4194-848c-cbd584557853', 'es', 'Burpee salto sobre balón', 'Haz un burpee y termina saltando lateralmente sobre un balón medicinal. Precisión y potencia. Cue: no pierdas de vista el balón al saltar. Error común: tropezar con el balón.'),
('f26421d2-d499-4f58-b5b2-fd4fab880214', 'a54f9978-4e4b-4819-afe0-d4e9dc5ecccc', 'en', 'Bodyweight Dive Bomber Push Up', 'Start in an inverted V position, lower your chest skimming the floor, and finish by extending your arms looking forward.'),
('1b3249be-b6ec-442f-aadc-8197c1d5fb81', 'a54f9978-4e4b-4819-afe0-d4e9dc5ecccc', 'es', 'Push Up tipo bomber en buceo', 'Comienza en posicion de V invertida, baja el pecho rozando el suelo y termina extendiendo los brazos con la mirada al frente.'),
('7ece956d-b73b-43c1-853f-456bb771cb35', 'a59cc0dc-3ddb-42fb-945a-30cb335fa27b', 'en', 'Side Lying Incline Lateral Raises', 'Lying sideways on a bench, lift weight. Cue: maximum initial tension. Error: rotating shoulder.'),
('d84e9b33-6e7d-451b-a47e-2bbbfba8f2a8', 'a59cc0dc-3ddb-42fb-945a-30cb335fa27b', 'es', 'Elevaciones laterales banco de lado inclinado', 'Tumbado lateral en banco, eleva pesa. Cue: tensión máxima inicial. Error: rotar hombro.'),
('55d16ee5-e6e1-45b7-9cd7-17b8d68c3290', 'a5a144b4-c372-4065-acfd-c6231957c6d5', 'en', 'Kettlebell Bottoms Up Horn Grip Goblet Bulgarian Split Squat', 'Perform a Bulgarian split squat while holding the upside-down kettlebell by the horns in front of the chest, challenging balance and stability.'),
('436c16f2-ffcc-410a-a353-4e688f46a414', 'a5a144b4-c372-4065-acfd-c6231957c6d5', 'es', 'Kettlebell Bottoms Up Horn Grip Goblet Sentadilla Búlgara búlgara', 'Realiza una sentadilla búlgara sujetando la pesa rusa invertida por los cuernos frente al pecho, retando equilibrio y estabilidad.'),
('94620a70-40d3-4438-b950-69289cad631f', 'a5b0ac04-2cbf-4b9c-9be1-f3c71159362b', 'en', 'Bottoms Up Cyclist Squat with Kettlebell (Front Rack)', 'Hold an inverted kettlebell in rack position on one shoulder and perform a cyclist squat with heels elevated.'),
('683910db-68af-49c2-bc74-f2f8e78f48d0', 'a5b0ac04-2cbf-4b9c-9be1-f3c71159362b', 'es', 'Sentadilla Ciclista con Kettlebell Bottoms Up (Front Rack)', 'Sujeta una Kettlebell invertida en posicion rack sobre un hombro y realiza una sentadilla ciclista con los talones elevados.'),
('f00370f2-3df1-46c5-ab08-a813356ea7bd', 'a5da9a59-51ea-42f0-aeea-b85b0a8ea401', 'en', 'Reverse Grip Bench Press', 'Hold the bar with palms facing your face (supinated). Objective: higher activation of the upper pectoral and triceps. Cues: secure grip and straight wrists. Common error: using excessive weight that compromises wrist safety.'),
('ac88571d-b05d-4eea-924c-fa6cc9ffe089', 'a5da9a59-51ea-42f0-aeea-b85b0a8ea401', 'es', 'Press de banca con agarre inverso', 'Sujeta la barra con las palmas mirando hacia tu cara (supinadas). Objetivo: mayor activación del pectoral superior y tríceps. Cues: agarre seguro y muñecas rectas. Error común: usar un peso excesivo que comprometa la seguridad de las muñecas.'),
('9f62eb6e-f105-4a4d-92a2-9831555bfae0', 'a67a3bff-b643-41b5-9195-d8f278d50ca0', 'en', 'Machine Incline Press', 'On a machine with an inclined backrest, perform the press focusing on the upper pectoral. The guided trajectory allows focusing on the movement without worrying about stabilization. Adjust seat for correct alignment.'),
('840743ff-3069-4852-94ac-5a2c8bdd8bd9', 'a67a3bff-b643-41b5-9195-d8f278d50ca0', 'es', 'Press inclinado máquina', 'En máquina con respaldo inclinado, realiza el press enfocando el pectoral superior. La trayectoria guiada permite concentrarse en el movimiento sin preocuparse por la estabilización. Ajusta el asiento para alineación correcta.'),
('e1b6fff8-8a39-42b3-8d5a-f77131ca1b6e', 'a68da7d6-bd74-49fc-a270-845233dff09f', 'en', 'Cable Fitball Preacher Curl', 'Support triceps on a Fitball. Use a low pulley to perform curls, using the ball as a support similar to a preacher bench.'),
('0456bdd1-787c-46f1-9031-47950dd9db86', 'a68da7d6-bd74-49fc-a270-845233dff09f', 'es', 'Curl Predicador con cable en Fitball', 'Apoya los tríceps sobre un Fitball. Usa una polea baja para realizar curls, utilizando el balón como soporte similar a un banco predicador.'),
('a2729056-68a6-4927-becb-37ce399c0a55', 'a6cbf030-eda2-4958-9c48-758910fa8de9', 'es', 'Zancada caminando', 'Da pasos largos hacia adelante bajando la cadera hasta que ambas rodillas formen un ángulo de 90 grados, avanzando continuamente.'),
('3ad1e9a2-a40b-4be4-b8a7-c82dd93ced48', 'a6e0aa3a-9148-4322-8ceb-d1cbcaf60672', 'en', 'Overhead Bulgarian Split Squat Knee-over-Toe', 'Hold the bar locked overhead while performing a split squat with the foot elevated, intentionally bringing the front knee over the toes.'),
('366eb403-a9f9-4b61-8562-980ade077847', 'a6e0aa3a-9148-4322-8ceb-d1cbcaf60672', 'es', 'Sentadilla Búlgara Overhead rodilla sobre punta del pie', 'Sostén la barra bloqueada sobre la cabeza mientras realizas una sentadilla split con el pie elevado, llevando la rodilla delantera intencionalmente sobre los dedos del pie.'),
('1590e508-0986-4047-b87e-c1958688f15b', 'a6f2487b-f321-4f43-b528-1cc08f679145', 'en', 'Supinated Barbell Row', 'Perform the bent-over row with a supinated grip (palms facing up). This variation allows greater bicep involvement and can be more comfortable for the wrists. Pull toward the lower abdomen keeping your elbows tucked to the body.'),
('e8be161f-356b-4234-aea4-6d897d2cc8c2', 'a6f2487b-f321-4f43-b528-1cc08f679145', 'es', 'Remo supino barra', 'Realiza el remo inclinado con agarre supino (palmas hacia arriba). Esta variación permite mayor participación del bíceps y puede ser más cómoda para las muñecas. Tira hacia el abdomen inferior manteniendo los codos pegados al cuerpo.'),
('63d2049d-a98c-4d71-a419-cff8221bfb12', 'a70fa606-7a15-4ecc-96e7-c376b80046a9', 'es', 'Zancada estática barra', 'Split squat barra hombros. Objetivo: cuádriceps. Cue: torso vertical. Error: rodilla sobrepasa pie.'),
('5876c903-711c-493e-b9fe-ce6fd1a860e5', 'a714552d-f7e3-4311-ae29-6735bf5f3bca', 'es', 'Zancada caminando Zombie con barra', 'Camina realizando zancadas con la barra apoyada en los deltoides frontales y los brazos estirados hacia adelante (sin manos), desafiando el equilibrio.'),
('200e84c6-9285-4cb4-bfae-88b3ec0fa426', 'a74951c6-00a4-43d9-a4f8-db6bab96c406', 'en', 'Floor Lumbar Extensions', 'Raise only the chest while keeping feet on the floor. Cue: look at the floor. Error: sudden jerks with the neck.'),
('7399f4df-93f3-4659-8943-d465db6ba4df', 'a74951c6-00a4-43d9-a4f8-db6bab96c406', 'es', 'Extensiones lumbares en suelo', 'Eleva solo el pecho manteniendo pies en suelo. Cue: mira al suelo. Error: tirones bruscos con el cuello.'),
('b616d749-1b88-4e89-8022-0feff5bf0b90', 'a79fda5e-026e-43f0-9a0e-69aa0b5e3d94', 'en', 'Ring Single Leg Out Front Lever', 'Execute a Front Lever with one leg fully extended and the other tucked to the chest, alternating to balance strength.'),
('cc5edc64-0ad5-41f5-bca8-14fb891c4d32', 'a79fda5e-026e-43f0-9a0e-69aa0b5e3d94', 'es', 'Front Lever a una pierna en anillas', 'Ejecuta un Front Lever con una pierna completamente estirada y la otra encogida hacia el pecho, alternando para equilibrar la fuerza.'),
('b0535287-d503-48e5-9580-f75c65a6b286', 'a7c9726b-f332-4de7-b66c-18d36abefdde', 'en', 'Barbell Upright Row', 'Pull the bar close to the body toward the chin by raising the elbows. Objective: deltoids and trapezius. Cues: elbows above the wrists. Common error: performing sudden jerks with the lumbar area.'),
('cd262238-0f1c-48e5-9b8c-a95c92bdc077', 'a7c9726b-f332-4de7-b66c-18d36abefdde', 'es', 'Remo al cuello con barra', 'Tira de la barra pegada al cuerpo hacia el mentón elevando los codos. Objetivo: deltoides y trapecio. Cues: codos por encima de las muñecas. Error común: realizar tirones bruscos con la zona lumbar.'),
('546de45b-31a1-46bf-a129-88782c4d9f47', 'a7f25b5e-8eb0-40fe-bffc-6dc90bd6373d', 'en', 'Cable Hip Abduction', 'Standing sideways to the low pulley, attach the ankle furthest from the machine. Keeping the leg straight, lift it laterally away from the body and return in a controlled manner.'),
('8b13963c-f7a4-4c98-a336-4bd592b0fd4e', 'a7f25b5e-8eb0-40fe-bffc-6dc90bd6373d', 'es', 'Abducción de cadera con cable', 'De pie de lado a la polea baja, sujeta el tobillo más alejado a la máquina. Manteniendo la pierna recta, levántala lateralmente alejándola del cuerpo y regresa controladamente.'),
('e96a5ba7-c95b-4390-89c7-75f26badb31f', 'a81696c9-77ff-46be-90fa-d1011c61a427', 'en', 'Diamond Plyometric Push Up', 'Perform a diamond push-up and push so hands leave the ground. Pure triceps power. Cue: hands under the sternum. Common error: arching the lower back due to lack of strength.'),
('e2efb356-f5d3-45f5-bebe-31bf959e7d62', 'a81696c9-77ff-46be-90fa-d1011c61a427', 'es', 'Flexión pliométrica diamante', 'Realiza flexión en diamante y empuja para que las manos despeguen del suelo. Potencia pura de tríceps. Cue: manos bajo el esternón. Error común: arquear la espalda baja por falta de fuerza.'),
('7a4cdafa-1bc4-464d-868c-6ef2004b4994', 'a83046cb-2cab-4aee-81ca-04e606b6fc4b', 'en', 'Tuck Jump', 'Jump vertically and quickly bring knees toward the chest in the air. Land and repeat. Objective: explosive power and hip speed. Cue: land on balls of feet to absorb impact. Common error: leaning the back backward in the air.'),
('2388868d-6b26-414c-bd19-c95d544407b4', 'a83046cb-2cab-4aee-81ca-04e606b6fc4b', 'es', 'Salto con rodillas al pecho', 'Salta verticalmente y lleva las rodillas hacia el pecho rápidamente en el aire. Aterriza y repite. Objetivo: potencia explosiva y velocidad de cadera. Cue: aterriza con las puntas para absorber impacto. Error común: inclinar la espalda hacia atrás en el aire.'),
('6fa82015-a9d3-41f3-b0b0-da172cbea577', 'a83c3bea-c9d6-4c67-94fa-a5cbc3cf181d', 'en', 'One-Arm Overhead Cyclist Squat with Kettlebell', 'Elevate heels and keep a kettlebell locked overhead while performing a deep squat.'),
('35e5f842-dc3c-4851-b446-7a79878a7ec2', 'a83c3bea-c9d6-4c67-94fa-a5cbc3cf181d', 'es', 'Sentadilla Ciclista Overhead con Kettlebell a una mano', 'Eleva los talones y mantén una Kettlebell bloqueada sobre la cabeza mientras realizas una sentadilla profunda.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('2d3346b4-fff8-4e0d-a79e-aa1e7d27af9b', 'a84cfde7-6f51-4665-9df9-05825cd77371', 'en', 'Band Internal Shoulder Rotation', 'Similar to external rotation but rotating the forearm inward crossing the body. Keep the elbow glued to your side and flexed at 90 degrees. Complements external rotation work for balanced rotator cuff development.'),
('176dd664-2bdb-4365-8d0b-3c85400dc3b2', 'a84cfde7-6f51-4665-9df9-05825cd77371', 'es', 'Rotación interna hombro banda', 'Similar a la rotación externa pero rotando el antebrazo hacia adentro cruzando el cuerpo. Mantén el codo pegado al costado y flexionado a 90 grados. Complementa el trabajo de rotación externa para un desarrollo equilibrado del manguito rotador.'),
('e4e5fef9-342d-470a-8b52-ac57488406e8', 'a8639ad6-325b-4efd-a3d8-8596a2e363fe', 'en', 'Medicine Ball Push Ups', 'Perform push-ups with one hand on the ball and the other on the floor. Shoulder instability. Straight body. Do not let your chest drop to the ball.'),
('c465f26e-fb53-4cc1-92aa-0659565c0f3b', 'a8639ad6-325b-4efd-a3d8-8596a2e363fe', 'es', 'Flexiones sobre balón medicinal', 'Realiza flexiones con una mano sobre el balón y otra en el suelo. Inestabilidad de hombro. Cuerpo recto. No dejes caer el pecho al balón.'),
('f9ace4bd-87ff-472a-89e4-2080ccdb19cb', 'a88b0722-76a0-4db9-ab04-b7709c7caadd', 'en', 'Standing Machine Calf Raise', 'Standing with shoulders under the pads, rise onto the balls of your feet. The extended leg position emphasizes the gastrocnemius. Keep the movement controlled and seek maximum possible range of motion.'),
('a6b03b75-de52-4d7f-a6f2-e3988050a1da', 'a88b0722-76a0-4db9-ab04-b7709c7caadd', 'es', 'Pantorrillas de pie máquina', 'De pie con los hombros bajo las almohadillas, elévate sobre las puntas de los pies. La posición de piernas extendidas enfatiza el gemelo. Mantén el movimiento controlado y busca el máximo rango de movimiento posible.'),
('f86a1eb2-febd-449a-9cf4-5b7811ef1457', 'a88b5521-b5ee-47bd-bcd1-b0107d3c0ff1', 'en', 'Shoulder Lateral Raises', 'Lift dumbbells to the sides to shoulder height with elbows semi-flexed. Cue: pour water from a pitcher while rising. Error: rising above shoulders.'),
('12bc7b79-9b5a-423a-9e9c-0b08719b3cbd', 'a88b5521-b5ee-47bd-bcd1-b0107d3c0ff1', 'es', 'Elevaciones laterales de hombro', 'Eleva mancuernas a los lados hasta la altura de los hombros con codos semiflexionados. Cue: vierte agua de una jarra al subir. Error: subir por encima de los hombros.'),
('5baa566a-7a02-4bae-ab81-515d3de78592', 'a8996200-38eb-4300-984d-bc9ec11b4524', 'en', 'TRX Floor Abductors', 'Open/close legs in TRX lying down. Objective: abductors. Cue: firm core. Error: jerky movements.'),
('eea1943d-b946-471f-afb8-291560df7008', 'a8996200-38eb-4300-984d-bc9ec11b4524', 'es', 'TRX Abductores suelo', 'Abre/cierra piernas TRX tumbado. Objetivo: abductores. Cue: core firme. Error: tirones.'),
('ece6ee58-19ab-418b-9643-63d0ff2aacd1', 'a8acfa2e-34f3-4d4c-b99c-2620b8d3885e', 'en', 'Hand-Assisted Bulgarian Split Squat', 'With one foot back on a bench, perform a squat while supporting yourself with hands on a lateral frame to improve balance.'),
('30095259-6faf-4ec2-a31d-0200059da978', 'a8acfa2e-34f3-4d4c-b99c-2620b8d3885e', 'es', 'Sentadilla búlgara asistida con manos', 'Con un pie atrasado en un banco, realiza una sentadilla apoyándote en un soporte lateral con las manos para mejorar el equilibrio.'),
('e74b99c4-6aea-43f6-838d-a89e65d7b45c', 'a8af4f2b-ef08-4253-a131-3c0e8781ea09', 'en', 'Ab wheel rollout', 'Slide the wheel forward from knees. Cue: core very tight. Error: letting the hips sag.'),
('81525a05-f132-4744-a5aa-295f30e8d390', 'a8af4f2b-ef08-4253-a131-3c0e8781ea09', 'es', 'Ab wheel rollout', 'Desliza la rueda hacia adelante desde rodillas. Cue: core muy apretado. Error: dejar caer la cadera.'),
('a176e814-583b-4910-a30d-2e36531999ed', 'a8c141ef-3274-4686-8e9c-0f0a77d11870', 'en', 'Guillotine Bench Press', 'Lower the bar toward the base of the neck with a wide grip. Objective: upper chest fibers. Cue: elbows very flared. Common error: using too much weight without control (dangerous for shoulders).'),
('bda2740a-2b80-4daf-9ef7-4bec09dc4684', 'a8c141ef-3274-4686-8e9c-0f0a77d11870', 'es', 'Press de banca guillotina', 'Baja la barra hacia la base del cuello con agarre ancho. Objetivo: fibras superiores del pecho. Cue: codos muy abiertos. Error común: usar demasiado peso sin control (peligroso para hombros).'),
('135457ba-587b-4702-96c8-db09a2922e64', 'a8da5c66-8efe-48cc-881a-add3ec45e411', 'en', 'Dumbbell Step Up (Suitcase)', 'Step onto a box or bench supporting the entire sole of the foot. Hold dumbbells at your sides and push with the front leg until extended.'),
('c05f93ad-88cb-4c1b-b2e5-92d308518536', 'a8da5c66-8efe-48cc-881a-add3ec45e411', 'es', 'Step Up con mancuernas (Maleta)', 'Sube a un cajón o banco apoyando toda la planta del pie. Sostén las mancuernas a los lados y empuja con la pierna delantera hasta extenderte.'),
('987a8da5-4d6b-4393-a503-8f169664bd7d', 'a8f79f3d-a400-4294-97b3-a14ac0d9e201', 'en', 'Incline Bench EZ Bar Triceps Extension', 'Lying on an incline bench, lower the EZ bar toward the forehead by flexing elbows and then extend arms fully to work the triceps.'),
('e7963790-88d3-405d-bccc-cdd8cd2e9df4', 'a8f79f3d-a400-4294-97b3-a14ac0d9e201', 'es', 'Extensión de tríceps en banco inclinado con barra Z', 'Tumbado en un banco inclinado, baja la barra Z hacia la frente flexionando los codos y luego extiende los brazos completamente para trabajar el triceps.'),
('84c7bf3e-0db6-4411-baf7-8f28c25e9569', 'a8fd38db-bda3-4af5-8343-e20608a01297', 'es', 'Press Z con Kettlebell doble', 'Siéntate en el suelo con las piernas estiradas en V. Sin apoyo en la espalda, realiza un press de hombros con dos pesas rusas.'),
('b5127a4c-e83b-4d92-aa1d-b9e9fe64c325', 'a8fe1fde-7b55-4ec5-ad99-a0fd59ebf0aa', 'en', 'Glute Machine', 'On a specific glute machine, perform hip extensions. Can be standing or quadruped according to design. Focus on glute contraction without excessively arching the back. Keep the core engaged.'),
('088df8f7-4112-4c75-9b51-327c534f2497', 'a8fe1fde-7b55-4ec5-ad99-a0fd59ebf0aa', 'es', 'Glúteo máquina', 'En máquina específica para glúteos, realiza extensiones de cadera. Puede ser de pie o en cuadrupedia según el diseño. Enfócate en la contracción del glúteo sin arquear excesivamente la espalda. Mantén el core activado.'),
('684db712-0bc8-4c9c-8223-e0d8dfc1e77b', 'a90d5a22-3943-4421-ab70-b9b5a7abbaf9', 'es', 'Zancada inversa contralateral con Slider y Kettlebell Bottoms Up', 'Sostén una pesa rusa invertida (fondo arriba) en una mano y desliza hacia atrás la pierna del lado opuesto usando un slider.'),
('a997aca4-c6e7-4a39-a58e-901d9325b00e', 'a9248bb3-4cba-497f-9411-4e42e619f9ab', 'es', 'Peso muerto Trap Bar', 'Levanta la barra hexagonal usando las asas superiores. Cue: saca pecho y espalda plana. Error: rodillas hacia adentro.'),
('629bb341-3b5f-4ddb-aefe-dc9e2a37cd48', 'a93e7021-2fa7-490b-a5de-bb2165d4f168', 'en', 'TRX Feet-Elevated Chest Pushup', 'Feet in the handles, perform pushups on the floor. Maximum instability. Straight body. Do not let the lumbar zone sag.'),
('95adbe0d-5dad-42b9-b5e5-6f85c1c4c477', 'a93e7021-2fa7-490b-a5de-bb2165d4f168', 'es', 'TRX Flexión de pecho con pies elevados', 'Pies en los agarres, realiza flexiones en el suelo. Inestabilidad máxima. Cuerpo recto. No dejes que la zona lumbar se hunda.'),
('b26eb836-2bf0-4fa9-a997-a45000c66592', 'a95496db-9d14-4bd0-b9d7-87fa5388752b', 'en', 'Barbell Reverse Grip Bent Over Row', 'Hinged forward, hold the bar with palms up and pull it toward your navel while keeping your back straight.'),
('f485d3a3-f180-43c4-8e46-a48fe48c4184', 'a95496db-9d14-4bd0-b9d7-87fa5388752b', 'es', 'Remo inclinado agarre inverso con barra', 'Inclinado hacia adelante, sujeta la barra con palmas hacia arriba y tirala hacia el ombligo manteniendo la espalda recta.'),
('e347fe6c-3b06-43aa-be4f-f2bd20971015', 'a95c8cdd-8ffb-4ac9-b83b-370434071f0e', 'en', 'Inverted Barbell Row', 'Hold a fixed bar from below with a straight body and heels supported. Pull the chest toward the bar contracting the scapulae and lower with control.'),
('293121ab-a268-4235-93bd-b26a72c1d312', 'a95c8cdd-8ffb-4ac9-b83b-370434071f0e', 'es', 'Remo invertido con barra', 'Sujeta una barra fija desde abajo con el cuerpo recto y los talones apoyados. Tira del pecho hacia la barra contrayendo las escápulas y baja con control.'),
('94ba90b0-2671-47aa-a6a4-b3eafe0a94f1', 'a98b5da4-5712-4058-a9a4-c71718c39d91', 'en', 'Superband Pallof Press', 'Hold the band in front of your chest laterally to the anchor and extend it while resisting rotation, deeply activating the core.'),
('8a97d694-2f85-43e2-afa3-9bd529950ccb', 'a98b5da4-5712-4058-a9a4-c71718c39d91', 'es', 'Press Pallof con banda elástica', 'Sujeta la banda frente al pecho lateralmente al anclaje y extiéndela resistiendo la rotación, activando profundamente el core.'),
('f11fb4aa-98c4-452f-91e2-57f16782ff69', 'a9aa5ddc-d604-42d7-a841-0373f2ee291a', 'en', 'Kneeling Rollout', 'Basic version of the rollout from knees. Ideal for beginners. Start with short ranges and progress gradually. Keep arms straight and avoid arching the lower back. Breathe controlled during the movement.'),
('a3690916-9d88-4f08-9dba-be5075a97f5d', 'a9aa5ddc-d604-42d7-a841-0373f2ee291a', 'es', 'Roll out rodillas', 'Versión básica del roll out desde rodillas. Ideal para principiantes. Comienza con rangos cortos y progresa gradualmente. Mantén los brazos rectos y evita arquear la espalda baja. Respira controladamente durante el movimiento.'),
('3f800323-e00a-44d5-8de1-aaaaff5659c8', 'a9d3698d-4d8f-4d5b-a977-0bb52acc608c', 'en', 'Battle Ropes Alternating Waves', 'Move the ropes up and down alternately as fast as possible. Maintain a partial squat. Firm core. Do not move the torso.'),
('cdfa67bf-a503-40bb-8dc5-dd319dd2696a', 'a9d3698d-4d8f-4d5b-a977-0bb52acc608c', 'es', 'Battle Ropes Ondas alternas', 'Mueve las cuerdas arriba y abajo de forma alterna lo más rápido posible. Mantén sentadilla parcial. Core firme. No muevas el tronco.'),
('97c955ef-7840-4901-9198-e7307fe2922c', 'aa233c17-781f-433a-903d-51bf9607d87a', 'en', 'Standing Ab Wheel Rollout', 'From a standing position, displace the wheel forward extending the body completely until close to the floor and return using core strength.'),
('2ed1f751-02ca-4da4-b997-f769e152a420', 'aa233c17-781f-433a-903d-51bf9607d87a', 'es', 'Rollout de pie con rueda abdominal', 'Desde una posicion de pie, desplaza la rueda hacia adelante extendiendo el cuerpo por completo hasta quedar cerca del suelo y regresa usando la fuerza del core.'),
('051f42e0-3660-4046-929d-d39ef63cef46', 'aa2c81c4-7430-4a94-93cd-181f6049680c', 'es', 'Press Pallof medio arrodillado con cable', 'En posicion de caballero lateral a la polea, sujeta el mando frente al pecho y extiende los brazos hacia adelante resistiendo la fuerza lateral del cable sin rotar el torso.'),
('89915141-06ff-4f6f-8e39-570bf2db9a91', 'aa2f3490-5f25-4536-a852-514f70c3e18c', 'en', 'Ring Dip Straight Body Press to Handstand', 'Perform a ring dip and use the pressing strength to lift the straight body until reaching a vertical handstand position.'),
('982ced1a-6df8-4d88-b356-e4cfd8d906e7', 'aa2f3490-5f25-4536-a852-514f70c3e18c', 'es', 'Ring Dip a Press de cuerpo recto a parada de manos', 'Realiza un fondo en anillas y utiliza la fuerza de empuje para elevar el cuerpo estirado hasta alcanzar la posicion vertical de parada de manos.'),
('a5a3d048-7a6d-4e93-8ec1-ed6381ff6065', 'aa3a6d28-80ba-4b65-ba0e-8ac84288a34d', 'es', 'Plancha frontal toques laterales', 'Saca pie lateral en plancha. Objetivo: estabilidad core. Cue: cadera quieta. Error: elevar glúteo.'),
('6602206d-4782-4d9e-8440-c3954ba59d2c', 'aa47071d-faaa-4d89-9b44-1c266868070a', 'en', 'Low Bar Back Squat', 'Place the bar on the posterior deltoids. Lean the torso slightly forward while lowering the hip, maximizing posterior chain leverage.'),
('9384b16f-78cd-4e80-aae3-70c14d25e860', 'aa47071d-faaa-4d89-9b44-1c266868070a', 'es', 'Sentadilla trasera con barra baja', 'Coloca la barra sobre los deltoides posteriores. Inclina el torso ligeramente hacia adelante mientras bajas la cadera, maximizando la palanca de la cadena posterior.'),
('1a7b5719-0d9d-4da3-939a-4e64fe950394', 'aa9dceb3-c91b-4b88-adee-5559fe0f8c4d', 'es', 'Press Overhead alterno (Seesaw) con Kettlebell', 'Presiona una pesa rusa hacia arriba mientras bajas la otra simultáneamente, creando un movimiento constante de sube y baja.'),
('4d66b75b-f7da-496e-bdc7-c814cc63a801', 'aaaafb0f-a04f-4f25-912c-8632b2511d2c', 'en', 'Fast Cross Body Mountain Climbers', 'Bring knee toward opposite elbow quickly. Cardio and core. Flat back. Do not lift glute too much.'),
('e37880d3-3b6a-45eb-a782-034e656bc8a2', 'aaaafb0f-a04f-4f25-912c-8632b2511d2c', 'es', 'Escaladores cruzados veloces', 'Lleva la rodilla hacia el codo opuesto rápidamente. Cardio y core. Espalda plana. No eleves el glúteo demasiado.'),
('296b545c-a90a-46f9-8dc1-75a4c33927c0', 'aab7f0e7-2192-42b7-9187-6a1af87a61ff', 'en', 'Dumbbell Upright Row', 'Raise dumbbells close to the body up to the chest while raising the elbows. Cue: elbows above wrists. Error: excessively shrugging the traps.'),
('8dbc1331-63ea-4dd6-8961-f7dd24904a38', 'aab7f0e7-2192-42b7-9187-6a1af87a61ff', 'es', 'Remo al mentón con mancuernas', 'Eleva mancuernas pegadas al cuerpo hasta el pecho subiendo codos. Cue: codos por encima de muñecas. Error: encoger trapecios excesivamente.'),
('91b25799-a639-4f73-93fa-8caea4a08483', 'aabc4438-1f04-4298-a1fa-f5db55d7b513', 'en', 'Plate Otis Up', 'Lying on your back, perform a sit up while keeping a plate extended over your chest with both arms locked throughout the movement.'),
('5fd90164-cb70-41b0-81b1-2569e64cadb9', 'aabc4438-1f04-4298-a1fa-f5db55d7b513', 'es', 'Plate Otis Up', 'Tumbado boca arriba, realiza un sit up manteniendo un disco extendido sobre el pecho con ambos brazos bloqueados durante el movimiento.'),
('780a4512-9ebf-4cc0-ad9f-857e446fb332', 'ab2363ff-8569-4c31-b430-f3b7615df839', 'en', 'Ring Chest Fly', 'From a plank position on rings, spread your arms laterally with a slight bend in the elbows and close them back in front of your chest.'),
('9abf8e71-3556-4893-90bf-ea056a153777', 'ab2363ff-8569-4c31-b430-f3b7615df839', 'es', 'Aperturas de pecho anular', 'Desde posicion de plancha en anillas, abre los brazos lateralmente con un ligero doblez en los codos y vuelve a cerrarlos frente al pecho.'),
('0d6683f6-1d7f-4229-ad3a-1403a69fffb3', 'ab5ec1e6-bc2e-478f-9d05-8c8c9a8af793', 'en', 'Band Lateral Raises', 'Step on the center of the band and hold the ends at the sides. Lift the arms laterally to shoulder height keeping a slight bend in the elbows. Control the descent resisting the band''s tension. Excellent for the middle deltoid.'),
('f8a848f7-55f3-47d6-81a2-3e4dfc79a1bb', 'ab5ec1e6-bc2e-478f-9d05-8c8c9a8af793', 'es', 'Elevaciones laterales con banda', 'Pisa el centro de la banda y sujeta los extremos a los lados. Eleva los brazos lateralmente hasta la altura de los hombros manteniendo una ligera flexión en los codos. Controla el descenso resistiendo la tensión de la banda. Excelente para el deltoides medio.'),
('d2875894-3a95-4688-b1e3-23a7149aadbe', 'ab74bea9-8ff1-4e26-895e-a827418b529a', 'en', 'Landmine Row', 'Landmine bar row. Allows for different angles and grips. T-bar row version is popular. The unique angle provides a different stimulus. Keep core tight to protect the lower back.'),
('a696a5ff-aae1-4297-ac95-0932b612f2ce', 'ab74bea9-8ff1-4e26-895e-a827418b529a', 'es', 'Remo landmine', 'Remo con barra en landmine. Permite diferentes ángulos y agarres. Versión en T-bar row es popular. El ángulo único proporciona un estímulo diferente. Mantén el core apretado para proteger la espalda baja.'),
('f2018f53-9537-423f-a2bf-292906263d4e', 'abe52b0d-a0d3-44b1-8806-d2e944ab335b', 'en', 'Bodyweight Bent Knee Copenhagen Plank', 'Simplified version of the Copenhagen Plank supporting the top knee on the bench instead of the foot to reduce the lever arm.'),
('ca81bad6-6ccf-4d1e-955f-22cbd2b71687', 'abe52b0d-a0d3-44b1-8806-d2e944ab335b', 'es', 'Copenhagen Plank con rodilla doblada', 'Version simplificada de la Copenhagen Plank apoyando la rodilla superior en el banco en lugar del pie para reducir el brazo de palanca.'),
('32ef9d19-2ae1-4479-a526-384fae8b7ad4', 'abe5cf82-c5c2-482c-bde5-376eaedbd0f0', 'en', 'Jumping Jacks', 'Start standing with feet together and arms at your sides. Jump opening your legs wider than shoulder-width while raising your arms above your head. Jump again to return to the starting position. Maintain a steady pace and land softly on the balls of your feet.'),
('cd61a59b-fae1-4c07-99da-dbcf73a2029a', 'abe5cf82-c5c2-482c-bde5-376eaedbd0f0', 'es', 'Jumping jacks', 'Comienza de pie con pies juntos y brazos a los lados. Salta abriendo las piernas más allá del ancho de los hombros mientras elevas los brazos por encima de la cabeza. Salta nuevamente para volver a la posición inicial. Mantén un ritmo constante y aterriza suavemente en las puntas de los pies.'),
('53a059e1-953e-488e-97aa-9135496733ae', 'abfa13e9-da19-440d-a944-bec43cd800a9', 'en', 'Straight Leg Elevation on Floor', 'Lying on your back, lift both legs together to 90 degrees and lower without touching the floor. Objective: lower abdominal. Cue: keep lower back glued to the floor. Error: arching back when lowering legs.'),
('69cfdaa4-de60-4962-a7e8-3108a94051a9', 'abfa13e9-da19-440d-a944-bec43cd800a9', 'es', 'Elevación de piernas estiradas en suelo', 'Tumbado boca arriba, eleva las piernas juntas hasta los 90 grados y baja sin tocar el suelo. Objetivo: abdominal inferior. Cue: mantén la zona lumbar pegada al suelo. Error: arquear la espalda al bajar las piernas.'),
('4aa56c81-2193-4037-8195-c6e41a0af8fd', 'ac35c27a-f91d-4b67-9697-d9862ebad9b4', 'en', 'Ring Grip Full Planche', 'Maintain a horizontal body on rings using a false or deep grip to improve torque and control of the planche position.'),
('49a54784-24b0-49ff-b828-5099c439841f', 'ac35c27a-f91d-4b67-9697-d9862ebad9b4', 'es', 'Plancha completa con agarre de Anillas', 'Manten el cuerpo horizontal en anillas utilizando un agarre falso o profundo para mejorar el torque y control de la posicion plana.'),
('50fa4153-d405-4118-ac0a-4ab56e289162', 'ac5453c9-472d-4992-a77f-ed6639406205', 'en', 'Double Kettlebell Clean to Thruster', 'Perform an explosive clean immediately followed by a deep squat and an overhead press on the way up, in one fluid motion.'),
('1497c3c7-d953-425a-8f8a-fe7c0058d194', 'ac5453c9-472d-4992-a77f-ed6639406205', 'es', 'Double Kettlebell Clean to Thruster', 'Realiza una cargada explosiva seguida inmediatamente de una sentadilla profunda y un press vertical al subir, en un solo movimiento fluido.'),
('193a46a3-4745-4252-be53-49b096f3268e', 'ac5b65d8-cebb-4f84-9a2f-e0170069de2d', 'en', 'Barbell Overhead Press', 'Standing, push the bar from the shoulders until arms are straightened above the head, keeping the core firm and without using leg drive.'),
('336c8108-f4ec-4567-9911-61a362f91f32', 'ac5b65d8-cebb-4f84-9a2f-e0170069de2d', 'es', 'Press de hombros con barra (Overhead Press)', 'De pie, empuja la barra desde los hombros hasta estirar los brazos por encima de la cabeza, manteniendo el core firme y sin impulsarte con las piernas.'),
('942b01a8-79b7-42fd-8428-3953b996adec', 'ad3dcb00-27cd-4808-9504-9222d0afade2', 'en', 'Machine Quadriceps Extension', 'Seated, extend knees against the roller. Pure quadriceps isolation. Cue: keep glute glued to the seat. Error: locking knees sharply.'),
('2b7138f5-b9de-426a-94c3-5ebbde311de3', 'ad3dcb00-27cd-4808-9504-9222d0afade2', 'es', 'Extensión de cuádriceps en máquina', 'Sentado, extiende las rodillas contra el rodillo. Aislamiento puro de cuádriceps. Cue: mantén el glúteo pegado al asiento. Error: bloquear rodillas bruscamente.'),
('7f8ba460-c09c-4050-b010-d4b6a21d55d2', 'ad7672c6-6aa4-4b3a-a0fe-75813cd8c07e', 'en', 'Superband Dead Bug', 'Perform the dead bug movement while holding an elastic band with your hands, increasing the tension on the core.'),
('d428650c-1b40-4478-b456-7c8d51f1deb2', 'ad7672c6-6aa4-4b3a-a0fe-75813cd8c07e', 'es', 'Dead Bug con banda elástica', 'Realiza el movimiento de Dead Bug mientras sujetas una banda elástica con las manos, aumentando la tensión sobre el core.'),
('2b320189-ba08-4c3b-b2f0-cecfe6a8ecb6', 'ad7d782b-aa3d-4b08-be1a-5f2881cfd392', 'en', 'Frontal Barbell Burpee', 'Perform a burpee and jump forward over a barbell. Cue: jump with both feet simultaneously. Common error: hesitating at the bar for fear of tripping.'),
('3dd0b529-d3fc-407a-a6b3-badc28f0f723', 'ad7d782b-aa3d-4b08-be1a-5f2881cfd392', 'es', 'Burpee sobre barra frontal', 'Realiza un burpee y salta hacia adelante sobre una barra. Cue: salto a dos pies simultáneos. Error común: dudar ante la barra por miedo al tropiezo.'),
('bb79b9dd-161b-428b-8b1c-3d6a0093c348', 'ad815d25-aeae-4769-be50-d1669457ae39', 'en', 'Prone Bench Hamstring Curl', 'Lying face down on a bench, flex the knees pulling the cable resistance toward the glutes.'),
('7fde54da-75bd-4806-b037-a7678b914068', 'ad815d25-aeae-4769-be50-d1669457ae39', 'es', 'Curl de isquiotibiales en banco prono', 'Tumbado boca abajo en un banco, flexiona las rodillas tirando de la resistencia del cable hacia los glúteos.'),
('b58ac602-0646-4de4-a09c-234665b4fabb', 'adf8c325-c948-40c2-b468-3f3ecc788d5c', 'en', 'Double Kettlebell Overhead Knee Over Toe Split Squat', 'Hold two kettlebells overhead and perform a split squat driving the front knee over the toes.'),
('803b94cc-eb87-4e1a-88b6-719a3de56de1', 'adf8c325-c948-40c2-b468-3f3ecc788d5c', 'es', 'Sentadilla Búlgara Overhead con Kettlebell doble rodilla sobre dedos', 'Sostén dos Kettlebells sobre la cabeza y realiza una sentadilla split llevando la rodilla delantera sobre los dedos del pie.'),
('4c73d602-4064-4e8e-b54f-75a10d71e394', 'ae16bf2a-bd23-4cce-8e1e-726c09ae9987', 'en', 'Zottman Dumbbell Curl', 'Perform a normal bicep curl (palms up) and, at the peak, rotate palms downward to descend slowly. Objective: biceps and forearms. Cue: lower the weight in a very controlled manner. Error: using body momentum to lift.'),
('cbf78a36-bb23-4d48-8790-e732cbf141a6', 'ae16bf2a-bd23-4cce-8e1e-726c09ae9987', 'es', 'Curl Zottman con mancuernas', 'Realiza un curl de bíceps normal (palmas arriba) y, en el punto máximo, gira las palmas hacia abajo para descender lentamente. Objetivo: bíceps y antebrazos. Cue: baja el peso de forma muy controlada. Error: usar el impulso del cuerpo para subir.'),
('245c8d79-0f55-4db1-a35c-9b6430d9ea03', 'ae194258-6a86-4fa3-8b6b-f53b0b8bcf65', 'en', 'Seated Box Jump', 'Sit on a bench, stand up and immediately jump onto a box. Eliminates pre-stretch to focus on pure power. Cue: full explosion when leaving the bench. Common error: hesitating on takeoff.'),
('316c868a-163a-464e-a354-0dfe5dc29ad3', 'ae194258-6a86-4fa3-8b6b-f53b0b8bcf65', 'es', 'Salto al cajón sentado', 'Siéntate en un banco, levántate y salta inmediatamente a un cajón. Elimina el pre-estiramiento para enfocar en potencia pura. Cue: explosión total al despegar del banco. Error común: dudar en el despegue.'),
('974b8a10-d077-4744-9779-ec9a0f2e2919', 'ae6553fe-1ea9-4fae-8ec4-b8d8c0cf3a31', 'en', 'Alternating Double Bottoms Up Kettlebell Cyclist Thruster', 'Perform the cyclist thruster movement with two inverted kettlebells, alternating the vertical press on each squat rise.'),
('a81d861c-1212-4c29-9f44-696992b640ce', 'ae6553fe-1ea9-4fae-8ec4-b8d8c0cf3a31', 'es', 'Thruster Ciclista alterno con Kettlebell doble Bottoms Up', 'Realiza el movimiento de thruster ciclista con dos pesas rusas invertidas, alternando el press vertical en cada subida de la sentadilla.'),
('dcfefcb6-5b50-4755-9fed-ec83520c2af4', 'af30d16b-e088-40da-84c4-541b4b705aef', 'en', 'Unilateral Cable Triceps Extension', 'Single-arm pulley extension. Objective: correct asymmetries. Cue: stable shoulder. Error: torso momentum.'),
('988438ff-bac5-4b2c-9580-0bebf972318d', 'af30d16b-e088-40da-84c4-541b4b705aef', 'es', 'Extensión tríceps polea unilateral', 'Extensión con un solo brazo en polea. Objetivo: corregir asimetrías. Cue: hombro estable. Error: impulso torso.'),
('86e56f1f-f678-43c8-9771-a2468e7da7a3', 'afa814ea-ef1d-449d-8c4c-e34c4deb84ba', 'en', 'Ring Dip to Handstand', 'Execute a ring dip and, in an explosive and fluid motion, transition into a vertical handstand position.'),
('a396d292-6f40-4424-b699-260a9b48b6bd', 'afa814ea-ef1d-449d-8c4c-e34c4deb84ba', 'es', 'Ring Dip a parada de manos', 'Ejecuta un fondo en anillas y, de forma explosiva y fluida, transiciona hasta quedar en posición vertical de parada de manos.'),
('af35c497-e08d-479a-ac42-d18c2001b92b', 'afac3a9e-39c1-4970-866b-434e4a919409', 'es', 'Peso muerto sumo con barra', 'Pies muy anchos, agarre por dentro de las piernas. Mayor énfasis en aductores y glúteo. Cue: espalda vertical. Error: dejar que las rodillas se cierren.'),
('c5dd81cc-3c0b-4d99-a4be-043573fcebfe', 'afc12594-f822-4006-852d-257fdd6a7093', 'en', 'Fitball Squat', 'Place the Fitball between your lower back and the wall. Descend into a squat while the ball rolls down your back. Provides support and proprioceptive feedback. Ideal for beginners or rehabilitation. Keep feet forward.'),
('2ff70323-ed20-4c76-b8d1-1ca8c9fd3414', 'afc12594-f822-4006-852d-257fdd6a7093', 'es', 'Sentadilla fitball', 'Coloca la fitball entre tu espalda baja y la pared. Desciende en sentadilla mientras la pelota rueda por tu espalda. Proporciona soporte y feedback propioceptivo. Ideal para principiantes o rehabilitación. Mantén los pies adelantados.'),
('7b771ba5-7279-44ad-8b71-dd0faf461af2', 'afc233fb-768c-429b-9279-78ce2dd37888', 'en', 'Seated Frontal Smith Shoulder Press', 'Seated guided military press. Cue: elbows forward. Error: arching lumbar.'),
('25a9007b-8cf0-4b84-ae29-fcb76ffec7da', 'afc233fb-768c-429b-9279-78ce2dd37888', 'es', 'Press hombros Smith frontal sentado', 'Press militar guiado sentado. Cue: codos adelantados. Error: arquear lumbar.'),
('5b37dfff-0465-4cb2-a720-cbc3f599c7c9', 'afd09ab9-fb4b-4f32-aabe-a3b428b74848', 'en', 'Wide Grip Barbell Chest Row', 'Leaning torso, very wide grip, pull toward the sternum. Cue: elbows out. Error: shrugging shoulders.'),
('392f0beb-6020-4af1-b47b-aec44239b8fc', 'afd09ab9-fb4b-4f32-aabe-a3b428b74848', 'es', 'Remo con barra agarre ancho al pecho', 'Torso inclinado, agarre muy ancho, tira hacia el esternón. Cue: codos hacia afuera. Error: encoger hombros.'),
('e100ccfe-6753-443b-b0cc-e353453fe7f9', 'aff2132a-6f25-4982-a406-b24f89fa1fa6', 'en', 'Dumbbell Lateral Raises', 'Lateral raise for middle deltoid, with strict technique and no swinging to maximize shoulder stimulus.'),
('42c8f5bf-b819-4227-a9e8-54f167a4361d', 'aff2132a-6f25-4982-a406-b24f89fa1fa6', 'es', 'Elevaciones laterales con mancuernas', 'Codos ligeramente flexionados, sube hasta línea del hombro (aprox.) sin encoger trapecio. Controla la bajada.'),
('b6f24658-b81b-43f3-badc-d65210aea88f', 'b00126cc-0d6f-4e7b-a7f7-6b3ed3999dbf', 'en', 'Single Arm Kettlebell Rotational Overhead Press', 'Press the kettlebell overhead while rotating the torso and pivoting on the foot, integrating full-body power.'),
('6bf58f68-6a18-43a6-ba23-9f32e3458dd6', 'b00126cc-0d6f-4e7b-a7f7-6b3ed3999dbf', 'es', 'Press aéreo rotacional con pesa rusa de un solo brazo', 'Presiona la Kettlebell sobre la cabeza mientras rotas el torso y pivoteas sobre el pie, integrando la potencia de todo el cuerpo.'),
('06422262-d72f-48da-9b4d-ca94e9107971', 'b0059384-31bb-47f2-8883-05abf4fef020', 'en', 'Leg Press Shrugs', 'Lift shoulders on leg press platform. Cue: straight arms. Error: bending elbows.'),
('3a6880d8-e112-481a-902c-06f41de967d9', 'b0059384-31bb-47f2-8883-05abf4fef020', 'es', 'Encogimientos hombros prensa', 'Eleva hombros en plataforma prensa. Cue: brazos rectos. Error: doblar codos.'),
('ab66df55-93c3-4ca9-a7e7-2a3e2618dce3', 'b006f9af-0012-4083-9fd6-6602cec3082d', 'en', 'Ring Side Plank', 'Perform a side plank by supporting one arm on the unstable ring, keeping the hips high and the body aligned.'),
('6ee07d85-3c52-4282-bf01-2eb1b3cde0e8', 'b006f9af-0012-4083-9fd6-6602cec3082d', 'es', 'Plank lateral en anillas', 'Realiza una plancha lateral apoyando un brazo en la anilla inestable, manteniendo la cadera alta y el cuerpo alineado.'),
('5d6347f4-017b-4906-81a7-9b965bb94158', 'b00928ef-5864-43b3-a32c-d57c87c2ef0d', 'en', 'Straight Bar Bicep Curl', 'Flex bar with palms up. Objective: bicep mass. Cue: fixed elbows. Error: moving shoulders.'),
('dd2aee53-4350-4150-b10e-1161936adf63', 'b00928ef-5864-43b3-a32c-d57c87c2ef0d', 'es', 'Curl bíceps barra recta', 'Flexiona barra con palmas arriba. Objetivo: masa bíceps. Cue: codos fijos. Error: mover hombros.'),
('398bd97c-2456-4db9-94ba-85710c4e59bf', 'b01a038c-c417-4314-8e0f-830d079bb42e', 'en', 'One-Arm Mid TRX Row', 'Hold a single TRX strap, lean your body back and pull the torso up keeping the elbow close to the ribs.'),
('8b7301a1-b78d-4bbc-8e79-2e441e9780ae', 'b01a038c-c417-4314-8e0f-830d079bb42e', 'es', 'Remo medio a una mano en TRX', 'Sostén una sola correa de TRX, inclina tu cuerpo hacia atrás y tira del torso hacia arriba manteniendo el codo cerca de las costillas.'),
('532094bb-d741-494f-8905-72abec4ee9f0', 'b0356314-8248-4be9-a448-162b97f6de4e', 'en', 'Cable Rope Half Kneeling High to Low Chop', 'Kneeling, pull the rope from a high position crossing the body toward the opposite hip, rotating the torso and keeping arms semi-straight.'),
('e72b6a44-7938-468d-b694-5c6696092a11', 'b0356314-8248-4be9-a448-162b97f6de4e', 'es', 'Woodchop alto a bajo en rodillas con cable', 'De rodillas, tira de la cuerda desde una posición alta cruzando el cuerpo hacia la cadera opuesta, rotando el torso y manteniendo los brazos semi-rectos.'),
('356021a6-b99a-4b91-9ca9-b145bf664997', 'b063235c-c00c-4f99-8688-04e884765afb', 'en', 'Double Kettlebell Bottoms Up Clean to Front Rack Squat', 'Perform a clean catching two upside-down kettlebells in the rack position while dropping into a deep squat.'),
('b1ac44cc-1653-4be8-b76f-b15ed917271c', 'b063235c-c00c-4f99-8688-04e884765afb', 'es', 'Squat Clean Front Rack con Kettlebell doble Bottoms Up', 'Realiza una cargada recibiendo dos Kettlebells invertidas en posicion rack mientras bajas a una sentadilla profunda.'),
('9a799fbd-d540-45e6-b718-17081af434ed', 'b0b9ae59-54b3-4e3a-8cc6-94415304ac58', 'en', 'Dumbbell Pendlay Row', 'With the torso parallel to the floor, row dumbbells from the floor (dead stop) to the torso on each rep.'),
('8a0684bf-536b-4b46-bdc5-2de7ccf9c631', 'b0b9ae59-54b3-4e3a-8cc6-94415304ac58', 'es', 'Remo Pendlay con mancuernas', 'Con el torso paralelo al suelo, rema las mancuernas desde el suelo (pausa muerta) hasta el torso en cada repetición.'),
('cc474ad6-5600-4ade-b65b-7c5febc1591e', 'b13c0209-559d-4e70-bfb5-d34a93e9e8f7', 'en', 'Ring Hanging Oblique Knee Raise', 'Hang from the rings. Lift your knees toward one side of the chest, rotating the hip to activate the obliques. Alternate sides on each repetition.'),
('44a10fe3-be01-44ab-ae2b-8c7e9647bcd0', 'b13c0209-559d-4e70-bfb5-d34a93e9e8f7', 'es', 'Elevación de rodilla oblicua colgado en anillas', 'Cuélgate de las anillas. Levanta las rodillas hacia un lado del pecho, girando la cadera para activar los oblicuos. Alterna los lados en cada repetición.'),
('945bf23d-b7ae-4b2f-816c-d804550c0849', 'b13dce93-0ed4-4294-b88d-ab25a803a6be', 'en', 'Double Kettlebell Outside Swing', 'Swing two kettlebells outside your legs, requiring a narrower stance and great control over the arms path.'),
('6a33c76d-4c12-434e-8e6b-9ab11fc703cf', 'b13dce93-0ed4-4294-b88d-ab25a803a6be', 'es', 'Swing exterior con Kettlebell doble', 'Balancea dos pesas rusas por fuera de las piernas, requiriendo una postura mas estrecha y un gran control de la trayectoria de los brazos.'),
('4cfdb5b9-340c-4225-b209-a881fdf53a27', 'b155a5e0-bbc1-47f1-ada2-3e198feb7ba7', 'en', 'Explosive Band Lateral Lunge', 'Perform lateral lunges resisted by a band, seeking a powerful jump to the center. Cue: resist the lateral pull of the band. Common error: the band making you lose balance when jumping.'),
('9e56f2cf-6604-4db8-a8f8-068020d2abbf', 'b155a5e0-bbc1-47f1-ada2-3e198feb7ba7', 'es', 'Zancada lateral explosiva banda', 'Realiza zancadas laterales resistidas por banda, buscando un salto potente al centro. Cue: resiste el tirón lateral de la banda. Error común: que la banda te desequilibre al saltar.'),
('b4f0cb58-e780-4d9e-9e36-ff1f502f0743', 'b166f733-60d1-49b2-9464-7ef72559a9fb', 'es', 'Zancada caminando Overhead con mancuernas', 'Camina realizando zancadas mientras sostienes dos mancuernas bloqueadas sobre la cabeza, exigiendo estabilidad en hombros y core.'),
('115bb602-36fa-4b6d-8a37-90bd9bffdceb', 'b182b147-302d-4248-b0ea-af4444767c90', 'en', 'One-Arm Cable Shotgun Row', 'In a lunge position, row with the cable from below while slightly rotating the torso, as if loading a shotgun.'),
('fa6f3ec7-4b67-4696-aa2a-f583de43a1f4', 'b182b147-302d-4248-b0ea-af4444767c90', 'es', 'Remo Shotgun a una mano con cable', 'En posición de zancada, rema con el cable desde abajo mientras rotas ligeramente el torso, como si cargaras una escopeta.'),
('87679519-4a6f-4a5d-9dc0-2ef4aafd6bd7', 'b1b06547-d549-45b5-a2e5-ada20e1be2b9', 'en', 'Straight-Arm Dumbbell Pullover', 'Perform a straight-arm dumbbell pullover while keeping the elbows almost locked. Move the dumbbell behind the head under control and return by engaging the lats and chest.'),
('b7a58e4d-462e-4b62-8196-553604779769', 'b1b06547-d549-45b5-a2e5-ada20e1be2b9', 'es', 'Pull over con mancuerna codos bloqueados', 'Realiza un pull over con mancuerna manteniendo los codos casi bloqueados. Lleva la mancuerna por detrás de la cabeza de forma controlada y vuelve activando dorsal y pecho.'),
('964221f2-287b-4bd4-8fa3-af442635e17b', 'b1cf23f5-4728-49b9-a370-244aa92051ec', 'en', 'Double Kettlebell Hollow Body Hold', 'Maintain the hollow body position while holding a kettlebell in each hand, either against the chest or with extended arms, increasing intensity.'),
('0756dae2-d5c6-4140-8511-23c50fff5fc6', 'b1cf23f5-4728-49b9-a370-244aa92051ec', 'es', 'Hollow Body Hold con Kettlebell doble', 'Mantén la posición de Hollow Body sosteniendo una Kettlebell en cada mano, ya sea contra el pecho o con brazos extendidos, aumentando la intensidad.'),
('02054aeb-b4a7-41dd-a972-1b1cabcbc00f', 'b1ebab9f-5c46-4daf-8694-af7a3a8bcb7f', 'en', 'Dumbbell Walking Lunges', 'Perform dumbbell walking lunges. Take long controlled steps, lower to a comfortable depth, and push through the front leg to move forward.'),
('085f0888-52a9-4620-8eda-a973095f8676', 'b1ebab9f-5c46-4daf-8694-af7a3a8bcb7f', 'es', 'Zancadas caminando con mancuernas', 'Realiza zancadas caminando con mancuernas. Da pasos largos y controlados, baja hasta una profundidad cómoda y empuja con la pierna delantera para avanzar.'),
('026a46cd-8aa9-4b88-a595-81026e332f10', 'b21e300a-a049-46c2-a05e-f2b34ae06910', 'en', 'Machine Hack Squat', 'Squat supported on an inclined platform. Cue: feet at mid-height, go deep. Error: locking knees when rising.'),
('ef181037-d386-4d34-8269-636e45a02f48', 'b21e300a-a049-46c2-a05e-f2b34ae06910', 'es', 'Sentadilla Hack en máquina', 'Sentadilla apoyado en plataforma inclinada. Cue: pies a media altura, baja profundo. Error: bloquear rodillas al subir.'),
('b88c091a-e9ba-4d3d-bd36-a6b14ba25a0b', 'b2279338-89c0-497e-a410-1e0aaec994c5', 'en', 'Bodyweight Bent Arm Press Handstand', 'From a tripod or tuck position, press your body into a vertical handstand while keeping your arms bent at the start.'),
('cad9fbfa-c6fd-4572-bbb7-b6013e119887', 'b2279338-89c0-497e-a410-1e0aaec994c5', 'es', 'Bent Arm Press Handstand', 'Desde una posición de trípode o tuck, empuja el cuerpo hasta quedar en parada de manos vertical manteniendo los brazos flexionados al inicio.'),
('9590f26c-f70c-43cc-b36e-15e1c47ccaaa', 'b239667d-5739-4f7f-9051-d96d56fc3131', 'en', 'Seated Fitball Adductor', 'Squeeze the fitball between your knees while seated. Objective: adductors. Cue: squeeze for 2 sec. Error: curved back.'),
('87df1617-d23a-4ff3-8bd1-48f977babef5', 'b239667d-5739-4f7f-9051-d96d56fc3131', 'es', 'Aductor fitball sentado', 'Aprieta fitball entre rodillas sentado. Objetivo: aductores. Cue: aprieta 2 seg. Error: espalda curva.'),
('a9fb6eed-f6e2-48e6-8955-5d34ac7b26f8', 'b27a3a64-8c04-4206-bed6-8f275cb41415', 'en', 'Standing Barbell Military Press', 'Push bar overhead without leg drive. Cue: glutes squeezed. Error: arching back.'),
('0bf3d282-8af0-4d32-b30b-bde860bf9de6', 'b27a3a64-8c04-4206-bed6-8f275cb41415', 'es', 'Press militar con barra de pie', 'Empuja barra sobre cabeza sin impulso de piernas. Cue: glúteos apretados. Error: arquear espalda.'),
('fa52756a-2471-40e3-bc08-53cf4a368843', 'b2930805-b797-43dd-a013-7aa9c2e5c30d', 'en', 'Single Arm Kettlebell Bottoms Up Turkish Get Up', 'Perform the complete Turkish Get Up while maintaining an upside-down kettlebell overhead, requiring total stability control.'),
('72bc2cc7-ce1a-4c7e-8371-73eb4b1a343c', 'b2930805-b797-43dd-a013-7aa9c2e5c30d', 'es', 'Turkish Get Up con Kettlebell a una mano Bottoms Up', 'Realiza el levantamiento turco completo manteniendo la Kettlebell invertida sobre la cabeza, requiriendo un control de estabilidad total.'),
('8303511e-2803-4278-ba50-9a4032fc801c', 'b2a37538-fd04-4429-b06e-9bdbf3ae689f', 'en', 'Unilateral Low Pulley Row', 'Seated row with a single arm. Focus on lats. Straight back. Do not rotate the trunk when stretching.'),
('168e9748-e1ed-430b-97de-3c7c9f13a2af', 'b2a37538-fd04-4429-b06e-9bdbf3ae689f', 'es', 'Remo bajo unilateral en polea', 'Remo sentado con un solo brazo. Enfoque en dorsal. Espalda recta. No rotes el tronco al estirar.'),
('895ed01a-2800-4c33-8cea-b9db86f7f864', 'b2e59bfb-e463-4eb3-a8a6-33dea036ecc0', 'en', 'Hefesto', 'From hanging on the bar, perform an inverted pull-up bringing the body behind the bar until you are in support. Extremely advanced movement that combines pulling strength with complex transition. Requires shoulder mobility.'),
('6b423692-fac3-4bd4-afe9-141ca12f79cd', 'b2e59bfb-e463-4eb3-a8a6-33dea036ecc0', 'es', 'Hefesto', 'Desde colgado en barra, realiza una dominada invertida llevando el cuerpo por detrás de la barra hasta quedar en apoyo. Movimiento extremadamente avanzado que combina fuerza de tracción con transición compleja. Requiere movilidad de hombros.'),
('272b20aa-09b9-40ff-ba01-416d5aabf95e', 'b2ed93e0-5764-4a65-b970-325190842424', 'en', 'Dumbbell Floor Press', 'Floor press with dumbbells. Objective: chest and triceps. Cue: lower back supported. Error: lifting the back.'),
('7794b2a9-a3bc-4a97-a78a-da27b7902e67', 'b2ed93e0-5764-4a65-b970-325190842424', 'es', 'Floor Press mancuernas', 'Press en suelo con mancuernas. Objetivo: pecho y tríceps. Cue: lumbar apoyada. Error: despegar espalda.'),
('332bf059-e28a-4553-853d-0a641a8680cc', 'b2f60df6-167a-4a77-b742-5e8504073640', 'en', 'Single Arm Landmine Z Press', 'Seated on the floor without support, press the landmine bar overhead, which eliminates leg drive and isolates the shoulder.'),
('a898f9bd-41ec-4f9e-80fb-0c4e39a9fdd3', 'b2f60df6-167a-4a77-b742-5e8504073640', 'es', 'Press Z para minas terrestres de un solo brazo', 'Sentado en el suelo sin apoyo, presiona la barra Landmine sobre la cabeza, lo que elimina el impulso de las piernas y aisla el hombro.'),
('7ee7ccb3-3001-4472-9be2-a2a0d1237094', 'b2fc76e9-c1a4-4f30-b640-1b640712dbe0', 'en', 'Overhead Cable Triceps Extension', 'Back to the low pulley, hold the rope overhead with elbows pointing forward. Extend the elbows keeping the upper arms motionless. This position emphasizes the long head of the triceps and provides a maximum stretch.'),
('90a7c762-9e2f-492a-ba5d-050ffd2bd359', 'b2fc76e9-c1a4-4f30-b640-1b640712dbe0', 'es', 'Extensión tríceps sobre cabeza cable', 'De espaldas a la polea baja, sostén la cuerda sobre la cabeza con los codos apuntando hacia adelante. Extiende los codos manteniendo los brazos superiores inmóviles. Esta posición enfatiza la cabeza larga del tríceps y proporciona un estiramiento máximo.'),
('af1e2aab-8608-48ee-bcab-1056e342c40e', 'b31aba5f-6d65-4cdd-9e3b-69b8c29825e4', 'en', 'Seated Barbell Shoulder Press', 'Push bar overhead while seated. Objective: deltoid strength. Cue: firm core. Error: arching lumbar.'),
('83313af5-3f8c-4dd6-b67d-6007a5b36feb', 'b31aba5f-6d65-4cdd-9e3b-69b8c29825e4', 'es', 'Press hombros sentado barra', 'Empuja barra sobre cabeza sentado. Objetivo: fuerza deltoides. Cue: core firme. Error: arquear lumbar.'),
('6245820e-85bc-4666-b161-4069eb09b755', 'b34a008a-5e98-4908-9b48-b2b7cb519669', 'en', 'Strict Calf Raises', 'Raise the heels seeking maximum height. Calf strength. Straight knees. Do not swing forward.'),
('27748182-68b6-4660-9ea1-23b850c88dcd', 'b34a008a-5e98-4908-9b48-b2b7cb519669', 'es', 'Elevación de talones estricta', 'Eleva los talones buscando máxima altura. Fuerza de gemelos. Rodillas estiradas. No te balancees adelante.'),
('e60304df-2753-4873-929b-cffce5438ad1', 'b3b9861b-6254-4954-8e92-15f194e90834', 'en', 'Overhead Cable Rope Triceps Extension', 'Back to the pulley, hold the rope overhead. Extend arms forward and up, separating the ends of the rope at the finish.'),
('706cff0f-b12f-4cd0-94ec-00ffcd074ea9', 'b3b9861b-6254-4954-8e92-15f194e90834', 'es', 'Extensión de tríceps Overhead con cuerda en polea', 'De espaldas a la polea, sostén la cuerda sobre la cabeza. Extiende los brazos hacia adelante y arriba, separando los extremos de la cuerda al final.'),
('3aa49e2c-d1db-437a-9890-b19ba569b0f7', 'b3c9e725-8804-490b-864e-5450902e1565', 'en', 'Single Arm Kettlebell Snatch', 'Drive the kettlebell from the floor to overhead in a single explosive movement, locking the arm out at the top.'),
('c21f83f9-4e50-4fe7-8580-89ce92e163ea', 'b3c9e725-8804-490b-864e-5450902e1565', 'es', 'Snatch con Kettlebell a una mano', 'Lleva la Kettlebell desde el suelo hasta por encima de la cabeza en un solo movimiento explosivo, bloqueando el brazo en el tope.'),
('e807da51-7b00-48f4-baa8-b480df329c7f', 'b3dc82d2-66cd-437b-902d-3625a787908e', 'en', 'Supinated Inverted Row', 'Low bar row with palms toward you. Objective: back/biceps. Cue: body like a board. Error: sinking the hip.'),
('6eafa7b1-6deb-4c3f-a8cf-61ae07af1a66', 'b3dc82d2-66cd-437b-902d-3625a787908e', 'es', 'Remo invertido supinado', 'Remo en barra baja palmas hacia ti. Objetivo: espalda/bíceps. Cue: cuerpo tabla. Error: hundir cadera.'),
('4941e518-f915-40c4-9cbf-527e82640cf8', 'b3e12dc1-301b-46b1-b2b8-860ceb706e30', 'es', 'Press Overhead sentado agarre inverso con barra Z', 'Sentado con apoyo lumbar, realiza un press de hombros con agarre supino en barra Z, manteniendo los codos hacia adelante.'),
('1cde60d3-4480-4975-ad5f-7851a05a620e', 'b3fa7877-7540-4c22-9469-a3652178c611', 'en', 'Kettlebell Clean and Press', 'Bring the weight to the shoulder (clean) and then lift it (press). Fluid movement. Straight back. Do not arch the back when pushing.'),
('eede4c6a-1e68-49a5-83ae-09c31a59cc7d', 'b3fa7877-7540-4c22-9469-a3652178c611', 'es', 'Kettlebell Clean and Press', 'Lleva la pesa al hombro (clean) y luego elévala (press). Movimiento fluido. Espalda recta. No arquees la espalda al empujar.'),
('b9d19bc5-413d-4702-a9d8-30b0ab6d4caf', 'b400cdb3-5123-4eae-852a-9968dbe90c73', 'en', 'Band Good Morning', 'Step on the band and place the other end behind the neck over the trapezius. With knees slightly flexed, lean forward from the hips keeping the back straight. Return up by contracting glutes and hamstrings against resistance.'),
('90e1376e-bbd3-46b1-90ec-121a95b55ef7', 'b400cdb3-5123-4eae-852a-9968dbe90c73', 'es', 'Good morning con banda', 'Pisa la banda y coloca el otro extremo detrás del cuello sobre los trapecios. Con las rodillas ligeramente flexionadas, inclínate hacia adelante desde las caderas manteniendo la espalda recta. Vuelve a la posición inicial contrayendo glúteos e isquiotibiales contra la resistencia.'),
('031d4fdd-d09f-49ff-b693-5974ec65143e', 'b434af88-04ff-4688-8bda-c7a79cd02cf5', 'en', 'Dumbbell Frog Pump', 'In a lying butterfly position (feet together), place a dumbbell on the pelvis and raise hips activating the glutes.'),
('78548248-a07a-443e-9721-ccf441fdc7a5', 'b434af88-04ff-4688-8bda-c7a79cd02cf5', 'es', 'Frog Pump con mancuerna', 'En posición de mariposa tumbado (pies juntos), coloca una mancuerna sobre la pelvis y eleva las caderas activando los glúteos.'),
('0783c9cd-23c5-435e-9a47-013bfa81bc84', 'b474e56f-abf3-44ce-8cf8-60bd5713e208', 'en', 'Single Leg Out Back Lever on Rings', 'Execute a back lever with one leg extended and the other tucked toward the chest, alternating to gain symmetrical strength.'),
('ab5d23f0-2da1-4c95-9916-26856a3fc745', 'b474e56f-abf3-44ce-8cf8-60bd5713e208', 'es', 'Single Leg Out Back Lever en anillas', 'Ejecuta un back lever con una pierna estirada y la otra encogida hacia el pecho, alternando para ganar fuerza simetrica.'),
('7d4dec27-69d8-4262-9a78-65ca452082ca', 'b47728ba-9026-46e4-a4a8-e4a704fbe955', 'en', 'Front Mace Flag Press', 'Hold the mace vertically in front of you and press forward extending the arms, resisting the weight''s leverage.'),
('ad2c5476-7816-4e33-83b1-fb7ceb7c5f63', 'b47728ba-9026-46e4-a4a8-e4a704fbe955', 'es', 'Press de bandera frontal con maza', 'Sostén la maza verticalmente frente a ti y presiona hacia adelante extendiendo los brazos, resistiendo la palanca del peso.'),
('f528a4f1-2b41-4105-9906-c55aaa053cb8', 'b47e4bb9-62f5-4796-a0c0-20dbdfca0139', 'en', 'Fitball Push Ups', 'Push-ups with hands on Fitball or feet elevated on it. Instability requires greater stabilizer activation. With hands on ball, works core more; with feet, emphasizes upper pectoral. Control the movement.'),
('a0c9a0fd-2599-4498-a315-bc83768a02de', 'b47e4bb9-62f5-4796-a0c0-20dbdfca0139', 'es', 'Flexiones fitball', 'Flexiones con manos sobre la fitball o pies elevados en ella. La inestabilidad requiere mayor activación de estabilizadores. Con manos en la pelota trabajas más el core, con pies enfatizas pectoral superior. Controla el movimiento.'),
('5dcf255f-8247-4b20-8dfc-6dc59fdd9cb3', 'b47f3ccd-569a-4df0-962d-ed0021e6e67a', 'en', 'Barbell Cyclist Thruster', 'With heels elevated, perform a deep squat and use the explosive ascent to perform an overhead military press in a single motion.'),
('9763c705-8dc4-408c-9350-e9cd54874556', 'b47f3ccd-569a-4df0-962d-ed0021e6e67a', 'es', 'Thruster Ciclista con barra', 'Con talones elevados, realiza una sentadilla profunda y aprovecha la subida explosiva para realizar un press militar sobre la cabeza en un solo movimiento.'),
('db8b8c90-72d9-4723-bda1-13b95450e576', 'b4b11683-d20a-4f4a-8ed8-5468bc8c4f10', 'en', 'TRX Shoulder Press', 'In a pike position (inverted V) with hands in the straps, perform vertical presses. Similar to pike push-ups but with the added instability of the TRX. Excellent for developing shoulder strength and stability.'),
('faaab8fe-cf14-41ce-9137-cce60e79b5f7', 'b4b11683-d20a-4f4a-8ed8-5468bc8c4f10', 'es', 'Press hombros TRX', 'En posición de pike (V invertida) con manos en las correas, realiza press verticales. Similar a flexiones pike pero con la inestabilidad añadida del TRX. Excelente para desarrollar fuerza en hombros y estabilidad.'),
('729c76af-8334-447e-8954-85317e2019ce', 'b4be2f53-14fd-46ad-ad5d-e5c7a8bc70af', 'en', 'Double Kettlebell Bottoms Up Front Rack Pistol Squat', 'Single-leg squat with upside-down kettlebells in front rack, requiring absolute motor control to prevent the weights from falling.'),
('0e8242a1-c450-4b60-8540-39ee3ceae392', 'b4be2f53-14fd-46ad-ad5d-e5c7a8bc70af', 'es', 'Sentadilla con pistola doble con pesa rusa, de abajo hacia arriba y con rejilla frontal', 'Sentadilla a una pierna con Kettlebells invertidas en rack frontal, requiriendo un control motor absoluto para evitar la caida del peso.'),
('551ed0e3-7f52-40f3-95b3-0ff82dc39ffc', 'b4bfcd1f-732d-486a-b430-f88c5dfa9d6d', 'en', 'Free Squat', 'Place feet at shoulder width with toes slightly outward. Descend by flexing knees and hips simultaneously, keeping the back straight and chest high. Lower until thighs are parallel to the floor or according to your flexibility. Push through the heels to return to the starting position.'),
('9d88df7e-8053-4863-9bcf-eee62a685710', 'b4bfcd1f-732d-486a-b430-f88c5dfa9d6d', 'es', 'Sentadilla libre', 'Coloca los pies al ancho de los hombros con las puntas ligeramente hacia afuera. Desciende flexionando rodillas y caderas simultáneamente, manteniendo la espalda recta y el pecho erguido. Baja hasta que los muslos estén paralelos al suelo o según tu flexibilidad. Empuja con los talones para volver a la posición inicial.'),
('77fa17c9-8693-4950-a6b8-4b0daf2a058f', 'b4eaf17f-39c6-44d3-8a71-2ac8fb283c33', 'en', 'Alternating Hammer Curl', 'Flex one dumbbell at a time with a neutral grip (palms facing each other). Objective: brachialis and brachioradialis. Cue: keep the elbow fixed at the side. Common error: rotating the wrist during the movement.'),
('f4a78e73-8dfa-4868-a9e5-8219b2827b56', 'b4eaf17f-39c6-44d3-8a71-2ac8fb283c33', 'es', 'Curl martillo alterno', 'Flexiona una mancuerna a la vez con agarre neutro (palmas enfrentadas). Objetivo: braquial y braquiorradial. Cue: mantén el codo fijo al costado. Error común: rotar la muñeca durante el movimiento.'),
('b2fd0ce8-7553-437b-bdb4-d67d138861e8', 'b5058ca6-f9cc-4f74-8f5f-9e9d2c7be060', 'en', 'TRX Chest Flyes', 'Leaning forward, open arms laterally with a slight elbow bend and close. Total control. Body as a unit. Do not let the pelvis drop.'),
('5a718ab3-b5a8-4df6-9b35-f632e56f5ea2', 'b5058ca6-f9cc-4f74-8f5f-9e9d2c7be060', 'es', 'TRX Aperturas de pecho', 'Inclinado hacia adelante, abre los brazos lateralmente con ligera flexión de codo y cierra. Control total. Cuerpo en bloque. No dejes caer la pelvis.'),
('f96f12b0-5e35-47d9-8a96-5384d08b3440', 'b512551f-c998-40fe-8889-617b4f582f64', 'en', 'Seated Cable Bicep Curl', 'Sit in front of a low pulley with a short bar. Support elbows on knees or keep them fixed at sides and perform the curl.'),
('cef12456-542f-4951-9d3c-dbc6fa07535f', 'b512551f-c998-40fe-8889-617b4f582f64', 'es', 'Curl de bíceps sentado con cable', 'Siéntate frente a una polea baja con una barra corta. Apoya los codos en las rodillas o mantenlos fijos a los lados y realiza el curl.'),
('29b8ff82-cb93-4f2f-8e5c-b97c50f5e2ca', 'b525fca2-0d56-4363-acf9-25dc79eea17b', 'es', 'TRX Y-Fly', 'Eleva brazos en Y inclinado atrás. Objetivo: deltoide posterior. Cues: brazos rectos. Error común: encoger hombros.'),
('a5b1446f-f213-47ff-ae8d-1b54f18e30d3', 'b568d66b-b81d-46bb-a191-dfd7b7d2c5a0', 'en', 'TRX Jump Squat', 'Holding the straps, perform jump squats. The TRX provides stability and allows you to adjust the jump intensity. Land softly and use the straps to maintain balance and correct posture.'),
('40ad42ab-b5ca-4bc8-b68d-3aab11922523', 'b568d66b-b81d-46bb-a191-dfd7b7d2c5a0', 'es', 'Jump squat TRX', 'Sujetando las correas, realiza sentadillas con salto. El TRX proporciona estabilidad y permite ajustar la intensidad del salto. Aterriza suavemente y usa las correas para mantener el equilibrio y la postura correcta.'),
('8f16e6b9-ccd9-4ce7-9343-429f3f920e73', 'b5b99869-3db7-45da-a522-11360e11ac10', 'en', 'Macebell Reverse Grip Offset Bicep Curl', 'Hold the mace with palms down asymmetrically and perform the curl to work forearms and biceps.'),
('fe323092-2168-4b04-b6cb-3edfde6d21c6', 'b5b99869-3db7-45da-a522-11360e11ac10', 'es', 'Curl de bíceps offset agarre inverso con maza', 'Sujeta la maza con las palmas hacia abajo de forma asimétrica y realiza el curl para trabajar antebrazos y bíceps.'),
('2cc5bcbe-d90b-4f99-a4f0-e018c24bce19', 'b5c9b192-96f8-48e2-93d8-81015276d04b', 'en', 'Pallof Press', 'Perform a Pallof press with a cable or band. From a sideways position to the anchor point, press the hands forward and resist trunk rotation throughout the movement.'),
('1c3c12f1-c75e-4533-9dd2-985c637b9bb7', 'b5c9b192-96f8-48e2-93d8-81015276d04b', 'es', 'Pallof press', 'Realiza un Pallof press con cable o banda. Desde una posición lateral al punto de anclaje, empuja las manos al frente y resiste la rotación del tronco durante todo el movimiento.'),
('3db0a53e-4269-4073-9794-98747c4691d4', 'b5d2f448-a0c9-4ae2-8c3e-4c17a07df9f3', 'en', 'Battle Ropes Side Plank Waves', 'In a side plank, move the rope with the free hand. Extreme core stability. Straight body. Do not let the hip sag to the floor.'),
('ea808ef4-8ec6-4dd5-8b2a-0a41e8822397', 'b5d2f448-a0c9-4ae2-8c3e-4c17a07df9f3', 'es', 'Battle Ropes Ondas en plancha lateral', 'En plancha lateral, mueve la cuerda con la mano libre. Estabilidad de core extrema. Cuerpo recto. No dejes caer la cadera al suelo.'),
('0136ab27-3cac-436c-83ed-aca32fb8ca89', 'b5d92170-717d-4f51-8e87-c2d807b1475e', 'en', 'Double Kettlebell High Pull', 'From the floor, pull two kettlebells upward using an explosive hip extension until the elbows are high.'),
('17af86c5-2ddd-4230-b64f-69edb7cc880e', 'b5d92170-717d-4f51-8e87-c2d807b1475e', 'es', 'High Pull con Kettlebell doble', 'Desde el suelo, tira de dos Kettlebells hacia arriba mediante una extension explosiva de cadera hasta que los codos queden altos.'),
('235e7357-d969-460f-95fe-686fef2b1bbe', 'b5ea9a9a-bf43-4fc8-8fab-89da72b05b03', 'en', 'TRX Bicep Curl', 'Leaned back with arms extended, perform curls bringing hands toward the forehead. Keep elbows elevated and fixed. TRX instability adds a stabilization component to the traditional exercise.'),
('af2e260a-67b8-445c-8fc4-f606f392c217', 'b5ea9a9a-bf43-4fc8-8fab-89da72b05b03', 'es', 'Curl bíceps TRX', 'Inclinado hacia atrás con brazos extendidos, realiza curls llevando las manos hacia la frente. Mantén los codos elevados y fijos. La inestabilidad del TRX añade un componente de estabilización al ejercicio tradicional.'),
('1e58a76c-61ab-4519-8e33-202a55be09aa', 'b6166551-06ac-446d-9260-fd85383071ed', 'es', 'Wall sit', 'Apoya la espalda contra una pared y deslízate hacia abajo hasta que los muslos estén paralelos al suelo, formando un ángulo de 90 grados en las rodillas. Mantén esta posición isométrica con el peso en los talones. Los brazos pueden estar cruzados o extendidos al frente. Excelente para resistencia muscular.'),
('dc7e4e6d-c19f-4414-879d-ba2b5a18308d', 'b622b2b3-3b5b-4885-ba3c-040d42260024', 'es', 'Power Snatch con barra', 'Lleva la barra desde el suelo hasta por encima de la cabeza con brazos extendidos en un solo movimiento explosivo, recibiéndola en media sentadilla.'),
('d7ba9542-c17f-41b7-9eae-2d6d188e4bfe', 'b62c171d-11bb-47c1-80b2-c2a51c1d133c', 'en', 'One-Arm Kettlebell Bent Over Row', 'Support one hand and knee on a bench. With a flat back, row the kettlebell toward the hip keeping the elbow close to the body.'),
('1a4e193d-38d2-4ba7-91e2-b33088b543df', 'b62c171d-11bb-47c1-80b2-c2a51c1d133c', 'es', 'Remo inclinado a una mano con Kettlebell', 'Apoya una mano y rodilla en un banco. Con la espalda plana, rema la pesa rusa hacia la cadera manteniendo el codo cerca del cuerpo.'),
('b5415b2f-86b2-4f9f-8e4d-f80aca25c9bf', 'b6398c46-1c48-43c8-b05a-c10102289bce', 'en', 'Parallette Full Planche Push Up', 'Perform a push-up while maintaining the body fully horizontal and parallel to the floor, supported only by the hands.'),
('ba78ac54-2d67-4682-9895-734d3dbefd3d', 'b6398c46-1c48-43c8-b05a-c10102289bce', 'es', 'Push Up en plancha completa en paralelas', 'Realiza una flexion de brazos manteniendo el cuerpo totalmente horizontal y paralelo al suelo, apoyado solo en las manos.'),
('df87d681-bb3d-4ab8-9e6a-638c9d28e4ac', 'b657da31-e10a-42e9-bce9-245317b6f8da', 'en', 'Upper Cable Crossovers', 'With pulleys in a high position, perform the crossover by bringing hands down and toward the center. This variation emphasizes the lower portion of the pectoral. Keep the torso slightly leaned forward for better stability.'),
('1b59e894-c6d1-47a3-a97d-728d87d8203f', 'b657da31-e10a-42e9-bce9-245317b6f8da', 'es', 'Cruces superiores cable', 'Con las poleas en posición alta, realiza el cruce llevando las manos hacia abajo y al centro. Esta variación enfatiza la porción inferior del pectoral. Mantén el torso ligeramente inclinado hacia adelante para mejor estabilidad.'),
('6ab790d4-7ffe-4c0a-ac3d-ca08a2aecb3d', 'b65ec17c-8df4-4eaf-83f2-8df6e4b6106a', 'en', 'Flutter Kicks', 'Small up and down leg movements a few cm from the floor. Cue: hands under glutes for support. Error: arching lumbar.'),
('5218a010-5884-4e70-8527-b7d0129c94de', 'b65ec17c-8df4-4eaf-83f2-8df6e4b6106a', 'es', 'Flutter Kicks', 'Pequeños movimientos arriba y abajo de piernas a pocos cm del suelo. Cue: manos bajo el glúteo para apoyo. Error: arquear lumbar.'),
('1016a31a-6d94-454b-89f8-abb80fdf5e58', 'b692df19-5525-4d64-9abf-4c668d3ed302', 'en', 'Lateral Bounds', 'Jump laterally from one leg to the other seeking maximum distance and stability. Objective: lateral power. Cue: nail the landing with knee aligned. Common error: letting the knee cave inward.'),
('097be7c7-f173-4879-b742-2ba44cad5c65', 'b692df19-5525-4d64-9abf-4c668d3ed302', 'es', 'Saltos laterales (Lateral bounds)', 'Salta lateralmente de una pierna a la otra buscando máxima distancia y estabilidad. Objetivo: potencia lateral. Cue: clava el aterrizaje con la rodilla alineada. Error común: dejar que la rodilla se hunda hacia adentro.'),
('2d628f78-2782-4f4d-90d0-27440a04ddf9', 'b6c82820-f0df-42f9-9634-8b5c0dbfba2a', 'en', 'Single Arm Kettlebell Sots Press', 'Perform a full shoulder press while staying in the deepest position of a squat, requiring extreme mobility.'),
('48fc28d1-e6d6-4ec6-a236-0c122abc8c9f', 'b6c82820-f0df-42f9-9634-8b5c0dbfba2a', 'es', 'Press Sots con pesa rusa de un solo brazo', 'Realiza un press de hombros completo mientras te mantienes en la posicion mas profunda de una sentadilla, exigiendo movilidad extrema.'),
('426cffcb-2a90-411c-9f56-6a0b27ebb136', 'b6e615a4-af8d-43af-b15b-c278c3d65a38', 'en', 'Strict bear crawl', 'Crawl on all fours with knees millimeters from the ground. Objective: total core stability. Cue: back flat as a table. Common error: raising hips upward.'),
('ca2f1288-1422-4902-8ed2-33f5234b26c1', 'b6e615a4-af8d-43af-b15b-c278c3d65a38', 'es', 'Caminata de oso estricta', 'Desplázate a cuatro patas con las rodillas a milímetros del suelo. Objetivo: estabilidad total del core. Cue: espalda plana como una mesa. Error común: elevar la cadera hacia arriba.'),
('c7c3bcc4-cde0-484f-8c02-16812c94e54d', 'b70bc7cb-e725-44bf-8ce7-0a0c7ba28ef1', 'en', 'Kettlebell Sumo Deadlift', 'With a wide foot stance, hold the kettlebell with both hands and lift it by extending hips and knees with a neutral back.'),
('f7c2e9eb-16a2-437e-a173-40aed765c2a7', 'b70bc7cb-e725-44bf-8ce7-0a0c7ba28ef1', 'es', 'Peso muerto Sumo con Kettlebell', 'Con una apertura de pies ancha, sujeta la Kettlebell con ambas manos y levántala extendiendo cadera y rodillas con la espalda neutra.'),
('2c0750c0-627f-47d4-a68e-9682048d7828', 'b728b144-8a3b-41d2-b39b-493b1a2ff46f', 'en', 'Stepped Band Shoulder Press', 'Push the band overhead. Cue: arms fully straightened. Error: arching the back.'),
('e85578f2-66fa-4cca-96a2-0e5fb936f572', 'b728b144-8a3b-41d2-b39b-493b1a2ff46f', 'es', 'Press hombros con banda pisada', 'Empuja la banda sobre la cabeza. Cue: brazos totalmente estirados. Error: arquear la espalda.'),
('6f9ea7ab-1c0b-4f41-87a1-a6df81ad271d', 'b782aed9-e0c6-446d-a203-4df54c19addc', 'en', 'Low Block Deadlift', 'Bar elevated 10-15cm from floor. Focuses on the middle phase of the pull. Cue: neutral back. Error: rounding the upper back.'),
('859af8ac-526b-4ff4-ba8b-b781f5c3620f', 'b782aed9-e0c6-446d-a203-4df54c19addc', 'es', 'Peso muerto desde bloques bajos', 'Barra elevada 10-15cm del suelo. Enfoca en la fase media del tirón. Cue: espalda neutra. Error: redondear la espalda alta.'),
('e3a6a25c-a1c0-4505-a598-64c223c9be8c', 'b786aa4f-e65e-4c83-a038-cf53174b3606', 'en', 'Medicine Ball Slam Burpee', 'Full burpee ending with a slam ball. One of the most metabolically demanding exercises. Maintain technique despite fatigue. The slam must be explosive even when tired.'),
('dca5971c-74df-4017-8e83-35f0f4cef7cc', 'b786aa4f-e65e-4c83-a038-cf53174b3606', 'es', 'Burpee golpeo balón medicinal', 'Burpee completo finalizando con slam ball. Uno de los ejercicios más demandantes metabólicamente. Mantén la técnica a pesar de la fatiga. El slam debe ser explosivo incluso cuando estés cansado.'),
('5996d97f-b0a2-4d15-b71a-e29182709ad4', 'b7992707-04da-4663-9b3c-34b85dd81097', 'en', 'California Press', 'Starts as a French press but allows the bar to move toward the lower chest on the way up, turning into a close-grip bench press. Objective: triceps overload. Cues: control the descent toward the forehead and explode on the way up. Common error: using excessive shoulder momentum.'),
('02647aec-9109-4c71-bf66-934671acf935', 'b7992707-04da-4663-9b3c-34b85dd81097', 'es', 'Press California', 'Inicia como un press francés pero permite que la barra se desplace hacia la parte inferior del pecho al subir, convirtiéndose en un press de banca estrecho. Objetivo: sobrecarga de tríceps. Cues: controla el descenso hacia la frente y explota al subir. Error común: usar excesivo impulso de hombros.'),
('db815ded-7251-4518-8d25-8491069e2dfd', 'b79f1028-e31d-4a0a-aa9f-2564d20edf4f', 'en', 'Lateral Bounce Toss', 'Throw the ball to the floor laterally and catch it quickly as it bounces. Core power. Cue: use hip drive. Common error: hunching the back when catching the ball.'),
('e6500f14-7f11-46bd-89d5-fb37655a42d1', 'b79f1028-e31d-4a0a-aa9f-2564d20edf4f', 'es', 'Lanzamiento lateral rebote', 'Lanza el balón al suelo lateralmente y recógelo rápidamente al rebotar. Potencia de core. Cue: usa el golpe de cadera. Error común: encorvar la espalda al recibir el balón.'),
('247423e7-fa53-4bed-8f83-9ab53aaccef5', 'b826fdb7-c753-424b-9eff-0df1491fb3eb', 'en', 'Dumbbell Snatch', 'In one pull from the floor, bring the dumbbell overhead. Cue: keep the weight close to the body. Error: arching the back at the start.'),
('9af5c9a7-fe60-451c-bf89-a88daeb9b597', 'b826fdb7-c753-424b-9eff-0df1491fb3eb', 'es', 'Arrancada con mancuerna (Snatch)', 'De un tirón desde el suelo lleva la mancuerna sobre la cabeza. Cue: mantén la pesa cerca del cuerpo. Error: arquear la espalda al inicio.'),
('dc35720c-2df6-45c5-9255-eab886c1705e', 'b885162e-0e50-4141-bccf-8849a2dcad00', 'es', 'Push Press alterno con Kettlebell doble', 'Utiliza un ligero impulso de las piernas para ayudar a presionar las pesas rusas alternativamente sobre la cabeza, manteniendo el control en la bajada.'),
('79c24dff-8314-4ee0-b85e-a8179a77912a', 'b8a0be53-3432-4d93-980b-dd5d2836e8f1', 'en', 'Battle Ropes Squat', 'Maintain waves while performing squats. You can do static squats holding the position or dynamic ones. The combination significantly increases metabolic demand. Maintain technique in both movements.'),
('2b7493a3-6dad-474a-87f3-db666bc3703c', 'b8a0be53-3432-4d93-980b-dd5d2836e8f1', 'es', 'Battle ropes squat', 'Mantén las ondas mientras realizas sentadillas. Puedes hacer sentadillas estáticas manteniendo la posición o dinámicas. La combinación aumenta significativamente la demanda metabólica. Mantén la técnica en ambos movimientos.'),
('0913dae2-edc6-4183-800c-8a9e48d943f8', 'b8ab3461-8c39-45a5-8082-b0230ed4ab26', 'en', 'Double Kettlebell Snatch', 'Lift two kettlebells from between your legs to overhead in a single continuous and explosive arc.'),
('3a026e9c-4c5a-4c35-b6c4-c1a895a79b7c', 'b8ab3461-8c39-45a5-8082-b0230ed4ab26', 'es', 'Snatch con Kettlebell doble', 'Eleva dos Kettlebells desde entre las piernas hasta por encima de la cabeza en un solo arco continuo y explosivo.'),
('3aad3a90-84c1-4167-9d09-967d947d877c', 'b8b0a653-ada9-455a-af3e-d58689f04d75', 'en', 'Single Leg Glute Bridge', 'From a glute bridge position, extend one leg keeping it aligned with the thigh of the supporting leg. Raise hips using only one leg, keeping the pelvis level. This unilateral exercise significantly increases intensity and improves muscle balance.'),
('9ec1f31c-f094-4c41-8824-a36612874b36', 'b8b0a653-ada9-455a-af3e-d58689f04d75', 'es', 'Single leg glute bridge', 'Desde la posición de puente glúteo, extiende una pierna manteniéndola alineada con el muslo de la pierna de apoyo. Eleva las caderas usando solo una pierna, manteniendo la pelvis nivelada. Este ejercicio unilateral aumenta significativamente la intensidad y mejora el equilibrio muscular.'),
('7a4be970-12a5-49fe-b977-7f6981ddc554', 'b8de6335-0aee-4886-8248-570eb6ca45eb', 'en', 'Seated Concentration Curl', 'Seated, support the elbow against the inside of the thigh and flex the dumbbell. Objective: bicep peak. Cue: control the weight descent. Common error: swinging the shoulder to facilitate flexion.'),
('3eeba423-306e-4b9a-a2af-82cbcbdb1897', 'b8de6335-0aee-4886-8248-570eb6ca45eb', 'es', 'Curl concentrado sentado', 'Sentado, apoya el codo contra el interior del muslo y flexiona la mancuerna. Objetivo: pico del bíceps. Cue: controla el descenso del peso. Error común: balancear el hombro para facilitar la flexión.'),
('ca4f244a-2c07-4c84-bf67-add5816da111', 'b913b3db-3196-4579-9d12-42a137e214b3', 'en', 'Farmers Walk with Dumbbells', 'Walk holding a heavy dumbbell in each hand at your sides. Keep back straight, shoulders back, and core tight.'),
('73eeac40-8432-4b0c-9a1c-43960bb1bf21', 'b913b3db-3196-4579-9d12-42a137e214b3', 'es', 'Caminata de granjero con mancuernas (Farmers Walk)', 'Camina sosteniendo una mancuerna pesada en cada mano a los costados. Mantén la espalda recta, hombros atrás y core tenso.'),
('c9c9a55e-a987-4e80-a505-a08646b2e933', 'b9223791-877a-41db-89ac-fd4ec765d399', 'en', 'Medicine Ball Explosive Slam', 'Slam ball with maximum speed and power. Lift the ball completely overhead with full body extension. Slam with all your strength using core and arms. Pick up immediately and repeat without pause.'),
('d7306a69-9ec3-4281-98ed-0f86301be3d8', 'b9223791-877a-41db-89ac-fd4ec765d399', 'es', 'Golpeo explosivo balón medicinal', 'Slam ball con máxima velocidad y potencia. Eleva el balón completamente sobre la cabeza con extensión total del cuerpo. Golpea con toda la fuerza usando core y brazos. Recoge inmediatamente y repite sin pausa.'),
('1b44361e-1047-4055-8301-0838e6ee8bc8', 'b93c2d1d-8623-4cfe-8d25-70f865ed94bc', 'en', 'Lateral Pulley Glute Kick with Stirrup', 'Push leg laterally on pulley. Cue: upright body. Error: using momentum.'),
('f77dd7ad-a3a1-43c2-9e66-53a7c4eacf76', 'b93c2d1d-8623-4cfe-8d25-70f865ed94bc', 'es', 'Patada glúteo lateral polea estribo', 'Aleja pierna lateral en polea. Cue: cuerpo erguido. Error: usar impulso.'),
('70fa5ddb-ae6a-444e-a0ef-f9378b5cbbb0', 'b94ff634-f0cf-4254-b943-9549e25174f3', 'en', 'Strict Overhead Squat', 'Squat with bar locked overhead. Maximum mobility. Cue: push the bar to the ceiling. Error: weak arms.'),
('c7f3a8c7-a51a-4d44-bdbe-61ea0cd091be', 'b94ff634-f0cf-4254-b943-9549e25174f3', 'es', 'Sentadilla overhead estricta', 'Sentadilla con barra bloqueada sobre la cabeza. Movilidad máxima. Cue: empuja la barra al techo. Error: brazos flojos.'),
('8a4ad46c-0fe8-4c0c-b81c-1d36dc877055', 'b953c811-a6f3-4081-853d-6638dbaf5677', 'en', 'Dumbbell Lateral Lunge', 'Hold the weight goblet-style and move laterally. Cue: hips back when lowering. Error: knee excessively passes the foot.'),
('4c2fd194-fa45-4bdb-9c80-06263657a7f0', 'b953c811-a6f3-4081-853d-6638dbaf5677', 'es', 'Zancada lateral con mancuerna', 'Sujeta la pesa estilo goblet y desplázate lateralmente. Cue: cadera atrás al bajar. Error: rodilla sobrepasa excesivamente el pie.'),
('e175a035-55c1-4bf7-b9df-638afdfd946c', 'b9beeb5b-8ce0-441f-813c-c3b7b8ebb0be', 'en', 'Dragon Flag', 'Lying down, grab a fixed point behind the head and lift the entire body supported only on shoulders. Cue: rigid body. Error: bending the hip during the movement.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('c31b0619-63d9-4c21-8f67-e78261902b6c', 'b9beeb5b-8ce0-441f-813c-c3b7b8ebb0be', 'es', 'Dragon Flag', 'Tumbado, agarra un punto fijo tras la cabeza y eleva todo el cuerpo apoyado solo en hombros. Cue: cuerpo rígido. Error: doblar la cadera durante el movimiento.'),
('ef4f8c93-dbef-4aae-97db-ee9d7da527c4', 'ba023b53-2606-496e-96d1-23d742a7c89c', 'en', 'Plyometric Band Lunge', 'Jumping lunges resisted by an elastic band anchored to the floor or waist. Resisted power. Cue: neutral back despite the pull. Common error: losing alignment of the front knee.'),
('fc7356da-3e20-48a2-b57c-9f754ce1fe8b', 'ba023b53-2606-496e-96d1-23d742a7c89c', 'es', 'Zancada pliométrica con banda', 'Zancadas con salto resistidas por una banda elástica anclada al suelo o cintura. Potencia resistida. Cue: espalda neutra a pesar del tirón. Error común: perder la alineación de la rodilla delantera.'),
('cb7382e4-0d7c-42fb-9f46-cd6fbdb803d4', 'ba0b94eb-02f2-4c47-a837-195df129abfb', 'en', 'Zercher Squat', 'Squat holding the bar in the crook of the elbows. Uncomfortable but effective position. Great core activation and more vertical posture. Use a pad or towel. Named after Ed Zercher.'),
('ae8bf365-5138-4317-a561-25a3fa1f1702', 'ba0b94eb-02f2-4c47-a837-195df129abfb', 'es', 'Sentadilla zercher', 'Sentadilla sosteniendo la barra en el pliegue de los codos. Posición incómoda pero efectiva. Gran activación del core y postura más vertical. Usa almohadilla o toalla. Nombrada por Ed Zercher.'),
('d8139a7d-f6ca-4365-8136-cfb26809bdc4', 'ba4034b9-6fbb-4962-8faa-0c15c18734d4', 'en', 'Band Rollout', 'Rollout with an elastic band anchored behind providing additional resistance. The band makes the extension harder and can assist or resist the return. Allows for progressive overload of the exercise.'),
('deb8c10d-6caa-41cd-81d7-909c9d833f86', 'ba4034b9-6fbb-4962-8faa-0c15c18734d4', 'es', 'Rodamiento con banda', 'Roll out con banda elástica anclada detrás proporcionando resistencia adicional. La banda hace más difícil la extensión y puede asistir o resistir el retorno. Permite sobrecarga progresiva del ejercicio.'),
('691daa8c-6885-482b-b05f-6065dd41c6e3', 'ba4919d0-3b4a-4b8a-9a43-ef08afeb7e51', 'en', 'Fast Plyometric Lunge', 'Jumping lunges seeking maximum leg change speed, not height. Cue: fast feet. Common error: lack of range in the lunge.'),
('681ad89a-06d1-48c9-ac54-5cf8d1bdca4d', 'ba4919d0-3b4a-4b8a-9a43-ef08afeb7e51', 'es', 'Zancada pliométrica rápida', 'Zancadas con salto buscando la máxima velocidad de cambio de piernas, no altura. Cue: pies rápidos. Error común: falta de rango en la zancada.'),
('3b61d898-85f1-45fe-b7d0-b489650959ac', 'ba6107c6-1ae0-4232-97df-7fade6f5101f', 'en', 'Behind the Neck Kettlebell Triceps Extension', 'Lower the kettlebell behind the head. Objective: triceps. Cue: elbows tucked in. Error: arching the lower back.'),
('6cca7f8c-6243-4fdd-9975-b3ed964ddae8', 'ba6107c6-1ae0-4232-97df-7fade6f5101f', 'es', 'Extensión tríceps kettlebell nuca', 'Baja pesa rusa tras cabeza. Objetivo: tríceps. Cue: codos cerrados. Error: arquear lumbar.'),
('51977c88-bd2b-4223-917b-2b7bbb5f5c38', 'ba62b473-3524-4eec-a4d0-b8c06110a339', 'en', 'Machine Rotary Torso', 'Seated with the torso fixed, rotate the lower body or vice versa according to design. Works the obliques in a controlled manner. Avoid using momentum and keep the movement smooth and controlled in both directions.'),
('9c55ef70-4ced-48af-986d-a5a51a064631', 'ba62b473-3524-4eec-a4d0-b8c06110a339', 'es', 'Rotary torso máquina', 'Sentado con el torso fijo, rota la parte inferior del cuerpo o viceversa según el diseño. Trabaja los oblicuos de forma controlada. Evita usar impulso y mantén el movimiento suave y controlado en ambas direcciones.'),
('469cd6e7-20f6-4368-9af6-6cd21105e627', 'ba648d11-3cf0-47ae-b419-287be9518a7b', 'en', 'Cross-Arm Superman', 'Lift chest/legs with arms to the sides. Objective: back/lower back. Cue: look at the floor. Error: neck back.'),
('947c6617-7ba2-41d4-a7d0-271d61885cee', 'ba648d11-3cf0-47ae-b419-287be9518a7b', 'es', 'Superman brazos cruz', 'Eleva pecho/piernas brazos lados. Objetivo: espalda/lumbar. Cue: mira suelo. Error: cuello atrás.'),
('aa84609a-cf93-477c-a571-df81e14042b7', 'ba65bbf0-2d16-4b8a-8f6e-7572e1a19fff', 'en', 'Double Kettlebell Bottoms Up Front Rack Step Up', 'Step up onto the bench with two upside-down kettlebells in the rack position, requiring exceptional grip control and stability.'),
('9d17e87f-fa89-4b13-9352-8f12bdf552d2', 'ba65bbf0-2d16-4b8a-8f6e-7572e1a19fff', 'es', 'Step Up Front Rack con Kettlebell doble Bottoms Up', 'Sube al banco con dos Kettlebells invertidas en posición rack, lo que requiere un control excepcional del agarre y la estabilidad.'),
('99e36de3-711b-4b83-bb66-a8b56ab9d759', 'ba6e2736-bab8-416d-8569-78cc1d71959d', 'en', 'Dumbbell Triceps Extension', 'Seated or standing, hold a dumbbell with both hands overhead. Lower the dumbbell behind the head by flexing the elbows, keeping the upper arms motionless. Extend back to the starting position by contracting the triceps.'),
('94c4c549-2d63-4e66-a22b-1aaaed7bd819', 'ba6e2736-bab8-416d-8569-78cc1d71959d', 'es', 'Extensión tríceps mancuernas', 'Sentado o de pie, sujeta una mancuerna con ambas manos sobre la cabeza. Desciende la mancuerna por detrás de la cabeza flexionando los codos, manteniendo los brazos superiores inmóviles. Extiende hasta la posición inicial contrayendo los tríceps.'),
('e3e5b0a8-8692-4056-ab22-22b0c1f361e2', 'baa9d468-4730-450a-baa0-cb7b1c396a40', 'es', 'Press pecho TRX', 'De pie inclinado hacia adelante con las manos en las correas, realiza un movimiento de press. Cuanto más inclinado estés, mayor será la dificultad. La inestabilidad del TRX aumenta la activación muscular estabilizadora.'),
('2a717c82-7e9b-4d16-9cbe-7126190aba76', 'baea5396-0244-4229-81ef-0ad6e8d3c98b', 'en', 'Band Front Raises', 'Step on the band and hold the ends in front of the thighs. Lift the arms forward to shoulder height keeping arms straight or with a slight bend. Descend in a controlled manner. Works primarily the anterior deltoid.'),
('f5305ac9-e0f0-405b-81ae-64e351f7fb02', 'baea5396-0244-4229-81ef-0ad6e8d3c98b', 'es', 'Elevaciones frontales con banda', 'Pisa la banda y sujeta los extremos frente a los muslos. Eleva los brazos al frente hasta la altura de los hombros manteniendo los brazos rectos o con ligera flexión. Desciende controladamente. Trabaja principalmente el deltoides anterior.'),
('779e0055-407c-4a64-a097-885a3385475d', 'baec9299-6704-41cb-9d8b-8101ee9f3f62', 'en', 'Single Arm Barbell Turkish Sit Up', 'Perform a sit up with a barbell locked in one hand, challenging balance and grip strength extremely.'),
('c454587d-5e09-4d43-a584-819509eedd20', 'baec9299-6704-41cb-9d8b-8101ee9f3f62', 'es', 'Sentadillas turcas con barra de un solo brazo', 'Realiza un sit up con una barra bloqueada en una mano, desafiando el equilibrio y la fuerza de agarre de forma extrema.'),
('b18333ef-516a-4df1-bc5f-fddda54bd004', 'bb1ea030-6410-49ee-ba84-73585cafb9de', 'en', 'Double Bottoms Up Kettlebell Floor Press', 'Lying on the floor, press two inverted kettlebells (bottom up), which requires enormous grip strength and shoulder stability.'),
('f45138b6-a4c6-4196-ae7f-9cae816cfa73', 'bb1ea030-6410-49ee-ba84-73585cafb9de', 'es', 'Floor Press con Kettlebell doble Bottoms Up', 'Tumbado en el suelo, presiona dos Kettlebells invertidas (fondo arriba), lo que requiere una enorme fuerza de agarre y estabilidad de hombros.'),
('5fe895ae-ede7-4929-b11b-70bd42f47c7d', 'bb69636d-acb1-4422-b6c2-c24b128e708b', 'en', 'TRX Reverse Grip Bicep Curl', 'Hold the TRX with palms down. Lean the body and perform a curl flexing elbows toward your forehead, working biceps and forearm.'),
('97a672ce-dff0-44aa-b543-d2ae8115e967', 'bb69636d-acb1-4422-b6c2-c24b128e708b', 'es', 'Curl de bíceps agarre inverso en TRX', 'Sujeta el TRX con las palmas hacia abajo. Inclina el cuerpo y realiza un curl flexionando los codos hacia tu frente, trabajando bíceps y antebrazo.'),
('b0ccea35-c336-4f2c-9899-7e74828d50d1', 'bb8de0b1-931a-487f-a779-55f358b785cf', 'en', 'Supinated Grip Lat Pulldown', 'Pull the bar with palms facing you. Objective: lats and biceps. Cues: elbows down. Common error: swinging the torso.'),
('7e1bbc37-1e6d-4ed3-8905-36f4f8840bb7', 'bb8de0b1-931a-487f-a779-55f358b785cf', 'es', 'Jalón al pecho agarre supino', 'Tira barra palmas hacia ti. Objetivo: dorsales y bíceps. Cues: codos hacia abajo. Error común: balancear el torso.'),
('a74add52-e597-47b2-bfac-d2a928f0b17d', 'bb97632b-efe1-470d-afa6-5ab9fbcbeefa', 'es', 'Press banca agarre ancho', 'Press banca manos muy separadas. Objetivo: pecho externo. Cue: codos fuera. Error: falta control.'),
('32766333-c62d-4011-809f-aa6a64ba13db', 'bbbb258e-2b06-4725-a35c-41202aa7db3f', 'en', 'Dumbbell Bench Press', 'Lie on a flat bench with a dumbbell in each hand at the sides of the chest. Press the dumbbells upward until arms are fully extended. Lower in a controlled manner bringing elbows slightly outward. Allows for a greater range of motion than the barbell.'),
('b39554a5-f7b9-4dfd-b00f-c2420e5bcdf2', 'bbbb258e-2b06-4725-a35c-41202aa7db3f', 'es', 'Press banca mancuernas', 'Túmbate en un banco plano con una mancuerna en cada mano a los lados del pecho. Presiona las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Desciende controladamente llevando los codos ligeramente hacia afuera. Permite mayor rango de movimiento que la barra.'),
('b6ba7494-25f0-46de-b76e-b722da8fbb09', 'bbbe02f3-527e-4901-80eb-694994c8b216', 'en', 'Standing Triple Jump', 'Perform three consecutive long jumps without stopping. Maximizes muscle elasticity. Cue: use arms rhythmically. Common error: braking momentum between the second and third jump.'),
('d3bed4d5-b35f-4784-af10-9ec73ee3fbb1', 'bbbe02f3-527e-4901-80eb-694994c8b216', 'es', 'Triple salto desde parado', 'Realiza tres saltos largos consecutivos sin detenerte. Maximiza la elasticidad muscular. Cue: usa los brazos rítmicamente. Error común: frenar la inercia entre el segundo y tercer salto.'),
('99bb708b-6f72-40ed-ae20-790e3a42efbc', 'bc50fbbb-74a4-42d6-a1d4-f41c0602f6b8', 'en', 'Alternating Rotational Double Kettlebell Shoulder Press', 'Press kettlebells alternately overhead while rotating the torso and pivoting on the foot of the pushing side for a dynamic movement.'),
('53a6a27b-cba7-4019-9c8c-4270e7e762c1', 'bc50fbbb-74a4-42d6-a1d4-f41c0602f6b8', 'es', 'Press de hombros rotacional alterno con Kettlebell doble', 'Presiona las pesas rusas alternativamente sobre la cabeza mientras rotas el torso y pivoteas sobre el pie del lado que empuja para un movimiento dinámico.'),
('14f9c776-5a0b-43ea-8ec9-7e4cdd0d3765', 'bc7cd25c-bbba-47b4-88d0-e5d8e8c81197', 'en', 'High Pulley Seated Face Pull', 'Pull rope to face while seated. Cue: thumbs back. Error: forward head.'),
('25a9978f-e530-4930-bdfd-e5046ca8097b', 'bc7cd25c-bbba-47b4-88d0-e5d8e8c81197', 'es', 'Face pull sentado polea alta espalda', 'Tira cuerda a cara sentado. Cue: pulgares atrás. Error: adelantar cabeza.'),
('f1067f0c-be37-4c86-b6d8-ea8eb01ce542', 'bc9468f9-e95b-4c75-ba50-2fa18493dff2', 'en', 'Single Leg Deadlift', 'Standing on one leg, hinge forward from the hips while extending the free leg backward, keeping both as straight as possible. Descend until the torso is parallel to the floor. Return up by contracting glutes and hamstrings. Keep hips square.'),
('a8bf79f8-7c9f-4dc8-a38a-2f40b8130762', 'bc9468f9-e95b-4c75-ba50-2fa18493dff2', 'es', 'Single leg deadlift', 'De pie sobre una pierna, inclínate hacia adelante desde las caderas mientras extiendes la pierna libre hacia atrás, manteniendo ambas lo más rectas posible. Desciende hasta que el torso esté paralelo al suelo. Vuelve a la posición inicial contrayendo glúteos e isquiotibiales. Mantén las caderas cuadradas.'),
('e7e3a9da-a891-4649-a721-ea880ffeaa09', 'bcbd047c-2e6a-4c34-8043-30d159680a34', 'en', 'Floor Dumbbell Flyes', 'Lying on the floor, perform chest flyes. The floor limits the range, protecting the shoulder. Elbows touch the floor gently. Do not bounce.'),
('e57ab94b-d84f-418b-8577-18cb82add681', 'bcbd047c-2e6a-4c34-8043-30d159680a34', 'es', 'Aperturas con mancuernas en suelo', 'Tumbado en el suelo, realiza press de pecho. El suelo limita el rango protegiendo el hombro. Codos tocan suelo suave. No rebotes.'),
('5d9685d9-5c06-4837-a5f7-d814f09e8544', 'bcc0c83a-c086-46fc-9320-cb4be8a162af', 'en', 'Step-down', 'Controlled step-down followed by a short acceleration for unilateral stability and carry-over to running/sprinting.'),
('bebbd342-4ff7-4a83-8fc6-5b7cdbb04d14', 'bcc0c83a-c086-46fc-9320-cb4be8a162af', 'es', 'Step-down', 'Baja del cajón con control (rodilla estable) y enlaza con una aceleración corta y potente. Técnica limpia antes de velocidad.'),
('4de84acc-68aa-4a57-bd05-e6526bf32b5a', 'bd06a08a-bfbd-4f62-9bcb-a975a43a1250', 'en', 'Single Arm Kettlebell Split Jerk', 'Drive the weight overhead using an explosive leg dip and catch it in a split lunge position.'),
('0c7e1c7b-0279-4cee-b21b-4ea0c9604181', 'bd06a08a-bfbd-4f62-9bcb-a975a43a1250', 'es', 'Split Jerk con Kettlebell a una mano', 'Lanza la pesa sobre la cabeza mediante un impulso explosivo de piernas y recibela en posicion de zancada dividida (split).'),
('9203e7b6-1587-4936-814d-4c90f10e5d24', 'bd18829a-db12-4927-9d13-a51cae65666c', 'en', 'Single Arm Barbell Overhead Toe Balance Squat', 'Deep squat on the balls of the feet while maintaining a barbell locked out overhead with a single arm, an extreme mobility challenge.'),
('41df1553-c5c8-4a53-a760-ffaabf2600f0', 'bd18829a-db12-4927-9d13-a51cae65666c', 'es', 'Sentadilla Overhead en equilibrio sobre dedos a una mano', 'Sentadilla profunda sobre las puntas de los pies manteniendo una barra bloqueada sobre la cabeza con un solo brazo, un reto extremo de movilidad.'),
('57865534-70f9-450e-bb52-d3ed885468b6', 'bd58fe26-177c-41d6-9a0b-720f1e8aa837', 'en', 'Bodyweight Freestanding Handstand Push Up', 'From a freestanding handstand position, bend your arms to lower your body and push back up to the vertical position.'),
('2e000f45-8638-486e-947a-399ecf6bab23', 'bd58fe26-177c-41d6-9a0b-720f1e8aa837', 'es', 'Handstand Push Up', 'Desde la posición vertical de parada de manos, flexiona los brazos para bajar el cuerpo y extiende con fuerza para volver arriba sin apoyo externo.'),
('d9585900-f801-4b6b-a045-d5b4b299e988', 'bd5a9a94-6653-46d0-9efb-8dbda494e83d', 'en', 'Behind the Back Cable Lateral Raises', 'Lift the cable laterally with the arm passing behind the body. Objective: more tension at the shoulder stretch. Cue: control the descent. Common error: using excessive torso momentum.'),
('c70c3fd8-79c2-4f6c-90bf-2b51a6326363', 'bd5a9a94-6653-46d0-9efb-8dbda494e83d', 'es', 'Elevaciones laterales por detrás en cable', 'Eleva el cable lateralmente con el brazo pasando por detrás del cuerpo. Objetivo: mayor tensión en el estiramiento del hombro. Cue: controla la bajada. Error común: usar excesivo impulso del tronco.'),
('eaa4502b-68c3-4ff7-a310-707422636742', 'bd668150-c4d6-4f0f-a563-dfc698a6ac63', 'en', 'Miniband Frog Pump', 'With a band above your knees and soles of the feet together, lift your hips by squeezing your glutes hard.'),
('56ab1412-0763-48b9-8fe7-8421d17fd976', 'bd668150-c4d6-4f0f-a563-dfc698a6ac63', 'es', 'Frog Pump con Miniband', 'Con una banda sobre las rodillas y plantas de los pies juntas, eleva la cadera apretando los gluteos con fuerza.'),
('56d6ed4b-6e69-4b5e-b727-7aa269353ef1', 'bd698c53-cc9d-40bc-bac6-b9fcf6ffb4a8', 'en', 'Barbell Bicep Curl', 'Standing with the bar held palms up at shoulder width, flex elbows bringing the bar toward shoulders. Keep elbows fixed at your sides and avoid swinging the body. Especially control the eccentric phase of the movement.'),
('b92ccaf6-5e12-4c88-bf5d-62a47a61a908', 'bd698c53-cc9d-40bc-bac6-b9fcf6ffb4a8', 'es', 'Curl bíceps barra', 'De pie con la barra agarrada con las palmas hacia arriba al ancho de los hombros, flexiona los codos llevando la barra hacia los hombros. Mantén los codos fijos a los costados y evita balancear el cuerpo. Controla especialmente la fase excéntrica del movimiento.'),
('81877427-05dc-4fef-848e-e8d97f7cdbd4', 'bd8b1d39-7219-43ac-8be1-3d79bf42aaf6', 'en', 'Front Rack Dumbbell Squat', 'Perform a deep squat holding two dumbbells on your shoulders, keeping elbows high and back neutral.'),
('3d111924-c752-43d8-b6f9-a1cc4be31f37', 'bd8b1d39-7219-43ac-8be1-3d79bf42aaf6', 'es', 'Sentadilla frontal con mancuernas (Front Rack)', 'Realiza una sentadilla profunda sosteniendo dos mancuernas sobre tus hombros, manteniendo los codos en alto y la espalda neutra.'),
('4dba5e09-258d-45b9-b243-5215a5de8f10', 'bdd80b37-db95-4af8-a6cb-15b4fa60dde1', 'en', 'Battle Ropes Power Slam', 'Slams with maximum power, raising the ropes as high as possible. Involves the whole body in each repetition. Use legs to generate momentum from below. Maintain a constant explosive rhythm.'),
('ea339f66-b27d-463b-88b2-86b313e95068', 'bdd80b37-db95-4af8-a6cb-15b4fa60dde1', 'es', 'Battle ropes power slam', 'Slams con máxima potencia elevando las cuerdas lo más alto posible. Involucra todo el cuerpo en cada repetición. Usa las piernas para generar impulso desde abajo. Mantén un ritmo explosivo constante.'),
('13573cb4-8699-49ff-ae25-63a37fe00f3a', 'bdf56f04-4970-4ef2-b213-568c26ae1260', 'en', 'Single Arm Ring Plank', 'Maintain the plank position supported on a single ring, which requires enormous core strength and shoulder stability.'),
('a3366e26-bdd3-4563-8747-50ed894178c5', 'bdf56f04-4970-4ef2-b213-568c26ae1260', 'es', 'Plancha en anillas a una mano', 'Mantén la posicion de plancha apoyado en una sola anilla, lo que requiere una enorme fuerza de core y estabilidad de hombro.'),
('375e7ce6-a102-4fb1-84f6-91641dc954b5', 'bdf9c1b4-a14e-4cfd-b997-eac4a80fef6e', 'en', 'High Pulley Rear Delt Cross-over', 'Cross cables from high to back. Cue: squeeze rear deltoid. Error: shrugging shoulders.'),
('cbfa496f-23bc-4cc2-97ae-ddbe496a8d54', 'bdf9c1b4-a14e-4cfd-b997-eac4a80fef6e', 'es', 'Pájaros polea alta Cross-over posterior', 'Cruza cables desde arriba atrás. Cue: aprieta deltoide posterior. Error: encoger hombros.'),
('3b44c8dd-790a-4e1e-8b5f-f9c062184ad1', 'be2e088a-0ad4-4ac9-a5a5-e1d353c95508', 'en', 'TRX Sprinter Start', 'Simulates a sprinter''s starting position with one leg forward and the other back in the strap. Alternately switch legs explosively. Develops unilateral power and improves coordination.'),
('c0f84762-e32a-4bba-bffe-5e0f1dae7eed', 'be2e088a-0ad4-4ac9-a5a5-e1d353c95508', 'es', 'Sprinter start TRX', 'Simula la posición de salida de un velocista con una pierna adelante y otra atrás en la correa. Alterna explosivamente las piernas. Desarrolla potencia unilateral y mejora la coordinación.'),
('8dad406f-e5d3-4e11-b0bd-fc8acdb3e430', 'be4a99a8-f772-47b1-bb03-d47dc6a826c4', 'en', 'Single Leg Pogo Jump', 'Fast bounces on a single foot seeking minimum ground contact time. Improves ankle stability and unilateral reactive power. Cue: keep knee almost locked, push with forefoot. Common error: letting the heel collapse against the ground.'),
('e1664281-fd46-4ccd-82b4-1f4d36647627', 'be4a99a8-f772-47b1-bb03-d47dc6a826c4', 'es', 'Salto pogo a una pierna', 'Rebotes rápidos sobre un solo pie buscando mínima estancia en el suelo. Mejora la estabilidad del tobillo y la potencia reactiva unilateral. Cue: mantén la rodilla casi bloqueada, empuja con el antepié. Error común: dejar que el talón colapse contra el suelo.'),
('287e40a0-9165-4588-8cb3-b9c400563038', 'be5577b8-d3ef-4904-81b0-1075869cf147', 'en', 'Ring Dead Hang to Front Lever Pull Up', 'Hanging from the rings, pull into a Front Lever position and perform a pull-up while keeping the body parallel to the floor.'),
('27d30611-a98a-42d7-a735-e25a27c2398c', 'be5577b8-d3ef-4904-81b0-1075869cf147', 'es', 'Dead Hang a Front Lever Pull Up en anillas', 'Colgado de las anillas, tira del cuerpo hasta posicion de Front Lever y realiza una dominada manteniendo el cuerpo paralelo al suelo.'),
('f2c63475-2c70-47c9-8c5a-9e96d3cb0c79', 'be6bb02b-7900-4d3f-a753-6b673bc73fdf', 'en', 'Single Arm Kettlebell Clean to Overhead Press', 'Perform a clean to bring the weight to the shoulder and, without pausing, press it vertically until the arm is fully extended.'),
('9b4a8f55-7936-4b25-b20d-487e96903d28', 'be6bb02b-7900-4d3f-a753-6b673bc73fdf', 'es', 'Clean a Press Overhead con Kettlebell a una mano', 'Realiza un clean para llevar la pesa al hombro y, sin pausa, presiónala verticalmente hasta estirar el brazo por completo.'),
('eef81e9e-273d-48d3-9fc3-dd2f0fd46ff7', 'bead711b-684c-40a7-b0af-06d988047bdc', 'es', 'Puente glúteo mancuerna pelvis', 'Eleva cadera con pesa en pelvis. Cue: aprieta arriba 2s. Error: arquear lumbar.'),
('31023121-a743-4534-8f2b-62fcc7c91246', 'beaf2a73-3e10-4144-9d85-d39a9aec4fee', 'en', 'Unilateral Standing Hamstring Curl', 'Flex leg in vertical machine. Objective: isolated hamstrings. Cue: thigh glued. Error: arching lower back.'),
('f388f44c-2dda-4d45-89dd-d1dbc5b32747', 'beaf2a73-3e10-4144-9d85-d39a9aec4fee', 'es', 'Curl femoral pie unilateral', 'Flexiona pierna en máquina vertical. Objetivo: isquios aislados. Cue: muslo pegado. Error: arquear lumbar.'),
('83018f35-0cd4-4789-b0f5-c91984e42207', 'bed5aff6-9774-46f3-ac68-4f524abead2c', 'en', 'Pectoral Contractor Machine', 'Seated with arms open, bring arms or pads together in front of the chest. Also known as pec deck. Provides effective pectoral isolation. Keep elbows slightly bent and control the movement.'),
('4b3d6d1c-6749-484a-b057-f743f5b4aef4', 'bed5aff6-9774-46f3-ac68-4f524abead2c', 'es', 'Contractor pectorales máquina', 'Sentado con los brazos abiertos, junta los brazos o almohadillas frente al pecho. También conocido como pec deck. Proporciona aislamiento efectivo del pectoral. Mantén los codos ligeramente flexionados y controla el movimiento.'),
('c37ead57-b732-499e-b5e5-b75bd7e74164', 'bed878f2-10b8-46e7-bb60-783db8629cde', 'en', 'Bodyweight Wall Assisted Hip Airplane', 'Supported by the wall for balance, hinge at one leg and rotate the pelvis opening and closing the hip over the supporting femur.'),
('7a241e0a-bd2d-41fd-b552-89266286e13a', 'bed878f2-10b8-46e7-bb60-783db8629cde', 'es', 'Avión de cadera asistido en pared', 'Apoyado en la pared para equilibrio, inclina el torso a una pierna y rota la pelvis abriendo y cerrando la cadera sobre el femur de apoyo.'),
('57a5e397-5b61-41b3-9193-55e091de44e1', 'bf0edc97-6dea-4c45-aba6-ee183178ff2d', 'en', 'Single Arm Kettlebell Tactical Snatch', 'An explosive snatch where the kettlebell is switched between hands between the legs during the descent phase before the next swing.'),
('6dc80b9f-ecc8-45d1-ab60-351466219032', 'bf0edc97-6dea-4c45-aba6-ee183178ff2d', 'es', 'Tactical Snatch con Kettlebell a una mano', 'Un snatch explosivo donde se intercambia la Kettlebell de mano entre las piernas durante la fase de descenso antes del siguiente balanceo.'),
('a7ce4bf7-35a2-484e-aa3a-8ffa677e736f', 'bf2aa58d-2926-493a-ae1a-c3f9bd4452d4', 'en', 'Wall Reach Vertical Jump', 'Jump attempting to touch the highest possible point on a wall. Visual height motivation. Cue: stretch the reaching arm. Common error: landing on heels.'),
('4f85f04c-b70c-4fd2-8e65-7837972da014', 'bf2aa58d-2926-493a-ae1a-c3f9bd4452d4', 'es', 'Salto vertical alcance pared', 'Salta intentando tocar el punto más alto posible en una pared. Motivación visual de altura. Cue: estira el brazo de alcance. Error común: aterrizar con los talones.'),
('c0610f7c-7dee-46a1-b338-87a8e5affa53', 'bf525e5d-cf73-4cd8-a34e-4c7e21d3e54b', 'en', 'One-Arm Kettlebell Cyclist Thruster', 'With heels elevated, perform a deep squat with a kettlebell in rack position and rise explosively finishing with a one-arm overhead press.'),
('2982446d-08bb-4b9a-bc66-a55b41d5e54b', 'bf525e5d-cf73-4cd8-a34e-4c7e21d3e54b', 'es', 'Thruster Ciclista a una mano con Kettlebell', 'Con los talones elevados, realiza una sentadilla profunda con una Kettlebell en posicion rack y sube explosivamente terminando con un press sobre la cabeza con un solo brazo.'),
('afcf237b-0dd0-45f8-8ec6-e4a13857286a', 'bf5c5a0f-6f3b-47a4-a3b6-9f9cbddb7da0', 'en', 'Machine Hip Thrust', 'In a specific hip thrust machine, perform hip thrusts with controlled resistance. More comfortable and safer than the barbell version. Strongly squeeze glutes at the top and control the descent.'),
('e066dfbb-29cf-4adf-96d2-228a65177935', 'bf5c5a0f-6f3b-47a4-a3b6-9f9cbddb7da0', 'es', 'Hip thrust máquina', 'En máquina específica de hip thrust, realiza empujes de cadera con resistencia controlada. Más cómodo y seguro que la versión con barra. Aprieta fuertemente los glúteos en la parte superior y controla el descenso.'),
('3954cf6a-8772-4def-8fba-3aa29a6a0357', 'bf7f7dae-8872-4e46-93ef-7a9ad3f5efd9', 'en', 'Trap Bar Pendlay Row', 'With the torso parallel to the floor, explosively lift the Trap bar from the floor to the abdomen on each rep.'),
('a14621d5-9ebe-4e29-8c2e-8bf6ae83f224', 'bf7f7dae-8872-4e46-93ef-7a9ad3f5efd9', 'es', 'Remo Pendlay con barra Trap', 'Con el torso paralelo al suelo, levanta la barra Trap de forma explosiva desde el suelo hasta el abdomen en cada repeticion.'),
('9e300aed-72cc-44e4-bffa-b35a4c81ce95', 'bf82ab3d-335c-43f5-a3a6-1121bd28e2df', 'en', 'Bodyweight Alternating Heel Taps', 'Lie on your back with knees bent. Slightly lift your shoulders off the floor and laterally flex your torso to touch your right heel with your right hand, then repeat with the left side.'),
('c22a2945-74fe-44b9-b332-50e26566069e', 'bf82ab3d-335c-43f5-a3a6-1121bd28e2df', 'es', 'Toques de talón alternos', 'Acuéstate boca arriba con las rodillas dobladas. Levanta ligeramente los hombros del suelo y flexiona el torso lateralmente para tocar el talón derecho con la mano derecha, luego repite con el lado izquierdo.'),
('f4e9dd66-68a2-41a5-b863-93d3ec1b7600', 'bf91c915-e439-4247-bd87-42cd450df70f', 'es', 'Wall roll out', 'Rueda verticalmente contra una pared. Buena progresión hacia el roll out completo. Permite ajustar la dificultad según la distancia a la pared. Mantén el cuerpo recto y controla el descenso.'),
('c64a7160-4ce3-4727-9d08-82f69d6b9600', 'bfa4cee9-30e4-41ef-89ce-3fcbdf9d691e', 'en', 'Indian Club Heart-Shaped Swing', 'Perform fluid circular movements with the Indian Club around the shoulders describing a heart-shaped trajectory to improve mobility.'),
('f997c9e0-3603-4e83-928a-9883be334405', 'bfa4cee9-30e4-41ef-89ce-3fcbdf9d691e', 'es', 'Swing en forma de corazón con Indian Club', 'Realiza movimientos circulares fluidos con el Indian Club alrededor de los hombros describiendo una trayectoria en forma de corazón para mejorar la movilidad.'),
('015e29f4-7b81-45dd-b0bc-f85d8c249b45', 'bfb3a0f2-1038-4244-bddf-9a92b948989a', 'en', 'Single Arm Kettlebell Bottoms Up Decline Bench Press', 'Lying on a decline bench, press an upside-down kettlebell with one hand, requiring extreme stability control.'),
('e7b0778a-4bff-4e68-83b6-59933be50841', 'bfb3a0f2-1038-4244-bddf-9a92b948989a', 'es', 'Press de banca declinado a una mano con Kettlebell Bottoms Up', 'Tumbado en banco declinado, presiona una Kettlebell invertida con una mano, exigiendo un control extremo de estabilidad.'),
('f4b4a634-ed92-4b1d-9804-2180335ed507', 'c021ebe1-d0a2-4fb2-a23f-70f48ebf74d3', 'en', 'Goblet Squat with Bottom Pause', 'Hold a squat with weight at the chest for 3 seconds at the bottom. Cue: elbows on knees. Error: lifting the heel.'),
('fb788bb3-a6ef-4773-b867-5b4a71939cba', 'c021ebe1-d0a2-4fb2-a23f-70f48ebf74d3', 'es', 'Sentadilla Goblet mancuerna pausa fondo', 'Mantén sentadilla con pesa al pecho 3s abajo. Cue: codos en rodillas. Error: despegar talón.'),
('a8d54932-236c-4f7f-868e-bc1b28c32475', 'c0285eca-a940-42bd-a18b-ca0a2a8cc079', 'en', 'Reverse Grip Straight Bar Cable Bicep Curl', 'Facing the low pulley, grab the straight bar with palms down and perform the curl to emphasize the brachialis and forearms.'),
('a4204323-5c3b-4e4f-836c-41aebf829477', 'c0285eca-a940-42bd-a18b-ca0a2a8cc079', 'es', 'Curl de bíceps agarre inverso con barra recta en cable', 'Frente a la polea baja, agarra la barra recta con las palmas hacia abajo y realiza el curl para enfatizar el braquial y los antebrazos.'),
('d66df1ec-018d-4ee7-b774-0a004a6b4df2', 'c0309550-fa25-4c33-9642-012d026945d6', 'en', 'Ring Handstand to Elbow Lever to Handstand', 'From a ring handstand, lower controlled into an elbow lever and press back up powerfully to the vertical position.'),
('673195b5-b083-4fae-b93d-83a5de1ebf5f', 'c0309550-fa25-4c33-9642-012d026945d6', 'es', 'Ring Handstand a Elbow Lever a Handstand', 'Desde parada de manos en anillas, baja controladamente hasta un apoyo de codos (elbow lever) y vuelve a presionar con fuerza hasta la vertical.'),
('72415dfd-cba5-42ef-b72e-5be88a8f9e76', 'c04093cd-3518-4cb6-8555-ed356d0a1a07', 'en', 'Bodyweight Standing Walkout Plank', 'From a standing position, lean over and walk your hands forward until you reach a high plank position. Hold for one second and walk your hands back toward your feet.'),
('0b7429ee-44f4-4989-bfd9-160eecf5ae4f', 'c04093cd-3518-4cb6-8555-ed356d0a1a07', 'es', 'Walkout a Plank', 'Desde una posición de pie, inclínate y camina con las manos hacia adelante hasta llegar a una posición de plancha alta. Mantén un segundo y camina con las manos de vuelta hacia los pies.'),
('d8e12c07-bca8-4cd5-a2d7-3b196f93b6f9', 'c05a2a8a-2fb4-452c-b7a6-6d7d942e5820', 'en', 'Standing Hamstring Curl', 'Standing in the machine, flex one knee at a time bringing the heel toward the glute. Keep the thigh of the working leg against the support. This unilateral version allows for greater focus on each leg.'),
('46001de3-18d3-40db-80e1-93ea9172a23e', 'c05a2a8a-2fb4-452c-b7a6-6d7d942e5820', 'es', 'Curl femoral de pie', 'De pie en la máquina, flexiona una rodilla por vez llevando el talón hacia el glúteo. Mantén el muslo de la pierna que trabaja apoyado en el soporte. Esta versión unilateral permite mayor concentración en cada pierna.'),
('2a30c050-56ae-4313-b137-b5c86522f8a9', 'c0cac239-3989-4498-b5bb-6375476b50bf', 'en', 'Lateral Clamshell with Miniband', 'Lie on your side with knees bent and a band above them. Keeping feet together, open the upper knee like a clamshell.'),
('23035a7f-c33b-40c2-bc72-e41df4af52af', 'c0cac239-3989-4498-b5bb-6375476b50bf', 'es', 'Clamshell lateral con Miniband', 'Acuéstate de lado con las rodillas dobladas y una banda sobre ellas. Manteniendo los pies juntos, abre la rodilla superior como una almeja.'),
('70406bec-fd15-4041-8990-f1b98098fd49', 'c0f036be-51ae-4be4-b790-4791e57a7383', 'en', 'Ring Half Lay Front Lever', 'Maintain the body parallel to the ground with straight arms and extended hips, but with knees bent at 90 degrees.'),
('8909af6d-65df-4658-bda1-156b0af891e4', 'c0f036be-51ae-4be4-b790-4791e57a7383', 'es', 'Half Lay Front Lever en anillas', 'Mantén el cuerpo paralelo al suelo con los brazos rectos y las caderas extendidas, pero con las rodillas flexionadas a 90 grados.'),
('f8d8ea4e-8083-4e15-8af8-b43aee9261c2', 'c12392bf-ce74-40d3-aa96-6276b3e56447', 'en', 'Parallette L Sit to Handstand', 'From an L-Sit position on the parallettes, lift your hips and transition your body into a vertical handstand position.'),
('be4930ec-b74d-4d9d-845d-64b6a3dd839d', 'c12392bf-ce74-40d3-aa96-6276b3e56447', 'es', 'L-Sit a parada de manos en paralelas', 'Desde la posición de L-Sit en las paralelas, eleva las caderas y transiciona el cuerpo hasta quedar en posición vertical de parada de manos.'),
('5264e199-de01-4339-ae65-411d6734666e', 'c131683f-b93c-4c5e-acb2-edd36b955b5c', 'en', 'TRX Hip Extension', 'Raise hips with heels in TRX. Objective: glutes/hamstrings. Cue: squeeze at the top. Error: arching lower back.'),
('3be8fa8f-5013-4bab-8739-1cd716cea5db', 'c131683f-b93c-4c5e-acb2-edd36b955b5c', 'es', 'TRX Extensión cadera', 'Eleva cadera talones TRX. Objetivo: glúteo/isquios. Cue: aprieta arriba. Error: arquear lumbar.'),
('05aa1f9d-c2c2-4f21-9c84-5ed088576f75', 'c17befe1-cd25-4598-b364-a8df135eb59a', 'en', 'Cable Kneeling Crunch', 'Kneel in front of a high pulley holding the rope behind the head. Contract the abdomen to bring elbows toward knees, rounding the back.'),
('88cd8128-71f3-4c97-b35b-18d54734fa45', 'c17befe1-cd25-4598-b364-a8df135eb59a', 'es', 'Crunch de rodillas con cable', 'Arrodíllate frente a una polea alta sosteniendo la cuerda detrás de la cabeza. Contrae el abdomen para llevar los codos hacia las rodillas, redondeando la espalda.'),
('88f49aac-6879-49d8-997c-8c47b4c0dc5f', 'c1c4645d-8f3b-45e4-b973-0d7f71a2176e', 'en', 'Alternating Double Kettlebell Bottoms Up Decline Bench Press', 'Lying on a decline bench, press the upside-down kettlebells alternately, keeping one stable at the top while the other descends.'),
('8905ed43-03db-42b6-9da8-c697626b0676', 'c1c4645d-8f3b-45e4-b973-0d7f71a2176e', 'es', 'Press de banca declinado alterno con Kettlebell doble Bottoms Up', 'Tumbado en banco declinado, presiona las Kettlebells invertidas de forma alterna, manteniendo una estable arriba mientras la otra desciende.'),
('fb066096-23f7-4f91-a2e8-677f3d7addcf', 'c2142817-284f-4b9a-96ac-2872a1ac97e8', 'en', 'TRX Overhead Squat', 'Squat maintaining arms extended overhead with TRX. Challenges shoulder and ankle mobility. The straps provide proprioceptive feedback. Maintain constant tension in the straps.'),
('0af6e347-a8d4-4700-99a3-f29ba9682216', 'c2142817-284f-4b9a-96ac-2872a1ac97e8', 'es', 'Sentadilla overhead TRX', 'Sentadilla manteniendo los brazos extendidos sobre la cabeza con TRX. Desafía la movilidad de hombros y tobillos. Las correas proporcionan feedback propioceptivo. Mantén tensión constante en las correas.'),
('7fe7a73c-d069-466f-bed6-eec07db8a428', 'c22863d1-60c5-4943-b8f4-2a7745eaab58', 'es', 'Puente de glúteo con barra', 'Tumbado con rodillas dobladas y barra sobre la pelvis, eleva la cadera contrayendo los glúteos hasta alinear rodillas y hombros.'),
('3422cba4-b993-4b88-a7e8-e735e6b0c493', 'c243f09f-120d-4c22-a4ac-12f0007d3c92', 'en', 'One-Leg Fitball Knee Tuck', 'In a plank position with one foot on the Fitball and the other in the air. Bring the knee of the supported leg toward the chest rolling the ball and return.'),
('6d9d5251-687d-42ad-b96b-487d7e34d382', 'c243f09f-120d-4c22-a4ac-12f0007d3c92', 'es', 'Knee Tuck a una pierna con Fitball', 'En posición de plancha con un pie en el Fitball y el otro en el aire. Lleva la rodilla de la pierna apoyada hacia el pecho rodando el balón y regresa.'),
('3e8e4408-b28e-46d3-869f-9012cdc7bde6', 'c2767892-6235-468d-b6e4-2629feabdfb3', 'en', 'Cable Rope Triceps Extension', 'Pull the rope down, separating the ends. Objective: lateral triceps. Cue: elbows glued. Error: forward shoulders.'),
('8e4a3157-cd20-4908-a549-c2c729c3a645', 'c2767892-6235-468d-b6e4-2629feabdfb3', 'es', 'Extensión tríceps polea cuerda', 'Tira cuerda abajo abriendo extremos. Objetivo: tríceps lateral. Cue: codos pegados. Error: adelantar hombros.'),
('8eecf29e-185d-46ec-845e-ea41291a8d66', 'c2a2aa84-493a-454c-9ab2-968b2695b3b8', 'es', 'Puente de glúteo a una pierna con pie elevado', 'Acuéstate con un pie apoyado en un banco o cajón. Eleva la cadera empujando con ese pie, manteniendo la otra pierna en el aire.'),
('0050a9a8-b835-4ab0-a093-8298d27cd981', 'c2e77bcb-539c-4e68-b6f4-e3e19ef8e64f', 'es', 'Press Pallof', 'Resiste la rotación del cable extendiendo los brazos al frente de forma isométrica. Objetivo: anti-rotación del core. Cue: pies clavados al suelo. Error común: permitir que el cable mueva tu tronco.'),
('3933fc99-707d-495b-9b96-03e8aefd5538', 'c2f43563-991e-4f50-b25b-238ce06d9b57', 'en', 'Conventional Bench Press', 'Lying on a flat bench, lower the bar to the chest and push upward. Keep feet supported and a slight lumbar curve. Cue: retract the scapulae. Error: bouncing the bar on the chest.'),
('11501ee7-9e0f-48da-b5e9-6b351de5e474', 'c2f43563-991e-4f50-b25b-238ce06d9b57', 'es', 'Press de banca convencional', 'Tumbado en banco plano, baja la barra al pecho y empuja hacia arriba. Mantén los pies apoyados y una ligera curva lumbar. Cue: retrae las escápulas. Error: rebotar la barra en el pecho.'),
('d0c3fb52-86d0-4b2b-bee3-527646ff08a5', 'c321ed30-27db-4804-9f85-42ce6bc0c9f6', 'en', 'Strict Seated Dumbbell Shrugs', 'Lift shoulders toward ears while seated to eliminate leg momentum. Cue: do not bend elbows when rising. Error: rotating shoulders in circles at the top.'),
('2fb76dee-e68e-468c-b4a5-4456383fe72c', 'c321ed30-27db-4804-9f85-42ce6bc0c9f6', 'es', 'Encogimientos hombros sentado mancuernas estricto', 'Eleva los hombros hacia las orejas sentado para eliminar el impulso de piernas. Cue: no dobles los codos al subir. Error: rotar los hombros en círculos arriba.'),
('0e29bca7-b847-4b06-b700-65b455de52cf', 'c3db4ee4-5668-4639-beb2-87903535cdbb', 'en', 'High Pulley Incline Flyes', 'Bring pulleys together in front of the upper chest on an incline bench. Cue: fixed elbows. Error: shrugging shoulders.'),
('4a43b361-a468-43ac-8666-2f3dd6820c83', 'c3db4ee4-5668-4639-beb2-87903535cdbb', 'es', 'Aperturas inclinadas en polea alta', 'Junta poleas frente al pecho superior en banco inclinado. Cue: codos fijos. Error: encoger hombros.'),
('2f434d03-acc6-4b4e-b908-44498f9ec174', 'c3eb6dea-7238-47af-b255-69f11215fbf2', 'en', 'Kettlebell Overhead Squat', 'Squat while keeping the weight with one arm fully extended above the head. Maximum mobility. Chest out. Do not let the arm fall forward.'),
('fdf9315a-af2d-4f2a-8ede-74dd0b750727', 'c3eb6dea-7238-47af-b255-69f11215fbf2', 'es', 'Kettlebell Overhead Squat', 'Sentadilla manteniendo la pesa con un brazo totalmente extendido sobre la cabeza. Movilidad máxima. Pecho alto. No dejes que el brazo caiga adelante.'),
('7be344a7-7115-4bb2-9fe4-aad0d56e0983', 'c3f4ea47-5af4-4d66-971b-f77fb69ab4b7', 'en', 'Dumbbell French Press', 'Lying down, lower dumbbells to the sides of the ears by flexing elbows. Cue: elbows pointing to the ceiling. Error: moving arms from the shoulder.'),
('ef10722c-b330-43a1-8f9b-f66fad88f7d2', 'c3f4ea47-5af4-4d66-971b-f77fb69ab4b7', 'es', 'Press francés con mancuernas', 'Tumbado, baja las mancuernas a los lados de las orejas flexionando codos. Cue: codos apuntando al techo. Error: mover los brazos desde el hombro.'),
('dbfa0ac0-31c2-472a-904f-54092aa39077', 'c3fe5e2b-1722-4256-ab2c-357b90ad3c93', 'en', 'Barbell Wrist Curl', 'Rest forearms on a bench and flex wrists with palms facing up. Objective: wrist flexors. Cue: full range of motion. Common error: lifting forearms off the bench.'),
('a96b9220-ac14-453a-b056-630fca4fa5ff', 'c3fe5e2b-1722-4256-ab2c-357b90ad3c93', 'es', 'Curl de muñeca con barra', 'Apoya antebrazos en banco y flexiona muñecas con las palmas hacia arriba. Objetivo: flexores de muñeca. Cue: rango de movimiento completo. Error común: levantar los antebrazos del banco.'),
('ea398ef4-a2e8-4901-8992-99d18e65d02c', 'c4196719-8b09-4904-9c13-7381ea2b8a09', 'en', 'Overhead Walking Lunges', 'Walking lunges with dumbbells held overhead. Combines leg strength with shoulder and core stability. Keep arms locked vertically. Requires excellent mobility and control.'),
('1425240b-a7a3-4280-b473-a0e507a8ac76', 'c4196719-8b09-4904-9c13-7381ea2b8a09', 'es', 'Zancadas caminando overhead', 'Zancadas caminando con mancuernas sostenidas sobre la cabeza. Combina fuerza de piernas con estabilidad de hombros y core. Mantén los brazos bloqueados verticalmente. Requiere excelente movilidad y control.'),
('9d04142b-e4b2-47d3-808e-ee37c9c77572', 'c465da2d-567d-4fbe-9ffb-20df10703e3c', 'en', 'Barbell Sumo Squat', 'Wide feet, bar on trapezius, lower into a deep squat. Objective: adductors and glute. Cue: knees aligned with toes. Common error: lifting heels off the floor.'),
('0a792a8c-f49d-4ed4-bfc0-8cf7a1ecfa1f', 'c465da2d-567d-4fbe-9ffb-20df10703e3c', 'es', 'Sentadilla sumo con barra', 'Pies anchos, barra en trapecio, baja en sentadilla profunda. Objetivo: aductores y glúteo. Cue: rodillas alineadas con puntas. Error común: levantar talones del suelo.'),
('2cb0670a-6809-44e6-b2dc-c17cc5b7d92c', 'c49ef3a4-f8de-4c4f-a8ca-721f23a15658', 'en', 'Between-Bench Dips', 'Lower the hip supported on the edge of a bench with hands behind you. Objective: triceps strength. Cue: elbows pointing backward. Common error: letting the shoulders shrug.'),
('780b3198-d370-4e54-b634-7cf8baee899b', 'c49ef3a4-f8de-4c4f-a8ca-721f23a15658', 'es', 'Fondos entre bancos', 'Baja la cadera apoyado en el borde de un banco con las manos tras de ti. Objetivo: fuerza de tríceps. Cue: codos apuntando hacia atrás. Error común: dejar que los hombros se encojan.'),
('433efcce-f19b-4359-afbd-adc4e5cc5c9a', 'c4b87b70-7a77-4833-a5d4-b6327ffa2a8c', 'es', 'Zancada inversa contralateral Slider y mancuerna Front Rack', 'Sostén una mancuerna en un hombro y desliza hacia atrás la pierna del lado opuesto usando un slider.'),
('79a6a77d-13b3-45be-afcc-caf2de9d9d2a', 'c4caaf1b-6a42-49b0-b6be-873264bf727f', 'en', 'High Bar Back Squat', 'Place the bar on the trapezius. Lower the hip keeping the torso as vertical as possible and knees aligned with feet, then rise with power.'),
('2a42b57f-9c56-418c-947c-a17e1057ded0', 'c4caaf1b-6a42-49b0-b6be-873264bf727f', 'es', 'Sentadilla trasera con barra alta', 'Coloca la barra sobre los trapecios. Baja la cadera manteniendo el torso lo mas vertical posible y las rodillas alineadas con los pies, luego sube con fuerza.'),
('9b412a50-5228-4475-89e2-accdd06657d0', 'c4fdc8b5-84c3-4220-9dd4-ad2788e00770', 'en', 'Hip Thrust on Fitball with Dumbbell', 'Perform a Hip Thrust with the back on the Fitball, holding a dumbbell on the hips to add load to the movement.'),
('cf5ca3d8-e3d6-42c0-ad90-c4709fb70cf2', 'c4fdc8b5-84c3-4220-9dd4-ad2788e00770', 'es', 'Hip Thrust sobre Fitball con mancuerna', 'Realiza un Hip Thrust con la espalda en el Fitball, sosteniendo una mancuerna sobre las caderas para añadir carga al movimiento.'),
('6b672abd-1f08-40aa-a9dd-b9191e5dac4a', 'c50be416-af7c-4c55-a067-1166e4116b1b', 'en', 'Kettlebell Thruster', 'Combines a front squat with a press in a fluid movement. From the rack position, descend into a squat and upon rising use the momentum to press overhead. Intense metabolic exercise that works the whole body.'),
('a943b2ac-40df-433c-a7a8-87ca44454cc7', 'c50be416-af7c-4c55-a067-1166e4116b1b', 'es', 'Thruster kettlebell', 'Combina una sentadilla frontal con press en un movimiento fluido. Desde la posición de rack, desciende en sentadilla y al subir usa el impulso para presionar sobre la cabeza. Ejercicio metabólico intenso que trabaja todo el cuerpo.'),
('c62601e9-b337-42c6-93c7-c3958a5671b2', 'c51036d2-95cf-403b-bf5a-d3d54e190287', 'es', 'Woodchopper en polea alta', 'Diagonal descendente cruzando el cuerpo. Potencia rotacional. Core bloqueado. No muevas las caderas excesivamente.'),
('60d04e3e-d51c-4925-b31b-c2bc37cd3998', 'c57287da-2a66-4a37-8e40-d7e39aad8d46', 'en', 'Barbell Z Press', 'Perform a military press seated on the floor with legs extended, requiring perfect spinal posture and core strength.'),
('9412dc61-59c1-4679-8ba3-7dae7fa3ac01', 'c57287da-2a66-4a37-8e40-d7e39aad8d46', 'es', 'Press Z con barra', 'Realiza un press militar sentado en el suelo con piernas extendidas, exigiendo una postura perfecta de la columna y fuerza de core.'),
('09e44a40-3961-4e11-b7c7-edba83535bf8', 'c59521c2-67a0-458c-bc05-eef90fee7d25', 'es', 'Plancha lateral isométrica', 'Apoyado en un antebrazo de lado, mantén la cadera elevada formando una línea. Objetivo: oblicuos. Cue: pecho abierto. Error común: dejar que la cadera caiga hacia el suelo.'),
('3fd4f555-a51e-418c-b2c9-9185e15b8189', 'c5f554d8-508e-47aa-849a-f6693ae427cc', 'en', 'Behind the Neck Cable Triceps Extension', 'Back to the pulley, extend arms overhead. Cue: elbows close to ears. Error: opening elbows laterally.'),
('e5a6bd98-fcec-4a4b-895e-b3adc55d7935', 'c5f554d8-508e-47aa-849a-f6693ae427cc', 'es', 'Extensión de tríceps tras nuca polea', 'De espaldas a la polea, extiende los brazos sobre la cabeza. Cue: codos pegados a las orejas. Error: abrir los codos lateralmente.'),
('f2aca63d-5a06-4098-808a-c7ddc31a6da0', 'c607c999-17e2-42e3-9afa-ff1f06a66d24', 'en', 'Neutral Grip Lat Pulldown', 'Pull the bar to the chest with palms facing each other. Cue: chest out as you lower. Error: swinging torso.'),
('c5306b06-09b4-402e-a040-cea1ce442f2e', 'c607c999-17e2-42e3-9afa-ff1f06a66d24', 'es', 'Jalón al pecho agarre neutro', 'Tira de la barra al pecho con palmas enfrentadas. Cue: saca pecho al bajar. Error: balancear torso.'),
('87a80f47-f884-401e-8583-6c0dc63dff4b', 'c6455069-74d5-4e26-a51b-37138de47517', 'en', 'Controlled Decline Push Ups', 'Feet on bench or elevated surface, perform push-ups on the floor. Objective: upper pectoral and deltoids. Cue: core locked. Common error: dropping head when lowering.'),
('1ea55e5f-6c6e-47d0-b715-abf6f0dbd149', 'c6455069-74d5-4e26-a51b-37138de47517', 'es', 'Flexiones declinadas controladas', 'Pies en banco o superficie elevada, realiza flexiones en el suelo. Objetivo: pectoral superior y deltoides. Cue: core bloqueado. Error común: dejar caer la cabeza al bajar.'),
('24740ad3-d65e-4687-af3b-9bb990e401ba', 'c6505688-fb83-4364-8c21-3f1e5031eaad', 'en', 'Rope Pulley Bicep Curl', 'Flex and pull ends apart at the top for greater contraction. Constant tension. Fixed elbows. Do not swing.'),
('9d4221ac-c140-42b8-8da7-00437b7c0c7e', 'c6505688-fb83-4364-8c21-3f1e5031eaad', 'es', 'Curl de bíceps en polea con cuerda', 'Flexiona y abre los extremos arriba para mayor contracción. Tensión constante. Codos fijos. No te balancees.'),
('3da07c56-8b46-4817-a6a9-b4241e79d380', 'c66946c3-b7c1-4068-8a8c-4b2101e40aaf', 'en', 'Barbell Hack Squat', 'Perform a squat holding the bar behind your legs, just under the glutes. Objective: quadriceps isolation. Cues: chest high and looking forward. Common error: rounding the back to reach the bar.'),
('d7005b62-7583-4d5d-bdf4-12aad6f77b14', 'c66946c3-b7c1-4068-8a8c-4b2101e40aaf', 'es', 'Sentadilla Hack con barra', 'Realiza una sentadilla sujetando la barra por detrás de tus piernas, justo bajo los glúteos. Objetivo: aislamiento de cuádriceps. Cues: pecho alto y mirada al frente. Error común: redondear la espalda para alcanzar la barra.'),
('7eacccad-c2c4-4354-b0fe-55027ab0454d', 'c6849be8-2c68-48aa-b765-52ccbca7e019', 'en', 'TRX Jump Squat', 'TRX-assisted jump squats allowing for greater explosiveness. The straps help with landing and allow for higher jumps. Maintain tension in the straps throughout the movement.'),
('19b781f0-606c-4ac8-8e48-7a9c3dab7a2b', 'c6849be8-2c68-48aa-b765-52ccbca7e019', 'es', 'Sentadilla salto TRX', 'Sentadillas con salto asistidas por TRX permitiendo mayor explosividad. Las correas ayudan en el aterrizaje y permiten saltos más altos. Mantén tensión en las correas durante todo el movimiento.'),
('7508ce5d-a997-41ef-a20a-3d62026f912c', 'c6b31e41-876c-47f8-91a9-9de2895247c2', 'en', 'Slider Hamstring Curl', 'In a bridge position, slide your heels on sliders away from the body and pull them back in by strongly contracting the hamstrings.'),
('bf46097a-c143-4b78-9433-1679c4ac345e', 'c6b31e41-876c-47f8-91a9-9de2895247c2', 'es', 'Curl de isquiotibiales con Slider', 'En posición de puente, desliza los talones sobre sliders alejándolos del cuerpo y vuelve a recogerlos contrayendo fuertemente los isquiotibiales.'),
('6d9e97d1-2c7f-4161-90ef-0b43197c6533', 'c6edda6c-cd40-41fa-bab9-21578619660e', 'en', 'Single Arm Dumbbell Seated Shoulder External Rotation', 'Sit with the elbow supported on the knee bent at 90 degrees. Rotate the forearm upward and backward keeping the elbow fixed, then lower controlled.'),
('e0679d08-8d90-4ed0-9294-d394def2ebfe', 'c6edda6c-cd40-41fa-bab9-21578619660e', 'es', 'Rotación externa de hombro sentado con mancuerna', 'Siéntate con el codo apoyado sobre la rodilla doblada a 90 grados. Rota el antebrazo hacia arriba y atrás manteniendo el codo fijo, luego baja controlado.'),
('1b75af69-181c-497c-a3a6-3180d41b68fd', 'c6fd042f-9291-4ba1-82ae-91ee03b2c042', 'en', 'Suspension Single Leg Standing Bent Knee Reverse Fly', 'Balance on one leg while spreading your arms backward in the TRX to work the rear deltoids.'),
('974413b2-32c1-4093-9cad-1e951156e58d', 'c6fd042f-9291-4ba1-82ae-91ee03b2c042', 'es', 'TRX de Pie con una sola pierna Rodilla doblada Aperturas inversa', 'Mantén el equilibrio sobre una pierna mientras abres los brazos hacia atrás en el TRX para trabajar los deltoides posteriores.'),
('a0e37576-b828-41c7-8772-a0910afc34e3', 'c712407a-bc78-4c47-ae64-ee8f874cce90', 'en', 'Single Arm Clubbell Inside Pullover', 'Bring the club from the opposite shoulder across the front of the torso to the vertical, working shoulder mobility and strength.'),
('563f14c1-0b2b-427e-a5d1-1844b4b8b181', 'c712407a-bc78-4c47-ae64-ee8f874cce90', 'es', 'Inside Pullover con maza a una mano', 'Lleva la maza desde el hombro opuesto cruzando por delante del torso hacia la vertical, trabajando la movilidad y fuerza del hombro.'),
('92ae53bc-37b3-4f5d-91eb-17cdec81c6ea', 'c73cfd26-ba38-4da8-bed1-97e7fe6d55fc', 'en', 'Ring Feet Elevated Row', 'Hold the rings with heels resting on a bench. Pull your chest toward the rings while maintaining the body in a rigid horizontal line.'),
('31d21ac3-2046-46a7-83cb-7637cd0fa420', 'c73cfd26-ba38-4da8-bed1-97e7fe6d55fc', 'es', 'Remo elevado con pies anulares', 'Sujeta las anillas con los talones apoyados en un banco. Tira del pecho hacia las anillas manteniendo el cuerpo en una linea horizontal rigida.'),
('25997b00-4185-4f73-af23-98678e51e099', 'c7661a20-d734-4c3f-956b-8b29dba5efb1', 'es', 'Pullover con barra recta en cable', 'De pie frente a la polea alta, con brazos rectos, baja la barra hacia los muslos utilizando los dorsales y controlando el retorno.'),
('4b8fd288-9115-42a5-be8c-4236847139b5', 'c7ac1d34-acaf-4003-b87a-9afcd07092db', 'en', 'Cable Hip Abduction', 'With an ankle strap on a low pulley, perform lateral hip abductions. Keep the torso upright and avoid leaning toward the opposite side. The cable provides constant resistance for the gluteus medius and minimus. Control the movement in both directions.'),
('c72942e3-cffe-416f-a4b2-d925a03ce42a', 'c7ac1d34-acaf-4003-b87a-9afcd07092db', 'es', 'Abducción cadera cable', 'Con tobillera en polea baja, realiza abducciones laterales de cadera. Mantén el torso erguido y evita inclinarte hacia el lado opuesto. El cable proporciona resistencia constante para el glúteo medio y menor. Controla el movimiento en ambas direcciones.'),
('ce65a043-734f-4ae5-83ec-61a412ce4b53', 'c8202aac-4150-4ad2-a96e-2df185b0239a', 'en', 'Kettlebell Arm Bar', 'Lying on your side, bring the kettlebell from the floor to a vertical extended arm. Shoulder mobility and stability exercise. Component of the Turkish get-up. Keep the arm perpendicular to the ground.'),
('92d1991b-2b5a-48c8-84e7-8d4b72364081', 'c8202aac-4150-4ad2-a96e-2df185b0239a', 'es', 'Barra de brazo kettlebell', 'Tumbado lateral, lleva la kettlebell desde el suelo hasta brazo extendido vertical. Ejercicio de movilidad y estabilidad del hombro. Componente del levantamiento turco. Mantén el brazo perpendicular al suelo.'),
('715049ee-2a0f-40b6-87cd-fd74faf7a979', 'c8345bb6-20f9-4240-936a-0adb9895b5aa', 'en', 'Kettlebell Clean', 'Bring the kettlebell from the floor to the rack position (shoulder) in an explosive movement. Requires coordination and timing. The kettlebell should rotate around the wrist, not hit the forearm. Base for more complex movements.'),
('0d96d092-4e0a-4f86-a917-d0f652bb1e04', 'c8345bb6-20f9-4240-936a-0adb9895b5aa', 'es', 'Cargada kettlebell', 'Lleva la kettlebell desde el suelo hasta la posición de rack (hombro) en un movimiento explosivo. Requiere coordinación y timing. La kettlebell debe rotar alrededor de la muñeca, no golpear el antebrazo. Base para movimientos más complejos.'),
('7b92f8f8-d44e-49c9-8783-34137e8fb07f', 'c88b27d3-2084-4c20-b18d-e1243c858cdc', 'en', 'Single Arm Kettlebell Overhead Squat', 'Keep a kettlebell locked out overhead with one arm and perform a deep squat with balance and core control.'),
('5a890385-eb37-4fb2-af58-c4c8aa9a46df', 'c88b27d3-2084-4c20-b18d-e1243c858cdc', 'es', 'Sentadilla Overhead con Kettlebell a una mano', 'Mantén una Kettlebell bloqueada sobre la cabeza con un brazo y realiza una sentadilla profunda con control del equilibrio y core.'),
('fca942ee-3d4d-4724-945a-63f0ae40d4ab', 'c8cd64d8-1d74-4d71-9e62-f142133f659e', 'en', 'TRX Hamstring Curl', 'Lying face up with heels in the straps, raise the hips and flex the knees bringing the heels toward the glutes. Keep the hips raised during the entire movement. Excellent for hamstrings.'),
('157a15d8-e243-4885-98d4-4423de9b0699', 'c8cd64d8-1d74-4d71-9e62-f142133f659e', 'es', 'Hamstring curl TRX', 'Tumbado boca arriba con talones en las correas, eleva las caderas y flexiona las rodillas llevando los talones hacia los glúteos. Mantén las caderas elevadas durante todo el movimiento. Excelente para isquiotibiales.'),
('73c7b732-1764-45db-86cd-943db2959d16', 'c9175294-669d-4424-b4f6-002a0bf52963', 'en', 'Single Arm Kettlebell Half Kneeling Windmill', 'In a half-kneeling position with the weight locked overhead, hinge your torso to touch the floor with your free hand to gain mobility.'),
('0af329fe-9177-48fb-82eb-117b93a6eb89', 'c9175294-669d-4424-b4f6-002a0bf52963', 'es', 'Windmill medio arrodillado con Kettlebell a una mano', 'En posicion de caballero con la pesa bloqueada sobre la cabeza, inclina el torso hasta tocar el suelo con la mano libre para ganar movilidad.'),
('7d8892ac-da9b-4f4f-b3a7-be206c61407d', 'c9369285-07c9-4c01-b2a6-6447a3c1f611', 'en', 'Around the Clock Lunge', 'Perform a forward lunge, a lateral lunge, and a backward lunge with the same leg following the hands of a clock. Objective: multiplanar stability. Cues: keep the core active to avoid imbalances. Common error: taking steps that are too short and compromise the knee.'),
('3c45bb15-9284-4302-935e-3af8bcc606aa', 'c9369285-07c9-4c01-b2a6-6447a3c1f611', 'es', 'Zancada reloj (Around the clock)', 'Realiza una zancada al frente, una lateral y una trasera con la misma pierna siguiendo las agujas del reloj. Objetivo: estabilidad multiplanar. Cues: mantén el core activo para evitar desequilibrios. Error común: dar pasos demasiado cortos que comprometan la rodilla.'),
('697637e7-c4c6-4e20-9b70-c61d1e63d6df', 'c93c403e-d91d-4dbc-898b-c8fca126614c', 'en', 'Bent Over Trap Bar Row', 'Hold the Trap bar by the side handles leaning the torso. Pull the weight toward the hip keeping the back straight.'),
('96c5f0f4-b315-42d9-a212-3732577a8de2', 'c93c403e-d91d-4dbc-898b-c8fca126614c', 'es', 'Remo inclinado con barra Trap', 'Sujeta la barra Trap por las asas laterales inclinando el torso. Tira del peso hacia la cadera manteniendo la espalda recta.'),
('82ad3f47-f010-4c99-be8a-18d8c807d882', 'c94d9821-9660-48c6-8ab1-5a3c4eb4d11e', 'en', 'Barbell Bench Press', 'Lying on a flat bench, lower the bar to the chest and push upward. Objective: pectoral pushing strength. Cue: retract the scapulae and feet on the floor. Common error: bouncing the bar off the chest.'),
('5d45ef58-fde0-4a8b-b918-fe4fa25940c1', 'c94d9821-9660-48c6-8ab1-5a3c4eb4d11e', 'es', 'Press de banca con barra', 'Tumbado en banco plano, baja la barra al pecho y empuja hacia arriba. Objetivo: fuerza de empuje pectoral. Cue: retrae las escápulas y pies en el suelo. Error común: rebotar la barra en el pecho.'),
('f1ac2fa8-e507-4512-bb02-14330221aa99', 'c958ea0a-58df-4564-90f1-225a4adade00', 'es', 'Plancha con elevación de brazo frontal', 'En plancha frontal, eleva un brazo totalmente estirado al frente sin mover el cuerpo. Objetivo: estabilidad anti-rotacional. Cues: pies anchos para mayor base. Error común: rotar el cuerpo al levantar el brazo.'),
('14b064f5-daab-4936-b016-ca3b6b5972b3', 'c95c271c-ec9f-4b36-9eba-0d0dc31b27a6', 'es', 'Pullover mancuernas', 'Túmbate perpendicular al banco con solo los hombros apoyados. Sujeta una mancuerna con ambas manos sobre el pecho. Desciende la mancuerna por detrás de la cabeza en arco manteniendo los brazos semi-extendidos. Vuelve a la posición inicial activando pecho y dorsales.'),
('369cc768-3ed4-4985-a8f2-c11627f21157', 'c973e606-491e-4def-945b-e760251b8719', 'en', 'Crab walk', 'Sit with hands supported behind you on the floor and lift hips. Walk backward or sideways moving hands and feet coordinately. Keep hips raised throughout the movement. Strengthens triceps, shoulders, and core while improving shoulder mobility.'),
('6fa376fe-d6ef-43af-b121-d648e88defbf', 'c973e606-491e-4def-945b-e760251b8719', 'es', 'Crab walk', 'Siéntate con las manos detrás apoyadas en el suelo y eleva las caderas. Camina hacia atrás o los lados moviendo manos y pies coordinadamente. Mantén las caderas elevadas durante todo el movimiento. Fortalece tríceps, hombros y core mientras mejora la movilidad de hombros.'),
('fc030cb9-2c8c-43ab-ace1-ccba4f497b85', 'c99bee43-fc7e-4158-870e-f2181665cd2b', 'en', 'Standing Military Press', 'Push the bar from the chest to lockout overhead without leg help. Cue: squeeze glutes and abdomen. Error: swinging the body to lift the weight.'),
('ee929310-bb6c-4649-b2f5-4bef91d51672', 'c99bee43-fc7e-4158-870e-f2181665cd2b', 'es', 'Press militar de pie', 'Empuja la barra desde el pecho hasta bloquear sobre la cabeza sin ayuda de piernas. Cue: aprieta glúteos y abdomen. Error: balanceo del cuerpo para subir el peso.'),
('82a0e8d9-8920-4e3f-b3ab-128a39167c04', 'c9b26220-c57e-4261-aa73-9998f8a50902', 'es', 'Pull apart con banda', 'Sujeta la banda con ambas manos frente al pecho, brazos extendidos. Separa las manos estirando la banda mientras llevas los omóplatos hacia atrás. Mantén los brazos paralelos al suelo durante todo el movimiento. Fortalece la espalda alta y mejora la postura.'),
('265c83d9-4a73-401a-b9fe-b9bf9a9fc940', 'c9c8931f-c2b1-44c4-a840-2312bd65aae6', 'en', 'Fitball Plyometric Push Up', 'Push-up with feet on Fitball and hands on floor, pushing explosively. High core demand. Cue: squeeze glutes to stabilize the ball. Common error: arching lower back excessively.'),
('a17b07c2-fc63-4528-826f-e47356dc10fd', 'c9c8931f-c2b1-44c4-a840-2312bd65aae6', 'es', 'Flexión pliométrica sobre fitball', 'Flexión con pies en fitball y manos en suelo, empujando explosivamente. Alta demanda de core. Cue: aprieta glúteos para estabilizar la bola. Error común: arquear la lumbar excesivamente.'),
('c9c636f8-fc76-4fa2-ae30-bccb7d0abc7c', 'c9d1f0e1-cd67-43b2-87e4-5c9fb33d3f00', 'en', 'Conventional Deadlift', 'Bar on the floor, grip at shoulder width, lift the load by extending hip and knees. Cue: bar against shins. Error: rounding the lower back.'),
('a235510f-d854-4e9e-88e1-9a056cf55694', 'c9d1f0e1-cd67-43b2-87e4-5c9fb33d3f00', 'es', 'Peso muerto convencional', 'Barra en el suelo, agarre a la anchura de hombros, levanta la carga extendiendo cadera y rodillas. Cue: barra pegada a las tibias. Error: redondear la espalda lumbar.'),
('165e647f-3825-4e32-aff8-bbe019fac17c', 'c9f4522c-8c61-43eb-a490-765c68cf7bba', 'en', 'Ring Skin the Cat', 'Hanging from the rings, rotate your body backward passing your legs between your arms until reaching maximum shoulder stretch.'),
('4a67fe01-1b13-4236-afe3-0bb2b688ffae', 'c9f4522c-8c61-43eb-a490-765c68cf7bba', 'es', 'Anillas Piel del Gato', 'Colgado de las anillas, gira el cuerpo hacia atras pasando las piernas entre los brazos hasta quedar en estiramiento maximo de hombros.'),
('38fb6f62-da54-4caf-8147-84c9050e50e3', 'ca2b9b88-15b3-46fa-be24-daddb077f104', 'en', 'Hollow Body Hold with Dumbbell (Crush Grip)', 'In Hollow Body position (lower back glued to floor, limbs raised), hold a dumbbell with both hands pressing it against the chest or extended overhead.'),
('3f619b90-7fa9-43c4-a69b-2d2aee85feaf', 'ca2b9b88-15b3-46fa-be24-daddb077f104', 'es', 'Hollow Body Hold con mancuerna (Agarre Crush)', 'En posición de Hollow Body (espalda baja pegada al suelo, extremidades elevadas), sostén una mancuerna con ambas manos presionándola contra el pecho o extendida sobre la cabeza.'),
('33e0608e-60ef-4a01-aa6f-2bd7281d1fac', 'ca4db067-9c1c-4c47-8885-a1039bd7456d', 'en', 'Clapping push ups', 'Perform an explosive push-up pushing with enough force to lift hands off the floor. In the air, give a quick clap before landing softly with hands to cushion and continue with the next repetition. Develops explosive upper body power.'),
('f425aa52-6317-4806-96b2-70225a8f9a5d', 'ca4db067-9c1c-4c47-8885-a1039bd7456d', 'es', 'Clapping push ups', 'Realiza una flexión explosiva empujando con suficiente fuerza para despegar las manos del suelo. En el aire, da una palmada rápida antes de aterrizar suavemente con las manos para amortiguar y continuar con la siguiente repetición. Desarrolla potencia explosiva del tren superior.'),
('9c9f13db-991d-488f-821a-cf8fa73d2fe0', 'ca65d717-0c11-4376-8794-3c5b6998feb5', 'en', 'Kettlebell Russian Twist', 'Seated, rotate the torso with the weight from side to side. Focus on obliques. Straight back. Do not move the legs excessively.'),
('8e108555-1186-427f-a5fb-26791b3f2969', 'ca65d717-0c11-4376-8794-3c5b6998feb5', 'es', 'Kettlebell Russian Twist', 'Sentado, gira el torso con la pesa de lado a lado. Enfoque en oblicuos. Espalda recta. No muevas excesivamente las piernas.'),
('387afb5c-ebb1-44fb-ad4a-61e5e2a06590', 'caa04bd0-90d8-428b-bebe-0341253570ef', 'en', 'Straight-Arm Dumbbell Step Up', 'Step onto the bench with weights at your sides. Cue: push with the upper leg. Error: jumping with the floor foot.'),
('cc175bf2-5e1e-48d2-8dec-2f8c1f51d752', 'caa04bd0-90d8-428b-bebe-0341253570ef', 'es', 'Step up mancuernas brazos estirados', 'Sube banco con pesas a los lados. Cue: empuja pierna arriba. Error: saltar con pie suelo.'),
('352740af-fc07-46f7-96cc-575a362cff6a', 'caa38799-6bca-408a-a323-34c7d0e36d7f', 'en', 'Superband Side Plank Hanging Hip Adduction', 'In a side plank position with an elastic band attached to the upper leg, lift the lower leg to work the adductor against resistance.'),
('3dbf8af2-ed35-4e26-942a-9034d2ab3e46', 'caa38799-6bca-408a-a323-34c7d0e36d7f', 'es', 'Aducción de cadera en Side Plank con banda', 'En posición de plancha lateral con una banda elástica enganchada a la pierna superior, eleva la pierna inferior para trabajar el aductor contra resistencia.'),
('29497da3-c3db-430e-9afe-5f2d664998c9', 'cabfdbfd-c69d-447d-90fb-40af707d59d9', 'en', 'Alternating Lateral Bench Jump', 'Jump side to side over a bench or imaginary line, landing softly and alternating the supporting leg.'),
('c773b5aa-9d64-4b62-a79b-2f4e1e369e57', 'cabfdbfd-c69d-447d-90fb-40af707d59d9', 'es', 'Salto lateral alterno sobre banco', 'Salta de lado a lado sobre un banco o linea imaginaria, aterrizando de forma suave y alternando la pierna de apoyo.'),
('50cbba60-bbc2-4479-814c-f665316b24e0', 'cac38166-59fb-4b9d-8385-65b195443d3b', 'en', 'Bodyweight Hand Assisted Skater Squat', 'Lower into a single-leg squat while using your hands on a lateral support to assist with balance and depth.'),
('36350f75-58a4-4e1e-a4c9-d602f12862fb', 'cac38166-59fb-4b9d-8385-65b195443d3b', 'es', 'Sentadilla patinadora asistida con manos', 'Baja en sentadilla sobre una sola pierna utilizando las manos en un soporte lateral para facilitar el equilibrio y la profundidad.'),
('e063b921-07da-4699-88ad-4300655d9dc5', 'cac45c3a-c429-42e6-817e-e08e0e1b4a3b', 'en', 'Tuck Jump Burpee', 'Burpee ending with a jump bringing knees to chest. Maximum cardiovascular and power intensity. Cue: absorb the impact gently. Common error: slouching too much when jumping.'),
('e55d238e-ce04-4eb5-b458-850ac042c5c7', 'cac45c3a-c429-42e6-817e-e08e0e1b4a3b', 'es', 'Burpee con rodillas al pecho', 'Burpee que finaliza con un salto llevando rodillas al pecho. Máxima intensidad cardiovascular y de potencia. Cue: absorbe el impacto suavemente. Error común: encorvarse demasiado al saltar.'),
('6e1a2d4e-4a0b-43a1-8f97-5cf391f7d8c8', 'cae23db5-0e30-4b27-9343-380e8a0b4f7c', 'en', 'Bent Knee Reverse Hyperextension', 'Supported on a bench or elevated surface, raise legs with knees flexed to isolate work on glutes and lower back.'),
('90a68896-579c-4bcc-b7a8-8f64df8b3c87', 'cae23db5-0e30-4b27-9343-380e8a0b4f7c', 'es', 'Hiperextensión inversa con rodilla doblada', 'Apoyado en un banco o superficie elevada, eleva las piernas con las rodillas flexionadas para aislar el trabajo en los gluteos y la espalda baja.'),
('a5122678-09d6-41da-89d5-1bd7577724cf', 'caf2a77c-2e6f-4d7b-93ff-1133c4762e3b', 'en', 'Lateral walk with Miniband (Thighs)', 'Standing with a band above the knees and in a half-squat. Take lateral steps maintaining constant tension in the band without knees caving in.'),
('05690f55-a0c5-47c1-9dc3-9e7d210d749e', 'caf2a77c-2e6f-4d7b-93ff-1133c4762e3b', 'es', 'Caminata lateral con Miniband (Muslos)', 'De pie con una banda sobre las rodillas y en media sentadilla. Da pasos laterales manteniendo la tensión constante en la banda sin juntar las rodillas.'),
('5dd01ce7-2a29-4b74-85f7-5a983a20314d', 'caf6d35d-a366-4435-bdc4-8a602e27376e', 'en', 'Hammer Curl', 'Neutral grip (palms facing each other), flex the dumbbell. Works the brachialis and brachioradialis. Cue: elbows glued to the side. Error: swinging the torso to lift.'),
('ce762815-9f57-4266-8749-8d153802b40e', 'caf6d35d-a366-4435-bdc4-8a602e27376e', 'es', 'Curl Martillo', 'Agarre neutro (palmas enfrentadas), flexiona la mancuerna. Trabaja braquial y braquiorradial. Cue: codos pegados al costado. Error: balancear el torso para subir.'),
('f0425e54-c186-44ae-95ab-60b703d29a28', 'cb41822b-dd1c-45c5-b2ab-ce94584cb842', 'en', 'Double Kettlebell Bottoms Up Thruster', 'Perform a deep squat and explosively press two upside-down kettlebells overhead as you rise.'),
('1b998a39-87dc-41b4-a3ae-88b02d74eb1c', 'cb41822b-dd1c-45c5-b2ab-ce94584cb842', 'es', 'Thruster con Kettlebell doble Bottoms Up', 'Realiza una sentadilla profunda y presiona dos Kettlebells invertidas sobre la cabeza de forma explosiva al subir.'),
('15cc1eb5-e2d6-41d7-aa1a-d4e7b399bf38', 'cb7893c3-6f7b-42e0-98d5-b1a2bee2de04', 'en', 'Low Cable Crossover', 'From below, bring hands together in front of the chest. Focus on upper pectoral. Elbows slightly bent. Do not use body momentum.'),
('8e42df88-b130-49a7-945c-226ca4f2d144', 'cb7893c3-6f7b-42e0-98d5-b1a2bee2de04', 'es', 'Cruce de poleas bajas', 'Desde abajo, junta las manos frente al pecho. Enfoque en pectoral superior. Codos semiflexionados. No uses el impulso del cuerpo.'),
('b8d1f8fd-5b80-4ef5-8eb0-a7737da7a272', 'cb8aaf91-eaea-4e9f-aad3-dff4c382451a', 'en', 'Barbell Paused Deadlift', 'Perform a deadlift stopping the bar for one second just below the knee before completing hip extension, improving control at the critical point.'),
('22b2f936-696f-41c1-b475-b2022d649dfb', 'cb8aaf91-eaea-4e9f-aad3-dff4c382451a', 'es', 'Peso muerto detenido con barra', 'Realiza un peso muerto deteniendo la barra durante un segundo justo debajo de la rodilla antes de completar la extensión de cadera, mejorando el control en el punto crítico.'),
('2f2ef54a-5cf3-4d93-a0ef-6c04a6db8102', 'cb8e5597-3b7a-40cf-87da-d772d259970d', 'en', 'Partial Pin Squat', 'Squat from supports in the mid-range of movement. Cue: complete stop on each rep. Error: bouncing on supports.'),
('bb9e9728-d420-4a4b-b65c-82c4fe4df900', 'cb8e5597-3b7a-40cf-87da-d772d259970d', 'es', 'Sentadilla Pin parcial', 'Sentadilla desde soportes en el rango medio del movimiento. Cue: parada total en cada repetición. Error: rebotar en los soportes.'),
('4edb6d4d-16da-42cd-b624-82a31ba83633', 'cb8fe49e-994e-4c4c-81d3-310dfd862dce', 'es', 'Push Jerk con mancuernas', 'Lleva las mancuernas sobre la cabeza mediante un impulso de piernas y una recepcion rapida en media sentadilla con brazos bloqueados.'),
('a1767e18-caf1-448f-975b-d182a767e3ad', 'cb9a77d9-ca8e-451e-8e29-d5ce204f38b2', 'en', 'Double Kettlebell Split Jerk', 'Drive the weights overhead using leg power, catching them with locked arms and one leg forward in a split stance.'),
('958ec507-f826-4d60-8689-3aa871e544ae', 'cb9a77d9-ca8e-451e-8e29-d5ce204f38b2', 'es', 'Split Jerk con Kettlebell doble', 'Lanza las pesas sobre la cabeza mediante un impulso de piernas, recibiéndolas con brazos bloqueados y una pierna adelantada.'),
('085bc8b6-69e7-48cf-9b84-4a18f7b7086e', 'cb9efa67-0049-4454-830b-fe82a20fcf87', 'en', 'Dumbbell Turkish Get-Up', 'From a lying position with a dumbbell extended overhead, stand up while always keeping the arm extended vertically. Reverse the movement to return to the floor. Requires exceptional mobility, stability, and coordination.'),
('e31438e8-5def-4ecb-99a4-e680a77bcbb8', 'cb9efa67-0049-4454-830b-fe82a20fcf87', 'es', 'Levantamiento turco mancuernas', 'Desde posición tumbada con una mancuerna extendida sobre la cabeza, levántate hasta ponerte de pie manteniendo siempre el brazo extendido verticalmente. Invierte el movimiento para volver al suelo. Requiere movilidad, estabilidad y coordinación excepcionales.'),
('f658806d-bd97-4035-ad26-d8e14eafc0e8', 'cbbc128c-28f2-415f-b61e-10524c885c72', 'en', 'Stationary Bike', 'Gentle pedaling for 3 minutes to raise body temperature and prepare legs without impact.'),
('4a99447d-4350-4275-80b6-2980f446be74', 'cbbc128c-28f2-415f-b61e-10524c885c72', 'es', 'Bicicleta estática', 'Pedalea 3 min a ritmo cómodo (sin quemarte). Enfócate en cadencia fluida.'),
('6b38fd6c-b541-4db7-9b75-90d4cac633c0', 'cbcba4da-f5d1-45f2-850b-e7e5d0a7a146', 'en', 'Barbell Turkish Sit Up', 'Perform a sit up while keeping a loaded barbell locked vertically over your chest, demanding superior stability control.'),
('a1cbd989-8b39-4dac-b617-6d1eaf8dabf0', 'cbcba4da-f5d1-45f2-850b-e7e5d0a7a146', 'es', 'Sentadillas turcas con barra', 'Realiza un sit up manteniendo una barra cargada bloqueada verticalmente sobre el pecho, exigiendo un control de estabilidad superior.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('43a32c1f-01f3-4cd6-a374-a8655b6b14d7', 'cbd83948-95b2-48dc-ade3-90d2642b5f69', 'en', 'Leg Press Calf Raises', 'On the leg press, place only the balls of your feet at the bottom of the platform. Perform plantar flexions by pushing with the toes. Allows for safe heavy loads for calf development.'),
('764ac4b6-4097-4216-bf75-00c5b00dc593', 'cbd83948-95b2-48dc-ade3-90d2642b5f69', 'es', 'Gemelos prensa', 'En la prensa de piernas, coloca solo las puntas de los pies en la parte inferior de la plataforma. Realiza flexiones plantares empujando con las puntas. Permite usar cargas pesadas de forma segura para el desarrollo de pantorrillas.'),
('1fdefad1-f1b2-4ad6-b0bf-56b9f9a38558', 'cbdb9922-40f5-4863-a2c6-d95b388acd1b', 'en', 'Cha Cha 3-Way with Miniband', 'With band on ankles and in an athletic position. Take quick, small steps: forward diagonal, lateral, and back diagonal, maintaining tension.'),
('a29f26d1-cf2c-488e-b16c-713bdc87dace', 'cbdb9922-40f5-4863-a2c6-d95b388acd1b', 'es', 'Cha Cha 3 vías con Miniband', 'Con banda en tobillos y posición atlética. Da pasos rápidos y pequeños: diagonal adelante, lateral y diagonal atrás, manteniendo tensión.'),
('530d9064-1ea6-44cb-ad18-941e81ad6596', 'cbfe1466-b517-43a6-baac-df945d0b6cc8', 'en', 'Barbell Good Mornings', 'Barbell on shoulders, lean torso forward with legs almost straight. Posterior chain. Very flat back. Do not lower if the back curves.'),
('c8b11a37-c122-45fa-b66a-61e036b195e7', 'cbfe1466-b517-43a6-baac-df945d0b6cc8', 'es', 'Buenos días con barra', 'Barra en hombros, inclina el torso adelante con piernas casi rectas. Cadena posterior. Espalda muy plana. No bajes si la espalda se curva.'),
('f792f618-cbd2-41bf-915d-207f9e9a0091', 'cc02226f-d15a-4127-9721-1e99eb88b0ac', 'en', 'Miniband Single Leg Hip Thrust', 'With a band above your knees, perform a hip thrust supported on a single leg to maximize glute activation.'),
('35e6ca15-9d45-4045-be20-ed8461561177', 'cc02226f-d15a-4127-9721-1e99eb88b0ac', 'es', 'Hip Thrust a una pierna con Miniband', 'Con una banda sobre las rodillas, realiza un empuje de cadera apoyado en una sola pierna para maximizar la activacion del gluteo.'),
('45e37ada-2568-44ce-a989-750748f67bb5', 'cc71c081-8316-44ef-8ad8-474dc7d68f35', 'en', 'Kneeling Cable Crunch', 'Kneeling pulley crunch for abdominals, flexing the spine in a controlled manner without pulling with the arms.'),
('cc8aa8b9-a824-46f6-a9ba-487dd3b4cef1', 'cc71c081-8316-44ef-8ad8-474dc7d68f35', 'es', 'Crunch en cable arrodillado', 'Cadera estable, lleva costillas hacia pelvis. No tires con brazos; piensa en ‘encoger’ el abdomen con control.'),
('b1e463f4-3de0-431b-974b-4b4bea1984ad', 'cc7b1e07-34c7-47aa-8f64-95edb4066dcc', 'en', 'Unilateral Ankle Bounce', 'Bounce on the ball of a single foot with the knee almost locked. Improves ankle stiffness. Cue: bounce like a spring. Do not flex the knee too much.'),
('e1a407e0-172d-41cc-a704-51fb6b2262f3', 'cc7b1e07-34c7-47aa-8f64-95edb4066dcc', 'es', 'Rebote de tobillo unilateral', 'Rebota sobre la punta de un solo pie con la rodilla casi bloqueada. Mejora la rigidez del tobillo. Cue: rebota como un resorte. No flexiones mucho la rodilla.'),
('0a54dd5b-60d6-46db-a2d1-13fee68f6b3b', 'cc9b5f99-6532-46cd-af10-4c427ffcfd69', 'en', 'Manmakers', 'Burpee with dumbbells, row in each arm, shoulder press, and squat. Cue: absolute core control. Error: using weights you cannot control in the press.'),
('f3e6453c-1262-48c5-9a53-a3dde2cc3282', 'cc9b5f99-6532-46cd-af10-4c427ffcfd69', 'es', 'Manmakers', 'Burpee con mancuernas, remo en cada brazo, press de hombros y sentadilla. Cue: control absoluto del core. Error: usar pesos que no puedas controlar en el press.'),
('2de978a3-e2ff-499b-bcb0-e03f3ec6a8b2', 'ccc79c23-50db-4be7-aeb8-17cce0de6eed', 'en', 'Rotated Hip Pogo Jump', 'Pogo jumps rotating the hips side to side while keeping the chest forward. Rotational agility. Cue: quick foot rotation. Common error: rotating shoulders as well.'),
('3432e6eb-6fd4-4a5d-a246-17ab241b5316', 'ccc79c23-50db-4be7-aeb8-17cce0de6eed', 'es', 'Salto pogo cadera rotada', 'Saltos pogo girando las caderas de lado a lado manteniendo el pecho al frente. Agilidad rotacional. Cue: rotación rápida de pies. Error común: girar los hombros también.'),
('394f5c0d-dc3d-4ba9-901b-7ba7d51bd709', 'ccda659d-7961-4242-b9fc-f9814a7e21f4', 'en', 'Straddle L-Sit on Parallel Bars', 'Hold yourself on the parallel bars with legs open in a V shape and lifted parallel to the floor, keeping the body locked.'),
('5ca4e323-e815-4978-a885-5b0645ff2e2b', 'ccda659d-7961-4242-b9fc-f9814a7e21f4', 'es', 'Straddle L-Sit en paralelas', 'Sostente en las paralelas con las piernas abiertas en forma de V y levantadas paralelas al suelo, manteniendo el cuerpo bloqueado.'),
('badcc21c-fdb7-4af5-b064-bca0a3b7bd80', 'cd52169c-5ceb-4107-bfc5-b3ede3a950e6', 'en', 'Single Arm Dumbbell Squat Snatch', 'Perform an explosive Snatch but catch the dumbbell in a deep squat position before standing up.'),
('f6788c8e-c725-45ed-a54c-45079d287848', 'cd52169c-5ceb-4107-bfc5-b3ede3a950e6', 'es', 'Squat Snatch a una mano con mancuerna', 'Realiza un Snatch explosivo pero recibe la mancuerna en una posicion de sentadilla profunda antes de ponerte de pie.'),
('2efc9a32-3249-4357-8611-4d156e4933f8', 'cd6de5e6-f88b-4c8a-bc82-19b69bf5aa29', 'en', 'Overhead Throw', 'Throwing over the head like a soccer throw-in. Can be forward or backward. Involves the whole body in the movement. Excellent for developing posterior chain power.'),
('72812f59-dd71-46ec-8dcb-b563795c3d6c', 'cd6de5e6-f88b-4c8a-bc82-19b69bf5aa29', 'es', 'Overhead throw', 'Lanzamiento por encima de la cabeza como saque de banda en fútbol. Puede ser hacia adelante o hacia atrás. Involucra todo el cuerpo en el movimiento. Excelente para desarrollar potencia en la cadena posterior.'),
('d18f4266-1ddc-4be0-b2f3-6ab2862200ff', 'cd8a032c-5e47-45c4-84c2-9eea4208ffe9', 'en', 'One-Arm Kettlebell Arm Bar', 'Lying down, hold a Kettlebell locked over the shoulder and roll the body toward the opposite side, working on scapular stability.'),
('158154f9-63bf-40ec-a05c-ea636f2e38a0', 'cd8a032c-5e47-45c4-84c2-9eea4208ffe9', 'es', 'Kettlebell Arm Bar a una mano', 'Tumbado, sostén una Kettlebell bloqueada sobre el hombro y rueda el cuerpo hacia el lado opuesto, trabajando la estabilidad escapular.'),
('22844bcb-9479-4994-90d7-45fa447dc7f0', 'cdea1c3e-dd43-43a8-b1da-abc22a1257a6', 'en', 'Unilateral Diagonal Pogo Jump', 'Fast diagonal pogo jumps on a single leg. Agility and extreme reactive power. Cue: keep ankle strong. Common error: loss of diagonal trajectory.'),
('20b036f4-c681-4802-b045-76396dab0fb1', 'cdea1c3e-dd43-43a8-b1da-abc22a1257a6', 'es', 'Salto pogo diagonal unilateral', 'Saltos pogo rápidos en diagonal sobre una sola pierna. Agilidad y potencia reactiva extrema. Cue: mantén el tobillo fuerte. Error común: pérdida de trayectoria diagonal.'),
('891da3fb-e3cd-47e9-a2e6-bb39fd97f27b', 'cdf7aa49-c794-433e-bc9c-6a37107fe843', 'en', 'Band Face Pull', 'Anchor the band at face height. Pull the ends toward your face, separating your hands as they approach, as if performing a double bicep curl. Focus on pulling elbows back and squeezing shoulder blades. Excellent for shoulder health.'),
('e9c513b1-f57f-426c-8e07-54316f987c20', 'cdf7aa49-c794-433e-bc9c-6a37107fe843', 'es', 'Face pull con banda', 'Ancla la banda a la altura de la cara. Tira de los extremos hacia tu cara separando las manos al acercarse, como si fueras a hacer una doble flexión de bíceps. Enfócate en llevar los codos hacia atrás y apretar los omóplatos. Excelente para la salud del hombro.'),
('3961d5c3-bae0-4816-9a22-6b048d5dd77b', 'ce1b6232-e6ba-452e-988e-7cef4014550f', 'es', 'Plancha invertida', 'Apoyo en talones y manos de espaldas al suelo, mantén cuerpo recto. Cue: empuja la cadera hacia arriba. Error: dejar caer la pelvis.'),
('0774f537-e76e-4344-9863-14cee6558a68', 'ce2a4fd3-8565-4bb7-8007-6d428cb2c006', 'en', 'Double Kettlebell Front Rack Box Pistol Squat', 'Hold two kettlebells in the rack position. Perform a single-leg squat lowering until you lightly touch a box and stand back up while maintaining balance.'),
('5e80fa74-87c6-4622-bb47-29c092271696', 'ce2a4fd3-8565-4bb7-8007-6d428cb2c006', 'es', 'Sentadilla Pistola a cajón Front Rack con Kettlebell doble', 'Sostén dos Kettlebells en posición rack. Realiza una sentadilla a una pierna bajando hasta tocar ligeramente un cajón y vuelve a subir manteniendo el equilibrio.'),
('f4e4f0de-ca4e-4e1f-8606-fbf487126179', 'ce2bdf11-6f3b-49a2-b267-ff646ba8e738', 'en', 'One-Leg Rollout', 'Rollout maintaining one leg raised off the floor. Adds balance component and increases core activation. Start from knees with one leg extended. Alternate legs for balanced work.'),
('dcf5c6ea-48dc-4397-9fc1-2786dddc1511', 'ce2bdf11-6f3b-49a2-b267-ff646ba8e738', 'es', 'Rodamiento una pierna', 'Roll out manteniendo una pierna elevada del suelo. Añade componente de equilibrio y aumenta la activación del core. Comienza desde rodillas con una pierna extendida. Alterna piernas para trabajo equilibrado.'),
('49375a34-3f3a-46f6-b1c9-ee034b90b939', 'ce35d826-1a54-47ec-bf32-4fab8249b5e8', 'es', 'Wall ball', 'Realiza una sentadilla sosteniendo el balón frente al pecho, y al subir lánzalo hacia un objetivo alto en la pared. Recíbelo y continúa con la siguiente repetición. Ejercicio metabólico completo muy usado en CrossFit.'),
('07297570-7b0b-4304-b743-4ef8119df69d', 'ce74e73c-8db8-46ed-bc9d-989b5f4f7602', 'en', 'Medicine Ball Feet Elevated Russian Twist', 'Keep your feet off the ground and rotate your torso while holding a medicine ball, taking it from one side to the other under control.'),
('863d1267-88cd-47eb-a039-ce65685ab1df', 'ce74e73c-8db8-46ed-bc9d-989b5f4f7602', 'es', 'Russian Twist con pies elevados y Balón medicinal', 'Mantén los pies sin tocar el suelo y gira el torso sujetando un balón medicinal, llevándolo de un costado al otro bajo control.'),
('4c96cde5-c63d-465f-b4fd-38bf3d69de04', 'ce80c510-2fd3-4e75-a56d-a83925f724f2', 'es', 'Peso muerto una pierna cable', 'RDL unilateral con cable bajo. La resistencia horizontal del cable añade componente de estabilización único. Excelente para equilibrio y propiocepción. Mantén cadera de la pierna de trabajo hacia atrás.'),
('b03576c6-f4f2-444d-984f-770e87976994', 'ce9e9b23-ba59-4c9b-ad95-787a426c1163', 'en', 'Calf Raises', 'Standing with feet hip-width apart, rise onto the toes while contracting the calves to the maximum. Hold the top position for a second and descend in a controlled manner without the heels touching the ground completely. You can perform it on a step for greater range of motion.'),
('12635852-b2bb-41ed-bf12-0eaa0fbda681', 'ce9e9b23-ba59-4c9b-ad95-787a426c1163', 'es', 'Elevaciones de pantorrilla', 'De pie con los pies al ancho de las caderas, elévate sobre las puntas de los pies contrayendo los gemelos al máximo. Mantén la posición superior por un segundo y desciende controladamente sin que los talones toquen completamente el suelo. Puedes realizarlo en un escalón para mayor rango de movimiento.'),
('610d14d9-5947-4c17-a904-e4108e810f1a', 'ced898b0-5381-4371-b713-2ed7adbf32c8', 'en', 'Close Grip Push Ups', 'Push-ups with hands shoulder-width apart and elbows tucked in. Objective: triceps. Cue: brush the sides of your body. Error: flaring elbows out.'),
('10b4a53a-356a-4594-8616-1c9d6b9ae6ea', 'ced898b0-5381-4371-b713-2ed7adbf32c8', 'es', 'Flexiones cerradas', 'Flexiones manos ancho hombros codos pegados. Objetivo: tríceps. Cue: roza costados. Error: abrir codos.'),
('c42807bc-57fd-47e5-ab5f-d0932ad13010', 'cf3b38a4-f312-4354-96f9-9a6bc21df0d0', 'es', 'Press banca barra', 'Túmbate en banco plano con los pies firmemente plantados. Agarra la barra con las manos más separadas que el ancho de los hombros. Desciende la barra controladamente hasta tocar ligeramente el pecho y presiona explosivamente hasta la extensión completa. Mantén los omóplatos retraídos.'),
('b88f3e68-c87f-4aa7-b606-ddbac1e9f9fe', 'cf3b3907-2892-45e3-aadd-e849008fdfe8', 'en', 'Dumbbell Lunges', 'With a dumbbell in each hand at the sides, perform lunges keeping the torso upright. The additional weight increases the exercise intensity and challenges balance more. You can perform static, alternating, or walking lunges.'),
('423f9d17-0ba3-4686-9c42-f26aa9bdbae5', 'cf3b3907-2892-45e3-aadd-e849008fdfe8', 'es', 'Zancadas mancuernas', 'Con una mancuerna en cada mano a los lados, realiza zancadas manteniendo el torso erguido. El peso adicional aumenta la intensidad del ejercicio y desafía más el equilibrio. Puedes realizar zancadas estáticas, alternadas o caminando.'),
('abde7cc5-d25e-4206-ad24-325bd018d078', 'cf5bd36f-7f48-4d31-a636-7c862ed46e97', 'en', 'TRX Triceps Extensions', 'Leaning forward holding the TRX, flex elbows to bring hands to the forehead and extend. Objective: triceps. Cue: elbows always pointing forward. Error: arching the lower back.'),
('f376f521-b2d4-4323-bacc-6891b3ca03da', 'cf5bd36f-7f48-4d31-a636-7c862ed46e97', 'es', 'Extensiones de tríceps en TRX', 'Inclinado hacia adelante sujetando el TRX, flexiona codos para llevar las manos a la frente y extiende. Objetivo: tríceps. Cue: codos siempre apuntando adelante. Error: arquear la espalda baja.'),
('33f70d4b-4a18-4585-9b23-7b47ba60bace', 'cf9095c2-23e7-400a-ac43-ca373a432ca2', 'es', 'Press Z con agarre aplastante y mancuernas', 'Siéntate en el suelo con las piernas extendidas en V. Sostén una mancuerna con ambas manos presionándola contra el pecho y empújala verticalmente sobre la cabeza sin apoyar la espalda.'),
('6411c7b9-31d2-4324-97b5-9c7734f8b93a', 'cfca28d9-82b7-414c-bdfb-ac76e8627d8e', 'en', 'Bodyweight Seated Ab Circles', 'Sit on the floor with hands supported behind you and legs raised. Draw large circles in the air with both feet together, maintaining control from the abdomen.'),
('d34a7ee9-15e3-4a4d-83e5-5e612fb54c94', 'cfca28d9-82b7-414c-bdfb-ac76e8627d8e', 'es', 'Círculos abdominales sentado', 'Siéntate en el suelo con las manos apoyadas atrás y las piernas levantadas. Dibuja círculos grandes en el aire con ambos pies juntos, manteniendo el control desde el abdomen.'),
('c453af7d-93b0-4349-a571-55457bcae38c', 'cfe4db42-291a-43c5-9b5b-efc66fead217', 'en', 'Weighted Box Jump', 'Jump onto a box with a vest or dumbbells. Maximum explosive power. Cue: land with extreme softness. Common error: using too much weight that compromises height.'),
('3d20e98f-77ba-4b5d-af22-78264e852541', 'cfe4db42-291a-43c5-9b5b-efc66fead217', 'es', 'Salto al cajón lastrado', 'Salta a un cajón con chaleco o mancuernas. Máxima potencia explosiva. Cue: aterriza con suavidad extrema. Error común: usar demasiado peso que comprometa la altura.'),
('0c78f1e2-4dd3-4fa5-a4b8-2ca3c560c706', 'cfec5336-d5ab-424e-80de-4cc29e51342f', 'en', 'Alternating Single Arm Dumbbell Pendlay Row', 'With the torso parallel to the ground, row one dumbbell from the floor to your side while the other rests, alternating arms.'),
('2fb805ae-f56a-4939-b318-1b49dc745980', 'cfec5336-d5ab-424e-80de-4cc29e51342f', 'es', 'Remo Pendlay alterno con mancuerna a una mano', 'Con el torso paralelo al suelo, rema una mancuerna desde el suelo hasta el costado mientras la otra descansa, alternando brazos.'),
('b63fa2f8-cecc-4b56-b0ef-754a7fd7f436', 'd03556f4-9f18-4b8c-b45d-d91b13bd6848', 'en', 'Elastic Band Shoulder Dislocations', 'Hold the band with a wide grip and pass it over your head toward your back and back again, keeping arms straight to gain mobility.'),
('27581815-8fc7-4928-9abc-9520013fe32f', 'd03556f4-9f18-4b8c-b45d-d91b13bd6848', 'es', 'Dislocaciones de hombro con banda elástica', 'Sujeta la banda con un agarre ancho y pásala sobre tu cabeza hacia la espalda y de regreso, manteniendo los brazos rectos para ganar movilidad.'),
('26236740-74e1-4d44-83ae-3b61aeb7dc55', 'd056d3a0-07ad-4a63-9534-741039c5c63f', 'en', 'Battle Ropes Reverse Lunge', 'Backward lunges while maintaining constant waves. Challenging coordination between upper and lower body. Keep the torso upright and waves consistent. Alternate legs while maintaining the rhythm.'),
('169c1033-8e1b-4a2e-b811-697f5a6dde59', 'd056d3a0-07ad-4a63-9534-741039c5c63f', 'es', 'Zancada posterior battle ropes', 'Zancadas hacia atrás mientras mantienes ondas constantes. Coordinación desafiante entre tren superior e inferior. Mantén el torso erguido y las ondas consistentes. Alterna piernas manteniendo el ritmo.'),
('909f7aa3-8dbe-4f4d-ad68-2e7bcc5abb09', 'd076c1c3-db7b-4e3d-a680-7d3c6fbbc950', 'en', 'Neutral Pull-ups', 'Uses parallel bars or neutral grips where palms face each other. This position is more natural for the wrists and allows for balanced work between lats and biceps. Lift the body keeping elbows close to the torso and descend controlled to full extension.'),
('efe8a4d0-9aad-48e0-bea9-a8fa4f641834', 'd076c1c3-db7b-4e3d-a680-7d3c6fbbc950', 'es', 'Dominadas neutras', 'Utiliza barras paralelas o agarres neutros donde las palmas se miran entre sí. Esta posición es más natural para las muñecas y permite un trabajo equilibrado entre dorsales y bíceps. Eleva el cuerpo manteniendo los codos cerca del torso y desciende controladamente hasta la extensión completa.'),
('6391ca45-3b72-4c01-97db-3e3f4b888898', 'd09f5ade-8587-4362-b44e-a5ba7e60ce52', 'en', 'TRX Crunch', 'In a plank position with feet in the straps, bring knees toward the chest performing a hip and spine flexion. TRX instability intensifies abdominal work. Control the return to the starting position.'),
('14e92005-f477-47bd-a1b9-20c54684301d', 'd09f5ade-8587-4362-b44e-a5ba7e60ce52', 'es', 'Crunch TRX', 'En plancha con pies en las correas, lleva las rodillas hacia el pecho realizando una flexión de cadera y columna. La inestabilidad del TRX intensifica el trabajo abdominal. Controla el retorno a la posición inicial.'),
('03190c06-7ad3-4419-89de-326915837105', 'd0d6afab-af7d-4738-9136-510e8c5abebd', 'en', 'Seated Barbell Soleus', 'Bar on thighs while seated, raise heels. Objective: soleus. Cue: full range. Error: short range.'),
('0044cba7-88ed-4072-b931-fe2c60843a37', 'd0d6afab-af7d-4738-9136-510e8c5abebd', 'es', 'Sóleo sentado barra', 'Barra en muslos sentado, eleva talones. Objetivo: sóleo. Cue: rango completo. Error: rango corto.'),
('e4dfa234-f316-419c-ba05-66f605ce1cd1', 'd0fc4110-985d-4f9c-a2f1-804ecb870b25', 'en', 'Ring Hanging Leg Raise', 'Hang from the rings. Keeping legs straight and together, lift them until they are parallel to the floor or higher using abdominal strength.'),
('0cf84d52-dcd4-440b-9ad6-7326786d9005', 'd0fc4110-985d-4f9c-a2f1-804ecb870b25', 'es', 'Elevación de piernas colgado en anillas', 'Cuélgate de las anillas. Manteniendo las piernas rectas y juntas, elévalas hasta que estén paralelas al suelo o más alto, usando la fuerza abdominal.'),
('6175129d-193b-496a-b6c8-398f4bf8da87', 'd12d829d-6b09-48f2-a57e-49d0ec96f2c8', 'en', 'Neutral Grip Seated Cable Row', 'Perform a neutral grip seated cable row. Pull the handle toward the abdomen while keeping the back stable and control the return phase.'),
('fe4920e4-32ed-4465-b6a2-971d75717b96', 'd12d829d-6b09-48f2-a57e-49d0ec96f2c8', 'es', 'Remo polea baja agarre neutro', 'Realiza un remo en polea baja con agarre neutro. Tira del agarre hacia el abdomen manteniendo la espalda estable y controla la fase de vuelta.'),
('894b608e-168c-4a0d-9a19-a05a0c3e089a', 'd1b9bf3a-70bc-4845-87b5-a036eacfa72e', 'en', 'Archer Push Ups', 'Start with hands very wide, wider than shoulders. When descending, direct body weight toward one arm while the other extends laterally. Alternate the working side with each repetition or complete sets per side. This exercise is a progression toward one-arm push-ups and requires great unilateral strength.'),
('38bcbce8-9e27-4047-bd6f-e61632583058', 'd1b9bf3a-70bc-4845-87b5-a036eacfa72e', 'es', 'Flexiones archer', 'Comienza con las manos muy separadas, más anchas que los hombros. Al descender, dirige el peso corporal hacia un brazo mientras el otro se extiende lateralmente. Alterna el lado de trabajo en cada repetición o completa series por lado. Este ejercicio es una progresión hacia las flexiones a un brazo y requiere gran fuerza unilateral.'),
('e1532fac-ca8a-4f4d-ab65-d06efd4cd7d4', 'd205ca05-20e0-497c-8e84-ad86d125250c', 'en', 'Single Arm Kettlebell Hollow Body Flutter Kicks', 'In a hollow body position, hold a kettlebell over your chest with one hand and perform flutter kicks to work the core.'),
('78c26051-ea3a-4cce-ad77-cc2eb5c35d63', 'd205ca05-20e0-497c-8e84-ad86d125250c', 'es', 'Hollow Body Flutter Kicks con Kettlebell a una mano', 'En posicion de Hollow Body, sostén una pesa rusa sobre el pecho con una mano y realiza patadas de aleteo para trabajar el core.'),
('72381e34-cf3a-44fa-b1de-0f03759a2839', 'd20b8f1b-fcbc-4206-842f-04cd579df5e7', 'en', 'Bodyweight Hollow Body Rock', 'In a Hollow Body position (lower back glued to floor, elevated limbs), rock back and forth like a cradle maintaining constant abdominal tension.'),
('472ac86a-a725-4d21-a1ae-fd0091702cf4', 'd20b8f1b-fcbc-4206-842f-04cd579df5e7', 'es', 'Hollow Body Rock', 'En posicion de Hollow Body (lumbares pegadas al suelo, extremidades elevadas), balanceate como una cuna manteniendo la tension abdominal constante.'),
('3fb9410f-ef77-45cc-9361-21aeec91f211', 'd20f418f-7140-4c79-b887-e119d4076da0', 'en', 'Single Arm Kettlebell Bottoms Up Overhead Squat', 'Maintain an upside-down kettlebell overhead with a locked arm while performing a deep squat, requiring maximum concentration and balance.'),
('5a4cf515-3b2d-4b82-bcbf-30d8f01c02b0', 'd20f418f-7140-4c79-b887-e119d4076da0', 'es', 'Sentadilla Overhead con Kettlebell a una mano Bottoms Up', 'Mantén una Kettlebell invertida sobre la cabeza con el brazo bloqueado mientras realizas una sentadilla profunda, exigiendo máxima concentración y equilibrio.'),
('92a8bd8d-b53b-4ada-8f03-760138ae0eb9', 'd21295a3-5988-4881-ba94-f6af36a502fd', 'en', 'Cable Straight Bar Spider Curl', 'Prone on an incline bench facing the pulley, perform a bicep curl with a straight bar letting arms hang vertically.'),
('ae98ffd7-32b1-47c9-9d68-cc45867be4c6', 'd21295a3-5988-4881-ba94-f6af36a502fd', 'es', 'Spider Curl con cable y barra recta', 'Boca abajo en un banco inclinado frente a la polea, realiza un curl con barra recta permitiendo que los brazos cuelguen verticalmente.'),
('cb0145d0-4656-48a7-9034-abc4ea58a03c', 'd2844d02-68cf-48a6-b0c4-81380c502537', 'en', 'Suitcase Carry', 'Walk a distance carrying a heavy dumbbell on only one side of the body. Objective: anti-lateral core stability. Cues: keep shoulders level and do not let the weight tilt you. Common error: tilting the torso away from the load.'),
('03e68c2a-ecb7-4115-a55e-f7a289197606', 'd2844d02-68cf-48a6-b0c4-81380c502537', 'es', 'Paseo de maleta (Suitcase Carry)', 'Camina una distancia cargando una mancuerna pesada en un solo lado del cuerpo. Objetivo: estabilidad anti-lateral del core. Cues: mantén los hombros nivelados y no permitas que el peso te incline. Error común: inclinar el torso hacia el lado opuesto a la carga.'),
('ebc1889a-d85b-4279-b77b-15341faeadc1', 'd28b4f5d-ea14-462a-bc88-13fb010e14f8', 'en', 'Double Overhead Cyclist Squat with Kettlebell', 'Perform a cyclist squat maintaining two kettlebells locked overhead, requiring ankle and shoulder mobility.'),
('d407c5e0-cc8a-439e-8fc0-1d932b5b37b5', 'd28b4f5d-ea14-462a-bc88-13fb010e14f8', 'es', 'Sentadilla Ciclista Overhead con Kettlebell doble', 'Realiza una sentadilla ciclista manteniendo dos Kettlebells bloqueadas sobre la cabeza, exigiendo movilidad de tobillo y hombro.'),
('56dc4de6-ea7e-41c4-b9e7-2c4e3eaa4c3d', 'd2a24096-fea4-4d19-a58a-e8d6ea47027f', 'es', 'Pike Pushups', 'En V invertida, baja la cabeza hacia el suelo entre las manos. Progresión para hombros. Cue: codos hacia atrás. Error: apoyar la parte superior de la cabeza.'),
('0dd6432f-dffb-45dd-889a-d8b1a85c6f0a', 'd2de6f75-39ab-4b5c-a682-5889501b4a4b', 'en', 'Cable Hammer Curl', 'Using a rope attachment on a low pulley, perform curls keeping palms facing each other. This neutral grip works the brachialis and brachioradialis in addition to the bicep. Keep wrists firm and elbows glued to the body.'),
('1a84aa00-672d-43dc-b811-9899d57fcfa4', 'd2de6f75-39ab-4b5c-a682-5889501b4a4b', 'es', 'Curl martillo cable', 'Usando un agarre de cuerda en polea baja, realiza curls manteniendo las palmas enfrentadas. Este agarre neutro trabaja el braquial y braquiorradial además del bíceps. Mantén las muñecas firmes y los codos pegados al cuerpo.'),
('ed2448a4-0066-42e0-a117-b9bbf4b709e0', 'd2fa82d7-b9af-4dbc-a705-b073f7f9dbfb', 'en', 'Hurdle Jump Burpee', 'Perform a burpee and end by jumping forward over a hurdle. Cue: maximum jump height after the burpee. Common error: lack of energy to clear the hurdle.'),
('0a4d431e-62e2-4f83-a1eb-d8a033b3c065', 'd2fa82d7-b9af-4dbc-a705-b073f7f9dbfb', 'es', 'Burpee con salto de valla', 'Realiza un burpee y termina saltando frontalmente sobre una valla. Cue: máxima altura de salto tras el burpee. Error común: falta de energía para superar la valla.'),
('4a1b7c00-0d84-4e00-8c8e-325c3c13ac6c', 'd304a89f-9df1-4f49-a775-4da158b55edc', 'en', 'Dumbbell Shrugs', 'Lift shoulders toward ears keeping arms straight. Focus on trapezius. Head straight. Do not rotate shoulders when rising.'),
('c25719ab-0995-401f-80e5-15eb38b652ce', 'd304a89f-9df1-4f49-a775-4da158b55edc', 'es', 'Encogimientos de hombros con mancuernas', 'Eleva los hombros hacia las orejas manteniendo brazos rectos. Enfoque en trapecio. Cabeza recta. No rotes los hombros al subir.'),
('72701596-aaa2-42f0-8490-03bc784cd7e9', 'd3402384-6c36-4188-9de2-3e35cd6fdeb4', 'en', 'Farmer Carry', 'Walk a distance carrying heavy dumbbells at your sides. Objective: grip strength and total stability. Cue: short and firm steps. Common error: shrugging shoulders up.'),
('b077b24e-9707-4b2a-b8f4-ac4b0089e7f9', 'd3402384-6c36-4188-9de2-3e35cd6fdeb4', 'es', 'Paseo del granjero (Farmer Carry)', 'Camina una distancia cargando mancuernas pesadas a los lados. Objetivo: fuerza de agarre y estabilidad total. Cue: pasos cortos y firmes. Error común: encoger los hombros hacia arriba.'),
('b24b2c8b-0f8d-4698-8349-a3aae8169f16', 'd350c24e-b886-42d4-908f-da675fffbd6f', 'en', 'Vertical Jump to Deep Squat', 'Jump and immediately descend into a controlled deep squat upon landing. Cue: nail the heels when landing. Common error: knees collapsing during cushioning.'),
('5590ff60-470b-42ce-9a57-bb8035096efd', 'd350c24e-b886-42d4-908f-da675fffbd6f', 'es', 'Salto vertical sentadilla profunda', 'Salta y al aterrizar baja inmediatamente a una sentadilla profunda controlada. Cue: clava los talones al aterrizar. Error común: rodillas colapsadas al amortiguar.'),
('1ae78aa4-801c-4fe5-aa65-d41ae67d263a', 'd390c896-e1b7-454d-8aa0-4e083b7f089e', 'en', 'Neutral Lat Pulldown', 'Pull the bar toward the chest with palms facing each other (neutral grip). Objective: lat width. Cue: elbows down. Common error: swinging the torso backward to assist.'),
('6780ba19-0684-4f7a-bd50-2ad2cf196018', 'd390c896-e1b7-454d-8aa0-4e083b7f089e', 'es', 'Jalón al pecho neutro', 'Tira de la barra hacia el pecho con palmas enfrentadas (agarre neutro). Objetivo: amplitud dorsal. Cue: codos hacia abajo. Error común: balancear el torso hacia atrás para ayudar.'),
('dd483320-0189-45b0-bb0f-341c4f932a85', 'd39f2d8e-008a-40a2-829c-cad334e4ebbc', 'en', 'Seated Low Pulley Row', 'Pull the handle toward the abdomen keeping the back straight. Cue: prior scapular retraction. Error: hunching the back when stretching arms.'),
('275cd53d-0d1e-4eae-9d82-fe73e7016538', 'd39f2d8e-008a-40a2-829c-cad334e4ebbc', 'es', 'Remo en polea baja sentado', 'Tira del agarre hacia el abdomen manteniendo la espalda recta. Cue: retracción escapular previa. Error: encorvar la espalda al estirar brazos.'),
('4dc25f4f-3455-4475-90e2-35f4814b0f6b', 'd43d143f-f82a-4039-8963-ab0643c7eac8', 'en', 'TRX Archer Push Ups', 'Push-ups directing weight toward one arm with feet in TRX. Combines unilateral challenge with instability. Advanced progression toward one-arm push-ups. Control movement speed.'),
('a77d3a39-a7aa-4040-b430-661437af485e', 'd43d143f-f82a-4039-8963-ab0643c7eac8', 'es', 'Flexiones archer TRX', 'Flexiones dirigiendo el peso hacia un brazo con pies en TRX. Combina el desafío unilateral con inestabilidad. Progresión avanzada hacia flexiones a un brazo. Controla la velocidad del movimiento.'),
('8dc9fae0-cb91-4bf9-8d32-f479f6eac846', 'd4623027-a223-4c6f-af94-133c4105ae1a', 'en', 'Alternating Single Arm Kettlebell Clean', 'Clean the kettlebell from the floor to the rack position, alternating arms each rep through a fluid hip movement.'),
('1fb8e8f1-995b-4b59-8ff4-97ac5bb7243a', 'd4623027-a223-4c6f-af94-133c4105ae1a', 'es', 'Clean con Kettlebell alterno a una mano', 'Lleva la Kettlebell desde el suelo hasta la posicion de rack, alternando el brazo en cada repeticion mediante un movimiento fluido de cadera.'),
('55c365c7-82f8-419c-8e88-623deb2a438d', 'd46ed7f4-cbb3-49b9-b25a-665d23a78aa3', 'en', 'Single Arm Dumbbell Overhead Contralateral Knee Over Toe Split Squat', 'Perform a split squat with a dumbbell overhead on the opposite side, allowing the front knee to travel forward over the toes.'),
('b91dcdc8-7733-4d76-9558-01d9b5de107f', 'd46ed7f4-cbb3-49b9-b25a-665d23a78aa3', 'es', 'Sentadilla Split Overhead contralateral rodilla sobre punta del pie', 'Realiza una sentadilla split con mancuerna sobre la cabeza en el lado opuesto, permitiendo que la rodilla delantera avance sobre los dedos del pie.'),
('35a82ef8-8585-4f5b-95e3-3a8195ffe5c3', 'd4758898-438c-4bad-b2ea-d4fc94a3a3b0', 'en', 'Lateral Dumbbell Woodchopper', 'Diagonal movement from bottom to top with a dumbbell. Cue: pivot foot. Error: arching lower back.'),
('fa76c356-cbd8-46ac-81eb-8a29204420e1', 'd4758898-438c-4bad-b2ea-d4fc94a3a3b0', 'es', 'Leñador con mancuerna lateral', 'Movimiento diagonal de abajo a arriba con mancuerna. Cue: pivota pie. Error: arquear lumbar.'),
('5036676d-0895-4eca-acc5-8108eec8e985', 'd4a077ae-51ba-414c-b800-d8db094bacf1', 'en', 'Strict Dragon Flag', 'Lying down, grab a fixed point behind the head and lift the entire body in a straight line supported only on shoulders. Objective: extreme abdominal strength. Cues: body rigid as a beam. Common error: bending the hip when rising or lowering.'),
('db42b810-11b8-4736-aa2e-8c9e22a06998', 'd4a077ae-51ba-414c-b800-d8db094bacf1', 'es', 'Dragon Flag estricto', 'Tumbado, agarra un punto fijo tras la cabeza y eleva todo el cuerpo en línea recta apoyado solo en hombros. Objetivo: fuerza abdominal extrema. Cues: cuerpo rígido como una viga. Error común: doblar la cadera al subir o bajar.'),
('2e108331-e6a3-4fc0-a40c-5df52aae9830', 'd4a806c3-39fa-4065-b182-c524b23179b5', 'en', 'Seated Elastic Band Row', 'Seated with legs straight, loop the band around your feet and pull the ends toward your abdomen. Objective: mid-back. Cue: chest out and retract scapulae. Error: shrugging shoulders up.'),
('58e8317e-e449-4105-a556-0292f7843cf3', 'd4a806c3-39fa-4065-b182-c524b23179b5', 'es', 'Remo con banda elástica sentado', 'Sentado con piernas estiradas, rodea los pies con la banda y tira de los extremos hacia tu abdomen. Objetivo: espalda media. Cue: saca pecho y retrae escápulas. Error: encoger los hombros hacia arriba.'),
('a2f1e2b3-f122-4a63-a246-ba3a10b23f16', 'd4bc3ae1-131e-420e-a9ff-c7c88ea92394', 'en', 'Cable Gluteus Medius Kickback', 'With the strap on the ankle, move the leg back and slightly outward. Objective: gluteus maximus and medius. Cues: do not arch the lower back. Common error: using torso momentum to move the weight.'),
('3113bab8-fa19-4adb-b889-8e58798e209f', 'd4bc3ae1-131e-420e-a9ff-c7c88ea92394', 'es', 'Patada de glúteo medio en cable', 'Con el estribo en el tobillo, desplaza la pierna hacia atrás y ligeramente hacia afuera. Objetivo: glúteo mayor y medio. Cues: no arquees la espalda baja. Error común: usar el impulso del tronco para mover el peso.'),
('efc97697-1a0e-485b-9337-85bcda5ed319', 'd4d52eda-120f-4a3f-9051-19d7c6ad66dc', 'en', 'One-Arm Landmine Split Clean to Split Jerk', 'Perform an explosive single-arm clean followed by a jerk receiving the weight in a split position, using a Landmine bar.'),
('076e54bf-a7a3-490f-8885-8a972c0ce455', 'd4d52eda-120f-4a3f-9051-19d7c6ad66dc', 'es', 'Split Clean a Split Jerk a una mano en Landmine', 'Realiza una cargada explosiva a una mano seguida de un envión recibiendo el peso en posición de zancada (split), utilizando una barra Landmine.'),
('c82adb81-b62a-4225-ae84-cdbd0a5310cf', 'd4d8f878-6daf-4727-a7ae-e38c534dfa85', 'en', 'One-Arm TRX Row', 'Unilateral row that maximizes instability. Requires significant anti-rotation core strength. Allows for a greater range of motion than bilateral rows. Keep hips and shoulders square.'),
('d4ae2452-b914-44a2-9da5-0ce264b171ec', 'd4d8f878-6daf-4727-a7ae-e38c534dfa85', 'es', 'Remo un brazo TRX', 'Remo unilateral que maximiza la inestabilidad. Requiere fuerza anti-rotación significativa del core. Permite mayor rango de movimiento que remo bilateral. Mantén caderas y hombros cuadrados.'),
('8ad92732-9e8d-482b-a3c3-ddfdf839fed4', 'd4eb09d3-0aa3-4b34-ae4a-97897fa30a70', 'en', 'Isometric Wall Sit', 'Back supported, knees at 90 degrees, maintain position. Muscular endurance. Flat back. Do not rest hands on thighs.'),
('d76e32de-ef64-46f6-b024-4995e9f15773', 'd4eb09d3-0aa3-4b34-ae4a-97897fa30a70', 'es', 'Sentadilla isométrica pared', 'Espalda apoyada, rodillas a 90 grados, mantén la posición. Resistencia muscular. Espalda plana. No apoyes las manos en los muslos.'),
('d3dbe9f0-409f-4468-af3c-3c5b7c08df2a', 'd4fbb1e2-3903-42bb-8c52-cacb1d7392f8', 'en', 'Ring Push Up', 'Perform push-ups while holding the rings close to the ground, adding an instability component that intensely activates the chest and core.'),
('c74b2d67-1de7-4783-8964-d3574b176a26', 'd4fbb1e2-3903-42bb-8c52-cacb1d7392f8', 'es', 'Anillas Push Up', 'Realiza flexiones sujetando las anillas cerca del suelo, lo que añade un componente de inestabilidad que activa intensamente el pecho y el core.'),
('d725d2dd-c33e-4974-9829-c5ac84576aca', 'd5073fde-69bc-4c5b-b974-42d2731f9fc7', 'en', 'Reverse Crunch', 'Perform a reverse crunch lying on your back. Bring the knees toward the chest while slightly lifting the pelvis and control the lowering phase without arching the lower back.'),
('492cffc5-bd3b-4fad-902f-cdcc0767eff6', 'd5073fde-69bc-4c5b-b974-42d2731f9fc7', 'es', 'Reverse crunch', 'Realiza un reverse crunch tumbado boca arriba. Lleva las rodillas hacia el pecho elevando ligeramente la pelvis y controla la bajada sin arquear la zona lumbar.'),
('7dabe419-4673-4429-b06a-a9e0c1ab3b15', 'd52949fc-5116-4a59-a3a9-291625bf4f87', 'en', 'Squat Jump with Controlled Landing', 'Perform a jump from a squat position and land under control, absorbing impact with the hips, knees, and ankles aligned.'),
('46bcb594-0d86-45bd-a1d9-b5430421ae45', 'd52949fc-5116-4a59-a3a9-291625bf4f87', 'es', 'Squat jump con caída controlada', 'Realiza un salto desde posición de sentadilla y aterriza de forma controlada, absorbiendo el impacto con cadera, rodillas y tobillos alineados.'),
('260c7537-f5fb-4651-997e-68423ebdaa22', 'd5680a67-71ba-41c3-b87b-f32d2e4e11a2', 'en', 'Suitcase Kettlebell Slider Lateral Lunge', 'Hold two kettlebells at the sides and slide one foot laterally on a slider, lowering the hip while the other leg remains straight.'),
('d3848030-e520-47cd-9a3c-fc24f93972ad', 'd5680a67-71ba-41c3-b87b-f32d2e4e11a2', 'es', 'Zancada lateral con Slider y Kettlebell (Maleta)', 'Sostén dos Kettlebells a los lados y desliza un pie lateralmente sobre un slider, bajando la cadera mientras la otra pierna permanece recta.'),
('044a7253-b89e-440a-a8ad-d0947cce4166', 'd5a8809a-ff94-4108-9b5c-9ea633c115b8', 'en', 'Straight Bar Front Raises', 'Lift bar forward. Objective: anterior deltoid. Cue: do not use hips. Error: arching back.'),
('05f8f653-45cb-4aae-914f-f25902445f78', 'd5a8809a-ff94-4108-9b5c-9ea633c115b8', 'es', 'Elevaciones frontales barra recta', 'Eleva barra al frente. Objetivo: deltoide anterior. Cue: no usar cadera. Error: arquear espalda.'),
('6ad3a61e-2ec9-439e-9905-cfcfe6c148aa', 'd5b2af46-a4ed-4b3c-9971-c897eb45b195', 'en', 'Alternating Double Kettlebell Prone Row', 'Lying face down, row the kettlebells alternately toward the hip, keeping the torso stable and avoiding unnecessary rotations.'),
('d87d914d-a42b-4892-ae96-4dd89588b18a', 'd5b2af46-a4ed-4b3c-9971-c897eb45b195', 'es', 'Remo prono alterno con Kettlebell doble', 'Tumbado boca abajo, rima las pesas rusas de forma alternada hacia la cadera, manteniendo el torso estable y evitando rotaciones innecesarias.'),
('66b17c3d-ebc2-42f4-8402-7f4c7219563b', 'd5bd933e-b570-4ede-acf4-b9f3a0e64aa7', 'en', 'Russian Twist', 'Seated with feet in the air, rotate the torso from side to side with a weight. Objective: oblique strength. Cue: rotate the shoulders, not just the arms. Common error: excessively hunching the back.'),
('9b936163-3bd4-44b6-990d-4eca45d26004', 'd5bd933e-b570-4ede-acf4-b9f3a0e64aa7', 'es', 'Giro ruso (Russian Twist)', 'Sentado con pies en aire, gira el torso de lado a lado con un peso. Objetivo: fuerza de los oblicuos. Cue: gira los hombros, no solo los brazos. Error común: encorvar excesivamente la espalda.'),
('cd807a40-1882-4018-904c-abb567be8238', 'd5d9da31-3414-4235-a97d-b3ca99eb71a2', 'en', 'TRX Single Leg Squat', 'Single-leg squat assisted with TRX. The straps provide the necessary support to maintain balance while working on the movement pattern. Progression toward the full pistol squat.'),
('4e6f7371-62da-41f8-af47-7b9f4bd8b053', 'd5d9da31-3414-4235-a97d-b3ca99eb71a2', 'es', 'Single leg squat TRX', 'Sentadilla a una pierna asistida con TRX. Las correas proporcionan el apoyo necesario para mantener el equilibrio mientras trabajas en el patrón de movimiento. Progresión hacia la sentadilla pistol completa.'),
('8f3bf62d-72dc-490d-8b97-4d4a7c9c3813', 'd61a09a4-e0f9-45f7-8e33-64fa312c79c5', 'en', 'Cable Lateral Raises', 'Lift the cable laterally behind the body for more tension. Descent control. Shoulder down. Do not use the trapezius excessively.'),
('886b2c98-1ba5-4d63-adc0-c7c6bdfb99d5', 'd61a09a4-e0f9-45f7-8e33-64fa312c79c5', 'es', 'Elevaciones laterales en polea', 'Eleva el cable lateralmente por detrás del cuerpo para mayor tensión. Control de bajada. Hombro bajo. No uses el trapecio excesivamente.'),
('6e5c6c3b-802e-4b66-b031-578d50de04c0', 'd647a097-fc37-4394-acdb-314df0b50ba6', 'es', 'Wrist curl barra', 'Sentado con los antebrazos apoyados en los muslos o un banco, realiza flexiones de muñeca con la barra. Puedes hacerlo con agarre supino para flexores o prono para extensores. Permite que la barra ruede hasta los dedos para mayor rango de movimiento.'),
('df460422-d716-4842-bdaa-295c448d1e0e', 'd64b749b-6234-41fa-9f0b-5d681fd6e289', 'en', 'Double Kettlebell Bottoms Up Seesaw Z Press', 'Seated on the floor, alternate the vertical press of two upside-down kettlebells in a see-saw motion, removing all momentum.'),
('294a95c5-2fab-4e25-be93-2e3376d28a32', 'd64b749b-6234-41fa-9f0b-5d681fd6e289', 'es', 'Press en Z con balancín doble de abajo hacia arriba con pesa rusa', 'Sentado en el suelo, alterna el press vertical de dos Kettlebells invertidas en movimiento de balancín, eliminando todo impulso.'),
('d342b1b5-c573-4813-983c-3535d56116bc', 'd6663af4-0b56-48fb-a7d8-7a7404d35569', 'en', 'One-Leg Chest Toss', 'Throw the medicine ball from the chest while balancing on a single leg. Extreme stability. Cue: very tight core. Common error: losing balance before the throw.'),
('a7f37e92-80b5-420b-907f-70aa50d5ea10', 'd6663af4-0b56-48fb-a7d8-7a7404d35569', 'es', 'Lanzamiento pecho una pierna', 'Lanza el balón medicinal de pecho mientras te mantienes en equilibrio sobre una sola pierna. Estabilidad extrema. Cue: core muy apretado. Error común: perder el equilibrio antes del lanzamiento.'),
('c3b2cabb-3b99-457b-a4f1-2d6b7a74eaa0', 'd67e21a3-9354-4861-84f3-74b41bcde6ac', 'en', 'Unilateral Low Pulley Bicep Curl', 'Flex cable with one arm. Cue: fixed elbow. Error: swinging the body.'),
('e6d78cf1-4f31-4e17-b0e7-d5a30f592894', 'd67e21a3-9354-4861-84f3-74b41bcde6ac', 'es', 'Curl bíceps unilateral polea baja', 'Flexiona cable a un brazo. Cue: codo fijo. Error: balancear cuerpo.'),
('fef8add2-4fda-4b45-ad9f-9afba01105f4', 'd6801b6f-dbb9-46aa-aaf5-5aa872d52a95', 'en', 'Alternating Superman', 'Lying face down, simultaneously lift the right arm and left leg, alternate sides. Objective: lower back strengthening and coordination. Cues: look toward the floor. Common error: performing sudden jerks with the neck.'),
('9fbfbfe8-ce64-4c8c-8836-fd1a7e40239d', 'd6801b6f-dbb9-46aa-aaf5-5aa872d52a95', 'es', 'Superman alterno', 'Tumbado boca abajo, eleva brazo derecho y pierna izquierda simultáneamente, alterna lados. Objetivo: fortalecimiento lumbar y coordinación. Cues: mira hacia el suelo. Error común: realizar tirones bruscos con el cuello.'),
('f692ed44-f2d4-4dbe-9672-e21629e16622', 'd69f1b2e-f6e2-4c6b-8d73-895a86fc3263', 'es', 'Press Arnold con mancuernas', 'Gira controlado (sin ‘tirón’). Mantén muñecas neutras y evita arquear la zona lumbar al final del recorrido.'),
('360dfe80-d1ca-461b-b472-e34420c63b7c', 'd6a89985-9d91-4801-abb4-a32a98d9481f', 'en', 'Supported Machine Bicep Curl', 'Flex arms supported on a machine. Cue: full range. Error: not fully straightening.'),
('7c194d90-9020-4d09-94d2-8c6c3e1000c8', 'd6a89985-9d91-4801-abb4-a32a98d9481f', 'es', 'Curl bíceps máquina apoyo', 'Flexiona brazos apoyados en máquina. Cue: rango total. Error: no estirar del todo.'),
('9f9fd085-78ff-4994-90fc-17ff9bdf8c66', 'd6dfcd47-1602-429d-b6ff-53e52cee37ea', 'en', 'Chest Supported Dumbbell Row', 'Face down on a 45-degree incline bench, row with dumbbells toward the hip. Objective: mid-back without lumbar load. Cue: squeeze shoulder blades at the top. Common error: lifting the chest off the bench.'),
('114801be-8f99-447a-bca9-90db530cc025', 'd6dfcd47-1602-429d-b6ff-53e52cee37ea', 'es', 'Remo apoyado en banco con mancuernas', 'Boca abajo en banco inclinado a 45 grados, rema con las mancuernas hacia la cadera. Objetivo: espalda media sin carga lumbar. Cue: junta las escápulas arriba. Error común: despegar el pecho del banco.'),
('25ba8c8b-b532-4085-890c-ca4365233616', 'd6e5fb5a-048d-4eee-841c-9922dd7673a4', 'es', 'Press Overhead con barra Z', 'Empuja la barra Z desde los hombros hasta bloquear los brazos por encima de la cabeza, manteniendo el core estable y la espalda recta.'),
('2e7956b9-9eea-4137-8a64-f987678d930b', 'd6f5b866-98e6-4cf7-83ff-3735df800be5', 'en', 'Incline Cable Behind-the-Neck V-Bar Triceps Extension', 'Leaning forward, extend cable behind the neck. Cue: closed elbows. Error: arching back.'),
('6427c206-9878-4c4b-96c2-b9aed7460837', 'd6f5b866-98e6-4cf7-83ff-3735df800be5', 'es', 'Tríceps barra V nuca cable inclinado', 'Inclinado adelante, extiende cable tras nuca. Cue: codos cerrados. Error: arquear espalda.'),
('a03f36a1-7311-48ec-ac9d-29891a996cb1', 'd6f64112-35b8-482e-807c-7e20bf4b5bfe', 'en', 'One-Arm Landmine Row', 'Stand next to the Landmine bar, lean the torso and grab the end of the bar. Pull the elbow back activating the lat.'),
('159d523b-1b0a-4ea8-b498-ae097a359de1', 'd6f64112-35b8-482e-807c-7e20bf4b5bfe', 'es', 'Remo Landmine a una mano', 'De pie junto a la barra Landmine, inclina el torso y agarra el extremo de la barra. Tira del codo hacia atrás activando el dorsal.'),
('f8255d55-0326-4717-b51c-91ce7df33f88', 'd6f92005-3cb7-4dce-904a-194fdb3a83b6', 'en', 'Double Kettlebell Front Rack Cossack Squat', 'Deep lateral squat with two kettlebells at the chest (front rack), focusing effort on adductors and trunk stability.'),
('301ebc39-0202-4654-b79f-4f0ce78c6ed8', 'd6f92005-3cb7-4dce-904a-194fdb3a83b6', 'es', 'Sentadilla cosaca Front Rack con Kettlebell doble', 'Sentadilla lateral profunda con dos pesas rusas en el pecho (front rack), enfocando el esfuerzo en los aductores y la estabilidad del tronco.'),
('6a6c7651-9403-481c-8076-ee50f08ce5d2', 'd709615b-cf3d-4e71-96f5-6377f3bbf0c5', 'en', 'Low Pulley Adductors', 'Sideways to the pulley, cross the leg in front. Internal force. Upright body. Do not lean the torso laterally.'),
('99d63cc6-238b-4a31-94cb-f3cbea3f1161', 'd709615b-cf3d-4e71-96f5-6377f3bbf0c5', 'es', 'Aductores en polea baja', 'De lado a la polea, cruza la pierna por delante. Fuerza interna. Cuerpo erguido. No inclines el torso lateralmente.'),
('67a9854a-77e0-4aee-80e3-7da78a6127de', 'd7c98411-b30f-4a3d-9ba5-082861c89166', 'en', 'Low Pulley Upright Row', 'Pull the bar to the chin with high elbows. Objective: deltoids. Cue: bar close to body. Error: jerks.'),
('1bcc6aa0-3b9c-471b-9a15-51d51732c659', 'd7c98411-b30f-4a3d-9ba5-082861c89166', 'es', 'Remo mentón polea baja', 'Tira barra al mentón codos altos. Objetivo: deltoides. Cue: barra cerca cuerpo. Error: tirones.'),
('2cb7a537-962a-4095-bd8b-ce40af1055b1', 'd839306f-d3dc-47ea-8345-d15f06fa9c2f', 'en', 'Triceps Pushdown', 'Push the pulley down locking elbows. Objective: triceps isolation. Cue: elbows glued to the sides. Common error: leaning the torso over the bar.'),
('4cd90e80-4a59-4703-9bfb-531d2a45a979', 'd839306f-d3dc-47ea-8345-d15f06fa9c2f', 'es', 'Tríceps Pushdown', 'Empuja la polea hacia abajo bloqueando codos. Objetivo: aislamiento de tríceps. Cue: codos pegados a los costados. Error común: inclinar el torso sobre la barra.'),
('f04f2313-3ea2-445b-86db-d48c04725cd6', 'd839527d-ca24-4505-b12b-15f170d3a884', 'en', 'Kettlebell Windmill', 'Weight up, lean the torso laterally to touch the opposite foot. Improves flexibility and stability. Always look at the weight. Do not bend the top knee.'),
('103b1bd3-5833-4d06-8f08-35810655a3c1', 'd839527d-ca24-4505-b12b-15f170d3a884', 'es', 'Kettlebell Windmill', 'Pesa arriba, inclina el torso lateralmente para tocar el pie opuesto. Mejora flexibilidad y estabilidad. Mira la pesa siempre. No dobles la rodilla superior.'),
('7f30748f-72a2-47b1-b1b1-b6554e9667ec', 'd84538df-3915-4bab-89f9-834e6d43ba71', 'en', 'Double Bottoms Up Overhead Cyclist Squat with Kettlebell', 'The ultimate level of stability: perform a cyclist squat with two inverted kettlebells held overhead.'),
('82329b47-684a-4d16-83c0-a1132293f57f', 'd84538df-3915-4bab-89f9-834e6d43ba71', 'es', 'Sentadilla Ciclista Overhead con Kettlebell doble Bottoms Up', 'El nivel maximo de estabilidad: realiza una sentadilla ciclista con dos Kettlebells invertidas sostenidas sobre la cabeza.'),
('52aeb0fe-d95a-4715-9714-d87e0e65da00', 'd86aa0bf-db5e-4734-a6f1-4ec524b08306', 'en', 'Alternating Double Kettlebell Incline Bench Prone Row', 'Lying face down on an incline bench, row the kettlebells alternatively toward your hip while keeping your chest supported and back neutral.'),
('7f393d97-e43f-4f05-9ba6-be68a996dcf0', 'd86aa0bf-db5e-4734-a6f1-4ec524b08306', 'es', 'Remo prono alterno en banco inclinado con Kettlebell doble', 'Boca abajo en un banco inclinado, rema las Kettlebells alternativamente hacia tu cadera manteniendo el pecho apoyado y la espalda neutra.'),
('283da7f7-548a-4c22-b5ef-c024530509f9', 'd895c492-7ed5-4f87-b480-014fa7e3a1d4', 'en', 'Fast Pogo Bounces', 'Short and fast ankle jumps minimizing contact with the ground. Cue: knees almost locked. Error: supporting with the heel.'),
('40540325-a67b-4b7a-99d0-92ccd6571658', 'd895c492-7ed5-4f87-b480-014fa7e3a1d4', 'es', 'Rebotes pogo rápidos', 'Saltos cortos y rápidos de tobillo minimizando el contacto con el suelo. Cue: rodillas casi bloqueadas. Error: apoyar el talón.'),
('5b59eeab-88de-461d-a411-662288137274', 'd8acd8cc-9abe-42b4-94fc-8d7259896526', 'en', 'Oblique Crunch on Fitball', 'Support the lower back on the fitball and perform a lateral abdominal flexion to bring the shoulder toward the opposite hip.'),
('b775c621-c146-4b47-8fb5-888c6f05e5a1', 'd8acd8cc-9abe-42b4-94fc-8d7259896526', 'es', 'Crunch oblicuo sobre Fitball', 'Apoya la zona lumbar en el Fitball y realiza una flexion abdominal lateral para llevar el hombro hacia la cadera opuesta.'),
('f2ea14ff-320d-4d37-af29-6dc69425d14f', 'd8b103b5-bda0-412f-858f-226736521490', 'en', 'Single Arm Dumbbell Overhead Contralateral Bulgarian Split Squat', 'With one foot elevated behind you, hold a dumbbell locked out overhead with the arm opposite to the front leg and perform the squat.'),
('67bc0d41-625f-49c0-98b6-99af3d05a4ae', 'd8b103b5-bda0-412f-858f-226736521490', 'es', 'Sentadilla Búlgara Overhead contralateral con mancuerna', 'Con un pie elevado atrás, sostén una mancuerna bloqueada sobre la cabeza con el brazo opuesto a la pierna delantera y realiza la sentadilla.'),
('a7448845-67c1-4485-9279-b5cc699f95a0', 'd945a5f3-2c23-4c75-b3f1-796b4d77bf5d', 'en', 'Machine Chest Flyes (Pec Deck)', 'Seated, bring the handles together in front of the chest while maintaining a slight elbow bend. Objective: pectoral isolation. Cue: squeeze at the center for 1 second. Error: allowing shoulders to hunch forward when closing.'),
('1eae5932-b588-4cbe-924e-2ae24344e303', 'd945a5f3-2c23-4c75-b3f1-796b4d77bf5d', 'es', 'Aperturas de pecho en máquina (Pec Deck)', 'Sentado, junta los agarres frente al pecho manteniendo una ligera flexión de codos. Objetivo: aislamiento de pectoral. Cue: aprieta al centro 1 segundo. Error: permitir que los hombros se adelanten al cerrar.'),
('c1713837-b446-40cc-851c-f74654dd817b', 'd95dfcbb-8a5b-4d98-80e6-e3effad229ff', 'en', 'Incline Lateral Raises', 'Lateral raise with tilted torso to focus on middle deltoid with more tension and less momentum.'),
('162340dc-34e7-4845-b0f4-6d75cf700819', 'd95dfcbb-8a5b-4d98-80e6-e3effad229ff', 'es', 'Elevaciones laterales inclinado', 'Inclínate ligeramente, sube con control sin balancear. Pausa arriba breve y baja lento para mantener tensión.'),
('1e0b34c5-517c-48ce-b4c9-ae3c5268eb70', 'd967860d-f7d9-496f-af1d-b69e1db717e4', 'en', 'TRX Face Pull', 'Pull the straps toward the face, separating hands as they approach. Excellent for rear deltoids and shoulder health. Keep elbows high and focus on external shoulder rotation at the end of the movement.'),
('b3585bf6-55bd-40c8-a991-fe269913f799', 'd967860d-f7d9-496f-af1d-b69e1db717e4', 'es', 'Face pull TRX', 'Tira de las correas hacia la cara separando las manos al acercarse. Excelente para deltoides posterior y salud del hombro. Mantén los codos altos y enfócate en la rotación externa de hombros al final del movimiento.'),
('36dad096-0ead-4e3e-ae6e-ceaa80069890', 'd9ca90bc-f940-4ae2-b261-07637f2f39ce', 'en', 'Glute Bridge Floor Press with Dumbbells', 'Maintain the high position of a glute bridge while performing a dumbbell chest press from the floor.'),
('f1f1c674-a96b-4066-bf0b-917656d8ae26', 'd9ca90bc-f940-4ae2-b261-07637f2f39ce', 'es', 'Floor Press con Puente de Glúteo y mancuernas', 'Mantén la posición alta de un puente de glúteo mientras realizas un press de pecho con mancuernas desde el suelo.'),
('073fa953-c638-4d01-ad40-1870683711d4', 'd9f65da1-4e22-4131-8235-33022687c7ca', 'en', 'Single Arm Kettlebell Overhead Contralateral Step Up', 'With one kettlebell locked out overhead, step up onto the bench with the leg opposite to the weighted arm.'),
('d33aed64-e6de-4fc9-a3c5-21d3d55f2343', 'd9f65da1-4e22-4131-8235-33022687c7ca', 'es', 'Step Up Overhead contralateral con Kettlebell a una mano', 'Con una Kettlebell bloqueada sobre la cabeza, sube al banco con la pierna opuesta al brazo que carga el peso.'),
('287ba33f-c985-4a24-8151-4d5b0e4dcec8', 'da01a117-eff6-40c8-b91e-0f6a082ec346', 'en', 'Double Kettlebell Overhead Alternating Cossack Squat', 'Perform deep lateral squats while maintaining two kettlebells locked out overhead, combining mobility and lateral stability.'),
('e3d2f199-b948-4d6a-918a-3b77c586847a', 'da01a117-eff6-40c8-b91e-0f6a082ec346', 'es', 'Sentadilla cosaca alterna Overhead con Kettlebell doble', 'Realiza sentadillas laterales profundas manteniendo dos pesas rusas bloqueadas sobre la cabeza, combinando movilidad y estabilidad lateral.'),
('d19324f9-248a-43d5-867b-c07fa2c9574f', 'da045b6f-677d-40be-9e94-bba060595f79', 'en', 'Narrow Grip Supinated Lat Pulldown', 'Seated, pull the bar toward the chest with palms facing you and hands close together. Objective: lats and biceps. Cue: pull with your elbows down. Error: excessively swinging the torso backward.'),
('f6d925dd-fd79-4839-8bc0-74dca17d5716', 'da045b6f-677d-40be-9e94-bba060595f79', 'es', 'Jalón al pecho agarre estrecho supinado', 'Sentado, tira de la barra hacia el pecho con palmas mirando hacia ti y manos juntas. Objetivo: dorsales y bíceps. Cue: tira con los codos hacia abajo. Error: balancear el torso hacia atrás excesivamente.'),
('d5a412a8-5eb0-44d8-a540-3ed6b9f47d0e', 'da119959-60cf-4990-b88b-9a512751b953', 'en', 'Kettlebell Bulgarian Split Squat', 'Bulgarian split squat with a kettlebell at the chest. Objective: unilateral. Cue: relaxed back foot. Error: leaning too much.'),
('6b998f82-5768-4003-ab65-f2639275f8c3', 'da119959-60cf-4990-b88b-9a512751b953', 'es', 'Sentadilla búlgara kettlebell', 'Split búlgaro pesa rusa al pecho. Objetivo: unilateral. Cue: pie trasero relajado. Error: inclinar mucho.'),
('14c4d378-34fd-4853-8c04-181723d979b4', 'da3ec6bd-7ad3-4cd4-a47e-aeabcd7b9e94', 'en', 'Single Arm Barbell Turkish Get Up', 'Perform the complete Turkish Get Up using a long barbell instead of a kettlebell, requiring extremely high arm stability and balance control.'),
('1398c767-03ab-4022-a5ed-40cde10a51e2', 'da3ec6bd-7ad3-4cd4-a47e-aeabcd7b9e94', 'es', 'Levantamiento turco con barra de un solo brazo', 'Realiza el levantamiento turco completo utilizando una barra larga en lugar de una pesa rusa, lo que exige un control de la estabilidad y el equilibrio del brazo extremadamente alto.'),
('51bfe593-a17a-44a7-858a-08142533a738', 'da46aac8-0c61-45d7-afb7-d648c152f59f', 'en', 'EZ Bar Curl', 'Bicep curl with EZ bar for elbow flexion with a comfortable grip, controlling swinging and using full range.'),
('0275a04c-cfe7-4cb7-8f8d-c5ae8ddd6ea5', 'da46aac8-0c61-45d7-afb7-d648c152f59f', 'es', 'Curl con barra Z', 'Codos fijos, sube sin echarte atrás. Baja controlado y evita acortar rango para que cuente cada repetición.'),
('d7b29b41-1b81-468a-b1a1-378063d15433', 'da4e7188-77f2-45c5-aac9-88cefbe14840', 'en', 'Deficit Deadlift', 'Deadlift from an elevated platform of 5-10cm increasing the range of motion. Strengthens the initial portion of the lift. Requires greater mobility and strength. Progress gradually with deficit height.'),
('da6788c5-2566-4694-9554-e7ee6666f26c', 'da4e7188-77f2-45c5-aac9-88cefbe14840', 'es', 'Peso muerto deficitario', 'Peso muerto desde plataforma elevada de 5-10cm aumentando el rango de movimiento. Fortalece la porción inicial del levantamiento. Requiere mayor movilidad y fuerza. Progresa gradualmente con la altura del déficit.'),
('6d776e42-257e-4cc4-9394-46b8bbe96dfc', 'dad2da33-19f0-446d-a95a-c07bf79a0187', 'en', 'Standing Machine Hamstring Curl', 'Flex one leg toward the glute in the vertical machine. Objective: unilateral hamstring isolation. Cue: keep the thigh against the support. Common error: arching the lower back to compensate for the load.'),
('e219d271-e084-4a09-9e39-803fa0441747', 'dad2da33-19f0-446d-a95a-c07bf79a0187', 'es', 'Curl femoral de pie en máquina', 'Flexiona una pierna hacia el glúteo en la máquina vertical. Objetivo: aislamiento unilateral de isquios. Cue: mantén el muslo pegado al soporte. Error común: arquear la espalda lumbar para compensar la carga.'),
('f902a874-9bcc-4808-8431-7ba3b3867aca', 'dad96e23-2536-406d-bf22-212e10cfe803', 'en', 'Barbell Back Squat', 'With the bar resting on the upper (high bar) or posterior (low bar) trapezius, descend controlled until thighs are parallel to the floor or according to your mobility. Keep knees aligned with feet and chest upright. Push through the heels to rise.'),
('94329b1d-e8a4-4d62-9712-512cc47fe6a5', 'dad96e23-2536-406d-bf22-212e10cfe803', 'es', 'Sentadilla trasera barra', 'Con la barra apoyada en los trapecios superiores (posición alta) o posteriores (posición baja), desciende controladamente hasta que los muslos estén paralelos al suelo o según tu movilidad. Mantén las rodillas alineadas con los pies y el pecho erguido. Empuja desde los talones para subir.'),
('a73dbd5e-2734-48e7-a1c5-94439af8e6b8', 'daf0928e-afb3-4806-8611-d99df36c7a77', 'en', 'Forehead-Supported Barbell Row', 'Row with the forehead supported on a frame to avoid moving the body. Cue: flat back. Error: lifting the forehead.'),
('3026a205-6b00-4ac3-b59e-e6ea69e964cc', 'daf0928e-afb3-4806-8611-d99df36c7a77', 'es', 'Remo barra apoyo frente', 'Rema con la frente apoyada en soporte para no mover el cuerpo. Cue: espalda plana. Error: despegar la frente.'),
('d7501ece-da96-4fa8-8c8f-ce427ccc149c', 'db195625-0792-445a-ad5b-946488eebf99', 'en', 'Cross Body Hammer Curl', 'Flex dumbbell toward the opposite shoulder. Objective: brachialis. Cue: brush the body. Error: rotating torso.'),
('abb9babd-faad-41ea-9bd6-bdbe8d199fb1', 'db195625-0792-445a-ad5b-946488eebf99', 'es', 'Curl martillo cruzado pecho', 'Flexiona mancuerna hacia hombro opuesto. Objetivo: braquial. Cue: roza el cuerpo. Error: girar torso.'),
('f85629aa-9093-4965-9195-d2946b98ddad', 'db2cf571-749d-49ee-85c4-bef8cc992dce', 'en', 'Candlestick Roll Up to Tuck Jump', 'Roll back on your back, use momentum to stand up without hands and jump explosively bringing knees to chest.'),
('16111331-9cf4-4eda-bcc8-761628920508', 'db2cf571-749d-49ee-85c4-bef8cc992dce', 'es', 'Candlestick Roll Up a Tuck Jump', 'Rueda hacia atrás sobre la espalda, toma impulso para ponerte de pie sin manos y salta explosivamente llevando rodillas al pecho.'),
('788e40c7-eeee-4e22-8d30-30b8c86e80f5', 'db363b46-6810-4212-9aae-4db76537c840', 'en', 'Single Leg Hurdle Jumps', 'Jump low hurdles consecutively with a single foot. Reactive power. Maintain balance. Do not touch hurdles with your foot.'),
('bdd34396-c72d-4071-a256-55eb62207a78', 'db363b46-6810-4212-9aae-4db76537c840', 'es', 'Saltos de valla a una pierna', 'Salta vallas bajas de forma consecutiva con un solo pie. Potencia reactiva. Mantén el equilibrio. No toques las vallas con el pie.'),
('816b5154-5a95-4599-a57e-064d15b1ba38', 'db3aff51-26ed-4732-a0c5-b0237efcf731', 'es', 'Press tras nuca barra', 'Con la barra apoyada en los trapecios, presiona verticalmente por detrás de la cabeza. Desciende solo hasta la altura de las orejas para proteger los hombros. Requiere buena movilidad de hombros; no recomendado para todos debido al riesgo de lesión.'),
('8e1371d1-77df-42b6-ab3d-35f6be4acec4', 'db3eb616-db89-4cf1-9abf-8586580b4084', 'en', 'Cable Rope Triceps Extension', 'Pull the rope down separating the ends at the bottom. Objective: lateral triceps. Cue: elbows fixed to sides. Common error: bringing shoulders forward due to excess load.'),
('438961b9-7c3b-4aaf-a587-d396ef9ca373', 'db3eb616-db89-4cf1-9abf-8586580b4084', 'es', 'Extensión de tríceps en polea con cuerda', 'Tira de la cuerda hacia abajo separando los extremos al final. Objetivo: tríceps lateral. Cue: codos fijos a costados. Error común: adelantar hombros por exceso de carga.'),
('10f426d1-1826-4baf-9028-82f9accfcb5b', 'db423a97-bf42-4aab-adb9-94cdc464e6e2', 'en', 'Leg Scissors', 'Lying down, cross legs over each other alternately a few cm off the floor. Cue: lower back glued to the floor. Error: arching the lower back.'),
('03c30bb6-9941-430f-9208-ff12bd4dec21', 'db423a97-bf42-4aab-adb9-94cdc464e6e2', 'es', 'Tijeras de piernas', 'Tumbado, cruza las piernas una sobre otra alternadamente a pocos cm del suelo. Cue: lumbar pegada al suelo. Error: arquear la espalda baja.'),
('59937903-43c8-4143-8cd4-8f8b51f8ae13', 'db516847-e150-4497-a613-6f8eeb6897fd', 'en', 'Single Arm Dumbbell Turkish Get Up', 'Lie down with a dumbbell held high. Stand up step by step until standing, always keeping the arm extended and eyes on the weight, then reverse the movement.'),
('941bd9a1-6c4c-4886-8750-2bbeceb688eb', 'db516847-e150-4497-a613-6f8eeb6897fd', 'es', 'Levantamiento turco con mancuerna', 'Acuéstate con una mancuerna en alto. Levántate paso a paso hasta estar de pie, manteniendo siempre el brazo extendido y la vista en la pesa, luego invierte el movimiento.'),
('5c7270a8-abfa-471f-ba80-88820bc0fbb6', 'db61bcfd-4d39-4a77-b7b5-43e9264cd47c', 'en', 'Behind the Neck EZ Bar Triceps Extension', 'Hold the EZ bar overhead and lower it flexing elbows toward the neck. Objective: long head of the triceps. Cue: keep elbows pointing upward. Common error: arching the lower back excessively.'),
('6e9dd584-f59c-4aaf-9d89-86fbcb195685', 'db61bcfd-4d39-4a77-b7b5-43e9264cd47c', 'es', 'Extensión de tríceps tras nuca con barra Z', 'Sujeta la barra Z sobre la cabeza y bájala flexionando codos hacia la nuca. Objetivo: cabeza larga del tríceps. Cue: mantén los codos apuntando hacia arriba. Error común: arquear la espalda lumbar excesivamente.'),
('d683fe39-3c54-4fd2-84cc-6df73050799a', 'db8c1c14-64ae-4374-b0bc-744b7cdbd659', 'en', 'Double Kettlebell Sots Press', 'Sitting in the deepest part of a squat, press two kettlebells overhead, requiring great joint mobility.'),
('ada40c5f-4cd3-4f88-9332-a4bf061b1c25', 'db8c1c14-64ae-4374-b0bc-744b7cdbd659', 'es', 'Press Sots con pesa rusa doble', 'Sentado en lo mas profundo de una sentadilla, presiona dos Kettlebells sobre la cabeza, exigiendo gran movilidad articular.'),
('ba75a7a3-aa7e-4e08-9300-bdb4783460c7', 'dbcd0ecd-8629-4dac-87c6-8341ae96d4d1', 'en', 'Ankle Mobility', 'Ankle mobility work to improve dorsiflexion and control in squats, jumps, and running.'),
('7d6a1963-31d7-4e09-acf5-3350327d2091', 'dbcd0ecd-8629-4dac-87c6-8341ae96d4d1', 'es', 'Movilidad de tobillo', 'Rodilla hacia delante sin levantar el talón. Movimiento suave y progresivo, sin dolor, buscando más rango.'),
('5736ec06-f971-4dc5-99f4-4fe3594b2367', 'dbe70b82-d95d-4d31-9f2e-e57fa1b64939', 'en', 'Barbell Front Rack Step Up', 'Perform a step-up onto a bench with the bar in a front rack position, keeping elbows high and the torso vertical.'),
('bd40d946-ab75-47c2-9b95-3a307d131d33', 'dbe70b82-d95d-4d31-9f2e-e57fa1b64939', 'es', 'Step Up Front Rack con barra', 'Realiza un escalon sobre banco con la barra en posicion de rack frontal, manteniendo los codos altos y el torso vertical.'),
('d30ad4cd-abbf-4f94-861b-140ae7500962', 'dc09b508-e034-43e6-b99d-59366ef11c6b', 'es', 'TRX Y-Deltoid Fly', 'Eleva brazos en Y inclinado TRX. Objetivo: deltoide posterior/espalda alta. Cue: brazos rectos. Error: encoger hombros.'),
('9fe8e7be-6ccc-4c99-a101-a1c2e39622f1', 'dc1d6565-39c8-4574-9209-8e12b3e7df70', 'en', 'Pike Pushups', 'Adopt an inverted V position with hips raised and hands and feet on the floor. Lower your head toward the floor between your hands by flexing your elbows, then push to return to the starting position. This exercise simulates an inverted military press and is excellent for developing deltoid strength.'),
('79524002-d093-49fe-bb24-413b4f8bc952', 'dc1d6565-39c8-4574-9209-8e12b3e7df70', 'es', 'Flexiones pike', 'Adopta una posición en V invertida con las caderas elevadas y las manos y pies en el suelo. Desciende la cabeza hacia el suelo entre las manos flexionando los codos, luego empuja para volver a la posición inicial. Este ejercicio simula un press militar invertido y es excelente para desarrollar fuerza en los deltoides.'),
('778d6fa7-6a00-4041-8f68-0ec1cfd407fc', 'dc214d43-1ec2-4679-97c6-bea4d96c067f', 'en', 'Archer squats', 'Adopt a very wide stance and descend to one side, keeping most of the weight on that leg while the other remains semi-extended. It is a progression toward the pistol squat that allows for working each leg with higher intensity while maintaining some assistance.'),
('62b8a981-9573-4e3c-8516-ae46513638e6', 'dc214d43-1ec2-4679-97c6-bea4d96c067f', 'es', 'Archer squats', 'Adopta una postura muy amplia y desciende hacia un lado manteniendo la mayor parte del peso en esa pierna mientras la otra permanece semi-extendida. Es una progresión hacia la sentadilla pistol que permite trabajar cada pierna con mayor intensidad mientras mantiene algo de asistencia.'),
('33b0dc25-f2a4-4a59-a8f5-102771c83f6f', 'dc65566c-d215-498f-9912-4501b502c13d', 'en', 'Dumbbell Suitcase Lateral Lunge', 'Hold dumbbells at the sides and take a wide lateral step, flexing the knee of the moving leg while keeping the other straight.'),
('2ed527ba-90fa-45c6-a735-ab359e55bc55', 'dc65566c-d215-498f-9912-4501b502c13d', 'es', 'Zancada lateral con mancuernas (Maleta)', 'Sostén las mancuernas a los lados y da un paso amplio lateral, flexionando la rodilla de la pierna que desplazas mientras mantienes la otra recta.'),
('b4321e81-d121-49a8-9427-55553584c0e0', 'dce2e47c-1f63-49f2-ad28-359bf23e3672', 'en', 'Kettlebell Snatch', 'Bring the kettlebell from the floor to overhead in one explosive continuous movement. Combines swing with press in one fluid motion. Requires perfect technique to avoid injury. Develops total body power.'),
('e154c17e-63fa-4a74-aab0-32aef3395806', 'dce2e47c-1f63-49f2-ad28-359bf23e3672', 'es', 'Arranque kettlebell', 'Lleva la kettlebell desde el suelo hasta sobre la cabeza en un movimiento continuo explosivo. Combina swing con press en un solo movimiento fluido. Requiere técnica perfecta para evitar lesiones. Desarrolla potencia total del cuerpo.'),
('6982a03b-13c3-4e67-9e20-fc95edda6ec4', 'dd081b6b-5456-4b28-acbf-c2c374d58301', 'es', 'Push Jerk a una mano con mancuerna', 'Ejecuta un jerk explosivo con un solo brazo utilizando las piernas para elevar la mancuerna y estabilizar el cuerpo en la recepcion.'),
('37dbfe01-b091-4365-a494-5c262c50b5bd', 'dd0f8497-bd08-43d2-8787-f4b2670e6011', 'en', 'Bent Over Dumbbell Row', 'Lean forward with a straight back and knees slightly bent. With a dumbbell in each hand, pull toward the abdomen bringing elbows back. Squeeze shoulder blades at the top of the movement. Keep the core active.'),
('f72a66e2-3adc-4788-bf24-43693f6ffb99', 'dd0f8497-bd08-43d2-8787-f4b2670e6011', 'es', 'Remo inclinado mancuernas', 'Inclínate hacia adelante con la espalda recta y las rodillas ligeramente flexionadas. Con una mancuerna en cada mano, tira hacia el abdomen llevando los codos hacia atrás. Aprieta los omóplatos en la parte superior del movimiento. Mantén el core activado.'),
('be11399e-c271-414b-b734-487ad69f5561', 'dd39fc68-da94-4522-ae21-bfac84bf9fff', 'en', 'Weighted Pistol Squat', 'Pistol squat holding dumbbell(s). The additional weight increases difficulty but can help with balance as a counterweight. Start with light weight in front. Maintain full control during the descent.'),
('fa42140b-2847-45ad-9ecb-9ce0ca343633', 'dd39fc68-da94-4522-ae21-bfac84bf9fff', 'es', 'Sentadilla pistol con peso', 'Sentadilla pistol sosteniendo mancuerna(s). El peso adicional aumenta la dificultad pero puede ayudar con el balance como contrapeso. Comienza con peso ligero al frente. Mantén control total en el descenso.'),
('51bf48ab-b3c1-43ff-9061-11e0da35e2d3', 'dd3c5b34-a517-4ae4-a4ee-eca64b20d1df', 'en', 'Low Bar Squat', 'Bar on posterior deltoids. Objective: posterior chain. Cue: hips back. Error: chest dropping.'),
('76319dad-0a48-4e61-a085-6ec561432938', 'dd3c5b34-a517-4ae4-a4ee-eca64b20d1df', 'es', 'Sentadilla barra baja', 'Barra en deltoide posterior. Objetivo: cadena posterior. Cue: cadera atrás. Error: caer pecho.'),
('c6abd71d-8eaf-47d3-a6a4-8fbfc35a24c4', 'dd517abe-2b71-4433-99a3-fd586510dcd9', 'en', 'Single Arm Kettlebell Suitcase Ipsilateral Bulgarian Split Squat', 'Split squat with elevated foot holding the kettlebell at one side with the hand on the same side as the supporting leg.'),
('c4694316-f6d5-40f5-99db-2044fc7a58a7', 'dd517abe-2b71-4433-99a3-fd586510dcd9', 'es', 'Maleta con pesa rusa de un solo brazo, Sentadilla Búlgara búlgara ipsilateral', 'Sentadilla split con pie elevado sosteniendo la pesa rusa a un costado con la mano del mismo lado que la pierna de apoyo.'),
('08a1f015-cfcf-493b-8ec4-98ee5d29febe', 'ddcbd442-a801-4ca3-a6e3-ac03afd4d56f', 'en', 'Machine Triceps Extension', 'Seated or standing depending on the design, extend the elbows against resistance. Can be with arms overhead or at the sides. The fixed trajectory allows focusing on triceps contraction without worrying about stabilization.'),
('b2321ac1-8410-4bd6-bef1-62d74a3d9dee', 'ddcbd442-a801-4ca3-a6e3-ac03afd4d56f', 'es', 'Extensión tríceps máquina', 'Sentado o de pie según el diseño, extiende los codos contra la resistencia. Puede ser con brazos sobre la cabeza o a los lados. La trayectoria fija permite concentrarse en la contracción del tríceps sin preocuparse por la estabilización.'),
('019ac14b-5856-4aff-9157-e03eb8a7c09c', 'ddd08599-7d60-414f-86d6-f60095d0f00a', 'en', 'Alternating Single Arm Landmine Cyclist Thruster', 'Perform a landmine thruster with heels elevated, alternating the arm that presses the weight in each ascending phase of the squat.'),
('2f42e408-09dc-4ad9-bd97-4c4b25ef4b53', 'ddd08599-7d60-414f-86d6-f60095d0f00a', 'es', 'Thruster Ciclista alterno a una mano en Landmine', 'Realiza un thruster en landmine con talones elevados, alternando el brazo que empuja el peso en cada fase ascendente de la sentadilla.'),
('bf4e3fe4-08e3-4562-8df8-af38a9fcc201', 'ddd85b92-d5fe-456b-b80c-e8eeca32f6e5', 'en', 'Barbell Back Rack Cyclist Squat', 'With heels elevated on a wedge and the bar on your traps, perform a deep squat focusing the work on the quadriceps.'),
('f27a591c-60bb-4781-9683-24b6e51c63ae', 'ddd85b92-d5fe-456b-b80c-e8eeca32f6e5', 'es', 'Sentadilla Ciclista con barra tras nuca', 'Con los talones elevados sobre una cuña y la barra en los trapecios, realiza una sentadilla profunda enfocando el trabajo en los cuadriceps.'),
('c5a6fa4e-0613-4f7e-bd59-b5098f1cfdab', 'ddd8e776-9e30-44ec-b636-341786ca994c', 'en', 'Star Jump', 'Jump vertically extending arms and legs in the air forming an X. Land with feet together. Improves coordination. Cue: full extension at the highest point. Common error: landing with legs open.'),
('e1eb99bb-9dfb-4f2e-a23f-0016818030b7', 'ddd8e776-9e30-44ec-b636-341786ca994c', 'es', 'Salto de estrella', 'Salta verticalmente extendiendo brazos y piernas en el aire formando una X. Aterriza con pies juntos. Mejora la coordinación. Cue: extensión total en el punto más alto. Error común: aterrizar con piernas abiertas.'),
('26ad1bd2-4c35-4c60-a0e4-9fbdaf6d37c2', 'ddd96f77-0207-4fd6-86c7-2590ac372895', 'en', 'Ring L Sit', 'Support yourself on the rings with locked arms and lift straight legs in front of you until they form a 90-degree angle.'),
('187f649c-bde6-4f84-8e45-90eddbf42349', 'ddd96f77-0207-4fd6-86c7-2590ac372895', 'es', 'L-Sit en anillas', 'Sostente en las anillas con los brazos bloqueados y eleva las piernas rectas frente a ti hasta formar un angulo de 90 grados.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('888b577d-e39e-432d-ab9b-5c53572b0463', 'ddf6a529-0e9f-4ce2-ac40-41995d4e299d', 'en', 'Unilateral Band Row', 'Step on the band and pull back. Cue: elbow toward the pocket. Error: rotating the torso.'),
('bb5d18f1-ca56-4fca-b639-3d689009d273', 'ddf6a529-0e9f-4ce2-ac40-41995d4e299d', 'es', 'Remo unilateral con banda', 'Pisa banda y tira hacia atrás. Cue: codo hacia el bolsillo. Error: girar el torso.'),
('6e68a349-fa5b-470f-8fa2-a91370163887', 'de18a83d-18f3-425a-aaa8-8ed503ce7823', 'en', 'Parallette Alternating Shoulder Tap Push Up', 'Perform a push-up on parallettes and, upon standing, touch the opposite shoulder with one hand while maintaining body stability on a single support.'),
('e1d5c500-10c6-4c94-bc88-c4ed6477dd2a', 'de18a83d-18f3-425a-aaa8-8ed503ce7823', 'es', 'Empuje hacia arriba con toque de hombro alterno paralelo', 'Realiza una flexion sobre paralelas y, al subir, toca el hombro opuesto con una mano manteniendo la estabilidad del cuerpo sobre un solo apoyo.'),
('2835a875-4790-42dd-8ada-138fb7f75614', 'de5d5755-9fe4-4b9d-a6fe-8d1823f2a72d', 'en', 'Barbell Squat Clean to Split Jerk', 'Perform a clean catching the bar in a full squat and finish with a jerk by splitting your legs for stability.'),
('afee6daa-6971-4109-8e96-fc4039073f3e', 'de5d5755-9fe4-4b9d-a6fe-8d1823f2a72d', 'es', 'Squat Clean a Split Jerk con barra', 'Realiza una cargada recibiendo la barra en sentadilla completa y termina con un envion dividiendo las piernas para estabilidad.'),
('d009651a-7abf-4692-8cef-04322fea74c2', 'de887dc9-59bb-4d00-820a-f6ab9bf27cbd', 'en', 'Decline Rollout', 'Rollout with knees or feet elevated on a bench or box. The decline angle significantly increases difficulty. Start with small elevations and progress. Maintain full control in both phases.'),
('f9b26765-b2b0-439a-964d-f74aa471f441', 'de887dc9-59bb-4d00-820a-f6ab9bf27cbd', 'es', 'Rodamiento declinado', 'Roll out con rodillas o pies elevados en banco o caja. El ángulo declinado aumenta significativamente la dificultad. Comienza con elevaciones pequeñas y progresa. Mantén control total en ambas fases.'),
('3e0550ba-2b1e-4ed5-979a-ec8d447e555b', 'de99e662-a345-4685-b786-4b97aa0410e2', 'en', 'Battle ropes jumping jacks', 'Perform jumping jacks while keeping the ropes in motion. Coordinate leg movement with the rope waves. Intense cardiovascular exercise that works the entire body simultaneously.'),
('8d18a870-d848-4b56-a440-457209290921', 'de99e662-a345-4685-b786-4b97aa0410e2', 'es', 'Battle ropes jumping jacks', 'Realiza jumping jacks mientras mantienes las cuerdas en movimiento. Coordina el movimiento de piernas con las ondas de las cuerdas. Ejercicio cardiovascular intenso que trabaja todo el cuerpo simultáneamente.'),
('03155799-509b-4684-b1a4-9711b564ca3a', 'de9f0204-e44f-49b9-bbd1-6badeb38ea5b', 'en', 'Flat Bench Leg Raises', 'Lying on your back on a flat bench, hold the edges behind the head or at the sides. Lift legs together and straight to vertical and lower them in a controlled manner without arching the lower back. Objective: lower rectus abdominis area. Cue: glue the lower back to the bench throughout the movement. Common error: letting the back arch when lowering legs.'),
('5b1f4e41-62d2-4444-a21e-324c139a1bc0', 'de9f0204-e44f-49b9-bbd1-6badeb38ea5b', 'es', 'Elevaciones de piernas en banco plano', 'Tumbado boca arriba en un banco plano, sujeta los bordes tras la cabeza o a los lados. Eleva las piernas juntas y estiradas hasta la vertical y bájalas controladamente sin arquear la zona lumbar. Objetivo: zona inferior del recto abdominal. Cue: pega la espalda baja al banco durante todo el recorrido. Error común: dejar que la espalda se arquee al bajar las piernas.'),
('ea8e7d08-923a-44ff-964b-f3bfccb5e6da', 'dec218db-d9e7-403a-99b8-e8bc5b98eeea', 'en', 'Box Jump', 'Explosively jump onto a box and land softly in a squat position. Objective: lower body power. Cue: knees out when landing. Common error: landing noisily with flat feet.'),
('6e668d23-20ca-4f47-b72b-50f6d5d61bad', 'dec218db-d9e7-403a-99b8-e8bc5b98eeea', 'es', 'Salto al cajón (Box Jump)', 'Salta de forma explosiva sobre un cajón y aterriza suavemente en posición de sentadilla. Objetivo: potencia del tren inferior. Cue: rodillas hacia afuera al caer. Error común: aterrizar ruidosamente con los pies planos.'),
('68f4d217-c6c1-4fe3-93a0-51c3dc16a675', 'ded51457-6f1c-4b07-a2bc-6c9b9839cdef', 'en', 'TRX Face Pull to Overhead Press', 'Perform a Face Pull on TRX, rotate arms upward into a Y position (press) maintaining tension, and return in a controlled manner.'),
('9b8e5823-c2ad-409e-b1b8-352dbe78d41e', 'ded51457-6f1c-4b07-a2bc-6c9b9839cdef', 'es', 'Face Pull a Overhead Press en TRX', 'Realiza un Face Pull en TRX, rota los brazos hacia arriba en posición de Y (press) manteniendo la tensión, y regresa controlado.'),
('13479593-71ce-46e9-a4d3-f055e95301c9', 'ded73726-3183-4289-838b-71234f02830b', 'en', 'Long Jump with Unilateral Landing', 'Jump forward with both feet but land and stabilize on only one. Improves eccentric braking. Cue: stick the knee without it wobbling. Common error: stiff landing that damages the knee.'),
('173083e3-a401-45d4-887e-c74d48a2b8ff', 'ded73726-3183-4289-838b-71234f02830b', 'es', 'Salto de longitud caída unilateral', 'Salta hacia adelante con ambos pies pero aterriza y estabiliza sobre uno solo. Mejora la frenada excéntrica. Cue: clava la rodilla sin que baile. Error común: aterrizaje rígido que daña la rodilla.'),
('8e3185a3-83d7-454e-98cd-81de8765042b', 'dee1372d-8418-462c-9e04-8034f960e341', 'en', 'Wide Grip Push Ups', 'Hands wider than shoulder-width. Greater pectoral emphasis. Cue: chest to the floor. Error: elbows flared too wide at 90 degrees.'),
('ac103574-f578-4b4b-b76a-52e37dc1249b', 'dee1372d-8418-462c-9e04-8034f960e341', 'es', 'Flexiones con manos anchas', 'Manos más allá de la anchura de hombros. Mayor énfasis en pectoral. Cue: pecho al suelo. Error: codos demasiado abiertos a 90 grados.'),
('46f3d51b-55bf-4c5d-947e-b59c70a54392', 'df29eefb-3b95-49b2-8d2f-f235f4551d36', 'en', 'Knee Band Skater Jump', 'Skater jumps with a band on the knees to activate the gluteus medius laterally. Cue: knee out at all times. Common error: the band pulling knees together upon landing.'),
('1b708d14-049b-490e-9ee2-0b393610bdf2', 'df29eefb-3b95-49b2-8d2f-f235f4551d36', 'es', 'Salto patinador banda rodillas', 'Saltos de patinador con banda en rodillas para activar glúteo medio lateralmente. Cue: rodilla hacia afuera siempre. Error común: que la banda cierre las rodillas al caer.'),
('8a2caa8b-ad11-49f6-9841-c09a963f0267', 'df55a42d-8b8a-4e29-8cbb-a55e5713e1d2', 'en', 'Unilateral Dumbbell RDL Balance', 'Lower the weight toward the supporting foot while raising the other leg back. Cue: flat back. Error: lateral wobbling.'),
('bd71bd3c-1cd5-4332-8dcc-4f64db9d2089', 'df55a42d-8b8a-4e29-8cbb-a55e5713e1d2', 'es', 'RDL unilateral mancuerna equilibrio', 'Baja pesa a pie apoyo elevando pierna atrás. Cue: espalda plana. Error: tambaleo lateral.'),
('90b1cfef-7874-4216-95cd-650c75b3c661', 'df9308a7-0b4e-4658-978a-624f6ff0c018', 'en', 'Kettlebell High Pull', 'Similar to the swing but actively pulling with the arm to shoulder height. The elbow should rise first, like an explosive high row. Develops upper back and shoulder power. Keep the kettlebell close to the body.'),
('2eebf186-67cc-4b16-906d-bd2aa88228f3', 'df9308a7-0b4e-4658-978a-624f6ff0c018', 'es', 'Tirón alto kettlebell', 'Similar al swing pero tirando activamente con el brazo hasta la altura del hombro. El codo debe subir primero, como un remo alto explosivo. Desarrolla potencia en la espalda alta y hombros. Mantén la kettlebell cerca del cuerpo.'),
('1deb0b34-e42d-40d5-b3e3-dec250c85205', 'df94d7f7-6816-464b-8326-6e627bf1ef7d', 'en', 'Double Kettlebell Pendlay Row', 'With the torso parallel to the floor, explosively lift two kettlebells from the floor and return them to a full stop on each rep.'),
('1dbe9acd-74f9-4228-9948-0ec85dafdee0', 'df94d7f7-6816-464b-8326-6e627bf1ef7d', 'es', 'Remo Pendlay con Kettlebell doble', 'Con el torso paralelo al suelo, levanta explosivamente dos pesas rusas desde el suelo y regrésalas a una parada completa en cada repetición.'),
('26371771-6fa6-47a1-8338-7c64982079e3', 'dfa2e7a2-181e-4ba8-b84b-5ac74d70d6bd', 'en', 'Prone Barbell Row', 'Lie face down on a high bench. Grab the bar from the floor and row toward the bench isolating the back without using momentum.'),
('e1abfb24-1a47-476f-86a6-d7e2e943bdbd', 'dfa2e7a2-181e-4ba8-b84b-5ac74d70d6bd', 'es', 'Remo prono con barra', 'Acuéstate boca abajo en un banco alto. Agarra la barra del suelo y rema hacia el banco aislando la espalda sin usar impulso.'),
('e299cf21-0126-462f-8c0f-7c0bb008dc47', 'e0065fd6-b8a6-4325-97a5-99f0b7508ba8', 'en', 'Double Kettlebell Clean to Front Rack Alternating Reverse Lunge', 'Clean two kettlebells to the rack position and alternate reverse lunges, keeping the torso upright and elbows high.'),
('2f68b8e5-d6b7-4b1f-80f3-2f915012a618', 'e0065fd6-b8a6-4325-97a5-99f0b7508ba8', 'es', 'Clean doble a Zancada inversa alterna Front Rack con Kettlebell', 'Lleva dos Kettlebells a posicion de rack y alterna zancadas hacia atras, manteniendo el torso erguido y los codos altos.'),
('36a677a9-b203-43bb-9e0f-be28f871913c', 'e0318239-bb47-4bb6-89c6-82deb48025cf', 'en', 'Battle Ropes Rhythmic Alternating Waves', 'Move ropes up and down alternating arms quickly. Objective: cardiovascular endurance. Cue: maintain partial squat. Common error: moving the torso instead of just the arms.'),
('d53c524f-928b-4d3e-9bb2-afabe6d19689', 'e0318239-bb47-4bb6-89c6-82deb48025cf', 'es', 'Battle ropes ondas alternas rítmicas', 'Mueve cuerdas arriba y abajo alternando brazos rápidamente. Objetivo: resistencia cardiovascular. Cue: mantén sentadilla parcial. Error común: mover el tronco en lugar de solo brazos.'),
('f8675a13-75d4-474f-a170-e563689bab3f', 'e0512d89-b89f-4e47-94ea-b81a3eed7700', 'es', 'Zancada búlgara mancuernas costados', 'Pie en banco, pesas a los lados. Cue: baja vertical. Error: rodilla pase mucho pie.'),
('090b7db4-6db9-4003-aad9-d1b66cbab1b0', 'e05abb5f-beec-4e9d-8359-48607e06cbd1', 'en', 'Ring Eccentric Pull Up', 'Jump or assist yourself to get to the top position of the Pull Up on rings. Lower your body very slowly (3-5 seconds) until arms are fully extended.'),
('1b7a1b0c-f2ef-4a78-9cc9-114bc4fb2376', 'e05abb5f-beec-4e9d-8359-48607e06cbd1', 'es', 'Pull Up excéntrico en anillas', 'Salta o ayúdate para subir a la posición superior del Pull Up en anillas. Baja el cuerpo muy lentamente (3-5 segundos) hasta extender los brazos por completo.'),
('b05280cf-60ad-485a-8b37-96a0ba4a97c6', 'e08b2481-e531-4aa4-8a9d-a28b00cd7592', 'es', 'Pike sobre Fitball', 'Con los pies sobre el Fitball y manos en el suelo (plancha), eleva las caderas hacia arriba rodando el balón hacia ti con las piernas rectas hasta quedar casi vertical.'),
('3735e1d5-1ee2-4965-add9-046eb54229d5', 'e0e010c1-4104-428c-9847-4b4ae9f8e3ee', 'en', 'Lying Machine Hamstring Curl', 'Flex legs while face down on the machine. Objective: hamstrings. Cues: hips glued to the bench. Common error: lifting the pelvis during flexion.'),
('bcdd2214-53ce-49f8-9561-633c234346f4', 'e0e010c1-4104-428c-9847-4b4ae9f8e3ee', 'es', 'Curl femoral acostado en máquina', 'Flexiona piernas boca abajo en máquina. Objetivo: isquiotibiales. Cues: cadera pegada al banco. Error común: levantar la pelvis al flexionar.'),
('272a7568-0516-415a-a4e5-6e1abcdf5860', 'e0f845e4-026d-48fd-a0be-3f05411cb733', 'en', 'Double Kettlebell Suitcase Bulgarian Split Squat', 'Hold two kettlebells at your sides (suitcase position) with one foot elevated on a bench. Lower your hips vertically while keeping the torso upright.'),
('723bebe0-95af-4d64-9c9b-f81ef1e7f37b', 'e0f845e4-026d-48fd-a0be-3f05411cb733', 'es', 'Sentadilla Búlgara con doble pesa rusa en posicion maleta', 'Sujeta dos Kettlebells a los costados (posicion maleta) con un pie elevado en un banco. Baja la cadera verticalmente manteniendo el torso erguido.'),
('c4ead691-b00d-4278-9bd0-cdaa76dc5218', 'e10bfa0c-cc24-4e7f-918f-e6583bd8203c', 'es', 'Puente de glúteo con banda', 'Eleva la cadera con banda sobre rodillas empujando hacia afuera. Cue: aprieta glúteos arriba. Error: arquear la zona lumbar en exceso.'),
('f7f485c8-c1d2-4101-8618-375b81d4a04a', 'e133947f-975e-45c5-bd49-6a69f5c1cd4a', 'en', 'Single Leg Romanian Deadlift Jump', 'Hinge into a single-leg Romanian deadlift and explosively jump vertically using only that leg. Land with balance.'),
('2345bca5-f0a6-47ca-82b1-59c7bb74980a', 'e133947f-975e-45c5-bd49-6a69f5c1cd4a', 'es', 'Salto de peso muerto rumano a una pierna', 'Inclínate en un peso muerto rumano a una pierna y, de forma explosiva, salta verticalmente usando solo esa pierna. Aterriza con equilibrio.'),
('e0e51598-cae9-4beb-b1e2-619d0ed7e501', 'e1520e3c-9e04-4114-ac40-cc881ad20916', 'en', 'One-Arm Medicine Ball Slam', 'Slam ball using only one arm. Requires greater core stabilization to resist rotation. Start with a lighter ball. Alternate arms. Keep the torso stable during the explosive movement.'),
('3f44f1c3-e0bf-4a5e-b954-86fbb419e57f', 'e1520e3c-9e04-4114-ac40-cc881ad20916', 'es', 'Golpeo un brazo balón medicinal', 'Slam ball usando solo un brazo. Requiere mayor estabilización del core para resistir rotación. Comienza con balón más ligero. Alterna brazos. Mantén el torso estable durante el movimiento explosivo.'),
('de79aebb-d79f-45d5-802b-9423d3ee6127', 'e152bcea-c94e-4fc8-8eb2-971eb4243cba', 'en', 'L-sit Pull-ups', 'Pull-ups while holding legs extended horizontally forming an L. Combines pulling strength with extreme isometric core work. Requires hamstring flexibility. One of the most difficult pull-up variations.'),
('69c7db49-8108-47ff-bd7b-2ee8f8ed7fcf', 'e152bcea-c94e-4fc8-8eb2-971eb4243cba', 'es', 'Dominadas en L', 'Dominadas manteniendo las piernas extendidas horizontalmente formando una L. Combina fuerza de tracción con isométrico de core extremo. Requiere flexibilidad en isquiotibiales. Una de las variaciones más difíciles de dominadas.'),
('97984ba4-5ba6-43e0-9c5e-fff8e47e3f17', 'e1678318-3724-4619-a52c-2b8cf30ee5c0', 'en', 'Seated Rotational Toss', 'Seated on the floor with legs straight, throw the ball laterally. Completely isolates the core. Cue: rotate from the waist. Common error: excessively flexing the elbows.'),
('98cdcca7-fe11-46cb-b010-819fb5b6e235', 'e1678318-3724-4619-a52c-2b8cf30ee5c0', 'es', 'Lanzamiento rotacional sentado', 'Sentado en el suelo con piernas estiradas, lanza el balón lateralmente. Aísla completamente el core. Cue: gira desde la cintura. Error común: flexionar los codos en exceso.'),
('28704a94-bf3d-4e23-9304-113939e90cd5', 'e1a95d69-4602-4eea-be79-65f79e4ae4c6', 'es', 'Tuck Jump', 'Salta verticalmente con potencia y lleva ambas rodillas hacia el pecho en el aire, aterrizando de forma suave y controlada.'),
('7a367e33-141a-45fa-9efc-2bc1b5329734', 'e2906a5f-2ef4-45a6-b12e-586a9b1281fe', 'en', 'Specific Seated Soleus Machine', 'Raise heels with knees bent against the support. Objective: soleus strength. Cue: full range of motion. Common error: bouncing the weight.'),
('67639f65-c45b-4747-9cd9-2ac1cdbf59ef', 'e2906a5f-2ef4-45a6-b12e-586a9b1281fe', 'es', 'Sóleo sentado en máquina específica', 'Eleva talones con rodillas flexionadas contra el soporte. Objetivo: fuerza del sóleo. Cue: rango de movimiento total. Error común: rebotar el peso.'),
('784f9058-735f-48e6-8fa9-81b561fdc833', 'e2918a21-058c-47b7-9291-d2022bffc4d9', 'en', 'Cable Quadruped Hip Abduction', 'On all fours sideways to the pulley, attach the cable to the outer leg and lift it laterally to work the gluteus medius.'),
('2a5d6318-e621-4213-8835-15734dbdeecb', 'e2918a21-058c-47b7-9291-d2022bffc4d9', 'es', 'Abducción de cadera cuadrúpeda con cable', 'En cuatro puntos lateral a la polea, sujeta el cable a la pierna exterior y elevala lateralmente para trabajar el gluteo medio.'),
('236c2d69-3b86-4650-a356-d78f71dda48f', 'e29735fb-352d-4467-a285-3aa124ab9208', 'en', 'Parallette Straddle Planche Push Up', 'Perform a push-up in a horizontal planche position with legs spread in a V-shape to facilitate body weight balance.'),
('338a5a0a-ddf2-4620-9a05-3ca35a5243a7', 'e29735fb-352d-4467-a285-3aa124ab9208', 'es', 'Push Up en plancha straddle en paralelas', 'Realiza una flexion en posicion de plancha horizontal con las piernas abiertas en V para facilitar el equilibrio del peso corporal.'),
('9efc974b-b089-4480-8894-da42c6c2f74c', 'e29f7821-8d69-4c30-8cbd-7d916f20fab6', 'en', 'Dumbbell Cuban Press', 'Standing with dumbbells: raise elbows (row), rotate forearms up (scarecrow), and push to the ceiling (press). Lower by reversing the steps.'),
('7f39be05-ad6f-4a31-ae5e-66691d26f064', 'e29f7821-8d69-4c30-8cbd-7d916f20fab6', 'es', 'Press Cubano con mancuernas', 'De pie con mancuernas: sube codos (remo), rota antebrazos arriba (espantapájaros) y empuja al techo (press). Baja invirtiendo los pasos.'),
('f3a4c97e-302b-4dfe-aff3-9e88d16a9546', 'e2adc7f5-ff6f-4d81-a59c-1517feb17afc', 'es', 'Pullover con maza a una mano', 'Tumbado boca arriba, lleva la maza con un brazo desde detrás de la cabeza hasta la vertical sobre el pecho, manteniendo el brazo casi estirado.'),
('ad22631c-3820-4dc2-87ea-418f23a35b58', 'e2b64ca6-6ceb-4b9a-a82f-0f0399213f42', 'es', 'Prensa pies parte superior', 'Pies arriba en plataforma. Cue: empuja talones. Error: levantar coxis.'),
('b0fb1e90-9d72-439d-9c44-9cc5fdc5508a', 'e2d5796a-1e8e-444b-b29a-ee843f68ffa2', 'en', 'Double Kettlebell Bottoms Up Front Rack Squat', 'Perform a deep squat while holding two upside-down kettlebells in a front rack position, requiring total stability control.'),
('5a281415-eaf3-4052-9fff-4b5f2347f048', 'e2d5796a-1e8e-444b-b29a-ee843f68ffa2', 'es', 'Sentadilla frontal Kettlebell doble Bottoms Up', 'Realiza una sentadilla profunda sujetando dos Kettlebells invertidas en posicion rack, exigiendo un control total de la estabilidad.'),
('bfc39f23-45a9-425b-bf23-1ef55bbbae70', 'e2e7487a-5bcd-4e81-b712-dd76e29e9c97', 'en', 'Alternating Low Grip Landmine Cossack Squat', 'Perform a deep lateral squat holding the Landmine bar at a low height, keeping the torso stable and the extended leg straight.'),
('ee7f5e84-5f78-4a68-8eb5-520d8131d687', 'e2e7487a-5bcd-4e81-b712-dd76e29e9c97', 'es', 'Sentadilla cosaca alterna agarre bajo en Landmine', 'Realiza una sentadilla lateral profunda sujetando la barra Landmine a una altura baja, manteniendo el torso estable y la pierna extendida recta.'),
('1923acf3-6c4c-49eb-a632-004575c9f2ec', 'e2f304bd-7459-42ad-9986-6af581504910', 'en', 'Cable Pectoral Crossovers', 'With pulleys at chest height, perform a hugging motion bringing hands together in front of the chest. Keep arms slightly bent throughout the movement. Constant cable tension maximizes pectoral activation.'),
('de035e99-b268-4209-9e26-bb12d23184bb', 'e2f304bd-7459-42ad-9986-6af581504910', 'es', 'Cruces pectorales cable', 'Con las poleas a la altura del pecho, realiza un movimiento de abrazo juntando las manos frente al pecho. Mantén los brazos ligeramente flexionados durante todo el movimiento. La tensión constante del cable maximiza la activación del pectoral.'),
('d4fbf417-2ba1-4ffb-bbc9-476775e12f67', 'e30f9bde-0b94-4aea-9a2d-8cbbb68805dc', 'en', 'Cable External Shoulder Rotation', 'With the elbow glued to your side and flexed at 90 degrees, rotate the forearm outward against cable resistance. Fundamental for rotator cuff health. Keep the elbow immobile and use light weight with perfect control.'),
('6b427a2b-cd8d-4c78-afa0-eed68d478a06', 'e30f9bde-0b94-4aea-9a2d-8cbbb68805dc', 'es', 'Rotación externa hombro cable', 'Con el codo pegado al costado y flexionado a 90 grados, rota el antebrazo hacia afuera contra la resistencia del cable. Fundamental para la salud del manguito rotador. Mantén el codo inmóvil y usa peso ligero con control perfecto.'),
('1748f3f9-0d72-4747-94d5-bdbddd97ab51', 'e3336cbf-5b6a-4871-8142-2e9b03da4de7', 'es', 'Press Overhead de rodillas a una mano con Kettlebell', 'Arrodillado sobre ambas piernas, presiona la pesa rusa sobre la cabeza con un solo brazo, estabilizando el tronco para evitar inclinaciones.'),
('af5e4223-353a-493f-bf48-57c55231f27c', 'e33daa15-4720-483b-a225-fc7b3389f2f3', 'en', 'Band Triceps Extension', 'Hold one end of the band overhead with a flexed arm. With the other hand, pull the other end extending the elbow completely. Keep the upper arm motionless and parallel to the floor. The band provides continuous resistance during the extension.'),
('75d30d72-6420-4889-b008-6f860e1d49ea', 'e33daa15-4720-483b-a225-fc7b3389f2f3', 'es', 'Extensión tríceps con banda', 'Sujeta un extremo de la banda sobre tu cabeza con un brazo flexionado. Con la otra mano, tira del otro extremo extendiendo el codo completamente. Mantén el brazo superior inmóvil y paralelo al suelo. La banda proporciona resistencia continua durante la extensión.'),
('0656ddee-2458-445c-a36c-ddc581ec6035', 'e33f2fd9-5cdf-4797-b1c8-6aebf12ddf2d', 'en', 'Barbell Front Squat', 'With the bar resting on the anterior deltoids and elbows elevated, perform the squat maintaining the torso more vertical than in the back squat. Requires greater wrist and ankle mobility. Emphasizes the quadriceps more and demands greater core activation.'),
('482455c8-2dbc-426e-b6b4-d76074d54a32', 'e33f2fd9-5cdf-4797-b1c8-6aebf12ddf2d', 'es', 'Sentadilla frontal barra', 'Con la barra apoyada en los deltoides anteriores y los codos elevados, realiza la sentadilla manteniendo el torso más vertical que en la sentadilla trasera. Requiere mayor movilidad de muñecas y tobillos. Enfatiza más los cuádriceps y exige mayor activación del core.'),
('cd6ab24c-7e3b-429c-aca3-063db8aedb02', 'e35f8ed7-b889-4dc8-a91f-009d47b4c7aa', 'en', 'Double Kettlebell Front Rack Pistol Squat', 'Perform a single-leg squat with two kettlebells in the rack position. The most technically demanding leg exercise with kettlebells.'),
('d274e5e3-a002-4ae7-bc94-37ae755bcb1f', 'e35f8ed7-b889-4dc8-a91f-009d47b4c7aa', 'es', 'Sentadilla Pistola Front Rack con Kettlebell doble', 'Realiza una sentadilla a una pierna con dos Kettlebells en posicion rack. El ejercicio de pierna mas demandante tecnicamente con pesas rusas.'),
('08e190f8-97df-4147-b2b1-bdefe0dbe7b8', 'e36305eb-2393-4b28-a2e5-59c93b9588b9', 'en', 'Superman Extensions', 'Face down, lift arms and legs simultaneously. Posterior chain. Smooth movement. Do not perform sudden jerks with the neck.'),
('873fcb3b-7922-4ce6-9f99-b96493063a00', 'e36305eb-2393-4b28-a2e5-59c93b9588b9', 'es', 'Superman extensiones', 'Boca abajo, eleva brazos y piernas simultáneamente. Cadena posterior. Movimiento suave. No des tirones bruscos con el cuello.'),
('5bb86b1f-20cb-43ee-a9e0-a31801c144ab', 'e363ac88-ea44-4b70-9a93-e159ae15cf2e', 'en', 'Overhead Ball Toss', 'Throw the medicine ball backward over your head with an explosive hip movement. Objective: posterior chain power. Cue: extend the hip forcefully. Common error: using too much arm and too little leg.'),
('1c00bd86-3b62-43af-81f0-276301680024', 'e363ac88-ea44-4b70-9a93-e159ae15cf2e', 'es', 'Lanzamiento overhead de balón', 'Lanza el balón medicinal hacia atrás sobre tu cabeza con un movimiento explosivo de cadera. Objetivo: potencia de la cadena posterior. Cue: extiende la cadera con fuerza. Error común: usar demasiado los brazos y poco las piernas.'),
('5c57df9d-8538-4c00-b28a-e91e8e28111b', 'e36f95d1-58d2-4655-958b-7de26cba2bbc', 'en', 'Band Resisted Skater Jump', 'Perform side-to-side lateral jumps with an elastic band anchored to the waist pulling you toward the anchor source.'),
('19292fe0-e328-4446-81ce-2e6721414f75', 'e36f95d1-58d2-4655-958b-7de26cba2bbc', 'es', 'Salto de patinador con resistencia de banda', 'Realiza saltos laterales de lado a lado con una banda elástica anclada a la cintura que te atraiga hacia el origen del anclaje.'),
('ffd6732c-936f-4399-83e1-425a7e23fe17', 'e38f4199-1c38-4682-a964-fe0483f5d3a4', 'en', 'Low Pulley Bicep Curl', 'Flex elbows pulling the cable from the low pulley. Objective: constant tension in the bicep. Cue: elbows fixed at sides. Common error: moving shoulders forward when rising.'),
('f9170cd0-20b4-4b28-b17f-6a1de6b82849', 'e38f4199-1c38-4682-a964-fe0483f5d3a4', 'es', 'Curl de bíceps en polea baja', 'Flexiona los codos tirando del cable de la polea baja. Objetivo: tensión constante en el bíceps. Cue: codos fijos a los costados. Error común: mover los hombros hacia adelante al subir.'),
('3ee47b96-867f-470a-a8fd-188fcb670b5b', 'e3da6e23-2ef7-4ec3-ab96-3ead69569bbb', 'en', 'Strict Dumbbell Preacher Curl', 'Flex weight with arm supported on bench. Cue: full stretch. Error: lifting elbow.'),
('9f4f4e01-3014-497d-af24-f9aad71731d5', 'e3da6e23-2ef7-4ec3-ab96-3ead69569bbb', 'es', 'Curl predicador mancuerna estricto', 'Flexiona pesa con brazo apoyado en banco. Cue: estira total. Error: levantar codo.'),
('80f5911b-99fd-4adc-904e-395daa5b7fcf', 'e416939b-82bf-4b95-af69-f9b35758f90d', 'en', 'Seated Band Row', 'Seated with legs extended, loop the band around your feet and row. Keep your back straight. Retract the scapulae. Do not shrug your shoulders.'),
('f30cf513-33bd-48c5-9372-bd3a6d3386a5', 'e416939b-82bf-4b95-af69-f9b35758f90d', 'es', 'Remo sentado con banda', 'Sentado, piernas estiradas, rodea pies con banda y rema. Espalda recta. Retrae escápulas. No subas los hombros.'),
('2ab3ec4c-20e7-437e-b3ad-0df88045cb4e', 'e43572ab-e8ee-4284-ad89-c75f97e273a5', 'en', 'Plate Front Raises', 'Hold plate and lift forward. Objective: anterior deltoid. Cue: no swinging. Error: arching back.'),
('c9a5570d-012c-4e6f-bfad-650218c835ca', 'e43572ab-e8ee-4284-ad89-c75f97e273a5', 'es', 'Elevaciones frontales con disco', 'Sujeta disco y eleva al frente. Objetivo: deltoides anterior. Cue: no balancear. Error: arquear espalda.'),
('6d07b4d8-5e04-45f9-b9d2-c20a128535b0', 'e4596505-5dce-4fe8-8ef3-049ad1c3a9b0', 'en', 'Bulgarian Split Squat', 'One foot elevated on a bench behind you, lower with the front leg until the thigh is parallel to the floor. Cue: slightly leaned trunk. Error: knee collapsing inward.'),
('d345b48c-1fd0-4e09-b1cb-4ee190e788bb', 'e4596505-5dce-4fe8-8ef3-049ad1c3a9b0', 'es', 'Sentadilla búlgara', 'Un pie elevado en banco tras de ti, baja con la pierna delantera hasta que el muslo sea paralelo al suelo. Cue: tronco ligeramente inclinado. Error: que la rodilla colapse hacia adentro.'),
('87ac284b-eb47-42b7-9051-dff162ac07f0', 'e47b3926-77ac-4f3b-bac7-5aa166743097', 'en', 'Band Bicep Curl', 'Step on the center of the band and hold the ends with palms up. Perform elbow flexions keeping elbows glued to your sides. The progressive resistance of the band makes the exercise more challenging at the top of the movement.'),
('0ab830bb-8949-41af-a08e-34ed88bbb6fe', 'e47b3926-77ac-4f3b-bac7-5aa166743097', 'es', 'Curl bíceps con banda', 'Pisa el centro de la banda y sujeta los extremos con las palmas hacia arriba. Realiza flexiones de codo manteniendo los codos pegados a los costados. La resistencia progresiva de la banda hace que el ejercicio sea más desafiante en la parte superior del movimiento.'),
('5d8ba68c-9654-4e93-8c5c-23febb286866', 'e47ea76a-6eb4-43cd-9570-9e4871bcc5f3', 'es', 'Turkish Sit Up en Landmine a una mano', 'Realiza un sit up sujetando el extremo de la barra Landmine con un brazo extendido, desafiando la estabilidad del core y el hombro.'),
('bbb71590-555f-4c4e-ac4c-76b36ad62711', 'e4e7fdbf-b0a5-47af-87e3-91ee017da993', 'es', 'TRX Remo bajo estricto', 'Tira agarres a costillas TRX. Objetivo: espalda. Cue: codos pegados. Error: hundir cadera.'),
('6b41386f-e5f3-4988-b060-ced21b92809f', 'e50c6346-ad5c-4c85-88dd-647ab22e94ed', 'en', 'Barbell Snatch', 'The most technical of the Olympic lifts. Bring the bar from the floor to overhead in a single continuous movement with a wide grip. Requires exceptional mobility, perfect coordination, and years of practice to master the technique correctly.'),
('4023c809-b97f-442c-9bbf-2cdf45a2ed2d', 'e50c6346-ad5c-4c85-88dd-647ab22e94ed', 'es', 'Arranque barra', 'El más técnico de los levantamientos olímpicos. Lleva la barra desde el suelo hasta sobre la cabeza en un solo movimiento continuo con agarre amplio. Requiere movilidad excepcional, coordinación perfecta y años de práctica para dominar la técnica correctamente.'),
('1e6cafdc-a810-4edc-b901-19415f69fb39', 'e51b23ae-f2cc-46e7-a9c3-911a1b817214', 'en', 'Decline Barbell Bench Press', 'Lying on a decline bench, lower the bar to the lower pectoral and push. Objective: lower pectoral fibers. Cue: feet well anchored. Common error: lowering the bar toward the neck.'),
('e4658350-f4d9-4073-8ee1-7d93dac05529', 'e51b23ae-f2cc-46e7-a9c3-911a1b817214', 'es', 'Press de banca declinado con barra', 'Tumbado en banco declinado, baja la barra a la parte inferior del pecho y empuja. Objetivo: fibras inferiores del pectoral. Cue: pies bien anclados. Error común: bajar la barra hacia el cuello.'),
('c33dbb89-2ea6-499b-9069-1c96e8738d41', 'e52667e3-614c-496e-8fb1-5ddccfbea51e', 'es', 'Push Jerk a una mano con Kettlebell Bottoms Up', 'Lanza una Kettlebell invertida sobre la cabeza y métete debajo flexionando rodillas, un reto maximo de estabilidad y potencia.'),
('3c6356a8-c3a5-43bd-aa37-a644124ce44a', 'e565695e-e291-49a1-81d5-0d5743f12097', 'en', 'Fingertip push ups', 'Perform push-ups supporting yourself only on your fingertips instead of palms. Significantly strengthens fingers, hands, and forearms. Start with a few reps to avoid injury and progress gradually. Keep fingers firm and arched.'),
('25a8bc8e-0038-4bb0-8b5a-7cb907381304', 'e565695e-e291-49a1-81d5-0d5743f12097', 'es', 'Fingertip push ups', 'Realiza flexiones apoyándote únicamente en las puntas de los dedos en lugar de las palmas. Fortalece significativamente los dedos, manos y antebrazos. Comienza con pocas repeticiones para evitar lesiones y progresa gradualmente. Mantén los dedos firmes y arqueados.'),
('cdc763f2-a3f9-4e79-847a-42e7b70ed681', 'e58a7dca-ba19-4fb7-b254-375cc3892674', 'en', 'Double Kettlebell Sumo Deadlift', 'With feet wider than shoulder-width, lift two kettlebells from the floor by extending hips and knees while keeping a neutral spine.'),
('fca7d923-a444-4b36-8ab0-4ec3921b0545', 'e58a7dca-ba19-4fb7-b254-375cc3892674', 'es', 'Peso muerto Sumo con Kettlebell doble', 'Con los pies mas anchos que los hombros, levanta dos Kettlebells desde el suelo extendiendo cadera y rodillas con la espalda neutra.'),
('b08278d3-0a79-4813-bc44-50e47639bc6d', 'e59c73a0-fe58-4e6a-9e99-eed0083ad556', 'en', 'Alternating Single Arm Kettlebell Alternating Staggered Stance Swing', 'Single-arm staggered stance swing alternating both the arm and foot position in a rhythmic and coordinated manner.'),
('043c2fcc-04dd-45ab-b384-88055c11e0b8', 'e59c73a0-fe58-4e6a-9e99-eed0083ad556', 'es', 'Swing en postura escalonada alterno con Kettlebell a una mano', 'Swing unilateral en postura escalonada alternando el brazo y la posicion de los pies de forma ritmica y coordinada.'),
('611c2ae2-98d2-4606-b31b-414647603c28', 'e6271a88-e47d-40da-b4b6-237dd5554d10', 'es', 'Upright row cable', 'Con polea baja y barra recta, realiza remo vertical llevando la barra hacia el mentón con los codos elevados. El cable proporciona tensión constante. Ten cuidado con la posición de las muñecas y no eleves demasiado si tienes problemas de hombro.'),
('1eea6a0c-7160-4345-bd65-1ac0d48f05d1', 'e66415a8-ac1e-460d-b85e-6ab6e46bb152', 'es', 'Prensa piernas unilateral estricta', 'Empuja plataforma con un pie. Cue: rodilla alineada. Error: bloquear rodilla.'),
('0b19e9fe-ff08-4c56-abba-c7ec19786bd0', 'e6adafbc-b80e-479e-aced-5ce2008bb4c6', 'en', 'Double Kettlebell Front Rack Squat', 'Perform a deep squat with two kettlebells resting on your forearms and shoulders, keeping elbows up and torso straight.'),
('ab5de9cc-e1fa-441a-918b-3eec6d191573', 'e6adafbc-b80e-479e-aced-5ce2008bb4c6', 'es', 'Sentadilla Front Rack con Kettlebell doble', 'Realiza una sentadilla profunda con dos Kettlebells apoyadas en los antebrazos y hombros, manteniendo los codos en alto y torso recto.'),
('f7995d7a-9095-4a14-b354-82bb0d6551b9', 'e6cee733-ba4a-4344-8b8c-f873d8ebf8a1', 'en', 'Alternating Dumbbell Shoulder Press', 'Push a weight alternating arms. Objective: unilateral. Cue: stable torso. Error: tilting body.'),
('06de2e52-9970-436d-851f-f0cdc426a901', 'e6cee733-ba4a-4344-8b8c-f873d8ebf8a1', 'es', 'Press hombros alterno mancuerna', 'Empuja una pesa alternando brazos. Objetivo: unilateral. Cue: torso estable. Error: inclinar cuerpo.'),
('093540a7-4d27-419c-b9a9-411002f8a460', 'e6d2735a-f52d-4a43-adbe-4976ba31fb59', 'en', 'Double Kettlebell Bottoms Up Clean to Front Rack Squat', 'Perform a clean catching two upside-down kettlebells in rack position and immediately drop into a deep squat.'),
('d3c0b3ff-95fa-4f1b-a5e9-d5e5c3398c1f', 'e6d2735a-f52d-4a43-adbe-4976ba31fb59', 'es', 'Doble con pesa rusa, desde abajo hacia arriba, limpio hasta sentadilla con rejilla frontal', 'Realiza una cargada recibiendo dos Kettlebells invertidas en posicion rack y baja inmediatamente a una sentadilla profunda.'),
('91cbe293-738c-41bd-b4cc-efb9749f69f1', 'e6d2ff3b-cc81-4f46-9e20-578f8b4414ad', 'en', 'Parallette V Sit', 'Support yourself on the parallettes and lift straight legs above hip level forming a V, maintaining isometric tension.'),
('bcc74928-02d1-4362-8e50-d007ea1e8a8c', 'e6d2ff3b-cc81-4f46-9e20-578f8b4414ad', 'es', 'V-Sit en paralelas', 'Sostente sobre las paralelas y eleva las piernas rectas por encima de la cadera formando una V, manteniendo la tensión isométrica.'),
('e15b707e-9e50-452e-881c-08842cd53d49', 'e6ee753a-255f-451a-a611-9306bfc3c832', 'es', 'Zancada inversa Overhead contralateral Slider Kettlebell Bottoms Up', 'Sostén una pesa rusa invertida sobre la cabeza. Desliza la pierna opuesta hacia atrás usando un slider, estabilizando hombro y torso.'),
('55ddea7a-bc47-4247-9185-7de07bfe3e79', 'e6f0fe51-5c66-4c3a-8a90-92bb10008b1e', 'en', 'Parallette Freestanding Handstand Push Up', 'In a vertical position on the parallettes, bend your arms until your head goes down between the bars and push explosively to full extension.'),
('2f92925c-88c0-498e-91a4-963284f1f292', 'e6f0fe51-5c66-4c3a-8a90-92bb10008b1e', 'es', 'Handstand Push Up en paralelas', 'En posición vertical sobre las paralelas, flexiona los brazos hasta que la cabeza baje entre las barras y empuja explosivamente hasta extender los brazos.'),
('0fddc725-73f7-4ed9-ad35-a7a79214f055', 'e6fd18ff-0cf7-4cba-92bd-0b4388cefe20', 'es', 'Zancada atrás con barra', 'Barra en hombros, da un paso atrás y baja. Estabilidad. Torso erguido. No dejes que la rodilla delantera colapse.'),
('38ef8df9-8ac6-4220-96fd-27fbb8cf5b6d', 'e77b7398-8d9a-4b76-99d5-eb73b00d9646', 'en', 'Seated One-Arm Dumbbell Cuban Press', 'Seated, perform an upright row, rotate the shoulder externally, and then press the dumbbell overhead. Reverse the movement.'),
('a6050f7e-45aa-4b1b-8125-56e2bfe5d449', 'e77b7398-8d9a-4b76-99d5-eb73b00d9646', 'es', 'Press Cubano sentado con mancuerna', 'Sentado, realiza un remo vertical, rota el hombro externamente y luego presiona la mancuerna sobre la cabeza. Invierte el movimiento.'),
('a29275e7-48b3-4f85-b489-a308a72418f7', 'e7a2a94a-c617-469b-a821-087414c38340', 'en', 'Alternating Behind the Neck Barbell Cossack Squat', 'With the bar on the shoulders, perform a deep lateral squat toward one side while keeping the other leg straight, and alternate.'),
('acea19b2-d340-465a-b58b-149eff86b9b2', 'e7a2a94a-c617-469b-a821-087414c38340', 'es', 'Sentadilla Cosaca alterna con barra tras nuca', 'Con la barra en los hombros, realiza una sentadilla lateral profunda hacia un lado manteniendo la otra pierna estirada, y alterna.'),
('cfb66b88-00bc-4102-a984-4b0a1a32e046', 'e7b2696f-306f-4ea2-9fe2-8989897706ca', 'en', 'B-Skips', 'Similar to the A-skip, but extend the leg forward before pulling the foot back against the ground. Improves stride. Neutral back. Avoid jerky movements.'),
('ec1beca7-6c1e-4f5f-a8e8-b2388d065d71', 'e7b2696f-306f-4ea2-9fe2-8989897706ca', 'es', 'Saltos B (B-Skips)', 'Similar al salto A, pero extiende la pierna hacia adelante antes de traccionar el pie hacia atrás contra el suelo. Mejora la zancada. Espalda neutra. Evita movimientos bruscos.'),
('22c28fdd-0c3a-4c57-b416-3c7db6044bd8', 'e7e31213-33b4-4804-adca-ef06e6d2db2a', 'en', 'Battle Rope Power Slam', 'Lift both ends of the rope overhead and slam them against the floor with maximum power using the whole body.'),
('79e1261b-7ac7-48e4-84ee-2ade4482e442', 'e7e31213-33b4-4804-adca-ef06e6d2db2a', 'es', 'Slam de poder con cuerda de batalla', 'Eleva ambos extremos de la cuerda sobre la cabeza y golpealos contra el suelo con maxima potencia utilizando todo el cuerpo.'),
('6ea74b38-b7cc-4432-b712-3eb4f5a739e5', 'e7ec3810-2ac1-4bf7-932b-f2b10ef7d8f1', 'en', 'Kettlebell Front Rack Squat', 'Hold two kettlebells against your shoulders and lower into a deep squat. Objective: quadriceps and core stability. Cues: very vertical torso. Common error: allowing the weight to lean you forward.'),
('57460576-98ff-42ff-b7c4-074783f69184', 'e7ec3810-2ac1-4bf7-932b-f2b10ef7d8f1', 'es', 'Sentadilla con kettlebells en posición de rack', 'Sostén dos pesas rusas contra los hombros y baja en sentadilla profunda. Objetivo: cuádriceps y estabilidad de core. Cues: torso muy vertical. Error común: permitir que el peso te incline hacia adelante.'),
('ca6844be-daf7-481c-aacd-afa2547a4793', 'e8243342-d98b-48b8-8d30-38bc51bd7cca', 'en', 'Kettlebell Turkish Get-Up', 'From a lying position with kettlebell extended, stand up following a specific sequence of movements. Requires mobility, stability, and coordination. One of the most complete exercises in existence. Practice without weight first.'),
('c6d9e686-a2cf-4b19-aa50-aa2a7de86f63', 'e8243342-d98b-48b8-8d30-38bc51bd7cca', 'es', 'Levantamiento turco kettlebell', 'Desde posición tumbada con kettlebell extendida, levántate hasta ponerte de pie siguiendo una secuencia específica de movimientos. Requiere movilidad, estabilidad y coordinación. Uno de los ejercicios más completos que existen. Practica sin peso primero.'),
('f1d138fb-f0d6-4dbc-9f44-14f6f899423f', 'e837b997-43a4-4b2e-b1a7-5d60645bc19f', 'en', 'Side Plank Hip Dips', 'Lower and raise hip in side plank. Objective: obliques. Cue: vertical movement. Error: rotating shoulder.'),
('924d8897-1a0c-459e-9419-dc96da92f39a', 'e837b997-43a4-4b2e-b1a7-5d60645bc19f', 'es', 'Hip Dips plancha lateral', 'Baja y sube cadera en plancha lateral. Objetivo: oblicuos. Cue: movimiento vertical. Error: rotar hombro.'),
('1b84f2c3-1061-4b3a-9bb7-86069c9beffb', 'e873c22e-3a65-44bd-be5c-963dc6ae7989', 'en', 'V-Sit', 'Maintain balance sitting only on the glutes with legs and torso elevated forming a V. Arms extended parallel to the legs. Requires exceptional core strength and flexibility. Progress from versions with bent knees.'),
('4955fd20-9e6b-4a88-8f2b-5ea836640253', 'e873c22e-3a65-44bd-be5c-963dc6ae7989', 'es', 'Sentado en V', 'Mantén el equilibrio sentado solo sobre los glúteos con piernas y torso elevados formando una V. Brazos extendidos paralelos a las piernas. Requiere fuerza excepcional del core y flexibilidad. Progresa desde versiones con rodillas flexionadas.'),
('34728b26-db5f-462b-b6cb-35a16c79975f', 'e87460b7-4267-4740-a788-6f02d5bb5d81', 'en', 'Weighted Dead bug', 'Dead bug with load for lumbopelvic stability, keeping the lower back flat and controlling breathing.'),
('d7631847-884e-4047-9241-2b724abf9bdd', 'e87460b7-4267-4740-a788-6f02d5bb5d81', 'es', 'Dead bug pesado', 'Mantén lumbar estable. Extiende pierna y brazo contrario sin arquear. Si pierdes control, reduce carga o rango.'),
('4c9c8ede-b7b7-4f90-a78b-3e449bea9989', 'e8983e2a-bd9b-4e74-8be3-4666e8f35388', 'en', 'Deep Handstand Push Ups', 'Handstand push-ups using parallettes or blocks for a greater range of motion. Allows the head to descend below the level of the hands. Significantly increases difficulty and muscle development.'),
('218beaa4-c962-4701-bd29-850d3c3a03f1', 'e8983e2a-bd9b-4e74-8be3-4666e8f35388', 'es', 'Flexiones parada de manos profundas', 'Flexiones en parada de manos usando paralelas o bloques para mayor rango de movimiento. Permite descender la cabeza por debajo del nivel de las manos. Aumenta significativamente la dificultad y el desarrollo muscular.'),
('920c024f-e638-4d14-a2a5-feebe2109f2a', 'e8b3c6ba-4a7c-43cb-bc45-911a36cc14c6', 'en', 'Double Kettlebell Dead Clean to Push Press', 'Explosively lift two kettlebells from the floor to shoulders and, without pausing, drive them overhead using leg momentum.'),
('0340e3b0-4fd3-4405-84f3-83d727ef8416', 'e8b3c6ba-4a7c-43cb-bc45-911a36cc14c6', 'es', 'Dead Clean a Push Press con Kettlebell doble', 'Lleva dos Kettlebells desde el suelo hasta los hombros de forma explosiva y, sin pausa, lánzalas sobre la cabeza usando el impulso de las piernas.'),
('c00f9305-bf8d-45fb-a26e-39edbf13b4c7', 'e8c3ca63-a844-49f1-aae9-dad1e79767c5', 'es', 'Tuck Back Lever en anillas', 'Cuélgate de las anillas y mantén el cuerpo paralelo al suelo boca abajo con las rodillas encogidas hacia el pecho.'),
('0beb6f66-f4cc-4f8b-941e-59998381a281', 'e8e43ffb-6aa0-404b-b223-4fab9e173376', 'en', 'Manna', 'Extreme V-sit progression where the hips rise above the level of the hands. One of the most difficult skills in calisthenics. Requires exceptional compression and strength. Only achievable after years of specific preparation.'),
('0d2ae534-2e0b-4619-9774-8d8203cdc8ba', 'e8e43ffb-6aa0-404b-b223-4fab9e173376', 'es', 'Manna', 'Progresión extrema del V-sit donde las caderas se elevan por encima del nivel de las manos. Una de las habilidades más difíciles de calistenia. Requiere compresión y fuerza excepcionales. Solo alcanzable tras años de preparación específica.'),
('1cf22b15-4ef6-4e3f-b58f-6c19c7434d70', 'e8f02a03-600d-46f3-8b38-e510da9837f3', 'en', 'Bent-Knee Soleus Raise', 'Perform bent-knee soleus raises. Keep the knee bent to emphasize the soleus and lift the heel under control.'),
('077f62e1-9248-4938-9a8f-25582577362b', 'e8f02a03-600d-46f3-8b38-e510da9837f3', 'es', 'Sóleo con rodilla flexionada', 'Realiza elevaciones de sóleo con la rodilla flexionada. Mantén la rodilla doblada para enfatizar el sóleo y eleva el talón de forma controlada.'),
('c10b8170-ed7c-4aa7-a5b2-c4924ba02ea5', 'e92b3390-fd1e-4683-89f4-3ff3c6538e4e', 'en', 'Barbell Squat', 'Barbell back squat for leg strength, maintaining abdominal bracing, aligned knees, and consistent depth.'),
('fde97415-f7a0-4602-9372-d3364a15209d', 'e92b3390-fd1e-4683-89f4-3ff3c6538e4e', 'es', 'Sentadilla con barra', 'Inhala y bloquea el tronco (brace). Baja controlado, rodillas siguen pies, y sube empujando el suelo sin perder postura.'),
('d8af8777-375f-4e4b-8386-1bb59b30de67', 'e966fd7a-3be5-4fba-a8f4-83e20d6e9cb1', 'en', 'Single Arm Kettlebell Snatch to Overhead Contralateral Reverse Lunge', 'Perform a snatch and, while keeping the weight locked overhead, execute a reverse lunge with the leg opposite to the loaded arm.'),
('75308885-cbc6-431a-abce-908ed95f27c8', 'e966fd7a-3be5-4fba-a8f4-83e20d6e9cb1', 'es', 'Snatch a Zancada inversa Overhead contralateral con Kettlebell', 'Realiza un snatch y, manteniendo la pesa bloqueada arriba, ejecuta una zancada atras con la pierna opuesta al brazo de carga.'),
('81a2ee53-7d50-4d4f-9f00-d19eae5fe9fe', 'e9873691-3d69-45ba-83f1-ad9222b2fe86', 'en', 'Incline Barbell Press', 'Incline barbell press to prioritize upper pectoral and anterior deltoid, keeping scapulae retracted and controlling the descent.'),
('841729ec-e7fa-4b45-86e8-146cf175b4f5', 'e9873691-3d69-45ba-83f1-ad9222b2fe86', 'es', 'Press inclinado con barra', 'Escápulas atrás y abajo, pecho arriba. Baja al alto del pecho y empuja sin perder tensión ni rebotar.'),
('29e60c97-f3f2-4211-afbc-1741d8a76ee6', 'e9c99ac9-dabc-44b1-a041-ca131f3f0155', 'en', 'Plyometric Archer Push Up', 'In each explosive push-up, shift weight toward one arm while the other extends laterally. Unilateral pushing power. Cue: body rigid as a board. Common error: rotating the hip to one side.'),
('cb6dacb9-ad8c-437f-8724-6995349e075b', 'e9c99ac9-dabc-44b1-a041-ca131f3f0155', 'es', 'Flexión pliométrica arquera', 'En cada flexión explosiva, cambia el peso hacia un brazo mientras el otro se extiende lateralmente. Potencia unilateral de empuje. Cue: cuerpo rígido como una tabla. Error común: rotar la cadera hacia un lado.'),
('24d22a3e-83f6-46c9-98f6-464b13b4aa49', 'e9fdc582-66f4-4d4d-8861-2f14e6cdbcef', 'es', 'Pike Pushups pies elevados', 'Flexión hombro pies en banco. Objetivo: fuerza hombro. Cue: frente ante manos. Error: arquear espalda.'),
('180dec03-c7e1-41e4-9b9e-5feccc79c3de', 'ea2859d2-3275-4d6d-9f22-2527fc51c8fa', 'en', 'TRX Row', 'Leaned back holding the straps, pull your body toward your hands. Adjust the body angle to modify difficulty. Keep the body straight like a board and squeeze the shoulder blades at the end.'),
('fb7bb016-9c8c-4b24-9b0c-5e2bf3effa7e', 'ea2859d2-3275-4d6d-9f22-2527fc51c8fa', 'es', 'Remo TRX', 'Inclinado hacia atrás sujetando las correas, tira del cuerpo hacia las manos. Ajusta el ángulo del cuerpo para modificar la dificultad. Mantén el cuerpo recto como una tabla y aprieta los omóplatos al final.'),
('5b74a5a7-aa86-461f-bcbf-a3a4c888d0b5', 'ea2b760c-a78b-4028-a739-549a87ade2e9', 'en', 'Incline Bench Dumbbell Row', 'Chest supported on a 45-degree bench, row with both dumbbells. Isolates the back. Head supported. Do not lift the chest off the bench.'),
('2be20e2b-d28c-410a-b3d3-e30d8cf1e654', 'ea2b760c-a78b-4028-a739-549a87ade2e9', 'es', 'Remo con mancuernas en banco inclinado', 'Pecho apoyado en banco a 45 grados, rema con ambas mancuernas. Aísla espalda. Cabeza apoyada. No levantes el pecho del banco.'),
('d26e4e24-fdc7-449c-87bb-e6e60af5f39f', 'ea8892f9-4aee-4256-98f7-bd7a80e61b26', 'en', 'One-Arm TRX Low Row', 'Hold one TRX strap with one hand. Lean back and pull the body up bringing the elbow close to the ribs.'),
('4af4f9ef-8a58-4933-8685-ee549ac3ec08', 'ea8892f9-4aee-4256-98f7-bd7a80e61b26', 'es', 'Remo bajo a una mano en TRX', 'Sostén una correa de TRX con una mano. Inclínate hacia atrás y tira del cuerpo hacia arriba llevando el codo pegado a las costillas.'),
('1f224e5e-b00a-454e-bbb7-321fa272cd52', 'eaaeaa88-f499-4ed3-8c40-1913486122b9', 'en', 'Alternating Goblet Landmine Cossack Squat', 'Hold the end of the Landmine bar in front of the chest. Perform deep lateral shifts alternating legs to work adductors.'),
('d3e522b2-49fa-415b-9400-f2b220196d15', 'eaaeaa88-f499-4ed3-8c40-1913486122b9', 'es', 'Sentadilla cosaca alterna Goblet en Landmine', 'Sujeta el extremo de la barra Landmine frente al pecho. Realiza desplazamientos laterales profundos alternando piernas para trabajar aductores.'),
('c8a0bb04-0459-49ca-9cec-b8bb9a84791f', 'eae757a9-5c76-4281-90c4-ea1b6ddfe16e', 'en', 'Muscle ups', 'Begin with an explosive pull-up that allows you to lift your chest above the bar. At the highest point, perform a quick transition by rotating the wrists and pushing down to finish in a dip position. Requires explosive strength, technique, and perfect coordination between pulling and pushing.'),
('25f88bac-9d31-4d20-b51b-0928dd963a62', 'eae757a9-5c76-4281-90c4-ea1b6ddfe16e', 'es', 'Muscle ups', 'Comienza con una dominada explosiva que te permita elevar el pecho por encima de la barra. En el punto más alto, realiza una transición rápida rotando las muñecas y empujando hacia abajo para terminar en posición de fondo. Requiere fuerza explosiva, técnica y coordinación perfecta entre tracción y empuje.'),
('a23a5e4c-9b1c-4879-bdc7-9771dad777c1', 'eaedc357-6d80-48ff-b217-f701c944d0da', 'en', 'Cable March', 'March in place holding cable in Pallof press position. Combines anti-rotation with dynamic stabilization. Lift knees high maintaining stable torso. Brutal intensity for the core.'),
('4b4043e5-e88a-4585-ac4c-1bff48da19d5', 'eaedc357-6d80-48ff-b217-f701c944d0da', 'es', 'Marcha cable', 'Marcha en el sitio sosteniendo cable en posición de Pallof press. Combina anti-rotación con estabilización dinámica. Levanta rodillas alto manteniendo torso estable. Intensidad brutal para el core.'),
('08290e0e-8bbc-4cf7-9912-166387f888d4', 'eafb0f43-d1d8-4741-98e1-cccfcccf2752', 'en', 'Alternating Front Clubbell Flag Press', 'Hold two clubs in front of the chest. Extend one arm forward keeping the club vertical and the core stable to resist leverage, then alternate.'),
('ddcda7b3-a3dd-48a6-953f-18a72b89b717', 'eafb0f43-d1d8-4741-98e1-cccfcccf2752', 'es', 'Press de bandera frontal alterno con Clubbell', 'Sostén dos mazas frente al pecho. Extiende un brazo hacia adelante manteniendo la maza vertical y el core estable para resistir la palanca, luego alterna.'),
('535c2f77-a9ba-4a1d-a540-54bccdf6291e', 'eafb5c18-430d-4114-abd0-54ef06d12527', 'es', 'Pulldown máquina', 'Similar al jalón con cable pero en máquina de placas. Tira hacia abajo hasta el pecho manteniendo el torso estable. Algunas máquinas permiten agarre independiente para cada brazo. Excelente para principiantes que no pueden hacer dominadas.'),
('983b42c3-325a-4f10-abf2-a1bfd21d5e78', 'eb014b78-1f49-46db-bf40-915d72e9a93f', 'en', 'Ring Straddle Planche', 'Horizontal planche position on rings with spread legs, a high-level gymnastics exercise due to added instability.'),
('735269f2-ab8e-40d3-82e2-2f5f5a5ed4b4', 'eb014b78-1f49-46db-bf40-915d72e9a93f', 'es', 'Plancha a horcajadas con Anillas', 'Posicion de plancha horizontal en anillas con las piernas abiertas, un ejercicio de gimnasia de alto nivel por la inestabilidad añadida.'),
('6425d953-7d71-4a61-b681-eefa25a5ead5', 'eb1f902a-7566-4cc4-b500-5f66412d78c1', 'en', 'Wall Rollout', 'Vertical rollout against a wall. Good progression for standing rollout. Start with feet near the wall and move back gradually. Keep the body in a straight line throughout the movement.'),
('0f0d5b98-5067-4e88-a56d-ceb00f5f7ccd', 'eb1f902a-7566-4cc4-b500-5f66412d78c1', 'es', 'Rodamiento desde pared', 'Roll out vertical contra una pared. Buena progresión para roll out de pie. Comienza con pies cerca de la pared y aléjate gradualmente. Mantén el cuerpo en línea recta durante todo el movimiento.'),
('ae088426-614e-46a0-b244-902271c6eca1', 'eb2c88e6-6a58-4615-8c3d-f721299129db', 'en', 'Supinated Yates Row', 'Bent-over row with palms up at 45 degrees. Focuses on the lower lat. Cue: pull toward the navel. Error: using leg momentum.'),
('86fb0175-9b24-4a14-bb1a-83e982c53873', 'eb2c88e6-6a58-4615-8c3d-f721299129db', 'es', 'Remo Yates supinado', 'Remo inclinado con palmas hacia arriba a 45 grados. Enfoca dorsal inferior. Cue: tira hacia el ombligo. Error: usar balanceo de piernas.'),
('60dfe349-03fd-4376-b984-e85e4b3f5f41', 'eb376635-4a4b-4a0e-b60f-d6455cd9e928', 'en', 'Low Cable Row', 'With the pulley in a low position, perform the row pulling toward the lower abdomen. This variation allows a different angle of traction which may be more comfortable for some. Keep core active and avoid excessive momentum.'),
('bfd83cb7-a02e-49b5-b5ee-0f1ee9d5164b', 'eb376635-4a4b-4a0e-b60f-d6455cd9e928', 'es', 'Remo bajo cable', 'Con la polea en posición baja, realiza el remo tirando hacia el abdomen inferior. Esta variación permite un ángulo diferente de tracción que puede ser más cómodo para algunos. Mantén el core activado y evita el impulso excesivo.'),
('f5048af9-0be7-4afb-a3ae-d4f6611090d4', 'eb4ad2ad-5b0d-49d3-8ca6-496e27a2f2a2', 'en', 'Unilateral High Pulley Bicep Curl', 'Sideways to the high pulley, flex the arm bringing the handle toward the ear. Objective: bicep peak. Cues: elbow high and fixed in the air. Common error: dropping the elbow during flexion.'),
('23a921d2-671e-40b9-92be-67b1bf312ca2', 'eb4ad2ad-5b0d-49d3-8ca6-496e27a2f2a2', 'es', 'Curl de bíceps en polea alta unilateral', 'De lado a la polea alta, flexiona el brazo llevando el agarre hacia la oreja. Objetivo: pico del bíceps. Cues: codo alto y fijo en el aire. Error común: bajar el codo durante la flexión.'),
('8d67f289-63b8-4648-9c42-47ba53febfaf', 'eb5041bc-c0f3-4a86-be45-21b1b8774a96', 'en', 'Single Leg Horizontal Jump', 'Maximum forward jump with a single leg. Classic test of unilateral power. Land with the same leg maintaining balance. Measure distance to track progress. Fundamental for many sports.'),
('15eba809-a370-4bc0-96b5-1de36b72fe75', 'eb5041bc-c0f3-4a86-be45-21b1b8774a96', 'es', 'Salto horizontal una pierna', 'Salto hacia adelante máximo con una sola pierna. Prueba clásica de potencia unilateral. Aterriza con la misma pierna manteniendo el equilibrio. Mide la distancia para trackear progreso. Fundamental para muchos deportes.'),
('1d37a369-169e-4e93-afdd-9dee55070d03', 'eb93f9fc-65e2-4285-a5c6-1572962a6def', 'en', 'EZ Bar Spider Curl', 'Rest your chest on an incline bench. With arms hanging, use an EZ bar to curl, keeping the upper arm immobile.'),
('74b9bdfd-36d3-4c9c-8e27-bec25ad39e99', 'eb93f9fc-65e2-4285-a5c6-1572962a6def', 'es', 'Spider Curl con barra Z', 'Apoya el pecho en un banco inclinado. Con los brazos colgando, usa una barra Z para hacer curl, manteniendo la parte superior del brazo inmóvil.'),
('af5dd1b6-e91d-4af1-9866-7f8ff8e2b989', 'eb959c2a-80e8-4160-81e0-f42fa4220d99', 'en', 'Single Arm Dumbbell Pendlay Row', 'With the torso parallel to the floor, row a dumbbell from a dead stop on the ground to your side, alternating arms.'),
('c5976c5e-6f22-442a-8821-ca01e3019259', 'eb959c2a-80e8-4160-81e0-f42fa4220d99', 'es', 'Remo Pendlay con mancuerna a una mano', 'Con el torso paralelo al suelo, rema una mancuerna desde una parada muerta en el suelo hasta tu costado, alternando brazos.'),
('2bfd7093-2f52-498d-847a-6b646794a67c', 'eb9cc845-bc9c-41dc-849d-a7a010759e4b', 'en', 'Controlled Step-Down', 'Perform a controlled step-down from a box or step. Keep the knee aligned with the foot and prevent the pelvis from dropping.'),
('cf2a79b5-af87-42b7-9a0a-9c1eea3079e6', 'eb9cc845-bc9c-41dc-849d-a7a010759e4b', 'es', 'Step-down controlado', 'Realiza un step-down bajando desde un cajón o escalón de forma lenta y controlada. Mantén la rodilla alineada con el pie y evita que la pelvis caiga.'),
('405654e6-9047-4b3d-9ece-93557d9c44ad', 'ebda3a92-dd1f-47b5-9ca9-ff9b4d82b9bd', 'en', 'Lateral Lunges', 'Take a wide step to one side, flexing the knee on that side while keeping the opposite leg extended. Descend by pushing the hips back and keeping the chest upright. Push with the heel to return to the center. Works lateral mobility and strengthens glutes and abductors.'),
('bb7fe711-8a4a-48e4-a3ea-20265db18d27', 'ebda3a92-dd1f-47b5-9ca9-ff9b4d82b9bd', 'es', 'Zancadas laterales', 'Da un paso amplio hacia un lado, flexionando la rodilla de ese lado mientras mantienes la pierna opuesta extendida. Desciende empujando las caderas hacia atrás y manteniendo el pecho erguido. Empuja con el talón para volver al centro. Trabaja la movilidad lateral y fortalece glúteos y abductores.'),
('69d73b53-af33-4d56-a954-6e3378f23ec6', 'ebdcf6fd-2f23-4860-a8af-38c43e288ee5', 'en', 'Lateral Dumbbell Step-up', 'Step onto the box sideways. Objective: gluteus medius. Cue: stable knee. Error: jumping with the floor foot.'),
('60276b21-d38f-4d6a-8925-592427da1fd1', 'ebdcf6fd-2f23-4860-a8af-38c43e288ee5', 'es', 'Step-up lateral mancuernas', 'Sube al cajón de lado. Objetivo: glúteo medio. Cue: rodilla estable. Error: saltar con pie suelo.'),
('3b8a631c-71db-4d08-8d13-d3e62583655b', 'ebe03021-94b4-4a3d-85b8-e33513d791a8', 'en', 'Tibialis Raises', 'Perform tibialis raises by keeping the heels supported and lifting the toes toward the shin. Control the lowering phase and keep tension in the front of the lower leg.'),
('7eabc775-79cc-4869-8ee5-50a7f1715163', 'ebe03021-94b4-4a3d-85b8-e33513d791a8', 'es', 'Tibial raises', 'Realiza elevaciones tibiales apoyando los talones y elevando la punta de los pies hacia la espinilla. Controla la bajada y mantén la tensión en la parte anterior de la pierna.'),
('5ca4b6b9-f597-4723-ba55-e8f0315af0c6', 'ebf41762-888e-45fd-a054-a609c6e7846c', 'en', 'Dumbbell Triceps Kickbacks', 'Lean forward with a dumbbell in each hand. Keep upper arms parallel to the floor and extend forearms back until arms are completely straight. Hold contraction for a second before flexing again.'),
('3e3b05e7-6801-48f5-ae20-9e1f74e4923f', 'ebf41762-888e-45fd-a054-a609c6e7846c', 'es', 'Patada tríceps mancuernas', 'Inclínate hacia adelante con una mancuerna en cada mano. Mantén los brazos superiores paralelos al suelo y extiende los antebrazos hacia atrás hasta que los brazos estén completamente rectos. Mantén la contracción un segundo antes de volver a flexionar.'),
('8223982c-b166-45b3-a2c1-d0577cd864a5', 'ec019c78-ac40-4e1f-beb6-bd019bd62b49', 'es', 'Pike con Slider', 'En posición de plancha con los pies en sliders, mantén las piernas rectas y eleva las caderas hacia el techo deslizando los pies hacia las manos, formando una V invertida.'),
('88222f39-3fc1-4216-8ca7-594a72e562a3', 'ec11f129-3722-4194-86b2-0c369f29aa84', 'en', 'Band Pull-ups', 'Use a band to assist the upward phase. Objective: pull-up progression. Cue: control the descent. Error: letting go quickly.'),
('096822da-1164-4847-a042-1809ab2335cb', 'ec11f129-3722-4194-86b2-0c369f29aa84', 'es', 'Dominadas con banda', 'Usa banda para asistir subida. Objetivo: progresión dominada. Cue: controla bajada. Error: soltar rápido.'),
('9ca0baf6-c0bb-434e-bb03-3d52fd1b104c', 'ec284c3e-e3a3-42c0-986d-33258ba7bae9', 'es', 'Press Seesaw de rodillas con Kettlebell doble', 'Arrodillado, presiona una Kettlebell mientras bajas la otra simultáneamente en un movimiento fluido de sube y baja (balancín).'),
('f1352009-5051-40b6-bc67-ac01c72ca882', 'ec39be67-665e-4c3a-90f1-0363a3838c62', 'en', 'Stability Ball Stir the Pot', 'Position yourself in a plank with forearms on the Fitball. Keeping the body rigid, make small circles with your elbows moving the ball, as if stirring a pot.'),
('cc6ba903-6d3b-41df-a24e-8e4e6f986c85', 'ec39be67-665e-4c3a-90f1-0363a3838c62', 'es', 'Stir the Pot con Fitball', 'Colócate en posición de plancha con los antebrazos sobre el Fitball. Manteniendo el cuerpo rígido, haz círculos pequeños con los codos moviendo el balón, como si removieras una olla.'),
('8657ff0a-d9e3-44d1-b017-142c6e4f939f', 'ec483a2c-e446-420c-adea-1970b3f195f9', 'en', 'Flat Dumbbell Bench Press', 'Lower dumbbells to the chest and push on a flat bench. Cue: control the descent. Error: clashing weights.'),
('91715d86-7879-4368-98fb-648311b90658', 'ec483a2c-e446-420c-adea-1970b3f195f9', 'es', 'Press de banca con mancuernas plano', 'Baja mancuernas al pecho y empuja en banco plano. Cue: controla el descenso. Error: chocar pesas.'),
('b093dfd5-ba3f-4584-8a44-f836d6929ccf', 'ec5a5c9e-ea28-4d76-b4de-5a81883bd31e', 'en', 'Cossack Jump Squat', 'Explosive transition between Cossack squats alternating sides with a jump. Requires mobility, strength, and power. Excellent for sports requiring quick changes of direction. Maintain control on landings.'),
('1e6230cb-eeac-41fd-9d85-2ecc4aa7a008', 'ec5a5c9e-ea28-4d76-b4de-5a81883bd31e', 'es', 'Sentadilla cossack salto', 'Transición explosiva entre sentadillas cossack alternando lados con un salto. Requiere movilidad, fuerza y potencia. Excelente para deportes que requieren cambios de dirección rápidos. Mantén el control en los aterrizajes.'),
('d9953989-d2f6-4733-ab44-28bfc8fae7f2', 'ec970e83-b7de-4ab0-a7e1-5cdb6e8f3c46', 'en', 'Straddle Back Lever on Rings', 'Back lever position maintaining legs straight and open in a V to reduce the lever arm and facilitate control.'),
('4d24a158-73b9-4635-a170-ef3b66009099', 'ec970e83-b7de-4ab0-a7e1-5cdb6e8f3c46', 'es', 'Straddle Back Lever en anillas', 'Posicion de back lever manteniendo las piernas estiradas y abiertas en V para reducir el brazo de palanca y facilitar el control.'),
('6f51532d-fbfb-40ee-a81b-18da6ccb67c9', 'ece06644-976f-4340-8d0b-271b92717f24', 'en', 'TRX Mountain Climber', 'With feet in the straps in a plank position, alternate bringing knees toward the chest. TRX instability significantly increases core work. Keep hips low and movement controlled.'),
('8421c63d-a0f4-403f-87c7-41367c1d03b7', 'ece06644-976f-4340-8d0b-271b92717f24', 'es', 'Mountain climber TRX', 'Con los pies en las correas en posición de plancha, alterna llevando las rodillas hacia el pecho. La inestabilidad del TRX aumenta significativamente el trabajo del core. Mantén las caderas bajas y el movimiento controlado.'),
('ac5d0df6-621b-4966-ac26-d8c12d9fe899', 'ed0526f3-e02b-4ef4-862a-9748c3d3ec47', 'en', 'Inchworm', 'From a standing position, lean forward placing your hands on the floor. Walk your hands forward until you reach a plank position. Perform an optional push-up, then walk your feet toward your hands keeping your legs as straight as possible. Stand up and repeat.'),
('ccc2293d-5e5f-4383-90fd-78a488fbc118', 'ed0526f3-e02b-4ef4-862a-9748c3d3ec47', 'es', 'Inchworm', 'Desde posición de pie, inclínate hacia adelante colocando las manos en el suelo. Camina con las manos hacia adelante hasta llegar a posición de plancha. Realiza una flexión opcional, luego camina con los pies hacia las manos manteniendo las piernas lo más rectas posible. Incorpórate y repite.'),
('719a66cf-1383-4b00-935d-a53a6d1228bf', 'ed054b1e-1313-4a59-9ae8-617f7351d846', 'en', 'Barbell Military Press', 'Push the bar overhead while standing without leg help. Objective: pure shoulder strength. Cue: squeeze glutes and core. Common error: arching the lumbar back at the end.'),
('219c69d8-dee9-4f09-a2ec-118ab4a5dd7c', 'ed054b1e-1313-4a59-9ae8-617f7351d846', 'es', 'Press Militar con barra', 'Empuja la barra sobre la cabeza estando de pie sin ayuda de piernas. Objetivo: fuerza pura de hombros. Cue: aprieta glúteos y core. Error común: arquear la espalda lumbar al final.'),
('6da5f95c-45bd-4857-8f3d-c59da7c9699c', 'ed202210-1374-427e-8caa-4179c261217c', 'en', 'Single Arm Kettlebell Suitcase Ipsilateral Step Up', 'Step up onto the bench with the leg on the same side as the hand holding the kettlebell at your side, keeping the torso perfectly upright.'),
('a9641522-030b-4fb8-9799-e847f605ed76', 'ed202210-1374-427e-8caa-4179c261217c', 'es', 'Step Up ipsilateral con Kettlebell a una mano (Maleta)', 'Sube al banco con la pierna del mismo lado en el que sostienes la Kettlebell a un costado, manteniendo el torso perfectamente erguido.'),
('08f210a7-d4bb-4d8f-8692-d6bf1e05bdad', 'ed305319-32d1-4561-89da-d1116e91f3b7', 'es', 'Press un brazo TRX', 'Press unilateral con máxima inestabilidad. Requiere fuerza y control excepcionales. El brazo libre puede estar extendido para balance. Progresa desde press bilateral dominando primero el movimiento.'),
('ebc866d4-5b45-4b45-8707-a1e414dc4b28', 'ed3fad39-3fdd-4c9e-b9b8-7527105771f5', 'en', 'TRX Y-Raise', 'Leaned back, lift extended arms forming a Y. Focus on upper back. Straight arms. Do not shrug shoulders.'),
('75df8230-15f5-4121-ac53-523db82106d0', 'ed3fad39-3fdd-4c9e-b9b8-7527105771f5', 'es', 'TRX Elevación en Y', 'Inclinado atrás, eleva los brazos extendidos formando una Y. Enfoca en espalda alta. Brazos rectos. No encojas los hombros.'),
('56258dce-457b-4d8d-b39a-6cfc48c908c9', 'ed66cc61-2858-410b-8bea-bb5fc4ee013a', 'en', 'Frontal Single Leg Hurdle Jump', 'Jump forward over low hurdles with a single leg. Power and coordination. Cue: drive with arms. Common error: dragging the foot due to lack of elevation.'),
('5292509f-3771-48de-b51d-dbaad5078e8c', 'ed66cc61-2858-410b-8bea-bb5fc4ee013a', 'es', 'Salto de valla a una pierna frontal', 'Salta hacia adelante sobre vallas bajas con una sola pierna. Potencia y coordinación. Cue: impulsa con los brazos. Error común: arrastrar el pie por falta de elevación.'),
('2f88b944-9b67-4225-83b3-fe942d80e3b3', 'ed9031ae-1e4d-46ff-a5ca-b0ab508372da', 'en', 'Unilateral Cable Chest Press', 'Push a single pulley stirrup forward while keeping the body stable. Objective: pectoral and anti-rotation. Cues: feet well anchored. Common error: allowing the cable to rotate your trunk upon return.'),
('1375fe82-266d-4733-97c0-ec2cd1b3037e', 'ed9031ae-1e4d-46ff-a5ca-b0ab508372da', 'es', 'Press de pecho unilateral en cable', 'Empuja un solo estribo de polea al frente mientras mantienes el cuerpo estable. Objetivo: pectoral y anti-rotación. Cues: pies bien anclados. Error común: permitir que el cable gire tu tronco al volver.'),
('06af75ee-51a8-47a9-84f9-c4e8e62b0e8d', 'edb496e5-ac61-4bd0-8426-72816ba7c403', 'en', 'Alternating Double Dumbbell Z Press', 'Sitting on the floor with legs in a V, perform overhead presses alternating arms continuously without back support.'),
('36f22f34-f4bb-481b-9977-3ad495a022db', 'edb496e5-ac61-4bd0-8426-72816ba7c403', 'es', 'Press Z alterno con mancuernas', 'Sentado en el suelo con piernas en V, realiza press de hombros alternando los brazos de forma continua sin apoyo en la espalda.'),
('23a77049-9357-43f3-a6f9-7b539af84506', 'edbba395-700d-48df-a1b7-a4ef6e3d8be4', 'en', 'Dumbbell Thrusters', 'Combines a front squat with a shoulder press in one fluid movement. Descend into a squat with dumbbells at shoulder height, and upon rising use the momentum to press the dumbbells overhead. Excellent full-body metabolic exercise.'),
('534d8d3a-ab41-4d8a-ac99-52d622e5c5d2', 'edbba395-700d-48df-a1b7-a4ef6e3d8be4', 'es', 'Thrusters mancuernas', 'Combina una sentadilla frontal con un press de hombros en un movimiento fluido. Desciende en sentadilla con las mancuernas a la altura de los hombros, y al subir usa el impulso para presionar las mancuernas sobre la cabeza. Excelente ejercicio metabólico de cuerpo completo.'),
('ea570164-d9e5-4dac-9b6f-1e256d9ec275', 'ee20197b-8737-4ed5-bdcc-bc863ce41f5a', 'en', 'Incline Push Ups', 'Place hands on an elevated surface like a bench, step, or bar. Keep the body straight and lower chest toward the elevated surface. This variation reduces body weight load, making it ideal for beginners or as a warmup. Higher surfaces make it easier.'),
('8d2b84f8-5011-4edb-8245-39c7a6f73fae', 'ee20197b-8737-4ed5-bdcc-bc863ce41f5a', 'es', 'Flexiones inclinadas', 'Coloca las manos sobre una superficie elevada como un banco, escalón o barra. Mantén el cuerpo recto y desciende el pecho hacia la superficie elevada. Esta variación reduce la carga de peso corporal, haciéndola ideal para principiantes o como ejercicio de calentamiento. Cuanto más alta sea la superficie, más fácil será el ejercicio.'),
('627dc73e-2d5b-4808-a773-edc4843e2749', 'ee41cbff-f09a-4d78-a50b-748df47ee439', 'en', 'Unilateral Kettlebell Snatch', 'Bring the weight from the floor to overhead in a single explosive movement. Objective: hip power. Cues: straighten arm near the ear. Common error: hitting the forearm with the weight upon lockout.'),
('2b6f762f-236c-4860-90d9-aa3cdc1e583e', 'ee41cbff-f09a-4d78-a50b-748df47ee439', 'es', 'Snatch unilateral con kettlebell', 'Lleva la pesa desde el suelo hasta encima de la cabeza en un solo movimiento explosivo. Objetivo: potencia de cadera. Cues: estira el brazo cerca de la oreja. Error común: golpear el antebrazo con la pesa al bloquear.'),
('18cb9415-84ec-4f98-a918-1a0400a9c97b', 'ee5dcab4-6645-4a22-8ff9-8ee04f7bc466', 'en', 'Double Battle Ropes Waves', 'Both ropes go up and down simultaneously with maximum amplitude. Requires more power than alternating waves. Use the whole body to generate the waves, not just arms. Maintain a constant rhythm.'),
('9e4ee528-6b88-4aa0-85e9-999c23f2e624', 'ee5dcab4-6645-4a22-8ff9-8ee04f7bc466', 'es', 'Ondas dobles battle ropes', 'Ambas cuerdas suben y bajan simultáneamente con máxima amplitud. Requiere mayor potencia que ondas alternadas. Usa todo el cuerpo para generar las ondas, no solo brazos. Mantén ritmo constante.'),
('b3f8757b-334d-4e25-a146-c70f97e403aa', 'ef01c596-306b-4d7a-b29c-1a2cf2739d23', 'en', 'Single Arm Kettlebell Dead Clean', 'Drive the kettlebell from the floor to the rack position in one explosive hip movement, preventing the weight from slamming the forearm.'),
('5cb429b5-fb0e-4f35-b986-8d696e0e9023', 'ef01c596-306b-4d7a-b29c-1a2cf2739d23', 'es', 'Dead Clean con Kettlebell a una mano', 'Lleva la pesa rusa desde el suelo hasta la posicion rack en un solo movimiento explosivo de cadera, evitando que la pesa golpee el antebrazo.'),
('4812c2eb-b908-415b-8171-17f54cfc9fd6', 'ef0539f8-c30d-4754-8d5c-903d790b54f3', 'en', 'Dumbbell Reverse Lunge', 'Hold dumbbells at the sides and step back lowering the back knee toward the floor. Objective: leg strength. Cue: keep the torso upright. Error: letting the front knee pass too far over the foot.'),
('aab60927-3c62-432a-b864-c03f4475d871', 'ef0539f8-c30d-4754-8d5c-903d790b54f3', 'es', 'Zancada trasera con mancuernas', 'Sujeta mancuernas a los lados y da un paso atrás bajando la rodilla trasera hacia el suelo. Objetivo: fuerza de piernas. Cue: mantén el torso erguido. Error: dejar que la rodilla delantera sobrepase demasiado el pie.'),
('8ca25b2b-3a6c-4822-bd9a-4baede29f858', 'ef547e82-d621-4a6c-9e80-d93958388df0', 'en', 'Barbell Overhead Cyclist Squat', 'With heels elevated, perform a deep squat while holding the bar locked out overhead, requiring total mobility and balance.'),
('c91fd2ba-73a6-499e-8254-25e306af4d7b', 'ef547e82-d621-4a6c-9e80-d93958388df0', 'es', 'Sentadilla Ciclista Overhead con barra', 'Con talones elevados, realiza una sentadilla profunda manteniendo la barra bloqueada sobre la cabeza, exigiendo movilidad y equilibrio total.'),
('c4f4e013-e785-4e89-a73d-0489c54e9e0e', 'ef64612c-9103-4fbf-89be-040d15d67a3a', 'es', 'Zancada inversa con Slider y Kettlebell doble (Maleta)', 'Sostén dos pesas rusas a los lados (estilo maleta). Coloca un pie sobre un slider y deslízalo hacia atrás en una zancada profunda, manteniendo el torso erguido, luego regresa.'),
('be0f6b36-f39c-48d6-819a-1e6fe1ac9c70', 'ef7e6d17-a917-4944-a01e-2de9c773d4f6', 'en', 'Dumbbell Bulgarian Split Squat (Suitcase)', 'Hold two dumbbells at your sides with one foot elevated on a bench behind you. Lower hips vertically and return up.'),
('962da69d-d1bb-4cfd-b13f-ee11de2f813d', 'ef7e6d17-a917-4944-a01e-2de9c773d4f6', 'es', 'Sentadilla Búlgara con mancuernas (Maleta)', 'Sostén dos mancuernas a los costados con un pie elevado en un banco tras de ti. Baja la cadera verticalmente y vuelve a subir.'),
('ff03be3c-efc6-410b-a56c-9481ed154c74', 'ef85345b-3f46-4367-b5d7-569395c72523', 'en', 'High Pulley Abdominal Crunch', 'Kneeling, flex the torso downward with a rope. Cue: exhale as you go down. Error: pulling with the arms.'),
('aef033ab-49ac-4368-b0c8-85d1541e0650', 'ef85345b-3f46-4367-b5d7-569395c72523', 'es', 'Crunch abdominal polea alta', 'De rodillas, flexiona torso hacia abajo con cuerda. Cue: exhala al bajar. Error: tirar con los brazos.'),
('3e434e6a-ce6c-4fb6-bbff-d1a531381a1e', 'efa07710-1799-4acf-91e6-1de0936a6843', 'en', 'Flat Dumbbell Flyes', 'Open arms on a flat bench. Objective: chest stretch. Cue: elbows slightly bent. Error: lowering too much.'),
('3d28f886-6064-4c09-8cad-b9aaf5438f37', 'efa07710-1799-4acf-91e6-1de0936a6843', 'es', 'Aperturas planas mancuerna', 'Abre brazos banco plano. Objetivo: estiramiento pecho. Cue: codos semiflexionados. Error: bajar mucho.'),
('9305cfa6-f84a-4063-8c29-f91793682bb4', 'efc3abf8-3677-4316-b333-5d1333f3abe8', 'en', 'Lunge Twist', 'Perform lunges while rotating the torso toward the side of the lead leg holding the ball. Combines leg strength with core rotation. Keep the ball away from the body for greater challenge.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('02ddd592-2efa-470f-9d02-d2853c7341a9', 'efc3abf8-3677-4316-b333-5d1333f3abe8', 'es', 'Lunge twist', 'Realiza zancadas mientras rotas el torso hacia el lado de la pierna adelantada sosteniendo el balón. Combina fuerza de piernas con rotación del core. Mantén el balón alejado del cuerpo para mayor desafío.'),
('d0658455-a6a1-4cab-94fe-67bf0efda286', 'efdde8cf-3c20-4a2c-9479-e025d66c057c', 'en', 'Bear crawl', 'Start on all fours with knees raised a few centimeters off the ground. Move forward by simultaneously moving the right hand with the left foot, then the left hand with the right foot. Keep the back flat and the core engaged. This exercise improves coordination and strengthens the whole body.'),
('719232bc-fd72-4869-ab90-e6d545bb3008', 'efdde8cf-3c20-4a2c-9479-e025d66c057c', 'es', 'Bear crawl', 'Comienza en cuadrupedia con las rodillas elevadas a pocos centímetros del suelo. Avanza moviendo simultáneamente la mano derecha con el pie izquierdo, luego la mano izquierda con el pie derecho. Mantén la espalda plana y el core activado. Este ejercicio mejora la coordinación y fortalece todo el cuerpo.'),
('d87284c5-57ab-4c4d-86c0-f55c7348d5ab', 'f0002672-31db-4dfb-8990-8fa511eb60f9', 'en', 'Superband Half Kneeling Pallof Press', 'Perform the Pallof press in a half-kneeling position, which increases the challenge on pelvic and torso stability.'),
('6e048bb6-24e7-4333-a7f9-f48c2f946e5d', 'f0002672-31db-4dfb-8990-8fa511eb60f9', 'es', 'Press Pallof medio arrodillado con banda', 'Realiza el press Pallof en posición de caballero, lo que aumenta el reto sobre la estabilidad de la pelvis y el torso.'),
('9f0e93a5-bc52-4f74-94b5-e58ecdc7f44c', 'f0245033-a2c1-40f0-ae62-2d446d8c5290', 'es', 'Victorian', 'Variación del planche donde las piernas se extienden hacia adelante en lugar de hacia atrás. Aún más difícil que el planche tradicional debido al brazo de palanca desfavorable. Solo alcanzable por atletas de élite con años de entrenamiento.'),
('52105d8b-efa6-4c8e-b9c9-bb35144fd499', 'f0a950ac-6a26-4b15-a03e-658a9ae659a1', 'en', 'Landmine Meadows Row', 'Standing perpendicular to the Landmine bar. Grab the thick end with one hand and row bringing the elbow out and up.'),
('bca7448f-907f-4ad2-a51f-9bbea026b73c', 'f0a950ac-6a26-4b15-a03e-658a9ae659a1', 'es', 'Remo Meadows en Landmine', 'De pie perpendicular a la barra Landmine. Agarra el extremo grueso con una mano y rema llevando el codo hacia afuera y arriba.'),
('9d69fad9-c795-48c8-81af-01c600d7d4fb', 'f0f95377-a307-4805-bea1-e76f8d40312b', 'en', 'Single Arm Suspension Plank', 'In a plank position with one hand in the TRX cradle, keep the body aligned while resisting the suspensions instability.'),
('7cd3b2f4-0290-4737-a07c-2f76b2e339b7', 'f0f95377-a307-4805-bea1-e76f8d40312b', 'es', 'Plank a una mano en TRX', 'En posición de plancha con una mano en el estribo del TRX, mantén el cuerpo alineado resistiendo la inestabilidad de la suspensión.'),
('13517737-e0c1-460d-93f8-86dedaa33833', 'f0ffdd26-67cd-43ed-a9cd-0d5fd948dac7', 'en', 'Single Arm Kettlebell Staggered Stance Swing', 'Perform a single-arm swing with one foot slightly behind the other, increasing the stability demand on the lead leg.'),
('99294ec8-d343-4d32-a656-0359f621e083', 'f0ffdd26-67cd-43ed-a9cd-0d5fd948dac7', 'es', 'Swing en postura escalonada con Kettlebell a una mano', 'Realiza un swing unilateral con un pie ligeramente retrasado (postura de split), lo que aumenta la demanda de estabilidad en la pierna delantera.'),
('c79e125a-e91c-491b-b40f-9510de7e9c79', 'f128dd5f-e5f7-461f-8578-7f535c0cd11d', 'es', 'Puente glúteo unilateral pausa 2s', 'Eleva cadera a un pie y mantén. Cue: cadera alineada. Error: caer de lado.'),
('566f26bb-d716-4c30-a5b8-dedb2d58aef6', 'f132c788-0a63-4ecd-9e1e-00a6a1a6bb90', 'en', 'Unilateral Lat Pulldown', 'Pull a single lever on the machine. Objective: correct asymmetries. Cues: squeeze the lat. Common error: leaning the body too much.'),
('bf19f9f0-667b-4c50-941c-4bc2df6ede3e', 'f132c788-0a63-4ecd-9e1e-00a6a1a6bb90', 'es', 'Jalón al pecho unilateral', 'Tira de una sola palanca en máquina. Objetivo: corregir asimetrías. Cues: aprieta el dorsal. Error común: inclinar mucho el cuerpo.'),
('fff8ed2e-3be3-4a14-b61f-cc4c4e4eab94', 'f1468a2c-b686-4570-90f1-63b344c5a05a', 'es', 'Plancha comando', 'Pasa de apoyo de antebrazos a manos alternativamente. Estabilidad y brazos. Cadera quieta. No balancees el cuerpo de lado.'),
('495f1251-1cac-4529-92ed-5082aeac5f95', 'f14b9e08-e88b-4a37-ae3e-6337dd11de15', 'en', 'Alternating Bird Dog', 'In quadruped, extend opposite arm and leg while maintaining balance. Objective: lumbopelvic stability. Cue: do not allow the hip to rotate. Common error: excessively arching the back when stretching.'),
('d2b579f9-e7a6-4658-bbbc-5f018bbbc007', 'f14b9e08-e88b-4a37-ae3e-6337dd11de15', 'es', 'Bird Dog alterno', 'En cuadrupedia, extiende brazo y pierna contraria manteniendo el equilibrio. Objetivo: estabilidad lumbopélvica. Cue: no permitas que la cadera rote. Error común: arquear la espalda excesivamente al estirar.'),
('80619653-adf8-48db-a15b-0370fe0fc50e', 'f169d0fc-fbae-45ae-95d9-be1922b2104c', 'en', 'Wide Stance Squat', 'Squat with feet far apart and toes pointed out. Powerlifting style. Emphasizes glutes and adductors. Allows some lifters to move more weight. Requires good hip mobility. Knees follow the line of the feet.'),
('1ed26097-952d-41ee-85b0-397c577e6679', 'f169d0fc-fbae-45ae-95d9-be1922b2104c', 'es', 'Sentadilla postura amplia', 'Sentadilla con pies muy separados y puntas hacia afuera. Estilo powerlifting. Enfatiza glúteos y aductores. Permite mover más peso en algunos levantadores. Requiere buena movilidad de caderas. Rodillas siguen la línea de los pies.'),
('24cbe656-618b-4729-adfd-d4e9a7753330', 'f16fbeb6-5856-4331-a2a5-819caa064e39', 'en', 'Static Bird Dog', 'In quadruped, extend opposite arm and leg. Cue: neutral back, do not rotate hip. Error: lifting arm and leg too much, breaking the line.'),
('a11b736d-bb1a-4d37-ae3c-754d6f1729f0', 'f16fbeb6-5856-4331-a2a5-819caa064e39', 'es', 'Bird Dog estático', 'En cuadrupedia, extiende brazo y pierna contraria. Cue: espalda neutra, no rotes cadera. Error: levantar brazo y pierna demasiado rompiendo la línea.'),
('7bb57747-e788-4680-bc71-7b0dee3246ba', 'f1807a41-4e49-4d7c-a777-d6b9f5b84bfc', 'en', 'Bosu Hemispherical Squat', 'Squat on the blue side of the Bosu. Objective: stability. Cue: look forward. Error: knees caving in.'),
('401b0b90-cfd8-4e84-bf39-41069bf3bff8', 'f1807a41-4e49-4d7c-a777-d6b9f5b84bfc', 'es', 'Sentadilla bosu semiesfera', 'Sentadilla sobre lado azul bosu. Objetivo: estabilidad. Cue: mirada frente. Error: rodillas dentro.'),
('91d4ddbc-25c0-45a2-a0a0-547fb4f80e8f', 'f1938154-8cf4-42f1-a031-74ba48626606', 'en', 'Parallette Tuck Planche', 'Support your weight on the parallettes with locked arms and lift your knees toward your chest while keeping your back parallel to the floor.'),
('4a56f7f1-248d-45a8-aed7-e42e24c93811', 'f1938154-8cf4-42f1-a031-74ba48626606', 'es', 'Tuck Planche en paralelas', 'Sostén tu peso sobre las paralelas con los brazos bloqueados y eleva las rodillas hacia el pecho manteniendo la espalda paralela al suelo.'),
('2423457a-70d1-43bc-af52-03962f92e1e1', 'f193aa17-015a-4102-bba9-f4be51a3495a', 'en', 'Double Kettlebell Bottoms Up Overhead Bulgarian Split Squat', 'Split squat with elevated foot while maintaining two upside-down kettlebells locked overhead, the ultimate leg stability challenge.'),
('1809eeaf-ff66-4ed5-a46e-e39e895b6f34', 'f193aa17-015a-4102-bba9-f4be51a3495a', 'es', 'Sentadilla Búlgara búlgara con pesas rusas dobles desde abajo hacia arriba', 'Sentadilla split con pie elevado manteniendo dos pesas rusas invertidas bloqueadas sobre la cabeza, el reto maximo de estabilidad de piernas.'),
('7b73e4de-0b4a-4f6d-be68-56afc2c0d597', 'f195be9a-a21a-430e-b9c0-9fe7821e4540', 'en', 'Triple Board Press', 'Bench press with three boards on the chest to limit range. Cue: control the contact. Error: sinking the boards.'),
('3347f199-6a8b-47ef-b8d2-988571f9811e', 'f195be9a-a21a-430e-b9c0-9fe7821e4540', 'es', 'Board Press triple tabla', 'Press banca con tres tablas sobre el pecho para limitar rango. Cue: controla el contacto. Error: hundir las tablas.'),
('c439a882-37f4-409c-88bb-47bf2aea89aa', 'f1a28ce8-8867-42a5-a1a9-591a2f813cdd', 'en', 'Close Grip Barbell Press', 'Perform a bench press with a close grip (hands shoulder-width apart or less). Lower the bar toward the lower chest keeping elbows close to the body. This variation significantly emphasizes the triceps.'),
('f031be54-b2ec-4e4d-9cc5-0111b3299f5e', 'f1a28ce8-8867-42a5-a1a9-591a2f813cdd', 'es', 'Press cerrado barra', 'Realiza un press de banca con agarre cerrado (manos separadas al ancho de los hombros o menos). Desciende la barra hacia la parte inferior del pecho manteniendo los codos cerca del cuerpo. Esta variación enfatiza significativamente los tríceps.'),
('72a837ca-7b7f-43a3-9ded-1c4e869e94fe', 'f1c377e7-b87d-4b97-b502-433c6f93593f', 'es', 'Peso muerto rumano con barra', 'Baja la barra rozando piernas con rodillas semi-rígidas hasta sentir estiramiento en isquios. Cue: cadera hacia atrás. Error: curvar la espalda alta.'),
('20fd1b0b-fd21-4f1f-a545-cc7ed75aaa02', 'f1dd0223-7608-4e13-acda-0f93de8a02aa', 'en', 'Prone Pull-ups', 'Hang from a bar with palms forward and pull until chin clears the bar. Cue: chest to the bar. Error: using excessive leg momentum.'),
('abc4cdc9-b553-418e-b3b0-fbe3396d6bd2', 'f1dd0223-7608-4e13-acda-0f93de8a02aa', 'es', 'Dominadas pronas (Pull-ups)', 'Cuélgate de una barra con palmas al frente y tira hasta que la barbilla pase la barra. Cue: pecho a la barra. Error: usar excesivo impulso de piernas.'),
('9c6c64ce-e003-4233-b0aa-fe0ba4f37a0b', 'f1e58a46-9266-468e-9830-5af6525910ff', 'en', 'Single Arm Reverse Grip Triceps Extension', 'Facing the pulley, grab the handle with palm facing up (supine). Extend arm downward isolating the triceps.'),
('bcacc3bb-846f-4e4b-8ac1-d5de9224b953', 'f1e58a46-9266-468e-9830-5af6525910ff', 'es', 'Extensión de tríceps agarre inverso a una mano', 'Frente a la polea, agarra el mango con la palma hacia arriba (supino). Extiende el brazo hacia abajo aislando el tríceps.'),
('53ef1383-ce44-4b6d-b8f4-f04ec68cff19', 'f23fda48-ca02-4963-b94e-df35956f8804', 'en', 'Klokov Press', 'Behind-the-neck barbell shoulder press using a very wide grip (snatch type). Objective: shoulder strength and scapular mobility. Cues: neutral back and firm core. Common error: sudden movements that stress the shoulder joint.'),
('4da6f572-c110-4c65-83c1-9c829566ede8', 'f23fda48-ca02-4963-b94e-df35956f8804', 'es', 'Press Klokov', 'Press de hombros con barra tras nuca utilizando un agarre muy ancho (tipo arranque). Objetivo: fuerza de hombros y movilidad escapular. Cues: espalda neutra y core firme. Error común: realizar movimientos bruscos que estresen la articulación del hombro.'),
('15999ea1-f153-40ae-94b0-b63b474ebd89', 'f26ae56c-9f5d-44c1-8e34-ef1752674ab9', 'en', 'Stability Ball Russian Twist', 'Support the upper back on the Fitball, with feet flat on the floor and hips raised. Join hands over the chest and rotate the torso to one side and then the other, maintaining hip stability.'),
('94a27829-d8c9-4d50-a855-ab24149a1c27', 'f26ae56c-9f5d-44c1-8e34-ef1752674ab9', 'es', 'Russian Twist sobre Fitball', 'Apoya la parte superior de la espalda sobre el Fitball, con los pies planos en el suelo y las caderas elevadas. Junta las manos sobre el pecho y gira el torso hacia un lado y luego hacia el otro, manteniendo la estabilidad de las caderas.'),
('07b773f7-2666-41c2-a521-844adf7ce647', 'f2a683fa-fb42-4e66-9425-88351a721394', 'en', 'Devil Press', 'Burpee with dumbbells followed by a double snatch from the floor. Cue: fluid movement, neutral back. Error: rounding the back when lifting from the floor.'),
('79df98fc-c946-4d6c-93ee-c82f5de18a2f', 'f2a683fa-fb42-4e66-9425-88351a721394', 'es', 'Devil Press', 'Burpee con mancuernas seguido de un snatch doble desde el suelo. Cue: movimiento fluido, espalda neutra. Error: redondear la espalda al levantar del suelo.'),
('c5890624-35eb-46e2-88af-974a2db1c9c9', 'f3181314-81f9-401a-8870-726f7288c4b1', 'es', 'Push Jerk a una mano con Kettlebell', 'Usa el impulso de las piernas para elevar la pesa rusa, luego flexiona las rodillas de nuevo para recibir el peso con el brazo estirado (Lockout).'),
('af150365-6f6e-4666-8ee7-a625e67852f7', 'f3194bef-ebdf-4389-a33c-47fa3a628cf9', 'en', 'Parallette Stalder Press to Handstand', 'From a seated straddle L-sit, press the body upward with straight arms until reaching a vertical handstand.'),
('35d35a4c-bb23-42a8-a678-563927478b70', 'f3194bef-ebdf-4389-a33c-47fa3a628cf9', 'es', 'Stalder Press a parada de manos en paralelas', 'Desde un L-Sit sentado con piernas abiertas (straddle), presiona el cuerpo hacia arriba con brazos rectos hasta la vertical.'),
('33e61072-6ed9-4a25-938e-cf1a37fdeda0', 'f3335c32-0c4e-4b54-a882-d6fd836da2e0', 'en', 'Barbell Squat Clean', 'Bring the bar from the floor to the shoulders explosively and catch it in a deep squat position before rising.'),
('c81ae910-fcc8-4aa4-ac6e-f5afee46dc2f', 'f3335c32-0c4e-4b54-a882-d6fd836da2e0', 'es', 'Squat Clean con barra', 'Lleva la barra desde el suelo hasta los hombros de forma explosiva y recíbela en una posición de sentadilla profunda antes de subir.'),
('17d40d29-7d8f-4364-a642-86aad2b5555c', 'f37a35a9-8ddb-48cd-99cc-84ec6aa03938', 'en', 'Bodyweight Flutter Kicks', 'Lie on your back with your hands under your glutes. Lift both legs slightly off the ground and perform alternating small, fast kicking movements without touching the floor.'),
('d0abde3c-4c5e-4ec6-9872-03a40fee8693', 'f37a35a9-8ddb-48cd-99cc-84ec6aa03938', 'es', 'Flutter Kicks', 'Acuéstate boca arriba con las manos bajo los glúteos. Levanta ambas piernas ligeramente del suelo y realiza movimientos alternos de patada pequeña y rápida sin tocar el suelo.'),
('60f9464b-c84f-48b3-9da2-504b9eb96bc6', 'f382f928-be54-49b1-b596-0330389ead8e', 'en', 'Legless Rope Climb', 'Climb using only the arms with legs extended without touching the rope. Requires exceptional pulling and grip strength. One of the most impressive demonstrations of upper body strength. Progress with assisted climbing.'),
('db37be31-d9ea-4645-b140-a5273a06a9b3', 'f382f928-be54-49b1-b596-0330389ead8e', 'es', 'Trepar cuerda sin piernas', 'Trepa usando solo los brazos con las piernas extendidas sin tocar la cuerda. Requiere fuerza de tracción y agarre excepcionales. Una de las demostraciones más impresionantes de fuerza del tren superior. Progresa con trepa asistida.'),
('1d8903f6-b0a6-459b-94ef-29294f6d25e6', 'f385ad4b-1538-44f4-91ba-74fd9ab34e11', 'en', 'Single Arm Kettlebell Suitcase Contralateral Step Up', 'Step up onto the bench with one leg while holding the kettlebell in the opposite hand (suitcase style), challenging lateral stability.'),
('b0113626-c387-42b3-ba09-32e6a88b8c63', 'f385ad4b-1538-44f4-91ba-74fd9ab34e11', 'es', 'Step Up contralateral con Kettlebell a una mano (Maleta)', 'Sube al banco con una pierna mientras sostienes la Kettlebell en la mano opuesta (estilo maleta), desafiando la estabilidad lateral.'),
('c62f0be9-a5c1-413f-bc21-5051b39561f3', 'f39b4645-2c11-4420-9885-5bc215caccfb', 'es', 'Y-pull TRX', 'Desde posición inclinada, tira formando una Y con los brazos. Trabaja la espalda desde un ángulo diferente y activa más los deltoides posteriores. Mantén los brazos rectos o ligeramente flexionados durante el movimiento.'),
('1e4e2846-9f17-4ad0-96d5-62e83ee83a89', 'f3a71764-2c8b-4bc5-bfa6-fad41b0c32df', 'en', 'TRX Single Leg Burpee', 'Burpee with one leg in the TRX strap. Dramatically increases difficulty and stabilization work. Alternate legs. Keep the movement fluid despite the instability.'),
('8bc63f74-dbb1-44fb-8213-149e4dd2b248', 'f3a71764-2c8b-4bc5-bfa6-fad41b0c32df', 'es', 'Burpee una pierna TRX', 'Burpee con una pierna en la correa del TRX. Aumenta dramáticamente la dificultad y el trabajo de estabilización. Alterna piernas. Mantén el movimiento fluido a pesar de la inestabilidad.'),
('dca43fc7-91fc-4b72-930a-d438f2a6c136', 'f3bb80af-25d9-4d55-b8b6-4cc038fc2650', 'en', 'Bodyweight Alternating Lateral Kick Through', 'From a quadruped position with knees raised, rotate the body and kick with one leg under the body to the opposite side while lifting the opposite hand.'),
('6a32fab8-2cad-4fc5-93ed-912076d0e530', 'f3bb80af-25d9-4d55-b8b6-4cc038fc2650', 'es', 'Kick Through lateral alterno', 'Desde posición de cuadrupedia con rodillas elevadas, gira el cuerpo y patea con una pierna por debajo del cuerpo hacia el lado opuesto mientras levantas la mano contraria.'),
('ab8f0cb5-5dbb-41c9-a0af-660cbb9d0ff2', 'f3e59401-47ef-4c47-9b20-86036f25b4d0', 'en', 'Medicine Ball Russian Twist', 'Rotate the ball side to side while seated. Objective: obliques. Cue: feet in the air. Error: moving only arms.'),
('932b3a0e-9652-404c-a245-aa18e3e0da00', 'f3e59401-47ef-4c47-9b20-86036f25b4d0', 'es', 'Russian twist balón medicinal', 'Gira balón lado a lado sentado. Objetivo: oblicuos. Cue: pies aire. Error: mover solo brazos.'),
('bd1b0992-ffa9-4cf0-b8e7-4ee33d9747dc', 'f3ea1b6f-d689-46e8-af5c-46172a3cbada', 'en', 'Incline Bench Prone Dumbbell Row', 'Lie face down on an incline bench. Row both dumbbells upward squeezing the back, without using momentum from the lower back.'),
('d9b83649-bccf-446c-a252-65341bc215f3', 'f3ea1b6f-d689-46e8-af5c-46172a3cbada', 'es', 'Remo prono en banco inclinado con mancuernas', 'Acuéstate boca abajo en un banco inclinado. Rema ambas mancuernas hacia arriba apretando la espalda, sin usar impulso de la espalda baja.'),
('f440fc3a-5d37-4503-92b3-aef048ca3596', 'f413d7ac-ffe3-4e76-bccf-5d77fdf654e5', 'en', 'Strict Straight Bar Pulley Bicep Curl', 'Flex bar on low pulley. Cue: constant tension. Error: swinging.'),
('530b84e4-6366-4825-8273-8d142490bacf', 'f413d7ac-ffe3-4e76-bccf-5d77fdf654e5', 'es', 'Curl bíceps polea barra recta estricto', 'Flexiona barra en polea baja. Cue: tensión constante. Error: balanceo.'),
('d2875c49-d63d-43e8-9549-2f7de5896d30', 'f448af64-0e5f-430b-ad4a-f2ef2c4d7bd9', 'en', 'Lateral Jump from Bosu to Floor', 'Jump laterally from the flat side of a Bosu to the floor and stabilize. Unstable impact control. Cue: nail the landing. Common error: letting the Bosu move when jumping.'),
('cbfc3471-a146-4d52-8cc3-74917907a102', 'f448af64-0e5f-430b-ad4a-f2ef2c4d7bd9', 'es', 'Salto lateral de bosu a suelo', 'Salta lateralmente desde el lado plano de un bosu hacia el suelo y estabiliza. Control de impacto inestable. Cue: clava el aterrizaje. Error común: dejar que el bosu se mueva al saltar.'),
('0b697154-1d4b-460d-8324-ad7b4b0c95b9', 'f4525288-45a4-4684-a400-21a4ee4b7bbc', 'en', 'Ring Hanging L-Sit Flutter Kicks', 'Hang from the rings and lift your legs straight to form an L. Maintain that position while performing flutter kicks with your legs.'),
('d492f7e2-4ec8-4119-a290-7b0c15202d0c', 'f4525288-45a4-4684-a400-21a4ee4b7bbc', 'es', 'L-Sit Flutter Kicks colgado en anillas', 'Cuélgate de las anillas y levanta las piernas rectas hasta formar una L. Mantén esa posición mientras realizas patadas de aleteo (Flutter Kicks) con las piernas.'),
('de310116-bc15-447a-b39b-9c9754f91272', 'f464fde1-09fd-457f-9fa5-65cafd1720ab', 'es', 'Zancada inversa ipsilateral con Slider y Kettlebell (Front Rack)', 'Sostén la pesa rusa en posición de rack y desliza hacia atrás la pierna del mismo lado usando un slider para un reto de equilibrio extremo.'),
('07baa1b1-c8d2-45b4-991d-7f9d7b71c462', 'f4897226-6dea-40af-978f-8777c23e7784', 'en', 'Bench Supported Bent Over Row', 'Row with the chest supported on an incline bench. Eliminates momentum and protects the lower back. Allows for greater concentration on the contraction. The bench should be at 30-45 degrees. Let the arms hang completely.'),
('7817eba7-e60c-4565-ae91-8447c53ed6e9', 'f4897226-6dea-40af-978f-8777c23e7784', 'es', 'Remo inclinado en banco', 'Remo con el pecho apoyado en banco inclinado. Elimina el impulso y protege la espalda baja. Permite mayor concentración en la contracción. El banco debe estar a 30-45 grados. Deja que los brazos cuelguen completamente.'),
('eb773df5-559b-447b-bb02-3aa3d2311d26', 'f4a92ac7-192d-4e71-baed-41c3d63e9e62', 'en', 'Back Lever', 'Similar to the front lever but facing upward. Considered harder than the front lever. Requires exceptional shoulder strength and flexibility. Progress carefully to avoid injury. Master the front lever first.'),
('fa5ab7e7-2483-43e8-bab2-c94c9a8a6622', 'f4a92ac7-192d-4e71-baed-41c3d63e9e62', 'es', 'Palanca posterior', 'Similar a la palanca frontal pero mirando hacia arriba. Considerada más difícil que la frontal. Requiere fuerza y flexibilidad excepcionales en hombros. Progresa cuidadosamente para evitar lesiones. Domina la palanca frontal primero.'),
('ac2ccd72-18aa-418b-8a0d-a340b454cd23', 'f4a9daaf-2f19-4291-b2fc-554d315149f6', 'en', 'Static Zercher Lunge', 'Lunge with the bar in the crook of the elbows. Cue: bar glued to the chest. Error: tilting the torso forward.'),
('91368d4d-7791-415b-9aa2-40c24b64b2aa', 'f4a9daaf-2f19-4291-b2fc-554d315149f6', 'es', 'Zancada Zercher estática', 'Zancada con barra en el pliegue de codos. Cue: barra pegada al pecho. Error: inclinar el torso hacia adelante.'),
('4ab32af2-a9f2-44f3-abca-7fa9bb377f05', 'f4e33d20-32bb-499b-9a48-2cfa4f800497', 'es', 'Press Overhead de rodillas con Kettlebell doble', 'Arrodillado sobre ambas rodillas (Tall Kneeling), realiza un press de hombros con dos pesas rusas, exigiendo mayor estabilidad del core.'),
('6192914e-1702-4577-9f5f-aa7a6efb304c', 'f4f08874-1e91-44ad-83a0-a7b809aaf34c', 'es', 'Prensa de piernas 45 grados', 'Empuja la plataforma con los pies a la anchura de hombros. Cue: no bloquees rodillas al extender. Error: bajar tanto que se levante el coxis.'),
('418b1957-1784-4ddb-9a40-f8420abbd354', 'f51abd12-dab8-4e2a-9bc9-4594e26a0dc1', 'en', 'One Arm Handstand', 'Inverted balance held by a single hand. Requires exceptional strength, perfect balance, and years of practice. Progress by first mastering the two-arm handstand perfectly. Core control is fundamental.'),
('933b96cb-9c85-41f0-9781-b9460d4105ad', 'f51abd12-dab8-4e2a-9bc9-4594e26a0dc1', 'es', 'Parada de manos a un brazo', 'Equilibrio invertido sostenido por una sola mano. Requiere fuerza excepcional, equilibrio perfecto y años de práctica. Progresa dominando primero la parada de manos a dos brazos perfectamente. El control del core es fundamental.'),
('2a450a35-70e8-4312-bdd3-c6bac81ce8d8', 'f563ca40-104d-457b-850f-ed22775e863a', 'en', 'Horizontal Oblique Cable Woodchopper', 'Pull cable from side to side. Cue: pivot foot. Error: moving only arms.'),
('f03b7c13-3f69-4966-99b9-39e4c2786cc1', 'f563ca40-104d-457b-850f-ed22775e863a', 'es', 'Horizontal Woodchopper cable oblicuos', 'Tira cable de lado a lado. Cue: pivota pie. Error: mover solo brazos.'),
('93d76bb0-c848-4ae5-b83a-40d56e97ecee', 'f5710907-e29d-4c26-bd52-b330dddbe71f', 'en', '1 and 1/4 Squat', 'Lower, rise slightly, lower again, and rise completely. Objective: time under tension. Cue: bounce control. Error: poor posture.'),
('b5d48144-9c88-42bf-987d-bc4d75f54f00', 'f5710907-e29d-4c26-bd52-b330dddbe71f', 'es', 'Sentadilla 1 y 1/4', 'Baja, sube un poco, baja y sube total. Objetivo: tiempo tensión. Cue: control rebote. Error: mala postura.'),
('9e97cd4b-85d2-4532-933d-58a445b28395', 'f58d3fe0-4ecd-4103-a60a-59fe37e24ba7', 'en', 'Low Pulley Bar Shrugs', 'Lift shoulders with cable in front. Cue: do not rotate shoulders. Error: bending elbows.'),
('742dc26a-3bbb-4cf7-9cf6-f7e20498024c', 'f58d3fe0-4ecd-4103-a60a-59fe37e24ba7', 'es', 'Encogimientos polea baja barra trapecios', 'Eleva hombros con cable al frente. Cue: no rotes hombros. Error: doblar codos.'),
('4a398d2f-4c4d-49b9-9cd9-327679a41eb9', 'f5914370-0521-4772-b8bb-3fbf97a1e8c8', 'en', 'Ring Front Lever Pull to Inverted Hang', 'From the Front Lever position, pull strongly on the rings to lift the body until completely inverted upside down.'),
('9586e695-82cb-45a1-b10f-2b0bd3e1c89d', 'f5914370-0521-4772-b8bb-3fbf97a1e8c8', 'es', 'Pull de Front Lever a colgado invertido en anillas', 'Desde la posicion de Front Lever, tira con fuerza de las anillas para elevar el cuerpo hasta quedar completamente invertido boca abajo.'),
('385baf08-559b-4eb5-a2ab-4da5e948754b', 'f5ff2119-41af-4377-a4f9-a93e76eb2f08', 'en', 'Heel Taps', 'Lying down, touch alternate heels. Objective: obliques. Cue: squeeze abdomen. Error: pulling on the neck.'),
('de9ff6aa-4104-4022-8e12-5840593c623a', 'f5ff2119-41af-4377-a4f9-a93e76eb2f08', 'es', 'Toques talón suelo', 'Tumbado toca talones alternos. Objetivo: oblicuos. Cue: aprieta abdomen. Error: tirar cuello.'),
('e3d67383-3bc8-493f-8851-3c9a9faa8306', 'f619950e-9cdb-4194-928a-564bb5e73147', 'en', 'Parallette L Sit to Bent Arm Press Handstand', 'From an L-Sit on parallettes, transition your legs back and up while pressing your torso into a vertical handstand.'),
('d0cc2c82-c64b-43fa-b4f0-977a6590913b', 'f619950e-9cdb-4194-928a-564bb5e73147', 'es', 'L-Sit a Bent Arm Press Handstand en paralelas', 'Desde un L-Sit en paralelas, transiciona las piernas hacia atrás y arriba empujando el torso hasta llegar a la parada de manos vertical.'),
('57843676-1600-444d-a1e2-970af395d57c', 'f648f3ec-fbd9-443e-ad75-4d7a0459eb00', 'en', 'Ring Inverted Iron Cross', 'Maintain your body vertically inverted while extending your arms laterally in a cross, an extreme variant of ring strength.'),
('4891a8ad-ab37-42b5-aee9-8d63be83e2d5', 'f648f3ec-fbd9-443e-ad75-4d7a0459eb00', 'es', 'Anillas Cruz de Hierro Invertida', 'Manten el cuerpo invertido verticalmente mientras extiendes los brazos lateralmente en cruz, una variante extrema de fuerza en anillas.'),
('35952997-86d0-4069-8dae-06354ad04852', 'f65ee455-5923-40db-8da5-5d64064202f3', 'es', 'Plancha Spiderman', 'En posición de plancha o flexión, lleva la rodilla hacia el codo del mismo lado por fuera del cuerpo. Objetivo: oblicuos y core. Cue: mantén la cadera baja. Error: elevar el glúteo para facilitar el movimiento.'),
('85d426b6-5ccb-4ffc-98c0-e950f822a611', 'f66f6aff-0f29-4665-a7e7-1564a0320e6a', 'es', 'Plancha frontal en Fitball', 'Mantén plancha con antebrazos en fitball inestable. Objetivo: estabilidad profunda core. Cue: aprieta glúteos. Error común: que la bola se aleje demasiado del cuerpo.'),
('6c9ef626-3350-4bd5-b71f-64bef51b3b26', 'f6bfb695-7253-41eb-ba44-3fed0984cca6', 'en', 'Bodyweight Copenhagen Plank Knee to Elbow', 'In a side plank position with the upper leg supported on a bench, bring the knee of the lower leg toward the elbow, keeping the hips high.'),
('f374728c-4da0-4302-87b1-a8b3ff94ec2e', 'f6bfb695-7253-41eb-ba44-3fed0984cca6', 'es', 'Copenhagen Plank rodilla a codo', 'En posición de Plank lateral con la pierna superior apoyada en un banco, lleva la rodilla de la pierna inferior hacia el codo, manteniendo la cadera alta.'),
('287e95fa-d65a-4cec-b96f-abb95637e3fd', 'f6e5b2e8-db14-4e41-8f40-b4fd4445d582', 'en', 'Zigzag Pogo Jump', 'Small fast jumps on the balls of the feet moving laterally forward. Agility. Cue: keep feet together. Common error: flexing hips too much.'),
('ca3f3518-f443-42bd-ae6a-36ec9b86eb1f', 'f6e5b2e8-db14-4e41-8f40-b4fd4445d582', 'es', 'Salto pogo en zigzag', 'Pequeños saltos rápidos sobre puntas de pies moviéndote lateralmente hacia adelante. Agilidad. Cue: mantén pies juntos. Error común: flexionar demasiado las caderas.'),
('35ac4047-8f82-465f-8453-ad51c01df486', 'f7a34a44-9d02-44bd-9f19-c9affbcbcc1f', 'en', 'Barbell Conventional Deadlift', 'Lift the bar from the floor maintaining a neutral back, extending knees and hip simultaneously until standing.'),
('15b65d9a-683b-47b5-b1d6-6805613f3ffc', 'f7a34a44-9d02-44bd-9f19-c9affbcbcc1f', 'es', 'Peso muerto convencional con barra', 'Levanta la barra desde el suelo manteniendo la espalda neutra, extendiendo rodillas y cadera simultáneamente hasta quedar erguido.'),
('09b849eb-f513-4cc6-ac17-a99e535f40ba', 'f7a67add-c76d-4994-8f7e-ae94f8fc5a59', 'es', 'Zancada inversa ipsilateral con Slider y Kettlebell Bottoms Up', 'Sostén una pesa rusa invertida en una mano y desliza hacia atrás la pierna del mismo lado usando un slider, desafiando la estabilidad total.'),
('57953ccf-2a41-4f00-b174-f0d07ad7c06c', 'f7ae92b4-5450-4a81-a145-d6fac4ece98b', 'en', 'Single Arm Landmine Half Kneeling Contralateral Shoulder Press', 'In a half-kneeling position, press the landmine bar with the arm opposite to the lead knee, working on cross-stability.'),
('ddf833f3-0d04-4737-b6d7-7a9f495a0eb2', 'f7ae92b4-5450-4a81-a145-d6fac4ece98b', 'es', 'Press de hombros contralateral medio arrodillado en Landmine', 'En posicion de caballero, presiona la barra Landmine con el brazo opuesto a la rodilla adelantada, trabajando la estabilidad cruzada.'),
('d59a4046-0b12-4e0c-909f-bd060d1cb3f8', 'f7e4ee4f-8d92-4493-b0c5-2233b503f22e', 'en', 'Band Resisted Reactive Vertical Jump', 'Jump vertically with an elastic band pulling you downward. Increases recruitment speed. Cue: maximum ankle extension. Common error: letting the band hunch you over.'),
('bbc97f0b-6191-4054-b64c-c63abc62a437', 'f7e4ee4f-8d92-4493-b0c5-2233b503f22e', 'es', 'Salto vertical reactivo con banda', 'Salta verticalmente con una banda elástica tirando de ti hacia abajo. Aumenta la velocidad de reclutamiento. Cue: máxima extensión de tobillo. Error común: dejar que la banda te encorve.'),
('c31c884a-c599-48f6-8f19-da321cff6596', 'f80b064a-a6e1-47fa-bc87-19d658f3b163', 'en', 'Band Quadriceps Extension', 'Seated, extend the knee against the resistance of an elastic band anchored behind. Objective: quadriceps isolation. Cues: keep the back straight. Common error: performing the movement with excessive speed without control.'),
('b39801f5-aaf8-47b4-955e-cbe6cd775824', 'f80b064a-a6e1-47fa-bc87-19d658f3b163', 'es', 'Extensión de cuádriceps con banda', 'Sentado, extiende la rodilla contra la resistencia de una banda elástica anclada atrás. Objetivo: aislamiento del cuádriceps. Cues: mantén la espalda recta. Error común: realizar el movimiento con excesiva rapidez sin control.'),
('303f4e31-5693-4324-9823-d4891f639b15', 'f845a294-b8b9-49f0-b3e5-b7d482e49f4c', 'en', 'Double Kettlebell Bottoms Up Front Rack Bulgarian Split Squat', 'Perform a split squat with the rear foot elevated on a bench while holding two upside-down kettlebells in a front rack position on the chest.'),
('9c5b38c7-3c0e-4190-83ac-8e10c9bb9685', 'f845a294-b8b9-49f0-b3e5-b7d482e49f4c', 'es', 'Sentadilla Búlgara con doble pesa rusa de abajo hacia arriba y con rejilla frontal', 'Realiza una sentadilla split con el pie trasero elevado en un banco mientras sostienes dos Kettlebells invertidas en posicion de rack sobre el pecho.'),
('7d28ca81-cdb9-4568-b017-080fd45d6ae1', 'f84a4a04-1c3f-4301-b2df-16d3ef760156', 'en', 'Battle Ropes Slams', 'Lift both ropes overhead and slam them against the floor with maximum force. Use the entire body in the movement, not just the arms. Maintain a constant and explosive pace. Excellent for developing power.'),
('bbe8ab6b-39f5-443c-b0f5-8805c9273ed0', 'f84a4a04-1c3f-4301-b2df-16d3ef760156', 'es', 'Battle ropes slams', 'Eleva ambas cuerdas sobre la cabeza y golpéalas contra el suelo con fuerza máxima. Usa todo el cuerpo en el movimiento, no solo los brazos. Mantén un ritmo constante y explosivo. Excelente para desarrollar potencia.'),
('5b2ce1bf-7700-40da-821b-a202b2231363', 'f86dad4c-2dd7-43a4-8719-59fdf34e59df', 'en', 'Suitcase carry', 'Walk holding weight on only one side like a heavy suitcase. Maximum challenge for core anti-lateral flexion. Keep shoulders leveled and upright posture. Change sides at half distance or in separate sets.'),
('b1cbe31c-be34-47ef-a82f-215279bab56f', 'f86dad4c-2dd7-43a4-8719-59fdf34e59df', 'es', 'Carga maleta', 'Camina sosteniendo peso solo en un lado como una maleta pesada. Máximo desafío anti-flexión lateral del core. Mantén hombros nivelados y postura erguida. Cambia de lado a mitad de distancia o en series separadas.'),
('adae25be-538f-4c3c-864b-46785afcf0af', 'f8974e50-d2ff-43c9-938b-9045d76e8535', 'en', 'Battle Ropes Single Arm', 'Waves with a single arm while the other rests or stays static. Allows working unilaterally and with higher intensity per arm. Alternate arms in intervals. Keep a stable posture.'),
('a11669d0-b42b-42e7-ab54-36e05e0de895', 'f8974e50-d2ff-43c9-938b-9045d76e8535', 'es', 'Battle ropes single arm', 'Ondas con un solo brazo mientras el otro descansa o se mantiene estático. Permite trabajar unilateralmente y con mayor intensidad por brazo. Alterna los brazos en intervalos. Mantén la postura estable.'),
('369a8fc7-ea50-4cb4-a827-fd4e98bae6c4', 'f8cf4c0c-6440-4934-a7d1-d86f9a0832fd', 'en', 'Alternating Front Rack Dumbbell Step Up', 'Step onto the bench holding dumbbells at shoulder height (front rack). Alternate the leg that leads the movement.'),
('33c99ed4-e519-4af6-a9a2-838066a4c21c', 'f8cf4c0c-6440-4934-a7d1-d86f9a0832fd', 'es', 'Step Up alterno Front Rack con mancuernas', 'Sube al banco sosteniendo las mancuernas a la altura de los hombros (front rack). Alterna la pierna que lidera el movimiento.'),
('71a683fb-b536-4609-9f2f-079d4a9bbb25', 'f8ec8185-07be-4191-8564-9b2066cf079e', 'en', 'Cable Crossover (Upper Chest Focus)', 'Pulleys in a low position, bring hands together in front of the face. Objective: clavicular head of the pectoral. Cue: elbows slightly bent. Common error: shrugging shoulders while lifting.'),
('c53078c5-c5a4-448e-b9ea-26e853a2f39d', 'f8ec8185-07be-4191-8564-9b2066cf079e', 'es', 'Cruce de poleas (enfocado pectoral superior)', 'Poleas en posición baja, junta manos frente a la cara. Objetivo: haz clavicular del pectoral. Cue: codos semiflexionados. Error común: encoger hombros al subir.'),
('a8f32b7e-6c90-4e3c-8d18-37366fad4169', 'f8f8c8db-102e-4795-b806-9f6249fff95e', 'en', 'Single-Leg Romanian Deadlift', 'Perform a single-leg Romanian deadlift by hinging at the hip while the free leg moves backward. Keep the back neutral and return by engaging the glutes and hamstrings.'),
('0cb48f27-19dc-470d-b03c-2a6029c679c6', 'f8f8c8db-102e-4795-b806-9f6249fff95e', 'es', 'Peso muerto a una pierna', 'Realiza un peso muerto a una pierna inclinando el tronco desde la cadera mientras la pierna libre se desplaza hacia atrás. Mantén la espalda neutra y vuelve activando glúteo e isquios.'),
('b03e1668-3ac8-49c3-84c2-cde67a3533d2', 'f9054898-a3fd-489f-9239-9da1bed52007', 'en', 'Seated Dumbbell Bicep Curl', 'Seated with back supported, flex dumbbells alternately or together. Objective: biceps. Cue: elbows fixed to the side of the body. Error: swinging the torso to lift the weight.'),
('fb696c3e-3d3e-4035-9305-b9f285b13935', 'f9054898-a3fd-489f-9239-9da1bed52007', 'es', 'Curl de bíceps sentado con mancuernas', 'Sentado con espalda apoyada, flexiona las mancuernas alternativamente o a la vez. Objetivo: bíceps. Cue: codos fijos al costado del cuerpo. Error: balancear el tronco para subir el peso.'),
('c7f61863-b554-487d-9b13-494501d1602f', 'f90f1a5f-6ec3-4b42-a15d-3d17372d74b9', 'en', 'Kettlebell Horn Grip Bicep Curl', 'Standing, hold the kettlebell by the side horns. Perform bicep curls keeping elbows glued to the ribs.'),
('99acc8ab-970b-4619-8292-a534cb12a4d2', 'f90f1a5f-6ec3-4b42-a15d-3d17372d74b9', 'es', 'Curl de bíceps agarre de cuernos con Kettlebell', 'De pie, sujeta la pesa rusa por los cuernos laterales. Realiza curls de bíceps manteniendo los codos pegados a las costillas.'),
('886a0f83-524b-4780-9be9-ebfae0b0ae82', 'f9274a29-b3ba-464c-8a0d-68f5f3a80732', 'en', 'Abductor Machine', 'Open legs while seated against resistance. Objective: gluteus medius. Cues: back on backrest. Common error: leaning forward to assist.'),
('ad008e84-9fe0-43e6-84f1-a8f810e162e9', 'f9274a29-b3ba-464c-8a0d-68f5f3a80732', 'es', 'Máquina de abductores', 'Abre piernas sentado contra resistencia. Objetivo: glúteo medio. Cues: espalda en respaldo. Error común: inclinarse adelante para ayudar.'),
('0c17d425-e298-4257-9741-6e66c164fc94', 'f927b171-8cc1-48d4-a556-258fe3bc0038', 'en', 'Calf raises single leg', 'Standing on one leg, rise onto the ball of the foot as high as possible contracting the calf. Maintain balance without supporting the free leg. Descend slowly to maximize time under tension. You can hold on lightly for balance if necessary.'),
('3e91c69a-1c65-4991-a914-c4899a2137db', 'f927b171-8cc1-48d4-a556-258fe3bc0038', 'es', 'Calf raises single leg', 'De pie sobre una pierna, elévate sobre la punta del pie lo más alto posible contrayendo el gemelo. Mantén el equilibrio sin apoyar la pierna libre. Desciende lentamente para maximizar el tiempo bajo tensión. Puedes sujetarte ligeramente para mantener el equilibrio si es necesario.'),
('833a0b91-e986-4ac3-bad9-dc85e82ff193', 'f9349e5d-8606-4904-aa0e-f5686cdcb172', 'en', 'Barbell Deadlift', 'With the bar on the floor, grip it with hands outside the legs. Keep back straight, chest up, and pull the bar close to the body until full hip extension. It is one of the most complete exercises for total strength.'),
('2521c23f-aa84-4b70-bb2d-f5dd1582b589', 'f9349e5d-8606-4904-aa0e-f5686cdcb172', 'es', 'Peso muerto barra', 'Con la barra en el suelo, agárrala con las manos fuera de las piernas. Mantén la espalda recta, el pecho elevado y tira de la barra pegada al cuerpo hasta la extensión completa de caderas. Es uno de los ejercicios más completos para desarrollar fuerza total.'),
('d7815702-a94a-4d00-bb2a-6a2a35866a39', 'f9413669-385c-4c6a-8f4b-47fb47ab8345', 'en', 'Landmine Press', 'Press with a bar anchored in a landmine. The range of motion is more natural for the shoulder. Can be done unilateral or bilateral, kneeling or standing. Excellent for those with limitations in traditional overhead press.'),
('f01c3c71-fc52-44c0-8508-eeaf49776baa', 'f9413669-385c-4c6a-8f4b-47fb47ab8345', 'es', 'Press landmine', 'Press con barra anclada en landmine. El arco de movimiento es más natural para el hombro. Puede hacerse unilateral o bilateral, de rodillas o de pie. Excelente para quienes tienen limitaciones en press overhead tradicional.'),
('b1a4e18f-83ea-4b3c-a12a-c91314039195', 'f95ed1d1-847a-4896-a4f5-85870bacebcc', 'en', 'Circular Pogo Jump', 'Fast pogo jumps while rotating the body in a small circle. Improves foot agility and dynamic balance. Cue: tight ankles. Common error: making circles too large, losing speed.'),
('26585300-cac7-402e-9304-4de6f840d379', 'f95ed1d1-847a-4896-a4f5-85870bacebcc', 'es', 'Salto pogo circular', 'Saltos pogo rápidos mientras rotas el cuerpo en un círculo pequeño. Mejora la agilidad de los pies y el equilibrio dinámico. Cue: tobillos tensos. Error común: hacer círculos demasiado grandes perdiendo rapidez.'),
('139fe5ff-4039-4ed0-84b2-0cfb925add38', 'f9759f4d-7399-4efe-8a96-c671a3bccd37', 'en', 'Seated Cable Row', 'Seated pulley row for the back, emphasizing scapular retraction and torso control without swinging.'),
('63707ec4-dade-4c07-9cf4-0b0df077e4f0', 'f9759f4d-7399-4efe-8a96-c671a3bccd37', 'es', 'Remo en cable sentado', 'Tira llevando codos atrás, pecho estable. Aprieta escápulas al final y vuelve lento sin dejarte ‘arrastrar’.'),
('017f83ab-2480-4d2a-959c-a3e892aaa75c', 'f9a04ae3-ab31-475a-bbb7-db728864a1a5', 'en', 'Matrix Squat', 'Squat with an extreme posterior lean of the torso, almost parallel to the floor. Requires exceptional strength and flexibility in ankles and hips. Popularized by the Matrix movie. Start with smaller leans and progress.'),
('627328ac-c4a2-47f4-ba7a-8a43a1a95ed6', 'f9a04ae3-ab31-475a-bbb7-db728864a1a5', 'es', 'Sentadilla matrix', 'Sentadilla con inclinación posterior extrema del torso, casi paralelo al suelo. Requiere fuerza y flexibilidad excepcionales en tobillos y caderas. Popularizada por la película Matrix. Comienza con inclinaciones menores y progresa.'),
('db81f1fe-cd4b-40f2-8f99-1a56bdf381f8', 'f9afdbea-415c-4176-9b9b-1cef274c575b', 'en', 'Behind the Neck Barbell Squat', 'Bar over the trapezius, lower the hip while keeping the torso stable and rise. Cue: knees out. Error: lifting heels off the floor.'),
('23aeb966-aa98-4979-b0a9-409cbca5fcf8', 'f9afdbea-415c-4176-9b9b-1cef274c575b', 'es', 'Sentadilla con barra tras nuca', 'Barra sobre los trapecios, baja la cadera manteniendo el torso estable y sube. Cue: rodillas hacia afuera. Error: levantar los talones del suelo.'),
('e54ded36-7b80-4918-9c0c-d7808aa8c468', 'f9b0f414-ad7d-4c9f-be60-6155714ebbc1', 'en', 'Barbell Overhead Squat', 'Perform a squat with the bar locked overhead using a wide grip. Objective: total mobility and power. Cues: constantly push the bar toward the ceiling. Common error: losing bar verticality by letting it fall forward.'),
('298b3a8d-6e0a-4f5e-b629-0a860b351f0d', 'f9b0f414-ad7d-4c9f-be60-6155714ebbc1', 'es', 'Sentadilla overhead con barra', 'Realiza una sentadilla con la barra bloqueada sobre la cabeza con agarre ancho. Objetivo: movilidad total y potencia. Cues: empuja la barra hacia el techo constantemente. Error común: perder la verticalidad de la barra dejándola caer hacia adelante.'),
('90625513-908a-4536-be9f-61eddec5f966', 'f9e344ad-ea50-4a86-9ab9-3e0e74784638', 'en', 'Bottoms Up Cyclist Squat with Kettlebell (Horn Grip)', 'Elevate heels and hold the inverted kettlebell by the horns in front of the chest for a greater stability challenge during the squat.'),
('2f4f6a05-e3ae-47a1-8732-84a8fba22a9a', 'f9e344ad-ea50-4a86-9ab9-3e0e74784638', 'es', 'Sentadilla Ciclista con Kettlebell Bottoms Up (Horn)', 'Eleva talones y sujeta la Kettlebell invertida por los cuernos frente al pecho para un mayor desafio de estabilidad durante la sentadilla.'),
('c3ac7a88-7132-432b-815f-66db20a1e72c', 'f9fadfe5-4c0a-43ce-98af-c334b796100b', 'en', 'Full Sit-ups', 'Full sit-up from lying down to touching the feet. Objective: rectus abdominis and hip flexors. Cue: lower vertebra by vertebra in a controlled way. Common error: lifting feet off the floor to rise.'),
('494d4a12-49ba-445b-ba41-499ba4b78b11', 'f9fadfe5-4c0a-43ce-98af-c334b796100b', 'es', 'Sit-ups completos', 'Incorporación completa desde tumbado hasta tocar los pies. Objetivo: recto abdominal y flexores de cadera. Cue: baja vértebra a vértebra de forma controlada. Error común: despegar los pies del suelo para subir.'),
('3ef97829-424a-4b7e-ad70-2d95c1ca3aa1', 'fa31bc9f-a993-49df-8cbd-d15ddd8f62d1', 'en', 'Narrow Supine Bicep Pulldown', 'Pull to the chest with palms facing you. Cue: elbows down. Error: swinging.'),
('60db72dc-b640-4121-a6ee-1a4d9df635fd', 'fa31bc9f-a993-49df-8cbd-d15ddd8f62d1', 'es', 'Jalón supino estrecho bíceps', 'Tira al pecho palmas hacia ti. Cue: codos abajo. Error: balanceo.'),
('43890039-2b27-49e6-b857-e30d789d55b6', 'fa37fe81-f3d0-4beb-b130-35dfb7ffe440', 'en', 'Unilateral Step Up with Jump', 'Step onto the bench and jump as high as possible landing on the same foot. Unilateral power. Cue: stable knee. Common error: landing on the edge of the bench.'),
('b6742495-48df-4f39-b67e-47b8965fa66d', 'fa37fe81-f3d0-4beb-b130-35dfb7ffe440', 'es', 'Step up con salto unilateral', 'Sube al banco y salta lo más alto posible aterrizando sobre el mismo pie. Potencia unilateral. Cue: rodilla estable. Error común: aterrizar sobre el borde del banco.'),
('4a4259ce-4491-463d-8b1f-1a591fdd1587', 'fa4179b0-c88a-4528-8fe0-f07812aa5fa9', 'en', 'Incline Bench Front Raises', 'Chest on bench, lift weights forward. Objective: isolated anterior deltoid. Cue: control descent. Error: using momentum.'),
('f71f03c5-631c-4bad-8d9b-be1db34cc24d', 'fa4179b0-c88a-4528-8fe0-f07812aa5fa9', 'es', 'Elevaciones frontales banco inclinado', 'Pecho en banco, eleva pesas al frente. Objetivo: deltoides anterior aislado. Cue: controla bajada. Error: usar impulso.'),
('4b9e327b-558c-40ad-a3e7-59c015366a6a', 'fa7b096d-323a-422a-a019-1a54876493b2', 'en', 'Barbell Reverse Wrist Curl', 'Rest forearms and lift the back of the hand with palms facing down. Objective: wrist extensors. Cue: control the weight on the way down. Common error: using the shoulder for momentum.'),
('4a64d249-d17d-403d-88e6-91e79e4bf5cd', 'fa7b096d-323a-422a-a019-1a54876493b2', 'es', 'Curl de muñeca invertido con barra', 'Apoya antebrazos y eleva el dorso de la mano con palmas hacia abajo. Objetivo: extensores de muñeca. Cue: controla la bajada del peso. Error común: usar el hombro para dar impulso.'),
('a3c78dca-95de-4bc6-ad12-78eba5e78b97', 'fa894b36-7ab2-4ac4-871b-8c35f4a6ee6f', 'en', 'Close-Grip Lat Pulldown', 'Perform a close-grip lat pulldown. Pull the handle toward the upper chest while keeping the torso stable and controlling the return.'),
('3e93a7a5-5302-4a07-9a0d-4ba10bb47f05', 'fa894b36-7ab2-4ac4-871b-8c35f4a6ee6f', 'es', 'Jalones cerrados al pecho', 'Realiza un jalón al pecho con agarre cerrado. Lleva el agarre hacia la parte alta del pecho manteniendo el torso estable y controlando la subida.'),
('777a5a3c-7bf3-4185-a290-90694b545edb', 'faa7e564-04d0-4cf1-b337-343669a3ec81', 'en', 'Vertical Jump from Kneeling', 'From a kneeling position, perform an explosive hip drive to land on your feet in a squat. Requires great glute power. Cue: swing arms for momentum. Common error: using hands on the floor to rise.'),
('a2fd3dca-cdb9-4beb-b6c0-9853004900c5', 'faa7e564-04d0-4cf1-b337-343669a3ec81', 'es', 'Salto vertical desde arrodillado', 'Desde posición de rodillas, realiza un golpe de cadera explosivo para caer de pie en sentadilla. Requiere gran potencia de glúteo. Cue: balancea los brazos para impulsarte. Error común: usar las manos en el suelo para subir.'),
('09e93408-e072-4137-b332-c3ef16fbdbd1', 'fabde350-b639-4130-a4f5-0e2cebd3dbc9', 'en', 'Soccer Throw Style Toss', 'Throw the medicine ball from behind the head forward with force. Objective: triceps and serratus power. Cue: feet well anchored. Common error: releasing the ball too late.'),
('b044c83d-35d2-4153-bf4a-51388d2834b9', 'fabde350-b639-4130-a4f5-0e2cebd3dbc9', 'es', 'Lanzamiento estilo saque de banda', 'Lanza el balón medicinal desde detrás de la cabeza hacia adelante con fuerza. Objetivo: potencia de tríceps y serrato. Cue: pies bien anclados. Error común: soltar el balón demasiado tarde.'),
('5a7a9d1b-5287-4d7d-a0a0-c1eb64c01491', 'fadfbf5a-5e7d-4a90-b7af-d01ee06b47fe', 'en', 'Ring Straddle Front Lever', 'Front Lever position keeping the body parallel to the ground with straight arms and legs straight and spread in a V-shape.'),
('a4f1c043-f6a8-4664-a762-c9862995cbdd', 'fadfbf5a-5e7d-4a90-b7af-d01ee06b47fe', 'es', 'Straddle Front Lever en anillas', 'Posicion de Front Lever manteniendo el cuerpo paralelo al suelo con los brazos rectos y las piernas estiradas y abiertas en forma de V.'),
('edc4a9de-0b47-4d89-b766-0f8d37a7d7fa', 'fae6ff9f-28ef-4c2d-bbe8-2ae642b7bad9', 'en', 'Unilateral Isometric Calf Raise on Leg Press', 'Single-leg calf work on the leg press with isometric contraction for ankle strength and running prevention.'),
('60cdc529-6d78-42dc-81bd-3e462d9afc9e', 'fae6ff9f-28ef-4c2d-bbe8-2ae642b7bad9', 'es', 'Elevación de talón isométrica en prensa unilateral', 'Sube a máxima punta y mantén la isometría el tiempo marcado. No rebotes; controla también la bajada.'),
('96ff16b7-74d5-41f0-8a10-286eab8c3338', 'fb22eca9-c390-439b-976d-43414f73b42d', 'en', 'Jefferson Deadlift', 'Deadlift with the bar between the legs, one foot forward and one behind. Works the body asymmetrically. Reduces lower back stress. Alternate foot position. Uncommon but effective.'),
('c62a0ea9-fa7a-401f-ac67-9efb31e66aa7', 'fb22eca9-c390-439b-976d-43414f73b42d', 'es', 'Peso muerto jefferson', 'Peso muerto con la barra entre las piernas, un pie adelante y otro atrás. Trabaja el cuerpo de forma asimétrica. Reduce estrés en espalda baja. Alterna la posición de pies. Poco común pero efectivo.'),
('b27202ce-16ce-4654-a93c-11d902f0356d', 'fb242680-dcc6-4f6a-b36c-d66604e9d590', 'en', 'Landmine Deadlift', 'Deadlift with one end of the bar anchored in a landmine or corner. Allows for a unique range of motion. Friendlier to the lower back. Can be done with parallel grip using attachment or perpendicular.'),
('89036b89-fe14-4fda-905f-32880c52d45b', 'fb242680-dcc6-4f6a-b36c-d66604e9d590', 'es', 'Peso muerto landmine', 'Peso muerto con un extremo de la barra anclado en landmine o esquina. Permite un arco de movimiento único. Más amigable para la espalda baja. Puede hacerse con agarre paralelo usando accesorio o perpendicular.'),
('9a8ae53c-f876-4010-acc6-bcc91b4b3e08', 'fb48f12a-83b9-4039-a90c-0e0eae7be43b', 'en', 'Unilateral Landmine Press', 'Bar anchored in a corner, push from the shoulder forward and up. Cue: lean slightly toward the bar. Error: rotating the torso when pushing.'),
('77dbfb17-f959-4b1d-883e-d7f79d368c8f', 'fb48f12a-83b9-4039-a90c-0e0eae7be43b', 'es', 'Landmine Press unilateral', 'Barra anclada en una esquina, empuja desde el hombro hacia adelante y arriba. Cue: inclínate ligeramente hacia la barra. Error: rotar el tronco al empujar.'),
('26a70586-0164-462b-9905-71b0b071f1ed', 'fb5b656e-4b18-4118-a83e-f3a86b76a84c', 'en', 'Single Arm Kettlebell Clean', 'Bring the kettlebell from the floor to the rack position in one fluid motion, smoothly rotating the weight around the forearm.'),
('2b7fed3f-cb71-4d71-921f-6c8a1cc5c1fc', 'fb5b656e-4b18-4118-a83e-f3a86b76a84c', 'es', 'Clean con Kettlebell a una mano', 'Lleva la Kettlebell desde el suelo hasta la posición de rack en un movimiento fluido, rotando la pesa alrededor del antebrazo con suavidad.'),
('a3fd7894-e3a7-46a8-b834-38b327556f9b', 'fb623f32-873d-45df-9615-9c1551f1e9b1', 'es', 'Push Press a una mano con Kettlebell', 'Flexiona ligeramente las rodillas y usa el impulso de las piernas para lanzar una pesa rusa sobre la cabeza, terminando con brazo estirado.'),
('61ba448f-c1df-499c-b3ad-ef15d0234d72', 'fba67106-35e7-4485-818d-823e8bddc892', 'en', 'Single Arm Battle Ropes Spirals', 'Circular movements with one rope while the other rests or performs another pattern. Allows for higher intensity per arm and unilateral work. Keep core stable to resist rotation.'),
('3e98b133-e5e4-4663-afa0-786cd6b463bc', 'fba67106-35e7-4485-818d-823e8bddc892', 'es', 'Espiral un brazo battle ropes', 'Movimientos circulares con una sola cuerda mientras la otra descansa o realiza otro patrón. Permite mayor intensidad por brazo y trabajo unilateral. Mantén el core estable para resistir rotación.'),
('5007c166-5d2a-4966-8bdf-81b540d674a8', 'fbc4ea2d-d739-49f5-8e44-70255f781618', 'es', 'Power pull TRX', 'Remo unilateral con rotación del torso. Combina tracción con rotación para un trabajo más funcional. Excelente para deportes que requieren movimientos de tracción con rotación. Mantén el core activado.'),
('a9c15aa9-41ac-4a2a-ab5c-5dd79dd6f3c4', 'fbc82fbd-d57a-478b-8fd0-e72a78e8b66a', 'en', 'Seated Machine Calf Raise', 'Seated with knees bent at 90 degrees, perform heel raises. This position emphasizes the soleus more than the gastrocnemius. Perform the full movement from maximum stretch to full contraction.'),
('2b699588-3558-445f-a0e6-06bcb492d9a4', 'fbc82fbd-d57a-478b-8fd0-e72a78e8b66a', 'es', 'Pantorrillas sentado máquina', 'Sentado con las rodillas flexionadas a 90 grados, realiza elevaciones de talones. Esta posición enfatiza el sóleo más que el gemelo. Realiza el movimiento completo desde el estiramiento máximo hasta la contracción completa.'),
('4ea44420-6d1a-458e-9e54-46021c31ad85', 'fbe5f913-9d48-4a03-9e2e-b0f3e6219d52', 'en', 'Battle Ropes Overhead Slam', 'Slams from a completely extended overhead position. Maximum power and range of motion. Involves full body extension. Slams must be explosive and continuous.'),
('3a9db4cb-036b-4361-8c17-75cac367efe9', 'fbe5f913-9d48-4a03-9e2e-b0f3e6219d52', 'es', 'Golpeo overhead battle ropes', 'Slams desde posición completamente extendida sobre la cabeza. Máxima potencia y rango de movimiento. Involucra extensión de todo el cuerpo. Los slams deben ser explosivos y continuos.'),
('74fecc4b-607c-49ae-b238-1f4c56bf82ec', 'fc0ba832-704a-4453-91b1-d96976a8a98a', 'en', 'Leaning Rotational Wall Toss', 'Lateral medicine ball throw with the torso leaning forward. Objective: obliques and rotational power. Cue: flat back. Common error: arching the lower back.'),
('11e8af87-9e30-46cd-9357-ff8cd31e5343', 'fc0ba832-704a-4453-91b1-d96976a8a98a', 'es', 'Lanzamiento rotacional a pared inclinado', 'Lanzamiento de balón medicinal lateral con el torso inclinado hacia adelante. Objetivo: oblicuos y potencia rotacional. Cue: espalda plana. Error común: arquear la lumbar.'),
('ed693bac-b336-497a-ab0e-647139d5ab29', 'fc2bd73a-7c20-4a49-ae8c-4c0ab37fcb8e', 'en', 'Supinated Pull-ups (Chin-ups)', 'Grip with palms facing you, pull until chin clears the bar. Greater bicep emphasis. Cue: elbows down. Error: not completing the lower range of motion.'),
('dcd2822c-260a-486f-ac0e-35cc8a98abea', 'fc2bd73a-7c20-4a49-ae8c-4c0ab37fcb8e', 'es', 'Dominadas supinas (Chin-ups)', 'Agarre con palmas hacia ti, tira hasta pasar la barbilla. Mayor énfasis en bíceps. Cue: codos hacia abajo. Error: no completar el rango de movimiento inferior.'),
('2f7b3c76-63fa-490d-9872-01f3f71ac052', 'fc44b253-a3e0-41b1-b0a9-8667bfba61b2', 'en', 'Single Arm Kettlebell Suitcase Cyclist Squat', 'With heels elevated, perform a deep squat while holding a single kettlebell on one side of the body to challenge lateral stability.'),
('fbb1f541-e831-406a-ab3d-536e601ccae5', 'fc44b253-a3e0-41b1-b0a9-8667bfba61b2', 'es', 'Sentadilla Ciclista con Kettlebell a una mano (Maleta)', 'Con talones elevados, realiza una sentadilla profunda sosteniendo una sola pesa rusa en un lado del cuerpo para desafiar la estabilidad lateral.'),
('8d8fc066-7c33-4770-b1ab-cb10f3081068', 'fc4f0c5b-6933-4e48-b73b-d0977e2d22c8', 'en', 'Standing Incline Concentration Curl', 'Flex bicep leaned over without support. Cue: arm hangs vertical. Error: swinging shoulder.'),
('07280e05-fe85-4447-92ac-cba60fe81cfb', 'fc4f0c5b-6933-4e48-b73b-d0977e2d22c8', 'es', 'Curl concentrado pie inclinado', 'Flexiona bíceps inclinado sin apoyo. Cue: brazo cuelga vertical. Error: balancear hombro.'),
('31480513-6c8b-4a7d-a0e7-bedd08c5f254', 'fcaf1c4d-0348-4f1b-904c-f08530381e22', 'en', 'Kettlebell Goblet Squat', 'Hold the kettlebell by the horns in front of your chest and perform a deep squat while keeping the torso upright and heels down.'),
('1ec9ccfa-23b0-4ca4-9e34-c3b6488d453c', 'fcaf1c4d-0348-4f1b-904c-f08530381e22', 'es', 'Sentadilla Goblet con Kettlebell', 'Sujeta la Kettlebell por los cuernos frente al pecho y realiza una sentadilla profunda manteniendo el torso erguido y talones apoyados.'),
('b18e15ef-086e-4c7b-98d8-b10bb22c2891', 'fcb5f2a7-fd48-466b-b9eb-416f30c0adc5', 'en', 'Single Arm Kettlebell Bottoms Up Bench Press', 'Lying on your back, press a single upside-down kettlebell toward the ceiling, requiring maximum forearm and shoulder control.'),
('e61b5ff9-5122-4a0e-b037-6ee1a9d97228', 'fcb5f2a7-fd48-466b-b9eb-416f30c0adc5', 'es', 'Press de banca a una mano con Kettlebell Bottoms Up', 'Tumbado boca arriba, presiona una sola Kettlebell invertida hacia el techo, exigiendo máximo control del antebrazo y hombro.'),
('0929920f-1bf5-4338-b787-6c2292c02a89', 'fcb9b007-a2d9-4c42-82b8-03b2fe875a4c', 'en', 'Full Shrimp Squat', 'Unilateral squat holding the foot of the free leg behind with both hands. Requires great quadriceps flexibility and unilateral strength. Balance is extremely challenging. Progress from assisted versions.'),
('463771ab-dc57-45b8-aa10-d787990774d7', 'fcb9b007-a2d9-4c42-82b8-03b2fe875a4c', 'es', 'Sentadilla camarón completa', 'Sentadilla unilateral sujetando el pie de la pierna libre detrás con ambas manos. Requiere gran flexibilidad en cuádriceps y fuerza unilateral. El equilibrio es extremadamente desafiante. Progresa desde versiones asistidas.'),
('4752dcd4-709d-4cc1-8e7c-0dbc37bcfb19', 'fcba4e19-514a-4567-be2b-0446c2c0dbd4', 'en', 'Burpee', 'From standing, squat down, kick feet back to plank, do a push-up, jump feet in, and jump vertically.'),
('266b23c1-55a9-4501-a5b0-f49b537aed0b', 'fcba4e19-514a-4567-be2b-0446c2c0dbd4', 'es', 'Burpee', 'Desde de pie, agáchate, lanza pies atrás a plancha, haz una flexión, recoge pies y salta verticalmente.'),
('6cb71560-bf47-4248-b671-90f4526ac08e', 'fce243ef-b793-4a26-8ff5-221e7b186023', 'en', 'Cable Hamstring Curl', 'Lying face down or standing with an ankle strap on a low pulley, flex the knee bringing the heel toward the glute. Keep the hip extended and avoid arching the back. The cable provides uniform resistance throughout the movement.'),
('cebe0112-15c0-404a-b02c-639a76253492', 'fce243ef-b793-4a26-8ff5-221e7b186023', 'es', 'Flexión isquio cable', 'Tumbado boca abajo o de pie con tobillera en polea baja, flexiona la rodilla llevando el talón hacia el glúteo. Mantén la cadera extendida y evita arquear la espalda. El cable proporciona resistencia uniforme durante todo el movimiento.'),
('f75f76c2-c52c-4865-b19f-95c54d7fc621', 'fd21f275-b16f-424c-a144-65e8f6bcb15e', 'en', 'Neutral Grip Pull-ups', 'Pull up on parallel bars. Objective: back and biceps. Cue: squeeze shoulder blades. Error: partial range.'),
('2ac6e4c4-2ac5-4aa2-a746-fdfd4b423e40', 'fd21f275-b16f-424c-a144-65e8f6bcb15e', 'es', 'Dominadas agarre neutro', 'Sube en barras paralelas. Objetivo: espalda y bíceps. Cue: junta escápulas. Error: rango parcial.'),
('1e45e292-cbac-4817-8d27-ea50e0a41f5d', 'fd54fc0b-7123-4217-bda1-f4b0cc455261', 'en', 'Sprint Slam', 'Run toward the ball, pick it up and perform an explosive slam. Combines speed with power. Can be done over short distances or as part of a circuit. Maintain high intensity throughout.'),
('10a5fff8-0fcd-4abf-be60-43c47328aac7', 'fd54fc0b-7123-4217-bda1-f4b0cc455261', 'es', 'Sprint slam', 'Corre hacia el balón, recógelo y realiza un slam explosivo. Combina velocidad con potencia. Puede hacerse en distancias cortas o como parte de un circuito. Mantén la intensidad alta durante todo el ejercicio.'),
('aa619ec7-8134-4046-949f-379db85e1e61', 'fd5becb4-0d27-4848-9ead-986338b3046e', 'en', 'Single Arm Kettlebell Clean to Front Rack Contralateral Reverse Lunge', 'Perform a clean to the shoulder and execute a reverse lunge with the leg opposite to the kettlebell side.'),
('100a9e86-9956-4887-989a-a099f0f3fab4', 'fd5becb4-0d27-4848-9ead-986338b3046e', 'es', 'Clean a Zancada inversa contralateral Front Rack con Kettlebell', 'Realiza una cargada al hombro y ejecuta una zancada atras con la pierna del lado opuesto a la pesa rusa.'),
('15293b00-0cb2-49bd-905d-5ae8b2b38289', 'fd6b3a86-1b09-483c-8b47-24a109d71e4a', 'en', 'Double Kettlebell Outside Clean', 'Clean two kettlebells to the shoulders by swinging them outside your legs, keeping elbows tucked when catching the weight.'),
('2cd1ea7f-71bc-4288-bdf4-9e4aae8974e9', 'fd6b3a86-1b09-483c-8b47-24a109d71e4a', 'es', 'Outside Clean con Kettlebell doble', 'Carga dos Kettlebells hacia los hombros balanceandolas por fuera de las piernas, manteniendo los codos pegados al cuerpo al recibir el peso.'),
('6b2408d0-0c21-41ed-8062-b7817a43bba3', 'fd6bdc39-476a-4eab-b28a-d084290e9cc8', 'en', 'Single Arm Kettlebell Bottoms Up Front Rack Contralateral Bulgarian Split Squat', 'With one foot elevated, hold an upside-down kettlebell on the shoulder opposite to the front leg. Perform a split squat working on cross-stability.'),
('ea574c14-7d8f-437b-8dc0-aeb0b2c3576d', 'fd6bdc39-476a-4eab-b28a-d084290e9cc8', 'es', 'Sentadilla Búlgara contralateral Front Rack con Kettlebell Bottoms Up', 'Con un pie elevado, sostén una Kettlebell invertida en el hombro opuesto a la pierna delantera. Baja en sentadilla split trabajando la estabilidad cruzada.'),
('f052af38-5c89-4424-8778-a5a1902e67e3', 'fd80efb1-b201-4381-b410-1b65ad383188', 'en', 'Slider Kneeling Alternating Reach Push Up', 'Execute kneeling push-ups alternating which arm slides forward on each repetition to work core stability.'),
('e21a9473-0681-4a8e-afa5-93e27b812a75', 'fd80efb1-b201-4381-b410-1b65ad383188', 'es', 'Flexión con alcance de rodillas alterno sobre Slider', 'Ejecuta flexiones de rodillas alternando el brazo que se desliza hacia adelante en cada repeticion para trabajar la estabilidad del core.'),
('b15b7a3a-b79f-4d8e-9d2e-06bb659c2cf7', 'fdb9cf74-ed8b-470b-82ea-78649c614419', 'en', 'Barbell Hang Power Clean', 'Starting with the bar above the knees, perform an explosive hip extension to bring the bar to the shoulders in a half-squat position.'),
('674a5fe2-1ff2-4ece-b706-0b21b5e933bc', 'fdb9cf74-ed8b-470b-82ea-78649c614419', 'es', 'Hang Power Clean con barra', 'Iniciando con la barra sobre las rodillas, realiza una extension explosiva de cadera para llevar la barra a los hombros en posicion de media sentadilla.'),
('36408c01-1109-41d7-acf6-02d5a6019768', 'fdcc8382-bfd9-455d-a3d3-f420ee948ada', 'en', 'One-Arm Dumbbell Suitcase Deadlift', 'Perform a conventional deadlift holding a dumbbell on only one side. Prevent the torso from tilting laterally.'),
('37189271-f97d-4fba-aa19-532857c324ec', 'fdcc8382-bfd9-455d-a3d3-f420ee948ada', 'es', 'Peso muerto maleta con mancuerna a una mano', 'Realiza un peso muerto convencional sosteniendo una mancuerna solo en un lado. Evita que el torso se incline lateralmente.'),
('89475200-968c-4a95-b3d5-35dcf017d0a7', 'fde505f4-367f-44f0-a9f2-e4828cbf9fbc', 'en', 'Ring Tuck Front Lever', 'Hang from the rings and lift your body until parallel to the floor with knees tucked to the chest and arms completely straight.'),
('44d7266f-db5e-4b61-8b79-5f24b9b32836', 'fde505f4-367f-44f0-a9f2-e4828cbf9fbc', 'es', 'Tuck Front Lever en anillas', 'Cuelgate de las anillas y eleva el cuerpo hasta quedar paralelo al suelo con las rodillas encogidas hacia el pecho y los brazos completamente rectos.'),
('b52def53-c4b9-443e-a13f-ac26a08a5253', 'fdf15a5a-1d9a-4cf9-91bd-c7b44cbe865e', 'en', 'Suspension Lateral Knee Tuck', 'In a plank position with feet in TRX, bring both knees toward one elbow to work the obliques, return to the center and repeat on the other side.'),
('24865ee8-b8fc-48cf-9521-132ad7c75a7b', 'fdf15a5a-1d9a-4cf9-91bd-c7b44cbe865e', 'es', 'Knee Tuck lateral en TRX', 'En posición de plancha con pies en TRX, lleva ambas rodillas hacia un codo para trabajar los oblicuos, regresa al centro y repite hacia el otro lado.'),
('f7514e41-1d62-4ec3-a85b-f2cff537aefd', 'fe21e489-f5de-4fec-a4af-39fd55e3da72', 'en', 'Machine Dips', 'Assisted dips on a machine that reduces body weight. Ideal for beginners who cannot perform free dips. Adjust assistance progressively. Lean forward for more chest emphasis or stay vertical for triceps.'),
('a2ce69cb-ac45-4b16-8ec9-ea337a58708c', 'fe21e489-f5de-4fec-a4af-39fd55e3da72', 'es', 'Dips máquina', 'Fondos asistidos en máquina que reduce el peso corporal. Ideal para principiantes que no pueden hacer fondos libres. Ajusta la asistencia progresivamente. Inclínate hacia adelante para más énfasis en pecho o mantente vertical para tríceps.'),
('3ab30b1b-1eb9-49ba-b9ab-a6efe63b033b', 'fe5bf426-e843-4d5c-84c6-2774cca86457', 'en', 'Single Arm Kettlebell Bottoms Up Front Rack Ipsilateral Step Up', 'Step up onto the bench with the leg on the same side as the upside-down kettlebell held in rack, requiring maximum unilateral control.'),
('fdf18498-48d8-486b-a688-19cacd9a381d', 'fe5bf426-e843-4d5c-84c6-2774cca86457', 'es', 'Step Up ipsilateral Front Rack con Kettlebell a una mano Bottoms Up', 'Sube al banco con la pierna del mismo lado que la Kettlebell invertida sostenida en rack, exigiendo máximo control unilateral.'),
('1251ad77-7594-40e8-9c32-a277d12a4f43', 'fe879db0-8615-434f-8d9d-be049a7ffc5d', 'en', 'Seated Alternating Bicep Curl', 'Flex dumbbells alternating arms. Objective: biceps. Cue: rotate palm as you lift. Error: swinging.'),
('8a4a44b5-5e0a-4bc2-b48b-550f51f91aa9', 'fe879db0-8615-434f-8d9d-be049a7ffc5d', 'es', 'Curl bíceps sentado alterno', 'Flexiona mancuernas alternando brazos. Objetivo: bíceps. Cue: gira palma al subir. Error: balanceo.'),
('abb01934-48a3-4c52-9bca-05e743249b08', 'fe98f5c9-181b-4bf8-a196-af3ae2be2d2d', 'en', 'Concentration Bicep Curl', 'Seated, elbow supported on the inner thigh, flex the dumbbell. Maximum isolation. Total control. Do not use the body to swing.'),
('1b0ce238-4199-4cba-a4ad-c46e172dcf22', 'fe98f5c9-181b-4bf8-a196-af3ae2be2d2d', 'es', 'Curl de bíceps concentrado', 'Sentado, codo apoyado en el muslo interno, flexiona la mancuerna. Aislamiento máximo. Control total. No uses el cuerpo para balancear.'),
('032f1924-10c2-4e44-a356-a87b700767fb', 'fea0fa90-9b6d-415f-b7ad-c63bf9d1bacd', 'es', 'Tuck L-Sit en paralelas', 'Sostente sobre las barras paralelas con los brazos estirados y eleva las rodillas hacia el pecho manteniendo la posicion de forma isometrica.'),
('3b34ddf6-c348-4f7d-bcc6-6c28b3354af5', 'feb19895-c99f-47f4-98b4-d72854019689', 'en', 'Double Kettlebell Romanian Deadlift', 'With a weight in each hand, hinge the torso forward by pushing the hips back with knees slightly bent until you feel a stretch in the hamstrings.'),
('39d96ab8-4849-44d1-974b-e507c43d3d02', 'feb19895-c99f-47f4-98b4-d72854019689', 'es', 'Peso muerto rumano con Kettlebell doble', 'Con una pesa en cada mano, inclina el torso hacia adelante empujando la cadera atrás con las rodillas semi-flexionadas hasta sentir estiramiento en los isquios.'),
('9ff0d53e-9305-4abe-ab62-40c50e0d9956', 'feda3b21-a7ad-45c1-b65d-5dc8551e94ea', 'en', 'Chest-Supported Machine Row', 'Pull the handles with the chest on the support. Objective: mid-back. Cues: stretch the shoulder when lowering. Common error: rotating the torso.'),
('0edff1cd-7a29-4b0d-a915-498103ddb7b1', 'feda3b21-a7ad-45c1-b65d-5dc8551e94ea', 'es', 'Remo en máquina con apoyo de pecho', 'Tira de los agarres con el pecho en soporte. Objetivo: espalda media. Cues: estira hombro al bajar. Error común: rotar el torso.'),
('5f1ac13a-8f4b-4cb3-8a56-3b37a50eb800', 'ff135d58-59dc-4ba4-85ed-e3af7255add8', 'en', 'Dumbbell Skullcrushers', 'Lower dumbbells to ears while lying down. Objective: triceps. Cue: elbows to ceiling. Error: moving shoulder.'),
('01426dc5-91d0-43cb-8c3d-9dfa4564b4c2', 'ff135d58-59dc-4ba4-85ed-e3af7255add8', 'es', 'Skullcrushers mancuernas', 'Baja mancuernas a orejas tumbado. Objetivo: tríceps. Cue: codos al techo. Error: mover hombro.'),
('9637ba86-f32c-40db-9eb6-887f8a1887e9', 'ff39db0a-6b4b-41a7-93bd-a9bce3387aa7', 'en', 'Kettlebell Press', 'From the rack position, press the kettlebell overhead. The unique design of the kettlebell challenges stabilization. Keep the core engaged and avoid arching the back. Can be done strict or with leg drive.'),
('571c301c-f172-475c-bd8b-62b25477ac14', 'ff39db0a-6b4b-41a7-93bd-a9bce3387aa7', 'es', 'Press kettlebell', 'Desde la posición de rack, presiona la kettlebell sobre la cabeza. El diseño único de la kettlebell desafía la estabilización. Mantén el core activado y evita arquear la espalda. Puede hacerse estricto o con impulso de piernas.'),
('44201281-3d62-4c36-9409-954aeb0d4b86', 'ff4ab808-e066-4777-ba72-03e2d6cab229', 'en', 'Bodyweight Hand Assisted Foot Elevated Knee Over Toe Split Squat', 'Split squat with elevated foot assisted by hands, allowing the front knee to pass the toes to gain mobility.'),
('43790d66-0038-4d7d-80cf-567dcf65b4c4', 'ff4ab808-e066-4777-ba72-03e2d6cab229', 'es', 'Sentadilla Búlgara asistida rodilla sobre punta del pie', 'Sentadilla split con pie elevado ayudado por las manos, permitiendo que la rodilla delantera sobrepase los dedos para ganar movilidad.'),
('565851e7-ba2e-4436-9c0d-d1cf44a0892d', 'ff615b5d-fac5-478f-8f73-037102efd52c', 'en', 'Barbell Reverse Grip Bench Press', 'Lie on the bench and hold the bar with palms facing your face. Press upward focusing on the upper pectoral.'),
('42db2e3e-5afc-43d8-ba28-65ad06af1932', 'ff615b5d-fac5-478f-8f73-037102efd52c', 'es', 'Press de banca con agarre inverso y barra', 'Acuéstate en el banco y sujeta la barra con las palmas mirando hacia tu cara. Presiona hacia arriba enfocando el pectoral superior.'),
('2fdf25cf-cd49-4d3d-84b8-1829d2390b2c', 'ffdc9db6-4471-4c1b-b540-e606a2267c4c', 'en', 'Band Bench Press (Accommodated Resistance)', 'Perform bench press with elastic bands attached to the bar to increase tension on the way up. Objective: lockout strength. Cues: stable bar and firm core. Common error: letting the band pull the bar laterally.'),
('fa546c0f-f978-4e08-b95b-caf13a2ae5e6', 'ffdc9db6-4471-4c1b-b540-e606a2267c4c', 'es', 'Press de banca con banda (Resistencia acomodada)', 'Realiza press de banca con bandas elásticas sujetas a la barra para aumentar la tensión al subir. Objetivo: fuerza de bloqueo. Cues: barra estable y core firme. Error común: dejar que la banda tire de la barra lateralmente.'),
('c9282893-25e4-4888-8565-8b0b1be52ac6', 'ffe57f8a-9530-4e24-9dc5-668edb8f54a3', 'en', 'Single Arm Kettlebell Single Leg Standing Bent Knee Around The World', 'Standing on a single leg, pass the kettlebell around your waist from one hand to the other while maintaining body balance.'),
('e12bef08-cbf1-4398-9cc6-1f13f59dad6c', 'ffe57f8a-9530-4e24-9dc5-668edb8f54a3', 'es', 'Alrededor del mundo a una pierna con Kettlebell', 'De pie sobre una sola pierna, pasa la Kettlebell alrededor de tu cintura de una mano a otra manteniendo el equilibrio del cuerpo.'),
('b347c907-e77e-491e-8351-12c876d70640', 'ffe7ffcf-6287-40fe-bc95-a5528de8f074', 'es', 'Pike Pushups frente manos', 'Flexión en V. Cue: baja frente ante manos. Error: codos muy abiertos.'),
('43402ffc-5625-4aa0-af39-85547c5bbb6f', 'fff3e543-33c4-4d4e-85be-f03bb5c608fb', 'en', 'Double Kettlebell Bottoms Up Seesaw Overhead Press', 'Alternate the press of two upside-down kettlebells overhead in a fluid motion, requiring absolute stability control.'),
('47a2f389-eb36-4db6-9140-10df7f72f698', 'fff3e543-33c4-4d4e-85be-f03bb5c608fb', 'es', 'Press aérea con doble pesa rusa de abajo hacia arriba y balancín', 'Alterna el press de dos Kettlebells invertidas sobre la cabeza en un movimiento fluido, requiriendo un control absoluto de estabilidad.'),
('41cc87f7-a21f-4a66-92d7-cc8eb58b4615', 'fffc4caf-dc49-4617-b611-13fd90c479d9', 'en', 'Single Arm Barbell Kneeling Rollout', 'Kneeling, hold the barbell with a single hand and roll it forward extending the core, then return to the starting position.');
INSERT INTO public."exercise_translations" ("id", "exercise_id", "language_code", "name", "description") VALUES
('380273a1-1bce-473c-bf96-06c11ffdf8fb', 'fffc4caf-dc49-4617-b611-13fd90c479d9', 'es', 'Rollout de rodillas con barra a una mano', 'De rodillas, sujeta la barra con una sola mano y deslizala hacia adelante extendiendo el core, regresando luego a la posicion inicial.'),
('198e3f53-9fd7-4218-82cd-6accf6bc9ee3', 'ffff1c4e-19bf-4089-92d6-bf2a81bb7a87', 'en', 'One-Arm High Cable Bicep Curl', 'Standing sideways to a high pulley. With arm extended laterally, flex the elbow to bring the hand toward the ear, keeping the elbow high.'),
('1060d53b-5c66-4465-ab6c-ab532fda7eed', 'ffff1c4e-19bf-4089-92d6-bf2a81bb7a87', 'es', 'Curl de bíceps alto con cable a una mano', 'De pie de lado a una polea alta. Con el brazo extendido lateralmente, flexiona el codo para llevar la mano hacia la oreja, manteniendo el codo alto.');
